window.__HRC_SHARD({"shard":"ite-kasai-drc-2017","builtAt":"2026-07-19T18:52:42+00:00","documents":[{"rec_id":"recTkSTOeTuqoSc8t","doc_id":"ITE Kasai DRC (2017) - CRP - 29.06.2018","symbol":"A/HRC/38/CRP.1","title":"Rapport détaillé de l'Equipe d'experts internationaux sur la situation au Kasaï","type":"CRP","date":"2018-06-29","year":2018,"bodies":["ITE Kasai DRC (2017)"],"paragraphCount":429,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/3. Annexes, CRPs and other materials/TOE DRC - 29-06-2018 - CRP - A_HRC_38_CRP.1 - FR.md","extractor":"pdftotext -layout"},{"rec_id":"recXXveoh2wisZaA5","doc_id":"ITE Kasai DRC (2017) - Official report - 03.07.2018","symbol":"A/HRC/38/31","title":"Report of the Team of international experts on the situation in the Kasai regions","type":"Official report","date":"2018-07-03","year":2018,"bodies":["ITE Kasai DRC (2017)"],"paragraphCount":113,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - 03-07-2018 - Official report - A_HRC_38_31 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"rectHw5BCJkNOy2Tl","doc_id":"ITE Kasai DRC (2017) - Official report - 07.05.2019","symbol":"A/HRC/41/31","title":"Report of the Team of International Experts on the situation in Kasai","type":"Official report","date":"2019-05-07","year":2019,"bodies":["ITE Kasai DRC (2017)"],"paragraphCount":82,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - 07-05-2019 - Official report - A_HRC_41_31 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recOMA5m0PDrmkf47","doc_id":"ITE Kasai DRC (2017) - Official report - 27.08.2020","symbol":"A/HRC/45/50","title":"Report of the team of international experts on the situation in Kasai","type":"Official report","date":"2020-08-27","year":2020,"bodies":["ITE Kasai DRC (2017)"],"paragraphCount":85,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - 27-08-2020 - Official report - A_HRC_45_50 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"reca1DGtVsz2vg0VY","doc_id":"ITE Kasai DRC (2017) - Official report - 20.08.2021","symbol":"A/HRC/48/82","title":"Report of the team of international experts on the situation in Kasai","type":"Official report","date":"2021-08-20","year":2021,"bodies":["ITE Kasai DRC (2017)"],"paragraphCount":100,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC - 20-08-2021 - Official report - A_HRC_48_82 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recenyyVjQEwTjwtP","doc_id":"ITE Kasai DRC (2017) - Official report - 18.08.2022","symbol":"A/HRC/51/60","title":"Report of the team of international experts on the Democratic Republic of the Congo","type":"Official report","date":"2022-08-18","year":2022,"bodies":["ITE Kasai DRC (2017)"],"paragraphCount":109,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - 18-08-2022 - Official document - A_HRC_51_60 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recFcelLCcNFThdpq","doc_id":"ITE Kasai DRC (2017) - Official report - 10.08.2023","symbol":"A/HRC/54/76","title":"Assistance technique et renforcement des capacités dans le domaine des droits de l’homme en République démocratique du Congo — Rapport de l’Équipe d’experts internationaux en République démocratique du Congo","type":"Official report","date":"2023-08-10","year":2023,"bodies":["ITE Kasai DRC (2017)"],"paragraphCount":141,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - Official document - A_HRC_54_76 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recRKoUWhEAMnMLuM","doc_id":"ITE Kasai DRC (2017) - Official report - 16.08.2024","symbol":"A/HRC/57/81","title":"Report of the team of international experts on the Democratic Republic of the Congo (final report)","type":"Official report","date":"2024-08-16","year":2024,"bodies":["ITE Kasai DRC (2017)"],"paragraphCount":133,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - 16-08-2024 - Official report - A_HRC_57_81 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"reczKpHBpllGVhs0C","doc_id":"ITE Kasai DRC (2017) - Official report - 20.08.2025","symbol":"A/HRC/60/83","title":"Technical assistance and capacity-building in the field of human rights in the Democratic Republic of the Congo - final report of the Team of International Experts","type":"Official report","date":"2025-08-20","year":2025,"bodies":["ITE Kasai DRC (2017)"],"paragraphCount":149,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/TOE DRC (2017) - 20-08-2025 - Official report - A_HRC_60_83 - EN.md","extractor":"pdftotext -layout"}],"paragraphs":[{"id":"a-hrc-38-crp-1-u0000","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":null,"seq":0,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend dans les provinces du Kasaï Central, Kasaï","text":"Acronymes\nANR          Agence nationale de renseignements\nBCNUDH       Bureau conjoint des Nations Unies aux droits de l’homme\nCENCO        Conférence épiscopale nationale du Congo\nCENI         Commission électorale nationale indépendante\nCICR         Comité international de la Croix-Rouge\nCNDH         Commission nationale des droits de l'homme\nCPI          Cour pénale internationale\nDGM          Direction générale de migration\nEEI          Equipe d’experts internationaux sur la situation au Kasaï\nEFO          Ecole de formation des officiers\nFARDC        Forces armées de la République démocratique du Congo\nFIDH         Fédération internationale des ligues des droits de l'homme\nHCDH         Haut-Commissariat des Nations Unies aux droits de l’homme\nIRRI         International Refugee Rights Initiative\nLNI          Légion nationale d’intervention\nMONUSCO      Mission de l'Organisation des Nations Unies pour la stabilisation en\nRépublique démocratique du Congo\nONU          Organisation des Nations Unies\nONU Femmes   Entité des Nations Unies pour l'égalité des sexes et l'autonomisation\ndes femmes\nPAM          Programme alimentaire mondial\nPNC          Police nationale congolaise\nPPRD         Parti du peuple pour la reconstruction et la démocratie\nRFI          Radio France internationale\nRDC          République démocratique du Congo\nTPIY         Tribunal pénal international pour l'ex-Yougoslavie\nUDPS         Union pour la démocratie et le progrès social\nUNICEF       Fonds des Nations Unies pour l'enfance","unnumbered":true},{"id":"a-hrc-38-crp-1-p0001","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"1","seq":1,"section":"I. Introduction","text":"L’Equipe d’experts internationaux sur la situation au Kasaï (EEI) a été créée pour une\npériode d’un an par la résolution 35/33 du Conseil des droits de l’homme adoptée à\nl’unanimité le 23 juin 20171."},{"id":"a-hrc-38-crp-1-p0002","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"2","seq":2,"section":"I. Introduction","text":"Le 26 juillet 2017, le Haut-Commissaire des Nations Unies aux droits de l’homme a\nnommé Bacre Waly Ndiaye (Sénégal), Fatimata M’Baye (Mauritanie) et Luc Côté\n(Canada) comme Experts internationaux. Bacre Waly Ndiaye a été désigné par le Haut-\nCommissaire des Nations Unies aux droits de l’homme comme Président de l’EEI."},{"id":"a-hrc-38-crp-1-p0003","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"3","seq":3,"section":"I. Introduction","text":"Les Experts internationaux ont conduit trois missions en République démocratique du\nCongo (RDC) et en particulier au Kasaï. Ils ont décidé de ne pas se rendre en Angola\ncompte tenu de la mission que le Haut-Commissariat des Nations Unies aux droits de\nl’homme (HCDH) y a mené en juin 2017. Au cours de leurs trois visites en RDC d’une\ndouzaine de jours chacune, les Experts internationaux ont rencontré des victimes et des\ntémoins des violences au Kasaï et se sont également entretenus avec plusieurs ministres du\nGouvernement congolais, des gouverneurs de province, des responsables des forces\narmées, y compris de la justice militaire, de la police, des services de renseignement, ainsi\nqu’avec des membres de la communauté internationale et de la société civile."},{"id":"a-hrc-38-crp-1-p0004","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"4","seq":4,"section":"I. Introduction","text":"Les Experts internationaux ont été assistés par un secrétariat établi et supporté par le\nHCDH. Ce secrétariat, composé de 14 professionnels du HCDH, d’une professionnelle\nd’ONU Femmes, spécialiste des questions de genre, et de trois assistants linguistiques, était\nbasé à Kananga dans la province du Kasaï Central."},{"id":"a-hrc-38-crp-1-p0005","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"5","seq":5,"section":"I. Introduction","text":"L’EEI a délivré une présentation orale au Conseil des droits de l’homme en mars\n2018. Le présent rapport contient les conclusions finales et une présentation détaillée des\nenquêtes menées par l’EEI. Les informations contenues dans ce rapport doivent être lues en\nconjonction avec le Rapport de l’Equipe d’experts internationaux sur la situation au Kasaï\n(A/HRC/38/31)."},{"id":"a-hrc-38-crp-1-p0006","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"6","seq":6,"section":"II. Mandat et interprétation du mandat","text":"Le paragraphe 10 de la résolution 35/33 du Conseil des droits de l’homme « [p]rie le\nHaut-Commissaire des Nations Unies aux droits de l’homme de dépêcher une équipe\nd’experts internationaux […] afin de réunir et de conserver des informations, d’établir les\nfaits et les circonstances […] concernant des violations présumées des droits de l’homme et\ndes violations du droit international humanitaire dans les régions du Kasaï, de\ncommuniquer aux autorités judiciaires de la [RDC] les conclusions de cette enquête afin\nd’établir la vérité et de faire en sorte que les auteurs des crimes odieux soient tous traduits\ndevant les autorités judiciaires de la [RDC] »."},{"id":"a-hrc-38-crp-1-p0007","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"7","seq":7,"section":"II. Mandat et interprétation du mandat","text":"L’EEI observe que le paragraphe 10 de la résolution 35/33 lui demande « d’établir les\nfaits et les circonstances conformément aux normes internationales et à la pratique ». L’EEI\nconsidère que cette disposition signifie qu’elle se doit, comme toutes les commissions\nd’enquêtes et autres mécanismes d’établissement des faits créés par le Conseil des droits de\nl’homme, d’agir de manière indépendante dans la mise en œuvre de son mandat. L’EEI a\ndonc œuvré dans le strict respect du principe d’indépendance vis-à-vis de tout Etat, de toute\npartie impliquée dans la crise, ainsi que du HCDH et des autres organes des Nations Unies,\ntelle que la Mission de l’Organisation des Nations Unies pour la stabilisation en République\ndémocratique du Congo (MONUSCO)."},{"id":"a-hrc-38-crp-1-p0008","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"8","seq":8,"section":"II. Mandat et interprétation du mandat","text":"L’EEI considère que son mandat consiste à établir les faits et circonstances des\nviolations des droits de l’homme et du droit international humanitaire commises depuis\n2016 au Kasaï qui sont susceptibles de constituer des crimes en droit international pénal.\nEu égard au large mandat qui lui a été confié et au temps relativement court pour sa mise\nen œuvre, l’EEI a décidé de concentrer en priorité ses enquêtes sur les actes de violence les\nplus graves – tels que les atteintes au droit à la vie et à l’intégrité physique, notamment les\nviolences sexuelles et basées sur le genre, ou encore les violences faites aux enfants – en\nportant une attention particulière à ceux susceptibles de constituer des crimes\ninternationaux."},{"id":"a-hrc-38-crp-1-p0009","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"9","seq":9,"section":"II. Mandat et interprétation du mandat","text":"L’enquête sur le meurtre des deux membres du Groupe d’experts sur la République\ndémocratique du Congo créé en application de la résolution 1533 (2004) du Conseil de\nsécurité, la suédo-chilienne Zaida Catalán et l’américain Michael Sharp, ainsi que la\ndisparition de leurs quatre accompagnateurs congolais en mars 2017, relève de la\ncompétence de l’EEI. Toutefois, la mise en place postérieure par le Secrétaire général des\nNations Unies d’un mécanisme de suivi chargé d’assister l’enquête criminelle ouverte au\nniveau national a incité l’EEI à ne pas utiliser de ressources substantielles à la\ndocumentation de cet incident et à se focaliser sur les autres aspects de la crise."},{"id":"a-hrc-38-crp-1-p0010","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"10","seq":10,"section":"II. Mandat et interprétation du mandat","text":"L’EEI considère que l’expression « les régions du Kasaï » utilisée dans la résolution\npour définir sa compétence provinciale englobe les cinq provinces suivantes issues du\nredécoupage administratif mis en œuvre en juillet 2015 : Kasaï, Kasaï Central, Kasaï\nOriental, Lomami, et Sankuru2. Les enquêtes se sont principalement concentrées sur les\nprovinces du Kasaï et du Kasaï Central, et dans une moindre mesure sur les provinces du\nKasaï Oriental et de Lomami3."},{"id":"a-hrc-38-crp-1-p0011","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"11","seq":11,"section":"II. Mandat et interprétation du mandat","text":"Le paragraphe 10 de la résolution 35/33 ne précise pas les contours temporels de la\ncompétence du mandat. L’EEI considère qu’elle est compétente pour documenter les actes\nde violence commis au Kasaï depuis 2016 et jusqu’à ce jour. Pour être en mesure de\nfinaliser son rapport, l’EEI a clôturé ses enquêtes le 20 mai 2018."},{"id":"a-hrc-38-crp-1-p0012","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"12","seq":12,"section":"II. Mandat et interprétation du mandat","text":"L’EEI est d’avis qu’en mentionnant dans ses paragraphes 2 et 10 le fait que tous les\nauteurs et responsables des violations et crimes commis au Kasaï se doivent d’être traduits\nen justice, la résolution 35/33 lui a confié le mandat d’examiner le rôle de tous les acteurs\nimpliqués dans la vague de violence qui touche le Kasaï depuis 2016."},{"id":"a-hrc-38-crp-1-p0013","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"13","seq":13,"section":"II. Mandat et interprétation du mandat","text":"En vertu du paragraphe 10 de la résolution 35/33, l’EEI doit communiquer ses\nconclusions aux autorités judiciaires de la RDC afin de faire en sorte que les auteurs de\ncrimes soient traduits en justice. Ce rapport ainsi que le Rapport de l’Equipe d’experts\ninternationaux sur la situation au Kasaï (A/HRC/38/31) ont été transmis aux autorités\njudiciaires de la RDC."},{"id":"a-hrc-38-crp-1-p0014","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"14","seq":14,"section":"II. Mandat et interprétation du mandat","text":"Pour préserver le droit à présomption d’innocence, l’EEI n’a pas publié la liste des\nauteurs présumés qu’elle a pu identifier grâce à son travail d’enquête. Cette liste\nconfidentielle a été remise au Haut-Commissaire des Nations Unies aux droits de l’homme,\nqui en est le gardien.\n2\nLoi organique n° 15/006 du 25 mars 2015 portant fixation des limites des provinces et celles de la ville de Kinshasa mettant\nen œuvre la Constitution de la République démocratique du Congo du 18 février 2006 telle que modifiée par la Loi n° 11/002 du 20\njanvier 2011."},{"id":"a-hrc-38-crp-1-p0015","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"15","seq":15,"section":"III. Coopération avec l’EEI","text":"L’EEI remercie la RDC pour sa coopération et pour lui avoir facilité ses visites et\nl’accès au pays. Elle étend ses remerciements à la MONUSCO pour son soutien, et aux\norganes et fonds des Nations Unies, en particulier le HCDH et ONU Femmes, ainsi qu’aux\norganisations gouvernementales et non-gouvernementales pour leur coopération. Elle\nremercie surtout les victimes et témoins qui ont accepté de partager leur expérience avec\nelle."},{"id":"a-hrc-38-crp-1-p0016","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"16","seq":16,"section":"A. Principes généraux","text":"L’EEI a collecté des informations auprès de nombreuses sources. L’EEI a d’abord\ncollecté une partie importante de la documentation existante sur la vague de violence au\nKasaï depuis 2016. Cette documentation, qualifiée de source secondaire parce qu’elle n’a\npas été directement recueillie par l’EEI, comprend des rapports et documents de la\nMONUSCO ainsi que d’organes, fonds et programmes des Nations Unies, d’organisations\ngouvernementales et non-gouvernementales, d’instituts de recherche, et de toute autre\nentité que l’EEI a jugé crédible et fiable dans sa méthodologie et sa documentation de la\nsituation des droits de l’homme au Kasaï."},{"id":"a-hrc-38-crp-1-p0017","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"17","seq":17,"section":"A. Principes généraux","text":"L’EEI a également directement recueilli des informations auprès des sources\nprimaires suivantes :\n•    des témoignages de victimes d’actes de violence, de témoins oculaires, de membres de\nla famille ou des connaissances proches des victimes ayant des informations directes\nsur les incidents en question ;\n•    des témoignages d’autres personnes ayant des informations directes et fiables sur des\nactes de violence, ou sur les circonstances dans lesquelles ils ont été commis ou\ncommandités ;\n•    des images satellites, des photos, vidéos et documents audio provenant de sources\nfiables et que l’EEI a été en mesure d’authentifier ;\n•    des documents qui appuient les témoignages directs, tels que des documents médicaux\nattestant de blessures des victimes, des correspondances, des copies de jugements ou\nd’autres documents découlant de procédures judiciaires ;\n•    des déclarations d’auteurs présumés d’actes de violence ;\n•    des informations publiques et officielles, telles que les lois, règlements, directives,\ndéclarations, ainsi que tout document officiel pertinent du Gouvernement de la RDC."},{"id":"a-hrc-38-crp-1-p0018","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"18","seq":18,"section":"A. Principes généraux","text":"L’EEI, par le biais de son secrétariat basé à Kananga, a conduit 524 entretiens avec\ndes victimes, des témoins, des auteurs présumés4 et d’autres sources au cours de missions\ndans les provinces du Kasaï, Kasaï Central, Kasaï Oriental et de Lomami ainsi que dans les\nvilles de Kinshasa et Kikwit."},{"id":"a-hrc-38-crp-1-p0019","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"19","seq":19,"section":"A. Principes généraux","text":"L’EEI a mis en place des procédures conformes aux meilleures pratiques en matière\nde protection des témoins. Pour chaque entretien, la sécurité du témoin a été évaluée afin de\nprendre les mesures nécessaires pour éviter de faire courir tout risque à la personne\nrencontrée. Par exemple, les lieux d’entretien ont été sélectionnés de façon à protéger la vie\nprivée et les entretiens conduits de manière individuelle et en toute confidentialité. Dans\ncertains cas, l’EEI a décidé du déplacement de témoins vers des endroits plus sécurisés afin\nde les interroger. Toutefois, la capacité limitée d’offrir une protection appropriée a parfois\nconduit l’EEI à devoir renoncer à recueillir le témoignage de certaines personnes afin de ne\npas les exposer au danger. Dans un souci de protection des victimes et des témoins avec\nlesquels elle s’est entretenue, l’EEI a décidé de ne pas mentionner dans le rapport leurs\nnoms et les détails qui permettraient leur identification."},{"id":"a-hrc-38-crp-1-p0020","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"20","seq":20,"section":"A. Principes généraux","text":"L’EEI a rencontré un certain nombre de difficultés à la conduite efficace de ses\nenquêtes. Elle a relevé des réticences de la part de certains témoins à parler d’actes de\nviolence commis par des forces de défense et de sécurité. Par ailleurs, l’EEI a été\nconfrontée quotidiennement à des difficultés d’accès aux témoins dues à la grande\nsuperficie du territoire à couvrir, au mauvais état des routes et à des considérations\nsécuritaires. L’EEI a également rencontré des retards dans le déploiement des membres du\nsecrétariat sur le terrain."},{"id":"a-hrc-38-crp-1-p0021","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"21","seq":21,"section":"A. Principes généraux","text":"Devant l’ampleur des violences au Kasaï, l’EEI a adopté une stratégie visant à ne\ndocumenter que des incidents graves et emblématiques des différentes phases temporelles\net géographiques de la crise. Cette stratégie a pris en compte des critères tels que la nature\ndes violences, le nombre de victimes, la manière dont les violences ont été commises ainsi\nque leur impact. L’objectif poursuivi par cette stratégie de sélection a été de présenter une\nliste d’incidents représentatifs de la crise qui touche le Kasaï depuis 2016 afin d’offrir une\nvision la plus objective et compréhensive possible. Le présent rapport ne reflète donc\nqu’une petite partie des actes et des crimes commis."},{"id":"a-hrc-38-crp-1-p0022","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"22","seq":22,"section":"A. Principes généraux","text":"Les conclusions de l’EEI démontrent que de très nombreuses personnes ont perdu la\nvie en raison des actes de violence. Il serait illusoire de vouloir chiffrer de manière\ndéfinitive le nombre de victimes de ces violences depuis 2016. Comprendre et expliquer,\nplutôt que chiffrer, a semblé être le moyen le plus efficace de prévenir la récurrence des\nviolences et de s’assurer que la question de l’impunité pour les auteurs des violations et des\ncrimes soit adressée."},{"id":"a-hrc-38-crp-1-p0023","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"23","seq":23,"section":"A. Principes généraux","text":"Les enquêtes menées par l’EEI ont confirmé l’existence d’un grand nombre de fosses\ncommunes au Kasaï. Dans la mesure du possible, celles-ci ont été localisées afin de\nfaciliter de futures procédures judiciaires. Toutefois, l’EEI considère qu’elle n’a ni le\nmandat ni les ressources techniques pour conduire des exhumations et/ou des examens de\nmédecine légale. L’EEI a donc fait le choix de concentrer son travail d’enquête sur le\nrecueil de témoignages."},{"id":"a-hrc-38-crp-1-p0024","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"24","seq":24,"section":"B. Méthodologie de documentation des violences sexuelles et basées sur le","text":"L’EEI a intégré une perspective sexospécifique dans l’ensemble de son travail et a\nporté une attention particulière aux allégations de violences sexuelles et basées sur le genre,\nnotamment à l’égard des femmes et des filles. Elle a également pris en considération la\ndimension genre dans son analyse des autres crimes et violations commis ainsi que sur les\neffets que l’ensemble de ceux-ci avaient en fonction des victimes et de leur sexe. Elle a\naussi tenu compte des problèmes spécifiques qui pouvaient survenir dans les enquêtes sur\ndes allégations de violences sexuelles visant aussi bien les femmes et filles que les hommes\net garçons. A cette fin, l’EEI s’est adjoint les services d’une spécialiste des questions de\ngenre / enquêtrice sur les violences sexuelles et basées sur le genre fournie par ONU\nFemmes, l’entité des Nations Unies consacrée à l’égalité des sexes et à l’autonomisation\ndes femmes."},{"id":"a-hrc-38-crp-1-p0025","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"25","seq":25,"section":"B. Méthodologie de documentation des violences sexuelles et basées sur le","text":"L’EEI a apporté une grande attention aux violences sexuelles et basées sur le genre\nqui demeurent un élément central des évènements qui se déroulent dans les provinces du\nKasaï depuis 2016 et a adopté une méthodologie de travail et de documentation adaptée.\nElle s’est également informée sur les traditions et coutumes qui tiennent une place\nimportante dans la région du Kasaï et leur incidence sur la perception du genre dans la\nsociété kasaïenne afin de mieux appréhender la signification de certains comportements, les\nviolations et crimes observés et leurs conséquences sur les personnes et les communautés.\nCela a notamment été rendu possible grâce à des entretiens avec des représentantes\nd’organisations et de réseaux de femmes, des personnes travaillant pour des organisations\nde support médical et psychologique aux victimes de violences sexuelles et des\nreprésentants d’organisations sur le terrain."},{"id":"a-hrc-38-crp-1-p0026","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"26","seq":26,"section":"B. Méthodologie de documentation des violences sexuelles et basées sur le","text":"Les informations recueillies laissent apparaitre que les femmes, avec les enfants, sont\nles principales victimes directes et indirectes des violences qui se sont produites au Kasaï\ndepuis 2016. L’EEI a eu recours à un réseau d’intermédiaires, y compris des réseaux de\nfemmes, afin d’avoir accès aux victimes et/ou témoins de violences sexuelles et de pouvoir\nles rencontrer de manière confidentielle. Elle a également travaillé avec des organisations\nspécialisées dans la prise en charge des victimes de violences sexuelles afin de s’assurer\ndans la mesure du possible d’une prise en charge notamment médicale et psychologique\ndes survivantes. Les arrangements de sécurité adoptés ont pris en compte des\nconsidérations liées au genre, à l’âge et aux besoins des victimes, notamment des\nsurvivantes et survivants de violences sexuelles, afin que les lieux d’entretiens offrent\ntoutes les conditions propices de confort et sécurité pour ces personnes. De même, les lieux\ndes entretiens ont été choisis afin de répondre à des soucis de confidentialité et de sécurité\net les enquêteurs ont utilisé des méthodes prenant en compte l’âge, des considérations de\ngenre et la fragilité des personnes rencontrées. L’EEI a également eu recours aux services\nd’interprètes hommes et femmes ayant de l’expérience dans l’interprétariat auprès de\nsurvivants de violences sexuelles et basées sur le genre et de victimes fragiles. Un glossaire\nde termes en français, anglais, swahili, lingala et tshiluba ayant trait aux violences sexuelles\na été constitué et mis à disposition des interprètes."},{"id":"a-hrc-38-crp-1-p0027","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"27","seq":27,"section":"C. Méthodologie de documentation des violences et crimes commis contre","text":"L’EEI a également apporté une attention particulière aux violences commises contre\nles enfants et mis en place une méthodologie de documentation adaptée aux besoins\nspécifiques des mineurs."},{"id":"a-hrc-38-crp-1-p0028","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"28","seq":28,"section":"C. Méthodologie de documentation des violences et crimes commis contre","text":"L’EEI a fait le choix de documenter en particulier les actes de violence les plus graves\ncommis contre les garçons et filles mineures au Kasaï y compris les six violations et crimes\nles plus graves faites aux enfants au sens des résolutions 1261 et suivantes du Conseil de\nSécurité : le meurtre et les mutilations d’enfants, le recrutement et l’utilisation d’enfants,\nles violences sexuelles faites aux enfants, l’enlèvement d’enfants, et dans une moindre\nmesure, les attaques contre les écoles et les hôpitaux et le déni d’accès à l’aide\nhumanitaire5. Il est important de souligner que les enfants ont également été des\ninstruments de la violence, contraints de commettre des violations et atteintes aux droits de\nl’homme et des crimes, notamment des meurtres."},{"id":"a-hrc-38-crp-1-p0029","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"29","seq":29,"section":"C. Méthodologie de documentation des violences et crimes commis contre","text":"Concernant la stratégie de collecte d’informations, l’EEI a d’abord conduit une\nanalyse des sources secondaires disponibles portant sur la situation des filles et garçons\naffectés par les violences commises dans les provinces du Kasaï depuis 2016. Pour\ndéterminer les sources considérées comme crédibles et fiables, l’EEI a porté une attention\nparticulière à la démonstration par ces sources d’une connaissance de la situation des droits\nde l’enfant au Kasaï. Cela a permis une meilleure compréhension du contexte socio-culturel\net notamment, de la place de l’enfant dans les communautés locales."},{"id":"a-hrc-38-crp-1-p0030","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"30","seq":30,"section":"C. Méthodologie de documentation des violences et crimes commis contre","text":"Priorité a été donnée à la conduite d’entretiens avec des enfants qu’ils soient témoins\ndirects, victimes et/ou auteurs de violences. L’objectif était de mettre en lumière leur\nexpérience en leur donnant la parole. L’EEI a privilégié aller à la rencontre des enfants, là\noù ils se trouvaient afin qu’ils n’aient pas à parcourir de longues distances. Les principales\nconsidérations prises en compte ont été la sécurité et les garanties de confidentialité pour\ntoutes les personnes qui ont été en contact avec l’EEI, les enfants en particulier ; la finalité\nétant de les protéger contre d’éventuelles représailles, la stigmatisation et le rejet. Par\nailleurs, l’EEI s’est montrée à l’écoute des craintes exprimées par les enfants et par leurs\nreprésentants légaux. Dans la décision d’engager ou non un entretien avec un enfant, l’EEI\na mis au premier plan sa protection et son bien-être en identifiant, par exemple, au\npréalable l’existence de structures à même d’apporter une assistance aux besoins de base de\nl’enfant et de sa communauté."},{"id":"a-hrc-38-crp-1-p0031","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"31","seq":31,"section":"C. Méthodologie de documentation des violences et crimes commis contre","text":"La gravité des violences vécues, des traumatismes physiques et psychiques\noccasionnés et l’extrême précarité de ces enfants ont imposé l’adoption de techniques\nd’entretien adaptées. L’EEI a privilégié l’utilisation des techniques d’entretiens cognitifs\npour stimuler la mémoire des victimes sans les influencer. L’enfant est ainsi par exemple\namené à raconter tout ce dont il se souvient de l’incident, puis à se concentrer sur ce qu’il a\nvu, ce qu’il a ressenti, ce qu’il a entendu et sur les circonstances de l’incident. Il a\négalement été important d’adapter l’approche à l’âge des enfants rencontrés, à leur sexe et\naux différentes violences qu’ils ont commises, subies ou dont ils ont été les témoins."},{"id":"a-hrc-38-crp-1-p0032","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"32","seq":32,"section":"V. Standard de preuve","text":"L’EEI a adopté le même niveau de preuve que la majorité des commissions d’enquête\ninternationales et autres missions d’établissement des faits, à savoir celui des « motifs\nraisonnables de croire ». Pour fonder ses conclusions factuelles, l’EEI a veillé à réunir un\nensemble d’informations fiables et concordantes sur la base desquelles une personne\nraisonnable et normalement prudente aurait des motifs de croire qu’un incident ou qu’un\ncomportement s’est produit."},{"id":"a-hrc-38-crp-1-p0033","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"33","seq":33,"section":"V. Standard de preuve","text":"L’EEI a procédé à une analyse rigoureuse des informations collectées et a évalué\nindividuellement la crédibilité des témoignages et la fiabilité des éléments de preuve\nrecueillis. Concernant la fiabilité des sources, l’EEI a pris en compte la nature de la source\nqui a fourni l’information, son indépendance et sa méthodologie. La crédibilité des témoins\na été évaluée en prenant en compte leurs intérêts personnels et politiques, leur position par\nrapport aux évènements et leur motivation à être entendus. L’EEI a aussi évalué la\ncohérence interne du récit et la capacité du témoin à se souvenir des évènements au regard\nde son âge, de son état de santé, et de son traumatisme."},{"id":"a-hrc-38-crp-1-p0034","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"34","seq":34,"section":"V. Standard de preuve","text":"L’EEI a cherché à obtenir des informations concordantes auprès d’au moins deux\nsources indépendantes et fiables. Néanmoins, les informations obtenues d’un rapport\nd’enquête d’une source secondaire ayant suivi une méthodologie qui exigeait déjà la\ncorroboration des informations obtenues n’ont pas toujours nécessité de nouvelles enquêtes\nde la part de l’EEI. L’exigence de corroboration n’a pas été appliquée strictement dans les\ncas de violences sexuelles en raison de la difficulté de l’obtenir d’une autre source\nindépendante, en particulier lorsque la victime n’a pas bénéficié d’une assistance\nmédicale6."},{"id":"a-hrc-38-crp-1-p0035","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"35","seq":35,"section":"VI. Sauvegarde et archivage des informations","text":"Le paragraphe 10 de la résolution 35/33 demande à l’EEI « de réunir et de conserver\ndes informations ». Dès lors, elle a veillé à collecter et conserver de manière claire et\norganisée dans une base de données sécurisée et confidentielle toutes les informations\nqu’elle a pu réunir. Les notes d’entretiens conduits par l’EEI ainsi que tous les documents\ncollectés au cours de l’enquête sont sauvegardés dans cette base de données, dont la garde a\nété confiée au Haut-Commissaire des Nations Unies aux droits de l’homme. L’EEI a\nautorisé ce dernier à partager les informations contenues dans la base de données avec tout\norgane et toute juridiction compétente remplissant les critères établis par le HCDH."},{"id":"a-hrc-38-crp-1-p0036","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"36","seq":36,"section":"VII. Contexte","text":"Le Kasaï, constitué depuis le redécoupage provincial de juillet 2015 de cinq\nprovinces, le Kasaï, le Kasaï Central, le Kasaï Oriental, le Lomami, et le Sankuru, reste une\ndes régions les moins développées de la RDC. Au plan national, le niveau de pauvreté a\nconnu une diminution depuis les vingt dernières années. Toutefois, entre 2005 et 2012,\nalors que ce taux diminuait dans d’autres régions de la RDC, le taux de pauvreté a\naugmenté au Kasaï, pour atteindre plus de 70% de la population7. Malgré de riches\nressources naturelles8, l’économie du Kasaï s’est effondrée depuis plusieurs décennies.\nL’Etat n’a investi que faiblement dans les services de base et les infrastructures, renforçant\nl’extrême pauvreté de la population et un sous-développement chronique9."},{"id":"a-hrc-38-crp-1-p0037","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"37","seq":37,"section":"VII. Contexte","text":"Le Kasaï est majoritairement peuplé de personnes de l’ethnie luba. A l’approche de\nl’indépendance, des violences ont éclaté au sein de la population luba. Aujourd’hui, cette\npopulation, qui partage une langue commune, le tshiluba, est relativement unie. En\nrevanche, les tensions entre les populations lubas et les populations chokwes et pendes,\nprésentes dans la partie sud et est de la province du Kasaï ont repris de l’importance avec le\nredécoupage territorial de 2015. La division de l’ancienne province du Kasaï Occidental en\ndeux nouvelles provinces a particulièrement exacerbé les tensions. Si le Kasaï Central reste\ndominé par la population luba, celle-ci a perdu de l’influence au profit des populations\nchokwes et pendes dans la province du Kasaï. La crise au Kasaï ne peut pas non plus être\nisolée des conflits locaux préexistants de chefferies coutumières et de partage des\nressources foncières et minières."},{"id":"a-hrc-38-crp-1-p0038","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"38","seq":38,"section":"VII. Contexte","text":"Le pouvoir coutumier, lié étroitement à l’identité ethnique, est une composante\nimportante du système du pouvoir local. Les chefs coutumiers jouent un rôle important\ndans l’administration publique, la gestion des villages, l’accès à la terre, et la justice locale\n; ils exercent aussi des fonctions spirituelles importantes. Ils sont nommés selon la tradition\nde la chefferie, puis reconnus par les autorités publiques, dont ils reçoivent un salaire10.\nBien que le rôle du chef coutumier soit en principe apolitique, les autorités étatiques\nexercent régulièrement des pressions à leur égard pour les inciter à s’aligner politiquement\nsur les autorités provinciales et nationales allant jusqu’à refuser de reconnaitre le statut de\nchef coutumier à des chefs pourtant nommés en accord avec la tradition."},{"id":"a-hrc-38-crp-1-p0039","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"39","seq":39,"section":"VII. Contexte","text":"Le Kasaï est traditionnellement un fief du principal parti d’opposition, l’Union pour la\ndémocratie et le progrès social (UDPS). Cela explique en partie la marginalisation de la\nrégion au plan national par le Gouvernement. La vague de violence au Kasaï depuis 2016\ns’inscrit dans un contexte national de tensions autour des élections présidentielles. En\ndécembre 2016, la majorité présidentielle et l’opposition politique ont signé un accord\nprévoyant la tenue d’élections présidentielles avant fin 2017 et interdisant au Président\nKabila de se présenter pour un troisième mandat11. Pourtant, au cours de l’année 2017, il\nest devenu clair que les élections n’auraient pas lieu à la fin de l’année comme le prévoyait\ncet accord. Des manifestations relatives au respect de l’accord ont été interdites ou\nréprimées dans plusieurs villes. Le Kasaï n’a pas été particulièrement touché par les\nmanifestations qui ont eu lieu à travers la RDC. Bien qu’il soit difficile d’exclure que le\ncontexte politique national ait pu influencer la réaction des autorités dans la gestion de la\ncrise au Kasaï, peu d’éléments permettent de conclure qu’il existe une connexion directe\nentre le déclenchement de la vague de violence au Kasaï et le processus des élections\nprésidentielles."},{"id":"a-hrc-38-crp-1-p0040","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"40","seq":40,"section":"VII. Contexte","text":"La vie du peuple luba demeure codifiée par la coutume et les traditions ; la sorcellerie\net les superstitions tiennent une place prépondérante12. Il existe également des fétiches,\nbons ou mauvais. Ainsi on trouve des fétiches d’immunité contre des projectiles, des\nfétiches de disparition. Ces fétiches peuvent être portés sur le corps ou cachés dans les\nvêtements que l’on porte. Certains sont avalés ou dissimulés dans le corps, sous forme de\npoudre. Certains objets du quotidien ou des animaux tels les chèvres et les poules peuvent\naussi avoir une signification particulière. Un grand nombre de règles vient régir la vie de la\ncommunauté et leur transgression peut entrainer de graves conséquences, non seulement\npour celui qui transgresse la norme mais aussi pour son entourage. La transgression est\nsource de malheur, de maladie ou de mort. La réparation d’une transgression appelle le plus\nsouvent la tenue d’une cérémonie et le versement d’offrandes afin d’éviter la punition des\nancêtres."},{"id":"a-hrc-38-crp-1-p0041","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"41","seq":41,"section":"VII. Contexte","text":"La femme est un des piliers fondamentaux du foyer et de la communauté et s’attaquer\nà elle revient à s’attaquer à la communauté. Ainsi un certain nombre de croyances\nentourent le corps de la femme13. Il existe des règles strictes concernant la nudité, et\nparticulièrement qui peut voir une femme mariée nue. Ainsi une femme ne doit pas voir sa\nfille ou sa belle-fille nue ; si cela se produit, une cérémonie réparatrice est nécessaire."},{"id":"a-hrc-38-crp-1-p0042","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"42","seq":42,"section":"VII. Contexte","text":"L’organisation sociale du peuple luba est patriarcale et patrilinéaire. Le but du\nmariage est multiple mais inclut l’agrandissement de la famille du père. Des règles strictes\nentourent la personne avec qui on peut avoir des relations sexuelles et se marier. La\nvirginité de la mariée n’est pas obligatoire mais elle reste importante. Les enfants\nreprésentent une grande richesse pour la famille au sens élargi. Le choix du nom d’un\nenfant est important même si les noms modernes ont fait leur apparition avec la\ncolonisation. Dans la tradition, les dépenses réalisées pour les filles sont vues à fonds perdu\ncar elles seront mariées à d’autres familles et leurs enfants viendront agrandir celles-ci. Les\nfemmes qui ne sont pas mariées sont stigmatisées dans la communauté. Le mariage\ntraditionnel reste prépondérant et celui-ci n’est pas valable sans le versement de la dot. La\nsituation économique du Kasaï et le chômage élevé des jeunes est une cause anxiogène\ndans la communauté car les jeunes hommes ont des difficultés à s’acquitter de la dot.\nL’infidélité conjugale de la femme, et la coutume ne fait pas la distinction entre le viol et\nl’adultère, est une faute très grave ; celle-ci ne peut être réparée, si le mari le veut bien, que\npar une cérémonie de purification et le versement d’offrandes expiatoires par la famille de\nla femme. En attendant, la femme perd ses droits d’épouse. Le mari peut également décider\nde divorcer et la famille de la femme doit alors rembourser la dot. Si rien n’est fait pour\nréparer l’affront que constitue l’adultère, la croyance veut que des personnes puissent\nmourir."},{"id":"a-hrc-38-crp-1-p0043","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"43","seq":43,"section":"VII. Contexte","text":"Hormis pour les personnes âgées, lorsqu’une personne meurt, il est nécessaire de\ntrouver une raison à ce décès. Ainsi par exemple, dans un couple, lorsque le mari décède,\non va se demander si une faute de son épouse ne serait pas à l’origine de la mort. Hors les\nchefs qui sont généralement enterrés dès le décès constaté, les enterrements ont lieu 24 à 48\nheures après le décès car les enterrements hâtifs sont considérés comme une insulte au\ndéfunt. Les pleurs sont importants lors d’un décès et sont la principale expression du deuil."},{"id":"a-hrc-38-crp-1-p0044","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"44","seq":44,"section":"A. Les forces de défense et de sécurité","text":"Les forces de défense et de sécurité congolaises englobent les Forces armées de la\nRépublique démocratique du Congo (FARDC), la Police nationale congolaise (PNC),\nl’Agence nationale de renseignements (ANR) et la Direction générale de migration (DGM).\nLe travail de l’EEI a particulièrement mis en lumière l’implication des FARDC et dans une\nmoindre mesure de la PNC dans les évènements qui se sont déroulés au Kasaï depuis 2016."},{"id":"a-hrc-38-crp-1-p0045","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"45","seq":45,"section":"A. Les forces de défense et de sécurité","text":"Les FARDC sont les héritières de la Force publique de l’Etat indépendant du Congo,\npuis de l’Armée nationale congolaise et des Forces armées zaïroises depuis l’indépendance.\nHistoriquement, les membres des forces armées ont eu une propension à commettre des\nviolations graves contre la population, à vivre au crochet de celle-ci, à piller et à tuer le plus\nsouvent en toute impunité, à ne pas protéger la population et à la considérer plutôt comme\nun ennemi. Cette situation perdure encore aujourd’hui. La composition ethnique de l’armée\na joué et continue de jouer un rôle important dans la dynamique des FARDC et dans les\nnominations aux postes-clés. En novembre 2007, le Secrétaire général de l’ONU relevait\ndans un rapport que les FARDC, indisciplinées et mal encadrées, continuaient de menacer\nla sécurité de la population14. Malgré l’assistance de la communauté internationale, et\nparticulièrement de la MONUSCO, à la RDC dans la réforme de son secteur de la sécurité,\ncette dernière n’a toujours pas réussi à former une armée professionnelle, correctement\norganisée et disciplinée. Les membres des FARDC continuent de commettre fréquemment\nde graves violations des droits de l’homme contre la population civile et de vivre à ses\ndépens tout en continuant de jouir de l’impunité. Ceci malgré les dispositions explicites de\nla Constitution15, de la Loi organique n° 11/012 du 11 août 2011 portant organisation et\nfonctionnement des forces armées et de la Loi nº 13/005 du 15 janvier 2013 portant statut\ndu militaire des Forces Armées de la République Démocratique du Congo qui consacrent le\nrôle des FARDC pour la protection de la population et la promotion et protection des droits\nde l’homme. Certains auteurs de crimes et de violations graves sont traduits en justice ;\nnéanmoins, au regard des violations rapportées, peu sont encore sanctionnés."},{"id":"a-hrc-38-crp-1-p0046","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"46","seq":46,"section":"A. Les forces de défense et de sécurité","text":"La réponse des FARDC contre la milice Kamuina Nsapu est caractéristique d’un\nconflit asymétrique : il s’agit essentiellement d’un conflit entre des forces armées\nofficielles et un opposant informel, moins équipé, avec moins de ressources humaines et\nlogistiques mais résilient. A ce jour, on peut observer cinq phases de réaction des FARDC\ncontre la milice Kamuina Nsapu."},{"id":"a-hrc-38-crp-1-p0047","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"47","seq":47,"section":"A. Les forces de défense et de sécurité","text":"La première phase, ou phase de réaction rapide, met en scène l’ancienne 5ème Brigade\nintégrée, fruit du brassage entre d’anciens membres de groupes armés et de membres des\nforces armées, qui fut stationnée pendant un certain temps au Nord Kivu avant d’être\nredéployée à Kananga en juin 2007. Certains commandants seraient impliqués dans de\ngraves violations des droits de l’homme commises dans l’est de la RDC. Fin 2011, cette\nbrigade est devenue le 2101ème Régiment et formait le gros des troupes de la 21ème Région\nmilitaire (commandée à partir de Mbuji Mayi) faisant partie de la 2ème zone de défense\n(commandée de Lubumbashi) en application de la Loi organique n° 11/012 du 11 août\n201116. Les affrontements lors de cette phase de réaction rapide ont duré d’avril à août\n2016, affectant sans distinction les membres de la milice et la population du Kasaï Central,\nen raison du manque d’information sur les buts et les capacités de la milice Kamuina\nNsapu. En conséquence, la population a initialement soutenu le mouvement Kamuina\nNsapu d’autant plus que les membres du 2101ème régiment sont principalement perçus par\nelle comme des « étrangers », des « rwandais », car ils viennent de l’est de la RDC."},{"id":"a-hrc-38-crp-1-p0048","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"48","seq":48,"section":"A. Les forces de défense et de sécurité","text":"La seconde phase, ou phase anti-insurrectionnelle de base, débute avec la mort du\nchef du mouvement Kamuina Nsapu et se déroule jusque début mars 2017. Alors que les\nautorités acquièrent une meilleure connaissance du mouvement Kamuina Nsapu, les\nFARDC renforcent leurs troupes pour atteindre 7 000 hommes fin 2016 alors qu’ils\nestiment alors entre 500 et 1 000 le nombre de combattants Kamuina Nsapu à neutraliser.\nLes FARDC tentent de garder un profil bas dans leurs actions et comptent sur la mise en\nplace de barrières, de cordons de sécurité, d’opérations de recherche et d’actions de terre\nbrûlée, et d’opérations psychologiques utilisant les médias pour arriver à leurs fins. Cette\ntactique continue d’éloigner les FARDC de tout soutien de la population17."},{"id":"a-hrc-38-crp-1-p0049","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"49","seq":49,"section":"A. Les forces de défense et de sécurité","text":"La troisième phase, ou phase de reconnaissance nationale et d’opération\npsychologique, se situe entre mars et septembre 2017. Le Gouvernement de la RDC crée le\nsecteur opérationnel du Grand Kasaï le 9 mars 2017 et le même mois on assiste à des\nnégociations entre la famille de Jean-Prince Mpandi et le gouverneur du Kasaï Central.\nCelles-ci conduisent à la restitution par les autorités congolaises du corps de Jean-Prince\nMpandi et à la désignation, par les représentants de la famille, d’un nouveau chef Kamuina\nNsapu. Malgré cet accord, la milice Kamuina Nsapu continue ses activités. On estime qu’à\nce moment-là, la milice Kamuina Nsapu regroupe au moins 2 500 combattants,\nprincipalement des enfants. Mais, c’est plus la stratégie et la tactique que le nombre de\ncombattants qui importe maintenant car la milice a la capacité d’envoyer des combattants\nsur tout le territoire des Lubas du Kasaï18 qu’elle recrute dans la jeunesse sans emploi. Cela\npose une menace aux capacités opérationnelles et logistiques des FARDC qui ne peuvent\nêtre présents sur l’ensemble du territoire kasaïen. Les FARDC lancent alors des opérations\npsychologiques : en impliquant parfois la communauté internationale en cherchant à faire\nreconnaitre la milice Kamuina Nsapu comme groupe terroriste ou en avertissant la\npopulation locale que les pratiques surnaturelles n’empêcheront pas les FARDC de tuer les\nmiliciens."},{"id":"a-hrc-38-crp-1-p0050","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"50","seq":50,"section":"A. Les forces de défense et de sécurité","text":"La quatrième phase, ou phase initiale de conflit non-conventionnel, débute en octobre\n2017 pour se terminer à la fin de la même année. Les FARDC semblent reconnaître au\nniveau opérationnel l’utilisation de pouvoirs supranaturels de la milice Kamuina Nsapu.\nCela a pour conséquence le recours par les FARDC à leurs propres cérémonies mystiques\nafin d’insuffler un sentiment d’invulnérabilité aux troupes19. On arrive à un status quo des\naffrontements. Les troupes FARDC redescendent à 4 500 hommes et sont principalement\norganisées au sein de trois régiments, stationnés au Kasaï, Kasaï Central et Kasaï Oriental\ncommandées à partir du quartier général du secteur opérationnel à Kananga."},{"id":"a-hrc-38-crp-1-p0051","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"51","seq":51,"section":"A. Les forces de défense et de sécurité","text":"La cinquième phase, ou phase actuelle de conflit non-conventionnel, a débuté en\njanvier 2018. Alors que la milice Kamuina Nsapu semble renforcer son recours aux\ncroyances surnaturelles pour combattre les forces de défense et de sécurité et prend\nprincipalement les FARDC pour cible, les FARDC remanient leur organisation au Kasaï en\nde plus petites unités. Le recours aux croyances surnaturelles par une partie des FARDC a\ncréé une rupture avec ceux qui n’y croient pas."},{"id":"a-hrc-38-crp-1-p0052","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"52","seq":52,"section":"A. Les forces de défense et de sécurité","text":"La PNC, quant à elle, est très largement sous équipée et sous entraînée pour répondre\naux violences au Kasaï, malgré des renforts d’une unité spécialisée dans le maintien de\nl’ordre, la Légion nationale d’intervention (LNI). Dans les premiers mois du conflit, la\nPNC était, dans la plupart des cas, le seul représentant armé des forces de défense et de\nsécurité sur le terrain. Certains agents de la PNC ont combattu contre la milice Kamuina\nNsapu mais ils ont souvent été vaincus. La majorité des agents de la PNC a fait le choix de\nla fuite à l’arrivée de la milice Kamuina Nsapu. Lorsque les agents de PNC n’ont pas réussi\nà fuir, ils ont fréquemment été les premières victimes des miliciens Kamuina Nsapu,\nsouvent sans opportunité de combattre. Dans certains cas, la PNC est intervenue en soutien\ndes FARDC lors d’opérations militaires."},{"id":"a-hrc-38-crp-1-p0053","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"53","seq":53,"section":"B. La milice Kamuina Nsapu","text":"Le terme Kamuina Nsapu renvoie aussi bien au village et groupement du même\nnom20, siège du pouvoir coutumier du clan Bashila Kasanga, qu’au titre du chef de ce clan\nou à la milice et ses membres."},{"id":"a-hrc-38-crp-1-p0054","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"54","seq":54,"section":"B. La milice Kamuina Nsapu","text":"Le mouvement Kamuina Nsapu est ancré dans l’héritage culturel de la nation luba qui\nest aujourd’hui présente dans trois régions de la RDC : dans la province du Haut-Lomami ;\nà l’est, par-delà la rivière Lualaba jusqu’au lac Tanganyika ; à l’ouest dans ce qui compose\nle Kasaï. Les Bashilange, c’est-à-dire ceux qui ont le léopard comme totem clanique, sont\nles Lubas du Kasaï21. Historiquement, les Bashilange ont eu du mal à cohabiter avec le\ncolonisateur et contrairement à d’autres clans, ont refusé de travailler ou d’étudier avec lui.\nAprès l’indépendance, la situation économique des Bashilange ne s’est pas améliorée, cela\nà cause du décalage entre les emplois disponibles et leurs compétences. Depuis, le taux de\nchômage est resté élevé. La vie quotidienne des Lubas reste très influencée par leurs\ncroyances ancestrales, qui jouent un rôle central dans leur organisation sociale."},{"id":"a-hrc-38-crp-1-p0055","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"55","seq":55,"section":"B. La milice Kamuina Nsapu","text":"La milice Kamuina Nsapu, majoritairement composée de personnes d’origine luba, est\nnée d’un conflit de pouvoir coutumier. Le chef Kamuina Nsapu, chef du village du même\nnom, est le chef du groupement de Bashila Kasanga, le chef du peuple Bashila Kasanga et\nle chef militaire du royaume Bashilange."},{"id":"a-hrc-38-crp-1-p0056","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"56","seq":56,"section":"B. La milice Kamuina Nsapu","text":"Après la mort de l’ancien chef Kamuina Nsapu en septembre 2012, Ntuma Mupala,\nchef de la chefferie Bashila Kasanga22, sur le territoire de Dibaya, province du Kasaï\nCentral, Jean-Prince Mpandi est nommé comme successeur par la famille Kamuina Nsapu\nen septembre 201323. La chefferie Bashila Kasanga appartient au royaume des Bashilange\ndont les chefferies se sont étendues depuis l’époque coloniale jusqu’en Angola voisin. Afin\nd’être reconnu comme chef coutumier, le droit congolais prévoit que Jean-Prince Mpandi\ndoit être investi et reconnu comme tel par les autorités publiques dans un arrêté24. La\ndemande de reconnaissance de Jean-Prince Mpandi comme chef coutumier Kamuina\nNsapu est rejetée par le Ministre de l’Intérieur, Evariste Boshab, pour des raisons politiques\nalors que les autorités appuient Ntenda Tshiambi, chef coutumier du village Ntenda, rival\nde Jean-Prince Mpandi et politiquement proche du Gouverneur du Kasaï Central de\nl’époque, Alex Kande25."},{"id":"a-hrc-38-crp-1-p0057","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"57","seq":57,"section":"B. La milice Kamuina Nsapu","text":"Le 3 avril 2016, une perquisition a été conduite au domicile du chef coutumier\nKamuina Nsapu, Jean-Prince Mpandi dans le village Kamuina Nsapu, groupement de\nDibayati, territoire de Dibaya, Kasaï Central alors qu’il se trouvait en Afrique du Sud. Cette\nperquisition ordonnée par les autorités judiciaires et conduite sur ordre de mission signé par\nle gouverneur du Kasaï Central de l’époque, Alex Kande Mupompa, avait pour objectif la\nrecherche d’armes à feu26."},{"id":"a-hrc-38-crp-1-p0058","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"58","seq":58,"section":"B. La milice Kamuina Nsapu","text":"En avril 2016, Jean-Prince Mpandi retourne à Kamuina Nsapu. Dès lors, il annonce la\ncréation d’un mouvement « politico-coutumier » reposant sur les pratiques et la légitimité\ndu pouvoir coutumier et le système des croyances ancestrales. Son mouvement s’oppose\naux autorités étatiques et aux « étrangers »27 responsables, selon lui, du harcèlement de la\npopulation et du manque d’opportunités économiques28."},{"id":"a-hrc-38-crp-1-p0059","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"59","seq":59,"section":"B. La milice Kamuina Nsapu","text":"Le lancement officiel du mouvement a lieu le 28 juillet 201629. Jean-Prince Mpandi a\nprononcé à cette occasion un discours à l’attention des miliciens Kamuina Nsapu dans\nlequel il a indiqué que la perquisition à son domicile aurait été conduite par cinq militaires.\nDans ce même discours, Jean-Prince Mpandi a expliqué qu’au cours de cette perquisition\nles militaires auraient profané ses fétiches, ses vêtements de chef coutumier et tenté de\nvioler son épouse30. D’après les informations disponibles aucune arme n’aurait été\n22\nBashila Kasanga désigne à la fois la chefferie et groupement du même nom.\n23\nVoir notamment T0137.\n24\nConstitution de la République Démocratique du Congo du 18 février 2006 telle que modifiée par la loi\ndu 20 janvier 2011 ; Loi organique 08/016 du 16 octobre 2008 portant composition, organisation et\nfonctionnement des entités territoriales décentralisées et leurs rapports avec l’Etat et les provinces ;\nLoi 15/015 du 25 août 2015 fixant le statut des chefs coutumiers ; T0112, T0417.\n25\nVoir notamment T0311, T0023, T0112, T0080, T0137, T0417.\n26\nVoir par exemple T0417, T0017.\n27\nLa référence aux « étrangers » renvoie aux personnes venant du Rwanda mais aussi de l’est du Congo\net rwandophones. Voir notamment T0023, T0112, T0331, T0417, T0181.\n28\nVoir notamment T0399, T0188, T0137, T0171 ; Discours de Jean-Prince Mpandi à l’occasion du\nlancement officiel de son mouvement le 28 juillet 2016.\n29\nVoir T0399, T0331 ; discours de Jean-Prince Mpandi à l’occasion du lancement officiel de son\nmouvement le 28 juillet 2016.\n30\nDiscours de Jean-Prince Mpandi à l’occasion du lancement officiel de son mouvement le 28 juillet\n2016. Voir aussi T0311, T0023, T0399, T0137, T0417, T0017. Voir aussi l’enregistrement de la\nconversation téléphonique entre le chef Kamuina Nsapu et la délégation de députés du 11 août 2016,\ndécouverte lors de cette perquisition31, mais cet incident a accentué l’animosité de Jean-\nPrince Mpandi vis-à-vis des autorités politiques, des forces de défense et de sécurité et à\nl’encontre du chef du village voisin de Ntenda, membre de la famille Kamuina Nsapu et\nsuspecté d’être à l’origine d’une dénonciation qui aurait conduit à la perquisition32."},{"id":"a-hrc-38-crp-1-p0060","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"60","seq":60,"section":"B. La milice Kamuina Nsapu","text":"Jean-Prince Mpandi a recruté des miliciens, en majorité des enfants, dans son village\net sur le territoire de Dibaya33 et fait ériger des barrières à partir de juin 2016 pour contrôler\nla circulation des agents de l’Etat qu’il voulait empêcher de pénétrer dans Kamuina\nNsapu34. La première attaque de la milice Kamuina Nsapu a été dirigée contre le village du\nchef rival Ntenda Tshiambi35. Par la suite, la milice Kamuina Nsapu a attaqué les symboles\nde l’Etat sur le territoire de Dibaya36. Les efforts des autorités politiques pour trouver une\nsolution négociée avec le chef coutumier Kamuina Nsapu ayant été inefficaces, celles-ci\nont rapidement choisi le recours à la force."},{"id":"a-hrc-38-crp-1-p0061","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"61","seq":61,"section":"B. La milice Kamuina Nsapu","text":"Le 12 août 2016, Jean-Prince Mpandi est tué dans l’attaque de son village par les\nforces de défense et de sécurité et son cadavre transporté à Kananga, provoquant\nl’indignation des Bashilange. En effet, selon la tradition, les chefs coutumiers sont enterrés\nen secret la nuit de leur mort suivant des rites bien établis. L’appartenance de la famille\nKamuina Nsapu au royaume des Bashilange a favorisé l’expansion rapide de la milice qui\ns’est propagée grâce à un système de recrutement bien organisé et la mise en place de\ntshiota (foyer initiatique). Des envoyés du défunt chef Kamuina Nsapu, parfois appelés «\napôtres », sont passés de village en village sur une zone géographique de plus en plus\nétendue pour y installer leurs tshiota, décapitant les chefs de village qui s’opposaient au\nmouvement. Des groupes de miliciens Kamuina Nsapu marchent vers Kananga afin de\nramener le corps de Jean-Prince Mpandi dans son village pour l’enterrer. Ils entreront à\nKananga le 22 septembre 2016 et des affrontements avec les forces de défense et de\nsécurité s’en suivront. Les tshiota ont ainsi été installés dans les cinq provinces du Kasaï.\nLes villageois ont été appelés à se rallier volontairement au mouvement ; certains seront\ncontraints ; ceux qui refusaient ont souvent été décapités37."},{"id":"a-hrc-38-crp-1-p0062","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"62","seq":62,"section":"B. La milice Kamuina Nsapu","text":"Au tshiota, en présence d’un « apôtre » ou d’un chef de haut rang, souvent appelé «\nprésident », les recrues, y compris de jeunes enfants, ont dû suivre le rite du baptême, qui\nimplique de boire une potion composée de plusieurs ingrédients tels de l’alcool, des os\nhumains broyés, du sang humain ou des insectes et de suivre des pratiques rituelles38. Les\nrecrues faisaient alors partie de la milice où les croyances ancestrales, les rites et les\nfétiches jouaient un rôle extrêmement important39. Pour maintenir leur invincibilité face\naux armes à feu des forces de défense et de sécurité, ces croyances exigeaient l’adhésion à\ndes règles de vie strictes40. Le tshiota était aussi le lieu privilégié des décapitations, souvent\ndisponible sur le site internet de Radio France internationale (RFI) (http://webdoc.rfi.fr/rdc-kasai-\nviolences-crimes-kamuina-nsapu/chap-01/).\npratiquées par des enfants, et des actes de cannibalisme. On y ramenait des têtes et d’autres\nparties du corps des victimes d’attaques ainsi que leur sang41."},{"id":"a-hrc-38-crp-1-p0063","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"63","seq":63,"section":"B. La milice Kamuina Nsapu","text":"L’organisation des unités et la planification des opérations offensives se décidaient au\ntshiota42. Avant les affrontements, les miliciens participaient à des rituels impliquant\nnotamment la consommation d’une potion souvent alcoolisée et l’ingestion de drogues\ncomme du chanvre43. Typiquement, lors des combats, les miliciens Kamuina Nsapu\ns’organisaient avec, en première ligne, une ou plusieurs jeunes filles appelées « ya\nmama »44. Elles avaient, selon leurs croyances, le pouvoir d’intercepter les projectiles\nd’armes à feu dans leurs jupes et les renvoyer vers l’ennemi45. Juste derrière suivaient des\ngarçons munis d’armes blanches (couteaux, machettes), de lance-pierres et de bâtons46. Ces\nderniers, dont certains avaient la forme d’un fusil, avaient, selon la croyance, le pouvoir\nmagique de se transformer en armes mortelles. Des miliciens plus âgés et mieux équipés\navec des fusils traditionnels ou de chasse et parfois des armes automatiques étaient en\ndernière ligne47."},{"id":"a-hrc-38-crp-1-p0064","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"64","seq":64,"section":"B. La milice Kamuina Nsapu","text":"Le nombre de miliciens constituant un groupe opérationnel variait mais se situait\ngénéralement entre 15 et 30, dont une majorité d’enfants48. A la tête de chaque groupe se\ntrouvait un « général » ou un « capita »49. Pendant les opérations, les miliciens Kamuina\nNsapu portaient presque toujours les mêmes signes distinctifs : des bandeaux rouges autour\nde la tête avec des feuilles, des plumes, et des petits couteaux coincés dedans, des fétiches\nautour du cou et parfois des bandeaux rouges autour des bras50 ; les « ya mama » portaient\ndes jupes courtes de couleur rouge51. La milice Kamuina Nsapu a été capable en un temps\ntrès court de recruter des miliciens, de mener des attaques dans les cinq provinces du Kasaï\net de prendre le contrôle de villages et de cités pendant plusieurs semaines, voire des mois."},{"id":"a-hrc-38-crp-1-p0065","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"65","seq":65,"section":"B. La milice Kamuina Nsapu","text":"Si dans les premiers mois du conflit, la milice Kamuina Nsapu s’attaquait à ce qu’elle\nconsidérait être des symboles de l’Etat, à partir de 2017 elle vise tous ceux qui s’opposent\nau mouvement en recourant à des formes de violence de plus en plus extrêmes. Ses\nattaques ont également pris un caractère ethnique en dehors des zones lubaphones."},{"id":"a-hrc-38-crp-1-p0066","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"66","seq":66,"section":"C. Les milices Bana Mura","text":"Les milices Bana Mura sont composées en grande majorité d’hommes jeunes de\nl’ethnie chokwe, mais aussi de quelques hommes des ethnies pende et tetela52, recrutés\nlocalement. Les milices Bana Mura ont été créées localement à partir de février-mars 2017\ndans la province du Kasaï, dans certaines parties du territoire de Kamonia et de la ville de\nTshikapa, en réaction aux attaques de la milice Kamuina Nsapu, d’ethnie luba, contre les\nChokwes et Pendes53. Elles s’en sont principalement prises à la population luba, mais aussi\naux populations suspectées de soutenir la milice Kamuina Nsapu, telles que la population\nbindi54. Les miliciens Bana Mura étaient armés de machettes neuves de marque Tramontina\net de diverses armes à feu, certaines neuves55."},{"id":"a-hrc-38-crp-1-p0067","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"67","seq":67,"section":"C. Les milices Bana Mura","text":"L’EEI a collecté de multiples témoignages et informations provenant d’autres sources\nmontrant qu’il existe des liens plus ou moins étroits entre les forces de défense et de\nsécurité et les milices Bana Mura. Dans la cité de Kamonia ces liens étaient très étroits. La\ncréation des milices Bana Mura dans la cité de Kamonia s’est faite sous l’impulsion de\nplusieurs chefs locaux chokwes, dont un ancien député national56 et a été largement\nencouragée par un Colonel de la PNC57. Des réunions ont eu lieu entre les miliciens et ce\ncolonel de la PNC58. Par ailleurs, plusieurs témoignages et d’autres sources secondaires\nconfirment des distributions d’armes aux miliciens Bana Mura59. Dans la cité de Kamonia\net dans les villages voisins, les forces de défense et de sécurité et les miliciens Bana Mura\nont combattu et mené des opérations de traque des miliciens Kamuina Nsapu de manière\nconjointe60. De plus, d’autres opérations ont été conduites conjointement entre les forces de\ndéfense et de sécurité et les milices Bana Mura sur le territoire de Kamonia61. Dans le\nsecteur de Lovua-Longatshimo, toujours sur le territoire de Kamonia, le chef du\ngroupement de Muyeji a joué un rôle prépondérant dans la création de milices Bana Mura,\nleur armement et la planification d’attaques contre la population luba dans les villages de\nson groupement, tels que les villages de Senge (ou Cinq), Camp Kwilu, Kakongo et Mvula-\nMilenge. Si certains acteurs locaux des forces de défense et de sécurité tels que des agents\nde la DGM et de l’ANR ont pu jouer un rôle dans ces attaques, la présence des FARDC et\nde la PNC n’a pas été rapportée62. Les milices Bana Mura ont opéré seules dans ce secteur\nmais sans que les forces de défense et de sécurité n’interviennent pour stopper les violences\nou venir en aide aux victimes. Plus récemment, les forces de défense et de sécurité se sont\nparfois affrontées aux milices Bana Mura63."},{"id":"a-hrc-38-crp-1-p0068","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"68","seq":68,"section":"C. Les milices Bana Mura","text":"L’EEI n’a pas reçu d’informations suffisantes qui permettent de conclure à l’existence\nd’une chaîne de commandement commune entre les différentes milices Bana Mura qui\nopéraient dans le territoire de Kamonia, province du Kasaï. Néanmoins certains liens\nexistaient entre les différentes milices Bana Mura. Par exemple, des distributions d’armes\nont eu lieu à plusieurs endroits du territoire de Kamonia au cours de la même période et les\narmes utilisées par les différents groupes lors des attaques étaient identiques."},{"id":"a-hrc-38-crp-1-p0069","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"69","seq":69,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"La perquisition du domicile du chef coutumier Kamuina Nsapu, Jean-Prince Mpandi,\nle 3 avril 2016, et la création subséquente de son mouvement « politico-coutumier » ont\nannoncé le début des violences dans le territoire de Dibaya, Kasaï Central64. Après son\nretour au village Kamuina Nsapu, Jean-Prince Mpandi a mobilisé la population pour\nqu’elle adhère à son mouvement et dans le but de créer une milice. Entre mai et août 2016,\nJean-Prince Mpandi a recruté massivement des miliciens dans son village, dans les villages\ndu groupement de Dibataie65, puis plus largement dans le territoire de Dibaya, dans les\nvillages et groupements des chefs coutumiers dont il avait le soutien66. Le recrutement dans\nla milice Kamuina Nsapu visait l’ensemble de la population mais en tout premier lieu les\nenfants, garçons et filles, dont certains très jeunes67. L’enrôlement passait par\nl’accomplissement d’un rituel de « baptême » au tshiota68."},{"id":"a-hrc-38-crp-1-p0070","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"70","seq":70,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"Par exemple, en mai-juin 2016, Jean-Prince Mpandi a enrôlé dans la milice environ\n200 personnes, dont des enfants âgés de 5-6 ans lors d’une cérémonie de baptême collectif\nau village Kamuina Nsapu. D’autres chefs de villages étaient présents ainsi que des\nmembres de la famille de Jean-Prince Mpandi69. Le 4 août 2016, Jean-Prince Mpandi a\nprononcé un discours dans le village de Mfuamba appelant la population à se révolter et à\nrejoindre le mouvement Kamuina Nsapu. Suite à ce discours de nombreux jeunes de\nMfuamba sont partis pour le village Kamuina Nsapu. Plus de 100 enfants de l’école de\nMfuamba ont rejoint les rangs de la milice ce jour-là70. Un témoin explique qu’en août\n2016, il a été stoppé avec trois autres garçons âgés de 14 à 17 ans à une barrière tenue par\nhuit miliciens Kamuina Nsapu au niveau du village de Kabudi, sur la route entre les\nvillages de Mfuamba et Tshimbulu. L’un des miliciens qui se faisait appeler le « délégué »\na demandé aux quatre garçons de rejoindre la milice et les a menacés de mort en cas de\nrefus. Les quatre garçons ont donc suivi un enfant milicien jusqu’au tshiota de Kabudi. Un\nhomme qui portait un bandeau rouge autour de la tête et une robe rouge les a baptisés. Ils\nont ainsi intégré la milice Kamuina Nsapu71."},{"id":"a-hrc-38-crp-1-p0071","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"71","seq":71,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"Outre les éléments collectés par l’EEI, la MONUSCO a documenté plus de 112 cas\nd’enfants parmi lesquels au moins 17 filles, recrutés dans la milice Kamuina Nsapu entre\navril et août 2016 dans le territoire de Dibaya. Certains de ces enfants ont indiqué la\nprésence de dizaines d’autres enfants kidnappés et recrutés tout comme eux. Cela tend à\ndémontrer que le nombre d’enfants enrôlés dans ce territoire pendant cette période est très\nsupérieur au nombre de cas documentés. Ces enfants, étaient essentiellement âgés de 4 à 15\nans, quelques-uns de 16-17 ans. Le 15 août 2016, dans le village de Tshikula, au moins 11\nenfants ont été kidnappés par les Kamuina Nsapu alors qu’ils rentraient de l’école. Les plus\njeunes racontent qu’ils ont été utilisés pour garder le tshiota ou pour servir à la garde\nrapprochée du chef Kamuina Nsapu, Jean-Prince Mpandi. D’autres, parmi les plus âgés,\nétaient chargés de procéder à l’arrestation d’habitants des villages qui ne respectaient pas\nles règles imposées par la milice. Tous, des plus jeunes aux plus âgés, ont été utilisés lors\nd’affrontements contre les forces de défense et de sécurité. Il ressort que la plupart des\nenfants kidnappés et recrutés durant cette période ont par la suite été utilisés pour attaquer\nle village de Ntenda et différents points de la ville de Kananga, notamment l’aéroport en\nseptembre 201672."},{"id":"a-hrc-38-crp-1-p0072","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"72","seq":72,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"A partir de juin 2016, les miliciens Kamuina Nsapu ont érigé des barrières dans les\nenvirons du village Kamuina Nsapu dont le but était de contrôler la circulation des\npoliciers, des militaires ou de tout autre agent de l’Etat73. Il existait par exemple des\nbarrières au niveau des villages de Mbondo, Ntambwe, Kayembe, Tshikula et Kabunji74.\nLorsque des FARDC ou des PNC croisaient des miliciens Kamuina Nsapu, ces derniers\nleur demandaient de retirer leurs uniformes pour pouvoir continuer leur route. Au moins un\npolicier qui avait refusé de retirer son uniforme a été blessé après avoir été battu par des\nmiliciens Kamuina Nsapu non loin de l’hôpital général du village de Tshikula75."},{"id":"a-hrc-38-crp-1-p0073","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"73","seq":73,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"Le 22 juillet 2016, les Kamuina Nsapu ont lancé leur toute première attaque contre les\nsymboles de l’Etat. Elle était dirigée contre le sous-commissariat de police du village de\nMfuamba qui a été attaqué puis incendié au cours de la nuit par des miliciens munis de\nflèches, bâtons et machettes qui sont ensuite repartis vers le village Kamuina Nsapu76."},{"id":"a-hrc-38-crp-1-p0074","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"74","seq":74,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"Le 23 juillet 2016, Jean-Prince Mpandi et ses miliciens ont attaqué le village de\nNtenda situé à quelques kilomètres du village Kamuina Nsapu77. Avant l’attaque, un\naccrochage entre le chef du village de Ntenda et des miliciens Kamuina Nsapu qui tenaient\nune barrière a eu lieu. Cet accrochage aurait provoqué la colère du chef Kamuina Nsapu et\nété l’un des éléments déclencheur de l’attaque du village de Ntenda78. Une autre raison\navancée pour cette attaque aurait été le refus du chef du village Ntenda d’adhérer au\nmouvement Kamuina Nsapu79. De plus, il existait un conflit ancien entre Jean-Prince\nMpandi et le chef du village Ntenda, notamment sur le partage du pouvoir coutumier80.\nD’après une mission d’enquête spéciale conduite entre le 23 septembre et le 30 octobre\n2016 par le Bureau conjoint des Nations Unies aux droits de l’homme (BCNUDH) de la\nMONUSCO, le bilan de cette attaque est d’au moins six morts par arme à feu et arme\nblanche et de quatre personnes blessées par balle. Le frère du chef du village Ntenda a été\nbrûlé vif et un autre homme tué par un pilon puis brûlé par les miliciens Kamuina Nsapu.\nCette mission ainsi que l’EEI ont également confirmé qu’au moins une centaine de maisons\nont été incendiées. De plus, au moins huit églises, deux écoles primaires ainsi qu’un centre\nde santé ont été pillés81."},{"id":"a-hrc-38-crp-1-p0075","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"75","seq":75,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"Entre cette attaque et la mort de Jean-Prince Mpandi, le 12 août 2016, la milice\nKamuina Nsapu, sous les ordres de Jean-Prince Mpandi, a conduit une série d’attaques\ndans plusieurs villages du territoire de Dibaya. Ces attaques visaient les symboles de\nl’autorité étatique et ont abouti à la destruction et au pillage de bâtiments publics ou\nconsidérés comme tels et à l’attaque physique de personnes symbolisant ou assimilées à\nl’autorité publique. Les agents de la PNC ont été les premières victimes des attaques de la\nmilice Kamuina Nsapu. Au cours du mois d’août 2016, les villages de Mfuamba,\nTshimbulu, Tshikula, Dibaya et Bukonde ont été attaqués par la milice Kamuina Nsapu82."},{"id":"a-hrc-38-crp-1-p0076","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"76","seq":76,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"L’attaque la plus meurtrière commise par la milice Kamuina Nsapu au cours de cette\npériode est celle de la cité de Tshimbulu, située à 120 km au sud-est de la ville de Kananga.\nLe 8 août 2016, une cinquantaine de miliciens Kamuina Nsapu, en majorité des jeunes\nadultes et des enfants, sont entrés dans la cité de Tshimbulu83. Les miliciens ont détruit le\nbureau de la Commission électorale nationale indépendante (CENI)84. Ils se sont ensuite\ndirigés vers l’état-major de la PNC où il y a eu un affrontement entre miliciens et PNC85.\nUn témoin raconte qu’un élément de la PNC a tenté de fuir mais a été rattrapé par les\nmiliciens. Un milicien l’a alors frappé avec une lance et le policier est tombé au sol.\nD’autres miliciens l’ont alors frappé avec des couteaux et des machettes. Un milicien lui a\ncoupé les deux mains pendant que d’autres le maintenaient86. Le témoin a également vu\ntrois miliciens Kamuina Nsapu adultes blessés par balle au niveau des jambes87.\nUn membre de la milice ayant participé à l’attaque, indique que quatre miliciens ont été\nblessés88. Les miliciens ont ensuite pénétré dans la maison du colonel de la PNC de\nTshimbulu89. Un témoin qui a visité la maison après leur départ, y a vu les cadavres de\nquatre éléments de la PNC couverts de blessures et de brûlures ainsi que les corps de quatre\nmiliciens Kamuina Nsapu90. D’après plusieurs témoins et le bilan dressé par l’ANR et la\nMONUSCO, il y aurait au moins 10 morts dont cinq éléments de la PNC et cinq miliciens ;\nla mairie, le bureau de la CENI, le commissariat de police, le parquet, les résidences du\ncolonel de la PNC et du maire, la maison du chef de groupement ont été détruits91."},{"id":"a-hrc-38-crp-1-p0077","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"77","seq":77,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"L’attaque de la cité de Tshimbulu a été planifiée et ordonnée par Jean-Prince Mpandi\net était dirigée par un chef de mission. Pendant l’attaque, ce chef de mission communiquait\npar téléphone avec Jean-Prince Mpandi 92. Un membre de la milice qui a participé à\nl’attaque de Tshimbulu explique que le plan présenté par Jean-Prince Mpandi était\nd’attaquer les symboles de l’autorité étatique dans la cité de Tshimbulu, puis dans la ville\nde Kananga, avant d’attaquer d’autres endroits pour libérer le pays des étrangers93.\nPlusieurs témoins ont indiqué qu’un des motifs de l’attaque de Tshimbulu était que Jean-\nPrince Mpandi tenait pour responsable la PNC de Tshimbulu de la perquisition de son\ndomicile le 3 avril 201694. Un témoin du village de Mfuamba a vu les miliciens Kamuina\nNsapu revenir de Tshimbulu à pied et en camion et se diriger vers le village Kamuina\nNsapu avec la tête coupée d’un policier95. Un membre de la milice Kamuina Nsapu qui a\nparticipé à l’attaque de Tshimbulu indique qu’après l’attaque, de retour dans le village de\nKamuina Nsapu, Jean-Prince Mpandi a félicité les miliciens et les a nettoyés du sang qu’ils\navaient sur eux96."},{"id":"a-hrc-38-crp-1-p0078","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"78","seq":78,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"Entre la fin juillet 2016 et le 12 août 2016, plusieurs tentatives de médiation entre les\nautorités politiques et Jean-Prince Mpandi ont eu lieu97. En particulier, le 9 ou le 10 août\n2016, une délégation de députés nationaux, des élus de la province du Kasaï Central, a été\ndépêchée à Kananga pour négocier avec le chef Kamuina Nsapu98. Le 11 août 2016, la\ndélégation a discuté par téléphone avec Jean-Prince Mpandi de sa venue. Ce dernier a\nindiqué qu’il n’accepterait de se rendre à Kananga qu’avec une escorte de la MONUSCO\npour assurer sa sécurité99. Le même jour, au cours d’une seconde conversation téléphonique\nentre la délégation et Jean-Prince Mpandi, la délégation a répondu à Jean-Prince Mpandi\nque la MONUSCO n’était plus présente au Kasaï mais que sa sécurité serait garantie s’il\nacceptait de venir à Kananga. Le chef coutumier Kamuina Nsapu a refusé cette proposition\net les négociations ont échoué100. Le soir du 11 août 2016, le gouverneur du Kasaï Central\nde l’époque, Alex Kande, a indiqué à l’issue d’un appel téléphonique qu’il avait été décidé\nd’éliminer Jean-Prince Mpandi le lendemain101."},{"id":"a-hrc-38-crp-1-p0079","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"79","seq":79,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"En parallèle, une opération militaire d’envergure est lancée pour stopper le chef\nKamuina Nsapu et la progression des miliciens sur le territoire de Dibaya. Le 8 août 2016,\nune délégation de haut niveau dirigée par le Vice-Premier Ministre de l’intérieur et de la\nsécurité, Evariste Boshab, et composée des principaux responsables des forces de défense\net de sécurité, est arrivée à Kananga102. Le lendemain, des renforts militaires ont atterri à\nl’aéroport de Kananga103. D’après la MONUSCO, c’est un contingent de FARDC de la\n21ème région militaire provenant de la zone de Mbuji-Mayi au Kasaï Oriental qui a\ndébarqué pour appuyer ceux du 2011ème régiment des FARDC déjà présent au Kasaï\nCentral104. Le plan mis en place par les forces de défense et de sécurité était de prendre le\nterritoire de Dibaya en étau en créant cinq fronts sur les principaux axes avec pour\ndestination finale le village Kamuina Nsapu105."},{"id":"a-hrc-38-crp-1-p0080","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"80","seq":80,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"La présence massive de forces de défense et de sécurité sur le territoire de Dibaya\nentre le 10 et 12 août 2016, ainsi que des affrontements violents entre les miliciens\nKamuina Nsapu et les forces de défense et de sécurité dans les localités de Tshimbulu,\nDibaya, Tshikula, Sampi, Bitanda, Kazumba et Kabunji ont été rapportés106. Au cours de\nces opérations militaires, les forces de défense et de sécurité ont tiré sur les miliciens\nKamuina Nsapu, dont de nombreux enfants ; certains enfants étaient non armés, d’autres\nétaient en possession de bâtons, de couteaux ou machettes. Un témoin a ainsi dénombré au\nmoins 22 morts parmi les miliciens Kamuina Nsapu dans des affrontements avec les\nFARDC dans le village de Kabunji et huit dans le village de Kazumba107. Dans une vidéo\nfilmée par des FARDC le 11 ou 12 août 2016, au niveau d’une barrière érigée par les\nmiliciens Kamuina Nsapu à une bifurcation sur la route du village Kamuina Nsapu, on peut\nvoir plusieurs enfants miliciens tués par balles. La vidéo montre des FARDC, se présentant\ncomme appartenant à la 5ème brigade opérationnelle, en train de tirer à feu nourri en\ndirection de miliciens Kamuina Nsapu dépourvus d’armes à feu108. Il y a également eu des\nblessés et des morts parmi les FARDC au cours de ces opérations militaires mais, comme\nl’explique un témoin, les FARDC ramassaient les corps des militaires et il n’était donc pas\npossible de les comptabiliser109."},{"id":"a-hrc-38-crp-1-p0081","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"81","seq":81,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"Le 12 août 2016, les forces de sécurité ont atteint le village Kamuina Nsapu. Un\ntémoin, présent au village, a indiqué que de nombreux militaires sont arrivés à pied, en\nvéhicule et par hélicoptère110. Les miliciens Kamuina Nsapu se sont battus et il y a eu des\nmorts parmi les miliciens et les villageois. Le témoin indique que les miliciens ont blessé\ndes militaires avec leurs bâtons et machettes. Depuis sa maison, Jean-Prince Mpandi\n2016 et activités de la coordination provinciales de la Commission Nationale des droits de l’homme –\nCNDH/Kasaï Central, décembre 2016, document interne MONUSCO.\ndonnait des instructions de combat aux miliciens. Voyant la bataille perdue, Jean-Prince\nMpandi a ordonné aux miliciens Kamuina Nsapu de fuir et est resté sur place111. Jean-\nPrince Mpandi est alors tué par des FARDC et son corps est transporté à Kananga112. Sur\ndes vidéos tournées par les FARDC on peut voir le corps du chef coutumier Kamuina\nNsapu. Son pied est presque détaché, son visage tuméfié et sa chemise maculée de sang113.\nA son retour dans le village de Kamuina Nsapu deux jours après la mort de Jean-Prince\nMpandi, un témoin a indiqué avoir vu les cadavres de FARDC et d’habitants du village114."},{"id":"a-hrc-38-crp-1-p0082","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"82","seq":82,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"Dans les jours suivants, les affrontements entre des miliciens Kamuina Nsapu et les\nforces de défense et de sécurité se sont poursuivis dans le territoire de Dibaya115. Par\nexemple, à la mi-août 2016, le village de Tshikula a été le lieu de plusieurs\naffrontements116. D’après les informations collectées, les FARDC avaient établi une base\nmilitaire à la mission catholique de Tshikula au cours des opérations qui ont conduit à la\nmort de Jean-Prince Mpandi et y sont restés les semaines suivantes117. L’EEI a documenté\nun incident qui s’est déroulé le 16 août 2016 devant la mission catholique de Tshikula. Ce\njour-là, deux enfants miliciens Kamuina Nsapu en possession de bâtons se sont dirigés vers\nla mission catholique de Tshikula. Les membres des FARDC ont tiré sur les deux miliciens\navec une mitrailleuse tuant l’un des miliciens. Une foule de miliciens Kamuina Nsapu,\nfilles et garçons, la plupart sans aucune arme, d’autres en possession de bâtons, est arrivée\npour récupérer le corps du milicien tué. Les FARDC ont alors tiré sur eux et un témoin\nindique avoir vu au moins dix personnes se faire tuer par les militaires devant la mission\ncatholique de Tshikula. Plus tard dans la journée, le même scénario s’est reproduit et les\nFARDC ont tiré pendant plusieurs heures sur les miliciens. Les militaires étaient les seuls à\nutiliser des armes à feu ; il n’y avait pas d’échange de tirs118. Un autre témoin a expliqué\nque les FARDC ont ouvert le feu sans égard pour la population qui se trouvait dans le\nvillage et ont tiré non seulement sur les miliciens mais aussi des femmes, des personnes\nâgées et des enfants119. Un témoin indique qu’après ces affrontements, il a vu au moins 100\ncorps être jetés dans des camions120. Un autre indique avoir mis au moins 20 corps dans un\ncamion et qu’un autre camion transportait le corps de trois militaires tués. Les corps ont été\ntransportés de Tshikula à l’Ecole de Formation des officiers (EFO) à Kananga pour y être\nenterrés121. Un autre témoin indique qu’au moment de ces affrontements entre les miliciens\nKamuina Nsapu et les FARDC, il a vu deux corps de militaires tués et neuf corps de\nmiliciens Kamuina Nsapu dans la brousse, sans savoir comment ils avaient été tués122.\nL’EEI constate qu’il semble que les FARDC ont eu tendance à transporter par camion les\ncorps de miliciens Kamuina Nsapu tués lors d’affrontement à l’EFO, à Kananga123."},{"id":"a-hrc-38-crp-1-p0083","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"83","seq":83,"section":"A. Avril-août 2016 – début des violences sur le territoire de Dibaya –","text":"L’EEI relève qu’il est difficile de documenter les allégations d’actes de violence\ncommis par les forces de défense et de sécurité contre la population civile lors des\nopérations militaires lancées à partir du 10 août 2016 et qui ont continué dans les semaines\nsuivantes sur le territoire de Dibaya. Des témoins ont clairement exprimé des craintes pour\nleur sécurité s’ils s’exprimaient sur ces violences et ont parfois décliné de s’entretenir avec\nl’EEI pour cette raison."},{"id":"a-hrc-38-crp-1-p0084","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"84","seq":84,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"La mort de Jean Prince Mpandi n’a pas mis un terme aux violences. Au contraire, le\nmouvement Kamuina Nsapu a continué ses activités dans le territoire de Dibaya entre\nseptembre-décembre 2016 et les actes de violence de la milice Kamuina Nsapu et des\nforces de défense et de sécurité se sont étendus à partir de septembre 2016 aux autres\nterritoires du Kasaï Central. Au Kasaï Oriental, les territoires de Kabeya-Kamwanga et de\nMiabi ont également été touchés en octobre 2016. Fin novembre 2016, la milice Kamuina\nNsapu est devenue active sur le territoire de Kamonia, province du Kasaï, sur l’axe\nKananga-Tshikapa.\n1.         Province du Kasaï Central"},{"id":"a-hrc-38-crp-1-p0085","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"85","seq":85,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Le recrutement d’enfants par la milice Kamuina Nsapu et leur utilisation lors\nd’affrontements avec les forces de défense et de sécurité a perduré et s’est même accentué\nentre septembre et décembre 2016 au Kasaï Central, et en particulier dans le territoire de\nDibaya et dans les communes et quartiers de Kananga. Par exemple de nombreux enfants\nmiliciens ont participé aux attaques de l’aéroport de Kananga fin septembre 2016 et du\nvillage de Bukonde en décembre 2016124. Un témoin recruté dans la milice Kamuina Nsapu\nsur le territoire de Dibaya en août 2016 raconte que la personne qui l’a recruté est arrivée\ndans la commune de Nganza, ville de Kananga en décembre 2016 afin de recruter des\nnouveaux miliciens. Selon lui, le recruteur enrôlait de nouveaux groupes de jeunes dans\nchaque village du territoire où il était de passage et à chaque fois, il nommait un « capita »\nen charge du groupe recruté125."},{"id":"a-hrc-38-crp-1-p0086","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"86","seq":86,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"La MONUSCO a documenté plus de 101 cas de recrutements et d’utilisation\nd’enfants par la milice Kamuina Nsapu dont 11 concernaient des filles. Les enfants\nvictimes étaient âgés de 4 à 17 ans au moment des faits. Généralement munis de bâtons en\nbois, de petits couteaux, plus rarement de fusils calibre 12 et systématiquement postés en\npremière ligne, les enfants ont déclaré avoir été utilisés dans le cadre d’affrontements\ncontre les forces de défense et de sécurité dans Kananga et sur le territoire de Dibaya.\nNombre d’entre eux ont également dû décapiter des agents de l’Etat et des membres de la\ncommunauté. A ces 101 cas individuels documentés, s’ajoute un garçon recruté dans le\nvillage Kamuina Nsapu le 18 septembre 2016 qui déclare qu’au moins 110 garçons et 9\nfilles étaient présents avec lui au moment de son initiation. Un autre garçon recruté dans la\nville de Kananga le 10 septembre 2016 raconte qu’il était entouré d’une trentaine d’autres\nenfants. De la même manière, un garçon recruté dans une commune de Kananga affirme\nque plus de 50 enfants ont été recrutés avec lui le même jour. Dans le cadre des\naffrontements avec les forces de défense et de sécurité, de nombreux enfants ont été blessés\npar balle. En décembre 2016, au moins 7 enfants dont 3 filles ont été abattus par les\nFARDC dans le territoire de Dibaya126."},{"id":"a-hrc-38-crp-1-p0087","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"87","seq":87,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Le 22 septembre 2016, un groupe de miliciens Kamuina Nsapu dont de nombreux\nenfants recrutés à cet effet dans le territoire de Dibaya ont attaqué l’aéroport de la ville de\nKananga. Trois FARDC ont été tués lors de cette attaque127. Le lendemain, dans la matinée,\nl’aéroport de Kananga a été de nouveau attaqué et des affrontements entre les miliciens\nKamuina Nsapu et les FARDC ont eu lieu. Alors qu’elle tentait de fuir l’aéroport, une\nemployée de Congo Airways a été rattrapée par une vingtaine de miliciens Kamuina Nsapu\nqui lui ont donné des coups de machette à la tête, au dos et aux pieds. Informé de la\nprésence d’un blessé, un FARDC aurait donné l’ordre à ses subordonnés d’achever la\npersonne si elle n’était pas encore morte. Les FARDC n’ont pas tiré sur elle mais\nl’employée de Congo Airways est décédée lors de son transport à l’hôpital. Les miliciens\nKamuina Nsapu ont incendié les biens et les bâtiments à proximité du bâtiment de\nl’aéroport128."},{"id":"a-hrc-38-crp-1-p0088","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"88","seq":88,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Il y a eu des affrontements entre les miliciens Kamuina Nsapu et des FARDC au cours\ndesquels les militaires ont utilisé des lance-roquettes129. Un élément FARDC a donné\nl’ordre de tirer sur tout ce qui bougeait dans l’aéroport130. Un témoin affirme avoir vu une\nvingtaine de corps de miliciens Kamuina Nsapu et de FARDC à proximité de l’aéroport ce\njour-là. Les miliciens étaient nombreux, composés notamment de garçons et de filles et\nétaient munis de bâtons, couteaux, machettes et de fusils de chasse131. Les FARDC présents\nà l’aéroport étaient arrivés de l’EFO et parlaient swahili132. Dans les heures qui ont suivi\nl’attaque de l’aéroport, les FARDC ont tiré des roquettes sur des quartiers Aholé et\nKamapongo situés à proximité de l’aéroport. Ils sont ensuite venus ramasser les cadavres\nde civils pour les ramener à l’EFO133."},{"id":"a-hrc-38-crp-1-p0089","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"89","seq":89,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Un premier bilan dressé par la MONUSCO faisait d’état d’au moins 50 miliciens\nKamuina Nsapu, 16 FARDC et PNC, ainsi que de six civils tués134. D’après une mission\nd’enquête spéciale conduite par le BCNUDH de la MONUSCO et déployée début\nnovembre 2016, au cours de ces deux jours d’affrontements au moins six civils, huit\néléments des forces de défense et de sécurité et environ 170 miliciens Kamuina Nsapu ont\nété tués. De plus, au moins 37 personnes ont été blessées – principalement lors de\nmouvements de panique de la population– dont 29 enfants, ainsi que le commandant de la\nPNC de la ville de Kananga135."},{"id":"a-hrc-38-crp-1-p0090","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"90","seq":90,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Fin septembre 2016, en répression à l’attaque de l’aéroport de Kananga par la milice\nKamuina Nsapu, les FARDC ont commis des exactions contre la population civile lors\nd’opérations dans les rues de Kananga et d’autres dites « porte-à-porte » visant à la traque\ndes miliciens. Au cours de ces opérations, les FARDC ont blessé, tué et violé\nindistinctement des membres de la population civile."},{"id":"a-hrc-38-crp-1-p0091","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"91","seq":91,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Par exemple, le 28 septembre 2016, un témoin a vu un élément FARDC tirer à bout\nportant sur un écolier d’environ 12 ans vers la maison du barreau dans le centre-ville de\nKananga136. Toujours fin septembre 2016, une femme en fuite près de la commune de\nNganza, a été rattrapée par trois FARDC. Après l’avoir accusée d’appartenir à la milice\nKamuina Nsapu, les soldats l’ont battue puis déshabillée. Deux des trois éléments FARDC\nl’ont violée avant de la laisser partir137. Un habitant de Kananga témoigne qu’au cours de la\nmême période, une dizaine de personnes se trouvaient dans sa maison lorsque des FARDC\nsont entrés et y ont ligoté toutes les personnes présentes. Les membres des FARDC ont\nviolés les femmes qui se trouvaient là. Ensuite, reprochant à la femme du témoin de l’avoir\ndétaché, les FARDC l’ont violée et tuée138. Suivant le même mode opératoire et au cours de\nla même période, six FARDC sont entrés dans la maison d’un témoin en fracturant la porte\nde son habitation. Après avoir ligoté les neuf personnes présentes dans la maison, ils ont\nenfermé la femme du témoin dans une chambre. Les six FARDC l’ont violée avant de la\ntuer de deux balles dans la tête et la poitrine et de quitter la maison. Juste après, sa fille de\nsix ans a reçu une balle dans la poitrine et est décédée139."},{"id":"a-hrc-38-crp-1-p0092","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"92","seq":92,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"D’après une mission d’enquête spéciale conduite par le BCNUDH de la MONUSCO,\nentre le 23 septembre et le 30 octobre 2016, les militaires du 2011ème régiment des FARDC\nbasés à Kananga, appuyés par les éléments de la 21ème Région militaire des FARDC, ont\nlancé une série d’attaques et de traque pour contrer les miliciens Kamuina Nsapu dans leur\nretraite, dans plusieurs villages, notamment à Mwamba Mbuyi et Tshimpidinga, dans les\nenvirons de Kananga. Au moins 44 personnes, dont au moins neuf femmes, trois filles et\ntrois garçons, ont été victimes d’exécutions sommaires par des FARDC à Tshimpidinga. La\nmission d’enquête a également pu vérifier dans ce même village la disparition d’au moins\nsix personnes, parmi lesquelles un garçon de 15 ans. Au moins quatre personnes, parmi\nlesquelles un garçon de 15 ans, ont été blessées par des FARDC pendant qu’elles fuyaient à\nl’arrivée des militaires dans le village140."},{"id":"a-hrc-38-crp-1-p0093","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"93","seq":93,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Entre septembre et décembre 2016, les affrontements entre les miliciens Kamuina\nNsapu et les forces de défense et de sécurité se sont poursuivis sur le territoire de Dibaya ;\nces dernières ont fait usage de la force contre des miliciens Kamuina Nsapu. Parmi les\nmiliciens, certains étaient des enfants munis de bâtons ou non-armés. Les forces de défense\net de sécurité se sont livrées à des exactions contre la population civile du territoire de\nDibaya141."},{"id":"a-hrc-38-crp-1-p0094","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"94","seq":94,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Par exemple, l’EEI a documenté les incidents qui se sont déroulés dans le village de\nBukonde les 8 et 9 décembre 2016. Le 8 décembre 2016, la milice Kamuina Nsapu est\nentrée dans le village. L’attaque visait les symboles de l’autorité de l’Etat. Les miliciens\nont incendié l’Etat-major de la PNC et ont cherché les agents de la PNC142. Un témoin\nexplique qu’il est intervenu pour assister une personne menacée par quatre miliciens\nKamuina Nsapu qui étaient à la recherche des bureaux de l’administrateur du territoire. Les\nquatre miliciens l’ont alors poursuivi. Devant son refus d’indiquer la résidence des\npoliciers, il a reçu quatre coups de machette avant de réussir à s’enfuir143. Les miliciens\nKamuina Nsapu ont ensuite brûlé la maison où vivaient les policiers144. Un agent de l’ANR\na été tué ce jour-là à coups de machette par les miliciens Kamuina Nsapu. Sa main droite et\nson pied gauche ont été coupés et il avait des blessures de machette sur le visage145. Un\ntémoin raconte qu’il a dû, sous la contrainte, ramener en moto deux miliciens âgés de 12-14\nans blessés par balles à Bukonde, vers Tshibemba. Avec lui, deux autres motos\ntransportaient chacune deux à trois miliciens (deux majeurs et trois mineurs), tous blessés\npar balle lors de l’attaque de Bukonde 146."},{"id":"a-hrc-38-crp-1-p0095","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"95","seq":95,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Les FARDC sont arrivés à Bukonde le matin du 9 décembre 2016 en camion147. Les\nmiliciens Kamuina Nsapu ont fait une seconde incursion dans le village ce même jour. Les\nmiliciens Kamuina Nsapu, y compris des femmes, des filles et des garçons sont revenus en\nplus grand nombre - une centaine environ - armés de de couteaux, machettes, bâtons et de\nquelques fusils de fabrication locale148. De violents affrontements ont eu lieu entre les\nmiliciens Kamuina Nsapu et les FARDC149. Un témoin indique qu’il a vu les corps de trois\nenfants et deux adultes tués par balle à proximité des FARDC150 De nombreux corps de\nmiliciens ont été enterrés par les FARDC dans une mangeoire à cochons et d’autres\ncadavres ont été enterrés par la Croix-Rouge congolaise151. Les FARDC sont restés dans le\nvillage de Bukonde après cet incident et ont pillé les maisons des villageois qui avaient fui\nles violences et tué à l’arme automatique au moins un civil qu’ils auraient pris pour un\nmilicien152."},{"id":"a-hrc-38-crp-1-p0096","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"96","seq":96,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"La milice Kamuina Nsapu était également présente dans d’autres territoires du Kasaï\nCentral entre septembre et décembre 2016, notamment dans le territoire de Kazumba153,\nDimbelenge et de Demba. Suivant le même schéma que dans le territoire de Dibaya, la\ntraque de la milice Kamuina Nsapu par les forces de défense et de sécurité a conduit à la\ncommission d’exactions contre la population civile. En particulier, d’après une mission\nd’enquête spéciale conduite par le BCNUDH de la MONUSCO en novembre 2016, dans le\nvillage de Nkoto, territoire de Demba, le 30 septembre 2016, au moins 37 personnes parmi\nlesquelles au moins six femmes, cinq garçons et quatre filles, ont été tuées par balle par les\nmilitaires du 2011ème régiment des FARDC lors d’une opération de traque contre les\nmiliciens Kamuina Nsapu. Les auteurs présumés ont indistinctement tiré sur les habitants\nqui vaquaient à leurs activités quotidiennes, qui tentaient de se protéger dans leur case ou\nde prendre la fuite154. Dans le territoire de Dimbelenge, une mission de la MONUSCO\nconduite en octobre 2016 a pu confirmer qu’au moins 57 personnes ont été tuées par des\nFARDC dont : 15 dans le village de Tshinyembe (cinq femmes, cinq hommes, trois\ngarçons et deux filles) le 30 septembre 2016, 13 dans le village de Katanga, deux dans le\nvillage de Lusamba Bumba, 10 dans le village de Tshimanga Mutombo, et enfin 17 dans le\nvillage de Mwamba Mbuyi155.\n2.         Province du Kasaï Oriental"},{"id":"a-hrc-38-crp-1-p0097","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"97","seq":97,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"En octobre 2016, le mouvement Kamuina Nsapu s’est propagé au Kasaï Oriental et en\nparticulier aux territoires de Kabeya-Kamwanga et de Miabi qui bordent le territoire de\nDibaya au Kasaï Central. Un témoin a expliqué que selon lui, c’est la manipulation par les\nautorités politiques du système de reconnaissance des chefs coutumiers, pour des raisons\npolitiques ou économiques liées au marché du diamant, qui aurait favorisé l’arrivée du\nmouvement Kamuina Nsapu au Kasaï Oriental. Certains chefs locaux destitués ont utilisé la\nmilice Kamuina Nsapu afin de tenter de renverser les chefs coutumiers reconnus par les\nautorités156. Selon lui, le mouvement Kamuina Nsapu du Kasaï Oriental n’avait pas de lien\nvéritable avec le mouvement Kamuina Nsapu du Kasaï Central157. Cette affirmation est\nnéanmoins contredite par un témoin direct qui indique que des miliciens Kamuina Nsapu\nrecrutés sur le territoire de Dibaya sont venus combattre avec les miliciens Kamuina Nsapu\nrecrutés sur le territoire de Kabeya-Kamwanga158. Par ailleurs, les miliciens Kamuina\nNsapu du territoire de Kabeya-Kamwanga ont suivi les mêmes pratiques que ceux du\nterritoire de Dibaya : notamment recrutement d’enfants et leur utilisation massive lors\nd’affrontements contre les forces de sécurité et de défense, port de bandeaux rouges,\nutilisation de bâtons lors des combats et érection de barrières sur le territoire159."},{"id":"a-hrc-38-crp-1-p0098","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"98","seq":98,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"L’EEI a en particulier documenté les affrontements entre la milice Kamuina Nsapu et\nles FARDC à Kena Nkuna, territoire de Kabeya-Kamwanga, les 13 et 14 octobre 2016,\nainsi que les opérations menées par les membres des forces de sécurité et de défense contre\nla population civile dans les jours et les semaines suivants ces combats."},{"id":"a-hrc-38-crp-1-p0099","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"99","seq":99,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Le 13 octobre 2016, deux jeunes adultes arborant des bandeaux rouges et tenant des\nbâtons mais sans autre arme ont été abattus par un agent de la PNC et deux FARDC alors\nqu’ils se trouvaient au marché de la cité de Kena Nkuna160. Le lendemain, une centaine de\nmiliciens, hommes, femmes, et une majorité de garçons et filles sont entrés à pied dans la\ncité de Kena Nkuna. Ils étaient habillés en civil avec un bandeau rouge autour de la tête où\nétait accrochée une herbe et ils étaient munis dans leur grande majorité de simples\nbâtons161. Ils se sont dirigés vers l’état-major des FARDC à la recherche des militaires. Ne\nles ayant pas trouvés, ils ont détruit et brûlés les bureaux des FARDC, puis ceux de la\nCENI, de l’administration du territoire et un hôtel qui hébergeait des militaires162."},{"id":"a-hrc-38-crp-1-p0100","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"100","seq":100,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Le même jour, des FARDC sont arrivés dans la cité de Kena Nkuna163. Il y a eu des\naffrontements toute la journée entre les FARDC et les miliciens Kamuina Nsapu faisant de\nnombreux morts parmi les miliciens164. Un premier affrontement a eu lieu devant l’hôtel\nqui hébergeait les militaires au cours duquel une vingtaine de miliciens Kamuina Nsapu ont\nété tués. Leurs corps ont été emportés par les FARDC. Quelques heures plus tard, un\nsecond affrontement a eu lieu sur la route principale, puis un troisième dans l’après-midi.\nDe nombreux miliciens ont été tués et là encore les FARDC ont emporté les corps dans\nleurs véhicules165. Un témoin indique que 11 miliciens Kamuina Nsapu ont été tués lors\nd’affrontements contre les FARDC ce jour-là dans le seul quartier Lubi et que les FARDC\nont emporté les corps166. Deux autres témoins indiquent avoir vu deux miliciens tués par les\nmembres des FARDC167. Au cours d’un de ces affrontements, un PNC est entré dans la\nmaison d’un habitant tuant deux personnes et un enfant et blessant une personne qui se\ntrouvait dans la maison168."},{"id":"a-hrc-38-crp-1-p0101","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"101","seq":101,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Le 15 octobre 2016, les FARDC à la recherche de miliciens ont lancé une opération\n« porte à porte » au cours de laquelle plusieurs civils ont été sommairement exécutés par\ndes FARDC. Par exemple, un témoin indique que son frère et sa nièce de deux ans ont été\ntués par balle ce jour-là169. Un autre que sa voisine a été tuée et enterrée par les FARDC170.\nUn témoin raconte qu’une voisine, sa fille et un autre homme ont également été tués dans\nleur maison par les FARDC au cours de cette opération171. Un homme a par ailleurs\nrapporté que son fils a été tué par balle dans sa maison qui se trouvait dans le quartier du\nmarché172. Suite aux violences dans la cité, plusieurs fosses communes ont été identifiées\npar la population et des corps ont été retrouvés dans des champs et derrière un bar dans le\nquartier de Sthidibula173. Le BCNUDH de la MONUSCO a localisé au moins deux fosses\ncommunes dans la cité de Kena Nkuna174."},{"id":"a-hrc-38-crp-1-p0102","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"102","seq":102,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"De nombreux habitants de la cité ont fui pendant plusieurs jours, semaines ou mois.\nCertains ont fui dans la brousse où des enfants sont morts en raison des conditions de vie175.\nLes FARDC présents dans la cité dans les semaines suivant les combats, ont très largement\npillé ou détruit les biens et les maisons de la population en fuite176. Ils ont également\ncommis d’autres exactions contre la population civile. Par exemple, une quinzaine de\nFARDC se sont présenté au domicile d’une femme à la recherche de son mari. Ce dernier\nétant absent, un FARDC qui lui semblait être le chef lui a demandé si elle préférait être\nviolée ou tuée. Sept FARDC l’ont déshabillée et violée177. Un témoin décrit comment en\nrentrant dans la cité de Kena Nkuna en décembre 2016, des FARDC ont demandé à une\nfamille de se dévêtir pour vérifier qu’ils ne portaient pas de vêtements rouges distinctifs des\nKamuina Nsapu. Un membre de la famille portait une culotte rouge et un FARDC a alors\ntiré et tué l’homme sur place sans lui laisser la possibilité de s’expliquer. Il a été enterré par\nles FARDC dans un puit à l’intérieur d’un restaurant178. Le 26 décembre 2016, plusieurs\npersonnes ont été sommairement exécutées par des FARDC au niveau de l’Eglise\ncatholique et enterrés vers le parking de Kena Nkuna179."},{"id":"a-hrc-38-crp-1-p0103","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"103","seq":103,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"L’EEI est d’avis que les exactions commises par les FARDC contre la population\ncivile de la cité de Kena Nkuna dans les jours et les semaines qui ont suivi les\naffrontements d’octobre 2016 sont représentatives de la situation dans d’autres villages de\nce territoire au cours de la même période. Elle a en particulier reçu des allégations crédibles\nde civils qui auraient été tués par les forces de défense et de sécurité dans le groupement de\nBena Kabukala et dans les villages de Bena Nzemba, Matadi, Lemba Lemba et Mubompa\nqui demandent à être vérifiées180."},{"id":"a-hrc-38-crp-1-p0104","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"104","seq":104,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"En ce qui concerne le territoire de Miabi, les exactions commises par des membres\ndes FARDC dans le village de Mwanza Lomba contre des miliciens Kamuina Nsapu ont\nété largement médiatisées. Le 18 décembre 2016, dans la localité de Bena Tshikasu, village\nMwanza Lomba, des FARDC de la 21ème Région militaire envoyés dans cette localité ont\naffronté des miliciens Kamuina Nsapu. Plusieurs miliciens ont été abattus par les FARDC.\nUn des militaires a par ailleurs filmé ces exécutions. La vidéo montre des soldats ouvrant le\nfeu sur des miliciens munis de bâtons et de couteaux mais sans entendre de coups de feu en\nretour. Lorsque les tirs ont cessé, on peut voir les militaires s’avancer et achever plusieurs\npersonnes au sol, y compris une femme. Les corps de femmes, garçons et hommes tués\nsont visibles sur la vidéo181."},{"id":"a-hrc-38-crp-1-p0105","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"105","seq":105,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"En février 2017, la vidéo de cet incident a été largement diffusée sur les réseaux\nsociaux. Une instruction a alors été ouverte par l’auditorat général. Un procès s’est tenu\ndans la ville de Mbuji-Mayi du 5 juin au 6 juillet 2017 mettant en cause neuf prévenus\n(dont deux en fuite), tous membres de la 21ème région militaire des FARDC. Le 6 juillet\n2017, huit prévenus ont été condamnés pour meurtre, dissipation de munitions de guerre et\noutrage aux bonnes mœurs à des peines allant de 15 ans de servitude pénale à la prison à\nperpétuité. Un prévenu a été acquitté182. Lors du procès, le FARDC qui a filmé a\nindiqué l’avoir fait pour encourager ses collègues qui pensaient que les miliciens étaient\ninvulnérables183. Deux FARDC ont reconnu lors du procès avoir enterré dans une fosse\ncommune située dans un champ de maïs derrière une maison sur la route de Mbuji-Mayi les\ncorps de miliciens Kamuina Nsapu. Le défenseur judiciaire militaire au procès a indiqué\nqu’il est demandé aux troupes de procéder à l’enterrement des cadavres des personnes tuées\nsur le champ de bataille pour raison de salubrité publique et afin d’éviter de démoraliser les\ntroupes qui viennent en renfort184. Le commandant de l’opération, répondant lors du procès\nà la question de savoir qui avait ordonné cette opération a indiqué qu’il s’agissait des\nautorités sans plus de précision. La défense des prévenus a néanmoins insisté sur le fait que\ncette opération avait été planifiée et ordonnée par le commandement de 21ème région\nmilitaire185."},{"id":"a-hrc-38-crp-1-p0106","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"106","seq":106,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"L’EEI a par ailleurs reçu des allégations crédibles selon lesquelles des membres de la\npopulation civile auraient été tués par les forces de défense et de sécurité sur le territoire de\nMiabi, en particulier dans les villages de Katinde et de Miteka, qui demandent à être\nvérifiées186.\n3.         Province du Kasaï"},{"id":"a-hrc-38-crp-1-p0107","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"107","seq":107,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Fin novembre/début décembre 2016, la vague de violence liée à la milice Kamuina\nNsapu atteint l’axe routier Kananga-Tshikapa, dans le territoire de Kamonia, province du\nKasaï. C’est un conflit de pouvoir coutumier entre le chef coutumier du Groupement de\nMbawu, dont le statut a été reconnu par les autorités, et son oncle qui se considérait comme\nle chef coutumier légitime du groupement qui a favorisé le déploiement de la milice\nKamuina Nsapu dans cette zone de la province du Kasaï187. Un témoin explique que\nl’homme qui se considérait comme le chef coutumier légitime du groupement de Mbawu\nmais n’avait pas obtenu de reconnaissance, s’est rendu dans la province du Kasaï Central\nafin de rapporter des fétiches Kamuina Nsapu et bénéficier ainsi de ses pouvoirs\nmystiques188. La famille Mbawu appartient au clan des Bashila Kasanga dont la famille du\nchef coutumier Kamuina Nsapu fait également partie189."},{"id":"a-hrc-38-crp-1-p0108","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"108","seq":108,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Un tshiota a été installé autour du 22 novembre 2016 dans le groupement de Mbawu\net de nombreux chefs de villages appartenant à ce groupement ont adhéré au mouvement\nKamuina Nsapu190. Les chefs de village du groupement de Mbawu ou de groupements\nenvironnants qui ont refusé de prêter allégeance au chef Mbawu et de recruter au sein de\nleur population pour les rangs de la milice Kamuina Nsapu ont été menacés et certains ont\nvu leur maison brûlée ou ont été décapités. Ainsi au moins quatre chefs coutumiers ont été\ntués par des miliciens Kamuina Nsapu. Plusieurs chefs coutumiers craignant pour leur vie\nont fui191."},{"id":"a-hrc-38-crp-1-p0109","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"109","seq":109,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Suivant le même schéma de recrutement au sein de la milice qu’au Kasaï Central, des\nenfants ont été recrutés par force ou par ruse au sein de la milice après avoir suivi le rituel\ndu baptême192. Un témoin raconte que le 27 novembre 2016, il a vu une foule immense\nd’hommes, de femmes et d’enfants au tshiota installé dans le groupement de Mbawu193. La\nMONUSCO a documenté 14 cas de recrutement et d’utilisation d’enfants par les Kamuina\nNsapu dans le territoire de Kamonia principalement dans les localités de Mbawu et de\nKabeya-Lumbu aux alentours du 15 décembre 2016. Les enfants étaient âgés de 8 à 17\nans194. Par ailleurs, un témoin mineur a raconté à l’EEI son recrutement par la force dans la\nmilice dans le village de Kabambaie, secteur de Kasaï-Kabambaie à la frontière du\nterritoire de Luebo, en décembre 2016. Neuf enfants miliciens Kamuina Nsapu l’ont\ncapturé avec 11 filles et 8 garçons dont l’âge variait entre 16 et 18 ans. Les miliciens l’ont\namené au tshiota et lui ont demandé de se soumettre au rituel du baptême. Ayant refusé, il\nfût assigné aux corvées. Pendant qu’il se trouvait avec les miliciens, ces derniers ont\nrapporté des cuisses humaines et des bidons de sang humain que le témoin a dû cuisiner. Il\na par ailleurs assisté au meurtre par décapitation au tshiota de sept personnes, six hommes\net une femme, fonctionnaires de l’Etat195. Au regard des informations collectées et en\nparticulier du nombre d’enfants qui ont participé à l’attaque de la ville Tshikapa, l’EEI\nestime que des centaines d’enfants ont été recrutés au cours du mois de décembre 2016\ndans cette partie du territoire de Kamonia."},{"id":"a-hrc-38-crp-1-p0110","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"110","seq":110,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Le premier incident entre les miliciens Kamuina Nsapu et les forces de sécurité et de\ndéfense sur le territoire de Kamonia s’est déroulé le 28 novembre 2016. Ce jour-là, deux\npoliciers ont été tués par les miliciens Kamuina Nsapu dans le groupement de Mbawu196.\nDans les jours qui suivirent, plusieurs incidents entre les représentants de l’autorité\npublique ou les forces de sécurité et de défense et les miliciens Kamuina Nsapu sont\nrapportés au cours desquels plusieurs éléments de la PNC ont perdu la vie197. Les 4 et 5\ndécembre 2016, de nombreux miliciens Kamuina Nsapu, dont des enfants entre 10 et 15\nans et des petites filles nommées « ya mama », sont entrées dans la ville de Tshikapa. Les\nmiliciens venaient du groupement de Mbawu et du village Kabeya Lumbu198. Des\naffrontements au niveau du pont Kasaï, dans le quartier de Kele et au niveau de l’aéroport\nde Tshikapa ont eu lieu entre les miliciens et forces de défense et de sécurité199. D’après les\nconclusions d’une mission de la MONUSCO, des renforts étaient arrivés de Kinshasa, dans\nles jours précédents permettant de reprendre rapidement le contrôle de la situation dans la\nville et de repousser les miliciens Kamuina Nsapu200. L’EEI n’a pas été en mesure de\nconfirmer le bilan de ces affrontements. Le bilan dressé par le gouverneur-adjoint de la\nprovince du Kasaï fait état de 31 personnes tuées dont 13 membres des forces de sécurité et\nde défense et 18 miliciens Kamuina Nsapu, ainsi qu’au moins 16 miliciens Kamuina Nsapu\narrêtés et 14 soldats blessés. Les chiffres assemblés par l’Eglise catholique sont d’une\ncentaine de morts201."},{"id":"a-hrc-38-crp-1-p0111","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"111","seq":111,"section":"B. Septembre-décembre 2016 – le mouvement Kamuina Nsapu s’étend","text":"Suite à l’attaque de Tshikapa, les FARDC ont conduit des opérations de traque des\nmiliciens dans les villages du groupement de Mbawu et dans des villages proches de l’axe\nKananga-Tshikapa. Lors de ces opérations, de nombreuses exactions ont été commises\ncontre la population civile202. L’EEI a documenté l’attaque par des membres des FARDC\ndu village de Tshitadi, groupement de Mbawu, le 6 décembre 2016, qu’elle considère\nreprésentative du mode opératoire des FARDC lors de ces opérations. Ce jour-là, des\nFARDC sont arrivés en grand nombre de Tshikapa dans le village de Tshitadi. Les FARDC\navaient des armes automatiques et des lance-roquettes. Selon les témoins, il n’y avait pas\nde miliciens Kamuina Nsapu dans le village au moment de l’attaque conduite par les\nFARDC. De nombreuses maisons ainsi que l’école ont été brûlées203. Des témoins\nracontent la mort par arme à feu de membres de leur famille le jour de l’attaque204. Un\ntémoin raconte qu’à son retour après trois jours de fuite, il a vu au moins trente cadavres\ndont des cadavres d’enfants dont trois qui étaient très jeunes ainsi que de femmes, dont\nl’une enceinte qui avait été éventrée avec son fœtus à ses côtés. D’autres se trouvaient dans\ndeux puits205. L’EEI a par ailleurs reçu des allégations crédibles d’opérations similaires\ndans les villages de Fuamba, Mbawu et Kabeya Lumbu au cours desquelles de nombreux\ncivils auraient perdu la vie206."},{"id":"a-hrc-38-crp-1-p0112","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"112","seq":112,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De janvier à juillet 2017, la milice Kamuina Nsapu a continué de progresser pour\natteindre toutes les provinces du Kasaï207. Poursuivant sa stratégie expansionniste, la milice\nKamuina Nsapu s’est installée ou a attaqué des centaines de villages, cités et villes du\nKasaï. Les exactions commises par la milice Kamuina Nsapu ont visé de plus en plus\nfréquemment les populations civiles s’éloignant de sa stratégie d’attaques contre les\nsymboles de l’autorité étatique. Le niveau de violence de la milice Kamuina Nsapu entre\njanvier et juillet 2017 est exponentiel, en particulier dès qu’elle se déploie dans des zones\noù la population non-lubaphone est importante et/ou devient majoritaire. Par ailleurs, à\npartir de mars 2017, avec l’arrivée de la milice Kamuina Nsapu dans les zones\nmajoritairement non-lubaphones et avec l’apparition des milices Bana Mura, les actes de\nviolence ont pris une nature ethnique prononcée dans le territoire de Kamonia, province du\nKasaï."},{"id":"a-hrc-38-crp-1-p0113","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"113","seq":113,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Fin décembre 2016, avec l’envoi de renforts pour endiguer l’expansion de la milice\nKamuina Nsapu, le nombre de militaires déployés au Kasaï atteignait 7 000. Le 9 mars\n2017, le Gouvernement crée le Secteur opérationnel du Grand Kasaï avec un\ncommandement basé à Kananga. La réaction des forces de défense et de sécurité, en\nparticulier des FARDC, face à la milice Kamuina Nsapu a continué à être brutale. Au cours\nd’affrontements, les forces de défense et de sécurité ont fait usage d’armes à feu et parfois\nde lance-roquettes contre des miliciens Kamuina Nsapu, souvent des enfants non-armés ou\nen possession de simples bâtons. Par ailleurs, les forces de défense et de sécurité ont\nrarement fait preuve de distinction entre les miliciens et la population. De nombreux\nmembres de la population civile ont été blessés ou tués à proximité des lieux\nd’affrontement ou lors d’opérations de traque des miliciens menées par les FARDC. Une\nfois les opérations militaires terminées, les FARDC ont très fréquemment commis des viols\net autres violences sexuelles, détruits des maisons ou des villages, des pillages dans les\nvillages dans lesquels ils étaient intervenus.\n1.         Province du Kasaï Central"},{"id":"a-hrc-38-crp-1-p0114","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"114","seq":114,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Point de départ des violences en 2016, le Kasaï Central n’a pas été épargné en 2017.\nLes cinq provinces du Kasaï ainsi que la ville de Kananga ont connu de multiples épisodes\nde violences entre janvier et juillet 2017. L’EEI a concentré ses enquêtes sur le territoire de\nDibaya, la ville de Kananga, le territoire de Luiza et a documenté quelques incidents isolés\ndans le territoire de Kazumba.\na.   Territoire de Dibaya"},{"id":"a-hrc-38-crp-1-p0115","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"115","seq":115,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Dans le territoire de Dibaya, par rapport à 2016, les actes de violence se sont amplifiés\nentre janvier et mai 2017. La milice Kamuina Nsapu y a été extrêmement active,\nnotamment grâce au soutien de nombreux chefs coutumiers acquis à la cause du\nmouvement Kamuina Nsapu, souvent depuis sa création208. De multiples tshiota ont été\ninstallés, notamment dans les villages de Kabudi, Kabeya-Madi, Moyo Musuila, Kazadi,\nLubondaye, Kawulu et Bena-Kena209."},{"id":"a-hrc-38-crp-1-p0116","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"116","seq":116,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les miliciens Kamuina Nsapu ont continué à s’attaquer aux agents de l’Etat et aux\npersonnes considérées comme des traitres, tuant, par exemple, au moins un élément de la\nPNC, un homme de Dibaya et un pasteur accusé de collaborer avec les FARDC à\nLumudi210. Dans les tous premiers jours de janvier 2017, les miliciens Kamuina Nsapu ont\nfait une incursion dans le village de Bukonde décapitant au moins deux habitants du village\navant de mutiler leur cadavre211. Au moins une personne soupçonnée de coopérer avec les\nmilitaires a aussi été violemment battue par des miliciens Kamuina Nsapu a Bukonde en\nmars 2017212 Entre janvier et mars 2017, plusieurs chefs coutumiers ou membres de leurs\nfamilles ont été tués et/ou décapités pour avoir refusé d’adhérer au mouvement Kamuina\nNsapu213. Au mois de mai 2017, une fille de 17 ans a été violée par un milicien Kamuina\nNsapu dans le village de Bena Kobi214."},{"id":"a-hrc-38-crp-1-p0117","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"117","seq":117,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"La milice Kamuina Nsapu a continué à recruter massivement les enfants vivant sur le\nterritoire de Dibaya. Par exemple, après l’installation d’un tshiota au village de Bena-Kena,\nles miliciens Kamuina Nsapu ont recruté une centaine de filles et garçons du village dans\nles rangs de la milice. Trois hommes et un garçon de 17 ans qui avaient refusé le baptême\nont été tués215. Dans le village Lubondaye, au moins 100 personnes, majoritairement des\ngarçons et des filles entre 8 et 17 ans, ont été recrutées. De nombreux enfants ont\négalement été recrutés dans la milice dans les villages de Kabeya-Madi et de Dibaya et au\nmoins un homme de 19 ans et un garçon de 17 ans ont été tués accusés de traitrise216. La\nMONUSCO a documenté les cas de 40 filles et 247 garçons recrutés par la milice Kamuina\nNsapu au premier semestre 2017. Certains ont été enlevés avant d’être formellement\nrecrutés suite au baptême. Les deux principales vagues de recrutements ont eu lieu entre\njanvier et mars 2017 dans le territoire de Dibaya dans le but d’attaquer la ville de\nTshimbulu puis, et dans la ville de Kananga et sa commune de Nganza. Des enfants ont\nraconté qu’au moment de leur recrutement, 34 filles et 36 garçons avaient également été\nenrôlés. Un autre déclare qu’il a été recruté avec 4 filles et 56 garçons. Les enfants étaient\nâgés entre 8 et 17 ans et presque tous ont déclaré qu’ils avaient été recrutés dans le but\nd’affronter les FARDC217."},{"id":"a-hrc-38-crp-1-p0118","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"118","seq":118,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI a en particulier documenté plusieurs affrontements très violents qui se sont\ndéroulés dans la cité de Tshimbulu. Le 4 janvier 2017, les miliciens Kamuina Nsapu ont\nfait une incursion dans la cité au cours de laquelle ils ont pillé la résidence du Colonel de la\nPNC et détruit le poste de police218. Un PNC qui avait tué un milicien a été battu et a eu sa\nmain coupée par les miliciens Kamuina Nsapu. Ces derniers l’ont ensuite transporté\nagonisant jusqu’à la route principale où il est décédé219. Le soir même, plusieurs camions\navec des FARDC à leur bord sont arrivés à Tshimbulu220. Le lendemain, les miliciens\nKamuina Nsapu, dont de nombreux enfants, ont fait une seconde incursion dans la cité. Des\naffrontements se sont déroulés devant la cathédrale le long de la route vers Bukonde. En\npremière ligne se trouvait une milicienne d’une vingtaine d’années qui portait une jupe et\nun bandeau rouge autour de la tête. Les miliciens avaient des bâtons en forme de fusils, des\nfusils de chasse et des machettes221. Des miliciens, dont des filles et des garçons, ont été\ntués par balles et par des tirs de lance-roquettes. Le corps de la milicienne qui se trouvait en\npremière ligne a été déchiqueté par des éclats suite au tir d’un lance-roquette222. Les\nmilitaires tiraient sur les enfants munis de bâtons alors même qu’ils fuyaient et les enfants\nblessés au sol étaient achevés par les militaires223. Le bilan fait état d’environ 20 miliciens\net d’un FARDC tués ce jour-là224. De plus, alors que les miliciens s’enfuyaient, les FARDC\nles ont poursuivis dans la cité tout en continuant de tirer. Les militaires ont tiré en rafale sur\nles habitations blessant par balle au moins une femme et tuant un garçon de moins de deux\nans225. Suite aux affrontements, les FARDC ont fouillé les maisons engendrant un\nmouvement de fuite de la population. Dans sa fuite une jeune femme a été blessée par balle\npar un militaire et est ensuite décédée à l’hôpital226. Au moins un homme, une femme et un\nenfant ont également été tués par les balles des FARDC et on dénombre d’autres blessés227."},{"id":"a-hrc-38-crp-1-p0119","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"119","seq":119,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le 9 février 2017, un groupe de 13 à 15 miliciens Kamuina Nsapu, munis de bâtons et\nde fusils de chasse ont fait une nouvelle incursion dans la cité de Tshimbulu et au moins six\nmiliciens ont été tués dans des affrontements avec les FARDC228. Le lendemain, les\nmiliciens Kamuina Nsapu sont revenus en grand nombre, plusieurs centaines. Lors des\naffrontements entre les miliciens Kamuina Nsapu et les FARDC au cours desquels les\nFARDC ont fait usage de lance-roquettes, environ100 miliciens ont trouvé la mort.\nCertains d’entre eux ont été tués alors qu’ils fuyaient et des blessés ont été achevés par les\nFARDC229. Un témoin explique avoir entendu le bruit de six tirs de roquettes ce jour-là230.\nLes corps ont été enterrés dans des fosses communes par des éléments de la PNC et des\nFARDC231. Par ailleurs, les corps de certains miliciens Kamuina Nsapu, dont ceux\nd’enfants ont été exposés publiquement afin que les habitants puissent observer que les\nmiliciens n’étaient pas invulnérables232. D’autres affrontements ont encore eu lieu au cours\ndu mois de mars 2017 à Tshimbulu. Un affrontement mi-mars aurait fait 28 morts parmi les\nmiliciens dont des enfants233. Un témoin indique avoir fui le village lors de cet affrontement\net avoir perdu toute trace depuis lors de deux de ses enfants de huit et dix ans qui auraient\nselon lui été tués par des balles perdues des FARDC234. Lors d’un ultime affrontement fin\nmars 2017, six à huit miliciens Kamuina Nsapu auraient été tués. Les témoins indiquent\nque la présence de la MONUSCO qui venait de se déployer aurait dissuadé les FARDC\nd’utiliser des lance-roquettes lors de cet affrontement235. Par ailleurs, une fille de 16 ans a\nété retenue contre son gré pendant trois jours par un élément des FARDC qui l’a agressée\nsexuellement et violée plusieurs fois par jour en mars 2017, période où les FARDC se\ntrouvaient à Tshimbulu236."},{"id":"a-hrc-38-crp-1-p0120","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"120","seq":120,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Ayant réussi à empêcher les miliciens d’entrer dans la cité de Tshimbulu, les FARDC\nont entrepris des opérations militaires dans plusieurs villages du territoire de Dibaya, en\nparticulier dans les villages où des tshiota étaient installés. Ces opérations ont été\nparticulièrement violentes. L’EEI a documenté l’arrivée des FARDC dans les villages de\nDibaya, Kabeya-Madi, Bena-Kalegna, Kazadi, Kawulu et Bukonde237. Les FARDC,\nnotamment ceux non-originaires du Kasaï, faisaient rarement la distinction entre les\nmiliciens et les habitants des villages considérés comme favorables au mouvement238."},{"id":"a-hrc-38-crp-1-p0121","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"121","seq":121,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Par exemple, début avril 2017, des affrontements entre les FARDC et les miliciens ont\neu lieu dans les villages de Dibaya et de Kabeya-Madi239. Le bilan de ces combats n’est pas\nétabli précisément mais il y a eu des morts parmi les miliciens, dont des enfants240. Le 1er\navril 2017, l’hôpital de Dibaya a traité 36 cas de blessures par balle, dont 10 filles et huit\ngarçons et 18 adultes âgés de 18 à 26 ans dont une femme ; les victimes étaient originaires\nde Kabeya-Madi ou des villages environnants de Dibaya241. De nombreux habitants du\nvillage de Bena Kalegna, dont le chef du village, avaient fui le village à l’arrivée de la\nmilice Kamuina Nsapu en mars 2017. A l’arrivée des FARDC, le chef de village est\nretourné au village et a été tué par les FARDC avec d’autres hommes et enfants qui\nl’accompagnaient. Un témoin indique avoir ainsi perdu trois membres de sa famille. Des\naffrontements durant lesquels des miliciens et un FARDC ont perdu la vie ont également eu\nlieu242."},{"id":"a-hrc-38-crp-1-p0122","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"122","seq":122,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Dans le village de Kazadi où les miliciens s’étaient installés, des FARDC sont arrivés\nà bord de deux camions en mars-avril 2017. Il y a eu un affrontement entre les FARDC et\ndes miliciens, dont des femmes, des filles et des garçons, munis des petits bâtons et de\nmachettes ; cet affrontement a duré toute la matinée. Puis, les FARDC sont partis vers le\nvillage voisin. Un témoin explique avoir vu six corps d’enfants du village, qui n’étaient pas\ndes miliciens, tués par balle. Un autre témoin précise avoir vu une dizaine de corps autour\nde sa maison. Certains corps ont été emportés par les FARDC. Un civil a également été tué\nsur la route par les FARDC qui quittaient le village243. En mars 2017, toujours à bord de\ndeux camions, les FARDC sont arrivés en provenance de Tshimbulu dans le village de\nKawulu, où les miliciens Kamuina Nsapu avaient installé un tshiota. Des miliciens mais\naussi des habitants, dont des garçons, ont été tués alors qu’ils fuyaient et que les militaires\ntiraient dans toutes les directions. Le nombre de personnes tuées n’a pas pu être déterminé\ncar les FARDC ont emporté les cadavres qu’ils ont ensuite enterrés sommairement dans\nune fosse commune à la sortie du village244. Des opérations militaires suivant un mode\nopératoire similaire ont eu lieu dans les villages de Ludi, Bena-Kena, Lubondaye, Muan-\nMukaya et de Lumbudi245."},{"id":"a-hrc-38-crp-1-p0123","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"123","seq":123,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Il y a également eu plusieurs affrontements entre les miliciens Kamuina Nsapu et les\nFARDC dans le village de Bukonde. Un témoin indique qu’il y a eu au total 13\naffrontements à Bukonde246. Un autre raconte que début janvier 2017 après des\naffrontements, il a vu les cadavres de huit miliciens dont des enfants, tués par les FARDC\net deux blessés247. Un autre témoin estime qu’environ 80 personnes ont été tuées à Bukonde\nentre décembre 2016 et mars 2017 dont la moitié était des enfants248. Le plus gros incident\ndocumenté a eu lieu vers le 8 mars 2017. Des miliciens Kamuina Nsapu, environ une\ncentaine, dont des femmes et des filles et des garçons, sont arrivés à Bukonde et ont\naffrontés les FARDC au niveau de l’hôpital249. Les corps de miliciens ont ensuite été\nenterrés derrière l’église de Bukonde250. Un témoin qui a assisté à cet affrontement estime\nqu’au moins 50 miliciens et un militaire ont perdu la vie251. Un homme qui sortait de sa\nmaison a été tué par des militaires par arme à feu et machettes et un autre a été blessé par\nballe alors qu’il se trouvait dans une maison en construction dans laquelle des FARDC\nétaient entrés 252."},{"id":"a-hrc-38-crp-1-p0124","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"124","seq":124,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Dans ces villages du territoire de Dibaya, des militaires ont pillé les biens des\nhabitants en fuite et brûlé plusieurs maisons253. Par ailleurs, des cas de viols commis par les\nFARDC ont été documentés et des allégations de viols par les FARDC dans le village de\nLubi ont été rapportées254. Dans ce même village, une fille de 17 ans a été enlevée par les\nFARDC à la fin de leur mission255. Au moins une femme a été violée par des FARDC dans\nle village de Lubandayi et emmenée par les FARDC à leur départ du village256. Dans le\nvillage de Bakwa Ndaya, après être entré dans la maison, deux militaires ont brutalisé une\nfemme et menacé son mari avec une arme à feu. L’un des militaires a menacé la femme\navec son arme et l’a maintenue au sol par le cou avant de la violer257. Un autre témoin\nraconte qu’alors qu’elle s’était enfuie dans la brousse autour du village de Bena Kalegna\navec sept autres femmes, une dizaine de FARDC ont découvert leur cachette et les ont\nviolées. L’une d’entre elle a été violée par deux éléments FARDC qui lui ont arraché ses\nvêtements et l’ont forcé à s’allonger sous la menace d’une arme258. Lors de ce même\nincident, une autre femme a été violée par trois éléments FARDC suivant le même mode\nopératoire ; elle a fait une fausse couche suite à ce viol259."},{"id":"a-hrc-38-crp-1-p0125","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"125","seq":125,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Deux membres du Groupe d’experts sur la République démocratique du Congo créé\nen application de la résolution 1533 (2004) du Conseil de sécurité, la suédo-chilienne Zaida\nCatalán et l’américain Michael Sharp, ont été tués le 12 mars 2017 sur le territoire de\nDibaya. A ce jour, leurs quatre accompagnateurs sont toujours portés disparus260. Les\nexperts et leurs accompagnateurs sont partis de Kananga le matin du 12 mars 2017 sur trois\nmotos en direction de la zone de Bukonde, territoire de Dibaya, où il y avait eu des\naffrontements récents entre la milice Kamuina Nsapu et les FARDC. Les cadavres des deux\nexperts ont été retrouvés deux semaines plus tard dans une tombe peu profonde non loin du\nvillage du Bukonde261. Le corps de Zaida Catalán a été décapité. Des informations\ncollectées et analysées, notamment par les journalistes de Radio France Internationale et de\nReuters262, indiquent que le déplacement des experts vers Bukonde a été planifié avec l’aide\nde certaines personnes qui auraient eu des liens avec l’ANR. Une vidéo du meurtre des\ndeux experts montre des jeunes, arborant des bandereaux rouges, typiques de la milice\nKamuina Nsapu, qui tuent les experts avec ce qui semblerait être un fusil de chasse.\nNéanmoins, une analyse de la vidéo sème le doute sur le point de savoir si les auteurs du\ncrime sont réellement des miliciens Kamuina Nsapu car ils semblent difficilement maitriser\nla langue Tshiluba, langue commune des Lubas qui constituaient exclusivement la milice\nKamuina Nsapu sur ce territoire263. Une procédure judiciaire est en cours, assistée par une\néquipe technique des Nations Unies chargée d’aider la justice militaire afin que les\npersonnes responsables soient traduites en justice264.\nb.   Ville de Kananga"},{"id":"a-hrc-38-crp-1-p0126","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"126","seq":126,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Entre janvier et avril 2017, la milice Kamuina Nsapu a été active dans la cité de\nKananga et les incidents sécuritaires entre les miliciens Kamuina Nsapu et les forces de\ndéfense et de sécurité ont été nombreux. Au moins quatre tshiota avaient été installés à\nKananga : un près du grand séminaire de Malole et trois dans la commune Nganza qui était\nconsidéré comme le fief des miliciens dans la ville265. De nombreux enfants ont été recrutés\ndans les rangs de la milice dans la commune de Nganza ainsi qu’au tshiota près du grand\nséminaire de Malole266."},{"id":"a-hrc-38-crp-1-p0127","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"127","seq":127,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De nombreux actes de violence commis dans la ville Kananga entre janvier et avril\n2017, et qui n’ont pu tous être confirmés, ont été rapportés à l’EEI267. Certaines de ces\nallégations concernent des exactions commises par la milice Kamuina Nsapu, tels que des\ndécapitations, des viols et des pillages. D’autres actes de violence concernent les forces de\ndéfense et de sécurité qui, au cours d’affrontements avec les miliciens dans la ville ou lors\nd’opérations de traque des miliciens, ont exécuté sommairement des personnes ou fait subir\nde mauvais traitements à des habitants de la ville de Kananga."},{"id":"a-hrc-38-crp-1-p0128","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"128","seq":128,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI a documenté deux incidents particulièrement sérieux, qui se sont déroulés les\n14-15 mars 2017 et les 28-30 mars 2017 dans la commune de Nganza, dont la\nresponsabilité incombe aux forces de défense et de sécurité, en particulier aux FARDC.\nDans la nuit du 14 au 15 mars 2017, les FARDC ont lancé une attaque planifiée sur les trois\ntshiota de la commune de Nganza où dormaient des centaines (environ 200 par tshiota) de\nmiliciens Kamuina Nsapu, en majorité des enfants268. Les FARDC ont ouvert le feu et fait\nusage de lance-roquettes contre les miliciens Kamuina Nsapu pendant leur sommeil269. Les\nmilitaires ont ensuite achevé des enfants blessés, parfois à l’arme blanche270. Les FARDC\nont entassé la plupart des cadavres dans des camions avant des emporter rendant le nombre\nde victimes difficile à déterminer271. Des témoins estiment qu’entre 40 et 100 miliciens\nauraient perdu la vie à l’un des trois tshiota272."},{"id":"a-hrc-38-crp-1-p0129","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"129","seq":129,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Dans les jours précédents, le 28-30 mars 2017, des tentatives de désarmement des\nmiliciens Kamuina Nsapu avaient été mises en œuvre par les autorités provinciales mais\ncelles-ci avaient échoué. Suite à cet échec et à des affrontements dans la ville entre les\nmiliciens Kamuina Nsapu et les forces de défense et de sécurité, ces dernières ont lancé, le\n28 mars 2017, une opération « porte à porte » à Nganza273. L’opération a duré plusieurs\njours274. Les forces de défense et de sécurité sont entrées dans les maisons des habitants de\nla commune de Nganza, et ont tiré indistinctement sur des hommes, des femmes et des\nenfants de tout âge en raison de leur sympathie supposée avec le mouvement Kamuina\nNsapu275. Des enfants ont été abattus dans leur sommeil. Cette nuit-là pendant cette\nopération des FARDC dans la commune de Nganza, la MONUSCO a pu confirmer le\nmeurtre d’au moins 27 garçons et 19 filles dont des bébés âgés de quelques mois abattus\ndans leur sommeil276."},{"id":"a-hrc-38-crp-1-p0130","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"130","seq":130,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Par exemple, un témoin raconte que son frère a été sommairement exécuté par des\nFARDC lorsqu’ils ont entrés dans sa chambre et que lui n’a eu la vie sauve que parce qu’il\nportait un teeshirt de la campagne électorale du parti au pouvoir277. Un autre raconte qu’une\nfamille entière de sept personnes a été tuée278. Un autre témoin a perdu sa petite fille de 3\nans, son fils de 28 ans et sa belle-fille de 20 ans au cours de cette opération279. Un autre\nexplique, « avant le 28 mars 2017, les miliciens sortaient de la brousse aux alentours de\nNganza, affrontaient […] les FARDC et retournaient dans la brousse autour de leurs\ntshiota. Il y avait toujours des morts de part et d’autre, mais la population était épargnée. Le\n28 mars 2017, ce n’était pas la bataille habituelle. C’était différent des autres jours. Les\nautres jours, la population se cachait dans les maisons, pendant les affrontements entre\nmiliciens et militaires des FARDC et après les gens sortaient […] les affrontements […]\nfinis. […] Les affrontements entre miliciens et militaires ont commencé le mardi 28 mars\n2017, vers 8 heures, dans les quartiers de la commune de Nganza. Je m’étais caché dans ma\nmaison, dans le quartier de Nganza nord, afin d’éviter les balles, parce que ça tirait de\npartout. Les militaires se sont livrés à une tuerie dans la commune de Nganza, en s’en\nprenant directement à la population. Ils détruisaient les portes, entraient dans les maisons et\ntuaient les occupants de ces habitations. Ils ont fait des carnages. Les survivants fuyaient\ndans la brousse, pour ceux qui pouvaient » 280. Par ailleurs, le personnel d’un hôpital de la\ncommune de Nganza a soigné ce jour-là, au moins une trentaine de personnes, toutes\nblessées par balles, dont un enfant de trois ans. Sur les trente personnes reçues, deux\ngarçons sont décédés281."},{"id":"a-hrc-38-crp-1-p0131","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"131","seq":131,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les militaires ont ensuite ramassé certains corps, parfois jusque dans les maisons282.\nDes corps ont été enterrés par des habitants dans des fosses communes et d’autres ont été\ntransportés par camion par les FARDC pour être enterrés dans des fosses communes et vers\nl’EFO283. Un témoin a identifié 51 personnes qui auraient été tuées, mais ce nombre ne\ncomptabilise pas les personnes venues d’ailleurs284. Un autre qui a participé au ramassage\ndes corps dans le quartier de Nganza Nord a comptabilisé au moins 50 personnes tuées de\ntous âges, y compris des bébés et des femmes enceintes285. La MONUSCO a également\ndocumenté le cas du viol d’une fille de 12 ans par les FARDC la nuit du 28 mars 2017286."},{"id":"a-hrc-38-crp-1-p0132","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"132","seq":132,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’ampleur de l’opération « porte à porte » et la manière dont elle a été conduite\nsuggèrent qu’il s’agissait d’une opération punitive contre la population de la commune de\nNganza, foyer des miliciens Kamuina Nsapu dans la ville de Kananga, et d’un moyen\nbrutal pour les forces de défense et de sécurité de mettre un terme aux activés de la milice\ndans la ville. L’ampleur de cette opération qui a duré plusieurs jours, laisse également\npenser que les autorités militaires de la Zone Opérationnelle du Grand Kasaï basées à\nKananga, mais aussi certaines autorités politiques provinciales voire nationales, ne\npouvaient ignorer ni l’ampleur, ni le but de l’opération. Il est également difficile de\nconcevoir qu’une telle opération ait pu être conduite sans autorisation préalable."},{"id":"a-hrc-38-crp-1-p0133","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"133","seq":133,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI estime que plusieurs centaines de personnes ont perdu la vie au cours des deux\nopérations conduites par les forces de défense et de sécurité dans la commune de Nganza.\nL’Eglise catholique estime qu’une centaine de personnes ont été tuées lors de l’opération\ndu 14-15 mars 2017 et environ 300 personnes lors de celle du 28-30 mars287. Le BCNUDH\nde la MONUSCO a pu confirmer la mort d’au moins 39 personnes, dont au moins 11\nenfants, dans la nuit du 14 au 15 mars 2016 et d’au moins 50 personnes les 28-30 mars\n2018288.\nc.   Territoire de Kazumba"},{"id":"a-hrc-38-crp-1-p0134","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"134","seq":134,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"D’après les informations collectées auprès de sources secondaires, la milice Kamuina\nNsapu a été particulièrement active sur le territoire de Kazumba289. Un tshiota important\nétait notamment installé chez le chef du village de Tshikulu290 et les miliciens Kamuina\nNsapu du territoire de Kazumba ont été parmi les plus expansionnistes. Ainsi des miliciens\nde ce territoire se sont déplacés sur le territoire de Luiza, mais aussi sur les territoires de\nLuebo et de Kamonia dans la Province du Kasaï291. Les incidents isolés que l’EEI a été en\nmesure de documenter sur le territoire de Kazumba, pendant son mandat, ne sont, de l’avis\nde l’EEI, pas représentatifs des exactions qui ont été commises contre la population civile\npar les miliciens Kamuina Nsapu et par les forces de défense et de sécurité entre janvier et\njuin 2017 et considère que des enquêtes plus approfondies sont nécessaires."},{"id":"a-hrc-38-crp-1-p0135","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"135","seq":135,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le 11 mars 2017, des miliciens Kamuina Nsapu, dont des enfants, ont attaqué six\npères catholiques à la Maison de formation de Notre-Dame du Kasaï, colline de Malandji,\naccusant les ecclésiastiques d’avoir caché des militaires. Après avoir pillé certains biens,\nles miliciens ont amené les six pères à leur tshiota qui se trouvait à une douzaine de\nkilomètres dans le village de Nsanga Nyembe. Les miliciens Kamuina Nsapu les ont alors\nforcés à se déshabiller dans le but de les décapiter. Finalement, tous ont été libérés après\nque cinq d’entre eux ont chacun reçu10 coups avec la partie plate de la lame d’une\nmachette sur la plante des pieds292. La vieille, le menuisier du Sanctuaire de Notre Dame du\nKasaï avait également été attaqué par des miliciens Kamuina Nsapu. Ses cinq enfants, âgés\nde 2 ans à 17 ans, ont été battus par les miliciens et certains de ses biens pillés. Là encore,\nle menuisier a été déplacé au tshiota et menacé de mort. Il a ensuite été ligoté, battu et a eu\nla main droite coupée par deux coups de machette293."},{"id":"a-hrc-38-crp-1-p0136","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"136","seq":136,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Dans le cadre de l’organisation de l’examen d’Etat, plusieurs délégations\nd’inspecteurs de l’éducation nationale avaient été déployées au Kasaï, notamment dans le\nterritoire de Kazumba, fin avril 2017. Au moins deux d’entre elles ont été attaquées par les\nmiliciens Kamuina Nsapu. Les membres de l’une de ces délégations ont été arrêtés,\nmaltraités et extorqués à plusieurs reprises par des miliciens Kamuina Nsapu provenant des\nalentours du village de Tshikulu et le chef de mission a été blessé à la cuisse294. Par ailleurs,\nprès du village de Kazumba, trois inspecteurs et trois inspectrices ont été stoppés par des\nmiliciens Kamuina Nsapu et ne sont jamais rentrés de leur mission. Leurs familles ont\nperdu toute trace d’eux le 30 avril 2017295."},{"id":"a-hrc-38-crp-1-p0137","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"137","seq":137,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le BCNUDH de la MONUSCO a également documenté un incident qui s’est déroulé\nle 7 mai 2017 au marché du village de Tshikulu, dans le territoire de Kazumba. D’après les\ntémoignages recueillis par le BCNUDH de la MONUSCO, des FARDC sont arrivés vers\n14 heures ce jour-là à Tshikulu à bord d’au moins quatre véhicules de transport de troupe.\nLes militaires ont d’abord tiré en l’air à l’entrée de la localité puis, étant parvenus à la place\ndu marché, ils ont visé indistinctement les marchands et les clients qui s’y trouvaient, avant\nd’emporter une importante quantité de marchandises, de l’argent et de continuer leur route\nvers Kananga. Au terme des différents entretiens et visites des sites, le BCNUDH de la\nMONUSCO a pu confirmer les exécutions sommaires d’au moins 60 adultes et 19 enfants,\ndes atteintes à l’intégrité physique par des blessures par balle à l’encontre de 17 adultes et 5\nenfants ainsi que le viol de 4 femmes. Par ailleurs, le BCNUDH de la MONUSCO a pu\nobtenir les identités de quatre personnes portées disparues dont trois garçons âgés de 14 à\n17 ans et recueilli des allégations répétées de pillages de biens provenant de 81 habitants\ndont des commerçants de la localité. Enfin le BCNUDH de la MONUSCO a identifié sept\nfosses communes présumées sur trois sites aux alentours du marché de Tshikulu296.\nd.   Territoire de Luiza"},{"id":"a-hrc-38-crp-1-p0138","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"138","seq":138,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les sept secteurs du territoire de Luiza ont été le théâtre d’actes de violence entre fin\njanvier 2017 et juillet 2017. La milice Kamuina Nsapu est arrivée fin janvier 2017, par le\nnord du territoire en provenance du territoire de Dibaya où est né le mouvement. Sur le\nterritoire de Luiza, la milice Kamuina Nsapu était sous l’autorité d’un chef Kamuina Nsapu\nse réclamant de la famille du chef Kamuina Nsapu et d’un adjoint, tous deux originaires du\nterritoire de Dibaya297. La proximité du territoire de Dibaya et le partage d’une langue\ncommune, le tshiluba, sont des facteurs qui ont favorisé l’expansion de la milice dans ce\nterritoire. Des conflits de partage du pouvoir coutumier et l’influence politique dans la\nreconnaissance des chefs coutumiers notamment dans le secteur de Bambayi, ainsi que des\ntensions préexistantes entre les Bindis et les Keles ont aussi été des facteurs favorables à la\nmilice298."},{"id":"a-hrc-38-crp-1-p0139","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"139","seq":139,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le chef Kamuina Nsapu du territoire de Luiza a installé plusieurs tshiota dont deux\nimportants dans les villages de Kitoko et de Yangala299. Il a, avec son adjoint, parcouru les\nvillages pour convaincre ou contraindre les chefs de village à adhérer au mouvement\nKamuina Nsapu300. Au moins neuf chefs coutumiers ainsi que des membres de leurs\nfamilles qui avaient refusé d’adhérer au mouvement ont été décapités301. L’un de ces chefs\na été tué avec un fusil traditionnel dans le village de Masuika avant d’être décapité et son\ncorps découpé. Sa tête, son sexe et ses bras ont ensuite été amenés au grand tshiota de\nYangala302."},{"id":"a-hrc-38-crp-1-p0140","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"140","seq":140,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De très nombreux garçons et filles, plusieurs centaines, parfois très jeunes, ont été\nrecrutés dans la milice Kamuina Nsapu notamment dans les villages de Kitoko, Moma,\nKadongo, Masuika, Mubinza et Tulumé. Les chefs de village qui ont adhéré au mouvement\nont participé activement au recrutement des enfants tout comme le chef Kamuina Nsapu et\nson adjoint sur le territoire tous deux originaires du territoire de Dibaya303. D’après les\ninformations collectées par la MONUSCO, il y a eu plusieurs vagues de recrutement massif\nd’enfants garçons et filles dans le territoire de Luiza en mars et avril 2017 : au moins 50\nenfants rien que dans la localité de Masuika dont 4 filles ; au moins 32 enfants dans le\nvillage de Moma dont 7 filles ; et, au moins 17 garçons et 1 fille dans le village de\nKadongo. Ces enfants ont été recrutés dans le but d’affronter les forces de défense et de\nsécurité. Certains d’entre eux déclarent que les Kamuina Nsapu leur ont promis l’éducation\ngratuite et des bourses d’études à la condition qu’ils aillent combattre les militaires. C’est\négalement dans le territoire de Luiza que l’on trouve les enfants les plus jeunes à avoir été\nenrôlés dans la milice. Il en est ainsi des cas de deux garçons âgés 3 ans et de 14 mois au\nmoment de leur initiation par les Kamuina Nsapu bien qu’ils n’aient pas été utilisés lors de\ncombats. Un garçon de 5 ans sera toutefois utilisé par les Kamuina Nsapu comme éclaireur.\nEn mai 2017, dans le territoire de Luiza, les miliciens Kamuina Nsapu ont décapité un\ngarçon de 17 ans qui avait refusé d’intégrer la milice304."},{"id":"a-hrc-38-crp-1-p0141","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"141","seq":141,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Par ailleurs, plusieurs témoins racontent que lorsque les miliciens sont arrivés à la\nmission catholique du village de Moma, ils ont recruté par la force de nombreux habitants\ndu village dont des enfants305. Un témoin explique qu’au moins 25 personnes du village de\nKitoko parmi lesquelles sept garçons et filles ont été recrutés dans la milice306.Un autre\nestime à environ 500 le nombre d’enfants recrutés et baptisés dans le village de Masuika307.\n60 à 70 enfants ont été recrutés dans le village de Lumpungu en mars 2017308. Dans la cité\nde Yangala, des enfants du village ont été recrutés par la force et de nombreux enfants\nvenant des villages environnants venaient s’y faire baptiser309. Après avoir installé un\ntshiota dans le village de Tulumé, les miliciens ont recruté des adultes mais aussi une\ncinquantaine d’enfants, filles et garçons, entre 13 et 18 ans310."},{"id":"a-hrc-38-crp-1-p0142","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"142","seq":142,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Dans les villages qui leur étaient hostiles, les miliciens Kamuina Nsapu s’en sont pris\naux habitants et à leurs biens en pillant et brûlant les maisons311. Par exemple dans le\nvillage de Kamushilu, les miliciens Kamuina Nsapu ont incendié 50 maisons suite à\nl’hostilité de la population à leur égard312. D’après la MONUSCO, le 6 mars 2017, 2 filles\net 2 garçons âgés de 4, 7, 11 et 13 ans sont morts brûlés vifs dans le territoire de Luiza\naprès l’attaque de leur village par les Kamuina Nsapu313. Un garçon de six ans a été tué par\nles miliciens Kamuina Nsapu alors qu’il fuyait le village de Tulume avec son père314. Dans\nle village de Mpungu, des affrontements entre les habitants hostiles au mouvement et les\nmiliciens Kamuina Nsapu ont fait quatre morts parmi les habitants, trois hommes et une\nfemme315. Début juin 2017, les miliciens Kamuina Nsapu ont également attaqué un groupe\nde huit personnes dont une femme qui avaient été envoyées en mission par les chefs de\ngroupements pour inciter les habitants à quitter le mouvement Kamuina Nsapu au chef-lieu\ndu groupement de Kalanla Diboko. Quatre ont réussi à fuir. Les quatre autres ont été\namenées au tshiota de Yangala. Les trois hommes ont été battus à mort et jetés dans une\nrivière et la femme violée par les miliciens Kamuina Nsapu avant d’être relâchée316."},{"id":"a-hrc-38-crp-1-p0143","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"143","seq":143,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les miliciens Kamuina Nsapu ont continué à conduire des attaques contre les biens et\nles personnes représentant l’autorité étatique ou qui y étaient assimilés317. Par exemple dans\nle village de Masuika, les miliciens Kamuina Nsapu ont pillé ou détruit les symboles de\nl’Etat comme l’église et les maisons d’agents de l’Etat318. Les miliciens ont aussi commis\ndes exactions contre la population civile dans les villages où ils s’étaient installés. Les\nhabitants qui ne respectaient pas les règles ou qui étaient considérés comme des traîtres\nétaient « jugés » au tshiota avant d’être battus ou décapités319. Par exemple à Masuika, les\nmiliciens Kamuina Nsapu avaient installé trois tshiota. Après avoir incité ou forcé la\npopulation à rejoindre le mouvement, ils règlementaient la vie du village. De nombreuses\npersonnes ont été battues ou tuées aux tshiota pour ne pas avoir respecté les règles\nimposées par la milice320."},{"id":"a-hrc-38-crp-1-p0144","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"144","seq":144,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’Eglise catholique a été une cible privilégiée des miliciens Kamuina Nsapu sur le\nterritoire de Luiza. Ses biens et bâtiments ont été en largement détruits ou pillés et des\nprêtres et personnes proches de l’Eglise ont été menacés et battus, par exemple dans le\nvillage de Masuika et à la mission catholique de Mubinza321. L’église du village de\nLumpungu a été saccagée par les miliciens Kamuina Nsapu322. Dans la cité de Yangala, les\nreligieux catholiques ont été arrêtés, menacés de mort et battus par les miliciens Kamuina\nNsapu323."},{"id":"a-hrc-38-crp-1-p0145","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"145","seq":145,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De nombreuses écoles ont été détruites par les miliciens dans les villages de\nKamushilu, Ngonyi, Kitoko, Kadongo, Kalemba-Mbuji et Malambo324. Par exemple, dans\nle village de Kadongo, devant le refus de la population du village d’adhérer au mouvement\nKamuina Nsapu, des miliciens ont brûlé trois écoles primaires et une école secondaire325."},{"id":"a-hrc-38-crp-1-p0146","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"146","seq":146,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Pour la première fois avec une telle ampleur, des viols collectifs, parfois devant les\nenfants des victimes, commis par les miliciens Kamuina Nsapu sont rapportés. Ainsi à\nl’arrivée des miliciens Kamuina Nsapu dans le village de Muzodi, début avril 2017, cinq\nmiliciens Kamuina Nsapu ont violé une femme enceinte devant sa fille de deux ans ; une\nsemaine plus tard, elle a fait une fausse couche326. Dans le village de Masuika, une\nvingtaine de miliciens Kamuina Nsapu à la recherche d’un agent de l’Etat ont accusé sa\nfemme de traitrise. Menacée par un couteau, la femme a tenté de s’enfuir mais les miliciens\nont déchiré ses vêtements avant de la violer devant ses enfants qui pleuraient. Elle s’est\névanouie après avoir été violée par le cinquième agresseur327. A Sankaji, une femme est\ntombée sur six miliciens Kamuina Nsapu, cinq adultes et un garçon de 15 ans qui ont\nmenacé de la tuer si elle n’avait pas des rapports sexuels avec eux. Ils l’ont ensuite jeté à\nterre et l’ont violé à tour de rôle328. Une dizaine d’habitants du village de Kamayi ont été\nattaqués par des miliciens au mois d’avril 2017 alors qu’ils travaillaient aux champs. Les\nmiliciens ont tiré sur les villageois qui essayaient de fuir et un homme a été tué. Deux\nfemmes ont été emmenées dans le village Lusengu où elles ont été battues avant d’être\nviolées par six ou sept miliciens. L’une d’entre elles est morte des suites de ces viols329."},{"id":"a-hrc-38-crp-1-p0147","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"147","seq":147,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les forces de défense et de sécurité sont arrivées sur le territoire de Luiza début\nfévrier 2017 dans le village de Nguema, secteur de Bambaie330. Entre le 3 et 5 février 2017,\nplusieurs affrontements violents entre les miliciens Kamuina Nsapu, en majorité des\nenfants soit non armés soit possession de bâtons, et les FARDC ont eu lieu dans ce village\ncausant la mort de plusieurs dizaines de miliciens331. Au cours des mois suivants, d’autres\naffrontements ont eu lieu à Nguema entre les miliciens Kamuina Nsapu et les forces de\ndéfense et de sécurité qui ont fait plusieurs dizaines de morts chez les miliciens dont de\nnombreux enfants, garçons et filles332. Trois sites contenant des fosses communes ont été\nidentifiés par la MONUSCO à Nguema333."},{"id":"a-hrc-38-crp-1-p0148","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"148","seq":148,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De nombreux affrontements ont eu lieu dans le territoire de Luiza entre février et mi-\njuillet 2017 lorsque le village de Yangala a été repris par les FARDC334. L’EEI a\ndocumenté certains affrontements dans les villages de Kadongo, Masuika, Mubinza,\nLumpungu et Yangala. Fin mars/début avril 2017, les FARDC sont arrivés dans le village\nde Kadongo et les affrontements avec la milice Kamuina Nsapu ont fait au moins 14 morts,\ny compris des garçons et une femme335. Mi-février 2017, dans les alentours de la mission\ncatholique de Mubinza, plusieurs affrontements violents ont eu lieu entre les miliciens, en\nmajorité des garçons et des filles, et les FARDC. Environ 13 miliciens ont été tués par les\nFARDC et un FARDC a été décapité par les miliciens. Puis 12 miliciens, cinq filles et sept\ngarçons de 7 à 18 ans, ont été tués lors d’un autre affrontement le 20 février 2017336. Un\nautre témoin indique avoir vu les cadavres de sept civils tués par balles à la suite à ces\naffrontements337."},{"id":"a-hrc-38-crp-1-p0149","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"149","seq":149,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Plusieurs affrontements entre les miliciens et les FARDC ont également eu lieu dans\nle village de Masuika lors de la reprise du village par les FARDC en avril ou mai 2017.\nLors d’un affrontement, au moins 17 miliciens Kamuina Nsapu, une grande majorité\nd’enfants, dont certains qui fuyaient ont été tués par les FARDC qui les pourchassaient. Les\ncorps des miliciens ont été jetés dans les latrines338 Dans la cité de Yangala, les FARDC\nsont intervenus à la mi-juillet 2017. Le bilan affrontements n’est pas connu mais trois\nfosses communes ont été localisées au niveau du domicile des prêtres catholiques339. Par\nailleurs deux hommes originaires de Yangala ont été tués et un autre blessé par balle par les\nFARDC alors qu’ils allaient chercher à manger pour les habitants qui s’étaient cachés dans\nla brousse340. Un autre homme a été tué par les FARDC et une femme blessée par balle341.\nDans le village de Masalayi, quatre miliciens Kamuina Nsapu, deux hommes et deux\nenfants ont été tués par les FARDC en juillet 2017 lors d’affrontements. Une femme du\nvillage voisin de Malamba qui n’avait pas fui a été tuée par les FARDC342. En mai et juin\n2017, plusieurs affrontements se sont déroulés dans le village de Kalemba-Mbuji au cours\ndesquels plusieurs dizaines de miliciens y compris des filles et des garçons, ont perdu la\nvie. Les militaires ont achevé au sol certains miliciens blessés343."},{"id":"a-hrc-38-crp-1-p0150","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"150","seq":150,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI a par ailleurs collecté des allégations similaires concernant les villages de\nMpungu, Tulumé, Kalemba Mbuji et Musefu344 et estime que des centaines de miliciens\nKamuina Nsapu, en majorité des enfants non armés ou en possession de simples bâtons, ont\nété tués par les forces de défense et de sécurité au cours d’affrontements sur le territoire de\nLuiza entre février et juillet 2017."},{"id":"a-hrc-38-crp-1-p0151","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"151","seq":151,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De nombreux civils, y compris des enfants, ont aussi perdu la vie ou été blessés\nlorsque les forces de défense et de sécurité ont fait usage de leurs armes de manière\nindiscriminée, par exemple dans les villages de Masuika, Kadimba, Muzodi, Nguema et\nentre Tshikombo et Tshibatabata 345. Ainsi, dans le village de Muzodi, le 7 avril 2017, les\nhabitants avaient été réunis par les miliciens Kamuina Nsapu arrivés la veille dans le\nvillage. C’est alors que les FARDC sont arrivés dans le village et ont ouvert le feu sans\nsommation et ont tiré en direction de toutes les personnes présentes et poursuivant les\npersonnes qui s’échappaient en faisant usage de leurs armes. Les militaires ont ensuite\nparcouru le village, maison par maison et ont tué certains autres civils. Un témoin raconte\nqu’il a été blessé à la jambe et au pied par quatre balles tirées par un militaire346. Trois\nmiliciens Kamuina Nsapu et plus d’une vingtaine d’habitants du village, dont des femmes\nenceintes, des enfants et un bébé de 8 mois ont perdu la vie, de nombreux habitants ont\négalement été blessés par balle. Plusieurs maisons ont également été brûlées347."},{"id":"a-hrc-38-crp-1-p0152","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"152","seq":152,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les FARDC ont pillé348, mais surtout systématiquement brûlé les villages dans\nlesquels ils étaient venus déloger les miliciens Kamuina Nsapu. Par exemple, après les\naffrontements dans le village de Kadongo, les FARDC ont brûlé presque toutes les maisons\ndu village, environ une centaine349. Les FARDC ont totalement brûlé les trois villages de la\nmission catholique de Moma et ainsi au moins 370 maisons ont été détruites. Une femme\nde 80 ans restée prisonnière de sa maison en flammes est décédée, brûlée vive350. De\nnombreuses maisons ont également été brûlées à Masuika lors l’intervention des\nFARDC351. En juillet 2017, le village de Masala a été entièrement détruit par le feu là\nencore, suite à une opération des FARDC352 D’autres villages, tels que Yangala,\nBakalomba, Muanda Muji, Kalemba-Mbuji, Mbalu et Ntumba près de la mission\ncatholique de Mubinza et le groupement de Pikan Mbuji, ont été partiellement brûlés par\nles FARDC353. Au regard des éléments collectés, le nombre de villages détruits par les\nFARDC serait de plusieurs dizaines et le nombre d’habitations brûlées de plusieurs\nmilliers354. Le nombre de maisons et villages brûlés sur le territoire de Luiza est très élevé\net sans commune mesure avec ce que l’EEI a documenté dans d’autres territoires. L’EEI\nestime qu’il s’agissait d’une stratégie délibérée des FARDC, dans le but de punir les\nvillages dans lesquels les miliciens Kamuina Nsapu avaient installé des tshiota."},{"id":"a-hrc-38-crp-1-p0153","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"153","seq":153,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Des cas de viols collectifs commis par des FARDC ont été documentés dans les\nvillages de Kadongo, Masuika, et Yangala. Dans le village de Kadongo, juste après\nl’opération militaire, une femme qui venait d’accoucher a été violée par deux éléments\nFARDC. Une autre femme a également été violée par deux éléments FARDC dans des\ncirconstances similaires à la même période355. Deux femmes auraient été violées dans le\nvillage de Masuika et plusieurs jeunes filles mineures abusées par les FARDC alors qu’ils\nstationnaient dans le village356. Deux éléments FARDC ont violée une jeune fille mineure\nlors de l’intervention des FARDC dans la cité de Yangala. Le viol a été dénoncé à la\nhiérarchie militaire mais au jour du départ de cette unité de Yangala aucune sanction\nn’avait été infligée aux auteurs357.\n2.         Province du Kasaï Oriental"},{"id":"a-hrc-38-crp-1-p0154","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"154","seq":154,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Dans la première partie de l’année 2017, la milice Kamuina Nsapu a continué à être\nactive au Kasaï Oriental, en particulier dans le territoire de Kabeya-Kambwanga358. L’EEI a\nreçu des allégations d’exactions commises par les miliciens Kamuina Nsapu, notamment\ndes décapitations, ainsi que d’affrontements entre les forces de défense et de sécurité et les\nmiliciens et d’exécutions sommaires de civils359. Elle considère que des enquêtes plus\napprofondies sur ces allégations sont nécessaires."},{"id":"a-hrc-38-crp-1-p0155","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"155","seq":155,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI a documenté un cas d’exécution sommaire et plusieurs cas de viols commis par\nles FARDC sur des civils lors d’opérations militaires dans le territoire de Miabi. Ainsi à\nMiteka, en juin 2017, lors d’une opération des FARDC, ils ont sommairement exécuté un\nhomme qui fuyait le village. Sa femme a ensuite été violée par trois FARDC360. Toujours à\nMiteka à la même période, une femme a croisé une douzaine de FARDC sans sa fuite.\nAprès lui avoir demandé si elle voulait ou non mourir, ils l’ont déshabillée, faite tomber par\nterre et violée devant l’un de ses enfants361. En janvier 2017, dans le village de Bena\nNiandu, six FARDC s’exprimant en lingala se sont introduits dans une maison. Après avoir\ndemandé à l’une des femmes s’y trouvant de choisir entre la vie et la mort, ils l’ont frappée\navec un objet dans le bas du dos et fauché. Alors qu’elle était à terre, ils l’ont violée tour à\ntour362."},{"id":"a-hrc-38-crp-1-p0156","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"156","seq":156,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Sur le territoire de Tshilenge, l’EEI a en particulier documenté plusieurs cas de\nrecrutement d’enfants, dont des filles, dans la milice Kamuina Nsapu dans les villages de\nBena Tshisuaka et de Nyoka en mai-juin 2017363. Les enfants, qui venaient de villages\navoisinants ou de Bena Tshisuaka, ont été forcés, parfois menacés de mort, d’accepter le\nbaptême. Une jeune fille raconte que le jour de son baptême, il y avait quelques adultes\nmais surtout des enfants âgés de 9 à 12 ans364. Les enfants rencontrés par l’EEI ont tous\ncombattus contre les FARDC et ont parfois tué des personnes. Certaines filles racontent\nqu’elles ont été utilisées comme « ya mama », c’est-à-dire qu’elles étaient en première\nligne des combats chargées d’arrêter les balles des FARDC avec leurs jupes365. Lorsqu’il\nn’y avait pas d’affrontement, les enfants travaillaient aux champs ou cuisinaient366. Une\nfille de 14 ans raconte : « les miliciens coupaient le sexe des militaires qui avaient été tués\nmais c’était le plus souvent le sexe des militaires gradés qu’ils coupaient. Ensuite les sexes\nétaient grillés et mangés. Les garçons coupaient les sexes et les donnaient aux filles. Le\nsang des victimes était bu. La peau des militaires était séchée puis réduite en poudre et\nensuite cette poudre était mélangée à de l’huile de palme. Ensuite on nous mettait ce\nmélange dans la bouche ou sur le front. Ça nous faisait perdre connaissance et ça nous\ndonnait la haine”367.\n3.         Province de Lomami"},{"id":"a-hrc-38-crp-1-p0157","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"157","seq":157,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Entre mars et juin 2017, la milice Kamuina Nsapu était présente dans la Province de\nLomami, en particulier dans le territoire de Luilu368. Elle est arrivée du territoire de Luiza,\nau Kasaï Central, où les miliciens étaient particulièrement actifs à cette période369. Plusieurs\nrecrues du territoire de Luilu sont allées accomplir la cérémonie du baptême au tshiota de la\ncité de Yangala370. Le chef Kamuina Nsapu du territoire de Luiza, se revendiquant de la\nfamille Kamuina Nsapu et originaire du territoire de Dibaya, est mentionné comme le\nprincipal chef Kamuina Nsapu dans le territoire de Luilu371."},{"id":"a-hrc-38-crp-1-p0158","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"158","seq":158,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le niveau de violence et de cruauté auquel a recours la milice Kamuina Nsapu contre\nles populations civiles croît avec son expansion vers des territoires où la population non-\nlubaphone est importante. Le recrutement dans la milice Kamuina Nsapu se fait\nsystématiquement par la force ou la contrainte372. Les chefs de villages sont loin d’être les\nseuls visés et les habitants, même les enfants, qui refusaient d’adhérer au mouvement\nKamuina Nsapu sont tués373. Un témoin raconte ainsi qu’après avoir été arrêté par des\nmiliciens Kamuina Nsapu dans le village de Mwena Kangala et avoir dû dénoncer la\ncachette de sa famille, ils sont revenus avec ses deux grands frères, son petit frère de cinq\nans et sa mère, son père ayant été décapité. Les miliciens Kamuina Nsapu ont ensuite\négorgé les quatre membres de sa famille dont son petit frère de cinq ans. Le témoin a dû\ntransporter la tête et le bras de sa mère jusqu’au village de Yangala374. Un garçon de 16 ans\nau moment des évènements, raconte comment il a été enrôlé de force dans le village de\nKaboya, à 60 km de Mwene Ditu, avant d’être envoyé à Yangala pour son baptême. Il a été\nensuite été envoyé, avec d’autres miliciens Kamuina Nsapu, combattre les FARDC à\nLunda dans la Province de Luluaba. Au cours de ces affrontements, 20 miliciens auraient\nperdu la vie dont cinq filles. Lors de cette opération, un « capitaine » était en charge sur le\nterrain et il faisait rapport au chef Kamuina Nsapu du territoire de Luiza375."},{"id":"a-hrc-38-crp-1-p0159","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"159","seq":159,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Loin des règles imposées par le mouvement sur le territoire de Dibaya dans les\npremiers mois du conflit, des cas de viols commis par les miliciens Kamuina Nsapu sont\nrapportés sur le territoire de Luilu. Par exemple, dans le village de Kaesa, un groupe de\nquatre femmes a été stoppé par des miliciens Kamuina Nsapu qui leur ont demandé si elles\nvoulaient vivre ou mourir. Ayant répondu qu’elles choisissaient la vie, les quatre femmes\nont toutes été violées par deux miliciens376. Plusieurs civils ont aussi été blessés ou tués par\nles miliciens Kamuina Nsapu pour ne pas avoir respecté les règles imposées ou pour avoir\nété accusés d’être des féticheurs377."},{"id":"a-hrc-38-crp-1-p0160","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"160","seq":160,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les enfants recrutés dans la milice sur le territoire de Luilu ont été utilisés dans des\naffrontements contre les forces de défense et de sécurité, en particulier dans les villages de\nTshilondu, de Mulundu et dans la zone située entre les villages de Kajaganye et de\nTshidulu378. L’EEI a collecté des témoignages sur des affrontements dans les villages de\nMahola, de Kadia Bilula, et dans un village près de Kamuena, au cours desquels des\nmiliciens Kamuina Nsapu, mais aussi des civils, auraient perdu la vie379. D’autres\nallégations crédibles reçues suggèrent que les exactions commises par les forces de défense\net de sécurité dans le cadre d’affrontements et contre la population civile seraient d’une\nampleur plus importante que les éléments collectés par l’EEI. Elle considère que des\nenquêtes supplémentaires sont nécessaires dans la cité de Mwene Ditu, ainsi que dans les\nvillages de Wikong, Mulundu et Tshidienga380. L’EEI a aussi documenté un cas de viol\ncommis par un élément FARDC dans la cité de Mwene-Ditu en juin 2017. Le viol a été\ndénoncé et le FARDC a été arrêté par sa hiérarchie. Il a été jugé et condamné à 20 ans de\nservitude pénale381. Enfin, des témoins ont rapporté qu’une milice Maï-Maï, composée de\npersonnes de l’ethnie Kanyoka s’était organisée pour combattre les miliciens Kamuina\nNsapu dans la province de Lomami et que certains de ses membres ont commis des\nexactions contre des membres de la population qu’ils soupçonnaient d’avoir adhérer au\nmouvement Kamuina Nsapu. Deux femmes ont été violées par des membres de cette milice\nMaï-Maï382.\n4.        Province du Kasaï"},{"id":"a-hrc-38-crp-1-p0161","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"161","seq":161,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les cinq territoires de la province du Kasaï ont été touchés par des actes de violence\nen 2017. Les deux territoires les plus affectés sont le territoire de Luebo et celui de\nKamonia sur lesquels l’EEI a focalisé ses enquêtes.\na.   Territoire de Luebo"},{"id":"a-hrc-38-crp-1-p0162","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"162","seq":162,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"En décembre 2016, le mouvement Kamuina Nsapu a fait son apparition sur le\nterritoire de Luebo, province du Kasaï, en particulier dans les villages de Kabeya-Mayi et\nde Konyi. En décembre 2016, un habitant du village de Konyi est allé chercher des fétiches\net a établi un tshiota dans le village. Cet habitant, devenu le chef Kamuina Nsapu du village\nde Konyi, y a recruté des miliciens de tous âges, y compris des enfants383. Ce même chef\nKamuina Nsapu a favorisé la création d’autres tshiota sur le territoire384. L’expansion du\nmouvement Kamuina Nsapu dans le territoire de Luebo s’explique notamment par le fait\nque la population y est majoritairement luba du clan Bashila Kasanga385."},{"id":"a-hrc-38-crp-1-p0163","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"163","seq":163,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI a en particulier documenté des actes de violence qui ont eu lieu dans la cité de\nLuebo et dans les villages avoisinants. Les miliciens Kamuina Nsapu ont fait leur première\nincursion dans la cité de Luebo fin février ou début mars 2017. Cette première tentative\nd’incursion a été conduite par deux factions distinctes de la milice. Un témoin raconte que\nles miliciens Kamuina Nsapu sont arrivés dans le village de Tshibuyi à l’entrée de la cité.\nLorsqu’ils ont tenté de traverser au niveau des deux ponts de la rivière Kaluebo, ils sont\ntombés dans une embuscade des forces de défense et de sécurité qui étaient déjà informées\nde leur arrivée. Un témoin qui s’est rendu sur les lieux juste après l’incident raconte avoir\nvu au moins trois corps : ceux d’une fille et d’un garçon âgés de 8-9 ans et celui d’un\ngarçon de 15 ans386."},{"id":"a-hrc-38-crp-1-p0164","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"164","seq":164,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Ce même jour, une seconde faction de miliciens Kamuina Nsapu est arrivée au village\nde Kan Jinganyinga. Les FARDC informés de leur arrivée, ont lancé une attaque très tôt le\nmatin suivant dans ce village, avant même que les miliciens n’aient eu le temps de\nprogresser vers la cité. Les FARDC ont utilisé des lance-roquettes faisant de nombreux\nmorts parmi les habitants. Un témoin qui s’est rendu sur les lieux juste après l’incident,\nraconte avoir vu un milicien Kamuina Nsapu blessé et au moins vingt corps de civils dont\ndes femmes et des enfants. Les FARDC ont pillé le village avant de partir387. Un autre\nterroriste du mouvement insurrectionnel « Kamuina Nsapu », documents internes MONUSCO,\nvidéos reçues d’un intermédiaire qui auraient été filmées dans les alentours de Mwene Ditu mais dont\nl’origine n’a pu être vérifiée.\ntémoin indirect indique que le bilan cet incident serait de trois morts et un blessé et que les\ncadavres auraient été enterrés par les militaires388. Peu de temps après, les FARDC ont\nquitté la cité de Luebo389."},{"id":"a-hrc-38-crp-1-p0165","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"165","seq":165,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le matin du 31 mars 2017, la milice Kamuina Nsapu est entrée dans la cité de Luebo\net en a pris le contrôle. Les miliciens étaient très nombreux. Les témoins parlent de\nplusieurs centaines, dont une majorité d’enfants, garçons et filles390. Plusieurs témoins\nprécisent, qu’en plus des bâtons, couteaux, machettes et fusils de chasse, certains miliciens\nétaient en possession d’armes de guerre391. La possession d’armes de ce type par les\nmiliciens Kamuina Nsapu n’a été que très peu rapporté à l’EEI. D’après les informations\nacquises, il est possible que ces armes de guerre aient été collectées par la milice lors\nd’attaques précédentes visant les forces de défense et de sécurité392."},{"id":"a-hrc-38-crp-1-p0166","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"166","seq":166,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les miliciens Kamuina Nsapu sont allés à la prison et ont libéré les détenus. Ils se\nsont ensuite rendus au couvent des sœurs du cœur immaculé de Marie, sont entrés dans les\nmaisons et ont brutalisé les sœurs393. Les miliciens Kamuina Nsapu se sont ensuite dirigés\nvers le quartier Lunkulu, où se trouvent plusieurs bâtiments religieux. Les bureaux de\nl’Institut supérieur et sa bibliothèque ont été saccagés et brûlés. Les habitations des\nreligieux et tous les biens de valeur ont été pillés ou détruits. L’évêché de Luebo a ensuite\nété pris pour cible. Là encore, les biens de valeur et les archives ont été saccagés et brûlés.\nLes religieux et toute personne associée à l’Eglise catholique présents à Luebo ce jour-là,\nrecherchés par les miliciens Kamuina Nsapu, ont dû prendre la fuite394. Un habitant qui\ntentait d’empêcher la destruction de l’évêché a été blessé à coups de machette par cinq\nmiliciens Kamuina Nsapu qui venaient du territoire de Kazumba au Kasaï Central395. Les\nprincipaux bâtiments administratifs de la cité ainsi que des habitations ont aussi été\nincendiés396."},{"id":"a-hrc-38-crp-1-p0167","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"167","seq":167,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Tout comme dans le territoire de Luiza au Kasaï Central, l’Eglise catholique a été\nspécifiquement visée par la milice Kamuina Nsapu. Plusieurs sources mentionnent que les\nmiliciens Kamuina Nsapu accusaient l’Eglise catholique d’avoir essayé de favoriser un\nnouveau mandat de l’actuel Président de la république avec la conférence épiscopale\nnationale du Congo (CENCO) et l’accord politique global et inclusif du Centre\ninterdiocésain de Kinshasa397. Une autre explication serait l’aide apportée par l’Eglise\ncatholique aux membres de l’ethnie Dekese qui ont été particulièrement pris pour cible et\nchassés par les miliciens Kamuina Nsapu du territoire de Luebo398."},{"id":"a-hrc-38-crp-1-p0168","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"168","seq":168,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Toujours le 31 mars 2017, les miliciens se sont attaqués à la femme de\nl’administrateur du territoire de Luebo. Elle a été exécutée par arme à feu puis ses pieds et\nmains ont été coupés par des miliciens399. Trois autres personnes ont été tuées par les\nmiliciens ce jour-là. Il s’agit de deux agents PNC et d’une personne de l’ethnie Dekese400.\nUn des agents de la PNC a été amené au tshiota où il a été allongé et s’est vu administré\ndes coups de machette et de couteau. Un milicien lui a donné un coup de couteau au niveau\ndu cou. Les miliciens l’ont finalement démembré401."},{"id":"a-hrc-38-crp-1-p0169","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"169","seq":169,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Entre le 31 mars et le 16 avril 2017, jour de l’intervention des forces de défense et de\nsécurité, la milice Kamuina Nsapu s’est installée et a contrôlé la cité de Luebo où les\nautorités avaient pris la fuite. Un tshiota, où toutes les décisions se prenaient, a été installé\nau niveau du rond-point parking. Les témoins décrivent que les miliciens Kamuina Nsapu\nétaient principalement des filles et garçons et qu’ils portaient des bandeaux rouges autour\nde la tête. Certains avaient des bâtons, des couteaux et des machettes402. Les chefs des\nmiliciens Kamuina Nsapu, des adultes, portaient des sortes de soutanes403. Plusieurs chefs\nde groupement du territoire de Luebo où des tshiota avaient été installés étaient les chefs de\nla cité de Luebo et se relayaient pour en assurer le contrôle404. Les chefs miliciens Kamuina\nNsapu ont ordonné la fermeture de toutes les églises et contrôlaient les appels\ntéléphoniques. Deux témoins mentionnent que des parents devaient payer pour le baptême\nde leurs enfants par la milice405."},{"id":"a-hrc-38-crp-1-p0170","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"170","seq":170,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le 4 avril 2017, des miliciens Kamuina Nsapu se sont introduits dans une maison et\nont violé deux sœurs âgées de 15 et 17 ans406. Sous la menace d’un couteau, les jeunes filles\nont dû se déshabiller. L’une d’entre elle a été maintenue par les pieds et les mains pendant\nque d’autres miliciens la violaient. L’autre jeune fille a été amenée dans une maison voisine\net a été violée par cinq miliciens Kamuina Nsapu407."},{"id":"a-hrc-38-crp-1-p0171","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"171","seq":171,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le 9 avril 2017, des miliciens Kamuina Nsapu ont forcé une femme, propriétaire d’un\nrestaurant, et son beau-fils à voir des relations sexuelles en public au niveau du tshiota.\nTous deux ont ensuite été tués, mutilés et décapités par des miliciens Kamuina Nsapu408. La\nfemme était accusée par les miliciens d’avoir trahi le mouvement Kamuina Nsapu.\nPlusieurs témoins mentionnent qu’elle a été « jugée » au tshiota409. Ce même jour, un agent\nde la PNC, un jeune homme accusé d’être un voleur et un homme accusé d’être un sorcier\nont été tués par décapitation au tshiota410."},{"id":"a-hrc-38-crp-1-p0172","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"172","seq":172,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Vers le 16 avril 2017, les FARDC ont repris le contrôle de la cité de Luebo après\nplusieurs affrontements avec les miliciens Kamuina Nsapu. Il y a eu des affrontements au\nniveau du pont de Kaluebo et dans le centre-ville. Au niveau du pont Kaluebo, des\nmiliciens mais aussi des civils qui les suivaient ont perdu la vie suite aux tirs des forces de\ndéfense et de sécurité. Les miliciens ont alors fui vers le tshiota dans le centre-ville de\nLuebo et une partie de population a fui en dehors de la cité411. Un autre affrontement très\nviolent, les FARDC utilisant des lance-roquettes, a eu lieu dans le centre de la cité de\nLuebo au cours duquel de très nombreux enfants miliciens Kamuina Nsapu ont perdu la\nvie412. Un témoin explique que juste après les affrontements il a vu de nombreux cadavres\nsur l’avenue Kalemba et l’avenue de la mission. Les corps, qu’il n’a pu dénombrer, étaient\nprincipalement ceux de miliciens. Les FARDC ont achevé les enfants blessés. Un second\naffrontement dans l’après-midi aurait également fait 12 morts parmi les miliciens. Dans les\njours suivants il y aurait eu au moins deux autres affrontements entre les FARDC et les\nmiliciens Kamuina Nsapu qui aurait conduit à la mort de huit miliciens413. Les militaires\nont tiré en l’air avant d’arriver au centre-ville414. Plusieurs témoins mentionnent que des\ncivils ont également été tués lors de ces affrontements sans qu’il ait été possible d’en\ndéterminer le nombre415. L’EEI note qu’il a été particulièrement difficile de documenter la\nreprise de la ville de Luebo par les FARDC et que plusieurs contacts ou témoins ont\nexprimé des réticences à s’exprimer sur le rôle des FARDC dans ces évènements416.\nPlusieurs fosses communes ont été identifiées dans la cité de Luebo417."},{"id":"a-hrc-38-crp-1-p0173","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"173","seq":173,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"A la reprise de la cité de Luebo, des éléments FARDC ont également procédé à des\npillages des biens des habitants418 et ont érigés des barrières afin d’extorquer la\npopulation419. Après la reprise de la cité, les forces de défense et de sécurité ont lancé des\nopérations militaires sur l’ensemble du territoire de Luebo, et en particulier dans les\nvillages où la milice s’était installée. Des allégations crédibles, qui doivent cependant être\nvérifiées, d’opérations militaires dans les villages voisins de Luebo, de Kan Jinganyinga et\nde Kambamoma, au cours desquelles les FARDC auraient tué des miliciens et des civils, et\nincendiés les habitations, ont été rapportées420."},{"id":"a-hrc-38-crp-1-p0174","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"174","seq":174,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De nombreux actes de violence commis par la milice Kamuina Nsapu et par les forces\nde défense et de sécurité ont eu lieu entre décembre 2016 et juin 2017 sur le territoire de\nLuebo. D’après les informations recueillies, entre février et avril 2017, 350 femmes et 420\nhommes auraient été tués lors d’affrontements entre les miliciens Kamuina Nsapu et les\nFARDC. 58 femmes et 150 hommes auraient également été blessés et 50 personnes\nauraient tuées par des balles perdues. 800 maisons ont été incendiées et quatre écoles de\nl’Eglise catholique ont été saccagées, pillées ou incendiées sur l’ensemble du territoire de\nLuebo421."},{"id":"a-hrc-38-crp-1-p0175","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"175","seq":175,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’allégation selon laquelle un affrontement très violent au cours duquel de très\nnombreux miliciens Kamuina Nsapu, dont de nombreux enfants, auraient été tué, sur l’axe\nreliant cité de Luebo à celle de Mweka, début avril 2017, devrait, aux yeux de l’EEI, faire\nl’objet d’une enquête approfondie422. Il en est de même de l’attaque par les miliciens\nKamuina Nsapu du village de Bagnagna où la population civile, en particulier les Bashilele\naurait été la cible des miliciens Kamuina Nsapu423.\nb.   Territoire de Kamonia"},{"id":"a-hrc-38-crp-1-p0176","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"176","seq":176,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"La milice Kamuina Nsapu était déjà active autour de la ville de Tshikapa et sur l’axe\nroutier Kananga-Tshikapa, secteur Bakwa-Nyambi, depuis décembre 2016424 et l’est restée\nau cours de la période allant de janvier à mai 2017. A partir de février-mars 2017, dans un\ndeuxième mouvement, la milice Kamuina Nsapu, en provenance du territoire de Kazumba,\nKasaï Central, est arrivée dans la partie sud du territoire de Kamonia dans les secteurs de\nKasaï-Longatshimo, Kasaï-Lunyeka et Lovua-Longatshimo. Dans le secteur de Kasaï-\nLongatshimo où la population est majoritairement luba, la milice Kamuina Nsapu a\nprogressé rapidement le long de l’axe entre Mutena et Kamako, ainsi que dans la partie\nfrontalière avec l’Angola dans le secteur de Kasaï-Lunyeka. Elle a ensuite atteint les zones\noù la population tend à être majoritairement chokwe du secteur de Lovua-Longatshimo où\nelle a rencontré une résistance violente des Chokwes et Pendes. Ces derniers se sont alors\norganisés en milices, les milices Bana Mura, dans le secteur de Kasaï-Longatshimo, et\naussi dans et autour de la cité de Kamonia, initialement pour se défendre. Cependant, ils\ns’en sont rapidement pris à la population luba au cours d’attaques extrêmement violentes."},{"id":"a-hrc-38-crp-1-p0177","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"177","seq":177,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI est particulièrement alarmée par le niveau de violence auquel la milice\nKamuina Nsapu a eu recours sur le territoire de Kamonia. Le territoire de Kamonia a été\nl’un des plus affecté par la crise qui touche le Kasaï depuis 2016. La progression de la\nmilice Kamuina Nsapu s’y est heurtée aux limites territoriales lubas dans le Kasaï. En\ntentant de s’étendre vers des zones majoritairement habitées par des Chokwes et des\nPendes, la milice Kamuina Nsapu a rencontré une très forte résistance de la part de ces\ncommunautés. Les faits décrits dans cette section démontrent que le niveau de violences\nauquel ont eu recours la milice Kamuina Nsapu et les milices Bana Mura est le plus élevé\nque l’EEI ait documenté aux cours de ses enquêtes. Les populations civiles, qu’elles soient\nd’ethnie chokwe, pende ou luba, ont été les principales victimes des actes de violence\ncommises par tous les acteurs du conflit. L’EEI estime que sur le seul territoire de\nKamonia, plusieurs milliers de personnes ont perdu la vie entre février et juin 2017. L’EEI\na noté deux changements, particulièrement marquants sur le territoire de Kamonia dans le\nmode opératoire de la milice Kamuina Nsapu."},{"id":"a-hrc-38-crp-1-p0178","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"178","seq":178,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Tout d’abord, loin de la règle de principe imposée au sein de la milice Kamuina\nNsapu de l’interdiction du viol, l’EEI a documenté de nombreux cas de viols et de\nviolences sexuelles commis par les miliciens Kamuina Nsapu sur le territoire de Kamonia.\nDe même cas ont aussi été rapportés dans d’autres territoires, notamment ceux sur lesquels\nl’influence des Lubas se réduit. Néanmoins leur nombre et leur violence sont spécialement\nimportants dans le territoire de Kamonia. Le nombre de viols commis est alarmant comme\nl’atteste le nombre de victimes entendues par l’EEI425. A titre d’exemple, en mars 2017, une\njeune femme a été kidnappée par des miliciens Kamuina Nsapu et conduite dans une\nmaison dans le village de Dizumbudu. Trois miliciens Kamuina Nsapu l’ont alors violée.\nElle est restée dans cette maison pendant une semaine où elle a été battue tous les jours et\nviolée trois fois avant d’être finalement libérée426. Une jeune fille de 17 ans au moment des\nfaits, dont le mari a été décapité par des miliciens Kamuina Nsapu qui s’étaient introduits à\nson domicile dans le village de Kamundele en avril 2017, a été violée par des miliciens\nKamuina Nsapu. Alors que deux miliciens la tenaient, un troisième l’a violée. Puis quatre\nmiliciens l’ont encore violée. Son voisin qui avait tenté de la secourir a été décapité. La\nvictime est tombée enceinte suite à ce viol427. Une autre jeune fille de 17 ans a également\nété violée par des miliciens Kamuina Nsapu dans le village de Tinjide, près de la frontière\navec l’Angola. Un groupe de miliciens, y compris des enfants, s’est introduit au domicile\nde la victime. Son frère qui a tenté de s’interposer a reçu un coup avec le plat de la\nmachette derrière la tête et les miliciens lui ont ensuite coupé le sexe. Des miliciens adultes\nont ensuite violé cette jeune fille. S’étant évanouie après s’être cognée la tête pendant son\nagression, elle n’est pas en mesure de dire combien d’agresseurs l’ont violée428. Dans le\nvillage de Kabumbo, à l’arrivée des miliciens Kamuina Nsapu, un homme du village\naccusé d’être membre du Parti du peuple pour la reconstruction et la démocratie (PPRD) a\nété déshabillé en public par les miliciens Kamuina Nsapu. Ces derniers ont alors demandé à\nun garçon du village de le violer en le pénétrant par l’anus. L’homme souffre toujours de\nséquelles physiques importantes liées à ce viol429."},{"id":"a-hrc-38-crp-1-p0179","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"179","seq":179,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De plus, certains des actes de violence commis sur ce territoire par les miliciens\nKamuina Nsapu revêtent une connotation ethnique. Les miliciens Kamuina Nsapu\nconsidéraient les non-lubaphones, spécialement les Chokwes, Pendes et Tetelas, comme\ndes ennemis du mouvement. De nombreux actes de violence commis par les Kamuina\nNsapu contre des membres de ces trois ethnies sont présentés ci-dessous. Il ne ressort pas\ntoujours nettement des éléments de preuve si les Chokwes, Pendes et Tetelas ont été\nattaqués pour des raisons ethniques ou parce qu’ils étaient assimilés à des opposants au\nmouvement et/ou considéré comme proches des autorités étatiques ou encore pour ces deux\nraisons à la fois. Cependant, les éléments de preuve montrent qu’au moins certains des\nactes de violence commis par les miliciens Kamuina Nsapu sur ce territoire revêtaient un\ncaractère ethnique. Ainsi, dans le village de Lubami Monga, au moment de l’attaque du\nvillage de Senge (ou Cinq) par les miliciens Bana Mura430, la milice Kamuina Nsapu était\npartie combattre les miliciens Bana Mura. A leur retour les miliciens Kamuina Nsapu ont\nspécifiquement regroupés tous les hommes et les femmes pendes du village et 24 Pendes\nont été décapités au tshiota431. Un témoin explique que dans le village de Lupemba, les\nmiliciens Kamuina Nsapu interdisaient aux habitants de parler tetela et pende. Il a dû\nprendre la fuite vers l’Angola après avoir été dénoncé comme appartenant à cette ethnie.\nUne fois arrivé en Angola, il a été informé par des habitants du village que 18 Tetelas\navaient été tués dans le village par les miliciens Kamuina Nsapu en mai 2017432. Un autre\ntémoin explique que dans le village de Dibala, où les miliciens Kamuina Nsapu avaient\ninstallé un tshiota, de nombreuses personnes ont été décapitées et que le choix des victimes\nse faisait notamment sur une base d’appartenance ethnique433.\nAxe Kananga-Tshikapa"},{"id":"a-hrc-38-crp-1-p0180","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"180","seq":180,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Au cours du premier semestre 2017, la milice Kamuina Nsapu a continué à commettre\ndes exactions sur l’axe Kananga-Tshikapa, notamment dans la zone autour du groupement\nMbawu et jusqu’au village de Kamuesha434. L’EEI a en particulier documenté l’incident au\ncours duquel 37 PNC, plus précisément de la LNI, et 2 FARDC ont trouvé la mort dans une\nembuscade des miliciens Kamuina Nsapu, autour du 24 mars 2017, vers le village de\nMalenga."},{"id":"a-hrc-38-crp-1-p0181","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"181","seq":181,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Vers le 24 mars 2017, deux camions transportant des membres de la LNI et deux\néléments FARDC sont partis de de Tshikapa vers Kananga. Deux jours plus tard, ils se sont\nembourbés sur la route principale à quelques kilomètres de la bifurcation Djoku Punda qui\nse trouve à 95 km de Tshikapa435. Les deux camions et leurs passagers se sont retrouvés\nencerclés par de très nombreux miliciens Kamuina Nsapu436. Les agents de la LNI et des\nFARDC ont été assis par terre et les miliciens Kamuina Nsapu les ont filmés437. Les\nmiliciens ont alors demandé aux agents de la LNI de retirer leurs uniformes438 et ont\ncollecté les armes qui se trouvaient dans les camions439. Les miliciens ont ensuite amené les\nmembres de la LNI et les FARDC, deux par deux, derrière une école et les ont tous tués à\ncoups de machette et décapités440. 37 agents de la LNI et deux FARDC ont ainsi perdu la\nvie. Trois agents de la LNI et les deux chauffeurs qui parlaient tshiluba ont eu la vie sauve\nmais ont dû toute la matinée du lendemain, enterrer le corps de leurs collègues441. Le major\nde la PNC a été tué dans un autre endroit. Les miliciens Kamuina Nsapu lui avaient coupé\nle sexe et les survivants avaient aussi dû l’enterrer442."},{"id":"a-hrc-38-crp-1-p0182","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"182","seq":182,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Par ailleurs, l’EEI a collecté des témoignages qui montrent que les FARDC ont aussi\ncommis des exactions sur l’axe Kananga-Tshikapa. Par exemple, dans le village de\nKabumba, lors d’une opération des FARDC, deux filles de 15 ans racontent qu’en fuyant le\nvillage elles ont vu de nombreux cadavres et qu’elles ont perdu à cette occasion quatre\nhommes de leur famille443. D’après un autre témoin, il y aurait eu plusieurs affrontements\nentre les FARDC et les miliciens Kamuina Nsapu au cours desquels plusieurs dizaines de\npersonnes, des miliciens et de civils, auraient été tués entre février et avril 2017 dans\nvillage de Tshitadi. Le témoin indique avoir assisté à l’enterrement d’au moins 10 habitants\ndu village en avril 2017, tous tués par balle, dont quatre hommes, une femme, une fille de\n15 ans, et trois garçons de moins de trois ans444. Une autre femme a expliqué que son mari\navait été tué par balle par les FARDC lors d’une opération militaire dans le village de\nTshitadi en mars 2017445. Un témoin raconte que vers le village de Kaluebo, sa fille de 24\nans a été violée par trois éléments FARDC si violemment qu’elle a commencé à saigner et\nqu’elle est décédée des suites de ce viol. Le bébé de sa fille, âgé de deux semaines, est\négalement décédé en raison des conditions de vie imposées par cette fuite446. D’autres\nallégations crédibles reçues suggèrent que les exactions commises par les forces de défense\net de sécurité contre la population civile sur cet axe seraient d’une ampleur bien plus\nimportante que les éléments collectés par l’EEI. Elle considère que des enquêtes\nsupplémentaires seraient nécessaires.\nVille de Tshikapa"},{"id":"a-hrc-38-crp-1-p0183","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"183","seq":183,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"La ville de Tshikapa est majoritairement lubaphone même si les minorités chokwes et\npendes y sont importantes. Tshikapa est divisé en neuf secteurs dont cinq sont\nmajoritairement habités par des Lubas, trois par les Chokwes et un par les Pendes. Les\ndifférentes communautés se mélangent peu.447"},{"id":"a-hrc-38-crp-1-p0184","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"184","seq":184,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"La milice Kamuina Nsapu s’est installée dans les quartiers habités par des Lubas de\nTshikapa448 et a commis des actes de violence dans la ville, en particulier entre janvier et\navril 2017. Dans la traque des représentants de l’Etat, plusieurs agents de la PNC, dont un\ncommandant ont été décapités449. Le niveau de violences à l’encontre de la population par\nla milice s’est accentué. Par exemple, début février 2017, des miliciens ont pénétré au\ndomicile d’une femme à la recherche d’agents de l’Etat. Après avoir fouillé la maison, les\nmiliciens Kamuina Nsapu lui ont demandé de choisir entre mourir ou devenir leur femme.\nQuatre miliciens Kamuina Nsapu l’ont alors plaquée au sol et violée450. Un témoin de\nl’ethnie tetela explique que des miliciens Kamuina Nsapu, une femme et quatre hommes,\nsont entrés dans sa maison et ont décapité son mari. Un milicien a alors bu le sang qui\ncoulait de la tête de son mari. Un chef Kamuina Nsapu a ensuite pris sa baïonnette et\ncommencé à mutiler le visage du témoin avant d’introduire sa main dans le vagin du\ntémoin devant ses enfants. Le témoin ajoute : « il enfonçait sa main comme s’il voulait\narracher quelque chose à l’intérieur. J’étais enceinte de cinq mois. J’ai beaucoup saigné. Ils\nm’ont ensuite abandonnée là avec mes enfants. »451"},{"id":"a-hrc-38-crp-1-p0185","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"185","seq":185,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Plusieurs affrontements entre la milice Kamuina Nsapu et les FARDC, mais aussi des\nopérations militaires menées à la recherche de miliciens Kamuina Nsapu, ont eu lieu au\ncours de cette période452. Plusieurs habitants de Tshikapa ont été blessés ou tués par les\nFARDC lors d’opérations militaires, notamment dans le quartier de l’hôpital de Tshikapa,\nla commune de Kele, et au niveau de l’aéroport. Des témoins ont indiqué que lors des\nopérations, les FARDC tiraient sur tout le monde sans faire de distinction entre les\nmiliciens et les habitants453."},{"id":"a-hrc-38-crp-1-p0186","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"186","seq":186,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI a également collecté des éléments de preuve concernant des actes de violence\nparticulièrement graves commis par les FARDC contre des habitants de la ville de\nTshikapa. En juin 2017, un groupe d’une dizaine d’hommes parlant lingala, portant des\npantalons militaires et des cagoules, et armés de machettes et de couteaux, se sont\nintroduits dans une maison en pleine nuit. Ils ont ligoté les pieds et les mains d’un homme\navant de le décapiter. Ils ont également décapité un autre jeune homme et éventré une\nfemme enceinte de sept mois. Ils ont sorti le fœtus et tué la mère. Puis neuf des hommes\nont trainé une femme derrière la maison, l’ont fait tomber par terre, lui ont arraché ses\nvêtements avant de la violer. Cinq d’entre eux ont également mis un doigt dans son anus.\nElle souffre d’importantes séquelles physiques. Ils ont ensuite enlevé quatre jeunes filles\nmineures disant qu’ils allaient en faire leurs femmes454. De manière similaire, des FARDC\nse sont introduits dans une maison de la ville de Tshikapa et trois d’entre eux ont décapité\nun homme avec une machette. Sa femme, enceinte, a été éventrée par les militaires qui ont\nsorti le fœtus. Deux FARDC ont ensuite violé une jeune femme de 18 ans et deux filles de\n14 et 17 ans455."},{"id":"a-hrc-38-crp-1-p0187","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"187","seq":187,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"En avril et mai 2017, les tensions entre les Lubas et les Chokwes et les Pendes étaient\nimportantes dans la ville de Tshikapa456. Un témoin a expliqué à l’EEI qu’en arrivant à\nTshikapa, il avait été arrêté par des Chokwes qui lui ont demandé s’il était Luba ou Pende.\nComme le témoin parlait pende, il a pu convaincre les Chokwes de le laisser passer. Ces\nderniers lui ont donné une carte attestant son ethnie pende qui servait de justificatif457."},{"id":"a-hrc-38-crp-1-p0188","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"188","seq":188,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Une femme luba raconte que mi-avril 2017, un groupe de dix hommes armés de\nbâtons et de haches a fait irruption dans sa maison. Les hommes qui parlaient chokwe\nétaient à la recherche de son mari. Ils l’ont attrapée et l’ont molestée expliquant que se sont\nses frères lubas qui tuent les Pendes à Tshikapa. Les hommes ont décapité le mari du\ntémoin et mis le feu à la maison458. De manière similaire, le 20 mai 2017, trois hommes\ncagoulés et habillés en civils se sont introduits dans une habitation et ont violé une femme.\nIls ont également enlevé une fille de 12 ans qui est toujours portée disparue459. Un autre\ntémoin raconte que sa maison a été incendiée par de jeunes chokwes et pendes portant de la\npoudre noire sur le visage pendant la nuit ; réveillée dans son sommeil par la fumée, elle a\nréussi à s’enfuir avec ses enfants même si l’un d’entre eux a été blessé. Elle estime que sa\nmaison a été ciblée car elle était située dans le quartier habité par des Lubas de\nDibomba.460."},{"id":"a-hrc-38-crp-1-p0189","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"189","seq":189,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Lors d’opérations de traque des miliciens Kamuina Nsapu, les FARDC ont également\ncommis de nombreuses exactions contre la population civile dans les villages environnant\nla ville de Tshikapa. Par exemple dans le village de Tshibritika, à 5 kilomètres de Tshikapa,\nles FARDC ont tué un homme et ses trois filles âgées de 6 mois, 6 ans et 8 ans. Sa\nquatrième fille de 15 ans a été violée par trois FARDC461. Deux femmes racontent\ncomment, en se rendant de Tshikapa au village de Milumbo en avril 2017, elles ont été\nviolées, alors qu’elles se trouvaient avec d’autres femmes, par cinq éléments FARDC.\nL’une des femmes a été tuée462. De manière similaire, deux jeunes filles de 15 ans ont été\nviolées par des éléments FARDC au niveau de la rivière Kabidumbi à 9 kilomètres de la\nville de Tshikapa, autour du 15 avril 2017. Les deux jeunes filles ont été arrêtées à une\nbarrière tenue par les FARDC et ont chacune été violées par un FARDC ; toutes les deux\nsouffrent de séquelles physiques463.\nSud du territoire de Kamonia"},{"id":"a-hrc-38-crp-1-p0190","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"190","seq":190,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"La milice Kamuina Nsapu est entrée dans la partie sud du territoire de Kamonia en\nprovenance du territoire de Kazumba, Kasaï Central464. Elle est devenue très active dans\ncette partie du territoire à partir de mars 2017, en particulier entre la cité de Mutena et celle\nde Kamako dans le secteur de Kasaï Lunyeka et dans la partie frontalière avec l’Angola du\nsecteur de Lovua-Longatshimo. L’animosité des communautés chokwe et pende en raison\nde la présence des Lubas dans cette partie sud du terrioire de Kamonia est ancienne ;\nnéanmoins, avant la crise, les communautés cohabitaient pacifiquement et travaillaient\nensemble surtout dans l’industrie du diamant. Avec l’arrivée de la milice Kamuina Nsapu,\nles relations entre les Lubas, Chokwes et Pendes se sont détériorées465. L’EEI a documenté\nles actes de violence dans plusieurs localités où la milice Kamuina Nsapu s’était installée, à\nsavoir : Mutshima, Diboko, Tshinota, Mudjadja, Sumbula, et Kamako466.\nCité de Kamako"},{"id":"a-hrc-38-crp-1-p0191","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"191","seq":191,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le 6 mars 2017, la milice Kamuina Nsapu a fait une incursion dans la cité de\nKamako. Un petit groupe de miliciens est arrivé dans la cité et a pris le contrôle de l’état-\nmajor de la PNC détruisant le cachot et libérant les prisonniers. Ils ont battu un FARDC\navant d’être repoussés de la ville par les forces de défense et de sécurité467. Un civil et\nplusieurs agents de la PNC ont été tués468."},{"id":"a-hrc-38-crp-1-p0192","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"192","seq":192,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Après cette première incursion, la PNC a commencé à arrêter arbitrairement des civils\nen particulier des Lubas, à les maltraiter et parfois à les exécuter469. Ainsi trois hommes\nlubas ont été arrêtés sous un prétexte fallacieux, battus à coups de machette, puis exécutés\npar des PNC de Kamako470. D’autres personnes ont été arrêtées et ont subi des mauvais\ntraitements en détention conduisant parfois à des invalidités permanentes, au prétexte qu’ils\nétaient des miliciens Kamuina Nsapu471. Ainsi le 10 avril 2017, six hommes lubaphones ont\nété arrêtés par 15 agents de la PNC. Les six hommes ont été battus à l’état-major de la\nPNC, y compris avec des coups de machette et des coups de pied avant d’être libérés\nplusieurs jours plus tard472."},{"id":"a-hrc-38-crp-1-p0193","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"193","seq":193,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le 13 ou 14 avril 2017, les miliciens Kamuina Nsapu, dont de nombreux enfants, sont\nrevenus en grand nombre et ont pris le contrôle de la cité de Kamako après un bref\naffrontement avec les forces de défense et de sécurité, au cours duquel des miliciens\nKamuina Nsapu, dont une fille, ont été tués. Ils ont dirigé la cité jusqu’au 30 avril 2017473.\nUn tshiota a été installé à l’état-major de la PNC où les Kamuina Nsapu ont baptisé, parfois\nde force, les nouvelles recrues et où ils ont « rendu la justice »474. Un témoin raconte qu’un\nagent de la PNC qui n’avait pas réussi à fuire a été décapité au tshiota ce jour-là475."},{"id":"a-hrc-38-crp-1-p0194","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"194","seq":194,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les miliciens Kamuina Nsapu ont recruté de nombreux enfants dans la cité de\nKamako476. Après son baptême au village de Mutshima avec sept garçons et trois filles, une\nfille de 15 ans qui avait décidé de rejoindre le mouvement Kamuina Nsapu est devenue\n« ya mama »477."},{"id":"a-hrc-38-crp-1-p0195","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"195","seq":195,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Pendant la période où les miliciens Kamuina Nsapu avaient le contrôle de la cité de\nKamako, ils ont procédé à de nombreuses décapitations ; 41 au moins selon un témoin. Le\ncapitaine de la PNC de Kamako, des agents de la PNC, le chef du service des transports et\nvoies de communication, un garçon de 14 ans accusé d’être un sorcier, des hommes\nsoupçonnés de complicité avec les militaires ou représentants de l’Etat, un chef de village\naccusé de sorcellerie, un agent de la Direction Général de Recette du Kasaï, ainsi que\nd’autres personnes accusées d’être des voleurs ou des sorciers, ont été publiquement\ndécapités par la milice Kamuina Nsapu478. Il y avait des décapitations presque tous les jours\nraconte un témoin479. Un témoin raconte que les miliciens ont voulu installer un second\ntshiota dans la ville. Ils avaient alors besoin de têtes pour nourrir le tshiota et sont passés\ndans plusieurs maisons pour enlever des habitants480. Deux jours après l’arrivée des\nmiliciens Kamuina Nsapu dans la cité, 15 d’entre eux se sont introduits dans une maison\nrecherchant des hommes et ont décapité un homme et un garçon de 11 ans481. Une jeune\nfemme raconte comment ses deux parents ont été décapités et sa mère éventrée par des\nenfants miliciens âgés de 12 à 14 ans lors de l’arrivée des miliciens Kamuina Nsapu dans la\ncité de Kamako avant que la maison familiale ne soit incendiée482. Une autre victime\nraconte que son mari a été décapité à Kamako à l’arrivée des miliciens et que son ami qui a\nété blessé partout sur le corps à coups de machette, n’avait survécu que parce qu’il parlait\ntshiluba483. Un homme raconte qu’ayant appris la décapitation de sa femme dans la cité de\nKamako, il avait demandé des explications à des miliciens Kamuina Nsapu. Ces derniers\nl’ont battu et lui ont cassé la jambe484."},{"id":"a-hrc-38-crp-1-p0196","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"196","seq":196,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Un témoin raconte qu’un chef Kamuina Nsapu venu de l’extérieur de la cité avec une\ndélégation avait invité la population à dénoncer les miliciens qui auraient commis des\npillages. Cette délégation a décapité un milicien Kamuina Nsapu identifié comme violeur.\nNéanmoins, les autres miliciens Kamuina Nsapu de la cité se sont retournés contre la\ndélégation et le chef Kamuina Nsapu ainsi que les membres de la délégation ont été\ndécapités, démembrés, et leurs corps ont été publiquement exposés dans la cité485."},{"id":"a-hrc-38-crp-1-p0197","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"197","seq":197,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"A cette période, alors qu’elles fuyaient les violences, une jeune femme, sa sœur de 17\nans et son petit frère de 10 ans ont été stoppés par des agents de la PNC alors qu’ils\nfuyaient l’arrivée des miliciens dans la cité. Deux PNC ont trainé la jeune femme à l’écart\ndans la forêt, ont arraché ses vêtements et l’ont violée. Sa sœur de 17 ans a également été\nviolée par deux autres PNC486."},{"id":"a-hrc-38-crp-1-p0198","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"198","seq":198,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le 1er mai 2017, les FARDC ont repris par la force le contrôle de la cité de Kamako.\nLes FARDC ont tiré sur les miliciens Kamuina Nsapu, incluant de nombreux enfants,\ngarçons et filles, non-armés ou munis de bâtons. Plusieurs témoins indiquent que les\nFARDC ont tiré même sur les enfants qui n’avaient pas d’armes et qui fuyaient487. Il y a\négalement eu de nombreux miliciens blessés, plusieurs dizaines, au moins 15, dont trois\nfilles488. Une « ya mama » qui avait été placée en première ligne des affrontements par les\nmiliciens pour arrêter les balles selon les croyances magiques a été blessée à l’œil par les\néclats d’une grenade de lance-roquette ; elle a également reçu quatre balles dans le corps489.\nLes FARDC ramassaient les corps des miliciens tués au fur et à mesure dans deux\ncamions490."},{"id":"a-hrc-38-crp-1-p0199","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"199","seq":199,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Des corps de miliciens ont été déchargés par les FARDC lors de plusieurs rotations de\ncamions au cimetière de Kamako ; la Croix-Rouge congolaise a ensuite enterré 37 corps491.\nTrois autres fosses communes ont été mentionnées : une derrière le nouveau bâtiment de la\nDGM au poste-frontière de Kamako qui compterait 67 corps et deux autres en face de la\nmaison du chef de groupement et derrière l’école dans lesquelles se trouverait environ 30\ncorps492. Un témoin parle de 37 miliciens, en majorité des enfants et des jeunes adultes, tués\nle 1er mai 2017 et de 36 autres tués le 2 mai 2017493."},{"id":"a-hrc-38-crp-1-p0200","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"200","seq":200,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Un témoin indique que le colonel des FARDC avait donné l’ordre de ne tirer que sur\nles miliciens494. Par ailleurs, les FARDC ont demandé à la population de ne pas fuir et de\ns’enfermer dans les habitations. Ils ont également indiqué qu’ils allaient fouiller les\nmaisons les unes après les autres à la recherche de vêtements de couleur rouge, incitant les\nhabitants à fuir495. Des très nombreux habitants de la cité ont fui à l’arrivée des FARDC496.\nMalgré les instructions données de ne tirer que sur les miliciens, les FARDC ne faisaient\npas de distinction entre les miliciens Kamuina Nsapu et la population civile et des habitants\nqui fuyaient ont été tués par balles497. Un témoin raconte que sa femme a été tuée par balle\nau moment de l’arrivée des FARDC dans la cité de Kamako498. Un autre témoin indique\nque deux de ses enfants sont morts noyés dans la rivière en fuyant la cité de Kamako suite\naux affrontements entre les miliciens et les FARDC499. Une femme a aussi été violée devant\ndeux de ses enfants par deux éléments FARDC en fuyant Kamako500.\nAlentours de Kamako et partie frontalière avec l’Angola"},{"id":"a-hrc-38-crp-1-p0201","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"201","seq":201,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Près de Kamako et dans la partie frontalière avec l’Angola, de nombreux actes de\nviolence ont été commis par les miliciens Kamuina Nsapu, non seulement contre les\nreprésentants de l’Etat ou personnes assimilées501, mais surtout contre la population civile.\nPlusieurs chefs de villages de cette zone qui s’étaient opposés à l’arrivée de la milice et à\nl’installation de moustiquaires supposées, selon la croyance, collecter les fétiches, ont été\ndécapités502. Dans les villages où les miliciens avaient installé des tshiota, de très nombreux\ncas de meurtres, surtout des décapitations, souvent plusieurs dizaines par village, sont\nrapportés. Ces exactions visaient parfois des représentants de l’Etat mais, dans la majorité\ndes cas, des membres de la population503. Par exemple, dans village de Lubami-Monga, les\nmiliciens Kamuina Nsapu faisaient des allers-retours entre la cité de Kamako et le village\net rapportaient de nombreuses têtes décapitées au tshiota du village. Un témoin raconte\navoir vu au moins six têtes de militaires, deux têtes de civils pendes, cinq têtes venant de\nKamako et d’autres têtes venant du village de Senge (ou Cinq)504. De manière similaire,\ndans le village de Tshinota, les miliciens Kamuina Nsapu ont décapité en public au tshiota\nau moins deux agents de l’ANR, deux de la DGM, une personne travaillant dans l’hygiène,\nun militaire, un jeune Pende, deux Chokwes, le nouveau chef du village, une personne\nsuspectée de contacts avec les autorités, le chef d’un village voisin et 10 Chokwes des\nvillages environnants505. Un témoin raconte avoir dénombré environ 65 têtes autour du\ntshiota506. De nombreux habitants ont également été battus, maltraités et mutilés par les\nmiliciens Kamuina Nsapu, notamment en cas de non-respect des règles de vie imposées par\nla milice. Par exemple, une nuit, des miliciens Kamuina Nsapu sont entrés dans la maison\nd’un homme. Ils l’ont battu à coups de machette avant de lier un fil dans son pénis ; il a de\ngraves séquelles physiques depuis507."},{"id":"a-hrc-38-crp-1-p0202","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"202","seq":202,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les miliciens Kamuina Nsapu ont également commis de nombreux actes de violence\nau cours d’incursions et d’attaques dans les villages de cette zone dans lesquels ils n’étaient\npas installés508. Dans le village de Kilolo, situé à la frontière avec l’Angola, un témoin\nraconte avoir vu un garçon de l’ethnie bindi accourir vers lui grièvement blessé à coups de\nmachette au niveau du cou ; l’enfant est mort. L’école du village avait été attaquée par des\nmiliciens Kamuina Nsapu. Après l’attaque, le témoin est retourné au village dont les rues\nétaient jonchées de cadavres, dont ceux de ses enfants âgés de 12, 15 et 17 ans. Deux de ses\nenfants avaient été décapités509. Les personnes travaillant dans l’industrie du diamant ont\nété spécialement visées par les attaques des miliciens510. Ainsi, le 7 mars 2017, un groupe\nde creuseurs de diamant qui travaillait près de Kamako à l’embouchure des rivière Mwali\net Luanga Nsthima, a été accosté par cinq miliciens Kamuina Nsapu, âgés de 14 à 16 ans.\nLes enfants miliciens ont coupé le tendon d’Achille d’un des creuseurs de diamant avec\nune machette avant de le décapiter. Puis ils ont décapité cinq autres creuseurs de diamant et\nordonné au seul survivant de ramasser les têtes et de les mettre dans un sac. Ils ont ensuite\ncoupé le sexe d’un des cadavres et bu le sang qui s’en échappait. Les miliciens Kamuina\nNsapu ont alors brûlé la main droite et le pied gauche du seul survivant avant de\nl’abandonner sur place511. Toujours près de Kamako, dans le village de Tshijinde, une\nvingtaine de miliciens Kamuina Nsapu se sont introduits dans la maison d’une famille\ntravaillant dans l’industrie du diamant. Dans la maison, les miliciens ont décapité à la\nmachette un ami de la famille, le mari et le fils du témoin. Les miliciens Kamuina Nsapu\nont ensuite rassemblés les têtes dans un sac et demandé au témoin de « partir transmettre le\nmessage », menaçant de le tuer s’il les jetait512. De multiples cas de viols commis par les\nmiliciens Kamuina Nsapu ont également été rapportés dans cette partie du territoire de\nKamonia513. Par exemple, autour du 17 mars 2017, sept femmes et leurs enfants, dont des\nfilles, ont été stoppés par un groupe d’une dizaine de miliciens Kamuina Nsapu en fuyant le\nvillage de Lubami-Monga. Les femmes ont été séparées de leurs enfants et amenées dans\nune petite maison dans la savane Kassa. Une fille de 12 ans et une femme enceinte ont été\nviolées par les miliciens Kamuina Nsapu et toutes deux sont mortes en conséquence de\nleurs viols. Toutes les autres femmes du groupe ont également été violées à plusieurs\nreprises par les miliciens Kamuina Nsapu ce jour-là514."},{"id":"a-hrc-38-crp-1-p0203","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"203","seq":203,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les FARDC ont conduit des opérations militaires, notamment en mars et en juin\n2017, visant à déloger les miliciens Kamuina Nsapu de la zone de Kamako et de la partie\nfrontalière avec l’Angola. L’EEI a reçu des allégations crédibles d’affrontements violents\nentre les FARDC et les miliciens dans le village de Lubami-Monga au cours desquels de\nnombreux miliciens Kamuina Nsapu auraient perdu la vie515. Par ailleurs, en juin 2017, les\nFARDC, accompagnés d’environ 70 miliciens Bana Mura, sont entrés à pied dans le village\nde Tshinota516. Les miliciens Bana Mura étaient habillés en civil, parlaient la langue\nchokwe et possédaient des armes de chasse sur lesquels était inscrit « RDC » ainsi que\nbâtons avec des clous517. Ils ont commencé à tirer sur la population qui a alors pris la fuite\net un témoin explique avoir vu plusieurs personnes tomber mortes518. Un autre habitant, de\nretour après deux semaines de fuite, a pu constater une cinquantaine de morts dans le\nvillage dont au moins une femme et un enfant de 3 mois. Les personnes avaient été tuées\npar arme à feu, bâton, couteau, et machette519. De nombreuses habitations ont aussi été\npillées ou détruites520. Par ailleurs, des affrontements violents entre les FARDC et les\nmiliciens Kamuina Nsapu ont eu lieu en mars 2017 dans le village de Sumbula. Le bilan de\nces affrontements est inconnu mais la MONUSCO a localisé six fosses communes dans le\nvillage521."},{"id":"a-hrc-38-crp-1-p0204","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"204","seq":204,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI considère que les éléments de preuve qu’elle a collectés ne donnent pas la\nmesure, ni de la violence, ni du nombre d’affrontements qui ont eu lieu entre les miliciens\nKamuina Nsapu et les FARDC dans cette partie du territoire de Kamonia, et encore moins\ndu nombre de civils qui auraient perdu la vie. Par ailleurs, les milices Bana Mura ont été\nactives sur cette partie du territoire et ont mené des opérations conjointes avec les FARDC,\npar exemple dans le village de Tshinota. Le rôle exact joué par les milices Bana Mura sur\ncette partie du territoire reste néanmoins à clarifier. L’EEI est d’avis que des enquêtes\ncomplémentaires sont nécessaires.\nAxe au sud de la cité de Mutena"},{"id":"a-hrc-38-crp-1-p0205","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"205","seq":205,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI a documenté des actes de violence commis par la milice Kamuina Nsapu et les\nforces de défense et de sécurité dans les villages de Mudjadja, Diboko et Mutshima, tous\nsitués au sud de la cité de Mutena, dans une zone où la population est majoritairement luba."},{"id":"a-hrc-38-crp-1-p0206","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"206","seq":206,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"La milice Kamuina Nsapu, composée d’hommes, de femmes et de nombreux enfants,\nest arrivée dans le village de Diboko autour du 20 mars 2017. Ils ont pris le contrôle du\nvillage et y ont installé un tshiota522. Un témoin explique que le tshiota de Diboko était\nl’état-major des miliciens Kamuina Nsapu où ils se réunissaient tous les lundi matin, et\nqu’ils avaient d’autres postes de contrôle dans les alentours du village523. La milice a\nmassivement recruté au sein de la population, majoritairement des enfants524. Comme\npartout ailleurs au Kasaï, la milice Kamuina Nsapu s’est attaquée aux personnes\nreprésentants l’autorité étatique, ainsi qu’à toutes autres personnes perçues comme traitre\nou proche des autorités étatiques. « Justice » était rendue au niveau du tshiota, et le plus\nsouvent la sentence était la décapitation. De nombreux cas de décapitation ont été\ndocumentés525. Pendant la période où la milice contrôlait le village, les miliciens ont par\nexemple tué au tshiota une femme d’une vingtaine d’années qu’ils accusaient de téléphoner\naux autorités ainsi que son père venu plaider la cause sa fille. Leurs têtes ont ensuite été\nramenées à leur famille526. Les miliciens Kamuina Nsapu ont également tué une femme\nagent de la PNC, coupé ses deux seins et son vagin avant de la décapiter527. Un témoin\nestime qu’au moins trente personnes ont perdu la vie pendant l’occupation du village par\nles miliciens528 et au moins une vingtaine de corps ont été enterrés entre fin avril et fin\nmai529. Les miliciens Kamuina Nsapu ont également détruit les biens et les maisons des\npersonnes qu’ils avaient décapitées530, saccagé l’Eglise catholique de Diboko et menacé de\nmort le prêtre à plusieurs reprises531."},{"id":"a-hrc-38-crp-1-p0207","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"207","seq":207,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le 10 juin 2017, les FARDC sont intervenus à Diboko. Les affrontements entre les\nmiliciens Kamuina Nsapu, dont de nombreux enfants munis de bâtons ou parfois de\nmachettes, et les FARDC ont duré deux ou trois jours. Il y a eu de nombreux morts lors de\nces affrontements, majoritairement des miliciens mais aussi plusieurs habitants, au moins\ntrois d’après les informations collectées532. 43 corps ont été enterrés suite aux\naffrontements533. Les FARDC, accompagnés de personnes habillées en civil, ont ensuite\npillé de nombreuses habitations du village de Diboko534. Lors d’une mission d’enquête\nconduite en Angola en juin 2017, le HCDH a par ailleurs documenté que le 10 juin 2017,\nentre 60 et 90 hommes, femmes et enfants, ont été tués dans une église pentecôtiste par le\ntir, de ce que les témoins interrogés ont décrit comme un lance-roquette, dans les alentours\nde Diboko535."},{"id":"a-hrc-38-crp-1-p0208","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"208","seq":208,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"En mai 2017, des affrontements ont eu lieu dans le village de Mudjadja entre des\nFARDC et des miliciens Kamuina Nsapu. Au cours de ces affrontements de nombreux\nmiliciens ont perdu la vie536. Plus tard, au mois de mai 2017, au milieu de la nuit, des\nmiliciens Kamuina Nsapu537 sont passés de maison en maison emmenant les hommes du\nvillage au prétexte de devoir les faire baptiser538. De nombreuses personnes qui avaient fui\nles violences dans le territoire de Kamonia avaient trouvé refuge où s’étaient retrouvées\nbloquées dans le village de Mudjadja et plusieurs d’entre-elles faisaient partie des hommes\narrêtés cette nuit-là539. Au moins 186 hommes du village de Mudjadja ont été amenés par\nles miliciens Kamuina Nsapu au tshiota du village de Diboko540. Là, accusés d’être des\n« petits cochons », ils tous été décapités devant une partie de la population. Des corps ont\naussi été coupés en morceaux541. Un témoin raconte avoir vu un peu plus tard dans la\njournée, les miliciens se promener avec des têtes et des morceaux de corps humains dans le\nvillage542. Certains corps ont été enterrés, d’autres jetés dans des latrines543. Le lendemain\nsoir, les femmes du village de Mudjadja ont été informées par le chef du village de\nMudjadja que tous les hommes amenés la veille avaient été tués au tshiota de Diboko544.\nD’après un témoin, les hommes du village de Mudjadja auraient été attaqués car les\nmiliciens Kamuina Nsapu les pensaient complice des FARDC lors des affrontements qui\navaient eu lieu début mai 2017 dans le village de Mudjadja entre des FARDC et des\nmiliciens Kamuina Nsapu545."},{"id":"a-hrc-38-crp-1-p0209","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"209","seq":209,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Une victime explique qu’elle a entendu dire que les miliciens Kamuina Nsapu\ncomptaient revenir chercher les femmes du village de Mudjadja mais que cela ne s’est pas\nproduit car les FARDC sont intervenus dans le village de Diboko546. Un autre témoin\nexplique que lorsque l’information de la mort des hommes a été donnée aux femmes du\nvillage, il leur a été demandé de se répartir entre les hommes encore présents dans le\nvillage, y compris avec des habitants qui n’étaient pas des miliciens Kamuina Nsapu.\nCertaines femmes ont accepté cette proposition et d’autres ont refusé547."},{"id":"a-hrc-38-crp-1-p0210","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"210","seq":210,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Début mars 2017, un petit groupe d’une dizaine de miliciens Kamuina Nsapu est aussi\narrivé dans le village de Mutshima. Ils ont alors procédé à la destruction des bâtiments de\nl’administration publique, c’est-à-dire les bureaux de la PNC, le parquet, le ministère\nprovincial des mines, les résidences du capitaine de la PNC et la DGM548. Le jour de leur\narrivée, il y a eu des affrontements entre les miliciens et des FARDC venus de Tshikapa.\nUn FARDC a été tué et décapité causant la fuite des militaires549. Dans les jours suivants,\nd’autres miliciens Kamuina Nsapu, y compris des enfants, sont arrivés en grand nombre et\nont installé un tshiota550. Ils ont invité ou contraint les villageois à venir se faire baptiser au\ntshiota et ont enrôlé dans la milice des habitants dont des filles et des garçons551. A leur\narrivée, ils ont tué quatre agents de la PNC et un agent de l’ANR552. Ils se sont ensuite\nattaqués à la population civile tuant et décapitant des habitants pendant toute la période où\nils ont occupé le village553. Ils ont également brûlé des maisons et détruits des biens de la\npopulation civile554."},{"id":"a-hrc-38-crp-1-p0211","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"211","seq":211,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"A l’arrivée des FARDC sur l’axe au sud de la cité de Mutena en juin 2017, les\npopulations de Diboko et d’autres villages du territoire de Kamonia se sont réfugiées à\nMutshima555, et un commandant Kamuina Nsapu a demandé à la population de se rendre\ndans la brousse à cause des affrontements. Les jours suivants, les miliciens Kamuina Nsapu\nont systématiquement pillé les maisons ainsi que les églises556. Les FARDC sont entrés\ndans le village de Mutshima le 15 juin 2017. Ils ont tiré trois coups de feu en l’air et tiré\nune roquette. Toute la population était presque déjà dans la brousse mais trois personnes\nd’une même famille ont été tuées par des balles perdues557. Ils ont également pillé les\nmaisons558. Des enfants mais aussi des adultes sont morts dans la brousse559. Un témoin\nexplique qu’à son retour de la brousse il a vu dans le village les corps de miliciens, dont des\nfilles et des garçons, en état de décomposition560. Quatre fosses communes ont été signalées\nà Mutshima561.\nCité de Kamonia et villages alentours"},{"id":"a-hrc-38-crp-1-p0212","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"212","seq":212,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"La milice Kamuina Nsapu est arrivée dans les environs de la cité de Kamonia fin mars\nou début avril 2017. Comme ailleurs, elle a conduit des attaques contre les personnes qui\nreprésentaient l’autorité étatique ou considérées comme telle. Par exemple, les miliciens\nKamuina Nsapu ont décapité au moins un agent de la PNC, un chef coutumier, le fils d’un\nchef de groupement ainsi que d’autres habitants pour collaboration avec les militaires ou\nappartenance supposée au PPRD562. Une femme raconte que son époux, un agent de\nl’ANR, a été décapité par des miliciens dans le village de Tshinota où il s’était rendu pour\nune réunion. Le lendemain, une dizaine de miliciens Kamuina Nsapu ont frappé à la porte\nde sa maison à Kamonia et lui ont présenté la tête de son mari. Sept miliciens Kamuina\nNsapu l’ont ensuite violée. Ses deux filles de 17 et 20 ans ont également été violées,\nchacune par trois miliciens563. Une fille de 16 ans au moment des faits explique qu’elle a\nété enlevée par des miliciens Kamuina Nsapu dans la cité de Kamonia avant d’être\nconduite à un tshiota non loin du village. Pendant trois jours, elle a dû travailler pour les\nmiliciens mais a surtout dû, sous peine d’être battue, décapiter par trois fois des personnes\ncapturées par les miliciens564. Elle déclare avoir assisté à la décapitation au tshiota de deux\nfemmes, deux hommes et un garçon de 17 ans565. Dans le village de Kata Mossola, un\ntémoin affirme avoir vu ses cinq enfants et un homme chokwe être décapités par des\nmiliciens Kamuina Nsapu parce qu’ils ne parlaient pas tshiluba. En revanche, les deux\nLubas qui se trouvaient avec eux ont eu la vie sauve et se sont vu remettre des vêtements\nrouges566."},{"id":"a-hrc-38-crp-1-p0213","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"213","seq":213,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’arrivée de la milice à proximité de la cité de Kamonia a conduit des habitants\nChokwe, ainsi que quelques Pendes et Tetelas de la cité et des environs, à s’organiser en\nmilices Bana Mura. Les milices Bana Mura se sont formées à Kamonia sous l’impulsion de\nplusieurs chefs locaux chokwes, dont un ancien député national567. Les miliciens Bana\nMura de Kamonia étaient de jeunes hommes de l’ethnie chokwe, parfois pende, habillés en\ncivils et armés de fusils de chasse souvent décrits comme neufs568. Ils ont commencé à\ns’organiser fin mars ou début avril 2017 encouragés par un Colonel de la PNC basé à\nKamonia569. Plusieurs témoins mentionnent la tenue de réunions entre les miliciens Bana\nMura et ce colonel de la PNC570. Un témoin affirme que les armes des miliciens Bana Mura\nont été distribuées par ce colonel, information confirmée par d’autres sources\nsecondaires571. De plus, un témoin explique avoir vu le Colonel de la PNC remettre des\nmunitions de calibre 12 au chef du groupement de Mpumpu. Le même soir de nombreux\nLubas sont arrivés à Kamonia suite à des attaques dans le groupement572. Lorsque les\nmiliciens Kamuina Nsapu ont fait des incursions dans la cité de Kamonia, les miliciens\nBana Mura étaient associés aux forces de défense et de sécurité et ont combattu avec elles.\nUn milicien Bana Mura explique qu’au moment des affrontements entre d’un côté les\nmiliciens Kamuina Nsapu et les forces de défense et de sécurité et les milices Bana Mura\nde l’autre, le Colonel de la PNC de Kamonia a réuni les miliciens Bana Mura et les forces\nde défense et de sécurité au bureau des FARDC pour accomplir un rituel avant d’aller\naffronter ensemble les miliciens Kamuina Nsapu573."},{"id":"a-hrc-38-crp-1-p0214","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"214","seq":214,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les miliciens Kamuina Nsapu ont fait leur première incursion dans la cité de Kamonia\nautour du 10-11 avril 2017 ; d’autres incursions ont eu lieu les jours suivants. Plusieurs\naffrontements ont eu lieu dans la cité de Kamonia entre d’un côté les miliciens Kamuina\nNsapu, y compris des enfants non-armés ou en possession de bâtons, et de l’autre, les\nforces de défense et de sécurité et des miliciens Bana Mura574. Le 11 avril 2017, huit ou\nneuf miliciens Kamuina Nsapu, y compris des enfants en possession de bâtons, qui\nvenaient d’entrer dans la cité, ont été tués par arme à feu par les forces de défense et de\nsécurité et des miliciens Bana Mura en face d’un comptoir d’achat de diamants575.\nQuelques jours plus tard, des affrontements d’une plus grande ampleur, qui ont duré trois\njours, ont eu lieu dans la cité. Un témoin a vu les cadavres de 35 miliciens tués dont des\nfemmes et des enfants. Il ajoute qu’il y avait également des victimes dans la population, y\ncompris des enfants, surpris par les affrontements576. Cette estimation est confirmée par\ntrois témoins577. Un autre témoin indique avoir vu le corps de 28 miliciens Kamuina Nsapu\ntués ce jour-là578. Selon un autre témoin, 18 corps de miliciens Kamuina Nsapu ont été\ncomptabilisés devant la Direction générale des impôts de Kamonia mais il indique que\nd’autres affrontements ont eu lieu dans d’autres quartiers de la cité579. Un témoin décrit\navoir vu une trentaine de miliciens Kamuina Nsapu affronter les forces de défense et de\nsécurité et avoir vu au moins 15 cadavres, pour la plupart des miliciens Kamuina Nsapu, y\ncompris des enfants âgés de 10 ans580. Les corps des victimes des affrontements ont été\nenterrés par la Croix-Rouge congolaise dans des fosses communes581. Des éléments des\nforces de défense et de sécurité ont également trouvé la mort lors de ces affrontements582."},{"id":"a-hrc-38-crp-1-p0215","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"215","seq":215,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"A la même période, les miliciens Bana Mura ont commencé à s’attaquer aux\npopulations lubas et bindis de la cité de Kamonia et à commettre des exactions à leur\nencontre583. D’après les témoignages collectés plusieurs dizaines de personnes, dont des\nenfants, auraient été tués par arme à feu ou arme blanche lors de ces attaques584. Un témoin\nexplique que dans la cité de Kamonia, le 26 avril 2017, son père, un Luba âgé de 75 ans, a\nété poignardé dans le dos puis dans le cou avant d’être tué à coups de machette par des\nmiliciens Bana Mura qui l’accusaient d’être de connivence avec la milice Kamuina\nNsapu585. Un autre témoin indique avoir vu le cadavre de 20 habitants lubas et bindis dans\nla cité tués par les miliciens Bana Mura en dehors de toute présence Kamuina Nsapu586. Un\ntémoin raconte qu’après les incursions des miliciens Kamuina Nsapu, les miliciens Bana\nMura « se sont mis à aller dans toutes les directions et à tuer indistinctement les\nlubaphones. Cela a créé la débandade dans les rangs des lubaphones. L’attaque a\ncommencé à partir du quartier Vatican à droite sur la route qui traverse Kamonia et\nconduisant à Kamako pour s’étendre ensuite aux autres quartiers. Arrivés au quartier du\nmarché, les militaires accompagnés des Bana Mura et sur leurs indications, ont tué par\nballe une fille de 17 ans et sa maman d’environ 47 ans. Elles étaient lubaphones. Ce jour-là,\nj’ai vu au total six corps de civils qu’ils avaient ainsi tués, dont deux femmes et au moins\ndeux enfants dont un garçon et une fille »587."},{"id":"a-hrc-38-crp-1-p0216","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"216","seq":216,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les miliciens Bana Mura ont également pillé les biens et les habitations des\nlubaphones et des Bindis et incendié nombre de leurs habitations588. Un soir des miliciens\nBana Mura ont attaqué le quartier du marché, habité majoritairement par des Lubas. Ils ont\nincendié des maisons après avoir verrouillé certaines portes, laissant brûler vifs leurs\noccupants589. De nombreuses fosses communes ont été identifiées dans la cité590. Pendant\nces attaques des miliciens Bana Mura contre les populations lubas et bindis, les forces de\ndéfense et de sécurité étaient présentes dans la cité de Kamonia. Aucun témoin ne rapporte\nqu’elles sont intervenues pour stopper les miliciens Bana Mura."},{"id":"a-hrc-38-crp-1-p0217","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"217","seq":217,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Des éléments FARDC sont eux-aussi accusés d’avoir commis des exécutions\nsommaires, des enlèvements d’enfants et des viols dans la cité de Kamonia, en avril-mai\n2017. Alors qu’elles tentaient de fuir, cinq filles ont été arrêtées par cinq FARDC. Elles ont\ntoutes été jetées par terre et déshabillées. Au moins l’une d’entre elles a été violée par trois\nFARDC591. Une femme raconte que pendant la période où les miliciens Kamuina Nsapu\napprochaient, elle a été violée par cinq éléments FARDC alors qu’elle faisait sa toilette à la\nrivière592. A la même période, une victime qui allait chercher du bois avec une autre femme\ndu village a été entourée par cinq éléments FARDC. Elle raconte : « un soldat m’a mis du\nlinge dans la bouche. Ils m’ont maintenue debout en écartant mes bras, deux soldats m’ont\nécarté et maintenu les jambes en arrachant mes vêtements. Un soldat a arraché mes sous-\nvêtements et deux ont continué à maintenir mes bras. Quatre soldats m’ont pénétrée avec\nleur sexe tour à tour. Un des quatre a frottée son doigt par terre avant de pénétrer mon\nvagin avec. Je suis tombée par terre et j’ai perdu connaissance ». Elle a toujours des\nséquelles physiques593. Des éléments FARDC se sont aussi introduits dans la maison d’une\nfemme en pleine nuit. Après l’avoir déshabillée, les éléments FARDC ont demandé à son\nfils de 18 ans d’avoir des relations sexuelles elle. Devant le refus du fils, les FARDC l’ont\ntué, lui enfonçant une baïonnette dans le cœur. Trois FARDC l’ont ensuite violée avant de\npartir avec ses trois autres garçons âgés de 12, 14 et 16 qui sont toujours portés disparus594."},{"id":"a-hrc-38-crp-1-p0218","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"218","seq":218,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Dans le village voisin de Tshimunde, au début du mois d’avril 2017, des dizaines de\npersonnes ont été tuées par des miliciens Bana Mura, accompagnés des forces de défense et\nde sécurité595. Un témoin explique que 30 personnes ont été enterrées après l’incident dans\nle village, dont de nombreuses femmes lubas596. Un témoin raconte que des personnes ont\nété tuées parce qu’elles ne savaient pas parler chokwe597. Cette attaque a probablement eu\nlieu en réaction à l’arrivée des miliciens Kamuina Nsapu dans le village de Tshimunde qui\nauraient ciblés les populations chokwes et pendes du village598. Les miliciens Bana Mura\nsont intervenus avec et sous le commandement des forces de défense et de sécurité pour\ndéloger les miliciens Kamuina Nsapu du village de Passu. Les forces de défense et de\nsécurité et les miliciens Bana Mura ont encerclé discrètement le tshiota autour duquel se\ntrouvaient une centaine de miliciens Kamuina Nsapu. Les forces de défense et de sécurité\net les miliciens Bana Mura ont alors tiré sur les miliciens Kamuina Nsapu qui, paniqués,\nont fui. Les miliciens Bana Mura les achevaient alors avec des lances. De multiples\nmiliciens Kamuina Nsapu ont perdu la vie dans cette attaque599."},{"id":"a-hrc-38-crp-1-p0219","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"219","seq":219,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"En dehors de de la cité de Kamonia, l’EEI a collecté d’autres allégations d’attaques\ncommises contre la population civile luba par les milices Bana Mura entre avril et mai\n2017, agissant seules ou parfois de concert avec les forces de défense et de sécurité, qui\nrequièrent des enquêtes supplémentaires. Ces allégations concernent des cas de meurtres\nd’hommes, de femmes et d’enfants, de viols et de destructions d’habitations par le feu\nparfois avec les habitants à l’intérieur dans les villages de Tshisenga, Mpasso,\nMukuandjanga600. L’EEI a également reçu une allégation crédible d’affrontements entre les\nFARDC et les miliciens Kamuina Nsapu dans le village de Kamondele au cours desquels\nde nombreuses personnes auraient perdu la vie601."},{"id":"a-hrc-38-crp-1-p0220","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"220","seq":220,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Suite aux attaques et meurtres ciblés des miliciens Bana Mura, la population luba de\nla cité de Kamonia a quitté en masse la cité. Un groupe d’une centaine de Lubas essayant\nde fuir la cité de Kamonia a été stoppé à une barrière tenue par des miliciens Bana Mura\navant même la sortie de la cité de Kamonia empêchant les Lubas de partir602. Un témoin\nraconte que les Lubas auraient réclamé le droit le quitter la cité et des membres des forces\nde défense et de sécurité auraient alors tiré en l’air pour les disperser avant d’effectuer des\ntirs ciblés603."},{"id":"a-hrc-38-crp-1-p0221","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"221","seq":221,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI a reçu de nombreux témoignages concernant des incidents qui se seraient\nproduits lors de la fuite des civils lubas sur l’axe reliant la cité de Kamonia à la ville de\nTshikapa. Des cas de viol, d’exécution sommaire par arme blanche, et de mauvais\ntraitement commis par un groupe Bana Mura ont été rapportés. Des éléments FARDC\nauraient extorqué, battu et violé des civils fuyant les violences. Des barrières avaient été\nérigées sur la route et étaient tenues soit par des miliciens Bana Mura, soit par les forces de\ndéfense et de sécurité soit conjointement, notamment au moment des incidents entre les\nmiliciens Kamuina Nsapu d’une part et les forces de défense et de sécurité et les Bana\nMura d’autre part en avril 2017. Plusieurs cas documentés sont résumés ci-dessous604."},{"id":"a-hrc-38-crp-1-p0222","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"222","seq":222,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Fuyant Kamonia, une femme rapporte qu’elle a été arrêtée par des miliciens Bana\nMura qui ont tué sa mère à coups de poignard. Son bébé âgé de 4 mois s’est ensuite noyé\ndans rivière Kapopa alors qu’elle tentait de la traverser à la nage. Au niveau de Mugamba,\nelle a croisé des FARDC qui ont proposé de les accompagner. Comme le témoin n’avait\npas d’argent un FARDC a décidé de la violer en guise de rémunération ; cela s’est passé\ndevant d’autres personnes. Une autre jeune fille aurait également été violée à cet endroit605."},{"id":"a-hrc-38-crp-1-p0223","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"223","seq":223,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Une femme explique avoir été attaquée et brutalisée par un groupe de miliciens Bana\nMura fin mai 2017 alors qu’elle fuyait. Deux miliciens Bana Mura l’ont ensuite maintenue\npendant qu’un autre l’a déshabillée et pénétrée de force. Selon le témoin une trentaine de\nfemmes auraient été violées par les miliciens Bana Mura606. Au niveau de Lunyanya, à 15\nkm de Kamonia, à une barrière des miliciens Bana Mura demandaient leur ethnie aux gens\nqui fuyaient. Lorsque deux personnes ont répondu bindi, les miliciens Bana Mura les ont\nemmenées dans la brousse et les ont tuées à coup de fusil607. Une famille en fuite vers\nTshikapa a été arrêtée par huit miliciens Bana Mura en sortant du village de Shamutoma.\nAyant compris que le père de famille était luba, les miliciens Bana Mura lui ont intimé\nl’ordre d’avoir des relations sexuelles avec ses filles. Devant son refus, les miliciens Bana\nl’ont battu avec des bouts de bois et des machettes avant de l’égorger. La mère de famille a\nalors vu son enfant de quatre mois, tenu par la gorge, être frappé contre un arbre, puis jeté\npar terre. Elle a ensuite été poignardée à plusieurs endroits alors qu’elle tentait de protéger\nson bébé. L’un des miliciens Bana Mura l’a alors violée608."},{"id":"a-hrc-38-crp-1-p0224","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"224","seq":224,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Au niveau de la forêt de Tshiakafuti, un village à environ 10km de Kamonia, un\ngroupe de personnes fuyant les violences a été arrêté par un groupe d’une dizaine des\nFARDC. Les membres du groupe ont été battus et se sont fait voler leur argent. Une\nmajorité de personnes n’avaient cependant pas d’argent pour payer les FARDC. Ces\nderniers ont alors choisi au hasard des femmes qu’ils ont violées pendant que deux\nmilitaires maintenaient le reste du groupe sous la menace d’une arme609. Dans un autre cas,\nune femme enceinte de sept mois qui fuyait avec quatre autres femmes vers Tshikapa a\ncroisé un groupe de FARDC. Les autres femmes se sont enfuient mais en raison de sa\ngrossesse elle n’a pas réussi à s’enfuir. Un élément FARDC l’a alors attrapée et violée\npendant que les autres FARDC pourchassaient les autres femmes du groupe. Elle a ensuite\nrepris la route et est tombée un peu plus loin, sur des miliciens Bana Mura armés de fusils\net de machettes et elle a alors été violée une seconde fois par un milicien Bana Mura610."},{"id":"a-hrc-38-crp-1-p0225","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"225","seq":225,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Des témoins ont décrit avoir traversé des villages désertés, d’autres brûlés et vu de\nnombreux cadavres, notamment de femmes et d’enfants611. Un témoin explique qu’en\nfuyant, il a traversé des villages vidés de leurs habitants et vu de nombreux cadavres le long\nde la route et des rivières612. Entre Kamonia et le village de Shakafusthi, des cadavres\njonchaient la route. Un témoin indique avoir une cinquantaine de cadavres en majorité des\nhommes mais aussi des femmes et des enfants dont un garçon de 6 ans et deux filles de\nquatre et deux ans613."},{"id":"a-hrc-38-crp-1-p0226","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"226","seq":226,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Un témoin explique qu’un jour un Général des FARDC est venu en visite à Kamonia\net que les habitants l’ont informé de la présence de miliciens Bana Mura sur la route entre\nKamonia et Tshikapa. Une semaine après sa visite, le témoin a pris la route de Kamonia\npour Tshikapa avec de nombreuses autres personnes et les miliciens Bana Mura n’étaient\nplus en place sur cet axe au moment de leur passage614."},{"id":"a-hrc-38-crp-1-p0227","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"227","seq":227,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI est particulièrement choquée par le nombre d’actes de violence commis par\ntous les acteurs du conflit contre les populations civiles démunies qui fuyaient les violences\net ceci dans toutes les zones documentées. Par exemple, en fuyant de Tshinota à Kamonia,\nune femme rapporte que son mari a été arrêté et décapité par les miliciens Kamuina Nsapu\nqui tenaient une barrière615. Une autre femme raconte qu’elle a été violée par trois miliciens\nKamuina Nsapu en fuyant Tshikapa616. Une femme décrit sa fuite du village de Kabeya-\nKamwanga vers la ville de Kikwit : « [m]on mari, [ma famille est moi] avons alors pris la\nfuite. Dans la brousse, nous avons croisé un groupe de [miliciens Kamuina Nsapu]. Deux\n[miliciens Kamuina Nsapu] sont restés avec nous et les autres sont partis. Ils nous ont\nensuite demandé de nous déshabiller afin de voir si personne ne portait de gris-gris. Ma\ntante […] qui portrait une corde à la hanche fut aussitôt décapitée. Ceux qui n’avaient pas\nde […] fétiches, ont été libérés. Nous [avons] continué jusqu’à la ville de Kananga, dans la\nprovince du Kasaï Central, où nous nous sommes cachés dans une maison inhabitée. Le\nlendemain matin vers 8h30, cinq soldats FARDC […] nous ont trouvé dans la maison. Sous\nla menace des armes, ils nous ont demandé notre identité. Ils ont ensuite enlevé mon mari\n[…]. Après leur départ, j’ai fui avec mes enfants vers Tshikapa, province de Kasaï, en\nempruntant un véhicule. En chemin nous avons rencontré trois [miliciens Kamuina Nsapu]\nqui ont arrêté la voiture et procédé à une fouille de tous les passagers […]. Ils ont décapité\nun passager qui portait une corde à la hanche et nous ont laissé partir. Nous avons rencontré\nplusieurs cadavres de soldat FARDC. Au niveau d’une barrière vers Kikwit, à côté du\nvillage Luanga Tshima, Province de Kwilu, entre quarante et cinquante soldats ont arrêté\nnotre véhicule, nous ont fait descendre et ont fouillé les passagers à la recherché de gris-\ngris. Certains soldats ont ensuite choisi des femmes qu’ils ont retirées du groupe pour les\nvioler. Deux parmi eux, m’ont conduite à côté dans la brousse et m’ont violée chacun en\nm’intimant l’ordre de me laisser faire au risque de me tuer. Ils m’ont ensuite ramenée dans\nle véhicule et nous avons continué notre chemin jusqu’à Kikwit, province de Kwilu.\nQuinze femmes dont six mineures ont été violées ce jour-là »617."},{"id":"a-hrc-38-crp-1-p0228","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"228","seq":228,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Une partie importante des viols documentés par l’EEI a été commise par des éléments\nFARDC contre des femmes en fuite et donc particulièrement vulnérables alors même que\nles FARDC se doivent d’assister les populations618. Ainsi, une femme qui fuyait avec ses\nenfants et une fille de 13 ans rapportent leur rencontre avec des éléments FARDC après une\nsemaine de marche dans la forêt. La femme a été trainée derrière un arbre et battue à coups\nde crosse de fusil pendant qu’un FARDC menaçait ses enfants avec une arme pour ne pas\nqu’ils crient. Devant ses enfants, 10 éléments FARDC lui ont alors fait subir des\nattouchements et l’ont violée avant de la laisser partir. La jeune fille de 13 ans a été violée\npar cinq éléments FARDC. Elle raconte que le premier a mis un doigt dans son vagin avant\nde la pénétrer et que les quatre autres FARDC l’ont ensuite violée à tour de rôle619. Dans un\nautre cas, après la décapitation de son mari par des miliciens Kamuina Nsapu en mars\n2017, une femme fuyant le village d’Akele, a croisé 10 FARDC. Trois d’entre eux lui ont\ndemandé de choisir entre la vie et la mort avant de la jeter à terre et de la déshabiller. Ils\nl’ont ensuite violée620. Une autre femme fuyant les violences dans la province du Kasaï\navait trouvé un camion de FARDC pour la transporter vers la ville de Kikwit. En chemin,\nle chauffeur s’est arrêté et lui a indiqué que si elle ne lui donnait pas d’argent, il ferait ce\nqu’il voulait d’elle. Il l’a ensuite violée avant de l’abandonner au bord de la route621. Une\nautre victime explique qu’en fuyant avec d’autres personnes le village de Katsikalé et alors\nqu’elles avaient trouvé refuge dans de petites huttes de cultivateur, des FARDC sont\narrivés. Sept FARDC ont violé sa nièce âgée de 19 ans puis quatre d’entre eux l’ont violée\navant de faire subit le même sort à une autre femme devant son mari qui avait été ligoté622.\nSecteur de Lovua-Longatshimo"},{"id":"a-hrc-38-crp-1-p0229","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"229","seq":229,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"En mars 2017, la milice Kamuina Nsapu a atteint le secteur de Lovua-Longatshimo.\nDans ce secteur, la population était composée majoritairement de Chokwes ainsi que de\nnombreux Pendes. Les miliciens Kamuina Nsapu ont installé des tshiota dans plusieurs\nvillages et ont décapité de nombreuses personnes, notamment dans les villages de Senge\n(ou Cinq) et de Mvula-Milenge. Avant l’attaque par les miliciens Bana Mura du village de\nSenge le 24 avril 2017623, la milice Kamuina Nsapu s’y était installée624. Au moins un agent\nde la PNC et plusieurs chefs de villages ont été décapités par les miliciens et plusieurs têtes\nrapportées d’un village voisin625. La milice Kamuina Nsapu a tenté de rallier la population à\nson mouvement insistant sur le fait qu’ils n’attaquaient que les représentants de l’Etat.\nNéanmoins, un témoin rapporte qu’un jour les miliciens avaient réuni des habitants du\nvillage de Senge en leur demandant individuellement leur ethnie. Pour s’assurer que la\npopulation ne mentait pas, les miliciens posaient des questions en tshiluba. Ceux qui\nn’arrivaient pas à répondre dans la langue des Lubas étaient décapités. Huit personnes ont\nainsi été décapitées lors de cet incident626. Les miliciens Kamuina Nsapu ont aussi attaqué\nle village de Mvula-Milenge au mois de mars 2017. Les miliciens, y compris des garçons et\ndes filles entre 7 et 13 ans, avaient un slogan en tshiluba qui signifiait « que cette terre soit\nla vôtre ; si c’est la nôtre, que vous soyez tous exterminés »627. Plusieurs personnes\nrapportent des cas de décapitations ou de blessures par machette commis par les miliciens\nKamuina Nsapu dans le village de Mvula-Milenge628."},{"id":"a-hrc-38-crp-1-p0230","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"230","seq":230,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’arrivée des miliciens Kamuina Nsapu dans le secteur de Lovua-Luthsima a créé un\nmouvement de panique de la population et ceux qui fuyaient étaient considérés par les\nmiliciens comme hostiles au mouvement. Par exemple, en fuyant le village de Mvula-\nMilenge, un groupe de personnes a été stoppé par dix miliciens Kamuina Nsapu. Ils ont\nreproché à deux hommes de les avoir regardés dans les yeux. Ils les ont alors enterrés ne\nlaissant apparaitre que leur tête avant de les décapiter. Ils ont ensuite violé les femmes629.\nUne femme raconte que dans sa fuite, elle a été arrêtée par des miliciens Kamuina Nsapu\nau niveau du village de Muyeji avant d’être conduite dans une église. D’après le témoin,\njusqu’à 45 femmes, certaines avec des enfants ont été gardées dans cette église pendant\nplusieurs jours et y ont été violées630. En mars 2017, trois miliciens Kamuina Nsapu sont\nentrés dans la maison d’une famille dans le village de Kilolo. Ils ont décapité les deux\nparents et l’un des miliciens a jeté à terre, déshabillé violemment, et violé une femme à son\nneuvième mois de grossesse. Les deux autres miliciens ont ensuite introduit leurs doigts\ndans le vagin de la femme en tirant. Elle témoin a abondamment saigné et a accouché\nquelques jours plus tard dans la brousse631."},{"id":"a-hrc-38-crp-1-p0231","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"231","seq":231,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Plusieurs cas de viols commis par les FARDC ont été rapportés lors de ce premier\nmouvement de population. Un témoin raconte avoir fui le village de Senge pour rejoindre\nTshikapa avec un groupe de personnes suite à l’annonce de l’arrivée des miliciens Kamuina\nNsapu. Entre Muyeji et Gombe, le groupe a été intercepté par une vingtaine de FARDC.\nLes FARDC ont, selon le témoin, trié les femmes selon leur âge ou préférences. Ils\nchoisissaient en particulier les femmes accompagnées de leur mari et certaines femmes ont\nété violées devant eux ou de leurs enfants. Le témoin explique avoir été elle-même violée\npar deux FARDC sous la menace d’une arme632. Une autre femme explique avoir été violée\npar deux hommes qu’elle décrit comme des militaires. Quatre autres femmes auraient\négalement été violées lors de cet incident633."},{"id":"a-hrc-38-crp-1-p0232","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"232","seq":232,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"En mars 2017, des milices Bana Mura se sont constituées dans le secteur de Lovua-\nLongatshimo, notamment dans le groupement de Muyeji. Si les milices Bana Mura ont été\ninitialement créées en réaction à l’arrivée des miliciens Kamuina Nsapu dans le secteur,\nelles ont rapidement étendu leurs activités en avril 2017. Loin de se limiter à combattre la\nmilice Kamuina Nsapu, les milices Bana Mura ont conduit des attaques meurtrières contre\nles populations civiles lubas dans de multiples localités du secteur de Lovua-\nLongatshimo634. Par exemple, entre le 24 et le 26 avril 2017, de très nombreux hommes,\nfemmes et enfants lubaphones ont été blessés, mutilés ou tués par arme à feu ou machette\nlors d’attaques lancées par les miliciens Bana Mura dans le groupement de Muyeji, et en\nparticulier dans les villages de Senge, Camp Kwilu, Kakondo et Mvula-Milenge. Le\nnombre de victimes de ces attaques est assurément de plusieurs centaines. Le niveau de\nviolence qui a été utilisé par les milices Bana Mura contre les populations lubaphones est\nextrêmement élevé. Au regard des éléments de preuve collectés, l’EEI est d’avis que ces\nattaques, qui ont toutes eu lieu au cours de la même semaine d’avril 2017, étaient\nplanifiées. Des réunions au cours desquelles les attaques de la population luba du\ngroupement ont été discutées ont eu lieu635. Plusieurs témoins mentionnent également des\ndistributions d’armes, des fusils de chasse et des machettes, avant cette série d’attaque636."},{"id":"a-hrc-38-crp-1-p0233","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"233","seq":233,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le 24 avril 2017, des miliciens Bana Mura ont attaqué la population lubaphone du\nvillage de Senge. Le chef du village était issu de l’ethnie chokwe et le village appartient au\ngroupement de Muyeji dont le chef est également d’ethnie chokwe et identifié comme le\nchef des miliciens Bana Mura dans le groupement637. Un témoin indique qu’avant l’attaque\ndes miliciens Bana Mura, il a vu le chef du village se réunir régulièrement avec le chef de\nl’ANR dans le village de Senge. Suite aux informations circulant à propos d’attaques dans\nd’autres villages, le chef du village a rassuré les habitants lubaphones en leur indiquant que\nles miliciens Bana Mura n’attaqueraient pas le village. Le chef du village de Senge faisait\nnéanmoins partie des assaillants lors de l’attaque638. Le chef du groupement de Muyeji\nserait venu dans le village avant l’attaque pour distribuer des armes et des munitions639 et\ndes barrières avaient été érigées pour empêcher les lubaphones de quitter le village640.\nL’attaque du village de Senge visait les habitants lubas du village. Les Chokwes ou les\npersonnes qui parlaient la langue chokwe ont été épargnés lors de l’attaque641. De plus, un\ntémoin précise que quelques jours avant l’attaque, les femmes et les enfants chokwes et\npendes avaient quitté le village642. L’un des assaillants a répondu aux supplications de sa\nvictime d’ethnie luba par les mots suivants : « nous sommes venus tuer, nous n’allons\nlaisser personne »643."},{"id":"a-hrc-38-crp-1-p0234","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"234","seq":234,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les miliciens Bana Mura étaient très nombreux, avec du cirage noir sur le visage, de\nla poudre blanche autour des yeux, et de bande de moustiquaires blanches autour de la tête.\nIls étaient armés de fusils de chasse qui portaient la mention « RDC » et de machettes de la\nmarque Tramontina644. Certains assaillants, principalement des jeunes hommes chokwes,\npendes et tetelas, habitaient le village de Senge ou venaient de villages avoisinants645. Les\nchefs de l’ANR et de la DGM de Senge ont apporté leur soutien aux miliciens646. Aucun\ntémoin ne mentionne la présence de FARDC lors de cette l’attaque."},{"id":"a-hrc-38-crp-1-p0235","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"235","seq":235,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les miliciens Bana Mura se sont attaqués à la population lubaphone dans les rues\nmais aussi dans leur maison. Une victime explique avoir été témoin de l’exécution d’un\nmembre de sa famille dans sa maison et n’avoir survécu que parce qu’il s’était fait passer\npour mort647. Les miliciens Bana Mura ont mis le feu à des maisons alors que les habitants,\ndont des enfants, se trouvaient à l’intérieur648. Une femme raconte qu’après avoir jeté son\nbébé au sol, les miliciens Bana Mura l’ont battue à coups de machette. Elle a été lardée par\nde nombreux coups de machette sur le corps et notamment à la tête et laissée pour morte\npar les miliciens649. Des miliciens Bana Mura sont entrés dans une maison en défonçant la\nporte avant d’attaquer une femme avec des machettes, la blessant à la tête et au bras. Ils se\nsont ensuite attaqués à ses enfants âgés de 4 à 14 ans les mutilant à la tête et aux bras à\nl’aide de machettes. Un de ses enfants, âgé de deux ans et demi a été tué, sectionné en deux\nà la hauteur de l’abdomen par un coup de machette. Les miliciens ont ensuite extrait ses\nintestins et les ont entourés autour de la mère et des enfants650. D’autres victimes ont été\nblessées et tuées par balle, dont une femme enceinte qui a ensuite été éventrée et dont les\nfœtus de ses jumeaux ont été sortis651."},{"id":"a-hrc-38-crp-1-p0236","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"236","seq":236,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Plusieurs témoins indiquent avoir vu de nombreux cadavres lors de leur fuite du\nvillage, dont ceux de femmes et d’enfants652. De plus, nombre de témoins ont perdu toute\ntrace de membres de leur famille depuis cette attaque653. Un rapport publié par la\nFédération internationale des ligues des droits de l'homme (FIDH), Organisation non-\ngouvernementale, suite à une mission d’enquête dans les camps de réfugiés en Angola,\ndécrit un modus operandi identique après avoir interrogé 30 témoins de l’attaque du village\nde Senge et parle de plusieurs centaines de personnes tuées654. Le HCDH, après une\nmission conduite en Angola en juin, confirmé l’identité de 116 personnes tuées, deux\nenlevées, et 13 blessées dans l’attaque du village de Senge.655."},{"id":"a-hrc-38-crp-1-p0237","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"237","seq":237,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les rapports de la FIDH et du HCDH décrivent également en détail l’attaque de\nl’hôpital de Senge. Entre 90 et 95 patients, des membres du personnel médical ainsi que\nplusieurs dizaines de civils qui s’étaient réfugiés dans l’hôpital auraient été tués au cours de\ncette attaque, principalement par balle, à coup de machette et brûlés vifs. Un nombre\nimportant de victimes aurait également été décapitées656. Ces deux rapports restituent\négalement plusieurs cas de viols de femmes par les miliciens Bana Mura, en particulier\navec des objets, tel que les canons des fusils ou des bâtons en bois657. Le rapport de la\nFIDH décrit également des cas de mutilations de cadavres : des corps d’hommes émasculés\ndont le pénis avait été déposé sur leur front et des cadavres de femmes avec le vagin coupé\nou des bâtons dans le vagin658."},{"id":"a-hrc-38-crp-1-p0238","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"238","seq":238,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le 24 ou le 25 avril 2017, une attaque similaire a eu lieu dans le village voisin de\nCamp Kwilu. Le village de Camp Kwilu était majoritairement habité par des Lubas. Les\nhabitants chokwes ont été épargnés lors de l’attaque659. D’après les informations recueillies,\nle chef du village de Camp Kwilu aurait participé à une réunion avec des chefs de villages\nvoisins d’origine chokwes au cours de laquelle aurait été discuté l’attaque des Lubas\naccusés d’être responsables de l’arrivée de la milice Kamuina Nsapu. Il en aurait rendu\ncompte aux villageois en indiquant qu’il avait passé un accord avec les autres chefs pour\nque le village de Camp Kwilu ne soit pas attaqué660. De très nombreux miliciens Bana\nMura, des hommes armés de machettes et de fusils de chasse, avec de la cendre noire sur le\nvisage et des moustiquaires blanches autour de la tête sont entrés dans le village en criant\nen langue chokwe « Nous allons tuer tous les gens de Kamuina Nsapu » et « chokwe,\nlevez-vous ! Bana Mura levez-vous !»661."},{"id":"a-hrc-38-crp-1-p0239","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"239","seq":239,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Selon le BCNUDH de la MONUSCO l’attaque du village de Camp Kwilu aurait pu\nconduire à la mort d’une centaine de personnes662. Les informations collectées par l’EEI\nvont dans le même sens. Plusieurs témoins ont indiqué avoir vu des habitants tués par balle\npar les miliciens Bana Mura ou brûlés dans leurs maisons après y avoir été enfermés par\ndes miliciens Bana Mura663. Une victime raconte avoir vu les miliciens Bana Mura en train\nde tuer des habitants avec des armes à feu et des machettes avant d’être elle-même attaquée\net frappée par deux hommes à coups de machette à la tête et aux bras. Un des assaillants lui\naurait dit « Rentrez chez vous ! Ça, ce n’est pas votre terre ! ». Le témoin a survécu en se\nfaisant passer pour mort664. Un témoin dit avoir vu de très nombreux miliciens Bana Mura\nau bord de la rivière qui disaient « nous allons tous vous tuer vous les lubaphones, puis\nnous allons rester seuls sur notre sol ». Il a alors vu de nombreux Lubas, dont des femmes,\nêtre décapités où avoir les pieds et les bras sectionnés. Il indique avoir vu au moins à trois\nreprises les miliciens prendre de jeunes enfants et les jeter dans la rivière depuis une\npirogue665. Une personne qui a traversé le village de Camp Kwilu le lendemain de l’attaque\ndéclare avoir vu un grand nombre de cadavres dans le village, si nombreux qu’il n’était pas\npossible de les compter. Elle a vu des corps avec des blessures par balles, par machettes ou\nbrûlés666. Une autre personne fuyant le village, a vu 15 cadavres, d’hommes, de femmes et\nd’enfants âgés de 3 à 10 ans et une autre a vu les corps de quatre hommes, trois femmes et\ntrois enfants667. Les biens des habitants ont été pillés et leurs maisons détruites par le feu\npar les miliciens Bana Mura668."},{"id":"a-hrc-38-crp-1-p0240","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"240","seq":240,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"A la même période, le village de Mvula-Milenge a subi une attaque similaire à celle\ndes villages de Senge et de camp Kwilu. Les miliciens Bana Mura sont arrivés dans le\nvillage et ont commencé à tuer avec des armes à feu et des machettes les habitants lubas, y\ncompris les enfants669. Selon les informations recueillies auprès d’un témoin, les miliciens\nBana Mura sont arrivés dans le village de Mvula-Milenge avec des FARDC. Il décrit que\ndes miliciens Bana Mura et des FARDC, opérant ensemble, ont enfermé deux hommes de\nla famille du témoin dans leur maison, avant d’y mettre le feu. Les deux hommes ayant\nréussi à sortir de la maison en feu, ils ont été ligotés sur les ordres d’un FARDC avant que\ndes miliciens Bana Mura ne les tuent à coups de machettes. Les deux hommes ont ensuite\nété éventrés670. Toujours à la même période, les miliciens Bana Mura ont aussi attaqué le\nvillage de Kakondo. Un témoin raconte avoir ouvert sa fenêtre et vu un groupe de 10\nmiliciens Bana Mura tuer son voisin à coups de machette en criant « vous les Lubas nous\nallons vous tuer tous ! Vous allez quitter notre milieu !». Plus tard, le témoin a entendu des\ncoups de feu et a vu trois de ses voisins s’écrouler671."},{"id":"a-hrc-38-crp-1-p0241","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"241","seq":241,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Le BCNUDH de la MONUSCO lors d’une mission d’enquête sur le territoire de\nKamonia a confirmé le viol d’au moins 41 femmes et deux filles par les miliciens Bana\nMura entre le 18 et 25 avril 2017, dans les villages de Muyeji, Mungamba, Camp Kwilu et\nKakondo672. Une femme rapporte que mi-mars 2017, trois hommes présumés miliciens\nBana Mura, l’ont violée. Des mois après ce crime, elle a toujours de sérieuses douleurs\nliées à ce viol673."},{"id":"a-hrc-38-crp-1-p0242","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"242","seq":242,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Suite à cette série d’attaques meurtrières conduites par les miliciens Bana Mura, la\npopulation luba a tenté de trouver refuge dans les villages alentours, en Angola ou vers la\nville de Tshikapa. Ainsi alors que des habitants du village de Senge se trouvaient dans la\nbrousse après l’attaque de leur village, un homme chokwe est venu avertir les personnes en\nfuite que les miliciens Bana Mura étaient sur le point de lancer une attaque sur les Lubas en\nfuite. Cet homme chokwe aurait ensuite été tué par les miliciens Bana Mura, accusé de\ntrahison674. Certains habitants du groupement de Muyeji ont réussi à fuir vers la frontière\navec l’Angola. Un témoin explique que l’armée angolaise est venue secourir les blessés à la\nfrontière dont des femmes avec les seins et des bras coupés et d’autres personnes blessées\npar balle675. Un autre témoin qui fuyait le village de Senge indique que juste après le village\net dans les villages suivants il a vu 20 à 30 cadavres, certains décapités ou éventrés, ainsi\nque le corps d’une femme dont le vagin coupé était posé sur son sein676."},{"id":"a-hrc-38-crp-1-p0243","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"243","seq":243,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De nombreux habitants du groupement de Muyeji ont tenté de fuir les massacres en\ntraversant la rivière Tshikapa. Au bord de cette rivière, au niveau de Kakondo, une barrière\navait été mise en place par les miliciens Bana Mura dans l’objectif d’empêcher la fuite des\nlubaphones677. Ceux parlant la langue chokwe pouvaient passer678. Un témoin raconte qu’il\ny avait de nombreux miliciens Bana Mura. Le groupe dans lequel il se trouvait a accosté de\nl’autre côté de la rivière. L’un des miliciens a dit en langue chokwe « nous allons\nexterminer les Balubas » et les miliciens se sont mis à tirer dans leur direction679. De\nnombreuses personnes, y compris des enfants, ont été tuées et d’autres blessées en tentant\nde fuir dans cette direction680."},{"id":"a-hrc-38-crp-1-p0244","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"244","seq":244,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De nombreux habitants lubaphones lors de leur fuite ont été maltraités, tués et des\nfemmes violées par des miliciens Bana Mura. Par exemple, en fuyant le village de Senge en\ndirection de l’Angola, un groupe de 13 femmes et 13 enfants, est arrivé à une ferme située\nnon loin du village Limite. Ils sont tombés sur un groupe de miliciens Bana Mura. Ayant\nidentifié huit femmes lubas, ils les ont tués. Parmi les cinq femmes restantes une s’est\névanouie et a été laissée sur place, les quatre autres ont été emmenées, gardées par leurs\nassaillants et violées par eux en présence de leurs enfants chaque fois qu’ils en avaient\nenvie pendant quatre jours. Elles et leurs enfants ont réussi à s’échapper.681. Un témoin\nraconte avoir vu un tas d’au moins trente corps à un barrage tenu par des miliciens Bana\nMura dans la localité de Seba682."},{"id":"a-hrc-38-crp-1-p0245","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"245","seq":245,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Certains témoins ont été escortés dans leur fuite par des FARDC jusqu’à Tshikapa683.\nPar contre, les FARDC ne sont pas intervenus pour empêcher les exactions commises par\nles miliciens Bana Mura contre les lubaphones. Par ailleurs, ils ont eux-mêmes violé des\nfemmes rendues particulièrement vulnérables par leur fuite. Par exemple, une femme qui\ntentait de traverser la rivière Tshikapa avec ses enfants, a été violée par dix FARDC à tour\nde rôle devant ses enfants avant qu’ils ne la laisser passer. Le seul qui ne l’a pas touché l’a\nensuite aidée, elle et ses enfants, à traverser la rivière sur une pirogue.684. Dans un autre cas,\nune femme qui fuyait le village de Senge rapporte que huit hommes avec des tenues\nmilitaires l’ont attrapée. Sept d’entre eux l’ont violée chacun leur tour. Elle a depuis des\nséquelles physiques685."},{"id":"a-hrc-38-crp-1-p0246","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"246","seq":246,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Suite aux attaques des miliciens Bana Mura dans les villages du groupement de\nMuyeji, des femmes et des filles lubas, ainsi que des enfants, ont été capturés par des\nmiliciens Bana Mura et transportés dans des fermes de ce même groupement, où ils ont été\nretenus captifs."},{"id":"a-hrc-38-crp-1-p0247","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"247","seq":247,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Arrivé au niveau de la rivière Tshikapa, un groupe de Lubas qui fuyait a été stoppé\npar des miliciens Bana Mura. Les hommes mais aussi les femmes non en âge de procréer\nont été séparés du groupe, décapités et jetés dans la rivière686. Les autres femmes et filles en\nâge de procréer, ainsi que d’autres femmes enlevées à la suite d’attaques des miliciens\nBana Mura dans le secteur de Lovua-Luthsima, ont été emmenées dans des fermes\nappartenant à des individus de l’ethnie chokwe, notamment à Sha-Findji, Tshikala, et\nKisasa dans le groupement de Muyeji687. Dans ces fermes, les femmes ont été réparties\nentre les hommes chokwes688. Une femme raconte qu’un homme lui a mis un bandeau sur\nles yeux et l’a amenée vers la ferme de Sha-Findji. Elle a alors entendu quelqu’un dire\n« vous allez être nos femmes, mettre nos enfants au monde et être nos travailleurs ».\nLorsque le témoin est arrivé à la ferme, elle a été regroupée avec une autre jeune femme et\ndes femmes plus âgées, mais toujours en âge de procréer. Certaines étaient accompagnées\nde leurs enfants. Les femmes ont été réparties entre les hommes chokwes présents. D’après\nle témoin, la personne qui s’est chargée de la répartition des femmes a dit à l’un des\nhommes présents de prendre une femme et de la garder afin de mettre des enfants au\nmonde689. De manière similaire, une autre victime explique qu’après s’être éloignée de la\nrivière, les miliciens Bana Mura sélectionnaient au sein du petit groupe de femmes et\nd’enfants lubas les femmes à leur convenance en disant « toi, tu seras ma femme, toi aussi,\netc... ». La victime a été choisie par un homme chokwe et amenée, avec une autre femme, à\nla ferme de Kisasa690."},{"id":"a-hrc-38-crp-1-p0248","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"248","seq":248,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Les femmes et les filles retenues dans ces fermes étaient sous surveillance permanente\net certaines devaient travailler toute la journée691. Par exemple, une femme raconte qu’elle\nétait entravée et devait travailler aux champs sous la contrainte. Elle a été battue trois pour\navoir refusé de travailler692. Tous les témoignages recueillis supportent que les femmes et\nfilles enlevées ont été violées de manière répétée pendant leur captivité, parfois plusieurs\nfois par jour, souvent pendant des mois693. Un témoin raconte que le premier soir de sa\ncaptivité, l’homme chokwe auquel elle avait été donnée a essayé d’avoir des relations\nsexuelles avec elle. Comme elle résistait, il l’a frappée avec des cordes sur les bras, le dos,\net les jambes. Il l’a ensuite cognée contre un mur et saisi par le cou. Il l’a violée. Elle a\narrêté de résister car elle voulait sauver sa vie. Après cette première nuit, elle a été violée\ntous les jours pendant sa captivité, parfois jusqu’à trois fois par jour694. Une autre femme\nraconte que l’homme chokwe la traitait comme sa femme et l’a forcée à avoir des relations\nsexuelles avec lui sous la menace d’une machette et d’une arme à feu695. Une autre victime\nraconte avoir été violée pendant quatre mois parfois trois à quatre fois par jour696. Cette\njeune femme est tombée enceinte de son assaillant. Certaines femmes ont réussi à s’enfuir,\nparfois avec des enfants, la plupart après des mois de captivité697."},{"id":"a-hrc-38-crp-1-p0249","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"249","seq":249,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Selon plusieurs survivantes, l’intention des auteurs étaient qu’elles mettent au monde\ndes enfants chokwes puisque l’ethnie est transmise par le père698. Par exemple, une femme\nexplique qu’avant les viols, son assaillant lui indiquait qu’il voulait qu’elle mette des\nenfants au monde pour lui699. Certaines femmes sont tombées enceinte lors de leur\ncaptivité700."},{"id":"a-hrc-38-crp-1-p0250","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"250","seq":250,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Des enfants lubaphones de tous âges, parfois seuls ou avec leurs mères, ont également\nété emmenés dans ces fermes. Ils ont souvent été maltraités et malnutris. Par exemple, un\ngarçon d’un an et demi, une fille de 4 ans et une autre de 13 ans ont été retenus dans une\nferme dirigée par des Chokwes pendant des mois. La jeune fille de 13 ans a été violée et le\ngarçon d’un an et demi souffre de malnutrition sévère701. L’EEI a également documenté le\ncas d’une fille de 13 ans retenue en captivité dans une ferme dirigée par des Chokwes dont\nle nom d’origine luba a été changé par un nom chokwe par la personne qui la détenait702.\nL’EEI n’a néanmoins pas été en mesure d’établir une pratique qui irait en ce sens. D’après\nla MONUSCO, des rançons ont parfois été demandées pour la libération des enfants et au\nmoins deux enfants auraient été envoyés en Angola pour y être vendus703."},{"id":"a-hrc-38-crp-1-p0251","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"251","seq":251,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Par ailleurs, une survivante indique qu’un jour une lettre est arrivée qui demandait de\nlibérer les femmes lubas en captivité. L’homme chokwe qui la retenait, l’a alors amenée\nchez le chef du village en pointant une arme sur elle. Le chef du village a demandé à\nl’homme de ne pas la tuer, et celle-ci est retournée à sa captivité704."},{"id":"a-hrc-38-crp-1-p0252","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"252","seq":252,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"En mars 2018, la MONUSCO avait vérifié qu’au moins 87 personnes, dont deux\nfemmes, 49 filles et 15 garçons étaient retenus en captivité dans des fermes du groupement\nMuyeji et avait reçu des allégations sérieuses concernant 39 autres personnes (10 femmes,\n2 hommes et 27 enfants)705. A ce jour, des femmes et des enfants sont toujours retenus dans\ndes fermes du groupement Muyeji par des personnes de l’ethnie chokwe. Au 6 juin 2018, la\nMONUSCO estime qu’au moins 68 enfants seraient encore retenus dans ces fermes706.\nMalgré des plaidoyers réguliers auprès des forces de défense et de sécurité congolaises de\nKananga et de Tshikapa par la MONUSCO leur réaction face à ces crimes reste\ninsuffisante.\nNord du territoire de Kamonia"},{"id":"a-hrc-38-crp-1-p0253","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"253","seq":253,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Au nord de la ville de Tshikapa, dans le secteur de Kasaï- Kabambayi, dans la partie\ndu secteur Bapende qui longe la rivière Kasaï, ainsi qu’à l’extrême sud du territoire d’Ilebo,\nla milice Kamuina Nsapu a été très présente en mars-avril 2017707. Tout comme pour le\nsecteur de Lovua-Longatshimo, l’influence lubaphone se réduit dans cette zone et la rivière\nKasaï marque une frontière naturelle entre deux zones d’influence, luba à l’est et\nchokwe/pende à l’ouest."},{"id":"a-hrc-38-crp-1-p0254","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"254","seq":254,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Dans cette zone, la logique expansionniste de la milice Kamuina Nsapu s’est heurtée à\nune forte résistance des populations chokwes et pendes. Les violences dont les populations\nciviles ont été les premières victimes ont pris un caractère ethnique. Ainsi la milice\nKamuina Nsapu s’est attaquée en particulier à la population chokwe et pende et des\nhabitants chokwes et pendes, organisés en milices se sont, en réaction, attaqués à la\npopulation lubaphone708. L’EEI n’a pas été en mesure de documenter de manière\ncompréhensive l’ampleur des actes de violence dans cette zone. Les éléments de preuve\nrésumés ci-dessous témoignent néanmoins de la commission d’actes de violence très\nsérieux qui requièrent des enquêtes approfondies."},{"id":"a-hrc-38-crp-1-p0255","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"255","seq":255,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Par exemple, dans le village de Shandala dans le secteur de Kasaï-Kabambayi, les\nmiliciens Kamuina Nsapu, y compris des enfants, sont arrivés au mois de mars/avril 2017.\nAprès s’être attaquée aux agents de l’Etat et aux personnes suspectées d’être hostiles au\nmouvement ou de supporter les autorités, la milice Kamuina Nsapu s’en est prise à la\npopulation civile chokwe, notamment aux hommes. Plusieurs personnes chokwes du\nvillage ont été tuées par les miliciens Kamuina Nsapu et au moins une femme chokwe a été\nviolée709. Par ailleurs, un témoin raconte qu’un jour les miliciens Kamuina Nsapu ont lancé\nune attaque contre des miliciens Bana Mura qui tenaient une réunion dans le village et que\ndes Chokwes ont été tués, y compris des enfants, et des maisons incendiées710. Un témoin\nraconte des violences similaires dans le village de Mwalukuaya. Il rapporte des cas de\ndécapitations de Pendes, ainsi que de personnes ne parlant pas tshiluba, et de viols.\nCertaines des femmes qui avaient déjà été violées par voie vaginale et anale par les\nmiliciens Kamuina Nsapu dans ce village, ont plus tard été violées par des miliciens Bana\nMura711. Dans la forêt de Katoka vers le village de Kabambayi, un groupe de personnes\ndont un agent de la PNC est tombé sur des miliciens Kamuina Nsapu. Ces derniers ont\nemmené l’agent de la PNC et l’ont tué. Une fille de 16 ans et sa petite sœur ont alors été\nemmenées au tshiota des miliciens Kamuina Nsapu où elles ont été retenues captives et\ndevaient cuisiner et aller puiser l’eau. Elles ne recevaient pas de nourriture. La jeune fille\nde 16 ans a été violée par un milicien Kamuina Nsapu. Toutes deux ont réussi à s’enfuir712."},{"id":"a-hrc-38-crp-1-p0256","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"256","seq":256,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"De l’autre côté de la rivière Kasaï, tout au sud du territoire de Ilebo, dans le village de\nBiponga, les miliciens Kamuina Nsapu sont arrivés fin avril ou début mai 2017 depuis le\ntshiota installé dans le village de Kabambayi. Plusieurs témoins ont indiqué que les\nmiliciens Kamuina Nsapu, y compris des enfants, sont arrivés en grand nombre et ont\nd’abord détruit les bâtiments publics. Les témoins ont ensuite noté un changement dans\nl’attitude des miliciens Kamuina Nsapu qui se sont attaqués largement à la population\ncivile. Les miliciens ont décapité de nombreux habitants du village et commis beaucoup de\nviols. Ils ont également brûlé de nombre d’habitations713. Une victime raconte que son\népoux, d’ethnie Bashilele, a été décapité le 2 mai 2017 parce qu’il ne pouvait pas parler\ntshiluba. Elle a ensuite été violée par trois miliciens Kamuina Nsapu714. Le jour de cet\nincident, cette survivante affirme avoir vu 18 cadavres de personnes tuées par les miliciens,\nen majorité des Chokwes, Pendes, et Bashileles715. Il y aurait également eu des\naffrontements violents entre les miliciens et les FARDC au cours desquels de nombreux\ncivils auraient perdu la vie, mais cette allégation doit être confirmée716. L’EEI a également\nreçu des éléments de preuve d’exactions commises par des membres de l’ethnie Bashilele\ncontre les Lubas en réaction à l’arrivée de la milice Kamuina Nsapu dans le village de\nBiponga. Ces derniers ont chassé les Lubas vers le village de Kabambayi, mais aussi tués et\nviolés certains habitants lubas717."},{"id":"a-hrc-38-crp-1-p0257","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"257","seq":257,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"L’EEI a également collecté des informations concernant des exactions similaires\ncommises par la milice Kamuina Nsapu dans les villages voisins de Kankala et de\nBashilele au cours de la même période718. Par exemple, une femme explique que fuyant le\nvillage de Bashilele au sein d’un groupe composé d’hommes et de six femmes, elle a été\nstoppée par des miliciens Kamuina Nsapu. Les femmes ont été triées en fonction de la\nlangue parlée et une mère, sa fille ainsi qu’elle-même ont été violées719."},{"id":"a-hrc-38-crp-1-p0258","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"258","seq":258,"section":"C. Janvier-juillet 2017 – explosion des violences dans tout le Kasaï et","text":"Par ailleurs, l’EEI a aussi reçu des éléments de preuve concordants concernant des\nexactions commises par des membres de la communauté pende, organisés en un groupe\nnommé Ecurie Mbe Mbe, contre les lubaphones, au nord de Tshikapa le long de la rivière\nKasaï, en avril et mai 2017. Mi-avril 2017, dans le village à majorité pende de Kavundi,\ndes habitants pendes ont chassé les Lubas du village ou les ont conduits à quitter le village\nen raison de l’arrivée massive d’individus de l’ethnie pende venant de villages\navoisinants720. De nombreux Lubas ont alors traversé la rivière Kasaï et certains se sont\ninstallés dans la ferme de Malanga et celle voisine de Kavundi. Mi-mai 2017, une\ncinquantaine de Pendes, organisés en un groupe nommé Ecurie Mbe Mbe, ont attaqué les\ndeux fermes, armés de fusils de chasse et de machettes721. Lors de cette attaque, les\nassaillants criaient « nous sommes venus pour tuer les Luba »722. Une femme raconte que\nles assaillants ont voulu lui couper la tête, blessant à la tempe l’enfant qu’elle portait dans\nses bras723. Entre quatre et six personnes ont été tuées et une autre blessée lors de cette\nattaque, dont des femmes et un garçon de 15 ans. Un enfant de cinq ans a également été\nenlevé724. Lors de cette attaque, une femme blessée à la cuisse à coups de machette a assisté\nà la mise à mort à la machette de sa fille de 25 ans, de ses fils de 16 et 27 ans et de son\nmari725. De manière similaire, un témoin raconte que le 20 avril 2017 à la ferme de Kasele,\ndes Pendes sont arrivés et ont incendiés les maisons et les commerces des lubaphones. Les\nlubaphones se sont alors enfuit vers le village de Kavundi où ils sont tombés sur des Pendes\norganisés en un groupe nommé Ecurie Mbe Mbe, qui les ont volés. Plus loin, dans la\nlocalité de Kalende, des membres de l’Ecurie Mbe Mbe ont décapité quatre hommes\nLubas726."},{"id":"a-hrc-38-crp-1-p0259","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"259","seq":259,"section":"X. Droit applicable","text":"En matière de droits de l’homme, la RDC est notamment partie à : la Convention\ninternationale sur l’élimination de toutes les formes de discrimination raciale ; au Pacte\ninternational relatif aux droits civils et politiques et le Premier protocole facultatif s’y\nrapportant ; au Pacte international relatif aux droits économiques, sociaux et culturels ; à la\nConvention sur l'élimination de toutes les formes de discrimination à l'égard des femmes ; à\nla Convention contre la torture et autres peines ou traitements cruels, inhumains ou\ndégradants et le Protocole facultatif s’y rapportant ; et à la Convention relative aux droits\nde l’enfant et ses deux premiers Protocoles facultatifs. Elle est également partie à la Charte\nafricaine des droits de l’homme et des peuples et à son Protocole relatif aux droits des\nfemmes, ainsi qu’au Pacte sur la sécurité, la stabilité et le développement dans la Région\ndes Grands Lacs et ses divers Protocoles.727"},{"id":"a-hrc-38-crp-1-p0260","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"260","seq":260,"section":"X. Droit applicable","text":"La RDC est partie aux quatre Conventions de Genève de 1949 et à ses deux\nProtocoles additionnels de 1977, ainsi qu’au Statut de Rome de la Cour pénale\ninternationale (CPI) dont elle a récemment incorporé les définitions et les éléments des\ncrimes internationaux dans son code pénal728."},{"id":"a-hrc-38-crp-1-p0261","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"261","seq":261,"section":"XI. Qualification juridique","text":"Les actes de violence décrits précédemment dans ce rapport constituent des violations\ndes droits de l’homme et du droit international humanitaire qui peuvent être qualifiés de\ncrimes internationaux."},{"id":"a-hrc-38-crp-1-p0262","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"262","seq":262,"section":"A. Crimes contre l’humanité","text":"L’article 7(1) du Statut de Rome et l’article 222 du Code pénal de la RDC définissent\nles crimes contre l’humanité comme l’un quelconque des actes énoncés dans ces articles\nlorsqu’il est commis dans le cadre d’une attaque généralisée ou systématique lancée contre\ntoute population civile et en connaissance de cette attaque."},{"id":"a-hrc-38-crp-1-p0263","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"263","seq":263,"section":"A. Crimes contre l’humanité","text":"Cinq éléments contextuels doivent être réunis pour qu’il y ait un crime contre\nl’humanité, à savoir : (i) l’acte de violence doit être commis dans le cadre d’une attaque ;\n(ii) l’attaque doit avoir un caractère généralisé ou systématique ; (iii) l’attaque doit être\ndirigée contre toute population civile ; (iv) la personne responsable du crime savait que ce\ncomportement faisait partie d’une attaque généralisée ou systématique dirigée contre une\npopulation civile ou entendait qu’il en fasse partie ; et (v) l’attaque doit être lancée en\napplication ou dans la poursuite de la politique d’un Etat ou d’une organisation ayant pour\nbut une telle attaque."},{"id":"a-hrc-38-crp-1-p0264","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"264","seq":264,"section":"A. Crimes contre l’humanité","text":"L’article 7(2)(a) du Statut de Rome définit « l’attaque lancée contre une population\ncivile » comme un comportement qui consiste en la commission multiple d’actes\nconstitutifs de crimes contre l’humanité visés à l’article 7(1) du Statut de Rome à\nl’encontre d’une population civile quelle qu’elle soit. Ce n'est pas l’acte qui doit être\ngénéralisé ou systématique pour pouvoir constituer un crime contre l'humanité ; c’est\nl'attaque sur la population civile, et le fait que l'auteur direct savait que sa conduite faisait\npartie ou était destinée à faire partie d'une attaque généralisée ou systématique lancée\ncontre une population civile729."},{"id":"a-hrc-38-crp-1-p0265","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"265","seq":265,"section":"A. Crimes contre l’humanité","text":"Les critères « généralisée » ou « systématique » ne sont pas cumulatifs730. L’adjectif\n« généralisée » renvoie au fait que l’attaque ait été menée à grande échelle et qu’il y ait un\ncertain nombre de victimes, alors que l’adjectif « systématique » se réfère au caractère\norganisé des actes de violence et l’improbabilité que leur caractère soit fortuit731."},{"id":"a-hrc-38-crp-1-p0266","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"266","seq":266,"section":"A. Crimes contre l’humanité","text":"Par ailleurs, « [l]a présence au sein de la population civile de personnes isolées ne\nrépondant pas à la définition de personne civile ne prive pas cette population de sa\nqualité »732. En effet, « rien n’exige que les victimes des crimes sous-jacents soient des\n\"civils\" »733. En d’autres termes, ce n’est pas un élément constitutif de ces crimes."},{"id":"a-hrc-38-crp-1-p0267","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"267","seq":267,"section":"A. Crimes contre l’humanité","text":"L’élément que l’auteur a agi en connaissance de cette attaque ne doit pas être\ninterprété comme exigeant que l’auteur avait connaissance de toutes les caractéristiques de\nl’attaque734. Il est suffisant que l’auteur sache que la population civile fait l’objet d’une\nattaque et que ses actes s’inscrivent dans le cadre de celle-ci735."},{"id":"a-hrc-38-crp-1-p0268","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"268","seq":268,"section":"A. Crimes contre l’humanité","text":"Finalement, l’article 7(2)(a) du Statut de Rome exige que l'attaque ait été commise\n« en application ou dans la poursuite de la politique d’un État ou d’une organisation ayant\npour but une telle attaque ». Pour que cet élément soit rempli, il faut que l’État ou\nl’organisation favorise ou encourage activement une telle attaque contre une population\ncivile736, sans qu’il y ait lieu d’exiger plus737. Dès lors, « il est loin d’être exclu, tout\nparticulièrement dans le contexte des guerres asymétriques d’aujourd’hui, qu’une attaque\ndirigée contre une population civile puisse être aussi le fait d’une entité privée regroupant\nun ensemble de personnes poursuivant l’objectif d’attaquer une population civile, en\nd’autres termes d’un groupe ne disposant pas obligatoirement d’une structure élaborée,\nsusceptible d’être qualifiée de quasi-étatique »738. De plus, « [l]e fait que l’attaque doive par\nailleurs être qualifiée de généralisée ou de systématique ne signifie pas, pour autant, que\nl’organisation qui la favorise ou l’encourage soit structurée d’une manière telle qu’elle\nprésente les mêmes caractéristiques que celles d’un État ». Ce qui compte avant tout, ce\nsont « les capacités d’action, de concertation et de coordination […] qui, en raison même\ndes moyens et des ressources dont elle dispose comme de l’adhésion qu’elle suscite,\npermettront la réalisation de l’attaque »739. La politique peut être déduite de divers facteurs\nqui, ensemble, permettent d’établir son existence et n’a donc pas besoin d’être énoncée de\nfaçon formelle. La CPI a clarifié qu’il peut s’agir : (i) du fait que l’attaque ait été planifiée,\ndirigée ou organisée ; (ii) d’un modèle récurrent de violences ; (iii) du recours à des\nressources publiques ou privées pour appliquer cette politique ; (iv) de l’implication de\nl’Etat ou de forces organisées dans la commission des crimes ; (v) de déclarations,\nd’instructions ou de documentation attribuable à l’Etat ou à l’organisation qui légitime ou\nencourage la commission des crimes ; et/ou (vi) d’une motivation sous-jacente740.\nFinalement, en ce qui concerne le terme d’ « organisation », la CPI rappelle que celle-ci\npeut simplement être définie comme « un corps organisé constitué de personnes ayant un\nobjectif particulier »741.\n1.         Par les forces de défense et de sécurité étatiques\na.   Eléments contextuels"},{"id":"a-hrc-38-crp-1-p0269","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"269","seq":269,"section":"A. Crimes contre l’humanité","text":"L’EEI a des motifs raisonnables de croire que, depuis août 2016, une attaque a été\nmenée dans la région du Kasaï par les forces de défense et de sécurité étatiques contre une\npartie de la population civile, en particulier contre la population civile de l’ethnie luba ou\nidentifiée comme telle en raison de son soutien supposé à la milice Kamuina Nsapu. Cette\nattaque a consisté en la multiplication d’actes visés dans l’article 7(1) du Statut de Rome\nainsi que dans l’incendie de maisons de civils et de pillage de leurs biens. La présence de\ncertains combattants de la milice Kamuina Nsapu parmi les victimes au sein de cette\npopulation civile ne change rien à cette qualification742."},{"id":"a-hrc-38-crp-1-p0270","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"270","seq":270,"section":"A. Crimes contre l’humanité","text":"Le nombre d’incidents, leurs commissions dans quatre provinces de la RDC, et la\npluralité des victimes permettent de conclure au caractère généralisé de l’attaque. De plus,\nl’EEI a des motifs raisonnables de croire que l’attaque est également systématique vu qu’il\ns’agit essentiellement de la répétition d’un même comportement criminel selon un modus\noperandi similaire consistant à mener des opérations de représailles, punitives ou porte à\nporte ne faisant pas de distinction entre les combattants de la milice Kamuina Nsapu et les\ncivils."},{"id":"a-hrc-38-crp-1-p0271","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"271","seq":271,"section":"A. Crimes contre l’humanité","text":"Les actes de violence commis par les forces de défense et de sécurité s’inscrivent dans\nle cadre de la répression du mouvement Kamuina Nsapu et de toute personne réellement ou\nprétendument identifiée comme liée aux idéaux et objectifs de ce mouvement, notamment\ndu fait de son ethnicité. Cette répression a entraîné une mobilisation importante des\nFARDC allant jusqu’à la création d’un secteur militaire opérationnel. L’EEI a des motifs\nraisonnables de croire que cette attaque contre la population civile a été commise en\napplication ou dans la poursuite de la politique d’un État ayant pour but une telle attaque,\nnotamment car la violence est récurrente et suit un même modèle suivant lequel les forces\nde défense et de sécurité arrivent dans des villages composés à majorité de Lubas où se\ntrouvent soi-disant des membres du mouvement Kamuina Nsapu et attaquent de manière\nindiscriminée les membres de la population civile qui vaquent à leurs occupations, ou\nconduisent des opérations porte à porte dans les maisons."},{"id":"a-hrc-38-crp-1-p0272","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"272","seq":272,"section":"A. Crimes contre l’humanité","text":"L’EEI a également des motifs raisonnables de croire que les auteurs présumés qu’elle\na pu identifier, membres des FARDC et dans une moindre mesure de la PNC, ne pouvaient\npas ne pas avoir une connaissance du contexte dans lequel s’inscrivaient leurs actes, vu\nleurs fonctions dans l’appareil sécuritaire étatique et que, dans certains cas, ils aient reçu\nl’ordre de tirer sur tout ce qui bouge de manière indiscriminée.\nb.   Typologie des crimes commis par les forces de défense et de sécurité"},{"id":"a-hrc-38-crp-1-p0273","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"273","seq":273,"section":"A. Crimes contre l’humanité","text":"Les éléments contextuels des crimes contre l’humanité étant d’après elle réunis, l’EEI\na des motifs raisonnables de croire que des éléments des forces de défense et de sécurité de\nla RDC ont notamment commis les crimes contre l’humanité suivants :\nMeurtre (Art. 7(1)(a) du Statut de Rome ; Art. 222(1) du Code pénal de la\nRDC)743"},{"id":"a-hrc-38-crp-1-p0274","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"274","seq":274,"section":"A. Crimes contre l’humanité","text":"Lors des attaques commises par les forces de défense et de sécurité, des éléments\nFARDC – et dans quelques cas, des agents de la PNC – ont tué des personnes faisant partie\nde la population civile. Si ces meurtres ont essentiellement été commis par des armes à feu\nlors d’attaques indiscriminées contre la population civile, certaines victimes ont été\nsommairement exécutées ou brûlées vives dans leurs maisons après que des éléments des\nFARDC y aient mis le feu, y compris une femme de 80 ans en mars 2017 à Moma,\nprovince du Kasaï Central744. Par ailleurs, certains éléments des FARDC ont parfois dit aux\nfemmes et filles de la population civile qu’elles avaient le « choix » entre être tuées ou\nviolées.\nEmprisonnement ou autre forme de privation grave de liberté physique en\nviolation des dispositions fondamentales du droit international (Art. 7(1)(e) du\nStatut de Rome ; Art. 222(5) du Code pénal de la RDC)745"},{"id":"a-hrc-38-crp-1-p0275","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"275","seq":275,"section":"A. Crimes contre l’humanité","text":"Les forces de défense et de sécurité ont emprisonné des personnes de la population\ncivile de manière illégale et arbitraire, c’est-à-dire en violation des règles fondamentales du\ndroit international, notamment des personnes de l’ethnie luba faussement accusées\nd’appartenir à la milice Kamuina Nsapu ou de la soutenir, mais aussi des membres de la\npopulation à des fins d’extorsion ou encore des membres de la famille d’auteurs présumés\nde délits ou de crimes alors qu’ils n’étaient pas eux-mêmes accusés d’actes répréhensibles.\nViol746 ou toute autre forme de violence sexuelle de gravité comparable747 (Art.\n7(1)(g) du Statut de Rome ; Art. 222(8) du Code pénal de la RDC)"},{"id":"a-hrc-38-crp-1-p0276","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"276","seq":276,"section":"A. Crimes contre l’humanité","text":"Des éléments des FARDC ont violé, souvent de manière répétée et/ou collectivement,\ndes femmes et des filles de la population civile lorsqu’ils sont entrés dans des villes ou\nvillages où se trouvaient soi-disant des membres du mouvement Kamuina Nsapu et\nlorsqu’ils ont conduit des opérations de représailles ou porte à porte dans les maisons.\nSi, dans la plupart des cas, ces viols ont consisté en la pénétration du vagin de la victime\npar l’organe sexuel du ou des auteur(s) de ces crimes, certaines victimes ont également été\npénétrées analement."},{"id":"a-hrc-38-crp-1-p0277","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"277","seq":277,"section":"A. Crimes contre l’humanité","text":"Des femmes et des filles de la population civile – y compris une jeune femme qui\navait accouché la veille – ont également été violées par des membres des FARDC ou de la\nPNC, parfois de manière répétée et/ou par plusieurs auteurs, jusqu’à 10 dans certains cas, et\nparfois devant des membres de leur famille, lorsqu’elles fuyaient les affrontements et les\nviolences et se cachaient dans la brousse, ou encore lorsqu’elles se faisaient arrêter aux\nbarrages routiers sur leur chemin. Des éléments des FARDC qui ont exigé d’être rémunérés\nafin d’escorter certaines de ces victimes sur le territoire de Kamonia, province du Kasaï,\nont violé ces dernières lorsqu’elles n’avaient plus d’argent pour les payer. Certaines\nvictimes – y compris une fille de 12 ans – qui avaient réussi à survivre aux violences sont\ndécédées des blessures causées par les viols commis lors de leur fuite."},{"id":"a-hrc-38-crp-1-p0278","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"278","seq":278,"section":"A. Crimes contre l’humanité","text":"Parmi les autres formes de violences sexuelles constitutives de crimes contre\nl’humanité, des éléments des FARDC ont fréquemment forcé des femmes et des filles, mais\négalement des hommes et des garçons, à se dénuder en public aux barrages routiers afin de\nsoi-disant vérifier s’ils ne portaient pas d’habits rouges ou de gris-gris comme les membres\nde la milice Kamuina Nsapu."},{"id":"a-hrc-38-crp-1-p0279","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"279","seq":279,"section":"A. Crimes contre l’humanité","text":"Ces actes ont été commis en usant soit de la force ou de la menace de la force, soit de\nla coercition telle que causée par l’abus de pouvoir de militaires armés profitant de la\nsituation de détresse et de vulnérabilité dans laquelle ces victimes se trouvaient.\nTorture (Art. 7(1)(f) du Statut de Rome ; Art. 222(6) du Code pénal de la\nRDC)748"},{"id":"a-hrc-38-crp-1-p0280","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"280","seq":280,"section":"A. Crimes contre l’humanité","text":"Dans de nombreux cas, des éléments des forces de défense et de sécurité ont\nintentionnellement infligé à une ou plusieurs personnes – sous leur garde ou leur contrôle –\nune douleur ou des souffrances, physiques ou mentales, aiguës qui peuvent être qualifiées\nde torture constitutive de crimes contre l’humanité.\ntierces personnes de la menace de la force ou de la coercition, telle que celle causée par la menace de\nviolences, contrainte, détention, pressions psychologiques, abus de pouvoir, ou bien à la faveur d’un\nenvironnement coercitif, ou encore en profitant de l’incapacité de ladite personne de donner son libre\nconsentement. L’expression « possession » se veut suffisamment large pour être dénuée de\nconnotation sexospécifique. Par ailleurs, il est entendu qu’une personne peut être incapable de donner\nun libre consentement si elle souffre d’une incapacité innée, acquise ou liée à l’âge."},{"id":"a-hrc-38-crp-1-p0281","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"281","seq":281,"section":"A. Crimes contre l’humanité","text":"Parmi les actes de torture les plus répétitifs commis par des éléments des FARDC, il\nconvient notamment de relever : (i) les cas où des membres de la population civile ont été\nsévèrement battus, notamment lors d’opérations porte à porte ; (ii) les cas de viols décrits\nci-dessus qui ont non seulement infligés des souffrances physiques mais aussi\npsychologiques aiguës aux victimes de ces crimes ; (iii) les cas où un ou plusieurs membres\nd’une famille ont été forcés d’assister au viol ou à l’exécution sommaire d’un ou de\nplusieurs autres membres de leur famille.\nAutres actes inhumains (Art. 7(1)(k) du Statut de Rome ; Art. 222(12) du Code\npénal de la RDC)749"},{"id":"a-hrc-38-crp-1-p0282","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"282","seq":282,"section":"A. Crimes contre l’humanité","text":"Parmi les autres actes inhumains constitutifs de crimes contre l’humanité, il convient\nde relever qu’un élément des FARDC a notamment éventré une femme enceinte devant la\nfille de cette dernière avant de sortir le fœtus du ventre de la défunte750. Cet exemple n’est\npas un cas isolé751.\n2.         Par la milice Kamuina Nsapu\na.   Eléments contextuels"},{"id":"a-hrc-38-crp-1-p0283","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"283","seq":283,"section":"A. Crimes contre l’humanité","text":"L’EEI a des motifs raisonnables de croire que la milice Kamuina Nsapu a lancé une\nattaque contre la population civile qui visait, d’un côté, les filles et garçons ainsi que\ncertains adultes pour les recruter de force et, d’un autre, les représentants et fonctionnaires\nde l’État, ainsi que la population civile qui aurait refusé d’adhérer à son mouvement. Dans\nle territoire de Kamonia dans la province du Kasaï, cette attaque visait aussi plus\nglobalement la population civile n’appartenant pas à l’ethnie luba. Cette attaque a consisté\nen la multiplication d’actes visés dans l’article 7(1) du Statut de Rome ainsi que dans\nl’incendie et/ou la destruction d’écoles, de centres de santé, d’églises et de bâtiments\npublics représentants l’autorité de l’État ou assimilés à ceux-ci. La présence de certains\néléments des FARDC et d’agents de la PNC parmi les victimes au sein de cette population\ncivile ne change rien à cette qualification752."},{"id":"a-hrc-38-crp-1-p0284","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"284","seq":284,"section":"A. Crimes contre l’humanité","text":"Le nombre d’incidents, leurs commissions dans quatre provinces de la RDC, et la\npluralité des victimes permettent de conclure au caractère généralisé de l’attaque. De plus,\nl’EEI a des motifs raisonnables de croire que l’attaque est également systématique étant\ndonné que, dans chaque lieu où la milice a commis une multitude d’actes de violence, cette\ndernière a suivi le même modus operandi consistant à recruter, essentiellement sous la\ncontrainte, des filles, garçons, femmes et hommes, de les baptiser et d’ensuite procéder à\ndes attaques contre les représentants et bâtiments symbolisant l’État ainsi que contre la\npopulation refusant d’adhérer à son mouvement et, dans le territoire de Kamonia dans la\nprovince du Kasaï, la population civile n’appartenant pas à l’ethnie luba."},{"id":"a-hrc-38-crp-1-p0285","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"285","seq":285,"section":"A. Crimes contre l’humanité","text":"S’agissant du concept de politique, c’est-à-dire que l’organisation favorise ou\nencourage activement une attaque contre une population civile, l’EEI rappelle que l’attaque\ncontre la population civile de la part de la milice Kamuina Nsapu comporte diverses\nfacettes, mais s’appuie sur une même idéologie expressément énoncée qui consiste à s’en\nprendre à la population civile représentant les symboles de l’État ou lui étant associée. La\nmise en œuvre de cette politique vise la population civile dans son ensemble, notamment\nafin de la recruter de force dans la milice ou pour la punir d’avoir refusé d’adhérer à son\nmouvement. Le modèle récurrent de violence commis par la milice Kamuina Nsapu, tel\nqu’illustré précédemment dans ce rapport, et qui vise à recruter et baptiser la population\ncivile avant de l’utiliser pour commettre des atrocités contre toute personne symbolisant\nl’État, lui étant assimilé ou étant perçue comme refusant d’adhérer à son mouvement atteste\négalement de l’existence de cette politique."},{"id":"a-hrc-38-crp-1-p0286","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"286","seq":286,"section":"A. Crimes contre l’humanité","text":"L’EEI a également des motifs raisonnables de croire que les auteurs présumés qu’elle\na pu identifier, membres de la milice Kamuina Nsapu, ne pouvaient pas ne pas avoir une\nconnaissance du contexte dans lequel s’inscrivaient leurs actes, vu l’idéologie de la milice\nou le fait qu’ils aient été baptisés lors d’un rituel au tshiota précédant leur participant aux\nattaques.\nb.   Typologie des crimes commis par la milice Kamuina Nsapu"},{"id":"a-hrc-38-crp-1-p0287","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"287","seq":287,"section":"A. Crimes contre l’humanité","text":"Les éléments contextuels des crimes contre l’humanité étant d’après elle réunis, l’EEI\na des motifs raisonnables de croire que des éléments de la milice Kamuina Nsapu ont\nnotamment commis les crimes contre l’humanité suivants :\nMeurtre (Art. 7(1)(a) du Statut de Rome ; Art. 222(1) du Code pénal de la\nRDC)753"},{"id":"a-hrc-38-crp-1-p0288","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"288","seq":288,"section":"A. Crimes contre l’humanité","text":"Partout où la milice Kamuina Nsapu s’est implantée ou a été active, des miliciens ont\ntué des membres de la population civile, y compris des représentants et fonctionnaires de\nl’État – et toute personne supposément assimilée à ceux-ci – ainsi que des chefs de village\nou de groupement et tout membre de la population civile qui refusaient d’adhérer à son\nmouvement ou qui étaient accusés – à tort ou à raison – de protéger, de cacher ou d’avoir\ndes liens avec des militaires, souvent appelés « petits cochons », des membres de la PNC\nou de l’ANR. Lorsque les miliciens ne trouvaient pas les membres de la PNC qu’ils\nrecherchaient, ils tuaient parfois leur épouse à leur place754."},{"id":"a-hrc-38-crp-1-p0289","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"289","seq":289,"section":"A. Crimes contre l’humanité","text":"La plupart des victimes de ces meurtres ont été tuées à la machette ou à l’aide d’un\ncouteau, puis décapitées au tshiota devant le reste de la population et parfois des membres\nde leur famille. Des membres de la milice Kamuina Nsapu ont également causé la mort de\ncertains hommes en leur coupant le pénis et les laissant se vider de leur sang755. D’autres\nmembres de la population civile ont été tués à la machette ou brûlés vifs dans leur maison.\nFinalement, dans certains cas, des femmes et des hommes ont été tués avec des armes à feu\nou étranglés avec des cordes. Dans nombre de cas, les miliciens ont ensuite amputé les\ncorps de leurs victimes. Ils ont aussi parfois brûlé leurs corps."},{"id":"a-hrc-38-crp-1-p0290","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"290","seq":290,"section":"A. Crimes contre l’humanité","text":"Ces meurtres d’une brutalité et d’une cruauté choquantes ont été perpétrés aussi bien\npar des hommes et des femmes que par des filles et des garçons faisant partie de la milice.\nEn effet, certains témoins ont rapporté que c’était des filles membres de la milice qui\navaient ordonné la décapitation des membres de leur famille de sexe masculin756. Si les\nfemmes accusées de sorcellerie ont systématiquement été tuées par les membres de la\nmilice, ces derniers ont souvent dit aux femmes et filles de la population civile qu’elles\navaient « le choix » entre être tuées ou violées.\nRéduction en esclavage (Art. 7(1)(c) du Statut de Rome ; Art. 222(3) du Code\npénal de la RDC)757"},{"id":"a-hrc-38-crp-1-p0291","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"291","seq":291,"section":"A. Crimes contre l’humanité","text":"Parmi les éléments essentiels qui caractérisent le crime de réduction en esclavage on\nretrouve « les éléments de contrôle et de propriété, la limitation et le contrôle de\nl’autonomie, de la liberté de choix ou de circulation et, souvent, les bénéfices retirés par\nl’auteur de l’infraction. Le consentement ou le libre arbitre de la victime fait défaut. Les\nmenaces, le recours à la force ou d’autres formes de contrainte, par exemple, le rendent\nsouvent impossible ou sans objet, tout comme la peur de la violence, le dol ou les\npromesses fallacieuses, l’abus de pouvoir, la vulnérabilité de la victime, la détention ou la\ncaptivité, les pressions psychologiques ou les conditions socio-économiques. Sont\négalement symptomatiques l’exploitation, le travail ou service forcé ou obligatoire, exigé\nsouvent sans rémunération et qui constitue souvent aussi, mais pas nécessairement, une\népreuve physique [ainsi que] l’utilisation sexuelle »758. Dès lors, pour déterminer s’il y a eu\nréduction en esclavage, les éléments qui peuvent être pris en compte comprennent : « le\ncontrôle des mouvements d’un individu, le contrôle de l’environnement physique, le\ncontrôle psychologique, les mesures prises pour empêcher ou décourager toute tentative de\nfuite, le recours à la force, les menaces de recourir à la force ou la contrainte, la durée, la\nrevendication de droits exclusifs, les traitements cruels et les sévices, le contrôle de la\nsexualité et le travail forcé »759."},{"id":"a-hrc-38-crp-1-p0292","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"292","seq":292,"section":"A. Crimes contre l’humanité","text":"La stratégie de la milice Kamuina Nsapu consistant à recruter, essentiellement sous la\ncontrainte, des garçons et filles, y compris très jeunes, ainsi que des adultes au sein de la\npopulation civile afin de les faire participer activement aux hostilités, de les utiliser dans\ndivers rôles d’appui à la milice ou encore à des fins sexuelles reflète ces éléments et peut\nêtre qualifiée de réduction en esclavage constitutive de crime contre l’humanité760."},{"id":"a-hrc-38-crp-1-p0293","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"293","seq":293,"section":"A. Crimes contre l’humanité","text":"En effet, nombre d’enfants, et des adultes, ont été capturés et forcés de rejoindre la\nmilice Kamuina Nsapu au sein de laquelle des miliciens ont exercé sur eux l’un quelconque\nou l’ensemble des pouvoirs liés au droit de propriété. Ces personnes ont non seulement été\nutilisées pour participer activement aux hostilités mais aussi contrôlées dans leurs\nmouvements, privées de liberté, battues, victimes et/ou témoins de traitements cruels et de\nsévices ou assignées aux corvées, telles que chercher du bois et de l’eau, laver la vaisselle,\net cuisinier. Par exemple, un garçon capturé en décembre 2016 par la milice et assigné de\nforce aux corvées précise : « Ils nous amenaient parfois des cuisses humaines qu’on devait\ncuisiner et des bidons de sang ». Il n’a réussi à s’échapper que lorsque les FARDC ont\naffronté la milice, mais a ensuite été capturé à nouveau par la milice et de nouveau assigné\nde force aux corvées et à la cuisine761. Une fille capturée dans la brousse avec sa petite sœur\npar la milice Kamuina Nsapu explique avoir été amenée dans une sorte de campement où il\nn’y avait que des femmes et forcée à cuisiner et à puiser de l’eau pour les miliciens qui ne\nlui donnaient pas de nourriture. La journée, lorsque le reste de la milice partait combattre,\ndeux miliciens costauds restaient avec elles pour les surveiller. Elle raconte avoir vu les\nmiliciens couper les oreilles des personnes qui tentaient de s’enfuir de la milice. Lors de\nleur réduction en esclavage, cette fille et d’autres femmes ont aussi été violées par des\nmiliciens762.\nViol ou toute autre forme de violence sexuelle de gravité comparable (Art.\n7(1)(g) du Statut de Rome ; Art. 222(8) du Code pénal de la RDC)763"},{"id":"a-hrc-38-crp-1-p0294","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"294","seq":294,"section":"A. Crimes contre l’humanité","text":"Des membres de la milice Kamuina Nsapu ont violé, souvent de manière répétée et/ou\ncollectivement, des femmes et des filles de la population civile qu’ils avaient recrutées de\nforce et gardées en captivité au sein de la milice. Certaines ont été violées par plusieurs\nauteurs, jusqu’à 10 dans certains cas. Les miliciens ont aussi violé des femmes et des filles\nqui fuyaient dans la brousse. De plus, après avoir exécuté des pères de famille dans leur\nmaison, ils ont également violé leur épouse et/ou leurs filles. Dans une moindre mesure,\ndes hommes ont également été forcés d’avoir des rapports sexuels avec un membre de leur\nfamille ou avec d’autres hommes. Un grand nombre de ces viols ont été commis en public\net/ou devant des membres de la famille des victimes, y compris des enfants."},{"id":"a-hrc-38-crp-1-p0295","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"295","seq":295,"section":"A. Crimes contre l’humanité","text":"La plupart de ces viols ont consisté en la pénétration du vagin de la victime par\nl’organe sexuel ou, dans une moindre mesure, les doigts ou la main du ou des auteur(s) de\nces crimes. Certaines victimes ont également été pénétrées analement par l’organe sexuel\ndu ou des auteur(s) de ces crimes. Certains hommes victimes de viols ont soit été forcés de\npénétrer vaginalement une femme ou de se faire sodomiser. Par exemple, 15 femmes qui\nfuyaient dans en novembre 2016 ont été arrêtées par des éléments de la milice Kamuina\nNsapu qui les ont violées devant tout le monde, y compris leurs enfants. Une de ces\nfemmes a raconté avoir été pénétrée vaginalement et analement par trois hommes de la\nmilice avant qu’ils ne la laissent repartir764. Une autre femme alors enceinte de cinq mois\nraconte, qu’en juin 2017, quatre hommes et une femme de la milice Kamuina Nsapu sont\narrivés chez elle et ont décapité son mari. Un des miliciens a bu le sang qui coulait de la\ntête de son mari, a mutilé le visage de la victime puis a introduit sa main entière dans son\nvagin en présence de ses enfants « comme s’il voulait arracher quelque chose à\nl’intérieur »765. Alors que 20 miliciens étaient rentrés chez elle pour chercher son mari, une\nautre femme a été violée par ces derniers à tour de rôle et a perdu connaissance lorsque le\ncinquième l’a pénétrée, précisant : « Je ne sais pas si tous les autres ont continué »766. Un\nhomme raconte avoir été déshabillé en public au tshiota avant que des miliciens contraigne\nun autre civil présent à le sodomiser767."},{"id":"a-hrc-38-crp-1-p0296","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"296","seq":296,"section":"A. Crimes contre l’humanité","text":"D’autres viols ont été commis pour punir les personnes qui ne respectaient pas les\nrègles imposées par la milice. Par exemple, début avril 2017, dans la cité de Luebo,\nprovince du Kasaï, des miliciens – qui ne mangent pas de poisson – ont accusé la\npropriétaire d’un restaurant de les avoir trahis en leur donnant des haricots mélangés de\npoisson. Afin de la punir, cette dernière a été déshabillée de force au tshiota, tout comme le\nfils de son époux d’un autre mariage, et les miliciens ont obligé ce dernier de pénétrer sa\nbelle-mère en public devant le reste de la population avant de les décapiter768."},{"id":"a-hrc-38-crp-1-p0297","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"297","seq":297,"section":"A. Crimes contre l’humanité","text":"Parmi les autres formes de violences sexuelles constitutives de crimes contre\nl’humanité, des éléments de la milice Kamuina Nsapu ont fréquemment dénudé de force et\nen public au tshiota des hommes, notamment un chef de groupement, et des femmes et des\nfilles, y compris une femme accusée de sorcellerie."},{"id":"a-hrc-38-crp-1-p0298","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"298","seq":298,"section":"A. Crimes contre l’humanité","text":"Ces viols et autres formes de violences sexuelles ont été commis en usant soit de la\nforce ou de la menace de la force, ou bien à la faveur d’un environnement coercitif,\nnotamment lorsque les victimes avaient été incorporées de force dans la milice.\nTorture (Art. 7(1)(f) du Statut de Rome ; Art. 222(6) du Code pénal de la\nRDC)769"},{"id":"a-hrc-38-crp-1-p0299","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"299","seq":299,"section":"A. Crimes contre l’humanité","text":"Dans d’innombrable cas, des éléments de la milice Kamuina Nsapu ont\nintentionnellement infligé à une ou plusieurs personnes – sous leur garde ou leur contrôle –\nune douleur ou des souffrances, physiques ou mentales, aiguës qui peuvent être qualifiées\nde torture constitutive de crimes contre l’humanité."},{"id":"a-hrc-38-crp-1-p0300","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"300","seq":300,"section":"A. Crimes contre l’humanité","text":"Ces cas étant si nombreux, il est impossible de tous les décrire. Parmi les actes de\ntorture les plus répétitifs commis par des miliciens Kamuina Nsapu, il convient de relever\nles cas suivants : (i) les cas où des miliciens ont sévèrement battus à la machette, fouettés,\nbrûlés ou amputés des membres de la population civile sous leur contrôle; (ii) les cas de\nviols décrits ci-dessus qui ont non seulement infligés des souffrances physiques mais aussi\npsychologiques aiguës aux victimes de ces crimes ; et (iii) les cas où un ou plusieurs\nmembres d’une famille ont été forcés d’assister au viol, à la décapitation ou à l’amputation\nd’un autre membre de leur famille soit dans leur maison, soit au tshiota et, dans de\nnombreux cas, se sont en plus vus interdire par les miliciens de pleurer durant la\ncommission de ces actes ou se sont même vus obliger de danser et de glorifier ces actes."},{"id":"a-hrc-38-crp-1-p0301","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"301","seq":301,"section":"A. Crimes contre l’humanité","text":"La plupart des actes de torture commis par la milice Kamuina Nsapu font preuve\nd’une cruauté inouïe. Il convient d’en citer quelques exemples. En février 2017, sur le\nterritoire de Kamonia, province du Kasaï, des miliciens ont coupé les seins et le clitoris\nd’une femme, agent de la PNC, en public au tshiota avant de la décapiter770. A la même\népoque, à Kananga, province du Kasaï Central, des miliciens sont entrés dans une maison\net ont décapité un père de famille et ont remis sa tête au plus jeune de ses six enfants\nprésents en lui disant « c’est la tête de papa » avant de violer leur mère devant eux771. En\nmars 2017, des miliciens qui occupaient un village dans le territoire de Kamonia, province\ndu Kasaï, sont arrivés avec des têtes décapitées. Deux d’entre eux ont approché une femme\nau marché et lui ont remis des testicules et le cœur d’une personne pour qu’elle les achète.\nComme celle-ci a refusé, elle a été battue par ces deux miliciens, rejoints par trois autres,\nqui l’ont par la suite frappée à l’aide de leurs machettes772. A la même période sur le même\nterritoire, des miliciens ont éventré une femme enceinte et « ont mangé cru le fœtus » de\ncette dernière devant le reste du groupe qui avait été capturé avec elle alors qu’ils fuyaient\nles violences773. En juin 2017, des miliciens ont égorgé, décapité et amputé cinq membres\nde la famille d’une fille de 17 ans, puis l’ont obligée à porter la tête et le bras de sa mère\njusqu’à leur tshiota774. A la même période à Tshikapa, province du Kasaï, une femme a non\nseulement dû assister à la décapitation de son mari mais aussi au fait qu’un des miliciens a\nbu le sang de la tête de ce dernier avant qu’un autre lui défigure le visage et introduise sa\nmain dans son vagin comme s’il voulait arracher quelque chose à l’intérieur alors qu’elle\nétait enceinte de cinq mois. Ces actes de tortures se sont produits devant ses enfants775.\nFinalement, en août 2017, à Tshikapa, une fille de 16 ans capturée et gardée en captivité\ndans la milice raconte : « J’ai vu les Kamuina Nsapu couper les oreilles des personnes qui\navaient tenté de s’enfuir »776."},{"id":"a-hrc-38-crp-1-p0302","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"302","seq":302,"section":"A. Crimes contre l’humanité","text":"De nombreux hommes ont également été victimes de tortures visant leurs organes\nsexuels. En effet, si dans de nombreux cas, des éléments de la milice Kamuina Nsapu ont\ncoupé à la machette ou au couteau le pénis d’hommes qu’ils venaient de tuer, dans d’autres\ncas, ils ont procédé à ce type de mutilation lorsque ces hommes étant encore en vie, les\nlaissant se vider de leur sang777. Dans un autre cas, les éléments de la milice ont, après avoir\nfrappé un homme âgé avec leurs machettes, « lié un fil dans [son] pénis », laissant des\nséquelles physiques graves et le rendant impuissant778.\nAutres actes inhumains (Art. 7(1)(k) du Statut de Rome ; Art. 222(12) du Code\npénal de la RDC)779"},{"id":"a-hrc-38-crp-1-p0303","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"303","seq":303,"section":"A. Crimes contre l’humanité","text":"En plus des nombreux actes de tortures décrits dans la section précédente, dans\nd’autres cas, des éléments de la milice Kamuina Nsapu ont, par un acte inhumain,\nintentionnellement infligé de grandes souffrances ou porté gravement atteinte à l’intégrité\ncorporelle ou à la santé physique ou mentale de leurs victimes. Ces actes peuvent être\nqualifiés d’autres actes inhumains constitutifs de crimes contre l’humanité. Parmi la pléiade\nd’actes inhumains commis par la milice Kamuina Nsapu, il convient d’en citer quelques-\nuns soit parce qu’ils ont été commis de manière systématique soit parce qu’ils sont\nemblématiques de la cruauté et de l’inhumanité dont ont fait preuve les éléments de la\nmilice."},{"id":"a-hrc-38-crp-1-p0304","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"304","seq":304,"section":"A. Crimes contre l’humanité","text":"Les membres de la population civile, y compris ceux qui ont été capturés par la\nmilice, ont dû assister à des actes d’anthropophagie, de mutilation, d’amputation et de\ndécapitation. Ainsi, dans nombre de cas, après avoir tué leurs victimes, les miliciens ont\namputé les têtes, les mains et les pieds de leurs victimes ou encore leurs lèvres ou une de\nleurs oreilles en public. Ils ont également procédé à l’ablation d’organes sexuels. Ainsi, au\ntshiota, devant la population civile souvent forcée de regarder, ils ont coupé le pénis de\nnombreux hommes, y compris de chefs de villages qu’ils considéraient comme des traitres,\nqui venaient d’être décapités, et ont parfois ensuite organisé une cérémonie pour les\nmanger après les avoir préparés, qui, selon leur croyance, leur donne du pouvoir, ou les ont\njetés dans le feu. Les clitoris de femmes préalablement coupés servaient parfois de\nmédailles aux miliciens. Dans un autre cas, une femme a notamment vu au tshiota les\nmiliciens manger la partie abdominale de son fils qui venait d’être décapité."},{"id":"a-hrc-38-crp-1-p0305","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"305","seq":305,"section":"A. Crimes contre l’humanité","text":"Un garçon capturé dans le territoire de Kamonia, province du Kasaï, en décembre\n2016 par la milice et assigné de force aux corvées précise : « Ils nous amenaient parfois des\ncuisses humaines qu’on devait cuisiner et des bidons de sang ». Il raconte également qu’à\ndeux reprises les miliciens ont ramené des têtes humaines décapitées, trois un jour et sept\nun autre jour avec, cette fois, deux pénis780. Une femme raconte qu’en avril 2017 sur le\nmême territoire, elle a été forcée de regarder non seulement la décapitation de trois\nmembres de sa famille par la milice Kamuina Nsapu mais également le fait que les\néléments de la milice ont systématiquement fait couler le sang des têtes et des corps des\ndéfunts dans une marmite mise sur le feu781. Une autre femme qui était à la maison explique\nque des miliciens lui ont amené successivement chez elle « la tête de [s]a fille qui était en\ntrain de saigner. Puis, dans un second temps, la tête de [s]on mari qui saignait encore »\nqu’ils venaient de décapiter au tshiota. Les autres parties de leurs corps ont été brûlées avec\nde l’essence pendant trois jours au tshiota782. Finalement, une fille de 14 ans intégrée de\nforce dans la milice Kamuina Nsapu en mai 2017 dans la province du Kasaï Oriental\nexplique : « Les miliciens coupaient le sexe des militaires qui avaient été tués mais c’était\nle plus souvent le sexe des militaires gradés qu’ils coupaient. Ensuite les sexes étaient\ngrillés et mangés. Les garçons coupaient les sexes et les donnaient aux filles. Le sang des\nvictimes était bu. La peau des militaires était séchée puis réduite en poudre et ensuite cette\npoudre était mélangée à de l’huile de palme. Ensuite on nous mettait ce mélange dans la\nbouche ou sur le front ».\n3.         Par les milices Bana Mura\na.   Eléments contextuels"},{"id":"a-hrc-38-crp-1-p0306","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"306","seq":306,"section":"A. Crimes contre l’humanité","text":"L’EEI a des motifs raisonnables de croire que les milices Bana Mura ont lancé une\nattaque contre la population civile, principalement de l’ethnie luba – en raison de son\nappartenance ou soutien supposés à la milice Kamuina Nsapu du fait de son ethnie ainsi\nque de sa supposée affiliation politique à l’opposition – présente sur le territoire de\nKamonia, province du Kasaï, à partir de février-mars 2017. Cette attaque a consisté en la\nmultiplication d’actes visés dans l’article 7(1) du Statut de Rome ainsi que l’incendie de\nmaisons de civils et de destruction de villages. La présence de certains miliciens Kamuina\nNsapu parmi les victimes au sein de la population civile ne change rien à cette\nqualification783."},{"id":"a-hrc-38-crp-1-p0307","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"307","seq":307,"section":"A. Crimes contre l’humanité","text":"Différents éléments permettent de conclure au caractère généralisé de l’attaque : le\nnombre d’incidents, leurs commissions dans de nombreux villages du territoire de\nKamonia, et la pluralité des victimes. De plus, l’EEI a des motifs raisonnables de croire que\nl’attaque est également systématique étant donné qu’il s’agit essentiellement de la\nrépétition d’un même comportement criminel consistant à éliminer la présence de la\npopulation civile luba du territoire de Kamonia en encerclant puis attaquant leurs villages et\nen commettant à leur l’encontre une multitude d’actes de violence, y compris des\nmassacres, en incendiant leurs habitations ou lieux de refuge, en poursuivant ceux qui\ns’échappaient en brousse et en érigeant des barrages routiers pour identifier les Lubas qui\nfuyaient et les tuer."},{"id":"a-hrc-38-crp-1-p0308","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"308","seq":308,"section":"A. Crimes contre l’humanité","text":"L’EEI est d’avis que les milices Bana Mura sont une organisation au sens de l’article\n7(2)(a) du Statut de Rome dans le sens où elles représentent « un corps organisé constitué\nde personnes ayant un objectif particulier »784 qui vise à repousser l’avancée de la milice\nKamuina Nsapu et à nettoyer le territoire de Kamonia de la population civile de l’ethnie\nluba étant donné l’assimilation faite entre cette dernière et la milice Kamuina Nsapu.\nS’agissant du concept de politique, les milices Bana Mura ont été créées et armées afin de\ns’en prendre à la population civile luba et un grand nombre des massacres ont été planifiés\net organisés lors de réunions à l’instigation de représentant des autorités locales, de chefs\nde groupements ou de villages avec parfois l’appui de membres des forces de défense et de\nsécurité. Par ailleurs, dans certains cas, les attaques et massacres auraient été précédés de\ndiscours de haine à l’encontre de la population civile luba. Dès lors, la planification et\nl’organisation de ces attaques, le modèle récurrent de violence commis à l’encontre de la\npopulation civile luba, l’implication dans certaines attaques d’éléments des FARDC, et les\ndiscours de haine à l’encontre des Lubas précédant ces attaques attestent de l’existence de\ncette politique."},{"id":"a-hrc-38-crp-1-p0309","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"309","seq":309,"section":"A. Crimes contre l’humanité","text":"L’EEI a des motifs raisonnables de croire que les auteurs présumés qu’elle a pu\nidentifier, membres des milices Bana Mura, ne pouvaient pas ne pas avoir une\nconnaissance du contexte dans lequel s’inscrivaient leurs actes, vu que les attaques contre\nla population luba étaient pour la plupart organisées et planifiées lors de réunions et que des\ndiscours de haine à l’encontre de cette population était monnaie courante sur le territoire de\nKamonia durant cette période.\nb.   Typologie des crimes commis par les milices Bana Mura"},{"id":"a-hrc-38-crp-1-p0310","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"310","seq":310,"section":"A. Crimes contre l’humanité","text":"Les éléments contextuels des crimes contre l’humanité étant d’après elle réunis, l’EEI\na des motifs raisonnables de croire que des miliciens Bana Mura ont notamment commis\nles crimes contre l’humanité suivants :\nMeurtre (Art. 7(1)(a) du Statut de Rome ; Art. 222(1) du Code pénal de la\nRDC)785"},{"id":"a-hrc-38-crp-1-p0311","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"311","seq":311,"section":"A. Crimes contre l’humanité","text":"Partout où des milices Bana Mura ont été actives sur le territoire de Kamonia, des\nmembres de ces milices ont systématiquement tué des civils de l’ethnie luba, et dans une\nmoindre mesure d’autres ethnies, en raison de leur supposé soutien à la milice Kamuina\nNsapu. Dans quelques cas, les femmes en âge de procréer ont toutefois été épargnées."},{"id":"a-hrc-38-crp-1-p0312","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"312","seq":312,"section":"A. Crimes contre l’humanité","text":"Les victimes de ces meurtres ont été tuées soit par des armes à feu, essentiellement\ndes fusils de chasse « calibre 12 », soit par des machettes ou des couteaux. D’autres\nvictimes ont été brûlées vives dans leurs maisons après y avoir été enfermées par des\nmiliciens Bana Mura. Par ailleurs, au bord de la rivière près de Camp Kwilu, vers fin avril\n2017, des miliciens ont décapité des hommes et des femmes et tué de jeunes enfants en les\njetant dans la rivière depuis une pirogue. Emblématique de la violence utilisée lors de ces\nmeurtres, des miliciens Bana Mura ont également tué un bébé de 10 mois en lui fracassant\nle crâne par terre en octobre 2017 à Kamonia786. Par ailleurs, certains miliciens Bana Mura\nont causé la mort de certaines femmes en les violant à l’aide de bâtons.\nExtermination (Art. 7(1)(b) du Statut de Rome ; Art. 222(2) du Code pénal de\nla RDC)787"},{"id":"a-hrc-38-crp-1-p0313","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"313","seq":313,"section":"A. Crimes contre l’humanité","text":"Certains des meurtres commis par les milices Bana Mura l’ont été à grande échelle,\nconstituant ainsi des massacres de membres de la population civile luba pouvant être\nqualifiés d’extermination constitutive de crime contre l’humanité. C’est notamment le cas\ndes massacres commis entre le 24 et 26 avril 2017 dans le groupement Muyeji, en\nparticulier dans les villages de Senge (Cinq), Camp Kwilu, Kakondo et Mvula Milenge, où\nles membres de la population civile luba tués se comptent par centaines.\nViol (Art. 7(1)(g) du Statut de Rome ; Art. 222(8) du Code pénal de la RDC)788"},{"id":"a-hrc-38-crp-1-p0314","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"314","seq":314,"section":"A. Crimes contre l’humanité","text":"Des femmes et des filles de la population civile luba, et dans une moindre mesure de\nl’ethnie tetela ainsi que des femmes pendes, qui fuyaient les violences entre les milices\nBana Mura et la milice Kamuina Nsapu sur le territoire de Kamonia ont été violées –\nparfois de manière répétée et/ou collectivement et/ou par plusieurs auteurs – par des\nmembres des milices Bana Mura soit dans la brousse soit aux barrages routiers tenus par\nces derniers. Elles ont souvent été violées devant leurs enfants et/ou d’autres membres de\nleur famille ou des proches. Par exemple, des femmes fuyant les violences et les combats et\nqui venaient d’échapper à des éléments de la milice Kamuina Nsapu qui les avaient violées\nsont tombées sur des miliciens Bana Mura qui les ont violées à leur tour789. Une femme\ntetela et quatre autres femmes qui ont été capturées lors de leur fuite vers l’Angola ont été\nviolées systématiquement pendant quatre jours consécutifs par des miliciens Bana Mura et\nceci en présence de leurs enfants qui ne pouvaient rien faire790. Une autre femme attrapée\npar trois miliciens Bana Mura armés raconte : « [d]eux m’ont tenue très fort par les bras\ntandis que l’autre m’a déshabillée et pénétrée de force pour me violer. […] Ce jour-là,\ntoutes les autres femmes, une trentaine, ont été violées »791."},{"id":"a-hrc-38-crp-1-p0315","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"315","seq":315,"section":"A. Crimes contre l’humanité","text":"D’autres femmes et filles ont été violées dans leurs villages lorsque des miliciens\nBana Mura ont attaqué ces villages. Ces viols se sont souvent produits devant des membres\nde leur famille ou des proches. Des femmes et des filles de la population civile luba en âge\nde procréer ont également été violées de manière répétée pendant des semaines ou des mois\nalors qu’elles étaient gardées en captivité dans des fermes par des miliciens Bana Mura, y\ncompris une femme qui avait accouché une semaine plus tôt et qui a ensuite été violée\nquotidiennement durant toute sa détention."},{"id":"a-hrc-38-crp-1-p0316","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"316","seq":316,"section":"A. Crimes contre l’humanité","text":"La plupart de ces viols ont consisté en la pénétration du vagin de la victime par\nl’organe sexuel du ou des auteur(s) de ces crimes. Certaines victimes ont également été\npénétrées vaginalement par des objets, tels que des bâtons ou encore des fusils, causant\nparfois leur mort."},{"id":"a-hrc-38-crp-1-p0317","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"317","seq":317,"section":"A. Crimes contre l’humanité","text":"Si la grande majorité de ces viols ont été commis contre des femmes et des filles, dans\nun cas au moins, des miliciens Bana Mura ont exigé qu’un homme luba – qui fuyait les\nviolences avec sa femme pende et leurs enfants – ait des relations sexuelles avec ses filles.\nAyant refusé, il a été battu avec des machettes, puis égorgé. Sa femme a alors été violée à\nsa place792."},{"id":"a-hrc-38-crp-1-p0318","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"318","seq":318,"section":"A. Crimes contre l’humanité","text":"Tous ces viols ont été commis en usant soit de la force ou de la menace de la force, ou\nbien à la faveur d’un environnement coercitif, notamment lorsque les femmes et filles\nétaient en captivité dans des fermes.\nRéduction en esclavage, y compris sexuel (Art. 7(1)(c) et (g) du Statut de\nRome ; Art. 222(3) et (8) du Code pénal de la RDC)793"},{"id":"a-hrc-38-crp-1-p0319","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"319","seq":319,"section":"A. Crimes contre l’humanité","text":"Des miliciens Bana Mura ont sélectionné des femmes et des filles lubas en âge de\nprocréer et les ont gardées en captivité, parfois avec leurs enfants, dans des fermes situées\ndans le groupement de Muyeji. Celles-ci n’ont pas uniquement été privées de leur liberté,\nmais ont systématiquement été violées de manière répétitive et certaines d’entre elles ont\nété forcées de travailler dans les champs ou de vendre des produits au marché. De très\njeunes filles et garçons lubas ont également été détenus dans ces fermes. Divers\nindicateurs794 permettent de déterminer que les miliciens Bana Mura ont exercé sur ces\nfemmes, ces filles et ces garçons l’un quelconque ou l’ensemble des pouvoirs liés au droit\nde propriété équivalant à une réduction en esclavage, y compris sexuel, constitutive de\ncrime contre l’humanité."},{"id":"a-hrc-38-crp-1-p0320","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"320","seq":320,"section":"A. Crimes contre l’humanité","text":"Premièrement, la manière dont ces femmes et filles ont été sélectionnées est\nillustrative des pouvoirs liés au droit de propriété exercés sur elles par les miliciens Bana\nMura. En effet, alors qu’elles fuyaient les violences ou lorsque leurs villages ont été\nattaqués, ces femmes et ces filles ont été sélectionnées du fait de leur âge de procréer\ncomme si elles étaient des objets. Ainsi une d’entre elle rapporte que, lors de son\narrestation, un milicien lui a dit : « nous allons tuer ton mari, tu vas être notre femme ».\nUne fois arrivée à la ferme, les miliciens sélectionnaient les femmes et disaient : « toi, tu\nseras ma femme, toi aussi ». Plusieurs miliciens ont ainsi choisi une ou des femmes parmi\nle groupe de femmes avec lequel elle avait été capturée795. Une autre femme raconte que le\nmilicien qui l’a sélectionnée a dit : « Moi j’ai beaucoup combattu, mais vous ne m’avez\njamais payé. Donc moi, je vais la prendre comme récompense »796."},{"id":"a-hrc-38-crp-1-p0321","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"321","seq":321,"section":"A. Crimes contre l’humanité","text":"Par ailleurs, ces femmes et filles – ainsi que ces jeunes enfants – étaient gardées en\ncaptivité et leurs mouvements contrôlés. En effet, des miliciens les surveillaient non\nseulement lorsqu’elles étaient à l’intérieur des fermes, mais également lorsqu’elles\ntravaillaient au champ ou devaient aller vendre des produits au marché. Une femme\nexplique : « A la ferme, j’étais entravée, torturée matin et soir. J’étais comme une esclave\navec d’autres à travailler dans les champs et puiser de l’eau »797."},{"id":"a-hrc-38-crp-1-p0322","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"322","seq":322,"section":"A. Crimes contre l’humanité","text":"En plus du travail forcé aux champs ou au marché imposés sur ces femmes et filles,\nles pouvoirs liés au droit de propriété exercés sur ces dernières sont aussi mis en exergue\npar le contrôle de leur sexualité, les traitements cruels et les sévices que certaines ont subis,\nainsi que le recours à la force ou d’autres formes de contrainte auxquelles elles ont été\nsoumises. Les femmes et filles ont ainsi été systématiquement violées de manière répétées,\nparfois quotidiennement, allant même jusqu’à trois ou quatre fois par jour et plusieurs fois\npar nuit dans certains cas, et ceci pendant des mois. Ces viols ont été commis en faisant\nusage de la force, de la contrainte ou de l’environnement coercitif dans lequel elles se\ntrouvaient. Ainsi, une femme luba décrit que, lors de son premier viol, le milicien avait une\nmachette et une arme à feu et l’a menacée de mort si elle refusait. Une autre femme\nexplique que la première fois elle a résisté. Le milicien lui « a dit : ‘tu es ma femme et tu ne\nretourneras pas chez toi’. Il [l]’a déshabillée. Puis il [l]’a frappée avec des cordes sur les\nbras, sur le dos, sur les jambes. Il [l]’a cognée contre le muret, [la] saisissant par le cou »\njusqu’à ce qu’elle cède. Elle explique : « Je voulais sauver ma vie donc j’ai accepté. Il m’a\nallongée sur une natte par terre et il s’est couché sur moi pour me pénétrer de force dans le\nsexe »798. Par ailleurs, plusieurs de ces miliciens ont revendiqué des droits exclusifs sur ces\nvictimes, les décrivant comme étant leurs femmes."},{"id":"a-hrc-38-crp-1-p0323","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"323","seq":323,"section":"A. Crimes contre l’humanité","text":"Finalement, bien qu’il ressort des témoignages de certaines femmes que les miliciens\nqui les ont réduites en esclavage, détenues illégalement et violées de manière répétitives\navaient l’intention qu’elles tombent enceinte et qu’elles mettent au monde leurs enfants,\nl’EEI n’a pas collecté suffisamment de preuves de cas où le ou les miliciens, sachant que\nles femmes avaient été mises enceinte de force, ont eu l’intention spécifique de les détenir\nillégalement afin de modifier la composition ethnique d’une population ou de commettre\nd’autres violations graves du droit international. Dès lors, l’EEI n’a pas pu prouver que le\ncrime de grossesse forcée constitutive de crime contre l’humanité avait été commis.\nTorture (Art. 7(1)(f) du Statut de Rome ; Art. 222(6) du Code pénal de la\nRDC)799"},{"id":"a-hrc-38-crp-1-p0324","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"324","seq":324,"section":"A. Crimes contre l’humanité","text":"Dans d’innombrables cas, des miliciens Bana Mura ont intentionnellement infligé à\ndes personnes – sous leur garde ou leur contrôle – une douleur ou des souffrances,\nphysiques ou mentales, aiguës qui peuvent être qualifiées de torture constitutive de crime\ncontre l’humanité."},{"id":"a-hrc-38-crp-1-p0325","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"325","seq":325,"section":"A. Crimes contre l’humanité","text":"Parmi les actes de torture les plus répétitifs commis par des miliciens Bana Mura, il\nconvient de relever les cas suivants : (i) les cas où des miliciens ont frappé à l’aide de\nmachettes, poignardé à l’aide de couteaux, mutilés, amputés – y compris les seins de\nfemmes – ou encore brûlés des civils sous leur contrôle ; (ii) les cas de viols décrits ci-\ndessus, y compris à l’aide d’objets, qui ont non seulement infligés des souffrances\nphysiques mais aussi psychologiques aiguës aux victimes de ces crimes ; et (iii) les cas où\nun ou plusieurs membres d’une famille ont été forcés d’assister au viol, au meurtre, à la\nmutilation ou à l’amputation d’un autre membre de leur famille."},{"id":"a-hrc-38-crp-1-p0326","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"326","seq":326,"section":"A. Crimes contre l’humanité","text":"Les actes de torture commis par les miliciens Bana Mura font preuve d’une violence\net d’une cruauté inouïes. Il convient d’en donner quelques exemples. Une femme luba\nraconte qu’en avril 2017 lors de l’attaque de son village, quatre miliciens sont entrés de\nforce chez elle. Elle explique : « [ils] défoncent la porte de la maison et me trouvent avec\nmes quatre enfants. […] D’un coup de machette, l’un cherchant à me fendre la tête, me\nblesse le long du visage du front aux lèvres en me cassant une incisive de la mâchoire\nsupérieure, car j’ai essayé d’esquiver. Ensuite il m’envoie un second coup que par réflexe,\nj’ai essayé de caler de mon bras droit qui reçoit le coup, ce qui me casse l’os de l’avant-\nbras droit. Ensuite, ils ont blessé chacun des quatre enfants âgés de 4 à 14 ans, à différentes\nparties du corps, principalement la tête et les bras. Le cinquième, 2 ans et 6 mois, benjamin\nde la fratrie, […] a, lui, été tué, sectionné en deux à la machette à la hauteur de l’abdomen.\nIls extraient ensuite ses entrailles (intestins), me réunissent avec les autres enfants, nous\nfont asseoir, et enroulent ces intestins autour de nous et ressortent. Nous sommes restés sur\nplace de 12 à 23 heures, profondément traumatisés »800. Une femme pende fuyant les\nviolences avec sa famille et interceptée par huit miliciens Bana Mura explique : « Ils ont su\nque mon mari était de la tribu Luba. Ils ont alors exigé que mon époux ait des relations\nsexuelles avec nos filles, ce qu’il a refusé. Ils sont rentrés dans une colère, et l’ont battu\navec du bois, des machettes et l’ont finalement égorgé. Pendant que j’étais par terre avec\nmon bébé de quatre mois au dos, l’un me l’a arraché du dos et a tenu le bébé par la gorge et\nl’a frappé contre un arbre avant de le jeter par terre. Il a ensuite pris une pelle et voulait\nfrapper à nouveau mon bébé lorsque je suis intervenue. Un autre m’a alors poignardée dans\nla cuisse gauche et dans la fesse gauche ensuite dans la fesse droite. Par terre, ils m’ont\nbâillonné la bouche avant que l’un d’eux me viole. Un second suivait lorsque j’ai senti un\ncoup comme un métal chaud dans ma côte droite et j’ai perdu connaissance »801.\nAutres actes inhumains (Art. 7(1)(k) du Statut de Rome ; Art. 222(12) du Code\npénal de la RDC)802"},{"id":"a-hrc-38-crp-1-p0327","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"327","seq":327,"section":"A. Crimes contre l’humanité","text":"En plus des nombreux actes de tortures décrits dans la section précédente, dans\nd’autres cas, des miliciens Bana Mura ont, par un acte inhumain, intentionnellement infligé\nde grandes souffrances ou porté gravement atteinte à l’intégrité corporelle ou à la santé\nphysique ou mentale de leurs victimes. Ces actes peuvent être qualifiés d’autres actes\ninhumains constitutifs de crimes contre l’humanité."},{"id":"a-hrc-38-crp-1-p0328","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"328","seq":328,"section":"A. Crimes contre l’humanité","text":"Parmi la multitude d’actes inhumains commis par les miliciens Bana Mura, certains\nsont emblématiques de la cruauté et de l’inhumanité dont ils ont fait preuve. Ainsi, des\nmiliciens Bana Mura ont notamment éventré à la machette une femme enceinte sur laquelle\nils venaient de tirer, puis ont tourné leur machette et en ont sorti les fœtus des jumeaux\nqu’elle attendait avant de les tuer803. Ils ont également éventré d’autres civils lubas qu’ils\navaient précédemment tués à la machette804. Les miliciens Bana Mura ont également\nprocédé à l’ablation d’organes sexuels de cadavres de leurs victimes qu’ils ont ensuite\ndéposés sur ceux-ci. Par exemple, des pénis d’hommes coupés ont ainsi été déposés sur le\nfront de leurs cadavres et des vagins de femmes tuées ont été coupés et, dans un cas, déposé\nsur le sein du cadavre.\nTransfert forcé de population (Art. 7(1)(d) du Statut de Rome ; Art. 222(4) du\nCode pénal de la RDC)805"},{"id":"a-hrc-38-crp-1-p0329","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"329","seq":329,"section":"A. Crimes contre l’humanité","text":"Alors que les membres de la population civile luba était légalement présents sur le\nterritoire de Kamonia, province du Kasaï, où ils habitaient, les milices Bana Mura ont, sans\nmotif admis en droit international, transféré de force en dehors de ce territoire un nombre\nconsidérable de membres de cette population. Ce transfert forcé s’est fait à la faveur du\nclimat coercitif provoqué par les attaques que les miliciens Bana Mura ont\nsystématiquement lancées contre la population civile de l’ethnie luba et les crimes commis\nà leur encontre sur le territoire de Kamonia ainsi que les discours haineux, tels que ceux\nleur disant « Rentrez chez vous ! Ça, ce n’est pas votre terre ! ». En effet, face à la\ncommission d’attaques consistant à éliminer la présence de la population civile luba du\nterritoire de Kamonia en attaquant leurs villages et en commettant à leur l’encontre une\nmultitude d’actes de violence, y compris des massacres, et en incendiant leurs habitations\nou lieux de refuge, les Lubas n’ont pas eu d’autre choix que de fuir le territoire de\nKamonia.\nPersécutions (Art. 7(1)(h) du Statut de Rome ; Art. 222(9) du Code pénal de la\nRDC)806"},{"id":"a-hrc-38-crp-1-p0330","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"330","seq":330,"section":"A. Crimes contre l’humanité","text":"La persécution constitutive de crimes contre l’humanité s’entend du « déni\nintentionnel et grave de droits fondamentaux en violation du droit international, pour des\nmotifs liés à l’identité du groupe ou de la collectivité qui en fait l’objet »807. Ce déni\nintentionnel et grave de droits fondamentaux doit se matérialiser par la commission\nd’autres crimes internationaux, par exemples des crimes contre l’humanité, ciblant un\ngroupe ou une collectivité – ou des personnes en raison de leur appartenance à ceux-ci –\nidentifiable pour des motifs notamment d’ordre politique ou ethnique."},{"id":"a-hrc-38-crp-1-p0331","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"331","seq":331,"section":"A. Crimes contre l’humanité","text":"Les crimes contre l’humanité commis depuis le mois de mars 2017 sur le territoire de\nKamonia, province du Kasaï, par les milices Bana Mura et qui viennent d’être décrits ci-\ndessus ont systématiquement visé la population civile, principalement de l’ethnie luba.\nCette collectivité était visée pour des motifs d’ordre politique et ethnique. Les motifs\nd’ordre politique proviennent du fait que la communauté ciblée est perçue comme affiliée\nou soutenant la milice et le mouvement politico-coutumier Kamuina Nsapu qui vise les\nreprésentants et symboles de l’Etat. En d’autres termes, la communauté ciblée est perçue\ncomme étant opposée aux autorités étatiques. Par ailleurs, les discours de haine des\nmiliciens Bana Mura envers cette collectivité leur disant qu’elle n’est pas chez elle permet\naussi de prouver l’intention discriminatoire à l’encontre de cette collectivité."},{"id":"a-hrc-38-crp-1-p0332","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"332","seq":332,"section":"B. Crimes de guerre","text":"Les articles 8(2)(c) et (e) du Statut de Rome et l’article 223 du Code pénal de la RDC\ndéfinissent les crimes de guerre commis dans des conflits armés non-internationaux.\nL’article 8(2)(c) du Statut de Rome et les articles 223(3) et (4) du Code pénal de la RDC\nincriminent les violations de l’article 3 commun aux quatre Conventions de Genève de\n1949. L’article 8(2)(e) du Statut de Rome et l’article 223(5) reprennent toutes les autres\nviolations graves des lois et coutumes applicables aux conflits armés non-internationaux.\nCes dernières sont tirées soit du Protocole Additionnel II de 1977 ou des violations des lois\net coutumes de la guerre applicables en cas de conflit armé non-international808. Pour leur\npart, les articles 8(2)(d) et (f) du Statut de Rome comprennent des clauses d’exclusions\npour les situations de troubles et tensions internes, telles que les émeutes, les actes isolés et\nsporadiques de violence ou les actes de nature similaire."},{"id":"a-hrc-38-crp-1-p0333","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"333","seq":333,"section":"B. Crimes de guerre","text":"Trois conditions contextuelles doivent être réunies pour qu’il y ait un crime de\nguerre : (i) l’existence d’un conflit armé ; (ii) un lien de rattachement entre le crime\ncommis et le conflit armé ; et (iii) la connaissance de la part de l’auteur du crime des\ncirconstances de fait établissant l’existence d’un conflit armé."},{"id":"a-hrc-38-crp-1-p0334","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"334","seq":334,"section":"B. Crimes de guerre","text":"Comme l’a souligné la CPI, à la différence du Protocole additionnel II de 1977 aux\nquatre Conventions de Genève, l’article 8(2)(f) du Statut de Rome exige seulement\nl’existence d’un conflit opposant de manière prolongée des groupes armés organisés, et non\npas que ces groupes armés exercent sur une partie du territoire un contrôle tel qu’il leur\npermette de mener des opérations militaires continues et concertées809. En outre, l’exigence\npolitique, racial, national, ethnique, culturel, religieux ou sexiste au sens de l’article 7(3) du Statut de\nRome, ou à d’autres critères universellement reconnus comme inadmissibles en droit international ;\net (iv) Le comportement était commis en corrélation avec tout acte visé à l’article 7(1) du Statut de\nRome ou avec tout crime relevant de la compétence de la CPI.\nénoncée à l’article 1(1) du Protocole additionnel II de 1977 que les groupes armés\norganisés soient sous la conduite d’un commandement responsable n’est pas incorporée par\nl’article 8(2)(f) du Statut de Rome810. A la place, les groupes armés organisés doivent\nprésenter un degré d’organisation suffisant pour leur permettre de mener un conflit armé\nprolongé811."},{"id":"a-hrc-38-crp-1-p0335","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"335","seq":335,"section":"B. Crimes de guerre","text":"Les crimes de guerre se distinguent des infractions criminelles ordinaires par le\ncontexte dans lequel ils sont commis. Il doit en effet exister un lien de rattachement\nsubstantiel entre le crime et le conflit armé, d’où l’insertion des termes « dans le contexte\nde et était associé à un conflit armé » non-international dans les éléments des crimes.\nComme l’a rappelé la Chambre d’appel du TPIY, un « crime de guerre n’est pas\nnécessairement un acte planifié ou le fruit d’une politique quelconque. Un lien de cause à\neffet n’est pas exigé entre le conflit armé et la perpétration du crime mais il faut, à tout le\nmoins, que l’existence du conflit armé ait considérablement pesé sur la capacité de l’auteur\ndu crime à le commettre, sa décision de le commettre, la manière dont il l’a commis ou le\nbut dans lequel il l’a commis »812. Afin de déterminer si un crime donné est suffisamment\nlié au conflit armé, les indices suivants peuvent être utiles : (i) le fait que l’auteur soit un\ncombattant ; (ii) le fait que la victime ne soit pas un combattant ou appartienne au camp\nadverse ; (iii) le fait que l’acte pourrait être considéré comme servant l’objectif ultime\nd’une campagne ou stratégie militaire ; et (iv) le fait que la commission du crime participe\ndes fonctions officielles de son auteur ou s’inscrive dans leur contexte813."},{"id":"a-hrc-38-crp-1-p0336","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"336","seq":336,"section":"B. Crimes de guerre","text":"Le dernier élément contextuel est que l’auteur du crime doit connaître les\ncirconstances de fait établissant l’existence d’un conflit armé ainsi que le lien entre son\ncomportement et le conflit armé. Cet élément doit être lu en conjonction avec l’introduction\ndes éléments des crimes figurant à l’article 8 du Statut de Rome, qui clarifie premièrement\nqu’ « [i]l n’est pas nécessaire d’établir que l’auteur a déterminé sur le plan juridique\nl’existence d’un conflit armé ou le caractère international ou non international du conflit ».\nDe ce point de vue, il n’est par conséquent pas nécessaire d’établir que l’auteur du crime a\neu connaissance des faits établissant le caractère international ou non international du\nconflit. Il suffit simplement que l’auteur du crime ait eu la connaissance des circonstances\nde fait établissant l’existence d’un conflit armé, ce qui est implicite dans le deuxième\nélément contextuel des crimes de guerre qui contient les termes « a eu lieu dans le contexte\nde et était associé à ».\n1.         Éléments contextuels\na.   Existence d’un conflit armé ne présentant pas un caractère international"},{"id":"a-hrc-38-crp-1-p0337","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"337","seq":337,"section":"B. Crimes de guerre","text":"A partir d’août 2016 et durant l’époque des faits visés dans le présent rapport, il\nexistait dans la région du Kasaï un conflit opposant les forces de défense et de sécurité de la\nRDC et la milice Kamuina Nsapu. Les caractéristiques de ce conflit sont typiques d’une\n« guerre asymétrique », une guerre qui oppose la force armée d’un Etat à un groupe armé\nde force inégale. Il s’agit essentiellement d’un conflit violent entre, d’une part, des forces\narmées et de sécurité étatiques et, d’autre part, une milice moins équipée, moins nombreuse\nmais toutefois résistante. L’asymétrie du conflit s’illustre également sous la forme d’une\n« guerre irrégulière » qui révèle une lutte violente entre des acteurs étatiques et non-\nétatiques pour promouvoir leur légitimité et leur influence sur les populations concernées."},{"id":"a-hrc-38-crp-1-p0338","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"338","seq":338,"section":"B. Crimes de guerre","text":"De plus, l’aspect irrégulier de ce conflit est renforcé par l’invocation, l’utilisation et la\ntentative de manipulation à des fins tactiques de soi-disant forces surnaturelles, considérées\npar la plupart des combattants des deux côtés comme une puissante ressource\nd’autoprotection en cas de danger, en particulier lors de l’entrée dans le combat. Par\nconséquent, ce conflit s’illustre également par la consommation – souvent forcée – de\ndrogues et la commission d’actes d’extrême cruauté (amputations, décapitations, actes\nd’anthropophagie, exposition des enfants au combat et à la mort, etc.) afin de réaliser\ncertains rituels propres à ce conflit."},{"id":"a-hrc-38-crp-1-p0339","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"339","seq":339,"section":"B. Crimes de guerre","text":"Afin d’appréhender si cette guerre s’apparente à un conflit armé non-international, il\nconvient dès lors de l’envisager à la lumière des deux critères permettant d’établir\nl’existence d’un tel conflit, à savoir : (i) un niveau minimum d’organisation des parties ; et\n(ii) l’intensité de la violence814.\nNiveau minimum d’organisation des parties"},{"id":"a-hrc-38-crp-1-p0340","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"340","seq":340,"section":"B. Crimes de guerre","text":"Comme mentionné précédemment dans ce rapport, le chef coutumier Kamuina Nsapu,\nJean Prince Mpandi, a créé une milice et lancé officiellement son mouvement le 28 juillet\n2016 qu’il définit comme « politico-coutumier », où le système coutumier traditionnel\nBashilange va de pair avec son action politique. Alors qu’il se réfère aux pratiques\nancestrales, y compris à la sorcellerie et à des forces considerées surnaturelles, son\nmouvement politique visa à établir sa légitimité sur la terre convoitée de manière ancestrale\npar les Bashilange et prend la forme d’une idéologie politique qui nie l’existence des\nautorités étatiques présentes sur cette terre qui se trouve à cheval sur les provinces du Kasaï\nCentral, du Kasaï, du Kasaï Oriental et de Lomami."},{"id":"a-hrc-38-crp-1-p0341","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"341","seq":341,"section":"B. Crimes de guerre","text":"Bien que peu connue du grand public, l’existence d’une chaîne de commandement au\nsein de la milice Kamuina Nsapu ressort du travail d’enquête de l’EEI. En effet, les\ncombattants Kamuina Nsapu ont des chaînes de commandement structurées autant au\nniveau de leur stratégie qu’au niveau de la mise en œuvre tactique de cette dernière."},{"id":"a-hrc-38-crp-1-p0342","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"342","seq":342,"section":"B. Crimes de guerre","text":"Du point stratégique, d’après les combattants Kamuina Nsapu eux-mêmes, ils sont\ndirigés par le chef coutumier Kamuina Nsapu, Jean Prince Mpandi, puis, après la mort de\nce dernier, par l’esprit du défunt, dont la pensée est exprimée à travers 12 « apôtres »815 ;\ndes sorciers vêtus de robes rouges qui apportent la plus haute orientation stratégique au\nmouvement. Directement en-dessous d’eux se trouve le « gardien du pouvoir », un chef\ntraditionnel de Bashila Kasanga très respecté, qui joue le rôle de porte-parole principal de\nla milice et s’occupe des questions stratégiques quotidiennes pour l’ensemble du\nmouvement. Il est soutenu dans ces fonctions par un conseil de sages opérant autour d’un\narbre sacré, qui sert les objectifs équivalent à ceux d'un état-major général présent dans un\nquartier général. Ainsi, les apôtres ont le droit de désigner « les généraux ». Ces derniers\nopèrent comme commandants tactiques du mouvement. Une fois choisi, chaque général\nsélectionne un village ou un groupement où il s’installe et, muni d’une potion rituelle\nfournie par l’apôtre qui l’a sélectionné, effectue une levée mystique en « baptisant » le chef\ncoutumier du village et des « troupes » qu’il a choisi de recruter. Le rituel nommé\n« baptême » qui formellement incorpore dans la milice les nouveaux combattants suit\ntoujours le même rituel et se déroule toujours au tshiota."},{"id":"a-hrc-38-crp-1-p0343","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"343","seq":343,"section":"B. Crimes de guerre","text":"Du point de vue de la mise en œuvre tactique de la stratégie du mouvement, la milice\nest composée de plusieurs groupes opérationnels indépendants. La structure type de ces\ngroupes est formée : (i) d’un « président », qui est un chef coutumier qui agit comme un\n« commissaire politique » ; (ii) d’un « général », qui équivaut à un commandant tactique du\ngroupe ; (iii) d’environ une dizaine d’éléments, des combattants adultes hommes et\nfemmes; (iv) d’un nombre moins élevé d’éléments mineurs, des garçons; et (v) jusqu’à cinq\n« ya mama », des petites filles. Il est fréquent que le président ait des secrétaires, tandis que\nle général a un « adjoint », qui est également son adjoint dans la chaîne de commandement.\nIl convient toutefois de noter que la structure a évolué dans le temps et en fonctions de\nl’évolution de leurs tactiques de combat et des moyens à leur disposition."},{"id":"a-hrc-38-crp-1-p0344","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"344","seq":344,"section":"B. Crimes de guerre","text":"La milice Kamuina Nsapu a également la capacité de recruter et former de nouveaux\ncombattants. Comme mentionné précédemment dans ce rapport, à partir de mai 2016, la\nmilice Kamuina Nsapu a recruté massivement de nouveaux combattants d’abord sur le\nterritoire de Dibaya, province du Kasaï Central, avant de procéder à des recrutements sur\nd’autres territoires de cette province ainsi que dans les provinces du Kasaï et du Kasaï\nOriental. Une des caractéristiques de la milice Kamuina Nsapu est sa capacité à notamment\nrecruter et utiliser des enfants comme soldats. D’après le Fonds des Nations Unies pour\nl'enfance (UNICEF) au 30 août 2017, 1 220 garçons et 658 filles auraient ainsi été recrutés\net utilisés par la milice Kamuina Nsapu816."},{"id":"a-hrc-38-crp-1-p0345","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"345","seq":345,"section":"B. Crimes de guerre","text":"La formation des nouveaux combattants, bien que sommaire, existe bel et bien. Après\navoir montré qu’ils peuvent utiliser l’arme qui leur est assignée, les « recrues » sont\nenvoyées au combat en suivant les ordres spécifiques donnés par le général en charge du\ngroupe et son adjoint. Avant chaque combat, la tactique à appliquer est expliquée de\nmanière détaillée. La tactique initiale de combat utilisée pour monter au front implique\ntrois échelons linéaires successifs composés premièrement de petites filles, les « ya mama »\nqui, selon les croyances mystiques, sont censées récolter les balles de l’ennemi dans leurs\njupes, deuxièmement de jeunes garçons armés d’armes blanches ou de bâtons magiques, et\nfinalement de combattants adultes armés de fusils traditionnels ou de chasse qui se\nrapprocheront ou non de l’ennemi en fonction de la puissance de feu de ce dernier. Au fur\net à mesure de l’intensification du conflit, la milice Kamuina Nsapu a eu recours à d’autres\ntactiques de combats, notamment à des manœuvres d’enveloppement basiques. L’envoi au\ncombat de chaque recrue est toujours précédé d’un rituel au tshiota."},{"id":"a-hrc-38-crp-1-p0346","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"346","seq":346,"section":"B. Crimes de guerre","text":"La capacité d’équiper des nouvelles recrues ainsi que celle de se procurer des armes et\nautres équipements destinés aux combats sont, en quelque sorte, simples. Les fusils\ntraditionnels – « mousquets » – et les fusils de chasse – « calibre 12 » – sont répandus dans\ntout le Kasaï. Ils sont fiables et efficaces sur de courtes distances. La poudre à canon\nnécessaire aux fusils traditionnels est une marchandise courante pour extraire les minéraux\ndans la région et les munitions des fusils sont fabriquées dans les villages en faisant fondre\nn’importe quel minerai. Les munitions des fusils de chasse sont également abondantes dans\nla région et peuvent être facilement achetées sans contrôle gouvernemental. Certains AK-\n47 volés aux FARDC font également partie de l'arsenal de la milice Kamuina Nsapu. Par\nailleurs, les machettes, flèches et lances utilisées par la milice lors de ses attaques sont\ndisponibles partout. En outre, la milice a également été capable de s’approvisionner en\narmement militaire plus lourd lors d’attaques contre certains convois des forces de défense\net de sécurité, comme par exemple lors de la saisie de deux camions de la LNI aux environs\ndu 24 mars 2017 sur l’axe entre Tshikapa-Kananga transportant un arsenal de combat\nimportant contenant notamment des armes automatiques et munitions817."},{"id":"a-hrc-38-crp-1-p0347","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"347","seq":347,"section":"B. Crimes de guerre","text":"Alors que dans une guerre irrégulière les combattants des groupes non-étatiques ne\nportent souvent pas de signes distinctifs mais se fondent avec le reste de la population afin\nd’éviter d’être identifiés, les combattants de la milice Kamuina Nsapu sont désireux d’être\nclairement perçus comme des membres du mouvement en portant ostensiblement des t-\nshirts ou jupes rouges, et/ou un ruban rouge autour de la tête qui est parfois ornée de\nrameaux, avec ou sans couteau coincé dans le ruban ou la couronne de rameaux qu’ils\nportent. Dans certains cas, certains membres de la milice arborent aussi de la chaux ou du\nkaolin blanc sur leur visage."},{"id":"a-hrc-38-crp-1-p0348","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"348","seq":348,"section":"B. Crimes de guerre","text":"Le réseau de téléphonie mobile est bien développé dans la région du Kasaï. Ainsi, les\ntéléphones portables assurent un moyen de communication efficace et bon marché et\nservent de matériel de communication principal pour relier la direction stratégique du\nmouvement avec les différents groupes de combat opérationnels, ainsi qu’entre ces\ngroupes. Ce moyen de communication, bien que simple, est essentiel afin d’assurer les\nmouvements logistiques de la milice et de transmettre les renseignements sur les forces\nennemies."},{"id":"a-hrc-38-crp-1-p0349","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"349","seq":349,"section":"B. Crimes de guerre","text":"Bien qu’il n’y ait pas de règlement interne écrit au sein de la milice Kamuina Nsapu,\nil existe une tradition orale bien connue de tous les miliciens décrivant ce qu’un combattant\nbaptisé devrait et ne devrait pas faire, y compris avant les phases de combats. Les interdits\ncomprennent notamment de ne pas toucher à l’argent d’autrui, de ne pas voler, de ne pas\ntuer quelqu’un de son propre groupe, de ne pas prendre la femme d’autrui, de ne pas fixer\nou toucher une femme ni d’avoir de relations sexuelles avant le combat, de ne pas tromper\net de ne pas manger certains aliments spécifiques818. La même tradition orale prévoit\négalement les sanctions disciplinaires pour les violations des ordres donnés et le non-\nrespect des interdits. Ces sanctions disciplinaires et leur mise en œuvre en pratique,\nrenforcée par la crainte de sanctions mystiques, servent notamment à s’assurer de\nl’exécution des ordres donnés au sein de la milice819 et témoignent d’une certaine\norganisation."},{"id":"a-hrc-38-crp-1-p0350","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"350","seq":350,"section":"B. Crimes de guerre","text":"Au début de la campagne, des communiqués publics ont été émis par le chef Kamuina\nNsapu, Jean-Prince Mpandi, principalement en diffusant par le biais de téléphones\nportables et d’internet des vidéos de ses discours aux membres du mouvement afin de faire\nconnaître l’idéologie et les buts du mouvement, de recruter de nouveaux combattants et\nd’appeler à la résistance contre les autorités étatiques. Après la mort du chef Kamuina\nNsapu, les communiqués officiels ont été faits oralement et transmis par des messagers\nspéciaux qui venaient dans les villages et, au nom des autorités du mouvement, exhortaient\nle chef coutumier dudit village à se joindre au mouvement ; s’assurant également de la\ntransmission de ce communiqué au sein de la population."},{"id":"a-hrc-38-crp-1-p0351","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"351","seq":351,"section":"B. Crimes de guerre","text":"La capacité de la milice Kamuina Nsapu à définir une stratégie militaire cohérente, à\ncontrôler le territoire, ainsi qu’à planifier et lancer des opérations militaires coordonnées\nressort de manière claire de plusieurs opérations décrites précédemment dans ce rapport.\nPar exemple, les détails de l’attaque menée en mars 2017 par la milice contre la ville de\nLuebo, province du Kasaï, permettent notamment de mettre cette capacité en exergue. Lors\nde cette attaque, deux généraux de la milice Kamuina Nsapu avaient initialement comme\nobjectif stratégique militaire de prendre la ville en entrant par des directions différentes.\nLeur tactique – consistant en une manœuvre d’enveloppement – ayant été déjouée par\nl’engagement des éléments des FARDC présents dans cette ville, les généraux décidèrent\nde retirer leurs troupes afin d’attendre le renfort de troupes supplémentaires de la milice en\nchemin vers la ville. Ayant obtenu des renseignements sur le départ des FARDC de la ville,\nils lancèrent alors une attaque dirigée par divers généraux contre les éléments de la PNC,\nseule force de sécurité encore présente alors à Luebo mais néanmoins peu armée ; leur\npermettant ainsi de saisir et conquérir la ville et de maintenir leur présence et contrôler ce\nterritoire pendant une quinzaine de jours."},{"id":"a-hrc-38-crp-1-p0352","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"352","seq":352,"section":"B. Crimes de guerre","text":"La milice Kamuina Nsapu a également la capacité de mener des opérations militaires\nà grande échelle, c’est-à-dire de mener des actions militaires engageant les forces de l’Etat\nde manière simultanée dans des points très éloignés géographiquement. Divers facteurs y\ncontribuent. Premièrement, la population Bashila Kasanga et plus largement la population\nBashilange propre à être acquise à la cause et donc à rejoindre le mouvement Kamuina\nNsapu est majoritaire au Kasaï et présente sur une grande partie du théâtre des opérations.\nPar conséquent, la milice a accès à de la main d’œuvre pour lancer des attaques contre les\nforces étatiques sur l’ensemble de l’étendue de son théâtre d’opération sans devoir recourir\nà de grands mouvements de troupes. Le fait que le processus de recrutement par baptême\nde nouveaux combattants soit extrêmement rapide favorise également la disponibilité de\ntroupes de manière presque immédiate dans le temps. Finalement, la disponibilité et\nl’efficacité du réseau de téléphonie mobile couvrant toute la région correspondant au\nthéâtre des opérations permet d’assurer la simultanéité des attaques et de faciliter l’échange\nde renseignements sur les mouvements des forces ennemies."},{"id":"a-hrc-38-crp-1-p0353","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"353","seq":353,"section":"B. Crimes de guerre","text":"En outre, malgré l’asymétrie du conflit, la milice Kamuina Nsapu est capable de\nmener des attaques contre des cibles militaires tactiques suivant une stratégie militaire\ncohérente visant notamment à s’attaquer aux symboles de l’Etat. Parmi d’autres exemples,\non notera l’attaque de l’aéroport de Kananga, province du Kasaï Central, les 22 et 23\nseptembre 2016 ainsi que plus généralement les attaques commises contre la ville elle-\nmême durant les premiers mois de 2017 ; la destruction des bureaux des FARDC, de la\nCENI et de l’administration territoriale à Kena Nkuna, province du Kasaï Oriental, le 14\noctobre 2016 ; la destruction de l’Etat-major de la PNC à Bukonde dans le territoire de\nDibaya, province du Kasaï Central, le 8 décembre 2016 ; ainsi que l’attaque contre 37\néléments de la LNI et la saisie de deux camions contenant du matériel de guerre, dans la\nprovince du Kasaï, aux alentours du 24 mars 2017."},{"id":"a-hrc-38-crp-1-p0354","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"354","seq":354,"section":"B. Crimes de guerre","text":"Finalement, la milice Kamuina Nsapu a également la capacité de déployer et\nregrouper des troupes en fonction des besoins stratégiques. Cela est notamment illustré par\nle fait que des éléments de la milice recrutés dans le territoire de Dibaya, province du Kasaï\nCentral, aient été envoyés en renfort pour mener des combats dans le territoire de Kabeya-\nKamwanga, province du Kasaï Oriental, ou encore par le fait que certains haut-dirigeants\ndu mouvement aient été identifiés lors des principales attaques commises aussi bien dans la\nprovince du Kasaï Central, que dans celles du Kasaï Oriental et du Kasaï.\nIntensité de la violence"},{"id":"a-hrc-38-crp-1-p0355","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"355","seq":355,"section":"B. Crimes de guerre","text":"La confrontation ouverte entre la milice Kamuina Nsapu et les forces de défense et de\nsécurité étatiques a débuté en juin 2016 par l’érection de barrages routiers et de points de\ncontrôle dans le territoire de Dibaya, province du Kasaï Central, afin de contrôler la\ncirculation des éléments des FARDC et autres agents de l’État. Elle s’est ensuite\nrapidement transformée en affrontements armés impliquant des massacres de civils, des\nincendies de villages entiers et des attaques armées contre tous les représentants et\nsymboles de l’autorité étatique, endommageant ou détruisant de nombreux bâtiments\npublics, y compris des écoles, des centres de santé, des églises, des commissariats de police\net des bureaux ou lieux hébergeant des éléments des FARDC. Après la mort du chef\ncoutumier Kamuina Nsapu, Jean-Prince Mpandi, en août 2016, le conflit s’est encore\nintensifié notamment du point de vue du nombre, de la fréquence et de la gravité des\naffrontements armés et s’est également propagé à l’ensemble du territoire géographique\ncomposé des Bashila Kasanga au sein de la région du Kasaï, qui s’étend sur quatre\nprovinces ; un territoire d’environ la taille du Libéria et peuplé d’environ 5 millions de\npersonnes."},{"id":"a-hrc-38-crp-1-p0356","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"356","seq":356,"section":"B. Crimes de guerre","text":"Bien que l’ampleur des massacres et des destructions depuis juillet 2017 se soit\nquelque peu amoindrie, le conflit se poursuit deux années après qu’il ait éclaté et des\ntueries continuent des deux côtés tout comme les destructions et les déplacements de\npopulations liés à ces incidents. Avec un bilan actuel de plusieurs milliers de morts,\nd’environ 1,4 million de déplacés internes et d’environ 35 000 réfugiés en Angola, le\nconflit dans la région du Kasaï choque par le nombre de victimes et le nombre de civils\nayant fui les combats."},{"id":"a-hrc-38-crp-1-p0357","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"357","seq":357,"section":"B. Crimes de guerre","text":"Dès le début, le conflit a mobilisé non-seulement des agents de la PNC, mais aussi des\néléments des FARDC. En effet, le 9 août 2016 déjà, un contingent de la 21ème région\nmilitaire provenant de la zone de Mbuji-Mayi, province du Kasaï Oriental, atterrit à\nl’aéroport de Kananga, capitale de la province du Kasaï Central, afin de renforcer les\nFARDC du 2011ème régiment déjà présents. Très rapidement, le conflit a mobilisé environ 3\n500 éléments des FARDC, commandés à partir de Mbuji-Mayi, province du Kasaï Oriental,\nainsi que tous les agents de la PNC présents dans la région du Kasaï. En décembre 2016, le\ndéploiement des FARDC a atteint un nombre de 7 000 éléments, les poussant à déplacer\nleur poste de commandement à Kananga. Afin de faire face à l’intensité de la violence, le 9\nmars 2017, un secteur militaire opérationnel a été créé par l’Ordonnance n° 17/002820. De\nplus, la PNC a eu recours à la LNI afin de faire face à cette situation. Si le chiffre de 7 000\néléments a ensuite été réduit à partir d’octobre 2017, le nombre de FARDC actuellement\ndéployés dans la région s’élève toujours à 4 500 éléments et le secteur opérationnel\nmilitaire est toujours en place."},{"id":"a-hrc-38-crp-1-p0358","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"358","seq":358,"section":"B. Crimes de guerre","text":"Alors que le nombre de personnes mobilisées en tant que combattants par la milice\nKamuina Nsapu dépasserait 3 500, la pertinence du nombre de combattants au sein de la\nmilice doit être relativisée par rapport à la guerre qu’elle mène ; le plus important dans ce\nconflit étant la capacité de la milice à accéder à de la main d’œuvre sur l’ensemble de\nl’étendue de son théâtre d’opération et d’incorporer rapidement de nouveaux combattants\npar un processus de baptême extrêmement rapide qui favorise la disponibilité de troupes de\nmanière presque immédiate dans le temps. Cela constitue un défi pour la capacité\nlogistique et opérationnelle des FARDC ; incapables d’être tout le temps à tous les endroits\nsur le théâtre des opérations."},{"id":"a-hrc-38-crp-1-p0359","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"359","seq":359,"section":"B. Crimes de guerre","text":"L’armement utilisé dans cette guerre irrégulière est de deux sortes. Du point de vue\nmilitaire, l’équipement de la milice Kamuina Nsapu est composé d’armes plutôt simples et\nadaptées à la taille de ses divers combattants : bâtons, machettes, arcs et flèches, lances,\nfusils traditionnels (« mousquets »), fusils de chasse (« calibre 12 ») et AK-47. Néanmoins,\nil convient de rappeler qu’en parallèle à l’intensification des combats, la milice a également\nété capable de s’approvisionner en armement militaire plus lourd lors d’attaques contre\ncertains convois des forces de défense et de sécurité821. Du côté des forces étatiques, il\nconvient de souligner l’utilisation d’armement plus lourd, comprenant notamment des\narmes automatiques, du type AK47, et des lance-roquettes."},{"id":"a-hrc-38-crp-1-p0360","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"360","seq":360,"section":"B. Crimes de guerre","text":"L’autre type d’armement auquel la milice Kamuina Nsapu a recours est de type\nsurnaturel. Le baptême des combattants Kamuina Nsapu est considéré pouvoir fournir à ces\nderniers différents degrés de protection lorsqu’ils mènent des opérations militaires. Cette\ninfluence surnaturelle étant reconnue par les forces étatiques présentes dans la région, des\ninformations fournies à l’EEI indiquent qu’un certain nombre d’officiers, même très haut\ngradés, des FARDC auraient subi un baptême semblable afin d’insuffler le sentiment\nd’invulnérabilité parmi leurs troupes. En réponse à ce développement et dans un esprit\nd’escalade de cet armement psychologique, en janvier 2018, la milice Kamuina Nsapu\naurait institué un nouveau type de baptême, considéré comme plus puissant, afin de\nl’emporter sur celui des FARDC."},{"id":"a-hrc-38-crp-1-p0361","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"361","seq":361,"section":"B. Crimes de guerre","text":"Le fait d’être organisé en petites unités n’empêche pas la milice Kamuina Nsapu de\ndévelopper et contrôler certaines lignes de front. Similairement au mouvement ancestral\ndes Lubas en direction de l’ouest, les combattants de la milice Kamuina Nsapu ont, à partir\nde mai 2017, forcé tous les Chokwes vivant au nord-est de Tshikapa à fuir vers la rive\nouest de la rivière Kasaï. Jusqu’à aujourd’hui, les combattants Kamuina Nsapu ont\nmaintenu cette ligne de front qui correspond ethniquement à la limite du territoire occupé\npar les Bashila Kasanga.\nConclusion sur l’existence d’un conflit armé non-international"},{"id":"a-hrc-38-crp-1-p0362","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"362","seq":362,"section":"B. Crimes de guerre","text":"L’EEI a des motifs raisonnables de croire que la milice Kamuina Nsapu était un\ngroupe armé bénéficiant d’un niveau minimum d’organisation et que l’intensité de la\nviolence avait atteint un niveau suffisant pour établir l’existence d’un conflit armé non-\ninternational en droit international humanitaire. Elle est donc de l’avis qu’à partir d’août\n2016 et durant l’époque des faits visés dans le présent rapport, il existait dans la région du\nKasaï un conflit armé non-international prolongé opposant les FARDC, soutenus par la\nPNC, et la milice Kamuina Nsapu.\nb.   Lien de rattachement entre les crimes et le conflit armé"},{"id":"a-hrc-38-crp-1-p0363","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"363","seq":363,"section":"B. Crimes de guerre","text":"Les crimes commis par des éléments des FARDC et de la milice Kamuina Nsapu l’ont\nété dans le contexte de et étaient associés au conflit armé non-international opposant les\ndeux parties. Les facteurs suivants lui permettant de faire cette détermination : (i) les\nauteurs des crimes commis étaient, pour la majorité, des éléments des FARDC et de la\nmilice Kamuina Nsapu qui étaient des combattants au moment de la commission desdits\ncrimes ; (ii) un large éventail des crimes commis l’ont été durant les affrontements\nopposant les deux parties au conflit ou immédiatement avant ou après; (iii) les victimes de\nleurs crimes étaient soit des civils soit des personnes appartenant au camp adverse ayant été\nmises hors de combat ; (iv) les crimes commis par les FARDC, dans la majorité des cas,\nservent l’objectif ultime de la stratégie militaire visant à combattre la milice Kamuina\nNsapu dans la région du Kasaï ; ils sont en effet compris dans le cadre d’une campagne de\nrépression des membres de cette milice ou lui étant assimilée, alors que ceux commis par la\nmilice Kamuina Nsapu peuvent, dans la majorité des cas, être considérés comme servant\nl’objectif ultime de son mouvement ; et (v) la commission de la majorité de ces crimes\nparticipent des fonctions « officielles » de leurs auteurs soit en tant que membres des\nFARDC ou en tant qu’éléments de la milice Kamuina Nsapu.\nc.   Connaissances des circonstances de fait établissant l’existence d’un conflit armé"},{"id":"a-hrc-38-crp-1-p0364","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"364","seq":364,"section":"B. Crimes de guerre","text":"Vu l’ampleur du conflit armé entre les FARDC et la milice Kamuina Nsapu dans\nquatre provinces pendant une période prolongée et l’impact qu’il a eu au niveau régional,\nnotamment le déplacement de 1,4 millions de déplacés internes, la destruction de villages\nentiers et, à partir du 9 mars 2017, la création d’un secteur opérationnel militaire dans la\nrégion, il est difficile d’imaginer, dans le contexte propre à l’espèce, que les auteurs\nprésumés de ces crimes pouvaient ignorer les circonstances de fait permettant d’établir\nl’existence d’un conflit armé.\n2.   Typologie des crimes commis\na.   Par les FARDC"},{"id":"a-hrc-38-crp-1-p0365","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"365","seq":365,"section":"B. Crimes de guerre","text":"Les éléments contextuels des crimes de guerre étant d’après elle réunis, l’EEI a des\nmotifs raisonnables de croire que des éléments des FARDC ont notamment commis les\ncrimes de guerre suivants :\nMeurtre constitutif d’atteinte à la vie (Art. 8(2)(c)(i) du Statut de Rome ; Art.\n223(3)(a) du Code pénal de la RDC)822"},{"id":"a-hrc-38-crp-1-p0366","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"366","seq":366,"section":"B. Crimes de guerre","text":"Les meurtres des membres de la population civile ne prenant pas activement part aux\nhostilités commis par des éléments des FARDC et ayant été qualifiés de crimes contre\nl’humanité ci-dessus823 constituent également des meurtres constitutifs d’atteintes à la vie\nqui sont des crimes de guerre. Sont également qualifiables d’atteintes à la vie constitutives\nde crimes de guerre, les meurtres des éléments de la milice Kamuina Nsapu, en majorité\ndes filles et des garçons, étant hors de combat. Cela inclut notamment les enfants qui ont\nété blessés par balles et gisant au sol dans l’incapacité de se défendre et qui ont été achevés\nfroidement à bout portant par des éléments des FARDC comme cela ressort de nombreux\ntémoignages et de plusieurs vidéos filmant ces crimes."},{"id":"a-hrc-38-crp-1-p0367","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"367","seq":367,"section":"B. Crimes de guerre","text":"Par contre, les cas dans lesquels des éléments de la milice Kamuina Nsapu, y compris\ndes filles et garçons, ont été tués par des FARDC alors qu’ils exerçaient une « fonction de\ncombat continue »824 ne constituent pas des atteintes à la vie constitutives de crime de\nguerre. En effet, ces éléments de la milice perdent le bénéfice de l’immunité contre les\nattaques directes – en d’autres termes d’être tués – aussi longtemps qu’ils assument leur\nfonction de combat continue, peu importe leur âge ou le fait qu’ils aient été contraints\nd’assumer cette fonction825. Il en va de même des cas où des personnes civiles ont été tuées\npar des FARDC pendant la durée où ils participaient directement aux hostilités, peu\nimporte leur âge ou le fait qu’ils aient été contraints de participer directement aux\nhostilités826. Ces derniers cas ne constituent également pas des crimes de guerre827.\nTraitements cruels828 et torture829 constitutifs d’atteinte à l’intégrité corporelle\n(Art. 8(2)(c)(i) du Statut de Rome ; Art. 223(3)(a) du Code pénal de la RDC)"},{"id":"a-hrc-38-crp-1-p0368","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"368","seq":368,"section":"B. Crimes de guerre","text":"Les tortures et autres actes inhumains commis par des membres des forces de défense\net de sécurité et ayant été qualifiés de crimes contre l’humanité ci-dessus830 constituent\négalement des traitements cruels constitutifs d’atteintes à l’intégrité corporelle qui sont des\ncrimes de guerre. Lorsque les douleurs ou souffrances aiguës, physiques ou mentales, ont\nété infligées par les membres des forces de défense et de sécurité afin, notamment, de\npunir, d’intimider ou de contraindre, ces mêmes actes constituent des tortures constitutives\nd’atteintes à l’intégrité corporelle qualifiables de crimes de guerre. C’est par exemple le cas\nde ces actes lorsqu’ils ont été commis lors d’opérations punitives.\nLe fait de diriger intentionnellement des attaques contre la population civile\nen tant que telle ou contre des personnes civiles qui ne participent pas\ndirectement aux hostilités (Art. 8(2)(e)(i) du Statut de Rome ; Art. 223(5)(a) du\nCode pénal de la RDC)831"},{"id":"a-hrc-38-crp-1-p0369","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"369","seq":369,"section":"B. Crimes de guerre","text":"Comme mentionné ci-dessus832, des éléments FARDC ont intentionnellement lancé\nd’innombrables attaques dont l’objectif était de prendre pour cible des civils de l’ethnie\nluba ou identifiés comme tels en raison de leur soutien supposé à la milice Kamuina Nsapu\nalors même que ces derniers ne prenaient pas directement part aux hostilités. Ces attaques\nont notamment eu lieu lorsqu’ils sont arrivés dans des villages composés à majorité de\nLubas et ont attaqué les membres de la population civile qui vaquaient à leurs occupations\nalors qu’il n’y avait pas de miliciens Kamuina Nsapu ou lorsque, durant des opérations\nporte à porte, ils ont ciblé des civils."},{"id":"a-hrc-38-crp-1-p0370","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"370","seq":370,"section":"B. Crimes de guerre","text":"En ce qui concerne les nombreuses attaques indiscriminées qui ont été menées par les\nFARDC durant le conflit armé, elles ne relèvent pas toutes automatiquement de ce crime.\nLes seules susceptibles de relever de ce crime sont celles qui intentionnellement visaient la\npopulation civile ou des civils, ce qui est notamment le cas lorsque les dommages causés\naux civils sont si importants qu’il apparaît que les FARDC avaient l’intention de prendre\nle but légitime du conflit, à savoir la soumission complète ou partielle de l’ennemi le plus tôt possible\navec le coût minimum en vies humaines et en moyens engagés – et le principe d’humanité – qui\ninterdit d’infliger des souffrances, des blessures ou des destructions qui ne sont pas véritablement\nnécessaires pour atteindre des buts militaires légitimes. En d’autres termes, sous l’effet conjoint de\nces deux principes, les actions militaires ne doivent pas excéder ce qui est véritablement nécessaires\npour atteindre un but militaire légitime dans les circonstances qui prévalent. Voir ibid., pp. 80, 82.\ndes objectifs civils pour cible. En revanche, les situations dans lesquelles l’attaque est\ndirigée contre un objectif militaire mais que des civils sont touchés incidemment ne\npeuvent pas être constitutives de ce crime833.\nPillage d’une ville ou d’une localité (Art. 8(2)(e)(v) du Statut de Rome ; Art.\n223(5)(e) du Code pénal de la RDC)834"},{"id":"a-hrc-38-crp-1-p0371","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"371","seq":371,"section":"B. Crimes de guerre","text":"Lors de leur déploiement dans de nombreuses villes ou villages dans la région du\nKasaï où ils ont affronté la milice Kamuina Nsapu, des éléments des FARDC se sont\nsystématiquement appropriés à des fins privées ou personnelles, et ce sans le consentement\nde leurs propriétaires légitimes, toutes sortes de biens appartenant à des membres de la\npopulation civile, notamment des motos, des vélos, des chèvres, des porcs, des volailles,\ndes machines à coudre, des bidons de carburants, du matériel information et bureautique.\nIls ont aussi pillé des maisons et des boutiques entièrement.\nViol ou toute autre forme de violence sexuelle de gravité comparable (Art.\n8(2)(e)(vi) du Statut de Rome ; Art. 223(5)(f) du Code pénal de la RDC)835 :"},{"id":"a-hrc-38-crp-1-p0372","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"372","seq":372,"section":"B. Crimes de guerre","text":"Les viols et autres formes de violences sexuelles commis par des éléments des\nFARDC et ayant été qualifiés de crimes contre l’humanité ci-dessus836 constituent\négalement des viols et d’autres formes de violences sexuelles constitutifs de crime de\nguerre.\nb.   Par la milice Kamuina Nsapu"},{"id":"a-hrc-38-crp-1-p0373","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"373","seq":373,"section":"B. Crimes de guerre","text":"Les éléments contextuels des crimes de guerre étant d’après elle réunis, l’EEI a des\nmotifs raisonnables de croire que des éléments de la milice Kamuina Nsapu ont notamment\ncommis les crimes de guerre suivants :\nMeurtre constitutif d’atteinte à la vie (Art. 8(2)(c)(i) du Statut de Rome ; Art.\n223(3)(a) du Code pénal de la RDC)837"},{"id":"a-hrc-38-crp-1-p0374","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"374","seq":374,"section":"B. Crimes de guerre","text":"Les meurtres des membres de la population civile ne prenant pas activement part aux\nhostilités commis par des éléments de la milice Kamuina Nsapu et ayant été qualifiés de\ncrimes contre l’humanité ci-dessus838 constituent également des meurtres constitutifs\nd’atteintes à la vie qui sont des crimes de guerre. Sont également qualifiables d’atteintes à\nla vie constitutives de crimes de guerre, les meurtres d’éléments des FARDC et de la PNC\nétant hors de combat, y compris lorsqu’ils sont au pouvoir de la milice ou lorsqu’ils sont en\nétat d’incapacité du fait de leurs blessures et en conséquence incapables de se défendre, à\ncondition qu’ils s’abstiennent de tout acte d’hostilité et ne tente pas de s’évader. Cela inclut\npar exemple le meurtre des éléments de la LNI capturés le 24 mars 2017.\nMutilation constitutive d’atteinte à l’intégrité corporelle839 et Mutilation840\n(Art. 8(2)(c)(i) et 8(2)(e)(xi) du Statut de Rome ; Art. 223(3)(a) et 223(5)(k) du\nCode pénal de la RDC)"},{"id":"a-hrc-38-crp-1-p0375","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"375","seq":375,"section":"B. Crimes de guerre","text":"Les cas d’amputations de parties du corps – telles que les mains, pieds, bras, jambes,\nseins, clitoris, pénis – et de défigurations permanentes de civils ou d’éléments des force de\ndéfense et de sécurité au pouvoir de la milice Kamuina Nsapu qui ont rendus infirmes de\nfaçon permanente leurs victimes et ayant été qualifiés de tortures ou d’autres acte\ninhumains constitutifs de crimes contre l’humanité ci-dessus841 constituent également des\nmutilations constitutives d’atteintes à l’intégrité corporelle qui sont des crimes de guerre en\nvertu de l’article 8(2)(c)(i) du Statut de Rome et 223(3)(a) du Code pénal de la RDC. Les\nmêmes actes qui ont causé la mort de leurs victimes, ou compromis gravement leur santé\nphysique ou mentale, sont des mutilations constitutives de crimes de guerre en vertu de\nl’article 8(2)(e)(xi) du Statut de Rome et 223(5)(k) du Code pénal de la RDC.\nTraitements cruels et torture constitutifs d’atteinte à l’intégrité corporelle\n(Art. 8(2)(c)(i) du Statut de Rome ; Art. 223(3)(a) du Code pénal de la RDC)842"},{"id":"a-hrc-38-crp-1-p0376","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"376","seq":376,"section":"B. Crimes de guerre","text":"Les tortures et les autres actes inhumains commis par des miliciens Kamuina Nsapu et\nayant été qualifiés de crimes contre l’humanité ci-dessus843 constituent également des\ntraitements cruels constitutifs d’atteintes à l’intégrité corporelle qui sont des crimes de\nguerre. Lorsque les douleurs ou souffrances aiguës, physiques ou mentales, ont été infligées\npar les membres de la milice afin, notamment, de punir, d’intimider ou de contraindre, ces\nmêmes actes constituent des tortures constitutives d’atteintes à l’intégrité corporelle\nqualifiables de crimes de guerre. C’est par exemple le cas du double viol infligé à la\npropriétaire d’un restaurant et à son beau-fils à Luebo, province du Kasaï, début avril 2017\nafin de la punir d’avoir vendu de la nourriture interdite aux miliciens844, mais également de\nnombreux actes décrits ci-dessus qui ont été commis soit dans le but d’intimider et de\ncontraindre la population civile à rejoindre la milice soit afin de la punir d’avoir refusé d’y\nadhérer.\nLe fait de diriger intentionnellement des attaques contre la population civile\nen tant que telle ou contre des personnes civiles qui ne participent pas\ndirectement aux hostilités (Art. 8(2)(e)(i) du Statut de Rome ; Art. 223(5)(a) du\nCode pénal de la RDC)845"},{"id":"a-hrc-38-crp-1-p0377","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"377","seq":377,"section":"B. Crimes de guerre","text":"Comme mentionné ci-dessus846, la milice Kamuina Nsapu a intentionnellement lancé\nd’innombrables attaques dont l’objectif était de prendre pour cible une population civile en\ngénéral ou des civils ne prenant pas directement part aux hostilités, notamment : (i) des\nfilles et garçons ainsi que des adultes pour les recruter de force dans la milice ; (ii) les\nreprésentants et fonctionnaires de l’État et tous les civils leur étant, à tort ou à raison,\nassimilés ; (iii) la population civile des villages et groupements qui aurait refusé d’adhérer\nà son mouvement ; et dans le territoire de Kamonia, province du Kasaï (iv) la population\ncivile n’appartenant pas à l’ethnie luba et ne parlant pas le tshiluba.\nLe fait de diriger intentionnellement des attaques contre des bâtiments\nconsacrés à la religion et à l’enseignement ainsi que des hôpitaux qui\nn’étaient pas des objectifs militaires (Art. 8(2)(e)(iv) du Statut de Rome ; Art.\n223(5)(d) du Code pénal de la RDC)847"},{"id":"a-hrc-38-crp-1-p0378","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"378","seq":378,"section":"B. Crimes de guerre","text":"Dans de nombreuses localités, du fait qu’ils étaient assimilés à des bâtiments publics\nreprésentant l’autorité de l’Etat, des éléments de la milice Kamuina Nsapu ont\nintentionnellement lancé des attaques dont l’objectif était un ou plusieurs bâtiments\nconsacrés à la religion, à l’enseignement, ainsi que des hôpitaux et des lieux où des\nmalades ou des blessés sont rassemblés, tant bien même qu’ils ne représentaient pas des\nobjectifs militaires848."},{"id":"a-hrc-38-crp-1-p0379","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"379","seq":379,"section":"B. Crimes de guerre","text":"Depuis, le début de la crise en août 2016 jusqu’en février 2018, l’UNICEF a ainsi\nrecensé des attaques contre 416 écoles et 224 hôpitaux ou structures de santé849. Si ces\nattaques se sont produites dans 17 territoires des cinq provinces du Kasaï, la province du\nKasaï Central – berceau du mouvement et de la milice Kamuina Nsapu – a subi le plus\ngrand nombre de ces attaques. Bien que l’EEI n’ait pas pu identifier les auteurs de\nl’ensemble de ces attaques, elle a conclu que des éléments de la milice ont commis ce\ncrime de guerre, notamment sur le territoire de Luiza, dans la province du Kasaï Central, à\npartir de 2017 où les bâtiments de l’Eglise catholique ont été une cible privilégie de la\nmilice de multiples écoles ont été détruites, y compris à Kamushiku, Kadongo et Malando,\nainsi que dans le ville de Luebo, dans la province du Kasaï, à partir du 31 mars 2017 où la\nplupart des bâtiments appartenant à l’Eglise catholique, ainsi que plusieurs écoles, ont été\ndétruits et brûlés, alors que les FARDC n’étaient pas présent dans la ville à cette date.\nViol ou toute autre forme de violence sexuelle de gravité comparable (Art.\n8(2)(e)(vi) du Statut de Rome ; Art. 223(5)(f) du Code pénal de la RDC)850"},{"id":"a-hrc-38-crp-1-p0380","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"380","seq":380,"section":"B. Crimes de guerre","text":"Les viols et autres formes de violences sexuelles commis par des éléments de la\nmilice Kamuina Nsapu et ayant été qualifiés de crimes contre l’humanité ci-dessus851\nconstituent également des crimes de guerre, y compris lorsqu’ils ont été commis par des\n846\nVoir supra, para. 283\n847\nLes éléments de ce crime sont : (i) L’auteur a lancé une attaque ; (ii) L’objectif de l’attaque était\nun ou plusieurs bâtiments consacrés à la religion, à l’enseignement […], des hôpitaux et des lieux où\ndes malades ou des blessés sont rassemblés, qui n’étaient pas des objectifs militaires ; et (iii) L’auteur\nentendait prendre pour cible de son attaque ledit ou lesdits bâtiments consacrés à la religion, à\nl’enseignement […], des hôpitaux et des lieux où des malades ou des blessés sont rassemblés, qui\nn’étaient pas des objectifs militaires.\n848\nAu vu des éléments des crimes, il n’est pas nécessaire qu’un résultat (dommage) soit démontré\npour que ce crime soit commis. Voir Roberta Arnold and Stefan Wehrenberg, “Article 8(2)(b)(ix) :\nIntentionally directing attacks against protected buildings”, in Otto Triffterer and Kai Ambos (eds.),\nThe Rome Statute of the International Criminal Court – A Commentary, C.H. Beck/Hart/Nomos,\n2016 (3rd ed.), p. 419.\nmembres de la milice Kamuina Nsapu sur des femmes et des filles ayant été contraintes de\ndevenir des membres de la milice et donc faisant partie de leurs propres troupes852.\nLe fait de procéder à la conscription ou à l’enrôlement d’enfants de moins de\n15/18 ans dans la milice ou de les faire participer activement à des hostilités\n(Art. 8(2)(e)(vii) du Statut de Rome ; Art. 223(5)(g) du Code pénal de la\nRDC)853"},{"id":"a-hrc-38-crp-1-p0381","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"381","seq":381,"section":"B. Crimes de guerre","text":"A partir du début du conflit armé en août 2016 et jusqu’à ce jour, l’expansion rapide\nde la milice Kamuina Nsapu s’est propagée grâce à un système bien organisé de\nrecrutement d’enfants. En effet, des éléments de ce groupe armé ont procédé à la\nconscription – et dans une moindre mesure à l’enrôlement – d’enfants partout où la milice\ns’est implantée ou a été active. Nombre de ces enfants ont également participé activement\naux hostilités."},{"id":"a-hrc-38-crp-1-p0382","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"382","seq":382,"section":"B. Crimes de guerre","text":"Si la conscription réfère à un recrutement forcé, l’enrôlement se réfère à un\nrecrutement volontaire. En d’autres termes, le consentement de l’enfant n’est pas un moyen\nde défense valide854. Dès lors, ce crime de guerre a été commis aussi bien lorsque les\nenfants ont rejoint la milice Kamuina Nsapu de manière « volontaire » – par exemple sur le\nterritoire de Luiza, province du Kasaï Central, où à partir de janvier 2017, des enfants ont\nrejoint la milice car ils se sont vus promettre une scolarité gratuite pour quiconque tuerait\ndes militaires ou encore dans la ville de Luebo, province du Kasaï, où en mars-avril 2017\nils se sont vus promettre 300 dollars américains, des voitures et/ou un travail – que\nlorsqu‘ils y ont été forcés, comme ce fut systématiquement le cas dans la province de\nLomami où ceux qui refusaient ont été décapités. Par ailleurs, la troisième forme de ce\ncrime de guerre a aussi été commise lorsque des éléments de la milice ont fait participer\nactivement aux hostilités des enfants, c’est-à-dire non seulement lorsque les filles et\ngarçons étaient utilisés comme combattants, mais aussi lorsqu’ils assumaient une multitude\nde rôles d’appui aux combats et que ces activités avaient un lien manifeste avec les\nhostilités."},{"id":"a-hrc-38-crp-1-p0383","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"383","seq":383,"section":"B. Crimes de guerre","text":"Tandis que l’article 8(2)(e)(vii) du Statut de Rome impose que les enfants soient âgés\nde moins de 15 ans, l’article 223(5)(g) du Code pénal de la RDC mettant en œuvre ce crime\nen droit interne impose qu’ils soient âgés de moins de 18 ans. La milice Kamuina Nsapu a\nessentiellement recruté et utilisé de jeunes enfants de moins de 15 ans et, dans une moindre\nmesure, de moins de 18 ans. Etant donné que le modus operandi de la milice consistait\nessentiellement à recruter des jeunes filles, les « ya mama », et de jeunes garçons pour les\nutiliser de manière active dans les combats, et vu l’ampleur du nombre d’enfants recrutés et\nutilisés par la milice – au 30 août 2017, l’UNICEF avait dénombré 1 220 garçons et 658\nfilles recrutés et utilisés par la milice, mais l’EEI estime que leur nombre est beaucoup plus\nélevé et que le recrutement continue notamment dans la province du Kasaï Central – l’EEI\nest d’avis qu’il est difficile d’imaginer que les auteurs présumés de ce crime ne savaient pas\nque les victimes avaient moins que 15 ans étant donné que leur stratégie visait à\nintentionnellement recruter de très jeunes enfants."},{"id":"a-hrc-38-crp-1-p0384","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"384","seq":384,"section":"C. Violations des droits de l’homme","text":"Les crimes établis ci-dessus permettent également de conclure que les droits de\nl’homme suivants ont notamment été violés : droit à la vie, droit à l’intégrité physique ou\nmentale, réduction en esclavage, interdiction du recrutement et de l’utilisation d’enfants\nsoldats, droit à la liberté et à la sécurité, et liberté de circulation. Ces violations ont eu un\nimpact direct sur la jouissance des droits économiques, sociaux et culturels de la population\ndu Kasaï."},{"id":"a-hrc-38-crp-1-p0385","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"385","seq":385,"section":"C. Violations des droits de l’homme","text":"En droit international, l’État est responsable du comportement de ses organes quelle\nque soit les fonctions exercées par ceux-ci, la position qu’ils occupent dans l’organisation\nde l’Etat, et leur nature (en tant qu’organe du gouvernement central ou d’une collectivité\nterritoriale de l’Etat)855. L’EEI est d’avis que les crimes commis par les forces de défense et\nde sécurité de la RDC énumérés ci-dessus constituent également des violations du droit\ninternational des droits de l’homme attribuable à la RDC et engageant sa responsabilité\ninternationale"},{"id":"a-hrc-38-crp-1-p0386","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"386","seq":386,"section":"C. Violations des droits de l’homme","text":"Les atteintes aux droits de l’homme commises par la milice Kamuina Nsapu et les\nmilices Bana Mura ne peuvent pas être attribuées à la RDC, car la milice Kamuina Nsapu\net/ou les milices Bana Mura : (i) n’ont pas été habilitées par le droit de cet Etat à exercer\ndes prérogatives de puissance publique856 ; (ii) n’agissaient pas sous la « totale\ndépendance » de l’Etat, dont elles n’étaient, en somme, qu’un simple instrument857 ; et (iii)\nn’agissaient pas en fait sur les instructions ou les directives ou sous le contrôle d’un Etat858.\nLa RDC n’a pas non plus reconnu et adopté leurs comportements illicites comme étant le\nsien859. En arrivant à ces conclusions, l’EEI rappelle que, bien que dans certains cas, les\nforces de défense et de sécurité de la RDC ont agi de pair avec les milices Bana Mura, ils\nse sont aussi affrontés."},{"id":"a-hrc-38-crp-1-p0387","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"387","seq":387,"section":"C. Violations des droits de l’homme","text":"Cela étant dit, en droit international des droits de l’homme, les États n’ont pas\nuniquement l’obligation de respecter les droits contenus dans les instruments\ninternationaux auxquels ils sont parties, mais également celle de protéger les individus\ncontre toute violation ou atteinte à ces droits et celle de mettre en œuvre ces droits. Dès\nlors, la RDC peut voir sa responsabilité internationale engagée pour avoir manqué à son\nobligation de protéger les droits de l’homme, étant donné qu’elle a laissé commettre sur son\nterritoire par des groupes non-étatiques des atteintes aux droits de l’homme, n’ayant\ntoujours pas pris les mesures nécessaires pour que des enquêtes soient menées sur ces\natteintes et que leurs auteurs soient arrêtés. L’État est également tenu de veiller à ce que les\nauteurs de violations répondent de leurs actes devant les juridictions nationales et que les\nvictimes, quand cela est nécessaire, reçoivent une compensation. Pour l’heure, en ce qui\n855\nArticle 4(1) du Projet d’articles sur la responsabilité de l’Etat pour fait internationale illicite,\nadopté par la Commission du droit international à sa 53ème session en 2001 et soumis à l’Assemblée\ngénérale des Nations Unies dans le cadre du rapport de la Commission sur ladite session (Projet\nd’articles sur la responsabilité de l’Etat). UN Doc. A/56/10 Supplément n° 10, 2001. L’Assemblée\ngénérale des Nations Unies a pris note du projet d’articles le 12 décembre 2001. Voir UN Doc.\nA/RES/56/83, 2001, Annexe. Voir aussi CIJ, Affaire relative à l’application de la Convention pour la\nprévention et la répression du crime de génocide (Bosnie-Herzégovine c. Serbie-et-Monténégro),\narrêt du 26 février 2007, C.I.J. Recueil 2007, p. 43, para. 385. L’article 4(2) du Projet d’articles sur la\nresponsabilité de l’Etat précise qu’ « [u]n organe comprend toute personne ou entité qui a ce statut\nd’après le droit interne de l’Etat ».\n856\nArticle 5 du Projet d’articles sur la responsabilité de l’Etat.\n857\nCIJ, Affaire relative à l’application de la Convention pour la prévention et la répression du crime\nde génocide (Bosnie-Herzégovine c. Serbie-et-Monténégro), arrêt du 26 février 2007, C.I.J. Recueil\n2007, p. 43, paras. 392-393.\nconcerne la majorité des incidents illustrés dans ce rapport, la RDC a failli à ses\nobligations."},{"id":"a-hrc-38-crp-1-p0388","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"388","seq":388,"section":"XII. Situation actuelle","text":"Si à partir d’août 2017, le niveau de violences a diminué dans toutes les provinces du\nKasaï, les actes de violence liés à la crise continuent d’être rapportés de manière régulière,\nindiquant que les causes du conflit n’ont pas été adressées, malgré la tenue, en septembre\n2017, d`une conférence sur la paix au Grand-Kasaï. Une partie des personnes déplacées par\nles violences ont pu rentrer chez elles et dans certains villages les enfants ont pu reprendre\nl’école860 ; cela n’est cependant pas le cas partout. L’EEI a concentré ses efforts dans la\ndocumentation des crimes et des violations des droits de l’homme les plus graves pendant\ntoute la durée de la crise au Kasaï, mais n’a pas pu documenter de manière systématique les\nallégations reçues pendant la période la plus récente."},{"id":"a-hrc-38-crp-1-p0389","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"389","seq":389,"section":"XII. Situation actuelle","text":"Les FARDC ont continué à faire un usage excessif de la force dans la poursuite des\nopérations contre la milice Kamuina Nsapu. Des personnes suspectées sans fondement\nd’appartenir à la milice continuent d’être détenues, battues ou tuées. Des villages où la\nprésence des miliciens est suspectée ont été pillés ou incendiés. Par exemple, le 30\nnovembre 2017, dans le territoire de Kamonia, province du Kasaï, des FARDC ont fait\nirruption dans le village de Kabeya Lumbu, après une distribution de vivres d’une\norganisation humanitaire. A la fin de la distribution, les FARDC sont arrivés à bord d’un\nvéhicule et ont ouvert le feu sur la population près du marché du village, où la distribution\navait eu lieu. Plusieurs personnes ont été tuées et blessées. La population de ce village avait\ndéjà fui après de nombreux affrontements dans le village entre la milice Kamuina Nsapu,\ntoujours présente dans la zone, et les forces de défense et sécurité en 2016 et 2017 et venait\nde rentrer au village861."},{"id":"a-hrc-38-crp-1-p0390","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"390","seq":390,"section":"XII. Situation actuelle","text":"L’EEI a relevé des cas isolés de personnes, y compris des enfants, qui auraient été\ntués de manière arbitraire par les FARDC, accusées d’appartenir à la milice Kamuina\nNsapu862. Les FARDC auraient continué à piller et incendier des villages où il y avait une\nprésence suspectée des miliciens863. De manière générale, la forte présence militaire dans le\nKasaï a continué à engendrer des extorsions et le harcèlement de la population aux\nbarrières tenues par des FARDC. Par exemple, le 23 mai 2018, des FARDC seraient venus\ntôt le matin dans le village de Tshimpidinga, territoire de Dibaya, où ils auraient arrêté de\nmanière arbitraire au moins deux hommes864."},{"id":"a-hrc-38-crp-1-p0391","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"391","seq":391,"section":"XII. Situation actuelle","text":"Dans la ville de Kananga et ses environs, entre janvier et avril 2018, des FARDC ont\ndétenu de manière arbitraire des douzaines de personnes suspectées d’être des miliciens\nKamuina Nsapu. Dans beaucoup des cas, des personnes ont été arrêtées par des militaires à\nbord d’un pick-up de couleur blanche, sans plaque d’immatriculation, et emmenées aux\ncachots à l’EFO. Certaines victimes ont été frappées par des militaires et détenues dans des\nconditions inhumaines ou dégradantes et au-delà du délai légal de garde à vue. Des sommes\nexorbitantes ont été exigées par des militaires afin de libérer les détenus865."},{"id":"a-hrc-38-crp-1-p0392","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"392","seq":392,"section":"XII. Situation actuelle","text":"Dans la partie sud du territoire de Kamonia, province de Kasaï, les personnes,\nprincipalement des Lubas, qui retournaient d’Angola, ont été extorquées et harcelées à des\nbarrières érigées par les autorités congolaises et des miliciens Bana Mura sur les routes\nfréquentées par les déplacés. La présence des miliciens Bana Mura dans cette zone aurait\nempêché des personnes lubas de rentrer et se réinstaller dans leurs villages d’origine, et\naurait occasionné leur déplacement vers la province de Kasaï Central. Cette situation\nperdure. De vives tensions entre les Chokwes et les Lubas dans cette partie du territoire de\nKamonia se sont manifestées et continuent de se manifester par des attaques sur des\nvillages par des miliciens Bana Mura et des affrontements entre les miliciens Bana Mura et\nles Lubas concernant l’accès aux sites miniers866. Par ailleurs, des allégations récentes, qui\nrestent à vérifier, suggèrent que les milices Bana Mura continueraient de recevoir des\narmes et tiendraient des réunions secrètes dans la ville de Tshikapa et la cité de Kamonia\ndont le but serait de préparer des actions ciblant les Lubas867."},{"id":"a-hrc-38-crp-1-p0393","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"393","seq":393,"section":"XII. Situation actuelle","text":"Pendant cette période l’EEI a documenté des cas des femmes Lubas qui continuent à\nêtre réduites à une situation d’esclavage, notamment sexuel, par des membres de l'ethnie\nchokwe dans le territoire de Kamonia, province de Kasaï868. Malgré des efforts de plaidoyer\nde la MONUSCO, la réaction des forces de défense et de sécurité congolaises face à ces\ncrimes reste insuffisante."},{"id":"a-hrc-38-crp-1-p0394","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"394","seq":394,"section":"XII. Situation actuelle","text":"Depuis décembre 2017, au moins 16 personnes auraient été tuées, des maisons\nincendiées et des milliers de personnes déplacées suite à de multiples affrontements entre\ndes miliciens d’ethnie Bakete associés à la milice Kamuina Nsapu et les FARDC, soutenus\npar la population d’ethnie Bakuba, dans la zone de Kakenge, territoire de Mweka, province\ndu Kasaï869."},{"id":"a-hrc-38-crp-1-p0395","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"395","seq":395,"section":"XII. Situation actuelle","text":"La milice Kamuina Nsapu est restée active, surtout au Kasaï Central et continue de\nrecruter, y compris des enfants, et à mener des attaques même si leur ampleur a diminué870.\nPar exemple, dans la nuit du 30 avril 2018, des miliciens ont attaqué et tué le chef\ncoutumier par intérim du village de Kamuina Nsapu, qui était proche des autorités\nprovinciales, ainsi que trois membres de sa famille. Le 9 mai 2018 des miliciens Kamuina\nNsapu auraient tué par décapitation quatre personnes dans le village de Mulombela,\nterritoire de Dibaya et le 26 mai 2018 des miliciens Kamuina Nsapu auraient tué trois\nfemmes par décapitation dans le village de Dibaya, territoire de Dibaya871."},{"id":"a-hrc-38-crp-1-p0396","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"396","seq":396,"section":"XII. Situation actuelle","text":"Le durcissement du conflit va dépendre de la capacité de la milice Kamuina Nsapu à\nattirer des fonds en échange de protection, de liberté de circulation ou d’opérer une activité\néconomique, notamment pour l’exploitation des diamants et de minéraux stratégiques dans\nleur aire d’influence. Le conflit pourrait également s’étendre si le peuple Bashila Kasanga\nde la région Lunda-Nord de l’Angola décidait de soutenir l’effort de guerre des Bashilange\ndont ils sont parents. Le conflit au Kasaï représente une menace au plan national."},{"id":"a-hrc-38-crp-1-p0397","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"397","seq":397,"section":"XII. Situation actuelle","text":"La situation politique en RDC reste tendue et il n’est pas exclu que les derniers\ndéveloppements puissent avoir une influence sur la situation au Kasaï. Les élections\nlégislatives et présidentielles sont prévues le 23 décembre 2018. La constitution limitant à\ndeux le nombre de mandats présidentiel, l’actuel président Joseph Kabila n'est pas autorisé\nà se représenter. Cependant, à ce jour, le Président ne s’est pas encore prononcé sur une\n866\nDocuments internes MONUSCO.\n867\nDocument interne MONUSCO.\n868\nT0375, documents internes MONUSCO.\n869\nDocument interne MONUSCO, https://reliefweb.int/report/democratic-republic-congo/drc-msf-\ntreats-20-people-after-deadly-attack-kasai-region.\néventuelle troisième candidature872. Par ailleurs, un projet de loi qui vise à introduire de\nnouvelles restrictions sur les activités des organisations non gouvernementales nationales et\ninternationales en RDC devrait être bientôt examiné par le Parlement. Dans sa forme\nactuelle, le projet de loi risque de réduire l’espace civique, la liberté d'association dans le\npays et la présence d’organisations non gouvernementales sur le terrain873. Dans un\ncommuniqué de presse, les experts des droits de l’homme de l’ONU estiment que « toutes\nces exigences [du projet de loi] menacent la capacité de la société civile à mener leurs\nactivités, et soulignent une volonté de museler les voix dissidentes »874."},{"id":"a-hrc-38-crp-1-p0398","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"398","seq":398,"section":"A. Conséquences humanitaires","text":"Au cours de son travail, l’EEI a été alarmée par la situation humanitaire, en particulier\nla situation très précaire dans laquelle se trouvent les populations déplacées en raison des\nviolences. La réponse financière à la crise humanitaire reste bien inférieure aux besoins. Si\nen raison d’infrastructures peu développées, l’accès aux populations dans le besoin dans le\nKasaï demeure un défi pour les acteurs humanitaires, il faut noter que les autorités\nnationales ainsi que provinciales ont parfois refusé l’accès aux agences humanitaires des\nNations Unies, sous prétexte que le Kasaï était considéré comme une zone d’opération\nmilitaire où les humanitaires ne pouvaient aller875."},{"id":"a-hrc-38-crp-1-p0399","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"399","seq":399,"section":"A. Conséquences humanitaires","text":"D’après le Bureau de la coordination des affaires humanitaires des Nations Unies,\n3,8 millions de personnes dont 2,3 millions d’enfants, ont besoin d’une aide humanitaire\ndans la région du Kasaï. Outre le cri d’alarme lancé par les organisations humanitaires,\nl’EEI a pu se rendre compte par elle-même des besoins d’assistance humanitaire des\npopulations affectées par les violences. Depuis 2016, les violences au Kasaï ont provoqué\nune crise humanitaire aigüe et sans précédent, occasionnant le déplacement de près de\n1,4 millions de personnes, dont 700 000 enfants ; 35 000 personnes se sont réfugiées en\nAngola876. 762 000 demeurent encore déplacées internes877. Les premières évaluations\nfaites par les acteurs humanitaires à partir de mai 2017 ont relevé une situation\ndésastreuse878. Suite aux violences, la population a perdu l’accès à ses moyens d’existence\net aux denrées alimentaires de base, aux soins médicaux et à l’éducation. Certains villages\nne sont plus ravitaillés et les prix des denrées de base ont augmenté à tel point qu’une partie\nde la population ne peut plus se les procurer. Selon les chiffres du Programme alimentaire\nmondial (PAM) et de l’Organisation pour l’alimentation et l’agriculture, environ 3,2\nmillions de personnes dans la région souffrent encore d'insécurité alimentaire et ont du mal\nà se nourrir ; Il s’agit en majorité d’enfants et de femmes. 14% de ces personnes dont de\nnombreux enfants souffrent d’insécurité alimentaire sévère879. Cela est directement lié à la\ncrise880. Selon l’UNICEF, 416 écoles et 224 centres de santé ont été attaqués depuis le\ndébut de la crise au Kasaï881. Plus de la moitié des attaques contre les écoles et près de la\nmoitié de celles contre les centres de santé ont eu lieu au Kasaï Central, ainsi qu’à Kamonia\net Luebo dans la province du Kasaï."},{"id":"a-hrc-38-crp-1-p0400","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"400","seq":400,"section":"A. Conséquences humanitaires","text":"De nombreuses personnes déplacées par les violences interviewées par l’EEI ont\nsouvent passé plusieurs semaines voire plusieurs mois dans des conditions extrêmement\ndifficiles se cachant dans la brousse, avant de pouvoir atteindre des centres urbanisés. De\nnombreuses personnes, dont beaucoup d’enfants et des femmes enceintes, sont tombées\nmalades et sont mortes faute d’accès à des centres de santé, de la nourriture de base et de\nl’eau potable882. Des épidémies de rougeole et de choleras ont fait des victimes.\nLorsqu’elles ne peuvent être hébergées par la famille ou des connaissances, les personnes\ndéplacées, souvent des femmes et des enfants, totalement démunies, passent leurs nuits\ndehors ou dans des églises, avec un minimum d’assistance et de secours."},{"id":"a-hrc-38-crp-1-p0401","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"401","seq":401,"section":"A. Conséquences humanitaires","text":"En raison des destructions des villages et des tensions ethniques dans le sud de la\nprovince du Kasaï, certaines personnes retournées d’Angola où elles étaient réfugiées n’ont\npas pu rentrer dans leurs villages d’origine883. La présence des barrières sur les routes,\nmises en place par des acteurs armés, a des conséquences négatives sur l’accès aux champs\net les déplacements aux marchés, les habitants et surtout les femmes ayant peur pour leur\nsécurité. La perception des taxes illégales aux barrières diminue l’activité économique et\nfait augmenter les prix des produits de première nécessité884."},{"id":"a-hrc-38-crp-1-p0402","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"402","seq":402,"section":"B. Conséquences sur les enfants","text":"Les violences qui ont touché le Kasaï depuis avril 2016 ont affecté les enfants de\nmanière disproportionnée. En effet, ceux-ci ont été à la fois les principales victimes des\nviolences mais aussi le principal instrument de celles-ci. Malgré les difficultés d’accès, les\nacteurs de la protection de l’enfant avaient déjà identifié, au 30 août 2017, 1 220 garçons et\n658 filles recrutés et utilisés par la milice Kamuina Nsapu885. Au vu des témoignages\ncollectés par l’EEI, il y a de sérieuses raisons de penser que la milice Kamuina Nsapu a\nrecruté et utilisé un nombre beaucoup plus élevé d’enfants. De nouveaux cas de\nrecrutements et d’utilisation d’enfants ont continué à être rapportés depuis cette date y\ncompris pour l’année 2018."},{"id":"a-hrc-38-crp-1-p0403","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"403","seq":403,"section":"B. Conséquences sur les enfants","text":"Des enfants ont été enlevés, blessés, mutilés, retenus, parfois de nombreux mois, ou\nexécutés par la milice Kamuina Nsapu. Certains ont vu leurs parents être décapités par les\nmiliciens Kamuina Nsapu, ou leur mère violée par les membres des forces de défense et de\nsécurité. La plupart d’entre eux ont été forcés à prendre part aux affrontements en première\nligne avec des armes blanches, des bâtons, des fusils traditionnels ou sans arme. Ils ont été\ncontraints de tuer. Ce sont au moins 401 mineurs qui ont été détenus en relation avec leur\nassociation à la milice Kamuina Nsapu886. Les traumatismes physiques et psychologiques\nengendrés par cette situation demanderont une prise en charge pendant longtemps."},{"id":"a-hrc-38-crp-1-p0404","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"404","seq":404,"section":"B. Conséquences sur les enfants","text":"Cette large utilisation d’enfants appartenant au même groupe ethnique dans le but de\ncommettre des actes d’une extrême violence a eu de nombreuses conséquences sur\nl’ensemble de la communauté. En effet, l’EEI a pu observer une véritable perte de\nconfiance entre enfants et adultes. Les enfants, à qui la milice Kamuina Nsapu disait qu’ils\nétaient invincibles grâce aux fétiches, ont vu mourir leurs camarades ; à certains et\ncertaines qui iraient combattre les militaires, les Kamuina Nsapu ont promis l’école\ngratuite."},{"id":"a-hrc-38-crp-1-p0405","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"405","seq":405,"section":"B. Conséquences sur les enfants","text":"Le recrutement et l’utilisation massive de garçons et de filles à des fonctions\nspécifiques par genre a aussi ancré l’idée que les petites filles recrutées dans la milice\nKamuina Nsapu, les « ya mama », avaient un pouvoir létal supérieur aux autres membres\nde la milice. Enfin, l’utilisation d’enfants en provenance d’un seul groupe ethnique dans le\nbut de commettre des actes de violence ciblant des agents de l’état a créé un climat de\nsuspicion et de méfiance à l’égard de ces enfants de cette ethnie. On peut également penser\nque cela pourrait être l’une des raisons pour lesquelles tant d’enfants lubas ont été victimes\nd’exécutions sommaires et extrajudiciaires parfois même dans leur sommeil. Plusieurs\ncentaines d’autres seront arrêtés et détenus durant de nombreux mois."},{"id":"a-hrc-38-crp-1-p0406","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"406","seq":406,"section":"B. Conséquences sur les enfants","text":"Le Bureau de la coordination des affaires humanitaires des Nations Unies a pu établir\nqu’en avril 2017, 1 185 600 enfants des Kasaï dont plus de 600 000 filles avaient besoin\nd’aide d’urgence887. En mai 2018, plus de 770 000 des enfants de moins de 5 ans\nsouffraient de malnutrition ; parmi eux, 400 000 souffraient de malnutrition sévère\ndemandant une attention médicale urgente.888 Selon l’UNICEF, 416 écoles ont été attaqués\ndepuis le début de la crise au Kasaï889. Au 31 mai 2017, UNICEF estimait qu’au moins 1\nenfant sur 10 dans les provinces du Kasaï a eu la scolarité interrompue par les violences890,\nles écoles et autres lieux d’enseignements étant parmi les cibles des attaques de la milice\nKamuina Nsapu."},{"id":"a-hrc-38-crp-1-p0407","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"407","seq":407,"section":"B. Conséquences sur les enfants","text":"L’impact des déplacements de populations sur les enfants, le nombre important\nd’enfants séparés de leurs parents ou orphelins, la malnutrition sévère et la destruction\nmassive et ciblée des écoles et des centres de santé auront des conséquences profondes et\ndurables sur les capacités de développement des provinces affectées et du pays tout entier.\nLes centres urbanisés ont vu l’apparition de groupes d’enfants vivant dans les rues et\ncommettant des larcins et agressions pour survivre891. Certains enfants sortis de la milice\nKamuina Nsapu ont exprimé la possibilité d’y retourner car ils vivaient actuellement dans\ndes conditions très difficiles. Ainsi une jeune fille a indiqué penser retourner dans la milice\ncar les drogues qu’on lui donnait lorsqu’elle était « ya mama » servaient de coupe-faim\nalors qu’elle ne mangeait pas à sa faim depuis sa sortie de la milice892."},{"id":"a-hrc-38-crp-1-p0408","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"408","seq":408,"section":"C. Conséquences sur les femmes","text":"Sur les 454 personnes qui ont partagé leur expérience avec l’EEI, au moins 45% ont\nmentionné qu’elles avaient été victimes de violences sexuelles par une ou plusieurs\npersonnes, au cours d’une ou plusieurs occasions, ou qu’elles avaient été témoin\nconnaissaient des personnes ayant subi de telles violences. La majorité des violences\nsexuelles commises sont des viols. Ces chiffrent doivent être lus au regard du fait que par\npeur de stigmatisation, beaucoup de victimes de viols n’osent pas parler de ce qu’il leur est\narrivé. Cela démontre l’ampleur des violences sexuelles qui ont été commises au Kasaï\ndepuis 2016 par tous les acteurs du conflit. Ainsi, une femme raconte qu’en fuyant son\nvillage avec d’autres femmes, elles sont tombées sur un groupe d’hommes cagoulés ; elle a\nété violée par neuf d’entre eux et que vu son état, le dixième a renoncé893."},{"id":"a-hrc-38-crp-1-p0409","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"409","seq":409,"section":"C. Conséquences sur les femmes","text":"Une grande partie des victimes n’a pas pu avoir accès à des soins médicaux dans les\n72 heures après leur viol894. Cela est parfois dû à l’impossibilité d’accéder à un centre de\nsanté adapté surtout dans les endroits les plus isolés, certains ayant d’ailleurs été détruits\ndans les violences qui se sont produites depuis 2016, ou au coût d’un service que les\nvictimes ne peuvent s’offrir895. Ainsi beaucoup de survivants et de survivantes souffrent de\nséquelles physiques, dont des infections, fistules, déchirures vaginales ou annales ou\nd’autres problèmes gynécologiques récurrents, qui ont une incidence sur leur capacité à\nexercer les tâches domestiques ou une activité professionnelle nécessaire pour subvenir aux\nbesoins de leur famille ; ils souffrent également de séquelles psychologiques896. Ainsi en\nmars 2017, une femme qui était restée cachée trois semaines dans la brousse, a été violée\npar trois hommes alors qu’elle était partie chercher de la nourriture pour ses enfants.\nL’agression a été tellement violente qu’elle souffre d’un prolapsus utérin du troisième\ndegré qui nécessite une opération chirurgicale à laquelle elle n’a pas accès897. Puisque\nnombre de victimes n’ont pas eu accès à une attention médicale adaptée, elles ne savent pas\nsi elles ont été affectées par des maladies sexuellement transmissibles tels le VIH898."},{"id":"a-hrc-38-crp-1-p0410","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"410","seq":410,"section":"C. Conséquences sur les femmes","text":"Des femmes qui étaient enceintes ont été violées ; certaines ont fait une fausse-couche\nou ont accouché prématurément suite à ces viols899 ; d’autres sont décédées des suites de\nleur viol900. Des femmes enceintes ont été tuées, éventrées et leur fœtus sortis901. De\nnombreuses femmes ont fait état de la brutalité physique avec laquelle elles ont été\nviolées902. Certaines victimes ont été obligées de prodiguer des actes sexuels à un membre\nde leur famille en public. Ainsi une femme rapporte qu’un soir des militaires se sont\nprésentés à son domicile et ont ordonné à son fils de 18 ans d’avoir un rapport sexuel avec\nelle. Comme il a refusé, il a été tué et elle a été violée par trois des assaillants903. Un\nhomme va être forcé d’avoir une relation sexuelle avec sa belle-mère devant la foule à\nLuebo. Cette scène va être filmée et diffusée sur les réseaux sociaux. Ils seront tous les\ndeux tués et leurs cadavres mutilés904. Une femme raconte qu’elle a été violée par trois\nhommes et que l’un l’a forcé à lui faire une fellation905. D’autres sont tombées enceinte\nsuite à leur viol906. Un homme raconte comment il est devenu impuissant depuis que des\nmiliciens Kamuina Nsapu ont forcé son domicile, qu’ils l’ont battu, et torturé notamment\nen liant un fil dans son pénis907."},{"id":"a-hrc-38-crp-1-p0411","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"411","seq":411,"section":"C. Conséquences sur les femmes","text":"Les victimes de violences sexuelles au Kasaï font face à de nombreuses conséquences\nphysiques, psycho-sociales et financières qui les affectent directement mais qui affectent\naussi l’ensemble de la communauté, notamment à cause des nombreuses traditions et règles\ncoutumières au Kasaï. Un nombre important de femmes ont été violées devant leurs\nenfants, leur mari ou d’autres membres de leur famille ou communauté908. Un suivi psycho-\nsocial est également nécessaire pour ces personnes, victimes, elles aussi."},{"id":"a-hrc-38-crp-1-p0412","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"412","seq":412,"section":"C. Conséquences sur les femmes","text":"Certaines femmes et jeunes filles ont également été retenues contre leur gré de\nplusieurs jours à plusieurs mois dans un environnement où elles ont été violées de façon\nrépétée, souvent plusieurs fois par jour. Certaines d’entre elles sont tombées enceintes suite\nà ces viols. Si certaines ont réussi à s’échapper ou ont été libérées, à ce jour, d’autres sont\ntoujours retenues contre leur gré909."},{"id":"a-hrc-38-crp-1-p0413","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"413","seq":413,"section":"C. Conséquences sur les femmes","text":"De manière générale, les victimes de violences sexuelles, et plus précisément de viol\nque l’EEI a pu rencontrer ont rarement porté plainte auprès des autorités congolaises. Le\nplus souvent elles ont indiqué un manque de confiance dans le système judiciaire, les coûts\nassociés aux poursuites ou l’inutilité de la démarche910. Elles ne voient pas ce que porter\nplainte pourrait leur apporter directement alors qu’elles considèrent les possibilités\nd’autonomisation économique et financière comme des réponses plus appropriées aux\nproblèmes auxquels elles doivent faire face. Porter plainte augmente aussi le risque de\nstigmatisation et réduira pour une jeune fille ses chances de se marier ou augmentera pour\nune femme marié la possibilité de subir un divorce si la communauté ou leur mari viennent\nà apprendre ce qui leur est arrivé911. En effet, les mesures de protection des témoins sont\nencore peu utilisées par les juridictions au Kasaï malgré la loi912. Les difficultés et coûts liés\nà l’exécution des jugements fait que les victimes, lorsqu’elles ont la possibilité de porter\nplainte et de voir la procédure aller jusqu’au jugement, reçoivent rarement les dommages-\nintérêts prononcés à leur bénéfice même lorsque l’Etat a été condamné in solidum."},{"id":"a-hrc-38-crp-1-p0414","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"414","seq":414,"section":"C. Conséquences sur les femmes","text":"Une femme raconte qu’après avoir été violée, sa belle-famille a considéré qu’elle\navait enfreint la coutume913 et qu’il devait donc y avoir divorce ; elle et sa famille ont dû\nrembourser la dot et elle, retourner dans sa famille.914 Une femme, enceinte de 4 mois au\nmoment de son viol, a, elle aussi, été chassée par son mari et a dû rembourser la dot ; elle a\nfait une fausse-couche quelques jours plus tard915. Certains maris ont cependant renoncé au\ndivorce après une cérémonie coutumière de purification916 ; malheureusement, toutes les\nfemmes dans ce cas n'ont pas les moyens financiers de recourir à ce type de cérémonie\ntraditionnelle917. Dans un autre cas, le mari avait demandé aux deux familles de se mettre\nd’accord sur la réparation car il souhaitait demeurer avec sa femme et que selon lui elle\nn’avait pas commis d’adultère. Malheureusement peu après, il a été tué pendant le conflit et\nla belle-famille, blâmant son épouse, l’a chassée de la parcelle918. Dans un autre cas, des\nmilitaires ont violé une femme et ont dit à son mari qu’ils avaient fait cela pour qu’il la leur\ndonne ; elle est ensuite partie avec les militaires919. Certaines femmes se retrouvent alors\ndans une précarité et une pauvreté accrues qui peuvent les exposer à devoir accorder des\nfaveurs sexuelles pour survivre."},{"id":"a-hrc-38-crp-1-p0415","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"415","seq":415,"section":"C. Conséquences sur les femmes","text":"D’autres crimes à connotation sexuelle ont également été commis. Il en est des\nnombreuses mutilations observées. Ainsi un témoin raconte qu’en mai 2017, elle a vu à\nKamako un groupe de miliciens Kamuina Nsapu dont certains arboraient des sexes de\nfemmes (clitoris et vagins) portés comme des médailles920. Certains témoins ont raconté\navoir vu des personnes couper, et même cuisiner puis manger de la chair humaine, dont des\npénis coupés sur des hommes vivants et des cadavres notamment de FARDC, et boire du\nsang humain921. Des mutilations de sexes féminins et masculins ainsi que de poitrines de\nfemmes ont été rapportées922. Une femme raconte qu’elle et sa fille ont été déshabillées et\ncertains ont subi des attouchements sexuels923. Des femmes et des hommes sont déshabillés\net exhibés en public, ce qui représente un grand tabou dans la communauté luba924. En\ns’attaquant au sexe et à la poitrine des femmes, c’est le symbole de la femme qui est\nattaquée et indirectement la communauté. Par exemple, pour l’ethnie luba, de nombreuses\ncroyances et règles et tabous sont attachées à ces symboles de la féminité et de la nudité."},{"id":"a-hrc-38-crp-1-p0416","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"416","seq":416,"section":"C. Conséquences sur les femmes","text":"Depuis le début des violences au Kasaï, le nombre de divorces (divorces coutumiers\ncar le mariage reste principalement coutumier dans cette région) a augmenté ainsi que les\nmariages précoces925. Le sentiment de honte et la peur d’être rejetées et stigmatisées par sa\nfamille et sa communauté pousse les survivantes de viols à ne pas parler publiquement de\nce qu’elles ont subi. Elles ne peuvent alors recevoir de soins médicaux appropriés."},{"id":"a-hrc-38-crp-1-p0417","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"417","seq":417,"section":"C. Conséquences sur les femmes","text":"En fuyant leurs villages à l’arrivé des miliciens ou des forces de sécurité, les femmes\net les filles se sont retrouvées en situation de vulnérabilité et nombre d’entre elles ont été\nviolées souvent par plusieurs individus926, parfois à différentes reprises, et souvent par des\n913\nCertaines normes coutumières ne font pas la différence entre l’adultère et le viol.\n914\nT0115.\n915\nT0273.\n916\nT0231, T0008.\n917\nT0008.\n918\nT0153.\n919\nT0015.\n920\nT0135.\n921\nT0135, T0197, T0297, T0205, T0386, T0233, T0335, T0056, T0166, T0167, T0339, T0367\nT0044, T0451.\nagresseurs leur demandant de « choisir » entre mourir et être violées927. Certaines ont été\nescortées par des hommes en arme mais lorsqu’elles étaient dans l’impossibilité de payer ce\n« service » elles ont été violées928. Des femmes et des enfants sont morts faute de soins et\nde nourriture alors qu’ils se cachaient dans la brousse929. Les personnes trop âgées ou\nmalades pour fuir leur village sont mortes, parfois brûlées dans l’incendie de leur maison930.\nDans certains villages, des FARDC ont emmené des femmes et des filles avec eux à leur\ndépart. L’endroit où se trouve certaines de ces femmes et ces filles est inconnu à ce jour931."},{"id":"a-hrc-38-crp-1-p0418","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"418","seq":418,"section":"C. Conséquences sur les femmes","text":"S’il existe notamment dans d’autres régions de la RDC un ensemble de structures\nmédicales, psycho-sociales et juridiques ainsi que des programmes d’assistance socio-\néconomique pour les survivants de violences sexuelles, il existe encore peu de structures et\nde programmes de ce type au Kasaï pour répondre aux besoins. Certaines femmes chassées\nde leur parcelle par leur mari ou leur belle-famille suite à leur viol932, dorment dans des\néglises et vivent d’expédients ce qui accroit leur vulnérabilité ; souffrant souvent de\nconséquences physiques de ce viol qui rendent leur santé précaire, elles éprouvent des\ndifficultés à exercer une activité professionnelle. Elles risquent alors, avec leurs enfants, de\ntomber dans un cercle vicieux de précarité et de pauvreté."},{"id":"a-hrc-38-crp-1-p0419","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"419","seq":419,"section":"D. Réponse judiciaire","text":"Afin de mieux comprendre la dynamique des violations et crimes commis au Kasaï\ndepuis 2016, l’EEI a suivi la réponse judiciaire face aux exactions commises. Elle a\nconstaté que si des procédures liées aux évènements qui se sont déroulés au Kasaï depuis\n2016 ont été ouvertes et quelques jugements rendus, un sérieux problème d’impunité\nsubsiste au regard de l’ampleur et de la gravité des crimes, violations et atteintes aux droits\nde l’homme documentées dans ce rapport. En effet, au regard du nombre d’incidents\nidentifiés, peu de procédures judiciaires ont été initiées. Parmi les affaires déjà jugées ou en\ncours, une minorité met en cause les membres des forces de défense et de sécurité. Les\nprocédures engagées contre les membres des forces de défense et de sécurité le sont le plus\nsouvent que contre les éléments les moins gradés. L’absence d’un membre de la justice\nmilitaire au grade au moins égal à celui du commandant du secteur opérationnel du Grand\nKasaï est un frein à la bonne administration de la justice. Un travail rigoureux et\nd’envergure reste à accomplir au plan judiciaire pour que tous les auteurs des crimes liés à\nla vague de violence soient traduits en justice et que les très nombreuses victimes soient\neffectivement rétablies dans leurs droits. Ainsi le Procureur de la CPI, où la situation en\nRDC est déjà sous enquête, a exprimé sa préoccupation quant aux actes de violence\ncommises dans les provinces du Kasaï et indiqué qu’elle continuait à suivre de près la\nsituation933."},{"id":"a-hrc-38-crp-1-p0420","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"420","seq":420,"section":"A. Conclusions","text":"L’Equipe d’experts internationaux est choquée par la situation désastreuse des\ndroits de l’homme qui perdure dans la région du Kasaï depuis 2016. Elle est\nparticulièrement préoccupée par l’ampleur des actes de violences que ses enquêtes ont\nrévélés. Le présent rapport ne reflète qu’une petite partie des actes et crimes commis.\nBien qu’elle ne soit pas en mesure de donner un nombre précis des victimes, l’Equipe\nestime que plusieurs milliers de personnes ont perdu la vie durant la crise. L’Equipe\nest également préoccupée du faible niveau d’attention suscité par cette tragédie."},{"id":"a-hrc-38-crp-1-p0421","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"421","seq":421,"section":"A. Conclusions","text":"L’Equipe confirme que les forces de défense et de sécurité, la milice Kamuina\nNsapu et les milices Bana Mura ont délibérément tué des civils, dont de nombreux\nenfants. Elles ont commis de nombreuses atrocités, notamment des mutilations, des\nviols et d’autres formes de violences sexuelles, et destruit des villages entiers.\nL’Equipe est d’avis que certaines des exactions commises par les forces de défense et\nde sécurité, les milices Bana Mura et la milice Kamuina Nsapu constituent des crimes\ncontre l’humanité ou des crimes de guerre, ainsi que des violations et des atteintes aux\ndroits de l’homme."},{"id":"a-hrc-38-crp-1-p0422","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"422","seq":422,"section":"A. Conclusions","text":"Les violences au Kasaï ont réveillé des tensions ethniques latentes et le conflit a\npris une dimension ethnique à partir du début de l’année 2017, en particulier sur le\nterritoire de Kamonia. L’Equipe est d’avis que les exactions commises par les milices\nBana Mura contre les membres de l’ethnie luba peuvent être qualifiées de persécution\npour des motifs d’ordre politique et ethnique constitutives de crimes contre\nl’humanité."},{"id":"a-hrc-38-crp-1-p0423","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"423","seq":423,"section":"A. Conclusions","text":"L’Equipe considère qu’il est urgent de mettre en place une politique de\ndésarmement des milices et un processus de réconciliation afin d’éviter une nouvelle\nvague de violence et permettre le retour des déplacés et des réfugiés."},{"id":"a-hrc-38-crp-1-p0424","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"424","seq":424,"section":"A. Conclusions","text":"Un très sérieux problème d’impunité subsiste au regard de l’ampleur et de la\ngravité des crimes. Si quelques procédures judiciaires ont été ouvertes et quelques\njugements rendus, les efforts déployés sont nettement insuffisants pour apporter une\nréponse satisfaisante aux victimes, étant donné la nature des crimes. Un travail\nrigoureux et d’envergure reste à accomplir au plan judiciaire pour que les auteurs des\ncrimes liés à la vague de violence soient jugés et que les très nombreuses victimes\nsoient effectivement rétablies dans leurs droits. S’il incombe en premier lieu aux\nautorités de la République démocratique du Congo de juger les auteurs de crimes\ninternationaux, l’Equipe rappelle que la Procureure de la Cour pénale internationale,\ninstance qui enquête déjà sur la situation en République démocratique du Congo, a\nexprimé sa préoccupation quant aux actes de violence commis au Kasaï et indiqué\nqu’elle continuait à suivre de près la situation."},{"id":"a-hrc-38-crp-1-p0425","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"425","seq":425,"section":"B. Recommandations","text":"L’Equipe d’experts internationaux considère qu’il est urgent d’engager dès à\nprésent la lutte contre l’impunité en sanctionnant les crimes les plus graves commis\npar tous les acteurs impliqués dans la crise. Toutefois, pour garantir la non-répétition\ndes violences, rendre justice aux victimes et favoriser la réconciliation, la seule\nsanction des crimes les plus graves ne sera pas suffisante."},{"id":"a-hrc-38-crp-1-p0426","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"426","seq":426,"section":"B. Recommandations","text":"L’Equipe recommande aux autorités de la République démocratique du Congo\nles mesures suivantes :\na) S’engager dans un processus inclusif de justice transitionnelle visant établir\nla vérité, à identifier les causes profondes de la crise et à apporter réparation aux\nvictimes afin d’assurer la réconciliation ;\nb) Respecter leurs engagements internationaux et appliquer les lois en vigeur ;\nc) Renforcer la capacité des auditorats militaires du Kasaï afin qu’ils puissent\nenquêter et poursuivre et juger les auteurs, y compris les plus hauts responsables, des\nnombreux crimes internationaux commis au Kasaï depuis 2016 en :\ni) Augmentant les ressources humaines et logistiques des auditorats\nmilitiares ;\nii) S’assurant que les officiers à la tête des auditorats soient au moins au même\nniveau que les officiers en charge des opérations dont la responsabilité pourrait être\nengagée,\niii) Appliquant une stratégie des poursuites afin de s’assurer que les auteurs de\ntoutes les parties impliquées dans les violences soient jugés ;\nd) S’assurer de la mise en place de personnels spécialisés chargés d’enquêter\net de poursuivre spécifiquement les crimes de violence sexuelle ;\ne) Appliquer effectivement les mesures de protection judiciaire envers les\nvictimes de crimes de violences sexuelle et encourager celles-ci à porter plainte et à\ns’exprimer devant la justice par la mise en place d’une assistance judiciaire ;\nf) S’assurer que les personnes reconnues coupables de crimes de violence\nsexuelles soient condamnées à des peines appropriées et qu’elles ne soient pas\nintégrées ou maintenues dans les forces de défense et de sécurité ;\ng) Dans les cas où des mineurs seraient jugés, s’assurer que les enquêteurs\naient une formation spécialisée et que les enfants accusés soient jugés devant des\nchambres spécialisées pour mineurs avec des procédures adaptées ;\nh) Appliquer effectivement les mesures de protection judiciaire envers les\nenfants victimes afin de faciliter leur participation et de protéger leur identité ;\ni) Prendre les mesures concrètes et effectives pour que les victimes de\nviolences sexuelle et les enfants victimes bénéficient de services médicaux,\npsychosociaux et socioéconomiques adaptés en incorporant une démarche\nséxopécifique ;\nj) Œuvrer à la libération immédiate des femmes et enfants toujours captifs\ndes miliciens Bana Mura sur le territoire de Kamonia ;"},{"id":"a-hrc-38-crp-1-p0427","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"427","seq":427,"section":"B. Recommandations","text":"L’Equipe recommande à la MONUSCO d’apporter un soutien concret aux\nautorités judiciaires compétentes dans le cadre des poursuites judiciaires contre les\nauteurs des crimes internationaux au Kasaï, notamment en soutenant la tenue des\naudiences foreines."},{"id":"a-hrc-38-crp-1-p0428","rec_id":"recTkSTOeTuqoSc8t","symbol":"A/HRC/38/CRP.1","n":"428","seq":428,"section":"B. Recommandations","text":"L’Equipe recommande au Secrétaire général de l’Organisation des Nations\nUnies de suivre de près l’avancement des enquêtes de la République démocratique du\nCongo sur la mort des deux experts d’Organisation et leurs accompagnateurs et, si\nnécessaire, de renforcer le mandat et les ressources de l’Equipe des Nations Unies\nchargée d’appuyer l’enquête nationale afin que les personnes responsables soient\ntraduites en justice."},{"id":"a-hrc-38-31-p0001","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"1","seq":0,"section":"I. Introduction","text":"In response to the wave of violence sweeping Kasa� since 2016, the Human Rights\nCouncil on 23 June 2017 decided unanimously, by its resolution 35/33, to establish a team\nof international experts on the situation in Kasa�, for a period of one year."},{"id":"a-hrc-38-31-p0002","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"2","seq":1,"section":"I. Introduction","text":"On 26 July 2017, the United Nations High Commissioner for Human Rights\nappointed Bacre Waly Ndiaye of Senegal (Chairman), Fatimata M'Baye of Mauritania and\nLuc C�t� of Canada as international experts. They were assisted by a secretariat set up by\nthe Office of the United Nations High Commissioner for Human Rights (OHCHR) and\nbased in Kananga, Kasa� Central Province."},{"id":"a-hrc-38-31-p0003","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"3","seq":2,"section":"I. Introduction","text":"In March 2018, the team of international experts presented an oral report to the\nHuman Rights Council."},{"id":"a-hrc-38-31-p0004","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"4","seq":3,"section":"I. Introduction","text":"The team would like to thank the Democratic Republic of the Congo for its\ncooperation and for facilitating access to the country. It expresses its thanks to the United\nNations Organization Stabilization Mission in the Democratic Republic of the Congo\n(MONUSCO) for its support, as well as to United Nations bodies, including OHCHR and\nthe United Nations Entity for Gender Equality and the Empowerment of Women (UN-\nWomen), and the governmental and non-governmental organizations that provided it with\ntheir cooperation. Lastly, and above all, it thanks the victims and witnesses who agreed to\ntell their stories."},{"id":"a-hrc-38-31-p0005","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"5","seq":4,"section":"II. Terms of reference","text":"In accordance with paragraph 10 of resolution 35/33, the team of international\nexperts was assigned the tasks of collecting and preserving information, determining the\nfacts and circumstances of presumed violations of human rights and international\nhumanitarian law in Kasa� and communicating the conclusions of this investigation to the\njudicial authorities of the Democratic Republic of the Congo in order to establish the truth\nand ensure that the perpetrators of deplorable crimes are all held accountable to before the\ncountry's judicial authorities."},{"id":"a-hrc-38-31-p0006","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"6","seq":5,"section":"II. Terms of reference","text":"The team believes that its terms of reference were to establish the facts and\ncircumstances of violations of human rights and international humanitarian law committed\nto date and since 2016 in the provinces of Kasa�, Kasa� Central, Kasa� Oriental, Lomami\nand Sankuru1 likely to constitute crimes under international criminal law. In the light of the\nbroad terms of reference given to the team and the time frame it was assigned, the team\ngave priority to investigating the most serious acts of violence, such as attacks on the right\nto life and physical integrity, and specifically sexual violence, gender-based violence and\nviolence committed against children."},{"id":"a-hrc-38-31-p0007","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"7","seq":6,"section":"II. Terms of reference","text":"The team also considers that its mandate is to examine the roles of all the parties\ninvolved in the wave of violence that has affected Kasa� since 2016, including the defence\nand security forces, the Kamuina Nsapu militia and the Bana Mura militias."},{"id":"a-hrc-38-31-p0008","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"8","seq":7,"section":"III. Methodology and standard of proof","text":"The international team of experts collected information from many sources on the\nwave of violence. It established a selection methodology concentrating on the most serious\nand symptomatic incidents, and it conducted interviews with 524 victims, witnesses,\npresumed perpetrators and other sources. Documents, photographs and videos were\ncollected in support of the testimonies."},{"id":"a-hrc-38-31-p0009","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"9","seq":8,"section":"III. Methodology and standard of proof","text":"The team encountered various obstacles to the effective conduct of its investigation.\nThe vast size of the territory in question, coupled with the fact that access to witnesses was\ndifficult owing to road conditions and security issues, presented daily challenges. Delays in\ndeploying the team in the field also posed challenges."},{"id":"a-hrc-38-31-p0010","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"10","seq":9,"section":"III. Methodology and standard of proof","text":"The team adopted the same standard of proof as the majority of international\ncommissions of inquiry and other fact-finding missions, namely, that there should be\n\"reasonable grounds to believe\", meaning that corroborating information must be received\nfrom at least two sources."},{"id":"a-hrc-38-31-p0011","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"11","seq":10,"section":"III. Methodology and standard of proof","text":"The team incorporated a gender perspective in all its work and paid special attention\nto allegations of sexual and gender-based violence. In addition, it also established an\ninvestigation methodology adapted to the specific needs of minors."},{"id":"a-hrc-38-31-p0012","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"12","seq":11,"section":"III. Methodology and standard of proof","text":"Notwithstanding the fact that procedures were set up in line with best practices for\nwitness protection and confidentiality, a number of witnesses expressed concern about the\nsharing of their testimonies when they related to acts of violence committed by the defence\nand security forces or by their own communities."},{"id":"a-hrc-38-31-p0013","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"13","seq":12,"section":"IV. Applicable law","text":"The Democratic Republic of the Congo is inter alia a party to the International\nConvention on the Elimination of all Forms of Racial Discrimination; the International\nCovenant on Civil and Political Rights and its first Optional Protocol; the International\nCovenant on Economic, Social and Cultural Rights; the Convention on the Elimination of\nAll Forms of Discrimination against Women; the Convention against Torture and Other\nCruel, Inhuman or Degrading Treatment or Punishment and its Optional Protocol; and the\nConvention on the Rights of the Child and its first two Optional Protocols. It is also a party\nto the African Charter on Human and Peoples' Rights and its protocol concerning the rights\nof women in Africa and the Pact on Security, Stability and Development in the Great Lakes\nRegion and its various protocols."},{"id":"a-hrc-38-31-p0014","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"14","seq":13,"section":"IV. Applicable law","text":"The Democratic Republic of the Congo is a party to the four Geneva Conventions of\n1949 and their Additional Protocols of 1977, as well as to the Rome Statute of the\nInternational Criminal Court, whose definitions of international crimes were recently\nincorporated into the country's Criminal Code."},{"id":"a-hrc-38-31-p0015","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"15","seq":14,"section":"IV. Applicable law","text":"The international team of experts has also considered Congolese national law, in\nparticular the safeguards for human rights included in the Constitution."},{"id":"a-hrc-38-31-p0016","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"16","seq":15,"section":"V. Background","text":"Since July 2015, the Kasa� region has consisted of five provinces: Kasa�, Kasa�\nCentral, Kasa� Oriental, Lomami and Sankuru.2 Kasa� is one of the least developed regions\nof the country. Despite an abundance of natural resources, the economy has been in ruins\nfor several decades. Extreme poverty and chronic underdevelopment have persisted because\nof the very low level of State investment in the region's basic services."},{"id":"a-hrc-38-31-p0017","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"17","seq":16,"section":"V. Background","text":"The Kasa� region, whose population is mostly Luba, has traditionally been a\nstronghold of the main opposition party, the Union pour la d�mocratie et le progr�s social,\nwhich explains in part why the region is marginalized at the national level. A wave of\nviolence erupted in Kasa� in 2016 in a national context of tension related to the presidential\nelection. In December 2016, the presidential majority and the political opposition signed an\nagreement calling for a presidential election by the end of 2017 and prohibiting President\nKabila from running for a third term. Yet in 2017 it became clear that the election would\nnot take place by the end of the year as stipulated in the agreement. Demonstrations calling\nfor the agreement to be respected were forbidden or suppressed in several cities. The Kasa�\nregion was not particularly affected by the demonstrations. While it may be difficult to\nconclude that national politics had nothing to do with the authorities' reaction in handling\nthe Kasa� crisis, there is little proof of a direct link between the wave of violence in Kasa�\nand the electoral process."},{"id":"a-hrc-38-31-p0018","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"18","seq":17,"section":"V. Background","text":"In the run-up to independence, violence had broken out within the Luba population.\nThe Luba people share a common language, Tshiluba, and at this juncture they are\nrelatively united. On the other hand, with the division of the former Province of Kasa�\nOccidental into two new provinces in 2015, tensions grew between Luba groups and\nChokwe and Pende people, who live in the southern and eastern parts of Kasa� Province.\nWhile Kasa� Central remains dominated by the Luba population, the Luba have lost\ninfluence in Kasa� Province to the Chokwe and the Pende. It is also impossible to consider\nthe crisis in the Kasa�s in isolation from pre-existing local conflicts involving customary\nchiefs and the sharing of land and mining resources."},{"id":"a-hrc-38-31-p0019","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"19","seq":18,"section":"V. Background","text":"Customary authority, which is closely linked to ethnic identity, is an important part\nof the local power system. Customary chiefs, in addition to performing important spiritual\nfunctions, play a major role in public administration, village management and access to\nland and local justice. They are named according to traditional customs and are\nsubsequently recognized by the public authorities, who pay them a salary. While the role of\ncustomary chief is supposed to be apolitical, the State authorities regularly bring pressure to\nbear on the chiefs to encourage them to fall into line politically with the provincial and\nnational authorities, going so far as to refuse to recognize those who nonetheless have been\nnamed through the traditional practice."},{"id":"a-hrc-38-31-p0020","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"20","seq":19,"section":"V. Background","text":"Belief in witchcraft and supernatural powers remains widespread in society,\nincluding in the defence and security forces. Jujus are given a great deal of importance. A\nlarge number of customary rules govern the life of the community, and breaking them can\nlead to serious consequences."},{"id":"a-hrc-38-31-p0021","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"21","seq":20,"section":"A. Defence and security forces","text":"The Democratic Republic of the Congo has still not been able to establish a well-\norganized, professional army. The Armed Forces of the Democratic Republic of the Congo\n(FARDC) continue to commit frequent and serious human rights violations against civilians\nand to live off the civilian population."},{"id":"a-hrc-38-31-p0022","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"22","seq":21,"section":"A. Defence and security forces","text":"When the crisis began in Kasa�, soldiers of the 2101st regiment were stationed in\nKananga. They reported to the 21st military region, based in Mbuji-Mayi, Kasa� Oriental.\nThe regiment, which had been under the fifth integrated brigade, was composed of a mix of\nreintegrated former militia members and troops of the national army. The presence in the\nregiment of Kinyarwanda-speaking military personnel from the eastern part of the country\nwas hotly criticized by Chief Kamuina Nsapu, who accused them of being foreigners. Some\nmilitary commanders had reportedly been involved in serious human rights violations in\nother parts of the Democratic Republic of the Congo."},{"id":"a-hrc-38-31-p0023","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"23","seq":22,"section":"A. Defence and security forces","text":"FARDC initially reacted with brutality against the Kamuina Nsapu militia. Despite\nthe arrival of reinforcements at the end of 2016, which brought the number of military\npersonnel in Kasa� to 7,000, FARDC failed to stop the rapid expansion of the militia. On 9\nMarch 2017, the Government established the Greater Kasa� Operations Sector, with its\ncommand centre in Kananga, in order to confront the Kamuina Nsapu militia, which the\nGovernment qualified as terrorists. In the territory of Kamonia, in Kasa� Province, FARDC\nconducted operations with the support of the Bana Mura militia. Towards the end of 2017,\nthe authorities started to reduce the number of troops in Kasa�."},{"id":"a-hrc-38-31-p0024","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"24","seq":23,"section":"A. Defence and security forces","text":"The Congolese National Police clearly lacked equipment and training to respond to\nthe violence in Kasa�, despite the arrival of a unit of reinforcements specialized in\nmaintaining order."},{"id":"a-hrc-38-31-p0025","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"25","seq":24,"section":"B. Kamuina Nsapu militia","text":"The Kamuina Nsapu militia, which is mostly Luba, emerged owing to a customary\npower struggle. Following the death of the former Kamuina Nsapu chief, Ntuma Mupala,\nchief of the Bajila-Kasanga clan in Dibaya territory of Kasa� Central Province, Jean-Prince\nMpandi was named as successor. The Bajila-Kasanga chieftainship belongs to the\nBashilange federal kingdom, whose chiefs since the colonial period have ruled all the way\nto neighbouring Angola. The Kamuina Nsapu chief is the military leader of the Bashilange\nkingdom."},{"id":"a-hrc-38-31-p0026","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"26","seq":25,"section":"B. Kamuina Nsapu militia","text":"Mr. Mpandi's request to be recognized as the Kamuina Nsapu customary chief was\ndenied by the Minister of the Interior, �variste Boshab, for political reasons. The authorities\ntried to support Ntenda Tshiambi, the customary chief of the village of Ntenda and a rival\nof Mr. Mpandi, who was politically close to the then-Governor of Kasa� Central, Alex\nKande."},{"id":"a-hrc-38-31-p0027","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"27","seq":26,"section":"B. Kamuina Nsapu militia","text":"On 3 April 2016, Mr. Mpandi's home was searched, in his absence, for weapons.\nThis incident reportedly exacerbated his animosity against the authorities and his rival, Mr.\nTshiambi, whom he suspected of being behind the search."},{"id":"a-hrc-38-31-p0028","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"28","seq":27,"section":"B. Kamuina Nsapu militia","text":"Upon his return from South Africa Mr. Mpandi accused the authorities of\ndesecrating his jujus and of attempting to sexually abuse his wife. He thus announced that\nhe would set up a \"political and customary\" movement on the basis of the practices and\nlegitimacy of customary power and the system of traditional beliefs. His movement\nopposed the State authorities and \"foreigners\" who were responsible, in his view, for\nharassing the people and for the lack of economic opportunity."},{"id":"a-hrc-38-31-p0029","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"29","seq":28,"section":"B. Kamuina Nsapu militia","text":"In his village and Dibaya territory, Kamuina Nsapu, the customary chief, recruited\nmilitia members, the majority of whom were children, and in June 2016 began to set up\nbarriers to control movement by State officials. The first armed attack by the Kamuina\nNsapu militia was directed against the village of the rival chief, Mr. Tshiambi. Later, the\nmilitia attacked symbols of the State in Dibaya territory. As efforts by the political\nauthorities to find a negotiated solution with the Kamuina Nsapu customary chief were\nineffective, the authorities quickly opted for the use of force."},{"id":"a-hrc-38-31-p0030","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"30","seq":29,"section":"B. Kamuina Nsapu militia","text":"On 12 August 2016, the Kamuina Nsapu chief was killed in an attack on his village\nby the defence and security forces, and his body was transported to Kananga, provoking\nindignation among the Bashilange. The fact that the Kamuina Nsapu family was part of the\nkingdom of Bashilange led to the rapid expansion of the militia. Thanks to an organized\nrecruitment system and the placement of tshiotas (initiation halls containing sacred fires),\nthe militia spread. Emissaries of the late Kamuina Nsapu, sometimes called \"apostles\",\ntravelled from village to village in an ever expanding area to set up their tshiotas,\nbeheading village chiefs who opposed their movement. Tshiotas were thus set up in the five\nprovinces of Kasa�. Villagers were called upon to voluntarily join the movement. Those\nwho refused were often beheaded."},{"id":"a-hrc-38-31-p0031","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"31","seq":30,"section":"B. Kamuina Nsapu militia","text":"In the tshiotas, in the presence of an \"apostle\" or a high-level chief often called the\n\"president\", the recruits, including young children, had to subject themselves to a \"baptism\"\nritual, which involved drinking an alcoholic mixture and performing other rites. Once this\nwas done, the recruits were part of the militia, where ancestral beliefs and rituals played an\nextremely important role. In order to ensure that militia members would be invincible\nagainst firearms, these beliefs required the observance of strict rules. The tshiotas were also\nfavoured as places for beheadings, often performed by children, as well as for acts of\ncannibalism. Heads and other body parts of victims of attacks were brought there, along\nwith their blood."},{"id":"a-hrc-38-31-p0032","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"32","seq":31,"section":"B. Kamuina Nsapu militia","text":"Units were organized and attacks were planned as well in the tshiotas. Before\nclashes, the militia members took part in rituals involving the swallowing of alcoholic\nmixtures. Typically, when the fighting occurred, the Kamuina Nsapu militia was deployed\nwith one or more girls called \"ya mama\" in the front line. According to their beliefs, they\nhad the power to catch firearm projectiles with their skirts. Just behind them were boys\narmed with knives and sticks. According to the beliefs, they had the magical power to\ntransform into lethal weapons. Older militia members with better equipment such as\ntraditional firearms or hunting weapons, and sometimes with automatic weapons, followed\nin the last line."},{"id":"a-hrc-38-31-p0033","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"33","seq":32,"section":"B. Kamuina Nsapu militia","text":"The number of militia members in an operational group varied but was generally\nbetween 15 and 30, most of whom were children. At the head of each group was a\n\"general\" or \"capita\" During the operations, the Kamuina Nsapu militia almost always\nwore the same distinctive clothing: Red headbands, with small knives and jujus around the\nneck. The Kamuina Nsapu militia managed in a very short time to recruit militia members,\ncarry out attacks in the five provinces of Kasa� and take control of villages and towns for\nseveral weeks or even months at a time."},{"id":"a-hrc-38-31-p0034","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"34","seq":33,"section":"B. Kamuina Nsapu militia","text":"Since 2017, the militia has become increasingly violent and its attacks have taken on\nan ethnic character outside areas where the language of the Luba people is spoken."},{"id":"a-hrc-38-31-p0035","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"35","seq":34,"section":"C. Bana Mura militias","text":"The Bana Mura militias are made up mostly of Chokwe men, but also include some\nPende and Tetela men. They were set up in February and March 2017 in certain parts of the\nKamonia territory and the town of Tshikapa, in Kasa� Province, in response to the attacks\nby the Kamuina Nsapu militia, which is Luba, against Chokwe and Pende people."},{"id":"a-hrc-38-31-p0036","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"36","seq":35,"section":"C. Bana Mura militias","text":"The Bana Mura militiamen had connections with certain representatives of the State.\nIn the town of Kamonia, meetings were held between political and security authorities and\nlocal chiefs in order to set up militia groups. Some local leaders, in particular the chief of\nthe village of Muyeji, played an important role in the organization of the Bana Mura\nmilitias. While it is difficult to find a shared chain of command, there were links between\nthe various Bana Mura militias. For example, weapons distributions organized by the local\nauthorities took place in several parts of the territory of Kamonia."},{"id":"a-hrc-38-31-p0037","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"37","seq":36,"section":"C. Bana Mura militias","text":"The Bana Mura militiamen were for the most part locally recruited young men\nbetween the ages of 18 and 22. The militiamen often had new weapons (machetes and\nhunting rifles)."},{"id":"a-hrc-38-31-p0038","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"38","seq":37,"section":"C. Bana Mura militias","text":"The operations carried out by the Bana Mura militias were particularly violent and\nwere often conducted with the defence and security forces, and sometimes under their\ncommand. In other cases, the Bana Mura militias operated alone, with the defence and\nsecurity forces refraining from intervening to stop the violence and help the victims.\nRecently, the defence and security forces have sometimes engaged the Bana Mura militias."},{"id":"a-hrc-38-31-p0039","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"39","seq":38,"section":"A. April�August 2016: Beginning of the violence in Dibaya territory, Kasa�","text":"The search of the home of the customary chief, Kamuina Nsapu, on 3 April 2016\nand the subsequent establishment of his \"political and customary\" movement, followed by\nthe recruitment of militia members, marked the onset of the violence in Dibaya territory of\nKasa� Central. Between May and August 2016, several hundred militia members, for the\nmost part girls and boys, were thus recruited in his village and in Dibaya territory."},{"id":"a-hrc-38-31-p0040","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"40","seq":39,"section":"A. April�August 2016: Beginning of the violence in Dibaya territory, Kasa�","text":"Beginning in June, the Kamuina Nsapu militia set up barriers around the village of\nKamuina Nsapu to control the movement of the police, the military and other\nrepresentatives of the State. On 22 July, a first attack was launched against symbols of the\nState, leading to the destruction of the police station in the village of Mfuamba. The next\nday, the village of the Ntenda customary chief, who was in conflict with the Kamuina\nNsapu customary chief, was attacked. This was the first deadly attack by the militia, and it\nleft at least six dead, four persons with bullet wounds and over a hundred houses burned."},{"id":"a-hrc-38-31-p0041","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"41","seq":40,"section":"A. April�August 2016: Beginning of the violence in Dibaya territory, Kasa�","text":"The Kamuina Nsapu customary chief then led a series of attacks in Dibaya territory,\nin particular against the towns and villages of Mfuamba, Bukonde, Tshikula, Dibaya and\nTshimbulu. These assaults led to the destruction and looting of public buildings and similar\nstructures and to attacks against persons representing or considered to represent the public\nauthorities. Officers of the Congolese National Police were the main victims of these\nattacks. The deadliest raid was against the town of Tshimbulu. It was ordered by the\nKamuina Nsapu chief and left at least five police officers and five militiamen dead."},{"id":"a-hrc-38-31-p0042","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"42","seq":41,"section":"A. April�August 2016: Beginning of the violence in Dibaya territory, Kasa�","text":"Following the failure of mediation efforts by the authorities, a major military\noperation was launched to halt the advance of the militia. With the arrival of military\nreinforcements in Kananga, the operation was aimed at taking Dibaya territory by attacking\non several fronts that were opened on the main roads, the final destination being the village\nof the Kamuina Nsapu chief. Between 10 and 12 August, violent clashes took place\nbetween FARDC and the Kamuina Nsapu militia, in particular in Tshimbulu, Dibaya,\nTshikula, Sampi, Bitanda and Kabunji. The armed forces fired on the militia members,\nincluding many unarmed children, including with the use of rocket launchers. There were\nalso dead and wounded among the members of the armed forces."},{"id":"a-hrc-38-31-p0043","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"43","seq":42,"section":"A. April�August 2016: Beginning of the violence in Dibaya territory, Kasa�","text":"On 12 August, the defence and security forces led an operation to kill the Kamuina\nNsapu customary chief in his native village. Following clashes that left several dead, the\ncustomary chief was shot dead by FARDC, and his body was moved to Kananga."},{"id":"a-hrc-38-31-p0044","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"44","seq":43,"section":"A. April�August 2016: Beginning of the violence in Dibaya territory, Kasa�","text":"Fighting between the Kamuina Nsapu militia and the defence and security forces\ncontinued in Dibaya territory. In mid-August, for instance, in front of the Tshikula Catholic\nMission, FARDC fired indiscriminately at civilians and Kamuina Nsapu militia members,\nmany of whom were children, causing dozens of casualties. Some of the bodies were\nstacked onto trucks and transported to the Kananga Officer Training School for burial."},{"id":"a-hrc-38-31-p0045","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"45","seq":44,"section":"B. September�December 2016: Spread of the Kamuina Nsapu movement","text":"The death of the Kamuina Nsapu customary chief did not bring the violence in Kasa�\nto an end. On the contrary, beginning in September 2016, the Kamuina Nsapu militia\nquickly spread further afield. While remaining active in Dibaya territory, the militia\nexpanded into other territories of Kasa� Central and into Kasa� Oriental beginning in\nSeptember/October 2016. By the end of November, it reached Kamonia territory, in Kasa�\nProvince, along the Kananga-Tshikapa road.\n1. Kasa� Central Province"},{"id":"a-hrc-38-31-p0046","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"46","seq":45,"section":"B. September�December 2016: Spread of the Kamuina Nsapu movement","text":"On 22 and 23 September 2016, the Kamuina Nsapu militia attacked the airport in\nKananga. A female employee of Congo Airways, several soldiers and many militiamen\nwere killed in clashes with FARDC. The Kamuina Nsapu militiamen burned down\nbuildings in the vicinity of the airport. Subsequently, FARDC fired rocket-propelled\ngrenades into the neighbourhoods near the airport, resulting in the death of civilians, whose\nbodies were transported to the Officer Training School."},{"id":"a-hrc-38-31-p0047","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"47","seq":46,"section":"B. September�December 2016: Spread of the Kamuina Nsapu movement","text":"At the end of September, in operations to track down the militia, the armed forces\nwounded, raped and killed civilians in Kananga and in nearby villages such as Mwamba-\nMbuyi and Tshimpidinga."},{"id":"a-hrc-38-31-p0048","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"48","seq":47,"section":"B. September�December 2016: Spread of the Kamuina Nsapu movement","text":"In Dibaya territory, the violence continued between September and December. On 8\nDecember, for instance, the Kamuina Nsapu militia set fire to the headquarters of the\nCongolese National Police in the village of Bukonde and hacked a member of the National\nIntelligence Agency to death in a machete attack. Villagers were also beaten and wounded\nwith machete blows. FARDC arrived the next day and engaged the militia, killing many\nmilitia members, including children. The FARDC members who remained in Bukonde after\nthe clashes looted houses and killed at least one civilian.\n2. Kasa� Oriental Province"},{"id":"a-hrc-38-31-p0049","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"49","seq":48,"section":"B. September�December 2016: Spread of the Kamuina Nsapu movement","text":"In October 2016, the Kamuina Nsapu movement spread to Kasa� Oriental. Violent\nacts occurred in several villages in Kabeya-Kamwanga territory until April 2017. For\nexample, on 13 October 2016, after two members of the militia were executed by the\ndefence and security forces in Kena Nkuna, about 100 Kamuina Nsapu militia members,\nmost of whom were children, entered the town and burned down public buildings and\nsimilar structures. FARDC thereupon arrived and clashes took place throughout the day,\nleaving several dead among the militia members and the civilian population. On 15 October\nFARDC launched a \"door-to-door\" operation to search for militia members, and several\ncivilians were executed. In the following weeks, the armed forces raped and executed\ncivilians and systematically looted and destroyed homes."},{"id":"a-hrc-38-31-p0050","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"50","seq":49,"section":"B. September�December 2016: Spread of the Kamuina Nsapu movement","text":"Violent acts were committed in several villages in Miabi territory, in Kasa� Oriental.\nFor example, on 18 December 2016, members of FARDC clashed with Kamuina Nsapu\nmilitiamen in the village of Mwanza Lomba. They opened fire on militiamen carrying\nsticks and knives, killing and wounding several people, including women and children, and\nthen executing the wounded who had fallen. After that incident was covered by the media,\neight of the nine soldiers tried for these crimes were convicted in July 2017.\n3. Kasa� Province"},{"id":"a-hrc-38-31-p0051","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"51","seq":50,"section":"B. September�December 2016: Spread of the Kamuina Nsapu movement","text":"The wave of violence linked to the Kamuina Nsapu movement reached the\nKananga-Tshikapa road, in Kamonia territory, Kasa� province, between late November and\nearly December 2016. As a result of a customary power struggle, a chief who was not\nrecognized by the authorities visited Kasa� Central Province with the aim of returning with\nthe Kamuina Nsapu jujus. In line with the usual pattern, children were recruited into the\nmilitia, and some village chiefs who refused to pledge support were beheaded."},{"id":"a-hrc-38-31-p0052","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"52","seq":51,"section":"B. September�December 2016: Spread of the Kamuina Nsapu movement","text":"The first incident in Kamonia territory took place on 28 November, when two\npolicemen were killed by Kamuina Nsapu militiamen in the Mbawu communities. On 4 and\n5 December, many militia members, including girls and boys, entered the town of\nTshikapa. Clashes took place near the Kasa� bridge, in the Kele neighbourhood and around\nthe airfield near the town centre."},{"id":"a-hrc-38-31-p0053","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"53","seq":52,"section":"B. September�December 2016: Spread of the Kamuina Nsapu movement","text":"After this attack, FARDC conducted reprisals in villages of the Mbawu communities\nand along the Kananga-Tshikapa road; many civilians were shot to death by the armed\nforces, including in the villages of Mfuamba, Mbawu and Kabeya-Lumbu. On 6 December\nthe armed forces arrived in large numbers in the village of Tshitadi, where there were no\nmilitiamen present. They burned many houses down and opened fire on the population,\nkilling dozens of men, women and children."},{"id":"a-hrc-38-31-p0054","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"54","seq":53,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"From January to July 2017, the Kamuina Nsapu movement and its militia continued\nto advance with the aim of reaching all provinces of Kasa�. Military reinforcements were\nsent and a military operations sector was established in early March 2017. Both the level of\nviolence associated with the clashes and the number of abuses committed by the Kamuina\nNsapu militia and the defence and security forces against civilians increased exponentially,\npeaking between January and May. Moreover, from March onwards, the conflict took on a\npronounced ethnic dimension in Kamonia territory, in Kasa� Province, with the arrival of\nthe Kamuina Nsapu militia in non-Luba-speaking areas and the emergence of the Bana\nMura militias.\n1. Kasa� Central Province\n(a) Dibaya territory"},{"id":"a-hrc-38-31-p0055","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"55","seq":54,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"There has been an upsurge in violence in Dibaya territory, the home of the Kamuina\nNsapu movement. On 5 January 2017, following incursions by members of the Kamuina\nNsapu militia in Tshimbulu, which had resulted in the destruction of the police station and\nthe death of a policeman, FARDC soldiers arrived to confront them. More than 20 members\nof the militia, most of whom were children armed with sticks, were killed by firearms and\nrocket launchers; some militia members were killed while lying on the ground. Local\nresidents were also injured or killed by projectiles. At least three other clashes took place in\nTshimbulu, including on 10 February, when at least 100 people were killed. The FARDC\nsoldiers raped women and girls, looted property and burned down houses."},{"id":"a-hrc-38-31-p0056","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"56","seq":55,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"Similar incidents took place in a large number of villages in the territory, including\nBukonde, Dibaya, Kabeya-Madi, Bena Kalegna, Muan Mukaya, Kazadi, Kaulu, Lumbudi,\nLubondaye and Lubi. Rape, often gang rape, looting, destruction of property and homes and\nsummary executions committed by FARDC were documented there. For the first time, the\nKamuina Nsapu militia attacked the civilian population of this territory."},{"id":"a-hrc-38-31-p0057","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"57","seq":56,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"Two members of the Group of Experts on the Democratic Republic of the Congo\nestablished pursuant to Security Council resolution 1533 (2004), Zaida Catal�n, a dual\nSwedish and Chilean citizen, and Michael Sharp, a United States citizen, were killed near\nthe village of Bukonde on 12 March. Ms. Catal�n's body was decapitated. Their four\ncompanions from the Democratic Republic of the Congo are still missing. Judicial\nproceedings are ongoing.\n(b) Town of Kananga"},{"id":"a-hrc-38-31-p0058","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"58","seq":57,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"In the town of Kananga, several tshiotas were erected by the Kamuina Nsapu militia,\nof which at least three were located in the commune of Nganza. Many children, both boys\nand girls, were recruited in the first few months of 2017. Multiple clashes took place in the\ntown between the militia and the defence and security forces between January and April,\nresulting in the death of several hundred people."},{"id":"a-hrc-38-31-p0059","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"59","seq":58,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"On the night of 14 March, FARDC launched a planned attack on three tshiotas in the\ncommune of Nganza where hundreds of Kamuina Nsapu militia members, mostly children\naged 8 and over, were sleeping. The FARDC soldiers used firearms and rocket launchers,\ncausing many casualties among the militia members. They also killed injured children,\nsometimes with knives. The bodies were stacked onto trucks and taken away by the\nsoldiers."},{"id":"a-hrc-38-31-p0060","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"60","seq":59,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"Between 28 and 30 March, FARDC launched \"door-to-door\" operations in the\ncommune of Nganza, during which many civilians, men, women and children, were\nwounded or killed indiscriminately. Young children were slaughtered in their sleep. Some\nbodies were taken away by FARDC, while others were buried in several mass graves by\nsoldiers or local residents.\n(c) Kazumba territory"},{"id":"a-hrc-38-31-p0061","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"61","seq":60,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"A number of isolated incidents were documented in Kazumba territory: on 10 and 11\nMarch 2017, members of the Kamuina Nsapu militia attacked Notre-Dame du Kasa�\nCathedral, located on Malandji Hill, stripping and beating several of the clergy and cutting\noff the parish carpenter's right hand. On 30 April, the militia executed six members of a\ndelegation of national school inspectors, near Kafumba. On 7 May, FARDC executed at\nleast 79 people, including 19 children, and raped 4 women at the Tshikulu village market.\n(d) Luiza territory"},{"id":"a-hrc-38-31-p0062","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"62","seq":61,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"All parts of Luiza territory were the scene of acts of violence between late January\nand July 2017. The Kamuina Nsapu militia arrived in the territory in late January from\nDibaya territory. The militia was under the command of a Kamuina Nsapu chief and an\nassociate, both of whom were from Dibaya. The chief set up several tshiotas, including two\nlarge ones in the villages of Kitoko and Yangala, and travelled to the various villages in the\nterritory to convince the village chiefs to join the movement or to force them to do so.\nThose who refused were beheaded. In the villages where they were met with hostility, the\nmilitia members retaliated against the inhabitants by looting and burning down their homes.\nSeveral hundred girls and boys were recruited into the militia, including in the villages of\nKitoko, Moma, Kadongo, Masuika, Mubinza and Tulume. The children were promised free\nschooling for anyone who killed soldiers."},{"id":"a-hrc-38-31-p0063","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"63","seq":62,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"In addition to attacks against property and persons that were symbols of State\nauthority or perceived as such, the militia also committed abusive acts against civilians.\nThose inhabitants who did not respect the rules imposed by the militia were \"tried\" in the\ntshiotas before being beaten or beheaded. Rape, sometimes in front of the victims' children,\nwas committed in several villages, including Muzodi, Masuika and Kamayi. The Catholic\nChurch, which had been largely spared in the past, was a prime target for the militia in\nLuiza territory, and much of its property and buildings were destroyed. Many schools were\nalso destroyed by the militia, including in Kamushilu, Kadongo and Malambo."},{"id":"a-hrc-38-31-p0064","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"64","seq":63,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"Between 3 and 5 February, several violent clashes between the Kamuina Nsapu\nmilitia members, the majority of whom were children, and FARDC took place in the village\nof Nguema, resulting in the death of several dozen militia members. From that point until\nmid-July, numerous skirmishes took place, including in the villages of Musefu, Kadongo,\nMasuika, Mubinza, Lumpungu, Kalemba Mbuji, Tulume and Yangala. Hundreds of\nKamuina Nsapu militia members, including children, were killed in those clashes, and\nmany civilians lost their lives as a result of the indiscriminate use of force by FARDC. On 7\nApril, FARDC opened fire indiscriminately on the inhabitants of the village of Muzodi,\nkilling some 20 villagers. Rape, including gang rape, was committed by members of\nFARDC, including in the villages of Kadongo, Masuika and Yangala. FARDC set fire to\nevery village that they stopped in to drive out the militia, including Kadongo, Moma,\nMasuika, Yangala and Masala; FARDC destroyed several dozen villages and burned down\nseveral thousand homes.\n2. Lomami Province"},{"id":"a-hrc-38-31-p0065","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"65","seq":64,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"In this province, the Kamuina Nsapu militia systematically recruited new members\nby force. Those who refused to join the movement, including children, were beheaded.\nMembers of the militia raped women, thus breaking their own rules prohibiting such\nbehaviour.\n3. Kasa� Province"},{"id":"a-hrc-38-31-p0066","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"66","seq":65,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"While in Kasa� Central the Kamuina Nsapu militia had mainly attacked symbols of\nState power, in Kasa� Province, their target was the non-Luba-speaking population,\nparticularly in Luebo and Kamonia territories.\n(a) Luebo territory"},{"id":"a-hrc-38-31-p0067","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"67","seq":66,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"The Kamuina Nsapu movement emerged in Luebo territory in December 2016,\nprimarily in the village of Konyi. A Kamuina Nsapu chief recruited militia members,\nincluding children, and ordered the construction of several tshiotas in the territory."},{"id":"a-hrc-38-31-p0068","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"68","seq":67,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"The Kamuina Nsapu militia first attempted to take control of Luebo town in early\nMarch 2017, but it was caught by FARDC ambushes. At least 20 bodies of civilians,\nincluding those of women and children, were discovered after the clashes at the entrance to\nthe town."},{"id":"a-hrc-38-31-p0069","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"69","seq":68,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"On the morning of 31 March, after FARDC had left the town, several hundred\nKamuina Nsapu militia members entered without resistance and took control. The militia\nmembers were armed with sticks, knives, machetes, some shotguns and, in some cases,\nweapons of war. Most public buildings and those belonging to the Catholic Church, as well\nas several schools, were destroyed or burned down. At least four civilians were killed."},{"id":"a-hrc-38-31-p0070","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"70","seq":69,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"The Kamuina Nsapu militia set up a tshiota in the centre of Luebo. Several chiefs\nfrom communities in Luebo territory took turns in controlling the town, and rules were\nimposed on its inhabitants. On 9 April, members of the Kamuina Nsapu militia forced a\nfemale restaurateur and her husband's son to have sex in public before killing and\nbeheading them. The same day, an officer of the Congolese National Police and two others\nwere also beheaded. Rape was also committed by members of the militia in early April."},{"id":"a-hrc-38-31-p0071","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"71","seq":70,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"Around 16 April, FARDC retook the town after several violent clashes during which\nmany Kamuina Nsapu child militiamen and civilians lost their lives. FARDC then\ndestroyed and burned down villages in the vicinity of the town of Luebo where there were\nconcentrations of militia, killing civilians in the process. Several mass graves were\nidentified. The clashes in Luebo territory reportedly left at least 770 people dead, including\n350 women and 420 men, and 208 people injured.\n(b) Kamonia territory: Tshikapa-Kananga road"},{"id":"a-hrc-38-31-p0072","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"72","seq":71,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"Between January and June 2017, the Kamuina Nsapu militia remained particularly\nactive on the Tshikapa-Kananga road. Around 24 March, 37 officers of the national police\nand 2 members of FARDC were killed and, in some cases, beheaded by the militia in the\nvillage of Malenga. A large amount of weapons and ammunition was also seized by the\nmilitia."},{"id":"a-hrc-38-31-p0073","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"73","seq":72,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"FARDC used excessive means to stop the Kamuina Nsapu militia, resulting in the\ndeath of many civilians, particularly in and around Mbawu and in the villages of Kabeya-\nLumbu and Kamuesha.\n(c) Tshikapa town"},{"id":"a-hrc-38-31-p0074","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"74","seq":73,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"Between February and June 2017, acts of violence took place in the town of\nTshikapa, where inhabitants live in neighbourhoods divided along ethnic lines."},{"id":"a-hrc-38-31-p0075","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"75","seq":74,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"In March, the Kamuina Nsapu militia beheaded several officers of the Congolese\nNational Police, including a commander. The level of violence used by the militia against\ncivilians subsequently increased and beheadings, mutilation and rape, which often took the\nform of gang rape and was so violent that some women died as a result of their ordeal, were\ncommitted in the town of Tshikapa and in the surrounding villages."},{"id":"a-hrc-38-31-p0076","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"76","seq":75,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"Several clashes between FARDC and the Kamuina Nsapu militia took place in\nTshikapa in March and April in the vicinity of the general hospital and in the communes of\nKele and Kanzala. FARDC made no distinction between militia members and inhabitants as\nit wounded and killed Luba-speaking civilians. In addition, soldiers broke into inhabitants'\nhomes at night and committed serious abuses against them. They beheaded men, raped\nnumerous women and girls, abducted young girls and even disembowelled a pregnant\nwoman."},{"id":"a-hrc-38-31-p0077","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"77","seq":76,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"From April onwards, some of the Chokwe and Pende civilians in the town, for\nwhom the Luba ethnic group was identified with the Kamuina Nsapu militia, carried out\nnight-time reprisals against homes in predominantly Luba-speaking neighbourhoods,\ncommitting murder and burning down houses.\n(d) Southern part of Kamonia territory"},{"id":"a-hrc-38-31-p0078","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"78","seq":77,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"The Kamuina Nsapu militia entered the southern part of Kamonia territory, thus\nadvancing into predominantly Chokwe areas. It became very active there from March 2017,\nparticularly on the Mutena-Kamako road and along the border with Angola."},{"id":"a-hrc-38-31-p0079","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"79","seq":78,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"Between March and May, the Kamuina Nsapu militia was active in the town of\nKamako. On 6 March, it made its first incursion and attacked the headquarters of the\nCongolese National Police, killing two or three officers. In response, the Congolese\nNational Police arrested and unlawfully detained civilians, subjected them to inhuman\ntreatment and summarily executed at least three of them. On 13 April, a large number of\nKamuina Nsapu militia members took control of the town and recruited many children,\nboth girls and boys. They beheaded at least 40 people in the tshiota, including a police\ncolonel, State officials and persons accused of theft or witchcraft."},{"id":"a-hrc-38-31-p0080","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"80","seq":79,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"On 1 May, FARDC entered Kamako and regained control after violent clashes that\nleft at least 50 people dead, including many unarmed children. FARDC took some bodies\naway in two trucks, while others were buried by residents and the Red Cross of the\nDemocratic Republic of the Congo."},{"id":"a-hrc-38-31-p0081","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"81","seq":80,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"All along the Mutena-Kamako road and the border with Angola, similar abuses were\ncommitted by the Kamuina Nsapu militia and FARDC, including in the villages of Diboko,\nLubami-Monga, Tshiniota, Sumbula, Mutshima, Lupemba, Mudjadja, Lumpedi, Kungu,\nKilolo, Bakua Mukuna and Bwalu Kai. In addition, the Kamuina Nsapu militia's rape of\nwomen, including gang rape, and of a man, was documented in these villages or when the\ninhabitants of this part of Kamonia territory fled. In May, for example, men and boys from\nthe village of Mudjadja were abducted from their homes by members of the Kamuina\nNsapu militia and taken to the tshiota in Diboko, supposedly to be baptized. It became the\nscene of the beheading of at least 186 men and boys. Their bodies were buried in two mass\ngraves by the Red Cross of the Democratic Republic of the Congo."},{"id":"a-hrc-38-31-p0082","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"82","seq":81,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"Incursions by members of the Kamuina Nsapu militia in the town of Kamonia began\naround 10 April, when at least 35 militia members, mostly children, were killed by the\ndefence and security forces and members of the Bana Mura militia. During these\nincursions, the Kamuina Nsapu militia killed residents, raped women, looted homes and\nbeheaded people associated with State authority. The Bana Mura militia members, for their\npart, followed orders from at least two civilian chiefs and a Congolese National Police\ncolonel and acted in concert with members of the defence and security forces. At the same\ntime, members of the Bana Mura militias committed abuses against the Luba-speaking and\nBindi population, whom they suspected of supporting the Kamuina Nsapu militia. Several\ndozen people were killed during these crackdowns and their bodies were buried in about a\ndozen mass graves. Some houses were looted and others were burned down, sometimes\nwith their inhabitants still inside. In the neighbouring village of Tshimunde, dozens of\npeople were killed by Bana Mura militiamen. In April and May, FARDC also carried out\nsummary executions, abducted girls and committed rape."},{"id":"a-hrc-38-31-p0083","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"83","seq":82,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"In the wake of the targeted attacks and killings perpetrated by the Bana Mura\nmilitiamen, the Luba-speaking population of the town of Kamonia fled en masse to the\ntown of Tshikapa. On the road linking the two cities, Bana Mura militiamen raped,\nsummarily executed and mistreated those fleeing. FARDC also extorted and beat civilians\nand raped women and girls fleeing the violence. A woman who was seven months pregnant\nwas raped by a member of FARDC and then by a member of the Bana Mura militia.\nBarriers were set up along the road, either by the Bana Mura militiamen or by the defence\nand security forces, or jointly, and many abuses were committed against Luba-speakers.\nWitnesses described passing through villages that had been deserted or burned to the\nground and seeing many corpses, including those of women and children."},{"id":"a-hrc-38-31-p0084","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"84","seq":83,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"In March, the Kamuina Nsapu militia arrived in the Lovua-Luthsima area and\nbeheaded many people, including in the villages of Senge (or Cinq) and Mvula-Milenge. In\nresponse, the Bana Mura militias intensified their activities. Between 24 and 26 April, large\nnumbers of Luba-speaking men, women and children were injured or killed in attacks\nplanned by the Bana Mura militiamen in the villages of Senge, Camp Kwilu, Kakondo and\nMvula-Milenge. The Bana Mura militias were composed of Chokwe people, armed with\nrifles and machetes, some of which had been provided by the chief of Muyeji village. The\nBana Mura militiamen were clearly targeting Luba-speaking residents."},{"id":"a-hrc-38-31-p0085","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"85","seq":84,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"A barrier had been set up by the Bana Mura militiamen along the banks of the\nTshikapa River at Kakondo, to prevent Luba-speakers from escaping. Those who spoke\nChokwe were allowed to pass. Many Luba-speaking residents, including children, were\nexecuted there, at the river crossing. Others were mistreated or killed as they fled. Women\nand girls were raped. In some cases, FARDC supported and guided the Bana Mura\nmilitiamen during the attacks. In others, they escorted displaced groups. FARDC, however,\ndid not intervene to prevent the numerous abuses committed by the Bana Mura militiamen\nagainst Luba-speakers."},{"id":"a-hrc-38-31-p0086","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"86","seq":85,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"At the Tshikapa River crossing, Bana Mura militiamen separated Luba-speaking\nmen and women not of childbearing age, beheaded them and threw their bodies into the\nriver. The other women and girls were taken to farms owned by individuals belonging to\nthe Chokwe ethnic group, including in Sha-Findji, Tshikala and Kisasa. The women and\ngirls sent to those farms were placed under constant surveillance and some had to work all\nday. They were repeatedly raped during their captivity, sometimes several times a day,\noften for months at a time. According to numerous victims, it was the perpetrators'\nintention for them to give birth to Chokwe children, as ethnicity is passed on through the\nmale line. Luba-speaking children of all ages were also brought to the farms, where they\nwere mistreated and malnourished. In some cases, the names of Luba-speaking children\nwere changed to Chokwe names. At the time of writing this report, women and children\nwere still being held on the farms.\n(e) Northern part of Kamonia territory"},{"id":"a-hrc-38-31-p0087","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"87","seq":86,"section":"C. January�July 2017: Eruption of violence throughout Kasa� and the","text":"In villages located in the north of Tshikapa, persons belonging to the Pende ethnic\ngroup calling themselves �curie Mbe attacked Luba-speakers and injured and killed\ncivilians, abducted children who were later reportedly enslaved and looted and burned\ndown homes."},{"id":"a-hrc-38-31-p0088","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"88","seq":87,"section":"VIII. Consequences of the Kasa� crisis and the current situation","text":"Since August 2017, the level of violence has decreased in all the provinces of Kasa�.\nHowever, crisis-related violence is still being reported, indicating that the causes of the\nconflict have not yet been addressed. FARDC has continued to use excessive force in\noperations against the Kamuina Nsapu militia. Persons wrongfully suspected of belonging\nto the militia continue to be detained, beaten or killed. Villages suspected of harbouring\nmilitia members have been looted or burned down. For example, on 30 November, in\nKamonia territory, Kasa� Province, a FARDC force raided the village of Kabeya-Lumbu,\nwhich they associated with the Kamuina Nsapu militia. The soldiers opened fire on the\npopulation near the market after food had been distributed by a humanitarian organization,\nkilling and wounding numerous people. In general, the strong military presence in Kasa�\nhas led to the harassment of the population; numerous cases of extortion have been\nreported, particularly at FARDC-controlled roadblocks."},{"id":"a-hrc-38-31-p0089","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"89","seq":88,"section":"VIII. Consequences of the Kasa� crisis and the current situation","text":"The Kamuina Nsapu militia has remained active, especially in Kasa� Central, and\ncontinues to recruit members, including children, and to carry out attacks, albeit on a lesser\nscale. For example, on the night of 30 April 2018, militia members attacked and killed the\nacting customary chief of Kamuina Nsapu village, who was close to provincial authorities,\nalong with three members of his family."},{"id":"a-hrc-38-31-p0090","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"90","seq":89,"section":"VIII. Consequences of the Kasa� crisis and the current situation","text":"In the southern part of the territory of Kamonia, strained relations between members\nof the Chokwe and Luba ethnic groups have also led to attacks on villages by the Bana\nMura militias and clashes between the Bana Mura militiamen and persons belonging to the\nLuba ethnic group over access to mining sites. Luba women, sometimes with their children,\ncontinue to be enslaved by Bana Mura militiamen. Despite advocacy efforts by some\ninternational organizations, the response of defence and security forces to these crimes\nremains insufficient. What is more, the presence of the Bana Mura militias prevents Luba\ninternally displaced persons from returning to their villages of origin."},{"id":"a-hrc-38-31-p0091","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"91","seq":90,"section":"VIII. Consequences of the Kasa� crisis and the current situation","text":"The violence in Kasa� has caused an acute and unprecedented humanitarian crisis,\nwith the displacement of an estimated 1.4 million people, including 35,000 refugees in\nAngola. According to figures from the World Food Programme and the Food and\nAgriculture Organization of the United Nations, some 3.2 million people continue to be\naffected by severe food insecurity, and malnutrition rates are high, especially among\nchildren."},{"id":"a-hrc-38-31-p0092","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"92","seq":91,"section":"VIII. Consequences of the Kasa� crisis and the current situation","text":"The team of international experts has been shocked by the humanitarian situation, in\nparticular the precariousness of the groups displaced by the violence. Many of the people\ninterviewed had spent weeks or even months living in extremely difficult conditions before\nreaching cities such as Tshikapa or Kikwit. They had fled the violence without any help or\nwith minimal assistance or relief. Some displaced people, including children, have died of\nmalnutrition or disease. The proliferation of barriers controlled by armed factions has\nimpeded access to fields, which, in turn, has affected the local economy. Lastly, the\ncollection of illegal taxes has raised the price of basic goods."},{"id":"a-hrc-38-31-p0093","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"93","seq":92,"section":"VIII. Consequences of the Kasa� crisis and the current situation","text":"Children have been particularly affected by the violence in Kasa�; they have been\nboth the main victims and the main perpetrators of the violence. According to figures from\nthe United Nations Children's Fund (UNICEF), as at 30 August 2017, 1,220 boys and 658\ngirls had been recruited and used by the Kamuina Nsapu militia. However, the team\nbelieves the numbers are in fact much higher and the recruitment is ongoing. Many children\nhave been abducted, wounded, mutilated, detained or executed. Some have seen their\nparents beheaded or beaten, or their mothers raped. Many of them have been forced to fight\non the front line without weapons or with dummy weapons, knives or, occasionally,\ntraditional rifles. They have been forced to kill and decapitate bodies. The physical and\npsychological trauma and stigmatization suffered by these children will require long-term\ncare. This massive use of children belonging to the same ethnic group has multiple\nconsequences for their community and creates a climate of suspicion towards them, which\ncan generate extreme reactions."},{"id":"a-hrc-38-31-p0094","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"94","seq":93,"section":"VIII. Consequences of the Kasa� crisis and the current situation","text":"UNICEF estimates that, since the beginning of the crisis in Kasa�, 416 schools and\n224 health centres have been looted or destroyed. Schools and other educational\nestablishments were prime targets of the Kamuina Nsapu militia."},{"id":"a-hrc-38-31-p0095","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"95","seq":94,"section":"VIII. Consequences of the Kasa� crisis and the current situation","text":"A significant number of victims of sexual violence, mainly rape, have described the\ndifficulties that they have faced. In addition to the medical and psychological problems they\nsuffer, survivors are also ostracized by their families and communities owing to the weight\ngiven to tradition and the resulting economic and social challenges. Many women have\nbeen raped in front of their husbands, children or other family members. It is therefore the\nentire social fabric of Kasa� that is suffering the consequences of this sexual violence. Most\nrape victims are reluctant to report their ordeal for fear of stigmatization and owing to a\ngeneral feeling of mistrust towards the justice system and a lack of effective reparation."},{"id":"a-hrc-38-31-p0096","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"96","seq":95,"section":"IX. Legal characterization","text":"The acts of violence committed against civilians are violations of human rights and\ninternational humanitarian law that constitute international crimes."},{"id":"a-hrc-38-31-p0097","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"97","seq":96,"section":"A. Crimes against humanity","text":"Article 7 (1) of the Rome Statute of the International Criminal Court defines crimes\nagainst humanity as acts committed as part of a widespread or systematic attack directed\nagainst any civilian population, with knowledge of the attack. \"Attack directed against any\ncivilian population\" means a course of conduct involving the multiple commission of acts\nreferred to in paragraph 1 against any civilian population, pursuant to or in furtherance of a\nState or organizational policy to commit such attack. The adjective \"widespread\" connotes\nthe large-scale nature of the attack and the existence of a certain number of victims,\nwhereas the adjective \"systematic\" refers to the organized nature of the acts of violence and\nimprobability of their random occurrence. The presence of combatants among the civilian\npopulation does not deprive this population of its civilian status."},{"id":"a-hrc-38-31-p0098","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"98","seq":97,"section":"A. Crimes against humanity","text":"The attacks perpetrated by the defence and security forces, the Kamuina Nsapu\nmilitia and the Bana Mura militias as described in the preceding sections were carried out\nagainst civilian populations in a widespread and systematic manner, pursuant to a State or\norganizational policy to commit such an attack. These attacks thus constitute crimes against\nhumanity, including murder, rape or any other form of sexual violence of comparable\ngravity, enslavement, including for sexual slavery, persecution and other inhuman acts."},{"id":"a-hrc-38-31-p0099","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"99","seq":98,"section":"B. War crimes","text":"Under article 8 (2) (c) and (e) of the Rome Statute, war crimes are defined, in the\ncase of an armed conflict not of an international character, as serious violations of article 3\ncommon to the four Geneva Conventions of 1949 against persons taking no active part in\nthe hostilities, and other serious violations of the laws and customs applicable in armed\nconflicts."},{"id":"a-hrc-38-31-p0100","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"100","seq":99,"section":"B. War crimes","text":"The team of international experts has reasonable grounds to believe that, as from\nAugust 2016 and during the period covered by this report, there was an armed conflict not\nof an international character in Kasa� between FARDC and the Kamuina Nsapu militia. In\norder to establish the existence of such a conflict, two criteria must be met: a minimum\nlevel of organization of the parties to the conflict and a certain intensity of violence."},{"id":"a-hrc-38-31-p0101","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"101","seq":100,"section":"B. War crimes","text":"The facts presented in this report lead to the conclusion that the Kamuina Nsapu\nmilitia is an armed group with a sufficient level of organization to conduct a protracted\narmed conflict, as demonstrated for example by the existence of chains of command, a\nconcrete strategy, the ability to recruit and train combatants, the existence and enforcement\nof disciplinary sanctions to ensure compliance with orders and the ability to plan and\nlaunch coordinated and large-scale military operations."},{"id":"a-hrc-38-31-p0102","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"102","seq":101,"section":"B. War crimes","text":"The facts also show that the intensity of the violence, including the number,\nduration, frequency and severity of the armed confrontations and their spread through four\nprovinces over a prolonged period, far exceeded that associated with mere situations of\ninternal unrest or tension. The number of victims and displaced persons fleeing the fighting,\nthe scale and extent of the destruction across four provinces, the type and numbers of the\ngovernment forces involved and the establishment of a military operations sector to deal\nwith the situation also support this conclusion."},{"id":"a-hrc-38-31-p0103","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"103","seq":102,"section":"B. War crimes","text":"Many of the acts described above were committed by FARDC and the Kamuina\nNsapu militia against persons taking no active part in the hostilities, or in violation of the\nlaws and customs applicable to armed conflict, in cases of armed conflict not of an\ninternational character. They thus constituted war crimes. These crimes include murder,\nmutilation, rape or any other form of sexual violence of comparable gravity, looting,\nintentionally directing attacks against the civilian population as such or against civilians\ntaking no active part in hostilities, intentionally directing attacks against religious buildings,\nschools and hospitals that are not military objectives, and conscripting or enlisting children\nunder the age of 15 into armed groups and forcing them to play an active part in hostilities."},{"id":"a-hrc-38-31-p0104","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"104","seq":103,"section":"C. Human rights violations","text":"The facts presented in this report lead to the conclusion that the following human\nrights in particular have been violated: the right to life, the right to physical and mental\nintegrity, the right to liberty and security of person and the right to freedom of movement.\nThe cases of enslavement and the recruitment and use of child soldiers that have been\nobserved also constitute human rights violations. These violations have had a direct impact\non the enjoyment of economic, social and cultural rights by the people of Kasa�."},{"id":"a-hrc-38-31-p0105","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"105","seq":104,"section":"A. Conclusions","text":"The team of international experts is appalled by the dire human rights situation\nprevailing in the Kasa� region since 2016. It is particularly concerned about the\nwidespread nature of the violence that its investigations have revealed. This report\nrelates only to a small number of the acts and crimes committed. Although the team is\nnot able to give an exact number of victims, it estimates that several thousand people\nhave lost their lives during the crisis. The team is also concerned about the low level of\nattention that this tragedy has been given."},{"id":"a-hrc-38-31-p0106","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"106","seq":105,"section":"A. Conclusions","text":"The team confirms that the defence and security forces, the Kamuina Nsapu\nmilitia and the Bana Mura militias have deliberately killed civilians, including many\nchildren. They have committed numerous atrocities, including mutilation, rape and\nother forms of sexual violence, and destroyed entire villages. The team believes some\nof the abuses committed by the defence and security forces, the Kamuina Nsapu\nmilitia and the Bana Mura militia constitute crimes against humanity and war crimes,\nas well as violations and abuses of human rights."},{"id":"a-hrc-38-31-p0107","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"107","seq":106,"section":"A. Conclusions","text":"The violence in Kasa� has awakened latent ethnic tensions and, since the\nbeginning of 2017, the conflict has taken on an ethnic dimension, particularly in\nKamonia territory. The team is of the view that the abuses committed by the Bana\nMura militia against members of the Luba ethnic group may be characterized as\npersecution on political and ethnic grounds constituting crimes against humanity."},{"id":"a-hrc-38-31-p0108","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"108","seq":107,"section":"A. Conclusions","text":"The team considers that there is an urgent need for a militia disarmament\npolicy and a reconciliation process so as to forestall a new wave of violence and to\nenable the return of internally displaced persons and refugees."},{"id":"a-hrc-38-31-p0109","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"109","seq":108,"section":"A. Conclusions","text":"Impunity remains a very serious problem, given the scale and gravity of the\ncrimes in question. While a few judicial proceedings have been initiated and some\ndecisions handed down, the efforts made to date are clearly insufficient to provide a\nsatisfactory response to the victims in view of the nature of the crimes. Rigorous and\nextensive work remains to be done by the judicial authorities to ensure that the\nperpetrators of the crimes linked to the wave of violence are brought to justice and\nthat the rights of the very numerous victims are effectively restored. While it is\nprimarily the responsibility of the authorities of the Democratic Republic of the\nCongo to try the perpetrators of international crimes, the team recalls that the\nProsecutor of the International Criminal Court, which is already investigating the\nsituation in the Democratic Republic of the Congo, has expressed concern about the\nacts of violence committed in Kasa� and has indicated that she will continue to\nmonitor the situation closely."},{"id":"a-hrc-38-31-p0110","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"110","seq":109,"section":"B. Recommendations","text":"The international team of experts recognizes the urgent need to begin\ncombating impunity forthwith by punishing the most serious crimes committed by all\nthose involved in the crisis. However, in order to prevent the violence from recurring,\nbring justice to the victims and foster reconciliation, punishment for the most serious\ncrimes will not, alone, be sufficient."},{"id":"a-hrc-38-31-p0111","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"111","seq":110,"section":"B. Recommendations","text":"The team recommends that the authorities of the Democratic Republic of the\nCongo take the following steps:\n(a) Engage in an inclusive process of transitional justice aimed at\nestablishing the truth, identifying the root causes of the crisis and providing redress to\nvictims, in order to ensure reconciliation;\n(b) Honour their international commitments and enforce existing laws;\n(c) Strengthen the capacity of Kasa� military prosecutors' offices to\ninvestigate, prosecute and try perpetrators, including the highest-ranking officials, for\nthe many international crimes committed in Kasa� since 2016, by:\n(i) Increasing the human and logistical resources of military prosecutors'\noffices;\n(ii) Ensuring that the officers in charge of the prosecutors' offices have at\nleast the same rank as the operational officers who may be held criminally\nliable;\n(iii) Applying a prosecution strategy so as to ensure that the perpetrators of\ncrimes from all the parties involved in the violence are brought to justice;\n(d) Ensure that specialized personnel are assigned the specific task of\ninvestigating and prosecuting crimes of sexual violence;\n(e) Enforce the application of judicial protection measures for victims of\ncrimes of sexual violence and, by providing legal assistance, encourage them to lodge\ncomplaints and to testify before the courts;\n(f) Ensure that persons convicted of crimes of sexual violence are given\nappropriate sentences and are prohibited from joining or remaining in the defence\nand security forces;\n(g) Ensure that, in cases where minors are to be tried, investigators are\ngiven specialized training and that accused children are tried in specialized juvenile\nchambers with appropriate procedures in place;\n(h) Enforce the application of judicial protection measures for child victims\nin order to facilitate their participation and to protect their identity;\n(i) Take concrete and effective steps to ensure, by incorporating a gender\nperspective, that victims of sexual violence and child victims have access to\nappropriate medical, psychosocial and socioeconomic services;\n(j) Work to secure the immediate release of the women and children who\nare still held captive by the Bana Mura militiamen in Kamonia territory."},{"id":"a-hrc-38-31-p0112","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"112","seq":111,"section":"B. Recommendations","text":"The team recommends that MONUSCO provide practical support to the\ncompetent judicial authorities in the prosecution of perpetrators of international\ncrimes in Kasa�, including by facilitating the holding of mobile court hearings."},{"id":"a-hrc-38-31-p0113","rec_id":"recXXveoh2wisZaA5","symbol":"A/HRC/38/31","n":"113","seq":112,"section":"B. Recommendations","text":"The team recommends that the Secretary-General of the United Nations closely\nmonitor the progress of the investigations by the Democratic Republic of the Congo\ninto the deaths of the two United Nations experts and their companions and, if\nnecessary, broaden the mandate and increase the resources of the United Nations\ncountry team responsible for supporting the national investigation to ensure that\nthose responsible are brought to justice."},{"id":"a-hrc-41-31-p0001","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"1","seq":0,"section":"I. Introduction","text":"Starting in August 2016, the Kasai region of the Democratic Republic of the Congo\nsuffered a wave of bloody violence perpetrated by armed groups (the Kamuina Nsapu,\nBana Mura and �curie Mbembe militias) and members of the defence and security forces of\nthe Democratic Republic of the Congo (the Armed Forces of the Democratic Republic of\nthe Congo, the national police, the National Intelligence Agency and the Directorate\nGeneral of Migration). Several thousand people were killed, countless acts of violence were\ncommitted against civilians and entire villages were set on fire and plundered. The violence\nalso resulted in the displacement of more than one million people, giving rise to an acute\nhumanitarian crisis."},{"id":"a-hrc-41-31-p0002","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"2","seq":1,"section":"I. Introduction","text":"At the request of the Human Rights Council, the United Nations High\nCommissioner for Human Rights dispatched a team of three international experts in 2017 to\ndetermine the facts and circumstances of the alleged human rights violations and violations\nof international humanitarian law in the Kasai region.1"},{"id":"a-hrc-41-31-p0003","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"3","seq":2,"section":"I. Introduction","text":"In the report that it submitted to the Council in July 2018, the team of international\nexperts concluded that the parties involved had: (a) deliberately killed civilians, including\nmany children; (b) committed numerous atrocities, including mutilation, rape and other\nforms of sexual violence; and (c) destroyed entire villages. It also concluded that some of\nthese abuses constituted crimes against humanity and war crimes, as well as serious\nviolations of human rights.2 Recognizing the urgent need to begin combating impunity for\nthe crimes and violations committed in Kasai since 2016, while stressing the need for non-\njudicial measures to promote reconciliation, the team of international experts made a\nnumber of recommendations to the authorities of the Democratic Republic of the Congo.3"},{"id":"a-hrc-41-31-p0004","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"4","seq":3,"section":"I. Introduction","text":"On 6 July 2018, noting with concern the conclusions of the team of international\nexperts, the Human Rights Council requested the High Commissioner to dispatch a new\nteam of international experts to monitor, evaluate and support the implementation by the\nDemocratic Republic of the Congo of the recommendations made by the previous team in\nits report, in particular with regard to the fight against impunity and measures to promote\nreconciliation and transitional justice.4"},{"id":"a-hrc-41-31-p0005","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"5","seq":4,"section":"I. Introduction","text":"The international experts, Bacre Waly Ndiaye of Senegal (Chair) and Sheila B.\nKeetharuth of Mauritius (member), were appointed by the High Commissioner on 20\nAugust 2018 and performed this monitoring and evaluation work once their secretariat had\nbeen set up, over the course of three missions to the Democratic Republic of the Congo in\nNovember 2018, February and March 2019 and April 2019. They supported the competent\nauthorities by holding thematic workshops, one on 28 February 2019 in Tshikapa, on\ninvestigation and prosecution strategies in the fight against impunity, and another on 17 and\n18 April 2019 in Kananga, bringing together the stakeholders involved in the reconciliation\nand transitional justice process in the Kasai region. The new team of international experts\nwas supported in the fulfilment of its mandate by a secretariat that was based in Kananga\nand composed of nine members, including five international members, some of whom were\nexperts in the areas of gender and transitional justice."},{"id":"a-hrc-41-31-p0006","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"6","seq":5,"section":"I. Introduction","text":"On 19 March 2019, the two international experts participated in an enhanced\ninteractive dialogue at the fortieth session of the Council, during which they reported on the\nprogress of their work and shared some preliminary findings. The present report, submitted\nto the Council at its forty-first session, contains the conclusions and recommendations of\nthe team of international experts.\n1 Human Rights Council resolution 35/33 of 23 June 2017, para. 10.\n2 Report of the team of international experts on the situation in Kasa� (A/HRC/38/31), paras. 105�109.\n3 Ibid., paras. 110�113.\n4 Human Rights Council resolution 38/20."},{"id":"a-hrc-41-31-p0007","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"7","seq":6,"section":"II. Mandate","text":"Human Rights Council resolution 38/20, which was adopted by consensus on 6 July\n2018, charges the team of international experts with the task of monitoring, evaluating,\nsupporting and reporting on the implementation by the Democratic Republic of the Congo\nof the recommendations made by the previous team and making recommendations in this\nregard, as appropriate."},{"id":"a-hrc-41-31-p0008","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"8","seq":7,"section":"II. Mandate","text":"The mandate of the team of international experts under resolution 38/20 differs from\nthat of a fact-finding mission in that the primary goal of the new team is not to draw factual\nconclusions but rather to report on and support the efforts made by a State in the light of a\nreport concluding that international crimes and human rights violations have been\ncommitted on its territory. This mechanism is a groundbreaking initiative of the Council\nand builds on the international community's recent efforts to ensure the accountability of\nStates when it comes to the investigation and prosecution of international crimes and other\nhuman rights violations and the process of reconciliation. The team adopted a methodology\nthat not only takes into account the specific national context but also reflects international\nprinciples, for it is aware that its work may serve as inspiration for other similar\nmechanisms."},{"id":"a-hrc-41-31-p0009","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"9","seq":8,"section":"II. Mandate","text":"The team of international experts notes that its mandate converges with that of other\nUnited Nations mechanisms already in place in the Democratic Republic of the Congo. The\nHigh Commissioner has deployed a technical assistance team to Kananga, under the\nauthority of the United Nations Joint Human Rights Office, to support the competent\nnational authorities in their investigation of human rights violations, including by providing\nforensic expertise. 5 The United Nations Organization Stabilization Mission in the\nDemocratic Republic of the Congo (MONUSCO) is also working to support the national\nauthorities in the area of justice and reconciliation in Kasai through its observation and\nreporting activities and technical support."},{"id":"a-hrc-41-31-p0010","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"10","seq":9,"section":"II. Mandate","text":"In addition, the Secretary-General of the United Nations has deployed a team of\nexperts specifically to assist with the trial for the killing of Security Council experts\nMichael Sharp and Zaida Catal�n and the Congolese nationals who were accompanying\nthem.6 Other United Nations mechanisms,7 international cooperation partners such as the\nEuropean Union, and international and Congolese non-governmental organizations (NGOs)\nare also involved in efforts to combat impunity and to promote reconciliation in Kasai. For\nexample, the project entitled Peace, Justice, Reconciliation and Reconstruction in Kasai\nCentral, which is financed by the Peacebuilding Fund and implemented by the United\nNations Development Programme, the United Nations Joint Human Rights Office and the\nNGO called Search for Common Ground, is focused on supporting the administration of\ncriminal justice, reconciliation and economic recovery in Kasai Central."},{"id":"a-hrc-41-31-p0011","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"11","seq":10,"section":"II. Mandate","text":"In this context, the team of international experts sought to identify the added value\nof its mandate and to determine how the team could help to strengthen the impact of\nexisting projects and programmes. The platform provided by the Human Rights Council\nallows it to draw attention to efforts and gaps that might otherwise go unnoticed and to\nensure that the situation in Kasai is not forgotten. Equally, this attention from the\ninternational community is likely to encourage the authorities of the Democratic Republic\nof the Congo to redouble their efforts to create the conditions for lasting peace in Kasai and\nto obtain appropriate assistance. As regards support for the implementation of the\nrecommendations, the team considered that, in addition to assisting the State, it could\ncatalyse the efforts of community leaders by bringing all stakeholders together around the\nsame table, as it did at the workshops held in Tshikapa and Kananga."},{"id":"a-hrc-41-31-p0012","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"12","seq":11,"section":"III. Cooperation between the team of international experts and","text":"A mandate such as the one given to the team of international experts cannot be\nfulfilled without genuine collaboration between the international experts and the authorities\nof the State concerned. The team appreciated the spirit of cooperation and openness that\nmarked its exchanges with the national and provincial authorities of the Democratic\nRepublic of the Congo over the course of its missions. The secretariat based in Kananga\nwas able to carry out its work unhindered by the political and military authorities."},{"id":"a-hrc-41-31-p0013","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"13","seq":12,"section":"III. Cooperation between the team of international experts and","text":"This spirit of openness was demonstrated by the new President of the Republic,\nF�lix Tshisekedi, who met with the international experts on 8 March 2019. During this\nmeeting, which was also attended by the Minister for Human Rights, President Tshisekedi\nand the international experts discussed the challenges relating to the fight against impunity\nand the process of reconciliation and transitional justice in Kasai. President Tshisekedi,\nwho has made respect for human rights a priority of his term in office, expressed his\nappreciation for the work of the international experts."},{"id":"a-hrc-41-31-p0014","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"14","seq":13,"section":"III. Cooperation between the team of international experts and","text":"The missions undertaken by the team of international experts coincided with a\nperiod of political transition, between the presidential and legislative elections of 30\nDecember 2018 and the instatement of the new national and provincial government\nauthorities, which had not yet occurred at the time of writing. Generally, however, the\noutgoing authorities dealt with day-to-day matters during this period, which enabled the\nteam to continue the existing dialogue regarding Kasai."},{"id":"a-hrc-41-31-p0015","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"15","seq":14,"section":"IV. Current situation in Kasai","text":"Since the previous team of international experts completed its work, the situation in\nthe Democratic Republic of the Congo and Kasai has changed significantly in ways that\nhave affected the implementation of the team's recommendations."},{"id":"a-hrc-41-31-p0016","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"16","seq":15,"section":"IV. Current situation in Kasai","text":"On 30 December 2018, the people of the Democratic Republic of the Congo went to\nthe polls to elect a new president. On 20 January 2019, the Constitutional Court proclaimed\nF�lix Tshisekedi President of the Republic, thus paving the way for the first peaceful\ntransition in the history of the country. The election of Mr. Tshisekedi, a native of Kasai,\ngave the people of that region hope that they would no longer feel abandoned by the central\nGovernment. Moreover, Mr. Tshisekedi's commitment to making human rights a priority\ncould give fresh impetus to the fight against impunity and to reconciliation and transitional\njustice efforts in Kasai."},{"id":"a-hrc-41-31-p0017","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"17","seq":16,"section":"IV. Current situation in Kasai","text":"The election of Mr. Tshisekedi sparked a spontaneous voluntary disarmament\nmovement among members of the Kamuina Nsapu militia. 8 The election of a \"son of\nKasai\" seems to have made some Kamuina Nsapu militia members feel as though they are\nnow part of the central authority that they had previously fought against. In Kananga, the\nprovincial authorities have offered monetary compensation according to the type of weapon\nthat is handed in."},{"id":"a-hrc-41-31-p0018","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"18","seq":17,"section":"IV. Current situation in Kasai","text":"The team of international experts notes, however, that the disarmament process is\nbeing conducted in a highly questionable manner and lacks supervision and perspective.\nWeapons are deposited in exchange for money and the circulation of those weapons is not\neffectively controlled. Furthermore, the process does not address the issue of reintegration,\nespecially that of girls, or the issue of criminal responsibility. It should be noted that the\nprocess has been suspended and MONUSCO has offered its assistance.\n8 It is worth noting that this is not the first disarmament movement that has occurred among the\nKamuina Nsapu militia. After the forum for peace, reconciliation and development in September\n2017 and the election of the Governor of Kasai Central Province in December 2017, some Kamuina\nNsapu militia leaders handed in their weapons, although in circumstances that raise many questions."},{"id":"a-hrc-41-31-p0019","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"19","seq":18,"section":"IV. Current situation in Kasai","text":"The disarmament movement could lose its fragile momentum at any time. Moreover,\nit is taking place in a context where ethnic tensions remain high, as illustrated by the events\nof 24 February 2019 in Kamako (Kasai Province), where several Kamuina Nsapu militia\nmembers who had surrendered their weapons were killed by the Armed Forces of the\nDemocratic Republic of the Congo after clashes between the Luba and Tetela peoples. So\nfar, there is nothing to suggest that the Bana Mura and �curie Mbembe militias intend to\nfollow the example of the Kamuina Nsapu militia. Worse still, there are signs that a Tetela\nmilitia may be forming."},{"id":"a-hrc-41-31-p0020","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"20","seq":19,"section":"IV. Current situation in Kasai","text":"Meanwhile, a serious humanitarian crisis is raging as a result of the mass return of\nseveral hundred thousand Congolese nationals, most of whom have been expelled from or\nforced to leave Angola by the Angolan authorities. This influx has put additional pressure\non the almost non-existent reception facilities at the border and has caused serious\nproblems, including health problems, as a result. In addition to the violence that they have\nsuffered in Angola, returning displaced persons and expelled persons also appear to be\nsubjected to violence and extortion in the Democratic Republic of the Congo, by the\ndefence and security forces in particular. The humanitarian crisis is an obstacle to\nreconciliation efforts in this area of Kasai. It was reported to the team of international\nexperts that, while the wounds have not yet had time to heal, the population is now a\nmishmash of executioners and victims of the crisis that has been raging in Kasai since\n2016. In these circumstances, which are complicated further by the humanitarian crisis, a\ndialogue of reconciliation may not be a realistic prospect. Resolving the humanitarian crisis\nat the Angolan border is therefore a major challenge that must be overcome in order to\nrestore lasting peace in Kasai."},{"id":"a-hrc-41-31-p0021","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"21","seq":20,"section":"V. Monitoring, evaluation and support for the implementation","text":"The conclusions of the team of international experts are based on the team's\nobservations and interactions with various stakeholders, namely the political, judicial and\nmilitary authorities, the police, traditional leaders, the bar association, the academic\ncommunity, civil society organizations, MONUSCO and other United Nations entities, and\nthe diplomatic community."},{"id":"a-hrc-41-31-p0022","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"22","seq":21,"section":"V. Monitoring, evaluation and support for the implementation","text":"The team of international experts appreciates the State's public commitment to\npromoting justice and reconciliation in Kasai. In November 2018, under the aegis of the\nthen Minister of Justice, a working group, comprising the Minister of Defence, the Minister\nfor Human Rights, the Personal Representative of the Head of State for Combating Sexual\nViolence and Child Recruitment and the Chief Military Prosecutor of the Armed Forces of\nthe Democratic Republic of the Congo, was set up to deal with issues relating to Kasai. The\nmeeting of this ministerial group was to be followed by technical working meetings, which\nunfortunately had not yet been held when the team of international experts was finalizing\nthis report."},{"id":"a-hrc-41-31-p0023","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"23","seq":22,"section":"V. Monitoring, evaluation and support for the implementation","text":"The team of international experts proposes to review below the implementation of\nthe recommendations contained in the previous team's report, which concern two main\nareas, namely the fight against impunity and support for reconciliation and transitional\njustice efforts."},{"id":"a-hrc-41-31-p0024","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"24","seq":23,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"Calling on the authorities of the Democratic Republic of the Congo to begin\ncombating impunity for the serious crimes committed in Kasai without further delay, the\nteam of international experts made a number of recommendations regarding the\ninvestigation and prosecution of those crimes and the support provided to victims and\nwitnesses.\n1. Analysis of the prosecution process"},{"id":"a-hrc-41-31-p0025","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"25","seq":24,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"In the Democratic Republic of the Congo, the prosecution of international crimes is\nlargely dealt with by the military justice authorities. Although Congolese law provides for\nthe concurrent jurisdiction of the civil and military justice authorities over such cases,9 in\npractice, the latter handle almost all prosecutions, whether they concern members of the\narmed forces or civilians. The team of international experts found that the military justice\nauthorities in Kasai are theoretically capable of investigating and prosecuting the serious\ncrimes that have been committed there. The commitment, professionalism and competence\nof the members of the military prosecutors' offices in Kasai were demonstrated during the\nworkshop in Tshikapa and the heads of those offices have gained experience in the east of\nthe Democratic Republic of the Congo. Nevertheless, representatives of the civil justice\nsystem and the bar association of Kananga recommended building the capacity of the civil\njustice authorities to deal with such cases as well. The team shares this view, for the\nprosecution process would be strengthened by the parallel involvement of the civil justice\nauthorities."},{"id":"a-hrc-41-31-p0026","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"26","seq":25,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"Since the investigations into the serious crimes committed in Kasai are still at the\ninitial stage, the team of international experts interacted with the military prosecution\nservices mainly for the purposes of monitoring, evaluating and supporting: (a) the\nimplementation of investigation and prosecution strategies; and (b) the allocation of human\nand logistical resources to this end. It will be necessary to carry out follow-up work with\nthe military courts when the investigations lead to trials and possible convictions.10"},{"id":"a-hrc-41-31-p0027","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"27","seq":26,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The team of international experts points out that the map of military judicial districts\nin Kasai is based on the old provincial divisions, which changed as a result of the territorial\nreform in 2015. Thus, two senior military prosecutors' offices are responsible for the five\ncurrent provinces of Kasai, one for the former Province of Kasai Occidental (covering the\nProvinces of Kasai and Kasai Central) and the other for the former Province of Kasai\nOriental (covering the Provinces of Kasai Oriental, Lomami and Sankuru).\n(a) Existence of an inclusive and comprehensive strategy of investigation and prosecution,\nwith a particular focus on crimes of sexual violence"},{"id":"a-hrc-41-31-p0028","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"28","seq":27,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The previous team of international experts called on the competent authorities to\napply a prosecution strategy that covered all perpetrators who had been involved in the\nviolence in Kasai.11"},{"id":"a-hrc-41-31-p0029","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"29","seq":28,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"With the support of MONUSCO and guided by international principles relating to\nthe selection and prioritization of cases, the senior military prosecutor's office of the former\nProvince of Kasai Occidental has drawn up a list of 16 incidents that are to be investigated\nas a priority. The cases concern the following regions and localities: Tshisuku, Nganza,\nKatoka, Diboko, Malenga, Tshikapa, Mutshima, Maswika, Nkoto, Tshinyembe, Tshimbulu,\nKabeya-Madi, Luebo and Kamonia (bearing in mind that some of these places feature in\nmore than one case)."},{"id":"a-hrc-41-31-p0030","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"30","seq":29,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"At the workshop in Tshikapa on 28 February 2019, the senior military prosecutor of\nthe former Province of Kasai Occidental explained that he had selected and prioritized\ncases on the basis of three criteria, focusing on: (a) the easiest cases (or the low-hanging\nfruit); (b) high impact cases; and (c) the cases involving the most serious violations.12"},{"id":"a-hrc-41-31-p0031","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"31","seq":30,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The strategy defined by the military prosecutor's office focuses on cases that have\nbecome emblematic owing to the particularly shocking circumstances in which the crimes\nwere committed, such as: (a) the \"door-to-door\" operations of the Armed Forces of the\nDemocratic Republic of the Congo in the commune of Nganza in Kananga (Kasai Central\nProvince) in March 2017;13 (b) the disappearance of national school inspectors in Kazumba\nterritory (Kasai Central Province) at the end of April 2017, which was attributed to the\nKamuina Nsapu militia;14 (c) the attack on the Tshikulu village market in Kazumba territory\nby members of the Armed Forces of the Democratic Republic of Congo in May 2017;15 (d)\nthe killing of 37 members of the National Response Legion of the national police by the\nKamuina Nsapu militia near the village of Malenga in Kamonia territory (Kasai\nProvince);16 and (e) the holding of women and children in captivity by the Bana Mura\nmilitia in Kamonia territory.17"},{"id":"a-hrc-41-31-p0032","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"32","seq":31,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"Only one of these cases is ready to be tried, namely the one involving crimes\ncommitted by the Kamuina Nsapu militia in Luebo. Little progress has been made on most\nof the other cases since the adoption of the strategy, despite the investigations that have\nbeen conducted jointly with MONUSCO and the technical assistance team. 18 While\nprogress is hindered in some cases by the unstable security situation in certain areas, in\nother cases, the problem seems to be a lack of cooperation on the part of senior military\nofficials, who have failed to act upon requests for judicial assistance to allow for the\nquestioning of suspects who are members of the Armed Forces of the Democratic Republic\nof the Congo and have been redeployed elsewhere in the country. Lastly, in some cases, the\nslow progress seems to be due to a lack of human or logistical resources, as discussed\nbelow."},{"id":"a-hrc-41-31-p0033","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"33","seq":32,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"Although it is true that there is an investigation and prosecution strategy in place, the\nteam of international experts believes that this strategy can be refined, strengthened and\nimplemented more quickly."},{"id":"a-hrc-41-31-p0034","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"34","seq":33,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"In the context of transitional justice, strategically selecting cases for prosecution has\nthe potential to contribute more broadly to reconciliation efforts by highlighting the root\ncauses of the crisis. Furthermore, a strategic approach to prosecution helps to ensure\nobjective fact-finding and to establish the truth. With that in mind, and as discussed at the\nworkshop in Tshikapa on 28 February 2019, the team of international experts believes that\nthe strategy adopted by the military prosecutor's office should incorporate a number of\nother issues that were brought to light by the 2016 crisis."},{"id":"a-hrc-41-31-p0035","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"35","seq":34,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The team of international experts notes, firstly, that the vast majority of the cases\nthat are currently under investigation involve abuses committed by the Kamuina Nsapu\nmilitia. Yet the defence and security forces and the Bana Mura and �curie Mbembe militias\nhave also committed abuses on a large scale, as detailed in the previous team's report, and\nthe strategy of the military prosecutor's office does not properly take into account the\nextent of these crimes. The strategy also fails to address the ethnic dimension of the\nconflict, including the emergence of the Bana Mura and �curie Mbembe militias as of\nJanuary 201719 and the crimes of persecution to which that led.20"},{"id":"a-hrc-41-31-p0036","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"36","seq":35,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"Secondly, although there are some investigations into sexual crimes, the team of\ninternational experts notes that the strategy does not adequately reflect the massive scale or\nthe fundamentally sexist nature of these crimes. The previous team of international experts\nemphasized in its report that women and children were the main victims of violence in\nKasai between 2016 and 2017, especially sexual violence.21 This sexual violence took many\nforms: although most cases involved rape, there were also cases of sexual slavery, sexual\nmutilation, forced exposure of private parts and forced witnessing of relatives being\nsubjected to rape and sexual violence. All parties engaged in such acts, including the\ndefence and security forces, even though their main task is to protect the population.22 A\nrobust response from the criminal justice system is therefore necessary in order to condemn\nsuch acts in the strongest possible terms and prevent repeat offences. An investigation and\nprosecution strategy to combat sexual violence as a whole would also give a voice to\nvictims who are prevented from speaking out by the taboos and social stigma attached to\nsexual violence. 23 Lastly, a strategy that addresses sexual crimes in a comprehensive\nmanner would pave the way for public recognition of the sexist nature of these crimes,\nwhich may facilitate the social rehabilitation of victims."},{"id":"a-hrc-41-31-p0037","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"37","seq":36,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The problem of the recruitment and use of child soldiers also reached alarming\nproportions during the conflict, with the forcible recruitment of young persons (or even\nvery young persons)24 by the militias, who took advantage of their vulnerability in order to\nmake them commit crimes. The senior military prosecutor's office of the former Province\nof Kasai Occidental affirms that it is investigating cases of this kind but the strategy, in its\ncurrent form, certainly does not convey the scale of the problem."},{"id":"a-hrc-41-31-p0038","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"38","seq":37,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The systematic and widespread nature of the violence in Kasai is also evident from\nthe extensive use of beheading as a means of killing people or mutilating dead bodies and\nthe burning down of public buildings and houses.25 While the team of international experts\nrecognizes that such crimes are being investigated, it feels that the strategy should\ncomprehensively address the systematic and widespread nature of these crimes so as to\nbetter reflect the wave of violence as a whole."},{"id":"a-hrc-41-31-p0039","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"39","seq":38,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The team of international experts believes that an investigation and prosecution\nstrategy that fails to incorporate the aspects mentioned above may lead to greater impunity\nand, consequently, undermine victims' trust in the justice system, which is essential for\nreconciliation. The team therefore calls on the military justice authorities to improve their\nstrategy with respect to the crimes committed in the Provinces of Kasai and Kasai Central\nand to increase the involvement of civil society, especially associations that work with\nvictims. The Congolese Criminal Code, which has been amended to include definitions of\ninternational crimes, provides a legal basis for the prosecution of all perpetrators.26 The\nmilitary justice authorities must also step up the pace, for some crimes date back almost\nthree years and the passage of time works against the criminal justice system by weakening\n19 A/HRC/38/31, paras. 54 ff.\n20 Ibid., paras. 97�98.\n21 Ibid., paras. 93 and 95.\n22 Members of the Armed Forces of the Democratic Republic of the Congo even went so far as to\nexploit the vulnerability of women who were fleeing the violence (ibid., para. 83).\n23 Ibid., para. 95.\n24 See, for example, A/HRC/38/31, para. 62.\n25 Ibid., paras. 97�98.\n26 Ibid., paras. 14 and 111 (b). Moreover, the recent decision of the Appeals Chamber of the\nInternational Criminal Court, in which it refused to exclude violence against members of the armed\nforces from the scope of war crimes, gives the Congolese military justice authorities the legal means\nto expand the scope of their investigations into sexual crimes committed against child soldiers. See\nThe Prosecutor v. Bosco Ntaganda, Judgment on the appeal of Mr. Ntaganda against the \"Second\ndecision on the Defence's challenge to the jurisdiction of the Court in respect of Counts 6 and 9\", 15\nJune 2017, ICC-01/04-02/06-1962.\nthe reliability of testimony, which is often the only evidence available, and making it more\ndifficult to identify and preserve physical evidence, such as mass graves."},{"id":"a-hrc-41-31-p0040","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"40","seq":39,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The team of international experts notes that the senior military prosecutor's office of\nthe former Province of Kasai Oriental has not yet opened any investigations into the\ninternational crimes committed in this region, owing to the recent arrival of a new senior\nmilitary prosecutor. Although the Provinces of Kasai Oriental, Lomami and Sankuru were\nnot so heavily affected by the violence, the fact remains that serious crimes, including\ncrimes of sexual violence, were committed in this area by members of the Kamuina Nsapu\nmilitia and the defence and security forces.27 At the workshop in Tshikapa on 28 February\n2019, the team could see that the military prosecutor's office for this region was willing to\nstart the investigation process. Given that the availability and quality of evidence is affected\nby the passage of time, it is urgently necessary to launch the criminal investigations as soon\nas possible.\n(b) Allocation of sufficient specialized human and logistical resources"},{"id":"a-hrc-41-31-p0041","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"41","seq":40,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The Kasai region covers an area of more than 320,000 km2. There are virtually no\nroads or tracks that are suitable for vehicles and the security conditions are unstable.\nConducting investigations there in order to identify the perpetrators of the many crimes\ncommitted requires considerable human and logistical resources. For example, at the\nInternational Criminal Court, which has jurisdiction over the Democratic Republic of the\nCongo, a single case involves a team of more than a dozen professionals, including both\ninvestigators and prosecutors, with specialized equipment and a budget that allows them to\ntravel to the sites where crimes were committed. It was in this context that the previous\nteam of international experts recommended that the authorities of the Democratic Republic\nof the Congo should increase the human and logistical resources of military prosecutors'\noffices in Kasai.28 Since the cases identified by the senior military prosecutor's office of the\nformer Province of Kasai Occidental are still at the investigation stage, the team of\ninternational experts has focused its attention primarily on the resources allocated to\nmilitary prosecutors' offices."},{"id":"a-hrc-41-31-p0042","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"42","seq":41,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The team of international experts notes with concern that the senior military\nprosecutors' offices in Kasai face a severe lack of resources that has not been remedied\nsince the submission of the previous team's report. For example, at present, the senior\nmilitary prosecutor's office of the former Province of Kasai Occidental has only two\nprosecutors: a senior military prosecutor and his deputy. The military prosecutors' offices\nof the garrisons of Kananga and Tshikapa, which are under the responsibility of the senior\nmilitary prosecutor's office, have only seven prosecutors in total. These prosecutors must\nnot only lead the investigations into the serious crimes committed since 2016 but also deal\nwith cases that are pending. The premises of the military prosecutor's office are in a bad\nstate of disrepair and lack a secure space for storing evidence. Furthermore, the office has\nno specialized equipment for forensic investigations, including the exhumation of mass\ngraves.29 The team of international experts was informed that, in 2018, the operating funds\nof the senior military prosecutor's office of the former Province of Kasai Occidental\nprovided for in the Budget Act had not yet been transferred."},{"id":"a-hrc-41-31-p0043","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"43","seq":42,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"Given the number and the scale of the international crimes committed in Kasai since\n2016, these levels of staffing and resources are far below what is required in order to be\nable to conduct investigations effectively and build strong cases against those who have\ncommitted serious crimes, even if only those who are suspected of bearing the greatest\nresponsibility. The team of international experts believes that this shortage of resources is\none of the factors that explains why the investigation and prosecution strategy has not\nyielded tangible results."},{"id":"a-hrc-41-31-p0044","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"44","seq":43,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The few investigations that have been carried out thus far by the senior military\nprosecutor's office of the former Province of Kasai Occidental would not have been\n27 A/HRC/38/31, paras. 49�50 (Kasai Oriental Province) and para. 65 (Lomami Province).\n28 Ibid., para. 111 (c) (i).\n29 For the moment, it is the technical assistance team that provides the necessary expertise.\npossible without the financial and logistical support of MONUSCO and the technical\nassistance team through the joint investigation mechanism. The team of international\nexperts is concerned by this over-reliance on external actors, whose role is to provide\nassistance in specific instances and for a limited time only, especially as discussions on an\nexit strategy for MONUSCO have begun.30 At the workshop in Tshikapa on 28 February\n2019, the international experts addressed the issue of empowering the military prosecutors'\noffices to work independently and building on the progress that has been made thanks to\nexternal actors."},{"id":"a-hrc-41-31-p0045","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"45","seq":44,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"In this context, the team of international experts calls on the military justice\nauthorities as a whole to review the allocation of resources to the Kasai region. At the\nmoment, the only trial concerning events in Kasai that is under way � namely, the trial for\nthe killing of the two Security Council experts, Michael Sharp and Zaida Catal�n, and the\nfour Congolese nationals who were accompanying them � is fully mobilizing the scarce\nresources available, as the military court of the garrison of Kananga has only two members.\nTo ease the burden placed on the Kasai military justice system, the team of international\nexperts calls on the national authorities to consider the possibility of temporarily deploying\nadditional public prosecutors and judges to Kasai. Since the public prosecution service is\nbeing directly represented by the general military prosecutor's office at the trial for the\nkilling of the experts and the four persons who were accompanying them, the team expects\nthe same level of interest to be shown for all other cases involving acts of violence\ncommitted in Kasai."},{"id":"a-hrc-41-31-p0046","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"46","seq":45,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"Public prosecutors and inspectors need specialized knowledge and skills in order to\nbe able to deal with crimes of the kind that were committed by all parties to the conflict,\nthat is, crimes against humanity and war crimes. In this connection, the team of\ninternational experts notes that the previous team recommended in its report that the\nnational authorities should, for example, ensure that specialized personnel are assigned the\nspecific task of investigating and prosecuting crimes of sexual violence.31"},{"id":"a-hrc-41-31-p0047","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"47","seq":46,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The workshop that was held in Tshikapa on 28 February 2019 brought together\nmembers of the military prosecutors' offices in Kasai and representatives of the bar\nassociation and the civil justice system around the same table for the first time. Both during\nthis workshop and at earlier work sessions, the team of international experts noted that the\nmembers of the military prosecutors' offices had a good knowledge of the legal framework\napplicable to international crimes, including sexual crimes. However, the team also noted\nthat the military prosecutors' offices in Kasai lacked women prosecutors. Given that\nwomen are among the main victims of the violence in Kasai, the team considers that\nparticular attention should be paid to the recruitment of women into the military justice\nsystem in Kasai."},{"id":"a-hrc-41-31-p0048","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"48","seq":47,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"Lastly, the team of international experts draws attention to the previous team's\nrecommendation that the authorities of the Democratic Republic of the Congo should\nensure that the officers in charge of the prosecutors' offices have at least the same rank as\nthe operational officers who may be held criminally liable. 32 The two senior military\nprosecutors who are currently in charge of the military prosecutors' offices in Kasai have\nthe rank of colonel. Since senior military prosecutors in other regions of the country hold\nthe rank of general, and in order to ensure that members of the Armed Forces of the\nDemocratic Republic of the Congo who were involved in the crimes committed in 2016 and\n2017 can be investigated without fear of rank-related conflict between prosecutors and\nsuspects, the team of international experts reiterates the previous team's recommendation\nthat the military prosecutors' offices in Kasai should be placed under the authority of\nofficers with the rank of general.\n30 See Security Council resolution 2463 (2019) of 29 March 2019, para. 44.\n31 A/HRC/38/31, para. 111 (d).\n32 Ibid., paras. 109 and 111 (c) (ii). See also article 67 of Act No. 023/2002 of 18 November 2002\nestablishing the Code of Military Justice: \"The prosecutor who represents the public prosecutor's\noffice at the hearing must hold a rank higher than or equal to that of the accused.\"\n(c) The fate of the women and children still in captivity in Kamonia territory (Kasai\nProvince)"},{"id":"a-hrc-41-31-p0049","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"49","seq":48,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The team of international experts notes that the previous team reported that several\ndozen Luba women and girls were being held against their will by the Bana Mura militia on\nfarms in Kamonia territory (Kasai Province), where they were forced to work and subjected\nto sexual slavery, 33 and called for their immediate release. 34 Although the team of\ninternational experts has neither the mandate nor the resources to investigate new\nallegations of serious human rights violations, during its interaction with the national\npolitical authorities and representatives of MONUSCO on the ground, it obtained some\ninformation which suggests that women and children are still being held by the Bana Mura\nmilitia. During a joint fact-finding mission undertaken by the senior military prosecutor's\noffice of the former Province of Kasai Occidental and MONUSCO in October 2018, a total\nof 38 people were interviewed, including at least 22 women and 4 children who had\nallegedly been abducted and subjected to sexual violence and forced labour. During their\nvisit to Tshikapa in February 2019, the international experts had the opportunity to speak to\nwomen who had successfully escaped from the farms where they were being held and who\nsaid that several other women were still there. At every opportunity, the team called for the\nimmediate release of these women and children."},{"id":"a-hrc-41-31-p0050","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"50","seq":49,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The team of international experts notes that, during the team's first mission to the\nDemocratic Republic of the Congo in November 2018, the Government expressed doubts\nas to whether the situation was truly as described. The Government subsequently qualified\nits comments and acknowledged its obligation to work to secure the victims' release. The\nteam of international experts stresses once again that it is urgently necessary to secure the\nimmediate release of these women and children and to ensure that those who have managed\nto flee are not left to fend for themselves.\n2. Support for victims and witnesses"},{"id":"a-hrc-41-31-p0051","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"51","seq":50,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"In the light of its findings on the extent of the sexual crimes committed in Kasai, the\nprevious team of international experts recommended that the authorities of the Democratic\nRepublic of the Congo should enforce the application of judicial protection measures for\nvictims of crimes of sexual violence and, by providing legal assistance, encourage them to\nlodge complaints and to testify before the courts.35 It also called on the authorities to take\nconcrete and effective steps to ensure, by incorporating a gender perspective, that victims of\nsexual violence have access to appropriate medical, psychosocial and socioeconomic\nservices.36 It made substantially similar recommendations with respect to child victims.37\nSupport and care for victims of sexual violence and child victims is essential in order to be\nable to repair the social fabric of Kasai."},{"id":"a-hrc-41-31-p0052","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"52","seq":51,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"Since none of the cases selected by the military justice authorities have been brought\nto trial yet, the team of international experts has focused its attention on the way in which\nthe military prosecutor's office conducts investigations into cases involving victims of\nsexual crimes and child victims. The team is pleased to note that, during the investigations\nof this kind that were conducted jointly with MONUSCO and the technical assistance team,\nappropriate and sufficient measures were taken to protect witnesses and victims of crimes\nof sexual violence and child victims during hearings. In the field, the investigators and\nprosecutors from the military prosecutor's office attended briefings, which covered issues\nsuch as the protection of information. 38 During the hearings, which were conducted in such\na way as to protect the identity of the witnesses, the investigators were accompanied by\n33 A/HRC/38/31, para. 86.\n34 Ibid., para. 111 (j).\n35 Ibid., para. 111 (e).\n36 Ibid., para. 111 (i).\n37 Ibid., para. 111 (h) and (i).\n38 These briefings were given by members of MONUSCO (in particular, the Child Protection Section)\nand members of the technical assistance team, the bar association of Kananga and local NGOs with\nexpertise in this area. In addition, in April 2018, the technical assistance team ran a training workshop\nfor members of the military prosecutors' offices on protective measures.\npsychosocial support workers. After the hearings, the persons who had been interviewed\nreceived psychological support. The team calls on the military justice authorities to\ninstitutionalize these practices with a view to ensuring that investigations are conducted\nindependently and in an appropriate manner."},{"id":"a-hrc-41-31-p0053","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"53","seq":52,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"As regards legal aid, the bar association of Kananga runs a legal clinic in Kananga\nthat helps victims to take legal action. There is also a project entitled Combating Gender-\nbased Violence: Justice, Empowerment and Dignity for Women and Girls in the\nDemocratic Republic of the Congo, which is being implemented jointly by the United\nNations Development Programme, the United Nations Population Fund and the United\nNations Joint Human Rights Office. One of the aims of this project is to strengthen legal aid\nmechanisms for victims of sexual violence in certain regions of the country, including\nKasai Central. This project is also partly focused on supporting efforts to provide medical\ncare and psychosocial support to victims and to ensure their socioeconomic reintegration.\nM�decins sans fronti�res (international) is active in Kasai Central, where it deploys mobile\nclinics to provide surgical, medical and psychosocial assistance to victims of sexual\nviolence. Meanwhile, the Ministry of Health, Family and Gender Issues of Kasai Central\nProvince is involved in a campaign to raise awareness of sexual violence among traditional\nleaders and the general public."},{"id":"a-hrc-41-31-p0054","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"54","seq":53,"section":"A. Monitoring of accountability concerning the events in the Kasai region","text":"The team of international experts notes that almost all victim support initiatives are\nbeing run by external partners. Given the ever-increasing need for support,39 the State must,\nin accordance with its Constitution40 and the National Strategy to Combat Gender-based\nViolence of 2009, shoulder its responsibilities in this regard and seek to ensure the long-\nterm future of the mechanisms that are supported by international partners."},{"id":"a-hrc-41-31-p0055","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"55","seq":54,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"Noting that criminal penalties alone would not be sufficient to prevent violence from\nrecurring, the previous team of international experts recommended that the authorities of\nthe Democratic Republic of the Congo engage in an inclusive process of transitional justice\naimed at establishing the truth, identifying the root causes of the crisis and providing\nredress to victims, in order to ensure reconciliation.41"},{"id":"a-hrc-41-31-p0056","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"56","seq":55,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts notes that the Government held a forum for peace,\nreconciliation and development in the Kasai region, from 19 to 22 September 2017 in\nKananga. The then Prime Minister stated that the aim of this forum was to promote the\nrestoration of peace, reconciliation and the reconstruction of Kasai.42"},{"id":"a-hrc-41-31-p0057","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"57","seq":56,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"At the time of writing the present report, the team of international experts had no\nknowledge of the conclusions and recommendations issued as a result of the forum and\nnoted that there was no follow-up mechanism."},{"id":"a-hrc-41-31-p0058","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"58","seq":57,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"In order to gain a better understanding of the issue of reconciliation in Kasai, the\nteam of international experts held a workshop in Kananga on 17 and 18 April 2019. This\nworkshop brought together around 60 persons from the five provinces of the Kasai region.\nThe participants included representatives of the provincial authorities, traditional leaders,\nmembers of the Catholic clergy, academics and researchers from the Kasai region,\nmembers of the bar association, members of the Armed Forces of the Democratic Republic\nof the Congo and the national police, and representatives of civil society organizations.\nRepresentatives of humanitarian organizations, United Nations agencies and MONUSCO\nwere also present. Various topics were discussed during the workshop, including traditional\nreconciliation practices in the Kasai region, the responsibilities of the State, the issue of\ndisarmament and the socioeconomic situation.\n1. Traditional reconciliation practices in the Kasai region"},{"id":"a-hrc-41-31-p0059","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"59","seq":58,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"During the workshop in Kananga, three reconciliation rituals from the Kasai region\nwere discussed, namely: (a) drinking from the same cup (kunua cibalu in Luba); (b)\nwarding off evil (mucipu cikandakanda); and (c) making a pact for peace (kutua ndondo wa\nbupole). It was also explained that communities in Kasai are, for the most part, lineage-\nbased and acephalous. Traditionally, they lived separately from one another and were led\nby their elders (bakulu). The elders played the role of arbiters in matters concerning their\nlineage. They served as advisers and priests who led the worship of ancestors. Within each\nlineage, individuals were related through their paternal family (patrilineal descent) or their\nmaternal family (matrilineal descent). If there was a conflict between two lineages or within\na lineage, the elders, as representatives of the deceased, were supposed to settle the dispute\namicably. The persons in conflict were then invited, as a gesture of reconciliation, to drink\nfrom the same cup and to wash their hands. In some cases, sacrifices were made to appease\nthe spirits of the ancestors.43"},{"id":"a-hrc-41-31-p0060","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"60","seq":59,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"Conflict of any kind was considered an evil that disrupts communities. Steps were\ntherefore taken to ward off conflict, bring an end to it and reconcile the warring parties.\nWomen played a crucial role in this regard. With brooms, mixing implements and other\nobjects in their hands, they performed rituals to ward off evil, singing and calling on the\nmen to stop fighting and to be reconciled.44"},{"id":"a-hrc-41-31-p0061","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"61","seq":60,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"It was also noted that there was bloodshed in Kasai on the eve of national\nindependence. There were clashes between the Luba and Lulua peoples in 1959, in and\naround Luluabourg.45 In a vain attempt to bring an end to this crisis, the traditional leaders\nof the Luba and Lulua peoples signed two conventions, one in Munkamba on 12 January\n1960 before the arbitration mission that was chaired by the Belgian lawyer Rae, and the\nother in Brussels on 27 February 1960 in the presence of the Minister of the Belgian Congo\nand Rwanda-Urundi.46"},{"id":"a-hrc-41-31-p0062","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"62","seq":61,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"This conflict was eventually resolved through the use of a traditional practice, which\ntook the form of the Ntenda Pact of 20 October 1961. On this occasion, as a gesture of\nreconciliation, the traditional leaders of the Luba, Lulua, Kanyok, Kuba, Songye, Kete and\nBindji peoples and the political leaders of the Luba and Lulua peoples took part in several\nritual ceremonies. The final reconciliation was marked by festivities that took place from 21\nto 25 October 1961 in the cities of Luluabourg and Bakwanga, in the presence of the then\nHead of State, Joseph Kasavubu.47"},{"id":"a-hrc-41-31-p0063","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"63","seq":62,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"With that in mind, the team of international experts invites all political actors and\nother segments of society in Kasai to take inspiration from these events and to initiate an\ninclusive and sustainable reconciliation process that is appropriate to the present-day\nsituation in Kasai.\n2. The responsibilities of the State"},{"id":"a-hrc-41-31-p0064","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"64","seq":63,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The workshop in Kananga also covered the issue of State responsibilities and the\nrelated questions of what the State has already done and how, and what more it needs to do\nin order to achieve reconciliation. It was noted that legal proceedings had been brought\nagainst members of the Kamuina Nsapu militia and traditional leaders who are currently in\nprison. However, considering the scale of what took place, these measures are inadequate\nand further steps should be taken to prosecute, in addition, the members of the defence and\nsecurity forces who were involved in serious crimes.48"},{"id":"a-hrc-41-31-p0065","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"65","seq":64,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"Legal proceedings alone will not be enough to restore peace and bring about\nreconciliation in the Kasai region. Since most criminals are insolvent, it naturally falls to\nthe State to ensure that victims obtain reparation, even if it is merely symbolic. It was noted\nthat the new President of the Republic, F�lix Tshisekedi, had recently considered setting up\na fund for the provision of reparation to victims of large-scale violence.49"},{"id":"a-hrc-41-31-p0066","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"66","seq":65,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts is of the view that the measures taken in this\nregard should, above all, support the rebuilding of communities, while providing victims\nwith the legal aid that they need in order to effectively assert their rights before the courts.\n3. The issue of disarmament"},{"id":"a-hrc-41-31-p0067","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"67","seq":66,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"As mentioned above, a disarmament process involving the Kamuina Nsapu militia\nwas initiated in the days following the forum for peace, reconciliation and development in\nKasai that was held in September 2017. The comments of the team of international experts\non this operation, which has been suspended for several weeks, are as follows."},{"id":"a-hrc-41-31-p0068","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"68","seq":67,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"In view of the failures observed in the east of the Democratic Republic of the\nCongo, the team of international experts considers that the disarmament process initiated in\nKasai should not be based on the traditional approach of demobilization, disarmament and\nreintegration, whereby former militia members and combatants are routinely integrated into\nthe regular defence and security forces. Instead, disarmament should be an integral part of\nthe reintegration and reconciliation process and emphasis should be placed on integrating\ncombatants into their respective communities. It also seems logical that significantly\nreducing the military presence and shutting down the zone of operations would help to\nsupport and encourage the disarmament of the militias.\n4. The socioeconomic situation"},{"id":"a-hrc-41-31-p0069","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"69","seq":68,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"Many of the recommendations made during the workshop in Kananga relate to the\nsocioeconomic situation in the Kasai region. Participants suggested, for example,\ndeveloping socioeconomic programmes to combat chronic youth unemployment and to\nsupport the economic integration of communities; launching construction projects where\nyoung persons could be employed to rebuild roads and tracks in Kasai; and renovating\npublic buildings, such as the schools and health centres that were the targets of widespread\ndestruction and looting during the conflict."},{"id":"a-hrc-41-31-p0070","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"70","seq":69,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"As the previous team of international experts mentioned in its report, the violence\nthat erupted in Kasai assumed the proportions that it did because the local communities are\nsuffering from extreme poverty, partly as a result of being abandoned by the central\nauthorities and partly because the region of Kasai is virtually inaccessible by road or rail.\nThese circumstances make it impossible for the region of Kasai, as a whole, to maintain\nregular trade and economic relations with the rest of the country, even though it has many\npotential sources of wealth."},{"id":"a-hrc-41-31-p0071","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"71","seq":70,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts believes that it is urgently necessary to adopt a real\nemergency plan for the development of the Kasai region in order to ensure that its economy\nand agriculture are sustainable and capable of reducing long-term unemployment among\nyoung persons, bearing in mind that such persons made up a large proportion of the militias\nthat were involved in the violence. This will require large-scale investment in\ninfrastructure, including roads, railways and access to electricity and water. The\nresponsibility for this pressing task must be shouldered primarily by the Government,\nwhich could be assisted in its efforts by donors.\n48 Presentation by Jos�phine Bitota, professor and chancellor of the University of Kasai Central.\n49 Ibid."},{"id":"a-hrc-41-31-p0072","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"72","seq":71,"section":"VI. Conclusions and recommendations","text":"The current lull in the violence in Kasai is fragile and the situation must still be\nmonitored closely. The positive impact of the political transition on the security\nsituation in Kasai must be consolidated by a relentless fight against impunity, coupled\nwith efforts to achieve reconciliation and to rebuild the economy in the Kasai region.\nOtherwise, the window of opportunity that remains open in Kasai is likely to close\nrapidly and to prove fruitless."},{"id":"a-hrc-41-31-p0073","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"73","seq":72,"section":"VI. Conclusions and recommendations","text":"As regards the fight against impunity, the investigation and prosecution\nstrategy must be structured in such a way as to cover all the types of human rights\nviolations that characterized the crisis in Kasai. The strategy must also make it\npossible to establish the historical truth and to work towards transitional justice and\nreconciliation."},{"id":"a-hrc-41-31-p0074","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"74","seq":73,"section":"VI. Conclusions and recommendations","text":"Although there is an investigation and prosecution strategy in place and several\ncases of violence are being investigated by the military prosecutors' offices in Kasai,\nspecifically those in Kananga and Tshikapa, the team of international experts finds it\nregrettable that these cases do not cover in a balanced way the full range of\nperpetrators who were involved. Moreover, the cases do not reflect the full range of\ncrimes against humanity and war crimes that were committed during the crisis in\nKasai. In particular, cases should be selected in such a way as to take into account the\nethnic persecution that took place, the scale of the sexual violence, the crimes\ncommitted against children, the use of beheading and the burning down of countless\npublic buildings and dwellings, so that these events are encompassed by the\nproceedings as a whole. With that in mind, it is important that the competent\nauthorities adopt a much broader strategy of investigation and prosecution, otherwise\nthe efforts to combat impunity in Kasai will be futile and will not help to achieve\neffective reconciliation between communities."},{"id":"a-hrc-41-31-p0075","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"75","seq":74,"section":"VI. Conclusions and recommendations","text":"The team of international experts considers that the military justice authorities\nrequire significant human, financial and logistical resources if they are to effectively\ncombat impunity in Kasai. It notes, however, that the resources made available by the\nState are utterly inadequate and that the local judicial authorities are overly reliant\non external partners, including MONUSCO. Since the latter is set to withdraw from\nthe country, the team urges the Government to put in place an independent strategy\nfor funding the efforts of the military and civil justice authorities to prevent and\npunish serious crimes. For the time being, additional resources and personnel should\nbe deployed to the military prosecutors' offices in Kasai in order to expedite\nproceedings and ensure that judgments are handed down within a reasonable time\nframe."},{"id":"a-hrc-41-31-p0076","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"76","seq":75,"section":"VI. Conclusions and recommendations","text":"The team of international experts acknowledges the efforts that have already\nbeen made by the Government to reconcile the communities of Kasai, including the\nholding of a forum for peace, reconciliation and development in September 2017. The\nteam considers that these efforts need to be supported by specific initiatives that set in\nmotion a culturally appropriate and legally acceptable process of reconciliation\nbetween the communities concerned. This process, which should be developed in\ncooperation with academics, traditionalists and researchers, should draw upon\npositive examples from the past and should rule out the possibility of a general pardon\nfor those who committed crimes against humanity and war crimes in Kasai."},{"id":"a-hrc-41-31-p0077","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"77","seq":76,"section":"VI. Conclusions and recommendations","text":"Since the current crisis stemmed from a conflict that was linked to traditional\nleadership, it is important to review the rules and practices relating to State\nsupervision of the exercise of customary power. In addition, given the criticism\nlevelled at the State itself by a sector of the population, it is necessary to reassess the\nrelationship and the policies of communication between the administrative authorities\nand the defence and security forces, on the one hand, and the population, on the other\nhand, taking into account the sense of abandonment in Kasai."},{"id":"a-hrc-41-31-p0078","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"78","seq":77,"section":"VI. Conclusions and recommendations","text":"The team of international experts believes that the efforts made to combat\nimpunity and to achieve reconciliation will not produce tangible and satisfactory\nresults unless the socioeconomic dimension of the conflict in Kasai is taken into\nconsideration. The vast majority of inhabitants live in a state of extreme poverty even\nthough the region is brimming with potential wealth. It is therefore urgently necessary\nto take robust measures to address this discrepancy. In particular, the team considers\nthat the exploitation of mineral resources in the Kasai region could be used to finance,\namong other things, the rebuilding of infrastructure, access to water and electricity\nfor all, and the revival of a sound economy and sustainable agriculture, in the\nframework of a real emergency plan for the development of Kasai, with the support of\nthe international community and the diaspora."},{"id":"a-hrc-41-31-p0079","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"79","seq":78,"section":"VI. Conclusions and recommendations","text":"The team of international experts considers that, in order to emerge from the\ncrisis in Kasai, it is essential to step up efforts to combat impunity and to speed up the\nprocess of community reconciliation and the establishment of an inclusive transitional\njustice mechanism that is aimed at establishing the truth, identifying the root causes of\nthe crisis and providing redress to victims."},{"id":"a-hrc-41-31-p0080","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"80","seq":79,"section":"VI. Conclusions and recommendations","text":"The team of international experts recommends that the authorities of the\nDemocratic Republic of the Congo take the following steps:\n(a) Work to secure the immediate release of the women and children who\nare still being held captive by the Bana Mura militia in Kamonia territory (Kasai\nProvince);\n(b) Adopt an investigation and prosecution strategy that encompasses all\ncategories of perpetrators of serious crimes in Kasai, regardless of their status or\nposition, their motive and the place where the crime was committed;\n(c) Allocate sufficient financial resources and the personnel, equipment and\nlogistical resources that are necessary to enable the military justice authorities in\nKasai to investigate and try cases without undue delay;\n(d) Consider the possibility of recruiting female staff to work for the\nmilitary justice authorities in Kasai, and overcome the shortage of staff by making\ngreater use of the civil justice system and the pool of talent offered by the bar\nassociation;\n(e) Ensure that specialized personnel are assigned the specific task of\ninvestigating and prosecuting crimes of sexual violence and crimes involving minors;\n(f) Enforce the application of judicial protection measures for victims of\ncrimes of sexual violence and child victims and encourage these persons to lodge\ncomplaints by providing them with effective legal assistance;\n(g) Set up a reparation fund in order to assist victims individually and to\nspeed up the rebuilding of communities affected by the violence;\n(h) Ensure that persons convicted of crimes are given appropriate sentences\nand are prohibited from joining or remaining in the defence and security forces;\n(i) Ensure that, in cases where minors are to be tried, investigators are\ngiven specialized training and that accused minors are tried in specialized chambers\nwith appropriate procedures in place;\n(j) Revitalize community reconciliation efforts in Kasai without delay and\nestablish an inclusive and appropriate transitional justice mechanism;\n(k) Launch audiovisual information programmes in order to reduce the\nethnic tensions that the crisis may have caused and promote dialogue and\nreconciliation between communities;\n(l) Ensure that the disarmament process that is under way applies to all\nmilitias without distinction and helps to facilitate reconciliation by ensuring the\neffective return of militia members to their respective communities;\n(m) Organize a conference on Kasai, with the support of the international\ncommunity and the diaspora, in order to mobilize resources for major projects\nrelating to road and rail communications, water and electricity distribution and\nagricultural development, with a view to reducing long-term unemployment among\nyoung persons in the region and paving the way for the economic recovery of Kasai\nwithin the Democratic Republic of the Congo."},{"id":"a-hrc-41-31-p0081","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"81","seq":80,"section":"VI. Conclusions and recommendations","text":"The team of international experts recommends that MONUSCO, the United\nNations system and the Peacebuilding Fund should, through their various projects\nand programmes, provide concrete support to the competent authorities in the fight\nagainst impunity, with a particular focus on strengthening the autonomy of national\ninstitutions and promoting reconciliation and transitional justice."},{"id":"a-hrc-41-31-p0082","rec_id":"rectHw5BCJkNOy2Tl","symbol":"A/HRC/41/31","n":"82","seq":81,"section":"VI. Conclusions and recommendations","text":"The team of international experts recommends that the Office of the United\nNations High Commissioner for Human Rights, MONUSCO and the United Nations\nsystem in general should remain actively involved in Kasai by providing technical\nsupport for all measures taken to combat impunity and to reconcile communities in\nKasai, including those relating to disarmament and community reintegration."},{"id":"a-hrc-45-50-p0001","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"1","seq":0,"section":"I. Introduction","text":"Taking note of the observation by the team of international experts in its previous\nreport that the current lull in the violence in Kasai is fragile, ethnic tensions remain high\nand the situation must still be monitored closely, (A/HRC/41/31, paras. 19 and 72), the\nHuman Rights Council, in its resolution 41/26 of 12 July 2019, renewed the mandate of the\nteam of international experts, tasking it with observing, assessing and assisting the efforts\nof the Democratic Republic of the Congo in implementing the recommendations contained\nin the report of the previous team of international experts and instructing it to submit a final\nreport to the Council at its forty-fifth session."},{"id":"a-hrc-45-50-p0002","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"2","seq":1,"section":"I. Introduction","text":"In order to facilitate its performance of this mandate, the Human Rights Council\nrequested the United Nations High Commissioner for Human Rights to provide, at the\nrequest of the authorities, technical assistance, including the necessary forensic expertise, to\nthe Government of the Democratic Republic of the Congo in order to support the judicial\nauthorities in their investigations into allegations of human rights violations and abuses in\nthe Kasai region and other regions of the country, with a view to bringing those responsible\nto justice."},{"id":"a-hrc-45-50-p0003","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"3","seq":2,"section":"I. Introduction","text":"The international experts, Bacre Waly Ndiaye, of Senegal, as Chair of the team, and\nSheila B. Keetharuth, of Mauritius, as a team member, were appointed for this purpose by\nthe Human Rights Council. In carrying out its mandate, the team of international experts\nwas supported by a secretariat based in Kananga, composed of three international members\nand one national member. The team of international experts proceeded to draw up its\nworkplan and to plan its field visits. Of the six planned visits, the team carried out only two:\nfrom 7 to 16 November 2019 and from 12 to 28 January 2020. The team of international\nexperts was unable to implement its workplan as foreseen owing to the coronavirus\n(COVID-19) pandemic."},{"id":"a-hrc-45-50-p0004","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"4","seq":3,"section":"I. Introduction","text":"However, on 17 June 2020, both international experts took part in the Human Rights\nCouncil's interactive dialogue on the Democratic Republic of the Congo, participating by\nvideoconference from their respective countries because of the COVID-19 restrictions in\nforce during the Council's forty-third session. At that time, they reported on the progress of\ntheir work and shared some preliminary findings."},{"id":"a-hrc-45-50-p0005","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"5","seq":4,"section":"I. Introduction","text":"The present report, submitted to the Human Rights Council at its forty-fifth session,\ncontains the conclusions and recommendations of the team of international experts."},{"id":"a-hrc-45-50-p0006","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"6","seq":5,"section":"II. Mandate","text":"To carry out its new mandate, the team of international experts adopted a three-\npronged approach, namely: (a) monitoring judicial cases in the context of the fight against\nimpunity; (b) monitoring the reconciliation, transitional justice and reparation process; and\n(c) providing institutional support for the State bodies responsible for implementing\nrecommendations."},{"id":"a-hrc-45-50-p0007","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"7","seq":6,"section":"II. Mandate","text":"This mandate has been taken up not only in a context where the World Bank and\nseveral international non-governmental organizations (NGOs) are launching humanitarian\nand development projects in the Kasai region, but also in a period of transition, where the\nUnited Nations Organization Stabilization Mission in the Democratic Republic of the\nCongo (MONUSCO) is gradually arranging for its withdrawal from the country. In view of\nthe presence of multiple actors in the Kasai region, it goes without saying that the mandate\nof the team of international experts will have added value only if it is seen as a catalyst and\nguide for the social and judicial policies undertaken in the region. Thus, during each of the\nvisits of the team of international experts, meetings with the country's highest authorities\nplay a decisive role in facilitating and accelerating the implementation of activities on the\nground. Indeed, in addition to the activities carried out by MONUSCO and the United\nNations Joint Human Rights Office, each visit to the Democratic Republic of the Congo by\nthe team of international experts is an opportunity to assess the Government's efforts to\nprosecute the perpetrators of serious crimes committed during the crisis linked to the\nKamuina Nsapu militia in the Kasai region and also to question the Government on\nobstacles observed in the fight against impunity and the promotion of reconciliation and\nsocial reintegration, transitional justice and reparations."},{"id":"a-hrc-45-50-p0008","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"8","seq":7,"section":"II. Mandate","text":"Such visits have also provided an opportunity for advocacy, which most of the time,\nwith every visit by the team of international experts, has facilitated progress. They are thus\na tool for political and legal support for the activities carried out by the Government,\nMONUSCO, the United Nations Joint Human Rights Office and others operating in the\nKasai region."},{"id":"a-hrc-45-50-p0009","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"9","seq":8,"section":"III. Cooperation between the team of international experts and","text":"The team of international experts appreciated the spirit of cooperation and openness\nthat marked its exchanges with the national and provincial authorities of the Democratic\nRepublic of the Congo over the course of its missions. This cooperation was reflected in\nseveral actions, including the facilitation of the team's two visits to the country through the\nissuance of courtesy visas and the organization of various meetings at the national and\nprovincial levels and of working sessions organized with State services. In addition, the\nmembers of the secretariat based in Kananga had their work facilitated in the same way at\nthe provincial and national levels."},{"id":"a-hrc-45-50-p0010","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"10","seq":9,"section":"III. Cooperation between the team of international experts and","text":"The authorities of the Democratic Republic of the Congo were able to fully\nappreciate the contribution made by the team of international experts to the Kasai peace\nprocess. Thanks to this, the Minister for Human Rights expressed the wish, at the meeting\nof the Task Force on 20 January 2020, that the mandate of the team of international experts\nwould eventually be extended to the other provinces affected by armed conflict, specifically\nTanganyika, Nord-Kivu, Sud-Kivu, Ituri and Mai-Ndombe."},{"id":"a-hrc-45-50-p0011","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"11","seq":10,"section":"IV. Current situation in the Kasai region","text":"The team of international experts has noted a relative lull in the violence in the Kasai\nregion; the crisis related to the Kamuina Nsapu militia, in its original form, has all but\ndisappeared. However, there has been an increase in crime, mainly attributable to acts by\nsome members of the security forces, the fact that ex-militiamen have not been fully\ndisarmed and the lack of a social and economic reintegration policy for those who have\nsurrendered their weapons. Recently, there have been reports in the commune of Nganza\nand around the Kananga airport that former Kamuina Nsapu militiamen are reorganizing.\nThis is alarming and calls for urgent measures to be taken to prevent the resurgence of\nmilitias and their redeployment in political, land or inter-communal conflicts."},{"id":"a-hrc-45-50-p0012","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"12","seq":11,"section":"IV. Current situation in the Kasai region","text":"In addition, the United Nations Joint Human Rights Office has documented several\ncases of rape and sexual assault, mostly committed by armed men and certain elements of\nthe Armed Forces of the Democratic Republic of the Congo or the security forces. The\nimpunity enjoyed by the perpetrators of these acts only makes the situation worse. There is\nthus an urgent need for the authorities responsible for security and justice to firmly combat\nthis phenomenon."},{"id":"a-hrc-45-50-p0013","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"13","seq":12,"section":"IV. Current situation in the Kasai region","text":"Socioeconomically, the situation in the Kasai region has hardly improved at all.\nPoverty is still pervasive and the cost of living has worsened as a result of the depreciation\nof the Congolese franc against the United States dollar, which has led to an increase in the\nprice of basic foodstuffs."},{"id":"a-hrc-45-50-p0014","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"14","seq":13,"section":"IV. Current situation in the Kasai region","text":"The situation is made worse by the fact that the Kasai region is heavily dependent on\nimports from Angola. With the closure of the borders under measures taken by the\nCongolese and Angolan authorities to combat the spread of COVID-19, several basic\ncommodities are unavailable in the provinces of Kasai and Kasai Central; those that are still\navailable are very expensive and thus beyond the means of the vast majority of people."},{"id":"a-hrc-45-50-p0015","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"15","seq":14,"section":"IV. Current situation in the Kasai region","text":"On the political front, the Kasai region is facing a series of crises marked by\ninstitutional changes and movements advancing political demands."},{"id":"a-hrc-45-50-p0016","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"16","seq":15,"section":"IV. Current situation in the Kasai region","text":"In Kasai Central Province, the Governor was removed from office on 24 June 2020\nfollowing a motion of censure put forward by a group of deputies. The same steps were\nundertaken in Kasai Province, but with no result."},{"id":"a-hrc-45-50-p0017","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"17","seq":16,"section":"IV. Current situation in the Kasai region","text":"There have also been peaceful political marches by protest movements in the region.\nFor example, on 7 and 9 July 2020, public demonstrations were organized by the Lutte pour\nle changement and Filimbi citizens' movements and the Union pour la d�mocratie et le\nprogr�s social political party in Kananga (Kasai Central Province), Tshikapa (Kasai\nProvince) and Mbuji-Mayi (Kasai Oriental Province) to protest against the \"confirmation\"\nof the candidate proposed by the National Assembly on 2 July 2020 as chair of the\nIndependent National Electoral Commission. The demonstrators also called for the reform\nof the national electoral system, which they considered \"non-negotiable\", in the next\nelectoral cycle."},{"id":"a-hrc-45-50-p0018","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"18","seq":17,"section":"IV. Current situation in the Kasai region","text":"The political situation in the Kasai region is influenced by divisions within the\ngoverning coalition that currently rules the country."},{"id":"a-hrc-45-50-p0019","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"19","seq":18,"section":"IV. Current situation in the Kasai region","text":"On the health front, the measures taken by the Congolese authorities to prevent the\nspread of COVID-19 from Kinshasa or the eastern provinces into the country's interior\nhave met with some success, and no cases had been reported in the Kasai region through\nthe end of July 2020, when emergency measures were lifted in the country. At the time of\nwriting, there were two confirmed cases of COVID-19 in Kasai Province, one in Tshikapa\nand one confirmed case in Kasai Central Province."},{"id":"a-hrc-45-50-p0020","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"20","seq":19,"section":"V. Monitoring, evaluation and support for implementation by","text":"The recommendations contained in the report of the previous team of international\nexperts (A/HRC/38/31) can be divided into two main groups, namely, those for combating\nimpunity and those for supporting reconciliation efforts and transitional justice."},{"id":"a-hrc-45-50-p0021","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"21","seq":20,"section":"V. Monitoring, evaluation and support for implementation by","text":"In its previous report, the team of international experts referred to the State's\nestablishment of a working group to implement the recommendations. As a reminder,\nresolution 41/26 of the Human Rights Council encouraged the Government to ensure that\nthe working group would meet as many times as necessary in order to regularly assess the\nprogress made in implementing the recommendations, improve the coordination between\nthe administrative authorities and stakeholders and recommend appropriate measures to the\nGovernment."},{"id":"a-hrc-45-50-p0022","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"22","seq":21,"section":"V. Monitoring, evaluation and support for implementation by","text":"In its interactions with the national authorities, the team of international experts\nsupported the Government's efforts to facilitate the working group's action by encouraging\nthe resumption of meetings. Thus, on 20 January 2020, the working group was able to hold\nits first meeting in the presence of members of the Government, the technical and judicial\nbodies involved in the implementation of the recommendations and the team of\ninternational experts."},{"id":"a-hrc-45-50-p0023","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"23","seq":22,"section":"V. Monitoring, evaluation and support for implementation by","text":"To support the working group, the team of international experts, through its\nsecretariat, drew up a suggested workplan to help the working group with the methodology\nand planning of its activities. The team of international experts proposed that the working\ngroup should meet at least once every two months to evaluate and follow up on its activities."},{"id":"a-hrc-45-50-p0024","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"24","seq":23,"section":"V. Monitoring, evaluation and support for implementation by","text":"Owing to the COVID-19 pandemic and the restrictive measures taken by the\nGovernment in response to it, the working group was no longer able to formally meet to\ncontinue its activities. However, from a meeting with the Minister for Human Rights, it was\nascertained that the Minister had been able to hold meetings with, inter alia, the Chief\nMilitary Prosecutor and the deputy minister of justice to assess the implementation of the\nitems falling within their competence. The team of international experts did not, however,\nreceive any notes on those assessments. The team recommends that a plan for the\nimplementation of the recommendations be drawn up with a timetable and allocation of the\ncorresponding budgetary resources, which would enable the working group to carry out its\nmandate effectively."},{"id":"a-hrc-45-50-p0025","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"25","seq":24,"section":"V. Monitoring, evaluation and support for implementation by","text":"The situation described above notwithstanding, the team of international experts was\nable to continue its work by supporting the Government's efforts in combating impunity\nand providing for reconciliation and transitional justice."},{"id":"a-hrc-45-50-p0026","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"26","seq":25,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"Following the recommendation in the previous report of the team of international\nexperts to adopt an investigation and prosecution strategy that encompasses all categories\nof perpetrators of serious crimes in Kasai (A/HRC/41/31, para. 80 (b)), 16 cases had been\nidentified as priorities by the senior military prosecutor's office at the military court of the\nformer Kasai Occidental Province. These cases concern the following localities: Tshisuku,\nNganza, Katoka, Diboko, Malenga, Tshikapa, Mutshima, Maswika, Nkoto, Tshinyembe,\nTshimbulu, Kabeya-Madi, Luebo and Kamonia."},{"id":"a-hrc-45-50-p0027","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"27","seq":26,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts notes that, despite the priority given to these 16\ncases, which requires that they be dealt with expeditiously, none has had its investigation\ncompleted and been referred to a trial court."},{"id":"a-hrc-45-50-p0028","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"28","seq":27,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"During each of its visits to the Democratic Republic of the Congo, the team of\ninternational experts held working meetings with both the Chief Military Prosecutor at the\nMilitary High Court and the senior military prosecutor at the military court of the former\nKasai Occidental Province. The team noted a number of circumstances slowing the judicial\ninvestigation of the cases, including: (a) difficulties in obtaining the lifting of the\nparliamentary immunity of a member of parliament suspected of serious human rights\nviolations; (b) a delay in the execution of warrants; and (c) procedural difficulties related to\npersonal jurisdiction which have arisen in investigations of cases involving military officers\nwith the rank of general."},{"id":"a-hrc-45-50-p0029","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"29","seq":28,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts notes, however, that with the support of\nMONUSCO and the United Nations Joint Human Rights Office, some progress has been\nmade in prosecutions, with the help of the technical assistance team.\n(b) Prosecution and investigation of court cases"},{"id":"a-hrc-45-50-p0030","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"30","seq":29,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts welcomes the arrest on 29 May 2020 by the\ngarrison military prosecutor's office in Kananga, in Kasai Central Province, of Tr�sor\nMputu Kankonde, one of the leaders of the Kamuina Nsapu militia wanted by the military\njustice system for several cases of human rights violations in the territory of Dibaya. This\nmilitia leader is also suspected of having participated in the murder of Zaida Catal�n and\nMichael Sharp, members of the Group of Experts on the Democratic Republic of the Congo\nestablished pursuant to United Nations Security Council resolution 1533 (2004), who were\nkilled on 12 March 2017."},{"id":"a-hrc-45-50-p0031","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"31","seq":30,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts notes with satisfaction that in February 2020, a\nteam of military judges and judicial police officers interviewed nearly 803 victims and\nwitnesses in the commune of Nganza, in Kananga. After this mission, information on the\nsituation of the persons in question both prior to and after their death was compiled. It was\nthus possible to identify 620 victims of summary and extrajudicial executions committed\nbetween 28 and 30 March 2017 and implicating the defence and security forces. Additional\ninformation on these victims was also collected to facilitate their identification by their\nfamilies after exhumation."},{"id":"a-hrc-45-50-p0032","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"32","seq":31,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts notes, however, that despite the recommendations\nmade in its previous reports, the women abducted by the Bana Mura militia have still not\nbeen freed, and they remain in captivity."},{"id":"a-hrc-45-50-p0033","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"33","seq":32,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"In November 2019, a group of these women was able to escape. According to their\naccounts, many others are still being held as sex slaves. The team of international experts\nregrets that the judicial authorities and security forces did not take this opportunity to find\nthe hostage-takers and free the women still held in captivity."},{"id":"a-hrc-45-50-p0034","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"34","seq":33,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts notes that, despite previous recommendations, the\nrecruitment of women into the military justice system, including their deployment to the\nKasai region, has not yet taken place. Their presence would clearly be advantageous,\nparticularly in building the confidence of women and girl victims in the context of current\ninvestigations and inquiries into cases, especially those involving rape and sexual violence."},{"id":"a-hrc-45-50-p0035","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"35","seq":34,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts is also concerned about the obstruction of the\nlifting of the parliamentary immunity of a legislator from the province of Kasai who is\nsuspected of serious human rights violations. It notes that despite the fact that the senior\nmilitary prosecutor at the military court of the former Kasai Occidental has claimed that\nefforts have been made to charge the suspect, to date, no judicial action has been taken\nagainst him. The team of international experts therefore urges the Kasai Provincial\nAssembly to cooperate fully with the military justice system so as to enable it to carry out\nits tasks of investigating and prosecuting allegations of serious crimes against one of the\nAssembly's members."},{"id":"a-hrc-45-50-p0036","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"36","seq":35,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts commends the efforts undertaken by the senior\nmilitary prosecutor's office at the military court of the former Kasai Occidental, with the\nsupport of the Chief Military Prosecutor, in the execution of warrants. It takes note of the\narrest in July 2020 of certain officers and non-commissioned officers of the Armed Forces\nof the Democratic Republic of the Congo suspected in particular in connection with the\nkillings in Nganza and Tshimbulu."},{"id":"a-hrc-45-50-p0037","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"37","seq":36,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team notes, however, that most of the cases for which these investigations have\nbeen carried out have been referred to the Chief Military Prosecutor's office, owing to the\nranks of the officers involved in these cases. The team hopes that the Chief Military\nProsecutor's office will speed up the processing of these cases, which have been stalled for\nseveral years."},{"id":"a-hrc-45-50-p0038","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"38","seq":37,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"With regard to the trial of the alleged killers of Zaida Catal�n and Michael Sharp,\nthe team notes that the trial is continuing, although it is apparently far from over. The trial\ninitially held at the Kananga garrison military court has been transferred to the military\ncourt of the former Kasai Occidental after charges were filed against a colonel of the\nArmed Forces of the Democratic Republic of the Congo. The case involving the\ndisappearance, in the same event, of the victims' four Congolese colleagues is still at the\npreliminary investigation stage. In January 2020 the Chief Military Prosecutor at the\nMilitary High Court said that it had not yet been formally established that the colleagues\nhad died."},{"id":"a-hrc-45-50-p0039","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"39","seq":38,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts is concerned about these proceedings, which are\nmoving along at two different speeds. When the two judicial procedures eventually come\ntogether, which is virtually inevitable to ensure the proper administration of justice, the trial\nalready under way for the murder of the two Security Council experts is very likely to be\nprolonged indefinitely."},{"id":"a-hrc-45-50-p0040","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"40","seq":39,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts emphasizes that the fight against impunity in the\nKasai region must go beyond the prosecution of those responsible for the murder of Zaida\nCatal�n, Michael Sharp and those who accompanied them."},{"id":"a-hrc-45-50-p0041","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"41","seq":40,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"In view of the slow pace in the processing of cases related to the crisis involving the\nKamuina Nsapu militia, the team of international experts doubts that, with its current\nresources, the Congolese justice system is able to work effectively and that the proceedings\nit has initiated can meet the need for justice arising from this crisis, even in cases chosen for\ntheir symbolic significance. This concern is shared by civil society in Kasai, in particular\nthe Soci�t� congolaise pour l'�tat de droit, an NGO represented by the president of the Bar\nAssociation of Kasai Central, who in a statement dated 16 July 2020 deplored the\njudiciary's lack of will to support the rule of law in the Kasai crisis. He also recommended\nthat the President of the Republic should refer the situation in Kasai to the International\nCriminal Court or, failing that, should establish a special criminal court for Kasai.\n2. Problem of the resources required to facilitate the administration of justice in the\nKasai region"},{"id":"a-hrc-45-50-p0042","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"42","seq":41,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"In its previous report, the team of international experts had noted the link between\nthe fight against impunity and the deployment of resources, indicating that a genuine fight\nagainst impunity in the Kasai region required significant human, financial and logistical\nresources for the military justice system (A/HRC/41/31, para. 75)."},{"id":"a-hrc-45-50-p0043","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"43","seq":42,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"In January 2020, when the team of international experts met with the Minister of\nJustice of Kasai Central Province, the Minister presented all the challenges facing the\njustice system in general, and the military and civilian justice systems in particular.\nSpecifically cited were the challenges they faced owing to the poor functioning of the\ncourts in the territories of the province other than Kananga, where the Minister claimed that\nthe courts were operational. The Minister also referred to obstacles related to the lack of\njudges and the high cost of travel to process certain cases in the territories, as well as the\nproblems of prison overcrowding, the lack of prison facilities and the dilapidated state of\nexisting prisons, which led to numerous escapes."},{"id":"a-hrc-45-50-p0044","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"44","seq":43,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"Lastly, the team of international experts notes that the performance of military\njustice activities in the Kasai region is heavily dependent on international organizations, in\nparticular MONUSCO, for logistical and financial support."},{"id":"a-hrc-45-50-p0045","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"45","seq":44,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"In the area of capacity-building and support, the team of international experts\nwelcomes the deployment by the Office of the United Nations High Commissioner for\nHuman Rights of a technical assistance team which is providing valuable support to the\nCongolese military justice system in the investigation of cases of international crimes\ncommitted during the Kasai crisis."},{"id":"a-hrc-45-50-p0046","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"46","seq":45,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts also notes with satisfaction the contribution of the\nNational Human Rights Commission and international NGOs in the training of judicial\npersonnel and court officials in the area of international crimes."},{"id":"a-hrc-45-50-p0047","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"47","seq":46,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"In October 2019, the National Human Rights Commission, in partnership with\nTRIAL International and with the financial support of the United Nations Development\nProgramme, organized training on the documentation of international crimes and basic\nhuman rights concepts for human rights NGOs in Kananga and in the territories of\nKazumba, Dibaya and Luiza."},{"id":"a-hrc-45-50-p0048","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"48","seq":47,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"In February 2020, TRIAL International conducted a training workshop in Kananga\non the investigation and prosecution of serious crimes for civilian and military judges,\nlawyers, the national police and health-care staff of Kananga Provincial Hospital, and also\nfor NGOs working to combat violence against women."},{"id":"a-hrc-45-50-p0049","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"49","seq":48,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"TRIAL International also provided financial support for mobile court hearings to be\nheld from 10 to 17 July 2020 in Tshikapa by the military court of the former Kasai\nOccidental, specifically ensuring that women victims of sexual violence and their lawyers\nwould be heard.\n3. Support for victims and witnesses"},{"id":"a-hrc-45-50-p0050","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"50","seq":49,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts notes that: (a) the victims � particularly those in\nthe communes of Nganza, Mulombodi, Tshilumba, Katoka, Tubuluku and Meteo (in\nKananga) and in the territories of Tshimbulu and Tshisuku � have established a hub of\nassociations; (b) some of these victims were able to obtain death certificates from the\nKananga city hall; and (c) other victims, on the other hand, have not able to do so, owing to\nthe suspension of the issuance of such certificates. The team of international experts\ntherefore urges the administrative and judicial authorities to facilitate the issuance of death\ncertificates to make it possible for such persons to take legal action. In addition, the team\ntakes note of the complaint lodged on 3 August 2020 by a group of victims from the\ncommune of Nganza with the senior military prosecutor's office of the military court of the\nformer Kasai Occidental against members of the Armed Forces of the Democratic Republic\nof the Congo involved in handling the Kamuina Nsapu militia crisis and against the\nMinister of the Interior who was in office at the time of the events."},{"id":"a-hrc-45-50-p0051","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"51","seq":50,"section":"A. Monitoring of accountability for the events in the Kasai region","text":"The team of international experts welcomes the Government's idea of establishing a\nnational fund for victims of serious human rights violations. Such a fund will no doubt\ninitially relieve the suffering of victims while they await compensation resulting from court\ndecisions. The team of international experts would therefore like to see prompt\nimplementation of this project."},{"id":"a-hrc-45-50-p0052","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"52","seq":51,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"In its previous report, the team of international experts recommended that the\nGovernment should revitalize community reconciliation efforts in Kasai without delay and\nestablish an inclusive and appropriate transitional justice mechanism (A/HRC/41/31, para.\n80 (j))."},{"id":"a-hrc-45-50-p0053","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"53","seq":52,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts notes with satisfaction that the Government plans\nto set up a national council for conflict prevention and transformation. It notes that this\ngovernment initiative comes after community consultations were held in the province of\nKasai Central as part of the implementation of the joint peace, justice, reconciliation and\nreconstruction programme in that province."},{"id":"a-hrc-45-50-p0054","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"54","seq":53,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts also notes that, in addition to Kasai Central, there\nare plans for similar transitional justice mechanisms in Kasai and Tanganyika provinces. In\nthis regard it is concerned about the question of how the provincial, regional and national\ndimensions of transitional justice, truth and reconciliation projects fit together in the\nDemocratic Republic of the Congo."},{"id":"a-hrc-45-50-p0055","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"55","seq":54,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"This reconciliation process, which does not cover the entire Kasai region,\nnonetheless affected by the same crisis, unfortunately is taking place in a context where the\nsecurity and humanitarian situation in the region is still alarming.\n1. Community consultations in Kasai Central Province"},{"id":"a-hrc-45-50-p0056","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"56","seq":55,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts welcomes the organization of the community\nconsultations that took place in Kasai Central Province from 15 to 23 August 2019. These\ninclusive consultations made it possible to hear the views of local populations affected by\nthe violence regarding the needs for justice, reparation, reconciliation, truth, peaceful\ncoexistence and the prevention of further conflict."},{"id":"a-hrc-45-50-p0057","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"57","seq":56,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"During the ceremony for the formal presentation of the consultations' report, the\nprovincial government committed itself to fully implementing the recommendations issued\nas a result of the consultations. The team of international experts is concerned about the fact\nthat, to its knowledge, no action has been taken by the Government of the Democratic\nRepublic of the Congo to take on board the results of the community consultations. In\naddition, it is concerned that the implementation of the recommendations resulting from the\nconsultations is being delayed owing, inter alia, to the dismissal of the Governor of Kasai\nCentral Province."},{"id":"a-hrc-45-50-p0058","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"58","seq":57,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts also notes that on 11 June 2020 the provincial\nMinister of Justice issued an order appointing the members of a drafting committee for the\ndraft provincial decree on the establishment and operation of the provincial truth, justice\nand reconciliation commission.\n2. Question of how the provincial, regional and national dimensions of the truth and\nreconciliation commissions in the Democratic Republic of the Congo fit together"},{"id":"a-hrc-45-50-p0059","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"59","seq":58,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"At various meetings held by the team of international experts with the national\nauthorities, the authorities welcomed the pilot project on transitional justice in Kasai\nCentral Province and expressed the hope that the experiment would be extended to other\nprovinces that have had social conflicts, in particular Tanganyika, Nord-Kivu, Sud-Kivu,\nIturi and Mai-Ndombe."},{"id":"a-hrc-45-50-p0060","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"60","seq":59,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"However, the team of international experts notes that there has been a new approach\nto the transitional justice process. According to the Ministry of Human Rights, transitional\njustice mechanisms must be led by the Government of the Democratic Republic of the\nCongo and not by the provincial authorities, the latter apparently being the case at present\nwith the experiment in Kasai Central. During the interactive dialogue on the Democratic\nRepublic of the Congo, the Minister stated that his country intended \"to revive the Truth\nand Reconciliation Commission, which proved its worth between 2003 and 2006\". During a\ntelephone meeting held on 10 August 2020 with the international experts, the Minister for\nHuman Rights stated that the draft decree on the transitional justice mechanism in the\nDemocratic Republic of the Congo would be adopted very soon."},{"id":"a-hrc-45-50-p0061","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"61","seq":60,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"In the view of the team of international experts, this approach should be given\nsufficient consideration to make it possible to decide on the best way for the provincial,\nregional and national dimensions of transitional justice, truth and reconciliation\nmechanisms to fit together in the Democratic Republic of the Congo. For this reason, the\nteam of international experts had planned to organize a workshop on this subject in April\n2020 in Tshikapa, Kasai Province. The workshop's terms of reference have been drawn up\nand the panellists identified, but as of the time of writing, the COVID-19 pandemic has\nprevented it from being held.\n3. Disarmament and socioeconomic reintegration measures"},{"id":"a-hrc-45-50-p0062","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"62","seq":61,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts notes that the crisis related to the Kamuina Nsapu\nmilitia, in its original form, has all but disappeared. However, with regard to the\nrecommendations in the previous report calling on the Congolese authorities to ensure that\nthe disarmament process under way applied to all militias without distinction\n(A/HRC/41/31, para. 80 (l)), the team of international experts has ascertained that the Bana\nMura and �curie Mbembe militiamen, who are still present in Kasai Province, were never\ndisarmed and that the voluntary disarmament initiatives launched by some militias have not\ncontinued, while those who have laid down their weapons have not benefited from\nsocioeconomic reintegration measures. It is feared that the former militiamen may\nreorganize into armed groups that attack civilians to survive or that they could sell their\nservices for political or economic gain."},{"id":"a-hrc-45-50-p0063","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"63","seq":62,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts reiterates the urgent need to disarm all militiamen\nwithout distinction and to ensure their socioeconomic reintegration.\n4. Socioeconomic and humanitarian situation"},{"id":"a-hrc-45-50-p0064","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"64","seq":63,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"As the team of international experts mentioned in its previous report, the efforts\nmade to combat impunity and to achieve reconciliation will not produce tangible and\nsatisfactory results unless the socioeconomic dimension of the conflict in Kasai is taken\ninto consideration (A/HRC/41/31, para. 78)."},{"id":"a-hrc-45-50-p0065","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"65","seq":64,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"Noting that the overwhelming majority of the population lives in a state of extreme\npoverty despite the fact that the territory is replete with potential sources of wealth, the\nteam of international experts reiterates that strong measures must be taken to address this\nsituation."},{"id":"a-hrc-45-50-p0066","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"66","seq":65,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts also welcomes the 100-day programme launched\nby the President of the Democratic Republic of the Congo, which contains components for\nthe development of the Kasai region. It looks forward to the effective implementation of\nthis programme, which calls in particular for the provision of better access to Sankuru\nProvince and the rehabilitation of schools and the modernization of major trunk roads."},{"id":"a-hrc-45-50-p0067","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"67","seq":66,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts also notes with satisfaction that during its visit, the\nCongolese authorities announced that a project had begun in Kasai Central Province for the\ndevelopment of agriculture, education and health services, with financial support from the\nWorld Bank."},{"id":"a-hrc-45-50-p0068","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"68","seq":67,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts welcomes this cooperation and invites other\ndevelopment actors to follow the lead of the World Bank, while calling on the Government\nto invest more in the Kasai region and to ensure that the exploitation of mining resources\nincludes an appropriate approach to social responsibility."},{"id":"a-hrc-45-50-p0069","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"69","seq":68,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"On the humanitarian front, the team of international experts notes that the situation\nhas hardly improved at all and remains marked by security challenges, in particular related\nto the disarmament of militias and the lack of other initiatives. Furthermore, there is a\nserious humanitarian crisis owing to the massive return of several hundred thousand\nCongolese nationals, most of whom were expelled by the Angolan authorities with the aim\nof preventing the spread of COVID-19 by relieving crowding at prisons and by expelling\nundocumented foreigners."},{"id":"a-hrc-45-50-p0070","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"70","seq":69,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"It is in this context that in April 2020 numerous Congolese citizens were driven out\nat the Kamako border post and at the Kandiadji and Kabungu crossing points, into Kasai\nProvince. Between 27 April and 14 May 2020, at least 1,127 people � including 218\nwomen, 58 boys and 57 girls � were forcibly repatriated by the Angolan police and the\ncountry's migration service. While some were quarantined, quarantine was impossible for\nthose who returned through unofficial border crossings. A climate of mistrust thus\ndeveloped, leading to discrimination and stigmatization. Some of the people who were\nforced to return do not wish to go back to their communities because they are afraid of\nbeing outcasts; others have had their land and property taken away."},{"id":"a-hrc-45-50-p0071","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"71","seq":70,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"According to the United Nations Office for the Coordination of Humanitarian\nAffairs, \"[i]n the first half of 2020, there were several alerts of continuing operations to\nexpel undocumented Congolese from Angola to the provinces of Kasai and Kwango.\nAccording to the Directorate General for Migrations of Kasai Province, 13,686 deportees\nand 764 voluntary returnees crossed various border points on the Angolan border between\nJanuary and June 2020. They thus joined hundreds of thousands of other returnees in the\nprovinces of Kasai, Kasai Central, Kasai Oriental, Lomami and Kwango, where more than\n516,000 people (expelled from Angola, returnees from the Kamuina Nsapu crisis or\nrepatriated persons) were registered in 2019\".1"},{"id":"a-hrc-45-50-p0072","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"72","seq":71,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"This new influx increased the number of displaced persons and further complicated\nan already dire humanitarian situation; persons who had previously been displaced are\nliving in difficult circumstances without any sustainable solutions. This situation has led to\nserious problems, including health issues, as reception infrastructures are either inadequate\nor practically non-existent. In addition to the violence that they have suffered in Angola,\nreturning displaced persons and expelled persons also appear to be subjected to violence\nand extortion in the Democratic Republic of the Congo, by the defence and security forces\nin particular. The humanitarian crisis is an obstacle to reconciliation efforts in this area of\nKasai. It was reported to the team of international experts that, while the wounds have not\nyet had time to heal, the population is now a mishmash of executioners and victims of the\ncrisis that has been raging in Kasai since 2016. In these circumstances, which are\ncomplicated further by the humanitarian crisis, a dialogue of reconciliation may not be a\nrealistic prospect. Resolving the humanitarian crisis at the Angolan border and addressing\nthe situation of displaced persons throughout the Kasai region is therefore a major\nchallenge that must be overcome in order to restore lasting peace in Kasai."},{"id":"a-hrc-45-50-p0073","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"73","seq":72,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"With regard to women, the team of international experts notes that no measures have\nbeen taken specifically for women in the context of management of the humanitarian crisis.\nYet special attention has to be paid to displaced women heads of household and girls,\nowing to their specific vulnerability."},{"id":"a-hrc-45-50-p0074","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"74","seq":73,"section":"B. Reconciliation and transitional justice in the Kasai region","text":"The team of international experts calls on humanitarian organizations to provide\nfurther support to the Congolese authorities to address this situation. It urges the\nGovernments of the Democratic Republic of the Congo and Angola to include the\nhumanitarian dimension and respect for human rights in any expulsion or repatriation\nmeasures."},{"id":"a-hrc-45-50-p0075","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"75","seq":74,"section":"VI. Conclusions and recommendations","text":"The team of international experts welcomes the full cooperation of the\nGovernment and its openness to implementing the recommendations on Kasai."},{"id":"a-hrc-45-50-p0076","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"76","seq":75,"section":"VI. Conclusions and recommendations","text":"The team of international experts reiterates the urgent need to make the fight\nagainst impunity the foundation and the catalyst for a return of the region to peace\nand stability. For this reason, while noting that some militiamen have been prosecuted\nand arrested, it encourages the courts to act just as effectively against all the alleged\nperpetrators of serious human rights violations committed during the Kamuina Nsapu\nmilitia crisis."},{"id":"a-hrc-45-50-p0077","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"77","seq":76,"section":"VI. Conclusions and recommendations","text":"The 16 priority cases identified by the senior military prosecutor's office at the\nmilitary court of the former Kasai Occidental are still in the preliminary investigation\nstage. Nearly three years after the cases were opened, none is about to be closed or\nreferred to the courts for trial. Thus, the fight against impunity is still an entirely open\nquestion."},{"id":"a-hrc-45-50-p0078","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"78","seq":77,"section":"VI. Conclusions and recommendations","text":"The security situation in the Kasai region is relatively calm, characterized by a\nworrying socioeconomic and humanitarian situation that has been made worse by the\nhazards of the COVID-19 pandemic."},{"id":"a-hrc-45-50-p0079","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"79","seq":78,"section":"VI. Conclusions and recommendations","text":"While there have been some positive developments � including the\nestablishment of the interministerial working group responsible for implementing\nrecommendations and the holding of community consultations in Kasai Central � the\nconcerns expressed in the previous report of the team of international experts\n(A/HRC/41/31) are still valid."},{"id":"a-hrc-45-50-p0080","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"80","seq":79,"section":"VI. Conclusions and recommendations","text":"In the light of the above, the team of international experts reiterates the\nrecommendations contained in its previous report, which called for the Government\nof the Democratic Republic of the Congo to adopt the following measures:\n(a) Continue to work to secure the immediate release of the women and\nchildren who are still being held captive by the Bana Mura militia in Kamonia\nterritory (Kasai Province);\n(b) Adopt an investigation and prosecution strategy that encompasses all\ncategories of perpetrators of serious crimes in Kasai, regardless of their status or\nposition, their motive and the place where the crime was committed;\n(c) Allocate to the military justice system in Kasai sufficient financial\nresources and the personnel, equipment and logistical resources that are necessary for\nit to investigate cases and issue rulings without undue delay;\n(d) Consider the possibility of recruiting female staff to work for the\nmilitary justice authorities in Kasai, and overcome the shortage of staff by making\ngreater use of the civil justice system and the pool of talent offered by the bar\nassociation;\n(e) Ensure that specialized personnel are assigned the specific task of\ninvestigating and prosecuting crimes of sexual violence and crimes involving minors;\nand\n(f) Ensure that the disarmament process that is under way applies to all\nmilitias without distinction and helps to facilitate reconciliation by ensuring the\neffective return of militia members to their respective communities, with a gender-\nspecific approach."},{"id":"a-hrc-45-50-p0081","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"81","seq":80,"section":"VI. Conclusions and recommendations","text":"Furthermore, the team of international experts recommends that the\nGovernment of the Democratic Republic of the Congo should take the following steps:\n(a) Establish genuine reparation mechanisms for victims and ensure that\nthey function effectively;\n(b) Provide the interministerial working group with substantial financial\nand material resources to facilitate its effective functioning and with a plan for the\nimplementation of the recommendations, with a timetable and allocation of the\ncorresponding budgetary resources;\n(c) Extend to other conflict-affected provinces the lessons learned from the\ntransitional justice mechanisms pilot project in Kasai Central Province;\n(d) Proceed with the effective disarmament of all militias, without\ndistinction;\n(e) Ensure that the disarmament of ex-militia members is accompanied with\nsocioeconomic reintegration measures;\n(f) Ensure the effective functioning of the courts in the Kasai region;\n(g) Recruit women judges and station them in the military courts of the\nKasai region to better address the numerous cases of rape and sexual violence against\nwomen and the specific situation of displaced women and girls; and\n(h) Give effect to the outcomes of the community consultations conducted in\nKasai Central Province."},{"id":"a-hrc-45-50-p0082","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"82","seq":81,"section":"VI. Conclusions and recommendations","text":"The team of international experts recommends that the Chief Military\nProsecutor's office should appoint a team of investigating judges dedicated exclusively\nto cases related to the Kamuina Nsapu militia crisis and that it should be provided\nwith sufficient resources."},{"id":"a-hrc-45-50-p0083","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"83","seq":82,"section":"VI. Conclusions and recommendations","text":"The team of international experts recommends that the parliament should\ncontribute to the proper administration of justice by lifting the parliamentary\nimmunity of any deputy suspected of serious human rights violations."},{"id":"a-hrc-45-50-p0084","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"84","seq":83,"section":"VI. Conclusions and recommendations","text":"The team of international experts recommends that MONUSCO, United\nNations agencies and the Peacebuilding Fund should, through their various projects\nand programmes, continue to provide concrete support to the competent authorities in\nthe fight against impunity, with a particular focus on strengthening the autonomy of\nnational institutions and promoting reconciliation and transitional justice."},{"id":"a-hrc-45-50-p0085","rec_id":"recOMA5m0PDrmkf47","symbol":"A/HRC/45/50","n":"85","seq":84,"section":"VI. Conclusions and recommendations","text":"The team of international experts recommends that the Office of the United\nNations High Commissioner for Human Rights, MONUSCO and the United Nations\nsystem in general should remain actively involved in Kasai by providing technical\nsupport for all measures taken to combat impunity and to reconcile communities in\nKasai, including those relating to disarmament and community reintegration."},{"id":"a-hrc-48-82-u0000","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":null,"seq":0,"section":null,"text":"United Nations                                                                                  A/HRC/48/82\nGeneral Assembly                                                             Distr.: General\n20 August 2021\nEnglish\nOriginal: French","unnumbered":true},{"id":"a-hrc-48-82-u0001","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":null,"seq":1,"section":null,"text":"Summary\nThis report is submitted pursuant to Human Rights Council resolution 45/34 of 7\nOctober 2020, which renewed the mandate of the team of international experts on the\nsituation in Kasai and requested it to submit a final report to the Council at its forty-eighth\nsession during an interactive dialogue and to provide an oral update at its forty-sixth session.\nThe report comes against the background of the coronavirus disease (COVID-19) pandemic,\nthe withdrawal of the United Nations Organization Stabilization Mission in the Democratic\nRepublic of the Congo (MONUSCO) from Kasai and Kasai Central provinces and a volatile\npolitical climate that has seen some governors of the Kasai region deposed. The\nsocioeconomic and security situation is characterized by successive intercommunal clashes,\nrunaway rates of urban crime, food insecurity and a deplorable humanitarian situation linked\nin part to the ongoing forced expulsion or refoulement of Congolese living in Angola.\nRegarding the fight against impunity, apart from a few positive developments, the\nteam of international experts noted a lack of meaningful progress in the processing of cases\nbrought against perpetrators of serious violations of human rights and international\nhumanitarian law committed during the crisis linked to the Kamuina Nsapu militia. None of\nthe 16 priority cases that the Congolese military justice system has identified and taken up\nsince 2019 has, thus far, been referred to the courts.\nThe trial of the alleged murderers of Zaida Catalán and Michael Sharp, who were\nmembers of the Security Council’s Group of Experts on the Democratic Republic of the\nCongo, is stalled, with no sign of a swift resolution. The case of their Congolese guides has\nseen little progress.\nThe team of international experts believes that there is an urgent need to deploy\nadditional human resources and step up the recruitment of new military judges.\nThe team of international experts was informed of the investigative measures taken\nby the military justice system in the cases of the women enslaved by Bana Mura militiamen\nand welcomes the fact that some of the women have been freed. The team urges the\nGovernment to redouble efforts to secure the release of the other women and to arrest all\ntheir alleged enslavers.","unnumbered":true},{"id":"a-hrc-48-82-u0002","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":null,"seq":2,"section":null,"text":"Concerning the strategies on reconciliation, transitional justice, victim assistance and\nreparations, the team of international experts observed a number of significant gains at the\nnational and provincial levels. These include the launch and ownership of the transitional\njustice process by the highest authorities of the State and the adoption of the edict on the\nestablishment, organization, powers and functioning of the Truth, Justice and Reconciliation\nCommission of Kasai Central Province.\nThe team of international experts believes that there is an inevitable nexus between\npunitive justice and transitional justice.\nThe team of international experts welcomes the Government’s decision to\ndecentralize the transitional justice process in the Democratic Republic of the Congo, as well\nas the symbolic request for forgiveness addressed to victims.\nGiven this momentum, and in the interest of promoting local projects to facilitate\ncommunity reconciliation, the team of international experts suggests that the interministerial\ntask force, which met only once during the reporting period, be given the mandate to\ncoordinate transitional justice arrangements nationwide, with the support of an adequately\nresourced permanent secretariat.","unnumbered":true},{"id":"a-hrc-48-82-p0001","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"1","seq":3,"section":"I. Introduction","text":"The present report, which covers the period from October 2020 to September 2021, is\nsubmitted pursuant to Human Rights Council resolution 45/34 of 7 October 2020, which\nrenewed the mandate of the team of international experts on the situation in Kasai, tasking it\nwith observing, assessing and assisting the efforts of the Democratic Republic of the Congo\nto implement the recommendations of the previous team of international experts.1 The team\nwas requested to submit a final report to the Council at its forty-eighth session during an\ninteractive dialogue and to provide an oral update at its forty-sixth session."},{"id":"a-hrc-48-82-p0002","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"2","seq":4,"section":"I. Introduction","text":"In order to facilitate the performance of this mandate, the Human Rights Council, in\nits resolution 45/34, reiterated the request contained in its resolution 41/26 of 12 July 2019\nthat the United Nations High Commissioner for Human Rights provide, at the request of the\nauthorities, technical assistance, including the necessary forensic expertise, to the\nGovernment of the Democratic Republic of the Congo in order to support the judicial\nauthorities in their investigations into allegations of human rights violations and abuses in\nthe Kasai region and other regions of the country, with a view to bringing those responsible\nto justice."},{"id":"a-hrc-48-82-p0003","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"3","seq":5,"section":"I. Introduction","text":"The international experts Bacre Waly Ndiaye, of Senegal, Chair of the team, and\nMarie-Thérèse Keita-Bocoum, of Côte d’Ivoire, a team member, were appointed for this\npurpose by the Human Rights Council. In the performance of its mandate, the team of\ninternational experts was supported by a secretariat consisting of a coordinator based in\nKinshasa and a human rights official based in Kananga who is specialized in transitional\njustice. The team of international experts amended its workplan, adding the activities that\ncould not be carried out in 2020 due to the COVID-19 pandemic. In accordance with this\nworkplan, the team of international experts conducted two field visits to the Democratic\nRepublic of the Congo, the first from 17 to 27 March 2021 and the second from 18 June to 2\nJuly 2021."},{"id":"a-hrc-48-82-p0004","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"4","seq":6,"section":"I. Introduction","text":"During the first visit, the team of international experts held two meetings with\nmembers of the Government of the Democratic Republic of the Congo, the judicial\nauthorities, the Head of MONUSCO and all United Nations agencies, as well as the\ndiplomatic corps, civil society and the press."},{"id":"a-hrc-48-82-p0005","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"5","seq":7,"section":"I. Introduction","text":"Meanwhile, the Chair of the team of international experts participated, from Kinshasa,\nin the interactive dialogue on the Democratic Republic of the Congo at the forty-sixth session\nof the Human Rights Council."},{"id":"a-hrc-48-82-p0006","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"6","seq":8,"section":"I. Introduction","text":"During the second visit, in addition to the usual meetings with representatives of the\nGovernment, the military justice authorities, the diplomatic corps, United Nations agencies,\ncivil society, the press and traditional leaders, the team of international experts attended an\nofficial ceremony in Tshisuku, on 22 June 2021, for the return of the bodies of the victims of\nthe Tshisuku massacre2 and the inauguration of a mausoleum erected in the victims’ memory."},{"id":"a-hrc-48-82-p0007","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"7","seq":9,"section":"I. Introduction","text":"In addition, the team of international experts held a workshop on 23 and 24 June 2021\nin Tshikapa, Kasai Province, to reflect on reconciliation and transitional justice in the Kasai\nregion."},{"id":"a-hrc-48-82-p0008","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"8","seq":10,"section":"II. Mandate","text":"To carry out its mandate, the new team of international experts adopted a three-\npronged approach, namely: (a) monitoring judicial cases in the context of the fight against\nimpunity; (b) monitoring the reconciliation, transitional justice and reparation process; and\n(c) providing institutional support to the State bodies responsible for implementing\nrecommendations.\n1   See A/HRC/45/50.\n2   Summary execution of at least 79 civilians at Tshisuku market by members of the Armed Forces of\nthe Democratic Republic of the Congo on 7 May 2017. In addition to the killings, there were also\nincidents of rape and looting."},{"id":"a-hrc-48-82-p0009","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"9","seq":11,"section":"II. Mandate","text":"The current team of international experts carried out its mandate against the\nbackground of the withdrawal of MONUSCO from Kasai and Kasai Central provinces."},{"id":"a-hrc-48-82-p0010","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"10","seq":12,"section":"II. Mandate","text":"The closure of the Tshikapa and Kananga field offices marked the complete\nwithdrawal of MONUSCO from the Kasai region."},{"id":"a-hrc-48-82-p0011","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"11","seq":13,"section":"II. Mandate","text":"It should be noted that some United Nations agencies and the Office of the United\nNations High Commissioner for Human Rights (OHCHR) have maintained a presence in the\nKasai region."},{"id":"a-hrc-48-82-p0012","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"12","seq":14,"section":"II. Mandate","text":"In this context, it goes without saying that the presence and activities of the team of\ninternational experts, alongside entities of the United Nations system and other partners, give\nencouragement to the Government and help guide its efforts to implement the team’s\nrecommendations."},{"id":"a-hrc-48-82-p0013","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"13","seq":15,"section":"II. Mandate","text":"Despite the public health situation arising from the COVID-19 pandemic, the team of\ninternational experts has striven to discharge its mandate through field visits and its\nsecretariat’s activities on the ground. Thanks to these combined efforts, the team was able to\nassess the Government’s efforts to prosecute the perpetrators of serious offences committed\nduring the Kamuina Nsapu militia crisis. The team was also able to bring to the Government’s\nattention the barriers to the fight against impunity, the promotion of truth and reconciliation,\ncommunity reintegration and reparations, as well as the many challenges it faces in the\nsecurity, humanitarian and development domains."},{"id":"a-hrc-48-82-p0014","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"14","seq":16,"section":"II. Mandate","text":"The activities of the team of international experts complement those of United Nations\nagencies and give partners the opportunity to discuss their projects and programmes with the\nCongolese authorities within a set framework."},{"id":"a-hrc-48-82-p0015","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"15","seq":17,"section":"III. Cooperation between the team of international experts and","text":"The team of international experts enjoyed genuine collaboration and fruitful\ncooperation with the Congolese authorities. The secretariat, based in Kinshasa and Kananga,\nwas able to carry out its work without any obstacles and benefited from the openness of its\nCongolese interlocutors."},{"id":"a-hrc-48-82-p0016","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"16","seq":18,"section":"III. Cooperation between the team of international experts and","text":"That open-mindedness was apparent at the various meetings between the Ministry of\nHuman Rights and the team of international experts. For instance, the team took part in a\nmeeting of the interministerial task force on Kasai on 28 June 2021, where it could observe\nthe dynamism of the new interministerial team, which clearly opted for the decentralization\nof the provincial transitional justice process."},{"id":"a-hrc-48-82-p0017","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"17","seq":19,"section":"IV. Current situation in the Kasai region","text":"The political situation in the Kasai region is very volatile, especially in the provinces\nof Lomami, Kasai, Kasai Central and Kasai Oriental, whose governors have been the object\nof motions of no confidence and have, in some cases, been deposed. These political changes\nare taking place in a particularly difficult security and social context."},{"id":"a-hrc-48-82-p0018","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"18","seq":20,"section":"IV. Current situation in the Kasai region","text":"On the security front, the region has seen a series of intercommunal clashes, which\nexposed the fragility of the relative calm observed since the end of the Kamuina Nsapu militia\ncrisis. For example, there was a clash between members of the Lulua and Kuba communities\nin the village of Mwenge, Bakwakenge, Kasai Province, from 26 to 28 March 2021. The\nclash led to the death of at least 13 people, the burning of 190 homes and the displacement\nof at least 21,000 people.3"},{"id":"a-hrc-48-82-p0019","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"19","seq":21,"section":"IV. Current situation in the Kasai region","text":"There was also a rise in urban crime during the reporting period. According to the\ninformation gathered by the United Nations Joint Human Rights Office in the Democratic\nRepublic of the Congo, during the last week of March 2021, armed individuals, sometimes\nwearing uniforms of the defence and security forces, entered private residences in Kasai\nCentral Province and the city of Kananga at night, where they committed various violations\nof the right to property, including extortion and robbery, as well as rape, and engaged in cruel,\ninhuman and degrading treatment. 4 Those offences were reported by the public. On 13\nFebruary 2021, in answer to a call by women’s civil society organizations in Kasai Central,\nseveral women’s associations protested in Kananga to demand that the authorities enhance\nsecurity."},{"id":"a-hrc-48-82-p0020","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"20","seq":22,"section":"IV. Current situation in the Kasai region","text":"The team of international experts notes that the rise in crime in the Kasai region stems\nfrom the lack of appropriate action to quell residual Kamuina Nsapu activity. This concern\nwas raised in the last report of the previous team of international experts.5 According to civil\nsociety, the insecurity is attributable to the arrival of unpaid military personnel from Kamina,\nthe reorganization of militias and the expansion of illegal checkpoints used to extract money\nfrom the population. In civil society’s view, it is crucial that former militiamen be\nreintegrated into the community."},{"id":"a-hrc-48-82-p0021","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"21","seq":23,"section":"IV. Current situation in the Kasai region","text":"On the health front, the Kasai region was essentially shielded from the COVID-19\npandemic until September 2020, but the figures published during the first half of 2021\nindicate an upward trend in infections, particularly in Kasai and Kasai Central provinces. On\nthe socioeconomic front, poverty is becoming endemic. Basic necessities and foodstuffs,\nwhich are mainly imported from Angola, are increasingly expensive. Peaceful marches to\nprotest against the rising cost of living have taken place in recent months in most of the large\ncities in Kasai, including Mbuji-Mayi, Kananga and Tshikapa.6"},{"id":"a-hrc-48-82-p0022","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"22","seq":24,"section":"IV. Current situation in the Kasai region","text":"Despite the situation described above, the team of international experts did its best to\nfulfil its mandate."},{"id":"a-hrc-48-82-p0023","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"23","seq":25,"section":"V. Monitoring, evaluation and support for implementation by","text":"The team of international experts organized two visits to the Democratic Republic of\nthe Congo, during which it met with the Congolese authorities to follow up on the\nimplementation of the recommendations contained in the last report of the previous team.\nThose recommendations centred around two main concerns: the monitoring of efforts to\nestablish responsibility for the violations of human rights and international humanitarian law\ncommitted in the Kasai region; and the issue of transitional justice and reconciliation in that\nregion."},{"id":"a-hrc-48-82-p0024","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"24","seq":26,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The monitoring of efforts to establish responsibility focused on three areas: the fight\nagainst impunity, obstacles to the administration of justice and the current situation of victims\nand witnesses.\n4 Weekly report for 15–21 May 2021 of the Kananga-Tshikapa field office of the United Nations Joint\nHuman Rights Office in the Democratic Republic of the Congo.\n5 A/HRC/45/50, para. 11.\n6 Activity report of the Kananga field office of the United Nations Joint Human Rights Office in the\nDemocratic Republic of the Congo.\n1.       Efforts to combat impunity\n(a)       Context and analysis"},{"id":"a-hrc-48-82-p0025","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"25","seq":27,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"In its last report, the previous team of international experts raised concerns about the\nslow pace of the judicial process in cases brought against the alleged perpetrators of serious\nhuman rights violations committed during the Kamuina Nsapu militia crisis. 7 The team of\ninternational experts finds that, unfortunately, there has been no noticeable change in the\nsituation. At the time of writing, none of the priority cases identified and taken up by the\nCongolese military justice system has, thus far, been referred to the courts."},{"id":"a-hrc-48-82-p0026","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"26","seq":28,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The slow pace of the judicial process has compelled victims’ associations and civil\nsociety in the Kasai region to call on the Secretary-General of the United Nations to advocate\nfor the establishment of a special tribunal for the prosecution of crimes committed during the\nKamuina Nsapu crisis.8\n(b)       Prosecution and investigation of court cases"},{"id":"a-hrc-48-82-p0027","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"27","seq":29,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts notes with satisfaction that, with the support of the\ntechnical assistance team deployed by OHCHR, the investigations into the crimes committed\nin Mulombodi, Nganza and Tshisuku have been completed at the level of the senior military\nprosecutor’s office at the military court of the former Kasai Occidental Province and have\nbeen referred to the Office of the Chief Military Prosecutor for reasons of jurisdiction, as\nelements of the cases involve generals of the Armed Forces of the Democratic Republic of\nthe Congo. The team of international experts encourages the investigating judges to redouble\ntheir efforts to ensure that the cases are processed expeditiously and referred to a court."},{"id":"a-hrc-48-82-p0028","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"28","seq":30,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts notes that, in the Kamonia case involving a\nprovincial deputy, the senior military prosecutor’s office in Kananga requested support to\nconduct a joint investigation mission in the field. Similarly, a request was made in the\nMalenga case for support in identifying the remains through DNA testing. In the Kamako\ncase, the prosecutor’s office requested expert assistance to exhume the bodies and hear some\n67 victims and witnesses."},{"id":"a-hrc-48-82-p0029","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"29","seq":31,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts urges the senior military prosecutor’s office at the\nmilitary court of the former Kasai Occidental Province and the Office of the Chief Military\nProsecutor at the Military High Court to establish, together with the technical assistance team\ndeployed by OHCHR, a detailed calendar to ensure that the necessary missions can be carried\nout within a reasonable time frame."},{"id":"a-hrc-48-82-p0030","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"30","seq":32,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts welcomes the considerable support that the technical\nassistance team deployed by OHCHR provided to the Congolese justice system in\ninvestigating offences committed during the Kamuina Nsapu militia crisis and hopes that the\ntechnical assistance will be continued and expanded."},{"id":"a-hrc-48-82-p0031","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"31","seq":33,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts has taken note of the sentencing, on 16 March 2021,\nby the garrison military court of Kananga, of Laurent Nsumbu, a former militiaman\nprosecuted for murder, terrorism, conspiracy and war crimes, to rigorous imprisonment for\nlife."},{"id":"a-hrc-48-82-p0032","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"32","seq":34,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts takes note, in the case of the women enslaved by\nBana Mura militiamen, of the hearing granted to 26 women and girls who were released by,\nor escaped from, their captors. The team was informed of the death, in early August 2021, of\nChief Muyej Kamba Shatshionga, a provincial deputy and the main suspect in that case. He\nand both of his sons had already been questioned by the senior military prosecutor’s office\nin Kananga."},{"id":"a-hrc-48-82-p0033","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"33","seq":35,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts urges the Government to redouble its efforts to\nsecure the release of the women who remain enslaved and to speed up the investigation into\nthe complaints of those who were able to escape, with a view to swiftly bringing to justice\nthe perpetrators of these offences and their accomplices."},{"id":"a-hrc-48-82-p0034","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"34","seq":36,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"Regarding the trial of the alleged murderers of Zaida Catalán and Michael Sharp,\nmembers of the Security Council’s Group of Experts on the Democratic Republic of the\nCongo, the team of international experts notes with regret that the hearings have been so long\nand yet have failed to bring an end to proceedings."},{"id":"a-hrc-48-82-p0035","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"35","seq":37,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"Moreover, concerns remain about the investigation into the disappearance of their\nCongolese guides, given that the circumstances of the disappearance cannot be dissociated\nfrom the murder of the two United Nations experts. There is still no hard evidence of the\nguides’ death. While the Civil Code rule on duration of absence has been lawfully invoked\nto conclude that they have died, the conclusion is nothing more than an assumption. No\nserious investigative measure that might shed light on the circumstances of the guides’\ndisappearance should be overlooked, even if it means that the case of the two experts has to\nbe tried separately.\n2.    Barriers to the administration of justice in the Kasai region"},{"id":"a-hrc-48-82-p0036","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"36","seq":38,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"In the light of the foregoing, the team of international experts notes the scale of the\nchallenges and underscores the presence of certain barriers to the administration of justice in\nthe Kasai region."},{"id":"a-hrc-48-82-p0037","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"37","seq":39,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"In its last report, the previous team of international experts emphasized that the\nshortage of judges was one of the obstacles facing the judicial system in Kasai."},{"id":"a-hrc-48-82-p0038","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"38","seq":40,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts notes with regret that, over a year later, the number\nof judges, especially in the military system, and the working conditions are unchanged.\nAccording to the Office of the Chief Military Prosecutor at the Military High Court, no\nmilitary judges have been recruited since 2010, and the shortage of judges is felt across the\njurisdiction of the military courts."},{"id":"a-hrc-48-82-p0039","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"39","seq":41,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts notes that staffing shortages are compounded by a\nlack of equipment. The senior military prosecutor’s office in Kananga does not have the\nnecessary vehicles to cover its entire district, namely Kasai and Kasai Central provinces.\nWith the withdrawal of MONUSCO, which provided the most logistical support to the\nmilitary justice system, these difficulties will get worse."},{"id":"a-hrc-48-82-p0040","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"40","seq":42,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts reaffirms that increasing the number of judicial\nprofessionals in the various areas of the Kasai region is a precondition for meeting the\npopulation’s high expectations with regard to combating impunity. In addition, it believes\nthat to resolve the shortage of human and material resources, the military justice system’s\ncapacity needs to be doubled if it is to adapt to the redistricting and have a senior military\nprosecutor’s office in each province. The team of international experts suggests a temporary\nsolution whereby judges would be deployed for at least 18 months to exclusively oversee the\nprocessing of cases stemming from the Kamuina Nsapu militia crisis. This would give the\nCongolese authorities an opportunity to demonstrate their ability to administer justice in an\nindependent manner by redeploying internal resources."},{"id":"a-hrc-48-82-p0041","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"41","seq":43,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts recalls the close connection between strengthening\nthe human and material resources of the justice system and having an effective policy to\ncombat impunity.\n3.    Current situation of victims and witnesses"},{"id":"a-hrc-48-82-p0042","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"42","seq":44,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The victims are still awaiting the trials of the alleged perpetrators of the serious\nviolations of human rights and international humanitarian law to which they were subjected\nduring the Kamuina Nsapu militia crisis. The victims have established an association to\ndefend their interests with a view to interacting more effectively with the judicial system and\nwith the civilian and political authorities. Most of them are weary of the slow pace of the\njudicial proceedings and feel that perpetrators of offences enjoy a degree of impunity."},{"id":"a-hrc-48-82-p0043","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"43","seq":45,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"At a meeting in Kananga on 21 June 2021, members of civil society stressed that most\nof the victims are women and that the lack of support has heightened their vulnerability and,\nunfortunately, in some cases, has contributed to their death."},{"id":"a-hrc-48-82-p0044","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"44","seq":46,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"While civil society organizations welcome the arrest of members of the Kamuina\nNsapu militia, they have their doubts about whether the victims will actually receive\ncompensation."},{"id":"a-hrc-48-82-p0045","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"45","seq":47,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts commends the Government for its initiative aimed\nat establishing a compensation fund for victims of the armed conflict and encourages it to\noperationalize the fund as soon as possible in order to end the anguish and frustration of\nvictims, who feel abandoned."},{"id":"a-hrc-48-82-p0046","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"46","seq":48,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts recalls that the case of the women who were\nenslaved and sexually exploited by the Bana Mura has not yet been clarified or resolved."},{"id":"a-hrc-48-82-p0047","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"47","seq":49,"section":"A. Monitoring of efforts to establish responsibility for the violations of","text":"The team of international experts is of the view that there is an inevitable nexus\nbetween retributive justice and transitional justice insofar as there cannot be forgiveness,\nreconciliation or guarantees of non-repetition in a context of total impunity."},{"id":"a-hrc-48-82-p0048","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"48","seq":50,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"In its last report, the previous team of international experts welcomed the efforts made\nby the Congolese authorities in the area of community reconciliation and transitional justice\nthrough, on the one hand, the Government’s plan to establish a national council for conflict\nprevention and transformation, and, on the other, the implementation of transitional justice\nmechanisms in Kasai Central.9"},{"id":"a-hrc-48-82-p0049","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"49","seq":51,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts welcomes the solemn declaration of President Félix\nTshisekedi reaffirming the need to put in place transitional justice mechanisms at the national\nlevel to address the grim legacy of violence in the country and to provide an opportunity to\nrestore a peaceful environment conducive to national reconciliation. He reiterated this\nstatement in September 2020, during his address to the United Nations General Assembly.\nThe team of international experts welcomes the initiatives taken by Congolese civil society\nto organize a round table of experts on transitional justice in January 2021 and a workshop\non building the capacity of civil society in the field of transitional justice in May 2021. It\nwelcomes the establishment by civil society of a working group on transitional justice."},{"id":"a-hrc-48-82-p0050","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"50","seq":52,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts commends the considerable progress made in the\nfield of transitional justice in Kasai Central Province thanks to the implementation of the\npeace, justice, reconciliation and reconstruction project, and appreciates the commendable\nfollow-up project on spontaneous surrender in Kasai and Tanganyika."},{"id":"a-hrc-48-82-p0051","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"51","seq":53,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts calls on the Government of the Democratic Republic\nof the Congo and development partners to support the effective implementation, in\naccordance with international standards, of the Commission on Truth, Justice and\nReconciliation of Kasai Central Province and to offer encouragement for this pilot project.\n1.       Establishment of the Commission on Truth, Justice and Reconciliation of Kasai\nCentral Province"},{"id":"a-hrc-48-82-p0052","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"52","seq":54,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts notes that the Provincial Assembly of Kasai Central\nadopted, on 28 June 2021, an edict on the establishment, organization, mandate and\nfunctioning of the Commission on Truth, Justice and Reconciliation of Kasai Central\nProvince. The methodology and process followed to establish the Commission were\ncommendable and could serve as a reference for the implementation of reconciliation\nprocesses in other provinces and across the country."},{"id":"a-hrc-48-82-p0053","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"53","seq":55,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts welcomes the promulgation on 15 July 2021 by the\nInterim Governor of Kasai Central of the edict of 28 June 2021 adopted by the Provincial\nAssembly."},{"id":"a-hrc-48-82-p0054","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"54","seq":56,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts supports the effective operationalization of the\nCommission on Truth, Justice and Reconciliation of Kasai Central Province. To this end, it\nrecommends that the provincial authorities should define the legal framework necessary for\nthe Commission to function, speed up the implementation of its organizational and\noperational mechanisms – particularly those relating to the selection of its members – and\nthe drafting of its rules of procedure and accompanying handbook, and identify the resources\nnecessary for its proper functioning."},{"id":"a-hrc-48-82-p0055","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"55","seq":57,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"In order to ensure the effective functioning of the Commission on Truth, Justice and\nReconciliation of Kasai Central Province, the team of international experts calls for the\nmobilization of bilateral and multilateral partners to provide it with the resources necessary\nfor it to operate.\n2.    Links between the provincial, regional, interregional and national dimensions of a\nharmonized transitional justice process in the Democratic Republic of the Congo"},{"id":"a-hrc-48-82-p0056","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"56","seq":58,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"In order to gain a better understanding of the Government’s position on the links\nbetween the provincial, regional and national dimensions of a harmonized transitional justice\nprocess, the team of international experts organized a workshop on reconciliation and\ntransitional justice in the Kasai region on 23 and 24 June 2021, in Tshikapa. The workshop\nbrought together stakeholders from the political, social, religious, judicial, traditional,\nmilitary and voluntary sectors."},{"id":"a-hrc-48-82-p0057","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"57","seq":59,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts notes with satisfaction that the Government publicly\nindicated at the workshop that it favours a decentralized approach to transitional justice\nmechanisms, with a central body responsible for coordinating the implementation of the\noutcomes and harmonization of the operating criteria of the different experiments under way\nin the country."},{"id":"a-hrc-48-82-p0058","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"58","seq":60,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts suggests that the mandate of the interministerial task\nforce should be strengthened and expanded and that it should be provided with a permanent\nsecretariat for this purpose."},{"id":"a-hrc-48-82-p0059","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"59","seq":61,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts notes with interest the proposals made by various\nparticipants in the discussion to extend their current mandate so as to cover transitional justice\nat the national level, in response to the request made at the highest level of the State for\ninternational technical assistance in this area.\n3.    Disarmament and socioeconomic reintegration measures"},{"id":"a-hrc-48-82-p0060","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"60","seq":62,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"Noting that the violent phase of the Kamuina Nsapu militia crisis is now over, the\nteam of international experts welcomes developments in the treatment of demobilized\nmilitiamen through socioeconomic reintegration and transitional justice initiatives under the\nspontaneous surrender project in Kasai and Tanganyika. This project draws on peacebuilding,\njustice and reparation efforts to reconcile communities affected by the crisis in the provinces\nof Kasai Central, Kasai and Tanganyika."},{"id":"a-hrc-48-82-p0061","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"61","seq":63,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"At the Tshikapa workshop on 23 and 24 June 2021, the team of international experts\nnevertheless noted, during the working group discussions, the concerns expressed by\nparticipants about the lack of consideration shown to victims and the priority treatment of\nformer combatants under the spontaneous surrender project in Kasai and Tanganyika."},{"id":"a-hrc-48-82-p0062","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"62","seq":64,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts suggests that at least equal attention should be paid\nto the victims of the armed conflict."},{"id":"a-hrc-48-82-p0063","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"63","seq":65,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"While welcoming the various initiatives that are under way, the team of international\nexperts reiterates the urgent need to disarm all militiamen without distinction and to ensure\ntheir socioeconomic reintegration.\n4.        Socioeconomic and humanitarian situation"},{"id":"a-hrc-48-82-p0064","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"64","seq":66,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The socioeconomic situation in the Kasai region is a subject of particular interest that\nwas regularly brought up in the reports of previous teams of international experts. 10 The team\nof international experts reiterates that efforts to combat impunity and achieve reconciliation\nwill not produce tangible and satisfactory results unless the socioeconomic dimension of the\nconflict in Kasai is taken into consideration."},{"id":"a-hrc-48-82-p0065","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"65","seq":67,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts is concerned about the food insecurity triggered by,\namong other things, the arrival of expelled or returning population groups from Angola and\nthe limited food-supply channels in Kasai and Kasai Central provinces. This situation has\nbeen exacerbated by the COVID-19 pandemic, the measures taken to eradicate it and the poor\nstate of the road infrastructure, as well as police harassment and extortion linked to the\nanarchic and costly establishment of checkpoints on the road network."},{"id":"a-hrc-48-82-p0066","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"66","seq":68,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts welcomes the chain of solidarity created around the\nNexus approach in Kasai and Kasai Central provinces to link humanitarian action to peace\nand development initiatives and to coordinate an international presence in these provinces\nafter the withdrawal of MONUSCO. The team welcomes this approach, which strengthens\ncooperation between development partners, provincial governments and civil society."},{"id":"a-hrc-48-82-p0067","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"67","seq":69,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"On the humanitarian front, the team of international experts notes that voluntary\nrepatriations of Congolese living in Angola organized by the Office of the United Nations\nHigh Commissioner for Refugees (UNHCR) have been suspended since March 2020 owing\nto the closure of the border between the Democratic Republic of the Congo and Angola as a\nresult of the COVID-19 health crisis. It notes that this suspension has unfortunately resulted\nin the unilateral refoulement of Congolese to the Democratic Republic of the Congo by the\nAngolan authorities. The team of international experts notes the need to take more measures\nspecifically to help women cope with the humanitarian crisis. It stresses that special attention\nshould be paid to displaced women heads of household and girls, owing to their specific\nvulnerability."},{"id":"a-hrc-48-82-p0068","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"68","seq":70,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"Following its meeting with UNHCR on the issue of expulsion and refoulement, the\nteam of international experts welcomes the programme implemented jointly by UNHCR, the\nInternational Organization for Migration and the Government of the Democratic Republic of\nthe Congo to provide support to persons on the move."},{"id":"a-hrc-48-82-p0069","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"69","seq":71,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"The team of international experts has noted that the strategy chosen to allow access to\nland for some internally displaced persons and some persons expelled or turned back from\nAngola was to relocate them in certain territories in the provinces of Kasai and Kasai Central.\nThis initiative, although helpful, will require sustained action to ensure the long-term\npeaceful coexistence of the population groups."},{"id":"a-hrc-48-82-p0070","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"70","seq":72,"section":"B. Transitional justice and reconciliation in the Kasai region","text":"During the Tshikapa workshop, the team of international experts noted that one of the\nissues raised was the rejection by some people from the province of population groups from\nother parts of the Democratic Republic of the Congo, commonly referred to as “newcomers”.\nIn the opinion of the participants, this division is maintained and manipulated by certain\npolitical actors."},{"id":"a-hrc-48-82-p0071","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"71","seq":73,"section":"A. Conclusions","text":"The team of international experts welcomes the implementation by the\nGovernment of the Democratic Republic of the Congo of some of its recommendations\nand encourages it to implement those that have not been implemented."},{"id":"a-hrc-48-82-p0072","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"72","seq":74,"section":"A. Conclusions","text":"The team of international experts welcomes the full cooperation of the\nGovernment and its openness to implementing the recommendations on Kasai. It\nappreciates the solemn commitment of the highest Congolese authorities to use the\ntransitional justice process as an alternative conflict resolution mechanism."},{"id":"a-hrc-48-82-p0073","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"73","seq":75,"section":"A. Conclusions","text":"The team of international experts reiterates the urgent need to make the fight\nagainst impunity the foundation and the catalyst for a return of the region to peace and\nstability. It stresses the complementarity of retributive justice and transitional justice\nin that there can be no forgiveness, reconciliation or guarantee of non-repetition\nwithout truth and justice."},{"id":"a-hrc-48-82-p0074","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"74","seq":76,"section":"A. Conclusions","text":"The team of international experts notes that, following the Tshikapa workshop,\nthe Government decided to decentralize the transitional justice process in the\nDemocratic Republic of the Congo."},{"id":"a-hrc-48-82-p0075","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"75","seq":77,"section":"A. Conclusions","text":"The team of international experts welcomes the initiatives taken by Congolese\ncivil society to support the Government in the transitional justice process and\nencourages it to continue its efforts to build capacity in the field of transitional justice."},{"id":"a-hrc-48-82-p0076","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"76","seq":78,"section":"A. Conclusions","text":"The team of international experts notes that, while the violent phase of the\nKamuina Nsapu militia crisis is over, the causes of the crisis remain, its consequences\nhave not been redressed and no guarantees of non-repetition are as yet in place."},{"id":"a-hrc-48-82-p0077","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"77","seq":79,"section":"A. Conclusions","text":"The team of international experts notes that, despite the relative calm in the\nKasai region, ordinary crime is increasing and the humanitarian situation is worrying\nin the context of the COVID-19 pandemic."},{"id":"a-hrc-48-82-p0078","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"78","seq":80,"section":"A. Conclusions","text":"The team of international experts notes that most of the recommendations made\nin the last report of the previous team have unfortunately not yet been implemented. 11\nThe latter had recommended that the authorities of the Democratic Republic of the\nCongo take the following steps:\n(a)  Continue to work to secure the immediate release of the women and\nchildren who are still being held captive by the Bana Mura militia in Kamonia, Kasai\nProvince;\n(b)    Adopt an investigation and prosecution strategy that encompasses all\ncategories of perpetrators of serious crimes in Kasai, regardless of their status or\nposition, their motive or the place where the crime was committed;\n(c)    Allocate to the military justice system in Kasai sufficient financial\nresources and the personnel, equipment and logistical resources that are necessary for\nit to investigate cases and issue rulings without undue delay;\n(d)     Consider the possibility of recruiting female staff to work for the military\njustice authorities in Kasai, and overcome the shortage of staff by making greater use\nof the civil justice system and the pool of talent offered by the bar association;\n(e)    Ensure that specialized personnel are assigned the specific task of\ninvestigating and prosecuting crimes of sexual violence and crimes involving minors;\n(f)    Ensure that the disarmament process that is under way applies to all\nmilitias without distinction and helps to facilitate reconciliation by ensuring the\neffective return of militia members to their respective communities, with a gender-\nspecific approach;\n(g)    Establish genuine reparation mechanisms for victims and ensure that they\nfunction effectively;\n(h)   Provide the interministerial working group with substantial financial and\nmaterial resources to facilitate its effective functioning and with a plan for the\nimplementation of the recommendations, with a timetable and allocation of the\ncorresponding budgetary resources;\n(i)    Extend to other conflict-affected provinces the lessons learned from the\ntransitional justice mechanisms pilot project in Kasai Central Province;\n11   A/HRC/45/50, paras. 80 and 81.\n(j)    Proceed with the effective disarmament of all militias, without distinction;\n(k)   Support the disarmament of ex-militia members with the spontaneous\nsurrender project in Kasai and Tanganyika;\n(l)    Ensure the effective functioning of the courts in the Kasai region;\n(m) Recruit women judges and station them in the military courts of the Kasai\nregion to better address the numerous cases of rape and sexual violence against women\nand the specific situation of displaced women and girls."},{"id":"a-hrc-48-82-p0079","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"79","seq":81,"section":"B. Recommendations","text":"While reiterating the need to implement the recommendations of previous\nreports, the team of international experts also makes the following recommendations.\n1.     Prevention of impunity"},{"id":"a-hrc-48-82-p0080","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"80","seq":82,"section":"B. Recommendations","text":"The team of international experts recommends that the Government of the\nDemocratic Republic of the Congo, with the support of development partners, deploy\nfor a period of at least 18 months adequately resourced judges to deal exclusively with\nthe cases related to the Kamuina Nsapu militia crisis."},{"id":"a-hrc-48-82-p0081","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"81","seq":83,"section":"B. Recommendations","text":"The team of international experts urges the Government to redouble its efforts\nto free the women who are still enslaved and to speed up the investigation by the military\njustice system of the complaints of those who have managed to escape, so as to ensure\nthat the perpetrators of these crimes and their accomplices are brought to justice\nquickly."},{"id":"a-hrc-48-82-p0082","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"82","seq":84,"section":"B. Recommendations","text":"The team of international experts recommends that United Nations agencies, the\nPeacebuilding Fund and development partners should, through their various projects\nand programmes, continue to provide concrete support to the competent authorities in\nthe fight against impunity, with a particular focus on strengthening the autonomy of\nnational institutions and promoting reconciliation and transitional justice."},{"id":"a-hrc-48-82-p0083","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"83","seq":85,"section":"B. Recommendations","text":"The team of international experts reminds the Congolese State of the need to\nincrease the number of judges through recruitment."},{"id":"a-hrc-48-82-p0084","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"84","seq":86,"section":"B. Recommendations","text":"The team of international experts encourages the Ministry of Justice, the\nSupreme Council of the Judiciary and the bar association to increase the number of in-\nservice training sessions for civilian judges and lawyers on the handling of international\ncrimes."},{"id":"a-hrc-48-82-p0085","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"85","seq":87,"section":"B. Recommendations","text":"The team of international experts welcomes the Congolese Government’s act of\nrecognition of responsibility and request for forgiveness, as solemnly expressed by the\nMinister for Human Rights in Tshisuku during the ceremony for the return of the\nremains of some of the victims, and recommends that this act of contrition be translated\ninto concrete action, in particular the adjudication of the cases of the 16 priority cases\nopened in the context of the Kamuina Nsapu militia crisis."},{"id":"a-hrc-48-82-p0086","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"86","seq":88,"section":"B. Recommendations","text":"The team of international experts encourages the Office of the United Nations\nHigh Commissioner for Human Rights to continue to support the Congolese judiciary\nthrough its technical assistance team deployed in the Democratic Republic of the Congo.\n2.     Conflict prevention"},{"id":"a-hrc-48-82-p0087","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"87","seq":89,"section":"B. Recommendations","text":"The team of international experts notes the interconnection between land\ndisputes, resource exploitation and community conflicts and calls on the Government\nof the Democratic Republic of the Congo to prioritize their resolution in order to\nprevent the recurrence of human rights violations in the above-mentioned conflicts."},{"id":"a-hrc-48-82-p0088","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"88","seq":90,"section":"B. Recommendations","text":"The team of international experts recommends that the current review of the law\nestablishing the status of traditional leaders should give more attention to the\nprevention and amicable resolution of chieftaincy disputes."},{"id":"a-hrc-48-82-p0089","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"89","seq":91,"section":"B. Recommendations","text":"The team of international experts urges the Governments of the Democratic\nRepublic of the Congo and Angola to include the humanitarian dimension and respect\nfor human rights in any expulsion or repatriation measures."},{"id":"a-hrc-48-82-p0090","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"90","seq":92,"section":"B. Recommendations","text":"The team of international experts encourages the Office of the United Nations\nHigh Commissioner for Refugees to resume the organization of voluntary repatriations\nof Congolese refugees living in Angola, in consultation with the two Governments.\n3.    Reconciliation and reintegration"},{"id":"a-hrc-48-82-p0091","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"91","seq":93,"section":"B. Recommendations","text":"The team of international experts recommends that the Government of the\nDemocratic Republic of the Congo establish a national body to oversee transitional\njustice, reparation and compensation mechanisms. It suggests that the interministerial\nworking group set up by the Government could be reformed and strengthened to\nperform this function with the support of a permanent secretariat."},{"id":"a-hrc-48-82-p0092","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"92","seq":94,"section":"B. Recommendations","text":"In view of the Government’s decision to decentralize the transitional justice\nprocess, the team of international experts recommends the organization of a national\nworkshop on transitional justice to discuss the pilot project under way in the Kasai\nregion."},{"id":"a-hrc-48-82-p0093","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"93","seq":95,"section":"B. Recommendations","text":"The team of international experts recommends that the Office of the United\nNations High Commissioner for Human Rights and other United Nations agencies\nretain a presence and remain actively involved in Kasai by providing technical support\nfor all measures taken to combat impunity and to reconcile communities in Kasai,\nincluding those relating to the disarmament of ex-militiamen and community\nreintegration."},{"id":"a-hrc-48-82-p0094","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"94","seq":96,"section":"B. Recommendations","text":"The team of international experts calls for the mobilization of bilateral and\nmultilateral partners to provide the Commission on Truth, Justice and Reconciliation\nof Kasai Central Province with the necessary resources to operate in accordance with\ninternational standards.\n4.    Reparation"},{"id":"a-hrc-48-82-p0095","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"95","seq":97,"section":"B. Recommendations","text":"The team of international experts encourages the Government to make the\ncompensation fund for victims of the armed conflict operational as soon as possible."},{"id":"a-hrc-48-82-p0096","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"96","seq":98,"section":"B. Recommendations","text":"The team of international experts encourages the continuation of the\nspontaneous surrender project in Kasai and Tanganyika and suggests that it also take\ninto account the situation of victims."},{"id":"a-hrc-48-82-p0097","rec_id":"reca1DGtVsz2vg0VY","symbol":"A/HRC/48/82","n":"97","seq":99,"section":"B. Recommendations","text":"The team of international experts recommends that the United Nations Human\nRights Council remain seized of the situation in Kasai, Democratic Republic of the\nCongo."},{"id":"a-hrc-51-60-u0000","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":null,"seq":0,"section":null,"text":"United Nations                                                                                 A/HRC/51/60\nGeneral Assembly                                                            Distr.: General\n18 August 2022\nEnglish\nOriginal: French","unnumbered":true},{"id":"a-hrc-51-60-u0001","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":null,"seq":1,"section":null,"text":"Summary\nThe present report is submitted pursuant to Human Rights Council resolution 48/20\nof 11 October 2021, which renewed the mandate of the team of international experts on the\nsituation in Kasai and extended it to cover the entire territory of the Democratic Republic of\nthe Congo. The Council requested the team of international experts to submit its final report\nto the Council, in the framework of an interactive dialogue, at its fifty-first session and to\npresent it with an oral update at its forty-ninth session. The implementation of this expanded\nmandate comes as the United Nations Organization Stabilization Mission in the Democratic\nRepublic of the Congo is gradually withdrawing from Tanganyika Province after having\nwithdrawn from the provinces of Kasai and Kasai Central.\nUnder its expanded mandate, the team of international experts conducted four field\nvisits and organized a workshop on the status and prospects of transitional justice in the\nDemocratic Republic of the Congo, in collaboration with the Ministry of Human Rights and\nthe United Nations Joint Human Rights Office in the Democratic Republic of the Congo.\nThe visits and the workshop allowed the team of international experts to develop a clearer\nunderstanding of the challenges and opportunities arising from the introduction of a system\nof transitional justice that will facilitate a break with past cycles of conflict, reconciliation\namong different population groups and observance of the rule of law, as a means of\nprotecting the gains to be made under the planned reforms.\nThese challenges include the cross-border nature of conflicts, insecurity and illegal\nresource exploitation. Moreover, long-standing intercommunal conflicts have been reignited,\noften as a smokescreen to draw attention away from the unlawful exploitation of the\ncountry’s agricultural, mining and land resources by armed groups. The country is\nexperiencing conflicts of an exceptionally violent nature, involving instances of rape and\nsexual violence, while the State is struggling to provide all citizens with the protection to\nwhich they are entitled. These conflicts are fuelled by hate speech and calls for violence and\ndiscrimination. Combined with widespread poverty, a high level of youth unemployment and\na lack of jobs and economic opportunities, the conflicts have led to an increase in crime and\nexposed young people to exploitation by armed groups and militias, including groups\naffiliated with political parties. These circumstances are a ticking time bomb, especially\nduring election periods.","unnumbered":true},{"id":"a-hrc-51-60-u0002","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":null,"seq":2,"section":null,"text":"Although sincere, the Government’s efforts and initiatives to promote disarmament,\ncommunity reintegration, reparation for victims, the fight against impunity and security and\njustice sector reforms require enhanced coordination with adequate communication and\ngreater national funding, with support from foreign partners, if they are to achieve their stated\nobjectives.\nImpunity for the violations of human rights and international humanitarian law\ndocumented in the report on the mapping exercise and in subsequent reports of the United\nNations Joint Human Rights Office and of Human Rights Council experts, the resumption of\nattacks by the Mouvement du 23 mars (M23) and the beginning of the Nairobi process\nfacilitated by the States members of the East African Community have demonstrated that it\nis essential to take account of the cross-border aspects of the conflicts and of transitional\njustice.\nTo promote dialogue and reflection on how the Democratic Republic of the Congo\ncan meet this set of challenges, the team of international experts organized, together with the\nMinistry of Human Rights and the United Nations Joint Human Rights Office, a workshop\non transitional justice, the outcomes of which will be taken into account by an expanded\nscientific committee that will be set up to propose a paper on the national transitional justice\npolicy.\nLastly, the team of international experts offers its conclusions and makes\nrecommendations with a view to strengthening current and future activities.","unnumbered":true},{"id":"a-hrc-51-60-p0001","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"1","seq":3,"section":"I. Introduction","text":"In its resolution 48/20 of 11 October 2021, the Human Rights Council renewed the\nmandate of the team of international experts on the situation in Kasai and extended it to cover\nthe entire territory of the Democratic Republic of the Congo in order to assist the country in\nits efforts to implement its transitional justice policy and to assess the follow-up given to\njudicial cases, particularly cases deemed a priority in the fight against impunity. The Human\nRights Council requested the team of international experts to submit its final report to the\nCouncil, in the framework of an interactive dialogue, at its fifty-first session and to present it\nwith an oral update at its forty-ninth session."},{"id":"a-hrc-51-60-p0002","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"2","seq":4,"section":"I. Introduction","text":"In resolution 48/20, the Human Rights Council reiterated its request to the Office of\nthe United Nations High Commissioner for Human Rights (OHCHR) to provide technical\nassistance, including forensic expertise, to the Government of the Democratic Republic of\nthe Congo in order to support the judicial authorities in their investigations into allegations\nof human rights violations and abuses, with a view to bringing those responsible to justice,\nand technical assistance to support the development of a transitional justice mechanism in\nthe Democratic Republic of the Congo."},{"id":"a-hrc-51-60-p0003","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"3","seq":5,"section":"I. Introduction","text":"The international experts Bacre Waly Ndiaye (Senegal), Chair of the team, and Marie\nThérèse Keita-Bocoum (Côte d’Ivoire), a team member, were appointed by the United\nNations High Commissioner for Human Rights on 11 November 2021 at the request of the\nHuman Rights Council. In the performance of its mandate, the team of international experts\nis supported by a coordinator and a human rights officer specializing in transitional justice.\nThe team of international experts drew up a plan of activities and conducted four field visits\nto the Democratic Republic of the Congo, from 1 to 12 December 2021, 1 to 15 March 2022,\n13 to 27 May 2022 and 13 to 26 July 2022."},{"id":"a-hrc-51-60-p0004","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"4","seq":6,"section":"I. Introduction","text":"During its first two visits, the team of international experts visited Kinshasa, Kalemie\nin Tanganyika Province, Goma in North Kivu and Bukavu in South Kivu to meet with\nmembers of the Government of the Democratic Republic of the Congo, provincial authorities,\ncivilian and military judicial authorities, the Special Representative of the Secretary-General\nin the Democratic Republic of the Congo and Head of the United Nations Organization\nStabilization Mission in the Democratic Republic of the Congo (MONUSCO),\nrepresentatives of all United Nations agencies, the diplomatic corps, provincial authorities,\nrepresentatives of the different communities and religious denominations and the President\nof the Panzi Foundation, as well as civil society and the press. In Kalemie, the team of\ninternational experts participated in the opening ceremony of the public consultations\norganized by the Government with the support of the United Nations Joint Human Rights\nOffice in the Democratic Republic of the Congo and the financial support of Belgium and\nthe United Nations Peacebuilding Fund."},{"id":"a-hrc-51-60-p0005","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"5","seq":7,"section":"I. Introduction","text":"On 7 December 2021, in Goma, the team of international experts participated in a\ntraining seminar on transitional justice for civilian and military judges from the provinces of\nNorth Kivu and South Kivu; on this occasion, the Chair of the team of international experts\ndelivered a statement on the transitional justice process in Grand Kasai. On 2 March 2022,\nthe team of international experts met with representatives of the Twa and Bantu communities."},{"id":"a-hrc-51-60-p0006","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"6","seq":8,"section":"I. Introduction","text":"During its third and fourth visits, the team of international experts met with the\nCoordinator of the Disarmament, Demobilization, Community Recovery and Stabilization\nProgramme, the Chair of the Standing Committee on Human Rights of the National\nAssembly, the President of the National Assembly and the members of the Joint Steering\nCommission on Transitional Justice, as well as the Chief Military Prosecutor at the Military\nHigh Court and the President of the Military High Court. During the second leg of its third\nmission, the team of international experts conducted a field visit to Lubumbashi, in Haut-\nKatanga Province, through which it learned about the factors at play in the conflict between\nthe Katangese and Kasai communities, including the Katangese community’s fear that the\ninflux of persons arriving from Kasai would alter the electoral majority; the activities of\nmilitias associated with political parties and of the Bakata Katanga armed group; and the\nimpact of hate speech in the Province."},{"id":"a-hrc-51-60-p0007","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"7","seq":9,"section":"I. Introduction","text":"From 19 to 21 July 2022, in Kinshasa, the team of international experts organized, in\ncollaboration with the Ministry of Human Rights and the United Nations Joint Human Rights\nOffice, a workshop on the status and prospects of transitional justice in the Democratic\nRepublic of the Congo."},{"id":"a-hrc-51-60-p0008","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"8","seq":10,"section":"I. Introduction","text":"In March 2022, in Geneva, the team of international experts presented its oral report\non the situation in the Democratic Republic of the Congo during an interactive dialogue at\nthe forty-ninth session of the Human Rights Council."},{"id":"a-hrc-51-60-p0009","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"9","seq":11,"section":"I. Introduction","text":"The present report is submitted in accordance with Human Rights Council resolution\n48/20. It highlights the various activities undertaken by the team of international experts in\nthe performance of its mandate."},{"id":"a-hrc-51-60-p0010","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"10","seq":12,"section":"II. Mandate","text":"The team of international experts adopted a two-pronged methodology: following up\non judicial cases, particularly cases deemed a priority in the fight against impunity, and\nmonitoring and supporting the authorities of the Democratic Republic of the Congo in the\ndevelopment and implementation of the transitional justice policy."},{"id":"a-hrc-51-60-p0011","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"11","seq":13,"section":"II. Mandate","text":"The implementation of the team’s expanded mandate comes at a time when\nMONUSCO is gradually withdrawing from Tanganyika Province, after its withdrawal from\nthe provinces of Kasai and Kasai-Central, a state of siege has been declared in the provinces\nof North Kivu and Ituri, conflicts between the Mouvement du 23 mars (M23) and the Armed\nForces of the Democratic Republic of the Congo have resumed in the eastern part of the\ncountry, violence has erupted between the Twa and Bantu communities in Tanganyika\nProvince, and the Katangese community has expressed hostility towards the Kasai\ncommunity in Haut-Katanga."},{"id":"a-hrc-51-60-p0012","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"12","seq":14,"section":"II. Mandate","text":"At the same time, the efforts of OHCHR and United Nations agencies to maintain a\npresence in those areas from which MONUSCO has withdrawn are worthy of note."},{"id":"a-hrc-51-60-p0013","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"13","seq":15,"section":"II. Mandate","text":"Despite the situation described above, the team of international experts made every\neffort to carry out its four field visits as planned and to take steps to support the Government."},{"id":"a-hrc-51-60-p0014","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"14","seq":16,"section":"III. Cooperation between the team of international experts and","text":"The team’s performance of its mandate requires genuine collaboration and effective\ncooperation with the Congolese authorities. The team was able to carry out its work without\nhindrance and enjoyed the continuous cooperation and openness of its Congolese\ninterlocutors."},{"id":"a-hrc-51-60-p0015","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"15","seq":17,"section":"III. Cooperation between the team of international experts and","text":"That open-mindedness was made apparent by the renewal and extension of the team’s\nmandate to the entire country at the request of the Government. The team welcomes the\nconstructive cooperation of the authorities of the Democratic Republic of the Congo in\nfacilitating its visits to the country."},{"id":"a-hrc-51-60-p0016","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"16","seq":18,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"The four field visits allowed the team of international experts to assess the security,\npolitical, judicial, social and humanitarian situation."},{"id":"a-hrc-51-60-p0017","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"17","seq":19,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"The team of international experts is concerned about the alarming security situation\nin the eastern provinces of the Democratic Republic of the Congo, particularly North Kivu\nand Ituri. It notes that since November 2021, M23 has resumed its attacks on the Armed\nForces of the Democratic Republic of the Congo and MONUSCO peacekeepers in North\nKivu. In February 2022, M23 destroyed a MONUSCO helicopter, killing eight\npeacekeepers.1 In addition, according to the United Nations Joint Human Rights Office, at\nleast 34 people, including 2 children, were killed when a rocket struck a school.2"},{"id":"a-hrc-51-60-p0018","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"18","seq":20,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"The team of international experts also notes that the border town of Bunagana3 has\npassed into the hands of M23 and regrets the many human rights abuses that this occupation\nentails. The situation in the eastern part of the country has resulted in the mass displacement\nof more than 170,000 people4 to Uganda and neighbouring territories, leading to the further\ndeterioration of the humanitarian situation, particularly for women, children and other\nvulnerable people."},{"id":"a-hrc-51-60-p0019","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"19","seq":21,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"The team of international experts further notes that the level of trust between different\npopulation groups has deteriorated considerably. Moreover, the authorities of the Democratic\nRepublic of the Congo and a large part of the national population accuse Rwanda of\nsupporting M23. This widespread suspicion has led to hate speech and to calls for violence\nand discrimination against population groups who speak Kinyarwanda. Despite the\nGovernment’s condemnation of this hate speech and the measures it has taken to stop it, it\nhas resulted in victims."},{"id":"a-hrc-51-60-p0020","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"20","seq":22,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"On the diplomatic and military fronts, the Heads of State of the East African\nCommunity have taken measures to restore peace and end the conflict. Talks between the\nGovernment of the Democratic Republic of the Congo and several armed groups were held\nin Nairobi in April 2022, with the aim of bringing peace to the eastern part of the country."},{"id":"a-hrc-51-60-p0021","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"21","seq":23,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"On the judicial front, the team of international experts remains concerned about the\nsevere lack of adequate human and material resources devoted to the administration of justice\nin the Democratic Republic of the Congo. The team of international experts notes the efforts\ndeployed by the Ministry of Justice to restore the civilian justice system in provinces where\na state of siege has been declared. In this context, an ordinance has been issued removing\nfrom the jurisdiction of the military courts all cases falling under the ordinary jurisdiction of\nthe civilian courts."},{"id":"a-hrc-51-60-p0022","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"22","seq":24,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"On the social and humanitarian front, the team of international experts is concerned\nabout the persistence and occasional exacerbation of inter-community tensions and conflicts\nin the provinces of Ituri, North Kivu and South Kivu, which have resulted in the emergence\nof new armed groups and a resurgence in the forced recruitment of children into their ranks. 5\nThese groups claim to be engaged in the self-defence of their communities but their real\nmotive is to control resources and territory. Multiple attacks on defence and security forces,\nas well as incursions into villages involving abuses against civilians, have led to mass\ndisplacement towards the country’s interior and to neighbouring countries. Camps for\ndisplaced persons have also been the target of deadly attacks. The delivery of humanitarian\naid, the assessment of needs and the evaluation of strategies for the protection of civilians are\nseverely hampered by the difficulty of gaining access to affected areas."},{"id":"a-hrc-51-60-p0023","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"23","seq":25,"section":"IV. Current situation in the Democratic Republic of the Congo","text":"On 25 and 26 July 2022, at the end of its fourth visit, the team of international experts\nwas informed of violent demonstrations in the provinces of North Kivu and Ituri intended to\nforce the withdrawal of MONUSCO.\n1 Statement delivered by the spokesperson for the Military Governor of North Kivu on 29 March 2022.\n2 United Nations Joint Human Rights Office in the Democratic Republic of the Congo, biannual report,\nJanuary–June 2022.\n3 A town in North Kivu on the border with Uganda that is a geostrategically important cross-border\ntrade centre.\n4 United Nations Joint Human Rights Office in the Democratic Republic of the Congo, biannual report,\nJanuary–June 2022.\n5 Protection Cluster, Democratic Republic of the Congo, “Analyse de protection − provinces de l’Ituri\n& du Nord Kivu : focus sur 3 facteurs de dégradation de la situation humanitaire et de protection”\n(November and December 2021)."},{"id":"a-hrc-51-60-p0024","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"24","seq":26,"section":"V. Implementation of the expanded mandate of the team of","text":"Under its expanded mandate covering the entire territory of the Democratic Republic\nof the Congo, the team of international experts organized four visits to the country during\nwhich it met with Congolese authorities, civil society and international partners. Combating\nimpunity and promoting reconciliation and transitional justice were the main objectives of\nthese visits."},{"id":"a-hrc-51-60-p0025","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"25","seq":27,"section":"A. Combating impunity","text":"The fight against impunity was examined from three angles: its context, the follow-\nup given to judicial cases and the situation of victims.\n1.       Context\n(a)       General situation of the administration of justice"},{"id":"a-hrc-51-60-p0026","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"26","seq":28,"section":"A. Combating impunity","text":"With respect to the administration of justice in the Democratic Republic of the Congo,\nthe general context remains unchanged, despite the efforts deployed in that regard, which\nnonetheless deserve to be highlighted. The glaring lack of human, financial and material\nresources continues to be the main challenge in this respect."},{"id":"a-hrc-51-60-p0027","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"27","seq":29,"section":"A. Combating impunity","text":"The lack of judges significantly undermines the fight against impunity. According to\nthe Chief Military Prosecutor, in Ituri Province, for example, the cases of more than 2,000\ndetainees are being handled by a mere 10 judges.6"},{"id":"a-hrc-51-60-p0028","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"28","seq":30,"section":"A. Combating impunity","text":"Many judges assigned to certain parts of the country are unable to report to their place\nof assignment because of a lack of infrastructure, housing or means of travel, or even, in\nsome places, the absence of a courthouse. The team of international experts notes that this\nsituation exacerbates the difficulties faced by the general public in gaining access to justice.\nThe Ministry of Justice is considering granting so-called “bush bonuses” to judges who are\nforced to leave their families behind upon relocation from their usual place of residence. A\njudicial infrastructure development programme is being implemented with the support of the\nEuropean Union to mitigate this problem."},{"id":"a-hrc-51-60-p0029","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"29","seq":31,"section":"A. Combating impunity","text":"Measures such as those described above, as well as measures to protect judges and\ntheir workplaces in the current extremely volatile security context, must be supported and\nsignificantly strengthened."},{"id":"a-hrc-51-60-p0030","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"30","seq":32,"section":"A. Combating impunity","text":"The team of international experts notes a correlation between the absence of the\njudicial system and the State, on the one hand, and the proliferation of armed groups and\nincreased violence, on the other."},{"id":"a-hrc-51-60-p0031","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"31","seq":33,"section":"A. Combating impunity","text":"Civilian judges interviewed by the team of international experts in Bukavu, in South\nKivu Province, explained that, owing to the difficulties of working in the current security\ncontext, no cases of crimes against humanity had been referred to the Court of Appeal.7 Such\ncrimes were brought before the military courts because military judges enjoyed army\nprotection when travelling and were considered to be more efficient, to the extent that even\nsimple cases related to the payment of rent were referred to them. The judges also complained\nof the absence of the State outside of urban centres. According to them, most cases of human\nrights violations were documented only by non-governmental organizations (NGOs) and the\nUnited Nations Joint Human Rights Office."},{"id":"a-hrc-51-60-p0032","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"32","seq":34,"section":"A. Combating impunity","text":"Representatives of civil society in Bukavu echoed these judges’ concerns, pointing\nout that insecurity is an obstacle to legal proceedings."},{"id":"a-hrc-51-60-p0033","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"33","seq":35,"section":"A. Combating impunity","text":"The team of international experts notes that not a single new judge has been recruited\nfor over 11 years. According to the Chief Military Prosecutor at the Military High Court,\nthere are currently 214 military prosecutors and 114 military court judges.8 The recruitment\nof 500 new military judges envisaged within the framework of the ongoing recruitment of\n2,000 judges by the Ministry of Justice will double the capacity of the military justice system."},{"id":"a-hrc-51-60-p0034","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"34","seq":36,"section":"A. Combating impunity","text":"Moreover, the reinstatement of judges who had been unfairly removed from office\nwill reinforce the impact of the planned recruitment drive. The implementation of these two\nmeasures should help to alleviate problems associated with the lack of human resources."},{"id":"a-hrc-51-60-p0035","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"35","seq":37,"section":"A. Combating impunity","text":"The team of international experts welcomed these measures and encouraged the\nGovernment to take due account of the need to increase the number of female judges through\nthe planned recruitment process; this would facilitate, inter alia, the processing of the many\ncases of sexual violence regularly recorded in the country’s provinces."},{"id":"a-hrc-51-60-p0036","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"36","seq":38,"section":"A. Combating impunity","text":"Moreover, this mass recruitment drive must be accompanied by adequate and\nsustained initial training in order to ensure the required level of professional competence,\nwithout which it would be ineffective."},{"id":"a-hrc-51-60-p0037","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"37","seq":39,"section":"A. Combating impunity","text":"However, it is important to emphasize that the operation of the judicial system\ndepends primarily on support from the international partners of the Democratic Republic of\nthe Congo. The team of international experts is of the view that a significant increase in the\nportion of the national budget set aside for the administration of justice is essential to ensure\nthe sustainability of efforts to rehabilitate the judicial system.\n(b)        Administration of justice in provinces where a state of siege has been declared"},{"id":"a-hrc-51-60-p0038","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"38","seq":40,"section":"A. Combating impunity","text":"The team of international experts notes that the security situation is clearly a major\nobstacle to combating impunity, particularly in the east of the country, where human rights\nviolations are frequent."},{"id":"a-hrc-51-60-p0039","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"39","seq":41,"section":"A. Combating impunity","text":"Article 6 of Order No. 21/016 of 3 May 2021 provides that, for the duration of the\nstate of siege, the criminal law jurisdiction normally vested in the civilian courts is transferred\nto the military courts. However, given the influx of civilian cases referred to the already\noverburdened military courts, Order No. 22/024 of 18 March 2022 restricted the jurisdiction\nof the military courts to a limited number of criminal offences, while at the same time re-\nestablishing the regular jurisdiction of the civilian courts."},{"id":"a-hrc-51-60-p0040","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"40","seq":42,"section":"A. Combating impunity","text":"The team of international experts is of the view that the presence of the military justice\nsystem needs to be strengthened significantly in the provinces that are under a state of siege,\nwhere the military courts are struggling to cope with the increasingly heavy burden of\neradicating armed groups, protecting the civilian population and strengthening discipline in\nthe army.\n2.        Follow-up to judicial cases\n(a)        General comments on the implementation of the recommendations made in the previous\nreport9"},{"id":"a-hrc-51-60-p0041","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"41","seq":43,"section":"A. Combating impunity","text":"The team of international experts used each of its four visits to follow up on the\njudicial cases opened in the wake of the Kamuina Nsapu militia crisis. It remains concerned,\nhowever, about the slow pace of the implementation of the recommendations made in its\nprevious reports10 regarding the fight against impunity."},{"id":"a-hrc-51-60-p0042","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"42","seq":44,"section":"A. Combating impunity","text":"The team of international experts notes that of the 16 priority cases identified since\n2019, only one, the Mulombodi case, has reached the stage of completion of preliminary\n8  Interview with the Chief Military Prosecutor on 3 December 2021, during the first visit of the team of\ninternational experts.\n9 A/HRC/48/82.\n10 A/HRC/41/31, A/HRC/45/50 and A/HRC/48/82.\nproceedings and referral to the Military High Court for trial. The team notes that, in this case,\nas well as in the Nganza and Tshisuku cases, the accused generals are protected by immunity.\nThe team of international experts supports the requests for waiver of immunity made by the\nOffice of the Chief Military Prosecutor and hopes that these requests will be looked upon\nfavourably, so that the process of military justice can overcome the obstacle of impunity."},{"id":"a-hrc-51-60-p0043","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"43","seq":45,"section":"A. Combating impunity","text":"The team of international experts is disappointed that the case of the women enslaved\nby the Bana Mura militia, which was raised many years ago, remains unresolved."},{"id":"a-hrc-51-60-p0044","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"44","seq":46,"section":"A. Combating impunity","text":"The team of international experts welcomes the fact that the case of the murder of\nZaida Catalán and Michael Sharp, members of the Group of Experts on the Democratic\nRepublic of the Congo, which was attached to a committee of the Security Council, has\nfinally come to trial. Death sentences were handed down to the perpetrators and their\naccomplices, which triggered an automatic appeal by the military prosecution service. The\nteam of international experts hopes that the Military High Court will sit within a reasonable\ntime to rule on the appeal filed by the Office of the Chief Military Prosecutor and the\ndefendants against the ruling of the Kananga Military Court. It notes with concern that the\ncase of the victims’ four Congolese colleagues is still pending."},{"id":"a-hrc-51-60-p0045","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"45","seq":47,"section":"A. Combating impunity","text":"The team of international experts welcomes the ruling handed down on the appeal\nfiled by the Military High Court in the case of the murder of Floribert Chebeya Bahizire and\nFidèle Bazana Edadi. It notes that the defendants have been ordered to pay damages to the\nwidows and orphans of the two victims in solidum with the Democratic Republic of the\nCongo. The team urges the Democratic Republic of the Congo to ensure the prompt execution\nof this ruling."},{"id":"a-hrc-51-60-p0046","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"46","seq":48,"section":"A. Combating impunity","text":"The team of international experts welcomes the continued forensic support provided\nto the Congolese justice system by the technical assistance team deployed by OHCHR.\n(b)     National prosecution strategy"},{"id":"a-hrc-51-60-p0047","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"47","seq":49,"section":"A. Combating impunity","text":"The team of international experts welcomes the development by the Democratic\nRepublic of the Congo of a national strategy for targeted prosecutions that will optimize the\nuse of available resources on a province-by-province basis and pave the way for transitional\njustice.\n3.     Situation of victims\n(a)     Victims’ impatience with the slowness of the judicial process"},{"id":"a-hrc-51-60-p0048","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"48","seq":50,"section":"A. Combating impunity","text":"The team of international experts notes that the lack of justice leads to a feeling of\nabandonment and a loss of trust in the judicial system among victims. As a result, some\nvictims’ associations and NGOs, such as Dr. Denis Mukwege’s Panzi Foundation, have\ncalled for the establishment of an international court with jurisdiction over the Democratic\nRepublic of the Congo or of hybrid courts. In addition, the Grand Kasai victims’ association\nhas filed a complaint with the International Criminal Court against former President Joseph\nKabila and certain political and military officials, including generals."},{"id":"a-hrc-51-60-p0049","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"49","seq":51,"section":"A. Combating impunity","text":"The team of international experts maintains that justice for the Congolese people can\nbe achieved in the Democratic Republic of the Congo by Congolese judges, provided that\nadequate resources are made available to them. The military courts and tribunals, which hear\nmost cases involving serious crimes, crimes against humanity and war crimes, have the\nprofessional tools they need to carry out their mandates effectively."},{"id":"a-hrc-51-60-p0050","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"50","seq":52,"section":"A. Combating impunity","text":"The need to urgently provide the justice system with sufficient means to accomplish\nits mission is imperative in the current context of war in the east of the country, with human\nrights violations on the rise and victims still awaiting the implementation of the conclusions\nof the report on the mapping exercise. The absence of the State is detrimental to this situation\nand is particularly noticeable in the context of the gradual disengagement of MONUSCO.\n(b)         Victims’ concerns"},{"id":"a-hrc-51-60-p0051","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"51","seq":53,"section":"A. Combating impunity","text":"The team of international experts notes that the Grand Kasai victims’ association\noccasionally organizes public demonstrations to demand justice for victims and the\nprosecution of alleged perpetrators of serious human rights violations."},{"id":"a-hrc-51-60-p0052","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"52","seq":54,"section":"B. Reconciliation and implementation of the transitional justice process","text":"In its previous report, the team of international experts commended the considerable\nprogress made in the field of transitional justice in Kasai Central Province thanks to the\nimplementation of the peace, justice, reconciliation and reconstruction project and the\nspontaneous surrender project in Kasai and Tanganyika. It urged the Government of the\nDemocratic Republic of the Congo and its development partners to support the effective\nimplementation of the Commission on Truth, Justice and Reconciliation of Kasai Central\nProvince in accordance with international standards and called for the mobilization of the\nresources necessary for it to operate.11"},{"id":"a-hrc-51-60-p0053","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"53","seq":55,"section":"B. Reconciliation and implementation of the transitional justice process","text":"Despite support from Belgium and the United Nations Peacebuilding Fund in funding\nthe transitional justice process throughout the country, as well as technical support from the\nUnited Nations Joint Human Rights Office, the funding gap at the provincial level remains a\nconcern. The team of international experts is concerned about the lack of donor interest in\nfunding the transitional justice process in Kasai and the lack of interest that the provincial\nauthorities have shown in the operation of the provincial Commission on Truth, Justice and\nReconciliation, which has been allocated a paltry budget of only $500. This situation is\nexacerbated by the closure of the peace, justice, reconciliation and reconstruction project in\nApril 2022."},{"id":"a-hrc-51-60-p0054","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"54","seq":56,"section":"B. Reconciliation and implementation of the transitional justice process","text":"Regarding efforts to facilitate the work of the provincial Commission on Truth, Justice\nand Reconciliation, the team of international experts welcomes the steps taken by the newly\nelected provincial authorities with the support of the United Nations Joint Human Rights\nOffice. These steps include the designation of the Commission’s headquarters, the\ndevelopment of a road map for its effective establishment in Kasai Central, the development\nof a code on the organization and functioning of the joint committee in charge of selecting\ncommissioners,12 and the order of the provincial minister of 17 December 2021 appointing\nthe members of the joint committee in charge of selecting candidate commissioners. In\naddition, the team of international experts welcomes the confirmation, by order of the new\nprovincial executive, of the appointment of the elected commissioners to lead the\nCommission in Kasai Central Province and the authorities’ willingness to ensure that\nadequate funding is provided."},{"id":"a-hrc-51-60-p0055","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"55","seq":57,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts emphasizes the need to train the elected\ncommissioners and their staff in the areas of transitional justice, human rights and\ninternational humanitarian law, and suggests that they also receive initial training on their\nmandate.\n2.         Implementation of the transitional justice process at the national level"},{"id":"a-hrc-51-60-p0056","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"56","seq":58,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts notes that two structures have been established at\nthe national level, namely the Joint Steering Commission on Transitional Justice and the\nDisarmament, Demobilization, Community Recovery and Stabilization Programme.\nStructures for implementing the transitional justice process"},{"id":"a-hrc-51-60-p0057","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"57","seq":59,"section":"B. Reconciliation and implementation of the transitional justice process","text":"With regard to the Joint Steering Commission on Transitional Justice, the team of\ninternational experts commends the Congolese Government’s initiative to establish, with the\n11   A/HRC/48/82, paras. 50, 51 and 55.\n12   The code was developed in November 2021 with the support of the United Nations Joint Human\nRights Office, OHCHR and the team of international experts.\nsupport of the United Nations Joint Human Rights Office, a framework for reflection that\ninvolves all key institutions and actors in order to consider different forms of transitional\njustice and develop a national policy in that regard. The team of international experts is also\npleased that this discussion platform, which was launched by the Office of the President and\nis coordinated by the Ministry of Human Rights and the Ministry of Justice, has been able to\nbring together other important bodies, such as the National Human Rights Commission, the\nNational Assembly’s Standing Committee on Human Rights, civil society and the United\nNations Joint Human Rights Office."},{"id":"a-hrc-51-60-p0058","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"58","seq":60,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts also welcomes the development by the Joint Steering\nCommission on Transitional Justice of a specific road map identifying activities to be carried\nout, specific objectives and results to be achieved and an implementation strategy. It notes\nthat the activities planned with a view to initiating the transitional justice process at the\nnational level have been entrusted to specialized subcommissions, namely the\nSubcommission on Truth and the Subcommission on Reparations, which are led by the\nMinistry of Human Rights, and the Subcommission on Justice and the Subcommission on\nGuarantees of Non-Recurrence, which are led by the Ministry of Justice."},{"id":"a-hrc-51-60-p0059","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"59","seq":61,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts was invited by the Ministry of Human Rights to\nparticipate in the opening ceremony of the public consultations held in March 2022 in\nKalemie, Tanganyika Province. Four provinces are concerned in the initial phase of these\nconsultations, namely North Kivu (Goma), Kasai (Tshikapa), Kongo Central (Matadi) and\nTanganyika."},{"id":"a-hrc-51-60-p0060","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"60","seq":62,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts invites the Congolese authorities to carry out more\nnational and subregional initiatives to promote a return to peace in conflict zones and to allow\ncommunities that have expressed a desire to resort to transitional justice mechanisms to\nexpress their needs in terms of truth, reparations, justice and reform through public\nconsultations."},{"id":"a-hrc-51-60-p0061","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"61","seq":63,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts also notes the Government’s efforts to promote\npeace and restore the authority of the State through the implementation of the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme. The development and\nadoption of the national implementation strategy for the Programme places emphasis on an\ninclusive community-based approach and on transitional justice as mechanisms for conflict\nresolution, reconciliation and reparation."},{"id":"a-hrc-51-60-p0062","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"62","seq":64,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts notes with concern that the Programme’s\noperationalization has been delayed and that it is limited to low-impact outreach activities\ndespite the current security context, which is marked by renewed clashes between M23 and\nthe Armed Forces of the Democratic Republic of the Congo in the country’s eastern\nprovinces. The team of international experts therefore urges the authorities of the Democratic\nRepublic of the Congo to expedite the effective implementation of the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme and encourages the\ncountry’s partners, in particular MONUSCO, to develop transitional initiatives to hasten the\nProgramme’s implementation.\n3.     Challenges in the implementation of the transitional justice process in the Democratic\nRepublic of the Congo"},{"id":"a-hrc-51-60-p0063","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"63","seq":65,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The various trips made by the team of international experts to the provinces of North\nKivu, South Kivu, Tanganyika, Ituri and Haut-Katanga have allowed it to identify challenges\nin the implementation of the transitional justice process in the Democratic Republic of the\nCongo. These challenges include: coordination of and adequate communication between the\ndifferent processes under way within the general transitional justice framework, and their\nharmonious implementation; funding of the transitional justice process; consideration of the\ncross-border dimension of conflicts; the question of reparations; and the difficulty of applying\ntransitional justice in a context of insecurity and inter-community conflicts.\n(a)    Coordination of and adequate communication between the different processes under way\nwithin the general transitional justice framework, and their harmonious implementation"},{"id":"a-hrc-51-60-p0064","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"64","seq":66,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts welcomes the Government’s transitional justice\ninitiatives. However, it remains concerned about the coordination, articulation and funding\nof these initiatives, as well as the communication between the persons running them. During\na workshop with the coordinator of the Disarmament, Demobilization, Community Recovery\nand Stabilization Programme on 16 March 2022, the team identified a need for more effective\ncoordination between the various institutions responsible for transitional justice."},{"id":"a-hrc-51-60-p0065","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"65","seq":67,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts found that the only forum for consultation between\nthe Disarmament, Demobilization, Community Recovery and Stabilization Programme and\nthe Ministry of Human Rights is the steering committee, which is a managerial body attached\nspecifically to the Disarmament, Demobilization, Community Recovery and Stabilization\nProgramme and which the Minister of Human Rights or his representative attends as an\nobserver. As a result, there is a risk of overlapping activities, a lack of coherence between\nactivities and confusion among the general public with regard to the roles and responsibilities\nof the various actors."},{"id":"a-hrc-51-60-p0066","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"66","seq":68,"section":"B. Reconciliation and implementation of the transitional justice process","text":"During a meeting between the team of international experts and the Joint Steering\nCommission on Transitional Justice, the members of the Commission complained about the\nabsence of an appropriate legal framework and the lack of independent funding for its\nactivities. Moreover, from a methodological standpoint, the work of the Commission was\nsuspended pending the results of the public consultations, whereas an evaluation of the\ninitiatives that had already taken place in the country, including the work done prior to the\nconsultations, could have been undertaken in parallel.\n(b)    Funding of the transitional justice process"},{"id":"a-hrc-51-60-p0067","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"67","seq":69,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts is concerned that the transitional justice process is\nlargely dependent on external funding. It strongly emphasizes the need for national funding,\nwhich is the only way to ensure credibility, coherence and sustainability.\n(c)   Consideration of the cross-border dimension of conflicts"},{"id":"a-hrc-51-60-p0068","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"68","seq":70,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The cross-border aspect of current conflicts and the need to take these aspects into\naccount in the transitional justice process in the Democratic Republic of the Congo were\npreviously illustrated by the report on the mapping exercise and are currently reflected in the\nNairobi process. The various field visits that the team of international experts made,\nparticularly to the provinces of North Kivu, South Kivu and Ituri, helped it to come to a better\nunderstanding of the dynamics of the conflicts, in which the parties are located on both sides\nof the borders of the Democratic Republic of the Congo."},{"id":"a-hrc-51-60-p0069","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"69","seq":71,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts learned from various interlocutors that the growing\nthreat represented by armed groups is the result of competition for the country’s agricultural,\npastoral, mining and land resources, its porous borders and a lack of State authority, and that\nthese armed groups are proliferating, often in collusion with foreign armed groups linked to\nnational or international interest groups in neighbouring countries or further afield."},{"id":"a-hrc-51-60-p0070","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"70","seq":72,"section":"B. Reconciliation and implementation of the transitional justice process","text":"In addition, other factors, such as the disintegration of the social fabric, the declining\ninfluence of traditional authorities, the greed of professional or opportunistic businessmen,\nboth national and foreign, and the general impoverishment of the population, contribute to\nthe proliferation of all sorts of actors in the Democratic Republic of the Congo.\n(d)    The question of reparations"},{"id":"a-hrc-51-60-p0071","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"71","seq":73,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The workshop on transitional justice allowed the team of international experts to better\nunderstand the challenges faced by victims in terms of reparation. The right to reparation for\nvictims is primarily addressed at the judicial level, particularly by the military courts.\nHowever, for the military courts, the issue of reparation is an accessory one, especially since\nit cannot be raised by victims in the context of direct summons proceedings. Moreover, a\ntendency to grant victims uniform reparation for harm caused, without individualization, has\nbeen observed. This standardization reduces reparations to the level of compensation. Lastly,\nin most cases, in the event of a conviction, payment of compensation is significantly delayed,\nand is sometimes hampered by the insolvency of the perpetrators. 13"},{"id":"a-hrc-51-60-p0072","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"72","seq":74,"section":"B. Reconciliation and implementation of the transitional justice process","text":"In a judgment of 9 February 2022, the International Court of Justice, to which the\nDemocratic Republic of the Congo had filed a complaint against Rwanda and Uganda after\ntheir armies clashed in Kisangani from 5 to 10 June 2000, causing numerous casualties and\nsignificant material damage, ordered Uganda to pay $325 million in reparations to the\nDemocratic Republic of the Congo.14 The question of the shares of this sum to be distributed\nto individual victims remains to be clarified.15"},{"id":"a-hrc-51-60-p0073","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"73","seq":75,"section":"B. Reconciliation and implementation of the transitional justice process","text":"With regard to non-judicial reparations, it is important to note that collective\nreparations are not the most appropriate means of addressing the multiple harms suffered by\nvictims of mass crimes."},{"id":"a-hrc-51-60-p0074","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"74","seq":76,"section":"B. Reconciliation and implementation of the transitional justice process","text":"In contrast, the Panzi Foundation and the Global Survivors Fund have adopted a\ncomprehensive approach to non-judicial reparations for victims by combining clinical\nmeasures, psychotherapeutic methods and social reintegration."},{"id":"a-hrc-51-60-p0075","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"75","seq":77,"section":"B. Reconciliation and implementation of the transitional justice process","text":"Lastly, the prospect of a national reparations fund is taking shape in the form of a\nspecial bill, including a funding proposal, to develop and implement a national reparations\npolicy."},{"id":"a-hrc-51-60-p0076","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"76","seq":78,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts hopes that the discussion concerning this bill will\ntake due account, on the one hand, of the uniqueness of the problems posed by the question\nof providing reparations for the harm suffered by the millions of victims of the\nmultigenerational and multidimensional conflicts that have ravaged the Democratic Republic\nof the Congo in the absence of a strong State and, on the other hand, of the meagre results\nobtained so far through the international courts. The involvement of women, traditional\nleaders and researchers specializing in the history and social and cultural anthropology of the\nDemocratic Republic of the Congo will enhance the effectiveness of the process and the real\nimpact of transitional justice.\n(e)        Difficulty of applying transitional justice in a context of insecurity and inter-community\nconflicts"},{"id":"a-hrc-51-60-p0077","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"77","seq":79,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The team of international experts notes that the transitional justice process is taking\nplace in a country where part of the territory is in a post-conflict situation, while in the other\nparts insecurity, violence and conflict not only continue but seem far from abating. Owing to\nthis situation, the transitional justice process in the Democratic Republic of the Congo must\ndepart from existing models and take a pragmatic approach that accommodates the diversity\nof local circumstances and the needs of the population."},{"id":"a-hrc-51-60-p0078","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"78","seq":80,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The discussions that the team of international experts held with the authorities and\nrepresentatives of the populations of the provinces of North Kivu, South Kivu, Tanganyika\nand Ituri revealed the importance of acting without waiting for the conflicts to end. These\ndiscussions made clear the urgency of taking immediate steps towards transitional justice to\ncurb the spread of current conflicts, to stifle hate speech and calls for violence and\ndiscrimination, to develop a strategy of targeted prosecutions and to seize opportunities for\ndisarming combatants and resolving conflicts before the chance to do so is lost. An analysis\nof the causes of these conflicts is essential in order to shape the contours of sustainable\nsolutions. Immediate solutions are required, in view of the ever-increasing number of victims\nliving in untenably precarious and vulnerable situations."},{"id":"a-hrc-51-60-p0079","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"79","seq":81,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The other essential dimension of transitional justice is the identification of the causes\nof the conflicts, the study of their impact and the analysis of the prospects for resolution\nbeyond the country’s borders, given the presence of the same communities on both sides of\nthe borders and the involvement of many neighbouring countries in the ongoing conflicts."},{"id":"a-hrc-51-60-p0080","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"80","seq":82,"section":"B. Reconciliation and implementation of the transitional justice process","text":"Accordingly, the team of international experts organized a workshop on transitional\njustice with the Ministry of Human Rights and the United Nations Joint Human Rights Office\nfrom 19 to 21 July 2022 to take stock of the situation and study options for developing a\nnational policy."},{"id":"a-hrc-51-60-p0081","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"81","seq":83,"section":"B. Reconciliation and implementation of the transitional justice process","text":"This workshop brought together members of parliament, senators, representatives of\nthe Office of the President and of the various ministries concerned, the diplomatic\ncommunity, academic figures and civil society."},{"id":"a-hrc-51-60-p0082","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"82","seq":84,"section":"B. Reconciliation and implementation of the transitional justice process","text":"The objective of the workshop was to facilitate the articulation, conceptualization and\ncoordination of different elements of the transitional justice policy and to work on the\ncommunication campaign that would accompany it. The following topics were discussed:\n• Consultations initiated within the framework of the transitional justice process in the\nDemocratic Republic of the Congo\n• Evaluation of Congolese criminal policy in the context of transitional justice\n• Lessons learned from the decentralized model in Kasai Central\n• Harmonization of the National Disarmament, Demobilization, Community Recovery\nand Stabilization Programme\n• Links and coordination between disarmament, demobilization and reintegration\nactivities and transitional justice\n• Strategy for harmonizing current transitional justice initiatives\n• Transitional justice in the context of justice reform\n• Forms and modalities of the victims’ right to reparation\n• Adopting a victim-centred approach in the development of a transitional justice\nstrategy\n• Transitional justice funding mechanisms\n• Reforms with a view to the non-repetition of past crimes\n• Use of forensics in the transitional justice process"},{"id":"a-hrc-51-60-p0083","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"83","seq":85,"section":"B. Reconciliation and implementation of the transitional justice process","text":"At the end of the workshop, the participants recommended that an expanded scientific\ncommittee be set up to draft a discussion paper on the national transitional justice policy in\nthe Democratic Republic of the Congo with a view to facilitating the development of a road\nmap that will ensure the policy’s smooth implementation."},{"id":"a-hrc-51-60-p0084","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"84","seq":86,"section":"A. Conclusions","text":"The team of international experts would not have been able to play its role in\nassessing, supporting and assisting the Democratic Republic of the Congo without the\nfull cooperation, goodwill and availability of the Congolese Government, for which it\nexpresses its thanks."},{"id":"a-hrc-51-60-p0085","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"85","seq":87,"section":"A. Conclusions","text":"In addition, the trust, openness and willingness to engage in dialogue shown by\nthe Congolese people, their traditional and religious leaders, civil society and the\ninternational community in Kinshasa, as well as the continuous support of the United\nNations Joint Human Rights Office and MONUSCO, allowed the team of international\nexperts to grasp the complexity and nuances of the situation in the Democratic Republic\nof the Congo and to use this experience to develop its recommendations."},{"id":"a-hrc-51-60-p0086","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"86","seq":88,"section":"A. Conclusions","text":"Early in the reporting period, progress in Kasai confirmed the wisdom of the\nGovernment’s decision to pursue a transitional justice process that is province-based,\ncentrally coordinated and supported by the United Nations and the international\ncommunity. In this context, public consultations were launched, a structure for\ncoordinating the various aspects of transitional justice was set up under the auspices of\nthe Office of the President and leadership of the Ministry of Human Rights, and a\nprocess of disarmament and reintegration was initiated along with a strategy of\ntargeted prosecutions."},{"id":"a-hrc-51-60-p0087","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"87","seq":89,"section":"A. Conclusions","text":"Recent attacks by M23 have highlighted the challenge posed by the long tradition\nof impunity in the Democratic Republic of the Congo, particularly for the crimes\ndocumented in the report on the mapping exercise, the centrality of the cross-border\nnature of the ongoing conflicts and insecurity, and, through the Nairobi process, the\nneed to involve the subregion in the search for lasting solutions, including the\nidentification of the root causes of the conflicts and the prevention of their recurrence,\nas well as in the transitional justice process as a whole."},{"id":"a-hrc-51-60-p0088","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"88","seq":90,"section":"A. Conclusions","text":"The current challenges are compounded by the structural weaknesses of the\nDemocratic Republic of the Congo. This general weakness extends to its administrative\nand judicial structures, the lack of a State presence and State authority over an\nimmense territory, which has a direct impact on the rule of law, and the wholly\ninadequate operation and funding of State institutions, which fail to meet the needs of\na population exposed to various forms of vulnerability and exploitation."},{"id":"a-hrc-51-60-p0089","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"89","seq":91,"section":"A. Conclusions","text":"Protecting the population will require a sustained effort to rebuild the State,\nwhich must go hand in hand with the implementation of transitional justice and the\nfight against impunity."},{"id":"a-hrc-51-60-p0090","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"90","seq":92,"section":"B. Recommendations","text":"While reiterating the need to pursue the implementation of the recommendations\nmade in its previous reports,16 the team of international experts makes the following\nadditional recommendations.\n1.        Conceptualization, articulation and communication strategy with regard to the\ntransitional justice policy and the fight against impunity"},{"id":"a-hrc-51-60-p0091","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"91","seq":93,"section":"B. Recommendations","text":"With a view to improving the visibility of the Government’s efforts, promoting\ncommunication about them and fostering ownership of the transitional justice policy by\nthe population, the team of international experts stresses the importance of promptly\nadopting an appropriate communication policy on the implementation of transitional\njustice and recommends that the Government give priority to the development of such\na policy."},{"id":"a-hrc-51-60-p0092","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"92","seq":94,"section":"B. Recommendations","text":"The team of international experts recommends the prompt and efficient\nestablishment of an expanded scientific committee, as recommended by the participants\nin the workshop on transitional justice held in Kinshasa from 19 to 21 July 2022.\n2.        Prevention of impunity"},{"id":"a-hrc-51-60-p0093","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"93","seq":95,"section":"B. Recommendations","text":"The team of international experts encourages the Government to continue\ndeveloping a policy of targeted prosecutions, province by province, as was done in Kasai\nin the context of the Kamuina Nsapu militia crisis, including in respect of the crimes\nand human rights violations documented in the report on the mapping exercise."},{"id":"a-hrc-51-60-p0094","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"94","seq":96,"section":"B. Recommendations","text":"The team of international experts recommends that the Government establish a\ncentralized biometric identification system as part of the process of disarming and\ndemobilizing combatants to allow for systematic background checks, which will be\nparticularly pertinent in the context of security sector reform, the conduct of\nprosecutions and the establishment of a nationwide civil administrative system."},{"id":"a-hrc-51-60-p0095","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"95","seq":97,"section":"B. Recommendations","text":"The team of international experts supports the Chief Military Prosecutor’s\nrequests for the waiver of army generals’ immunity, as well as the Congolese\nGovernment’s review of current policies on amnesty, immunity and integration of\nformer combatants (mixage and brassage), which constitute significant obstacles to\nending impunity."},{"id":"a-hrc-51-60-p0096","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"96","seq":98,"section":"B. Recommendations","text":"The team of international experts recommends that the Human Rights Council\ncontinue the deployment and strengthen the capacities of the forensic technical\nassistance team by increasing the size of the team and providing it with additional\nresources, including effective tools for collecting evidence to facilitate justice and\nmemory work.\n3.    Consideration of victims at all stages of the process"},{"id":"a-hrc-51-60-p0097","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"97","seq":99,"section":"B. Recommendations","text":"The team of international experts welcomes the Government’s decision to\nprepare a bill on a policy of reparations for victims and recommends that victims’ needs\nfor protection, immediate and other assistance, and reparation be taken into\nconsideration at all stages of the transitional justice process.\n4.    Conflict prevention and guarantees of non-repetition"},{"id":"a-hrc-51-60-p0098","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"98","seq":100,"section":"B. Recommendations","text":"The team of international experts urges the legislature to promptly adopt and\ngive effect to the bill on the nationwide prevention and punishment of hate speech and\nof calls for violence and discrimination."},{"id":"a-hrc-51-60-p0099","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"99","seq":101,"section":"B. Recommendations","text":"The team of international experts recommends that the Government prioritize\nthe analysis of the current conflicts and the use of factual history to help dispel the\nmyths that continue to fuel discrimination and conflict in the Democratic Republic of\nthe Congo."},{"id":"a-hrc-51-60-p0100","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"100","seq":102,"section":"B. Recommendations","text":"The team of international experts encourages the Government to look into the\nreasons for the failure of previous reconciliation and peace negotiations and strategies,\nincluding the Addis Ababa Agreement, the Great Lakes Pact and the Nairobi process,\nand to take due account of the lessons learned from them when implementing the\ncurrent transitional justice process."},{"id":"a-hrc-51-60-p0101","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"101","seq":103,"section":"B. Recommendations","text":"The team of international experts recommends that the Government develop a\nplan for administrative reform to complement the current security and judicial sector\nreform programmes. The three reform programmes should be implemented together\nso as to be mutually reinforcing."},{"id":"a-hrc-51-60-p0102","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"102","seq":104,"section":"B. Recommendations","text":"The team of international experts encourages the Government to establish an\nappropriate, high-quality training programme for its senior officials, taking into\naccount the gradual withdrawal of MONUSCO and the need to ensure the\nsustainability of the planned reforms."},{"id":"a-hrc-51-60-p0103","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"103","seq":105,"section":"B. Recommendations","text":"The team of international experts welcomes the recognition by the Nairobi\nprocess of the cross-border nature of the ongoing conflicts and insecurity and\nrecommends that the subregion become more closely involved in identifying the causes\nof conflicts and preventing their recurrence, and that it strengthen the transitional\njustice aspect of its work, rather than limiting itself to the political and military aspects.\n5.    Public, private and international funding of the transitional justice process"},{"id":"a-hrc-51-60-p0104","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"104","seq":106,"section":"B. Recommendations","text":"The team of international experts notes with regret the inadequacy of the\nresources made available to the transitional justice process in the Kasai region and\nstresses the need for sufficient and sustainable funding for all aspects of transitional\njustice and State reform as a prerequisite for their success."},{"id":"a-hrc-51-60-p0105","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"105","seq":107,"section":"B. Recommendations","text":"The team of international experts urges the Government to redouble its efforts\nto ensure that its transitional justice and State reform initiatives are funded from the\nnational budget at both the provincial and central levels. Such financial efforts will\nreinforce the political will reiterated by the Government, ensure the immediacy and\nsustainability of transitional justice projects, and encourage increased bilateral and\nmultilateral cooperation in their funding."},{"id":"a-hrc-51-60-p0106","rec_id":"recenyyVjQEwTjwtP","symbol":"A/HRC/51/60","n":"106","seq":108,"section":"B. Recommendations","text":"In addition, given the considerable level of funding required for the\nimplementation of transitional justice, the team of international experts recommends\nthat the Government develop a policy that would organize the contributions of national\nand multinational companies operating in the Democratic Republic of the Congo to the\nfunding of peace, reconciliation, stability and sustainable development initiatives."},{"id":"a-hrc-54-76-u0000","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":null,"seq":0,"section":null,"text":"Nations Unies                                                                                      A/HRC/54/76\nAssemblée générale                                                           Distr. générale\n10 août 2023","unnumbered":true},{"id":"a-hrc-54-76-u0001","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":null,"seq":1,"section":null,"text":"Résumé\nDans sa résolution 51/36 du 7 octobre 2022, le Conseil des droits de l’homme a\nrenouvelé le mandat de l’Équipe d’experts internationaux en République démocratique du\nCongo et lui a demandé d’apporter l’appui technique nécessaire au Gouvernement dans la\nmise en œuvre de la stratégie nationale de justice transitionnelle. Le Conseil a demandé en\noutre à l’Équipe d’experts internationaux de lui présenter son rapport final à sa\ncinquante-quatrième session, dans le cadre d’un dialogue interactif renforcé, ainsi qu’une\nmise à jour orale à sa cinquante-deuxième session.\nL’exécution de ce mandat élargi intervient dans un contexte de retrait progressif de la\nMission de l’Organisation des Nations Unies pour la stabilisation en République\ndémocratique du Congo, d’aggravation de la situation sécuritaire et de préparation\nd’échéances électorales.\nDans le cadre de son mandat élargi, l’Équipe d’experts internationaux a effectué\nquatre visites de terrain et organisé, avec le Ministère des droits humains et le Bureau\nconjoint des Nations Unies pour les droits de l’homme en République démocratique du\nCongo, deux ateliers : l’un sur l’évaluation de la mise en œuvre des différentes\nrecommandations issues de ses rapports antérieurs, et l’autre sur l’écriture du plan d’action\nstratégique du Ministère des droits humains en matière de justice transitionnelle. Elle a\nparticipé à Kananga à l’atelier de validation des textes de fonctionnement de la Commission\nprovinciale vérité, justice et réconciliation au Kasaï-Central et à la signature d’un protocole\nd’accord entre la Commission et le Bureau conjoint, qui ont été suivis du lancement officiel\ndes activités de la Commission.","unnumbered":true},{"id":"a-hrc-54-76-u0002","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":null,"seq":2,"section":null,"text":"L’exacerbation des attaques du M23 et la facilitation de la Communauté d’Afrique de\nl’Est dans le cadre du processus de Nairobi ont souligné la nécessité de la prise en compte\ndes aspects transfrontaliers des conflits et de la justice transitionnelle.\nÀ cet effet, l’Équipe d’experts internationaux a tenu une réunion virtuelle avec\nl’Envoyé spécial du Secrétaire général pour la région des Grands Lacs, sur la prise en compte\nde la justice transitionnelle dans les initiatives sous-régionales de règlement des conflits en\nRépublique démocratique du Congo.\nL’Équipe d’experts internationaux a enfin proposé des conclusions et formulé des\nrecommandations en vue de renforcer les actions en cours et à venir.","unnumbered":true},{"id":"a-hrc-54-76-p0001","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"1","seq":3,"section":"I. Introduction","text":"Dans sa résolution 51/36 du 7 octobre 2022, le Conseil des droits de l’homme a\nrenouvelé le mandat de l’Équipe d’experts internationaux en République démocratique du\nCongo et lui a demandé d’apporter l’appui technique nécessaire au Gouvernement dans la\nmise en œuvre de la stratégie nationale sur la justice transitionnelle. Le Conseil a demandé\nen outre à l’Équipe d’experts internationaux de lui présenter son rapport final à sa\ncinquante-quatrième session, dans le cadre d’un dialogue interactif renforcé, ainsi qu’une\nmise à jour orale à sa cinquante-deuxième session. Le présent rapport s’inscrit dans\nl’exécution de la résolution susmentionnée."},{"id":"a-hrc-54-76-p0002","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"2","seq":4,"section":"I. Introduction","text":"Dans la même résolution, le Conseil des droits de l’homme a demandé au\nHaut-Commissaire des Nations Unies aux droits de l’homme de continuer à fournir au\nGouvernement de la République démocratique du Congo l’assistance technique, y compris\nl’expertise médico-légale nécessaire, pour appuyer les autorités judiciaires du pays dans leurs\nenquêtes sur les allégations de violations des droits de l’homme et d’atteintes à ces droits afin\nque leurs auteurs soient traduits en justice, et de renforcer l’équipe d’assistance technique\nd’experts médico-légaux supplémentaires en lui octroyant des moyens suffisants pour qu’elle\naide le Gouvernement à se doter de capacités nationales spécialisées dans le domaine de la\nmédecine légale."},{"id":"a-hrc-54-76-p0003","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"3","seq":5,"section":"I. Introduction","text":"Le Conseil des droits de l’homme a enfin demandé au Haut-Commissaire de mettre à\nla disposition du Gouvernement de la République démocratique du Congo plus d’experts en\njustice transitionnelle dont la mission serait d’apporter une assistance technique à la rédaction\nstratégique et à l’adoption d’outils méthodologiques nécessaires au fonctionnement du fonds\nde réparation et des commissions provinciales de vérité et réconciliation, conformément aux\nnormes et aux instruments internationaux."},{"id":"a-hrc-54-76-p0004","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"4","seq":6,"section":"I. Introduction","text":"Le 29 novembre 2022, le Haut-Commissaire des Nations Unies aux droits de l’homme\na nommé Bacre Waly Ndiaye (Sénégal) Président et Marie-Thérèse Keita-Bocoum\n(Côte d’Ivoire) membre de l’Équipe d’experts internationaux. Le 30 janvier 2023, le\nHaut-Commissaire a nommé Marie-Thérèse Keita-Bocoum Présidente de l’Équipe d’experts\ninternationaux en remplacement de Bacre Waly Ndiaye (élu membre du Comité des droits\nde l’homme) et, le 9 juin 2023, a nommé Bessolé René Bagoro (Burkina Faso) membre de\nl’Équipe d’experts internationaux."},{"id":"a-hrc-54-76-p0005","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"5","seq":7,"section":"I. Introduction","text":"L’Équipe d’experts internationaux est appuyée par un secrétariat composé d’un\ncoordonnateur et d’un fonctionnaire des droits de l’homme spécialiste de la justice\ntransitionnelle. En 2023, elle a effectué quatre visites de terrain en République démocratique\ndu Congo : du 14 au 27 janvier, du 14 au 29 mai, du 21 juin au 6 juillet et, enfin, du 20 juillet\nau 5 août."},{"id":"a-hrc-54-76-p0006","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"6","seq":8,"section":"I. Introduction","text":"À l’occasion de ces visites, l’Équipe d’experts internationaux a rencontré diverses\npersonnalités, notamment le Président de l’Assemblée nationale ; le Vice-Premier Ministre\net Ministre de la défense et des anciens combattants ; le Ministre d’État, Ministre de la justice\net Garde des sceaux ; la Directrice de cabinet adjointe du Président de la République chargée\ndes questions politiques, juridiques et diplomatiques ; le Ministre des droits humains ; le\nMinistre des communications et des médias, porte-parole du Gouvernement ; le Président de\nla Commission nationale des droits de l’homme ; le Président de la Commission des droits\nde l’homme de l’Assemblée nationale ; le Secrétaire permanent du Conseil supérieur de la\nmagistrature ; l’Auditeur général des Forces armées de la République démocratique du\nCongo ; le Coordonnateur national du Programme de désarmement, de démobilisation, de\nrelèvement communautaire et de stabilisation ; le Gouverneur de la province du\nKasaï-Central ; et des membres du corps diplomatique accrédités en République\ndémocratique du Congo, y compris les ambassadeurs du Groupe africain ainsi que les\nreprésentants de l’Union africaine et de l’Union européenne."},{"id":"a-hrc-54-76-p0007","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"7","seq":9,"section":"I. Introduction","text":"Au cours de sa première visite, l’Équipe d’experts internationaux a organisé à\nKinshasa, les 25 et 26 janvier 2023, un atelier d’évaluation de la mise en œuvre des\nrecommandations issues de ses rapports publiés depuis le début de son mandat, soit de 2018\nà 2022. Elle a ensuite participé à l’atelier de formation initiale des commissaires de la\nCommission provinciale vérité, justice et réconciliation au Kasaï-Central organisé par le\nBureau conjoint des Nations Unies pour les droits de l’homme en République démocratique\ndu Congo (BCNUDH) du 23 au 27 janvier 2023."},{"id":"a-hrc-54-76-p0008","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"8","seq":10,"section":"I. Introduction","text":"Lors de sa deuxième visite, l’Équipe d’experts internationaux s’est rendue à Kinshasa\net à Kananga, dans la province du Kasaï-Central. Au cours de la mission de terrain à Kananga,\nelle a relevé les difficultés et défis relatifs au démarrage effectif de la Commission provinciale\nvérité, justice et réconciliation au Kasaï-Central. À cet effet, elle a rencontré le Gouverneur\nde la province, l’Auditeur militaire supérieur de l’ancienne province du Kasaï-Occidental,\nl’Association des victimes du grand Kasaï, le Coordonnateur provincial de l’organisation non\ngouvernementale TRIAL International, les représentants des confessions religieuses, les\nchefs coutumiers, les représentants du système des Nations Unies ainsi que les commissaires\nde la Commission provinciale vérité, justice et réconciliation au Kasaï-Central. Avec ses\ninterlocuteurs, l’Équipe d’experts internationaux a échangé sur le niveau d’engagement des\nautorités provinciales dans le cadre du soutien à la Commission, l’appui que l’Équipe\nd’experts internationaux pourrait lui apporter ainsi que les stratégies de mobilisation des\nressources financières nécessaires. Elle s’est également informée des progrès réalisés dans\nles domaines de la lutte contre l’impunité et de la mise en œuvre de la justice transitionnelle."},{"id":"a-hrc-54-76-p0009","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"9","seq":11,"section":"I. Introduction","text":"À l’occasion de sa troisième visite, l’Équipe d’experts internationaux s’est entretenue\nà Kinshasa avec des membres du Gouvernement, du corps diplomatique, du système des\nNations Unies et des organisations de la société civile, pour s’enquérir de l’état d’avancement\nde la lutte contre l’impunité et de la mise en œuvre de la justice transitionnelle."},{"id":"a-hrc-54-76-p0010","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"10","seq":12,"section":"I. Introduction","text":"Le 13 juillet 2023, l’Équipe d’experts internationaux a tenu une réunion virtuelle avec\nl’Envoyé spécial du Secrétaire général pour la région des Grands Lacs. La réunion a porté\nsur la prise en compte de la justice transitionnelle dans les initiatives sous-régionales de\nrèglement des conflits en République démocratique du Congo."},{"id":"a-hrc-54-76-p0011","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"11","seq":13,"section":"I. Introduction","text":"Durant sa quatrième visite, l’Équipe d’experts internationaux a participé à Kananga,\nles 24 et 25 juillet 2023, à l’atelier d’appropriation et de validation des textes de\nfonctionnement de la Commission provinciale vérité, justice et réconciliation au\nKasaï-Central, en l’occurrence le règlement intérieur et le manuel de procédures. En marge\nde cette activité, elle a également assisté au lancement officiel des activités de la Commission,\nprécédé de la signature de l’accord portant cadre de coopération technique entre la\nCommission et le BCNUDH."},{"id":"a-hrc-54-76-p0012","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"12","seq":14,"section":"I. Introduction","text":"Du 25 au 27 juillet 2023, à Zongo, dans la province du Kongo-Central, l’Équipe\nd’experts internationaux a coorganisé avec le Ministère des droits humains et le BCNUDH\nla retraite d’écriture du plan d’action stratégique dudit ministère en matière de justice\ntransitionnelle."},{"id":"a-hrc-54-76-p0013","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"13","seq":15,"section":"I. Introduction","text":"Conformément à la résolution 51/36 du Conseil des droits de l’homme, l’Équipe\nd’experts internationaux a présenté le 30 mars 2023 son rapport sur la situation en République\ndémocratique du Congo lors du dialogue interactif tenu dans le cadre de la\ncinquante-deuxième session du Conseil."},{"id":"a-hrc-54-76-p0014","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"14","seq":16,"section":"I. Introduction","text":"Le présent rapport est conforme aux dispositions de la résolution 51/36 du Conseil\ndes droits de l’homme. Il met en relief les différentes actions menées par l’Équipe d’experts\ninternationaux dans le cadre de l’exécution de son mandat élargi."},{"id":"a-hrc-54-76-p0015","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"15","seq":17,"section":"II. Mandat","text":"L’Équipe d’experts internationaux a organisé au début de sa mission un atelier\nd’évaluation de la mise en œuvre des différentes recommandations issues des rapports\nantérieurs1 qu’elle a présentés devant le Conseil des droits de l’homme. Cet atelier, qui a eu\nlieu les 25 et 26 janvier 2023, a regroupé des représentants des départements ministériels,\nd’ambassades, d’autorités judiciaires et de la société civile. Cette évaluation intérimaire a\npermis à l’Équipe d’experts internationaux de mesurer le niveau de progrès réalisé par la\nRépublique démocratique du Congo depuis la mise en place du mandat de l’Équipe d’experts\ninternationaux, en 2018."},{"id":"a-hrc-54-76-p0016","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"16","seq":18,"section":"II. Mandat","text":"L’exécution du mandat de l’Équipe d’experts internationaux intervient dans un\ncontexte où la République démocratique du Congo fait toujours face à une insécurité dans sa\npartie orientale, en raison de l’agression du pays par le Mouvement du 23 mars (M23) et de\nla présence de plusieurs groupes armés dans la région."},{"id":"a-hrc-54-76-p0017","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"17","seq":19,"section":"II. Mandat","text":"Hormis le contexte sécuritaire, la mise en œuvre du mandat intervient également dans\nun contexte de retrait de la Mission de l’Organisation des Nations Unies pour la stabilisation\nen République démocratique du Congo et de mise en place d’une stratégie de transition pour\nassurer la poursuite de l’appui des Nations Unies à la République démocratique du Congo."},{"id":"a-hrc-54-76-p0018","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"18","seq":20,"section":"II. Mandat","text":"Ce processus de retrait a eu un impact sur l’appui logistique indispensable à la mise\nen œuvre du mandat de l’Équipe d’experts internationaux."},{"id":"a-hrc-54-76-p0019","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"19","seq":21,"section":"II. Mandat","text":"Nonobstant la situation ainsi décrite, l’Équipe d’experts internationaux a pu effectuer\nquatre visites de terrain en République démocratique du Congo et apporter un appui\nsignificatif au Gouvernement."},{"id":"a-hrc-54-76-p0020","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"20","seq":22,"section":"III. Coopération entre l’Équipe d’experts internationaux","text":"Durant la période couverte par son mandat, l’Équipe d’experts internationaux a\nbénéficié d’une franche coopération avec les autorités de la République démocratique du\nCongo, notamment des facilités administratives pour ses visites dans le pays."},{"id":"a-hrc-54-76-p0021","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"21","seq":23,"section":"III. Coopération entre l’Équipe d’experts internationaux","text":"Lors de chacune de ses visites, l’Équipe d’experts internationaux a rencontré des\nprésidents d’institutions, des membres du Gouvernement et des autorités judiciaires du pays,\ndes membres du corps diplomatique et du système des Nations Unies, des représentants de la\nsociété civile, y compris des femmes et des jeunes, des chefs coutumiers et des autorités\nreligieuses. Cette franche coopération a constitué un atout pour la mise en œuvre du mandat\nde l’Équipe d’experts internationaux."},{"id":"a-hrc-54-76-p0022","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"22","seq":24,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux déplore la poursuite du conflit dans l’est de la\nRépublique démocratique du Congo. Exacerbée par l’attaque du M23, cette crise connaît une\nextension dans plusieurs localités de la province du Nord-Kivu, avec l’utilisation massive\nd’armes et d’explosifs. Elle entraîne par ailleurs d’importants mouvements de population."},{"id":"a-hrc-54-76-p0023","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"23","seq":25,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux note qu’après le retrait du M23 en mars 2023 de\ncertaines zones importantes, notamment le sud-ouest de Rutshuru et le nord-est de Masisi,\non assiste depuis avril 2023 à de nouveaux affrontements entre le M23 et les groupes armés\nlocaux et les Forces démocratiques de libération du Rwanda dans ces zones2."},{"id":"a-hrc-54-76-p0024","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"24","seq":26,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux est également préoccupée par la situation\nsécuritaire dans le territoire de Kabambare, dans la province du Maniema, où, selon un\nrapport du BCNUDH3, il y a eu en juillet 2023 de violents affrontements entre les groupes\narmés Maï-Maï Hercule et les groupes d’autodéfense de Masiya au chef-lieu du secteur de\nKabeya.\n2 Groupe mondial de la protection en République démocratique du Congo, « Points saillants de\nprotection − Avril-mai 2023 », p. 1.\n3 BCNUDH, « Note du BCNUDH Uvira sur la situation des droits de l’homme dans le territoire de\nKabambare (Province du Maniema), à la suite des violents affrontements du 15 juillet 2023, entre les\ngroupes armés Maï-Maï Malaika/Hercule et les autodéfenses de Masiya, au chef-lieu du Secteur des\nBabuyu (territoire de Kabambare, province du Maniema) », 17 juillet 2023."},{"id":"a-hrc-54-76-p0025","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"25","seq":27,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"La réunion virtuelle entre l’Équipe d’experts internationaux et l’Envoyé spécial du\nSecrétaire général pour la région des Grands Lacs tenue le 13 juillet 2023 a conforté l’idée\nselon laquelle le conflit dans l’est de la République démocratique du Congo est alimenté par\ndes groupes armés tant nationaux qu’étrangers. Certains groupes armés nationaux bénéficient\nde l’appui de pays étrangers."},{"id":"a-hrc-54-76-p0026","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"26","seq":28,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux est préoccupée par la lenteur de la mise en œuvre\ndes décisions et conclusions issues du processus de Nairobi, sous l’égide de la Communauté\nd’Afrique de l’Est, et de la feuille de route de Luanda. Au moment de la finalisation du\nprésent rapport, le précantonnement ou le cantonnement de plusieurs groupes armés très\nactifs dans l’est du pays n’avait toujours pas commencé. Un désarmement effectif suivi d’un\ncantonnement permettra un retour au calme et ouvrira la voie à la mise en œuvre du\nProgramme de désarmement, de démobilisation, de relèvement communautaire et de\nstabilisation. L’Équipe d’experts internationaux appelle à la mise en œuvre rapide des\ndécisions des processus de Luanda et de Nairobi, y compris le désarmement effectif de tous\nles groupes armés."},{"id":"a-hrc-54-76-p0027","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"27","seq":29,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux note avec satisfaction que, lors de l’audience lui\nayant été accordée le 22 juin 2023, le Vice-Premier Ministre et Ministre de la Défense et des\nanciens combattants a souligné la nécessité de désarmer les groupes armés et d’intégrer dans\nle Programme de désarmement, de démobilisation, de relèvement communautaire et de\nstabilisation les membres de ces groupes qui y étaient admissibles. Elle se félicite de la\ndisposition du Gouvernement de la République démocratique du Congo à poursuivre la\nconstruction des camps de cantonnement, et encourage à cet effet la communauté\ninternationale à soutenir cette initiative."},{"id":"a-hrc-54-76-p0028","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"28","seq":30,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux relève le lien évident qui existe entre l’insécurité\nqui sévit dans plusieurs localités du pays et l’absence de l’État dans ces zones. Elle prend\nnote des réformes en cours au Ministère de la défense qui visent, d’ici à la fin de l’année 2023,\nun déploiement de militaires pour renforcer leur présence sur l’ensemble du territoire\nnational."},{"id":"a-hrc-54-76-p0029","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"29","seq":31,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"Sur le plan humanitaire, l’Équipe d’experts internationaux déplore que rien qu’au\npremier trimestre de 2023, il y ait eu près de 677 000 nouvelles personnes déplacées à\nl’intérieur de leur propre pays, dont 51 % de femmes. Plus de 98 % de ces déplacements sont\ndus aux attaques et aux affrontements armés. Les principales provinces touchées sont celles\ndu Sud-Kivu, du Nord-Kivu et de l’Ituri4."},{"id":"a-hrc-54-76-p0030","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"30","seq":32,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux est préoccupée par l’augmentation des cas de\nviolations et d’abus, notamment des violences basées sur le genre et des violences sexuelles\nliées aux conflits dans les sites de personnes déplacées autour de Goma, ainsi que par la\nrecrudescence des attaques perpétrées contre des civils5."},{"id":"a-hrc-54-76-p0031","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"31","seq":33,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux déplore l’existence de « maisons de tolérance » ou\nmaisons de prostitution dans les camps de personnes déplacées où, du fait de leur\nvulnérabilité, de nombreuses femmes et filles font l’objet d’exploitation et d’abus sexuels.\nCe phénomène, qui s’amplifie, impliquerait des agents responsables de la sécurité des camps."},{"id":"a-hrc-54-76-p0032","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"32","seq":34,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux souligne que les cas de viols à l’égard des femmes\nont un impact négatif sur leur intégrité physique et morale, et déstabilisent la cohésion\nfamiliale et le tissu social. De plus, les enfants nés de ces viols, souvent abandonnés, peuvent\nêtre des proies pour les groupes armés."},{"id":"a-hrc-54-76-p0033","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"33","seq":35,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux s’inquiète de la détérioration de la situation\nhumanitaire consécutive aux conflits intercommunautaires dans le territoire de Kwamouth,\nnotamment les activités de la milice Mobondo entraînant des violences et des mouvements\nde population dans les provinces du Kwango, du Kwilu et de Mai-Ndombe ainsi que dans la\ncommune de Maluku de la province de Kinshasa."},{"id":"a-hrc-54-76-p0034","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"34","seq":36,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"Dans la province de Tanganyika, la situation est marquée par la recrudescence des\nattaques des miliciens twa et bantou contre plusieurs villages des territoires de Kalemie et de\nMoba. Il en résulte d’importants déplacements de population ainsi qu’une montée de la\ncriminalité. À cela s’ajoutent de multiples incursions des Maï-Maï Malaika à partir du sud\ndu territoire de Kabambare, dans la province du Maniema6."},{"id":"a-hrc-54-76-p0035","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"35","seq":37,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux reste préoccupée par l’augmentation des\nexpulsions des Congolais de l’Angola. Elle rappelle l’urgence de la mise en œuvre de sa\nrecommandation à cet effet7. Elle déplore en outre l’aggravation de la situation humanitaire\nen raison des conflits intercommunautaires en lien avec le pouvoir coutumier dans les\nprovinces du Kasaï."},{"id":"a-hrc-54-76-p0036","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"36","seq":38,"section":"IV. Situation sécuritaire et humanitaire actuelle","text":"L’Équipe d’experts internationaux est préoccupée par la dégradation de la situation\nsécuritaire à Kinshasa, marquée par des enlèvements suivis souvent de morts d’hommes, tel\nle cas de Chérubin Okende, député et ex-Ministre des transports issu du parti politique\nd’opposition Ensemble pour la République, dont le corps a été retrouvé le 13 juillet 2023.\nL’Équipe d’experts internationaux prend note de ce que le Gouvernement a condamné ce\ncrime et « décidé de la mise en place d’une commission d’enquête plus large,\npluridisciplinaire avec l’implication de tous les services et la collaboration des services\nétrangers pour faire la lumière en toute transparence sur ce cas 8 »."},{"id":"a-hrc-54-76-p0037","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"37","seq":39,"section":"V. Mise en œuvre du mandat de l’Équipe d’experts","text":"Le mandat de l’Équipe d’experts internationaux est essentiellement articulé autour de\ndeux pôles : d’une part, la lutte contre l’impunité et, d’autre part, l’appui au processus de\njustice transitionnelle."},{"id":"a-hrc-54-76-p0038","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"38","seq":40,"section":"A. Lutte contre l’impunité","text":"Dans le domaine de la lutte contre l’impunité, l’Équipe d’experts internationaux a\npoursuivi l’exécution de son mandat à travers l’analyse du contexte de l’administration de la\njustice en République démocratique du Congo et le suivi des dossiers judiciaires ouverts dans\nle cadre de la crise liée à la milice Kamuina Nsapu ainsi que d’autres cas emblématiques.\n1.        Administration de la justice en République démocratique du Congo"},{"id":"a-hrc-54-76-p0039","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"39","seq":41,"section":"A. Lutte contre l’impunité","text":"L’atelier d’évaluation de la mise en œuvre des recommandations issues des différents\nrapports de l’Équipe d’experts internationaux publiés depuis la création de son mandat, soit\nde 2018 à 2022, organisé à Kinshasa les 25 et 26 janvier 2023, lui a permis de constater les\nefforts du Gouvernement pour améliorer l’administration de la justice."},{"id":"a-hrc-54-76-p0040","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"40","seq":42,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux note en effet que, dans le domaine de la lutte contre\nl’impunité, le Ministère de la justice a adopté une stratégie portant sur les volets judiciaire et\npénitentiaire."},{"id":"a-hrc-54-76-p0041","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"41","seq":43,"section":"A. Lutte contre l’impunité","text":"Concernant le volet judiciaire, et singulièrement le renforcement quantitatif et\nqualitatif des magistrats, l’Équipe d’experts internationaux salue le recrutement de\n5 000 nouveaux magistrats, ce qui répond à l’une des recommandations qu’elle avait\nformulées dans ses précédents rapports.\n6 Ibid., p. 1 et 2.\n7 A/HRC/48/82, par. 89 et 90.\n8 Communiqué du Ministre des communications et des médias, porte-parole du Gouvernement,\nà l’issue du Conseil des ministres du 14 juillet 2023."},{"id":"a-hrc-54-76-p0042","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"42","seq":44,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux encourage le Gouvernement à poursuivre ces\nrecrutements, d’autant plus que, selon le Conseil supérieur de la magistrature, la République\ndémocratique du Congo a besoin d’au moins 10 000 magistrats pour une couverture\nraisonnable de l’ensemble du territoire9."},{"id":"a-hrc-54-76-p0043","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"43","seq":45,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux note que le processus de formation initiale a\ncommencé avec une première vague de 2 500 nouveaux magistrats pour une durée de trois\nmois. Elle félicite à cet égard le Gouvernement et l’encourage à mettre en place un\nprogramme de formation continue, au besoin avec l’appui des partenaires internationaux."},{"id":"a-hrc-54-76-p0044","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"44","seq":46,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux souligne que l’effort considérable de renforcement\ndes ressources humaines qui est en cours doit être accompagné de l’amélioration des\nconditions de travail des magistrats, notamment l’équipement en matériel roulant et en\nmobilier de bureau. Elle relève que la bonne administration de la justice requiert également\nle renforcement des compétences des auxiliaires de justice, en particulier les greffiers, les\nofficiers de police judiciaire et les avocats."},{"id":"a-hrc-54-76-p0045","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"45","seq":47,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux constate que le Ministère de la justice a engagé une\nréforme du système pénitentiaire impliquant un cadre normatif et institutionnel conforme aux\nnormes internationales."},{"id":"a-hrc-54-76-p0046","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"46","seq":48,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux prend note de la signature, le 1er juin 2023, du\nMémorandum d’entente entre la République démocratique du Congo et le Bureau du\nProcureur de la Cour pénale internationale."},{"id":"a-hrc-54-76-p0047","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"47","seq":49,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux se félicite de ce que ce mémorandum vise à\nrenforcer la lutte contre l’impunité en République démocratique du Congo, et prend acte de\nl’engagement de cette dernière à « assurer la protection des victimes et des témoins et à leur\napporter le soutien et l’assistance nécessaires, y compris un soutien psychologique, et à\nveiller, par le biais des autorités judiciaires compétentes, à leur familiarisation avec le\ndéroulement des procédures »10."},{"id":"a-hrc-54-76-p0048","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"48","seq":50,"section":"A. Lutte contre l’impunité","text":"Au cours de son entretien avec le Vice-Premier Ministre et Ministre de la défense et\ndes anciens combattants, l’Équipe d’experts internationaux a pris note avec satisfaction de\nl’engagement du Ministère à lutter contre l’impunité au sein des Forces armées de la\nRépublique démocratique du Congo. À cet effet, le Ministre a exprimé le souhait d’un\naccompagnement pour le renforcement des capacités des Forces armées dans le domaine des\ndroits de l’homme et du droit international humanitaire. L’Équipe d’experts internationaux\nprie le Haut-Commissariat des Nations Unies aux droits de l’homme de prendre en\nconsidération ce souhait."},{"id":"a-hrc-54-76-p0049","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"49","seq":51,"section":"A. Lutte contre l’impunité","text":"S’agissant des allégations de viols et d’abus sexuels attribuables aux membres des\nForces armées de la République démocratique du Congo sur les sites de personnes déplacées\nde Kwamouth et de Goma, l’Équipe d’experts internationaux se félicite de la mise en place,\npar le Ministère de la défense et des anciens combattants, de deux commissions d’enquête11.\n2.       Suivi des dossiers judiciaires"},{"id":"a-hrc-54-76-p0050","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"50","seq":52,"section":"A. Lutte contre l’impunité","text":"Lors des visites de terrain, l’Équipe d’experts internationaux a rencontré l’Auditeur\ngénéral des Forces armées de la République démocratique du Congo et l’Auditeur militaire\nsupérieur de l’ancienne province du Kasaï-Occidental pour faire le suivi des dossiers ouverts\nà la suite de la crise liée à la milice Kamuina Nsapu."},{"id":"a-hrc-54-76-p0051","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"51","seq":53,"section":"A. Lutte contre l’impunité","text":"À l’issue de ces échanges, l’Équipe d’experts internationaux a relevé que, sur les\n16 cas emblématiques ouverts à cet effet, 6 dossiers n’avaient pas encore fait l’objet d’un\ndébut d’instruction, 8 dossiers étaient en cours d’instruction, et 2 dossiers étaient en cours de\njugement, soit le dossier Mulombodi et celui de l’assassinat des deux experts des\nNations Unies, Zaida Catalán et Michael Sharp."},{"id":"a-hrc-54-76-p0052","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"52","seq":54,"section":"A. Lutte contre l’impunité","text":"Dans le dossier Mulombodi, où deux officiers généraux sont poursuivis pour crimes\ncontre l’humanité pour des faits de viols, de meurtres, de traitements inhumains et dégradants\net d’emprisonnement du fait de la responsabilité du supérieur hiérarchique, l’audience est en\ncours devant la Haute Cour militaire."},{"id":"a-hrc-54-76-p0053","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"53","seq":55,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux note également que l’audience en appel se déroule\ndevant la Haute Cour militaire dans le dossier de l’assassinat des deux experts des\nNations Unies. Elle note en outre que l’instruction se poursuit dans l’affaire Moyo Musuila\nconcernant les quatre accompagnateurs des experts des Nations Unies."},{"id":"a-hrc-54-76-p0054","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"54","seq":56,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux se félicite de l’appui apporté par le\nHaut-Commissariat aux droits de l’homme aux autorités judiciaires, à travers le déploiement\nde l’équipe d’assistance technique composée de médecins légistes, de psychologues,\nd’anthropologues, et de spécialistes des questions du genre, de la protection des victimes et\nde la géolocalisation."},{"id":"a-hrc-54-76-p0055","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"55","seq":57,"section":"A. Lutte contre l’impunité","text":"Cette équipe pluridisciplinaire a procédé, au cours d’une mission conjointe\nd’investigation, à l’exhumation des restes humains sur neuf nouveaux sites dans les provinces\ndu Kasaï et du Kasaï-Central. Les ossements d’au moins 52 victimes ont été collectés et ont\nfait l’objet de prélèvements et d’examens au laboratoire de criminalistique. Une autre mission\nconjointe médico-légale a été conduite à Kabalo, dans la province de Tanganyika, pour\nlocaliser, exhumer et examiner des corps de victimes appartenant à la minorité ethnique twa."},{"id":"a-hrc-54-76-p0056","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"56","seq":58,"section":"A. Lutte contre l’impunité","text":"Dans le domaine du renforcement des capacités, l’équipe d’assistance technique a\norganisé, en juillet 2023, un colloque international sur les enjeux et défis de la médecine\nlégale en République démocratique du Congo. Ce colloque visait la mise en place d’une\nstratégie pour le développement et le renforcement des capacités en médecine légale, laquelle\ncontribuerait à lutter efficacement contre l’impunité et à soutenir le processus de justice\ntransitionnelle dans le pays."},{"id":"a-hrc-54-76-p0057","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"57","seq":59,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux encourage le Gouvernement à mettre en œuvre la\nfeuille de route issue des travaux de ce colloque, et invite à cet effet la communauté\ninternationale à apporter tout son soutien à la République démocratique du Congo en vue de\nla réalisation des objectifs de ce colloque."},{"id":"a-hrc-54-76-p0058","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"58","seq":60,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux salue cette coopération technique et suggère le\nrenouvellement et le renforcement en ressources humaines de l’équipe d’assistance\ntechnique, en particulier dans le domaine psychothérapeutique."},{"id":"a-hrc-54-76-p0059","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"59","seq":61,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux réaffirme que seule une justice impartiale, rendue\ndans un délai raisonnable, pourra rassurer les victimes et permettre d’entrevoir un pardon\nsincère de la part des victimes, gage d’une réconciliation véritable.\n3.         Situation des victimes"},{"id":"a-hrc-54-76-p0060","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"60","seq":62,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux note que, depuis la publication de son précédent\nrapport, les préoccupations des victimes demeurent12."},{"id":"a-hrc-54-76-p0061","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"61","seq":63,"section":"A. Lutte contre l’impunité","text":"Lors de sa visite de terrain à Kananga, le 19 mai 2023, l’Équipe d’experts\ninternationaux a rencontré l’Association des victimes du grand Kasaï. Au cours des échanges,\nle porte-parole de l’Association a renouvelé les inquiétudes des victimes face à la lenteur de\nla justice, et réitéré leur demande de voir la communauté internationale faire pression sur le\nGouvernement afin que justice leur soit rendue dans les meilleurs délais. En outre, le\nporte-parole a identifié quelques sites ayant fait l’objet d’attaques lors de la crise liée à la\nmilice Kamuina Nsapu et a souligné le besoin de construire des mémoriaux à Nganza, à\nMulombodi et à Dibaya.\n12   A/HRC/51/60, par. 48."},{"id":"a-hrc-54-76-p0062","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"62","seq":64,"section":"A. Lutte contre l’impunité","text":"Au cours d’une audience tenue le 25 juillet 2023, le Gouverneur de la province du\nKasaï-Central a informé l’Équipe d’experts internationaux, en présence du Ministre des\ndroits humains, des dispositions déjà prises pour la réalisation imminente des mémoriaux."},{"id":"a-hrc-54-76-p0063","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"63","seq":65,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux salue la tenue de l’atelier de formation sur la justice\ntransitionnelle organisé par le BCNUDH en faveur des membres de l’Association des\nvictimes du grand Kasaï."},{"id":"a-hrc-54-76-p0064","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"64","seq":66,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux encourage les autorités de la République\ndémocratique du Congo à mettre en œuvre sa recommandation visant à mettre en place un\nprogramme de développement au profit des victimes de la crise du Kasaï."},{"id":"a-hrc-54-76-p0065","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"65","seq":67,"section":"A. Lutte contre l’impunité","text":"L’Équipe d’experts internationaux apprécie également l’association des victimes à\nl’atelier de validation des textes de fonctionnement de la Commission provinciale vérité,\njustice et réconciliation au Kasaï-Central ainsi qu’au lancement des activités de la\nCommission, le 25 juillet 2023. Elle encourage la Commission à poursuivre et à renforcer sa\ncollaboration avec les victimes de la crise du Kasaï."},{"id":"a-hrc-54-76-p0066","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"66","seq":68,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"Dans son précédent rapport, l’Équipe d’experts internationaux avait souligné la\nnécessité d’un accompagnement conséquent de la Commission provinciale vérité, justice et\nréconciliation au Kasaï-Central par le Gouvernement et les partenaires techniques et\nfinanciers, à travers une mobilisation des ressources essentielles à son fonctionnement13."},{"id":"a-hrc-54-76-p0067","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"67","seq":69,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux se félicite de ce que l’intérêt pour\nl’accompagnement de la Commission provinciale vérité, justice et réconciliation au\nKasaï-Central, bien que timide, commence à se manifester. En effet, outre l’appui significatif\ndu BCNUDH, d’autres partenaires commencent à la soutenir. À ce sujet, l’Équipe d’experts\ninternationaux a été informée de la signature, en juillet 2023, d’un accord de partenariat entre\nTRIAL International et la Commission. Elle salue cette collaboration et invite les autres\nbailleurs de fonds à faire de même afin d’assurer le succès du processus de justice\ntransitionnelle au Kasaï-Central."},{"id":"a-hrc-54-76-p0068","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"68","seq":70,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux salue la mise à disposition par le Gouverneur de la\nprovince du Kasaï-Central d’un bâtiment pour abriter le siège de la Commission provinciale\nvérité, justice et réconciliation au Kasaï-Central et l’encourage à lui allouer une dotation\nmensuelle suffisante pour son fonctionnement. Elle prend note de la signature d’un protocole\nd’accord portant création d’un cadre de concertation de partenariat entre le gouvernement\nprovincial du Kasaï-Central et la Commission."},{"id":"a-hrc-54-76-p0069","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"69","seq":71,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"Dans le domaine du renforcement des capacités, l’Équipe d’experts internationaux\nnote qu’une formation initiale des commissaires a été organisée avec l’appui du BCNUDH,\ndu 23 au 27 janvier 2023, sur l’appropriation de leur mandat et le fonctionnement d’une\ncommission vérité, justice et réconciliation. L’Équipe d’experts internationaux a contribué à\ncette formation en assurant trois modules portant sur le partage d’expériences du\nfonctionnement des commissions vérité et justice, sur la réconciliation et les commissions\nvérité et justice, et sur la prise en compte de la dimension de genre dans le processus de\njustice transitionnelle."},{"id":"a-hrc-54-76-p0070","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"70","seq":72,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"Les 24 et 25 juillet 2023, l’Équipe d’experts internationaux a participé à Kananga à\ndeux événements organisés conjointement par le BCNUDH et le gouvernement provincial\ndu Kasaï-Central. Le premier concernait l’atelier d’appropriation et de validation des textes\nde fonctionnement de la Commission provinciale vérité, justice et réconciliation au\nKasaï-Central, et le second, le lancement officiel des activités de la Commission. Ces deux\névénements se sont déroulés en présence du Ministre des droits humains, du Représentant\npermanent de la République démocratique du Congo auprès de l’Office des Nations Unies et\ndes autres organisations internationales à Genève, de représentants d’associations de\nvictimes, de certains bailleurs de fonds, et de représentants du système des Nations Unies en\nRépublique démocratique du Congo ainsi que d’organisations non gouvernementales\ninternationales. En marge de la cérémonie du lancement officiel, l’Équipe d’experts\ninternationaux a assisté à la signature de deux documents : l’un portant « accord de\ncoopération technique entre la Commission et le BCNUDH », l’autre relatif au « Protocole\nd’accord portant création d’un cadre de concertation entre le gouvernement provincial du\nKasaï-Central et la Commission ». L’Équipe d’experts internationaux salue ces initiatives."},{"id":"a-hrc-54-76-p0071","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"71","seq":73,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux apprécie la mise à disposition par le\nHaut-Commissariat aux droits de l’homme d’un expert en justice transitionnelle au bureau\nde terrain de Kananga, pour appuyer le travail de la Commission provinciale vérité, justice\net réconciliation au Kasaï-Central. L’appui de cet expert a été significatif dans l’élaboration\net la validation des outils stratégiques et méthodologiques relatifs au fonctionnement de la\nCommission.\n2.    Mise en œuvre du processus de justice transitionnelle au niveau national"},{"id":"a-hrc-54-76-p0072","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"72","seq":74,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux relève qu’au niveau national, les initiatives de\njustice transitionnelle sont pilotées par le Ministère des droits humains et le Programme de\ndésarmement, de démobilisation, de relèvement communautaire et de stabilisation.\nLes structures de mise en œuvre du processus de justice transitionnelle"},{"id":"a-hrc-54-76-p0073","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"73","seq":75,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux loue les efforts du Ministère des droits humains\nvisant à poursuivre les consultations populaires en donnant la possibilité aux populations, et\nen particulier aux victimes, d’exprimer leurs quêtes de vérité, de justice, de réparation et de\ngaranties de non-répétition dans le cadre de la justice transitionnelle. L’Équipe d’experts\ninternationaux a été informée de la poursuite, par le Ministère des droits humains, en\njuin 2023, des consultations populaires dans les provinces du Kasaï-Oriental, du Sankuru, de\nLomami et de Kinshasa. Elle encourage fortement le Gouvernement à poursuivre ces\nconsultations, et rappelle cependant que celles-ci doivent toujours être conformes aux normes\ninternationales en la matière."},{"id":"a-hrc-54-76-p0074","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"74","seq":76,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux se félicite de l’élaboration du document de\npolitique nationale en matière de justice transitionnelle et encourage le Gouvernement à\nprocéder à sa mise en œuvre."},{"id":"a-hrc-54-76-p0075","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"75","seq":77,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"Les 25 et 26 janvier 2023, l’Équipe d’experts internationaux a coorganisé avec le\nMinistère des droits humains, à Kinshasa, un atelier sur l’évaluation de la mise en œuvre de\nses recommandations formulées de 2018 à 2022, dans le cadre de son mandat. Cet atelier a\nréuni une cinquantaine de participants de diverses structures étatiques, de la société civile et\ndu corps diplomatique. Il a permis à l’Équipe d’experts internationaux de mesurer le niveau\nde mise en œuvre des recommandations et d’identifier les contraintes et défis qui demeurent."},{"id":"a-hrc-54-76-p0076","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"76","seq":78,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux salue également le déploiement par le\nHaut-Commissariat aux droits de l’homme d’un fonctionnaire des droits de l’homme\nspécialiste en justice transitionnelle au sein du Ministère des droits humains. Sa mission est\nd’appuyer le Ministère dans la rédaction et l’adoption d’outils méthodologiques et\nstratégiques relatifs à la justice transitionnelle. Grâce à cet appui, le Ministère des droits\nhumains, en collaboration avec le BCNUDH, l’Équipe d’experts internationaux et l’Entité\ndes Nations Unies pour l’égalité des sexes et l’autonomisation des femmes (ONU-Femmes),\na organisé à Zongo, dans la province du Kongo-Central, une retraite d’écriture de son plan\nd’action stratégique en matière de justice transitionnelle. Le plan d’action issu de cette retraite\ndevrait être validé au cours d’un atelier qui doit réunir les ministères sectoriels, les membres\ndu corps diplomatique, les organisations internationales, les représentants de la société civile\net des victimes."},{"id":"a-hrc-54-76-p0077","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"77","seq":79,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux félicite le Ministère des droits humains pour la\ntenue de cette retraite et l’encourage vivement à procéder à sa validation dans les meilleurs\ndélais, afin d’avoir une feuille de route pour la justice transitionnelle."},{"id":"a-hrc-54-76-p0078","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"78","seq":80,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux invite les partenaires, y compris le BCNUDH, à\nsoutenir les efforts du Ministère des droits humains dans la mise en œuvre de la feuille de\nroute pour la justice transitionnelle après sa validation."},{"id":"a-hrc-54-76-p0079","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"79","seq":81,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux souligne l’importance de multiplier, sur les plans\nnational et sous-régional, les initiatives visant à favoriser le retour à la paix dans les zones en\nconflit et à permettre aux communautés ayant manifesté le désir de recourir aux mécanismes\nde justice transitionnelle d’exprimer leurs besoins de vérité, de réparation, de justice et de\nréformes à travers les consultations populaires. Ces initiatives pourraient considérer le rôle à\njouer par les chefs coutumiers, les autorités religieuses, les associations de femmes et les\njeunes pour créer des portes d’entrée favorables à un dialogue sur la justice transitionnelle."},{"id":"a-hrc-54-76-p0080","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"80","seq":82,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux prend note des efforts du Gouvernement pour\npromouvoir la paix et la restauration de l’autorité de l’État en mettant en place le Programme\nde désarmement, de démobilisation, de relèvement communautaire et de stabilisation. La\nstratégie nationale de mise en œuvre de ce programme met l’accent sur l’approche\ncommunautaire inclusive et la justice transitionnelle comme mécanismes de règlement des\nconflits, de réconciliation et de réparation des préjudices."},{"id":"a-hrc-54-76-p0081","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"81","seq":83,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux se félicite des progrès accomplis par le Programme\nde désarmement, de démobilisation, de relèvement communautaire et de stabilisation,\nnotamment l’implantation de ses antennes provinciales et l’adoption des plans provinciaux.\nCependant, elle l’encourage à davantage collaborer avec les institutions nationales\nimpliquées dans le processus de justice transitionnelle."},{"id":"a-hrc-54-76-p0082","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"82","seq":84,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux constate avec inquiétude que, bien que les plans\nopérationnels provinciaux aient connu un début de mise en œuvre, leur impact sur la paix et\nla sécurité demeure limité en raison de la persistance des attaques des groupes armés dans\nl’est du pays."},{"id":"a-hrc-54-76-p0083","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"83","seq":85,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"Lors de sa deuxième visite, l’Équipe d’experts internationaux s’est entretenue avec le\nCoordonnateur du Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation. À l’issue de cet entretien, elle a noté des avancées,\nnotamment la production d’outils stratégiques tels que la cartographie des conflits identifiant\nles groupes armés locaux et étrangers, l’élaboration d’un plan opérationnel provincial,\nl’identification des sites de désarmement et de démobilisation, et la sensibilisation des\npopulations. Toutefois, l’Équipe d’experts internationaux a pris note de quelques\ncontradictions entre les partenaires techniques et financiers et le Programme, notamment\ndans l’approche communautaire de réinsertion ou de prise en charge des démobilisés issus\ndes groupes armés."},{"id":"a-hrc-54-76-p0084","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"84","seq":86,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"Relativement à la question de la collaboration entre les différentes structures chargées\nde mettre en œuvre le processus de justice transitionnelle en République démocratique du\nCongo, le Coordonnateur du Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation a souligné l’existence de synergies entre le Programme et\nles ministères sectoriels dans le cadre du relèvement communautaire."},{"id":"a-hrc-54-76-p0085","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"85","seq":87,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux a constaté une différence d’approche\nopérationnelle entre le Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation et ses partenaires. Elle a noté que le Programme privilégiait\nune approche non judiciaire optant pour la resocialisation des ex-combattants, tandis que les\npartenaires y associaient le volet des poursuites judiciaires. Pour promouvoir le vivre\nensemble des populations, l’Équipe d’experts internationaux exhorte les autorités chargées\nde la mise en œuvre du Programme et les partenaires à établir un équilibre entre les poursuites\njudiciaires, qui garantissent le droit des victimes à la justice, et les stratégies de\nresocialisation, qui favorisent un climat d’apaisement au sein des communautés.\n3.     Défis de la mise en œuvre du processus de justice transitionnelle\nen cours en République démocratique du Congo"},{"id":"a-hrc-54-76-p0086","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"86","seq":88,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"Les défis de la mise en œuvre du processus de justice transitionnelle demeurent\nnotamment la sensibilisation et la communication sur le processus ainsi que son appropriation\npar la population. L’Équipe d’experts internationaux note toutefois des évolutions\nconcernant : a) l’harmonisation des différents processus en cours, en vue d’obtenir une vision\nd’ensemble et de permettre leur mise en œuvre intégrée ; b) le financement du processus de\njustice transitionnelle ; c) la prise en compte de la dimension transfrontalière des conflits ;\nd) la question des réparations ; et e) la mise en œuvre de la justice transitionnelle dans un\ncontexte d’insécurité et de conflits intercommunautaires.\na)         L’harmonisation et la communication adéquate des différents processus en cours\ndans le cadre d’une vision d’ensemble et leur mise en œuvre intégrée"},{"id":"a-hrc-54-76-p0087","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"87","seq":89,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux avait déjà identifié dans son précédent rapport\nquelques pesanteurs associées à la mise en œuvre des initiatives de justice transitionnelle en\nRépublique démocratique du Congo, notamment la coordination, l’articulation et le\nfinancement de ces initiatives, ainsi que la stratégie de communication sur ces différentes\ninitiatives 14 . Lors d’une séance de travail avec le Coordonnateur du Programme de\ndésarmement, de démobilisation, de relèvement communautaire et de stabilisation le 22 mai\n2023, l’Équipe d’experts internationaux a pu constater des signaux positifs dans la\ncoordination entre les différentes institutions chargées de la justice transitionnelle. À ce sujet,\nelle a été informée du développement d’une synergie entre le Ministère du Plan et le\nProgramme pour le recours à une main-d’œuvre disponible parmi les bénéficiaires du\nProgramme, afin de favoriser leur insertion socioéconomique."},{"id":"a-hrc-54-76-p0088","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"88","seq":90,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux a néanmoins noté que l’unique cadre de\nconcertation entre le Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation et le Ministère des droits humains était le comité de\npilotage, qui est un organe de gestion propre au Programme. Le Ministre des droits humains,\nqui a la mission d’harmoniser la justice transitionnelle au niveau national, n’a qu’un rôle\nd’observateur dans ce comité. Il existe donc des risques de chevauchement des initiatives, de\ndéperdition des ressources, de manque de cohérence dans l’action et de confusion dans\nl’esprit du public concernant les attributions et les rôles des différents acteurs."},{"id":"a-hrc-54-76-p0089","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"89","seq":91,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"À cet effet, l’Équipe d’experts internationaux soutient l’initiative du BCNUDH\nd’organiser un atelier de haut niveau entre la coordination nationale du Programme de\ndésarmement, de démobilisation, de relèvement communautaire et de stabilisation et le\nMinistère des droits humains.\nb)         Le financement du processus de justice transitionnelle"},{"id":"a-hrc-54-76-p0090","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"90","seq":92,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux reste préoccupée par le fait que le financement du\nprocessus dépend pour l’essentiel des aides extérieures. La nécessité d’un financement\nnational renforcé, seul à même d’assurer la crédibilité, la cohérence et la durabilité du\nprocessus, demeure."},{"id":"a-hrc-54-76-p0091","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"91","seq":93,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"Lors de sa deuxième visite, l’Équipe d’experts internationaux a soulevé la question\ndu financement lors des échanges avec le Président de l’Assemblée nationale et a noté\nl’engagement des parlementaires à prévoir un soutien financier pour le processus de justice\ntransitionnelle en République démocratique du Congo, et dans la province du Kasaï-Central\nen particulier."},{"id":"a-hrc-54-76-p0092","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"92","seq":94,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux encourage le Président de l’Assemblée nationale à\ntraduire cet engagement en actes concrets.\nc)         La prise en compte de la dimension transfrontalière des conflits"},{"id":"a-hrc-54-76-p0093","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"93","seq":95,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux reste préoccupée par la dimension transfrontalière\nou sous-régionale des conflits dans l’est de la République démocratique du Congo. Lors de\nsa réunion virtuelle avec l’Envoyé spécial du Secrétaire général pour la région des Grands\nLacs, elle a eu des discussions fructueuses en vue d’envisager la possibilité de prendre en\ncompte les dimensions de la justice transitionnelle dans les stratégies sous-régionales de\npromotion de la paix, de la sécurité et de la stabilité en République démocratique du Congo.\n14   Ibid., par. 64."},{"id":"a-hrc-54-76-p0094","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"94","seq":96,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux se félicite des échanges avec l’Envoyé spécial du\nSecrétaire général pour la région des Grands Lacs et a pris note de son souhait de formaliser\nune coopération institutionnelle entre le Haut-Commissariat aux droits de l’homme et le\nRéseau de coopération judiciaire de la région des Grands Lacs, afin de permettre à ce dernier\nde bénéficier de l’appui du Haut-Commissariat.\nd)        La question des réparations"},{"id":"a-hrc-54-76-p0095","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"95","seq":97,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux avait déjà relevé les difficultés auxquelles font face\nles victimes en matière de réparation dans son précédent rapport15."},{"id":"a-hrc-54-76-p0096","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"96","seq":98,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux note cependant que la réparation des victimes est\ndésormais encadrée juridiquement par la loi no 22/065 du 26 décembre 2022 fixant les\nprincipes fondamentaux relatifs à la protection et à la réparation des victimes de violences\nsexuelles liées aux conflits et des victimes des crimes contre la paix et la sécurité de\nl’humanité. Promulguée par le Président de la République, cette loi définit la vision du\nGouvernement en matière de réparation et promeut la création d’un programme de\nréparations administratives afin de répondre au problème persistant de non-paiement des\nréparations judiciaires. L’Équipe d’experts internationaux constate que le Gouvernement a\négalement institué par le décret no 22/38 du 6 décembre 2022 un établissement public chargé\nd’encadrer les victimes et les réparations à travers le Fonds national de réparation des\nvictimes des violences sexuelles liées aux conflits et d’autres crimes contre la paix et la\nsécurité de l’humanité en République Démocratique du Congo (FONAREV). Un décret\nmodifiant et complétant le décret susmentionné a été adopté en mai 2023."},{"id":"a-hrc-54-76-p0097","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"97","seq":99,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux souligne la nécessité, dans le cadre de la réparation\nnon judiciaire, de combiner les mesures cliniques, l’appui psychothérapeutique et les actions\nde réinsertion sociale pour permettre aux victimes de se prendre en charge et de retrouver\nleur dignité."},{"id":"a-hrc-54-76-p0098","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"98","seq":100,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux souligne la nécessité de considérer les réparations\ncollectives qui permettent de traiter les causes et les conséquences du conflit, telles que les\nécoles, les centres de santé ou les foyers polyvalents pour les jeunes et les victimes de\nviolences sexuelles.\ne)        La mise en œuvre de la justice transitionnelle dans un contexte d’insécurité\net de conflits intercommunautaires"},{"id":"a-hrc-54-76-p0099","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"99","seq":101,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux demeure préoccupée par le fait que le processus de\njustice transitionnelle se déroule dans un contexte de persistance de conflits anciens et\nd’émergence de nouveaux conflits intercommunautaires, notamment dans les provinces de\nMai-Ndombe, du Kwilu et du Kwango ainsi que dans la commune de Maluku de la province\nde Kinshasa, avec une augmentation des discours de haine."},{"id":"a-hrc-54-76-p0100","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"100","seq":102,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux s’inquiète des conséquences humanitaires des\nconflits qui ont cours notamment dans les provinces de Mai-Ndombe, du Kwilu et du\nKwango ainsi que dans la commune de Maluku de la province de Kinshasa."},{"id":"a-hrc-54-76-p0101","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"101","seq":103,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"L’Équipe d’experts internationaux exhorte le Gouvernement à considérer cette\nsituation fragilisant la protection des civils et rendant difficile la réponse humanitaire. Elle\ninvite les partenaires au développement et la communauté internationale à accompagner le\nGouvernement de la République démocratique du Congo par des actions urgentes et\nconcertées allant dans le sens de la restauration de la paix et de l’équilibre social."},{"id":"a-hrc-54-76-p0102","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"102","seq":104,"section":"B. Mise en œuvre du processus de justice transitionnelle","text":"À cet effet, l’Équipe d’experts internationaux a eu des échanges avec le Ministre des\ndroits humains, le 16 mai 2023, sur la situation sécuritaire en République démocratique du\nCongo. Elle se réjouit également du fait que la situation sécuritaire dans l’ouest du pays fait\nl’objet d’une attention particulière de la part du BCNUDH."},{"id":"a-hrc-54-76-p0103","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"103","seq":105,"section":"A. Conclusions","text":"L’Équipe d’experts internationaux a continué à bénéficier de la pleine\ncoopération, de la bonne volonté et de la disponibilité du Gouvernement pour mener à\nbien son mandat. Elle tient à lui exprimer sa gratitude."},{"id":"a-hrc-54-76-p0104","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"104","seq":106,"section":"A. Conclusions","text":"L’Équipe d’experts internationaux se félicite de la confiance, de la franchise et\nde la volonté de dialogue de la population, des chefs coutumiers, des autorités\nreligieuses, de la société civile et de la communauté internationale à Kinshasa et dans\nles provinces, qui ont partagé leurs expériences et leurs connaissances de la complexité\net des nuances de la situation en République démocratique du Congo. À cela s’ajoute le\nsoutien inestimable du BCNUDH, du système des Nations Unies et de la Mission de\nl’Organisation des Nations Unies pour la stabilisation en République démocratique du\nCongo, y compris les chefs de section et chefs de bureaux de terrain."},{"id":"a-hrc-54-76-p0105","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"105","seq":107,"section":"A. Conclusions","text":"L’Équipe d’experts internationaux observe que des recommandations issues de\nson précédent rapport ont commencé à être mises en œuvre."},{"id":"a-hrc-54-76-p0106","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"106","seq":108,"section":"A. Conclusions","text":"L’Équipe d’experts internationaux note à cet effet le recrutement de nouveaux\nmagistrats, dont une partie doit commencer sa formation initiale en août 2023. Ce\nrecrutement demeure insuffisant, par rapport aux besoins du pays. De plus, la\nformation initiale d’une durée prévue de trois mois devrait être suivie d’une formation\ncontinue étendue, au besoin, à tous les acteurs de la chaîne pénale."},{"id":"a-hrc-54-76-p0107","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"107","seq":109,"section":"A. Conclusions","text":"S’agissant de la justice juvénile, l’Équipe d’experts internationaux observe le\nmanque de magistrats spécialisés ainsi que de structures adéquates nécessaires à la\nréinsertion sociale des enfants auteurs ou victimes d’infractions. Il est indispensable de\npallier cette insuffisance."},{"id":"a-hrc-54-76-p0108","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"108","seq":110,"section":"A. Conclusions","text":"L’Équipe d’experts internationaux relève que l’insécurité croissante à l’intérieur\ndu pays compromet le déploiement des magistrats, accentuant ainsi l’absence de l’État\ndans certaines zones."},{"id":"a-hrc-54-76-p0109","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"109","seq":111,"section":"A. Conclusions","text":"Les progrès réalisés dans la province du Kasaï-Central confortent l’idée selon\nlaquelle l’approche complémentaire (niveau provincial et national) est la bonne, pourvu\nque la justice transitionnelle bénéficie d’un accompagnement suffisant de l’État et des\npartenaires. Cet exemple rendra crédible le processus et pourra convaincre les autres\nprovinces d’aller dans ce sens."},{"id":"a-hrc-54-76-p0110","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"110","seq":112,"section":"A. Conclusions","text":"L’une des faiblesses du processus de justice transitionnelle est l’insuffisance de\nla sensibilisation et de la communication, y compris dans la province du Kasaï-Central.\nCela pose le problème de son appropriation par les populations."},{"id":"a-hrc-54-76-p0111","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"111","seq":113,"section":"A. Conclusions","text":"Un manque d’harmonisation dans la mise en œuvre du processus de justice\ntransitionnelle a été constaté, y compris au niveau des partenaires d’appui. Or, pour\nqu’un processus de justice transitionnelle soit efficace et crédible, il faut qu’il y ait une\nharmonisation, une complémentarité et une cohérence des activités menées."},{"id":"a-hrc-54-76-p0112","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"112","seq":114,"section":"A. Conclusions","text":"La poursuite du processus de justice transitionnelle dans les zones en conflit est\npossible pourvu qu’il y ait des portes d’entrée devant conduire à un dialogue sur la\njustice transitionnelle et favoriser la cessation des hostilités. Cette démarche est\négalement possible même en période électorale."},{"id":"a-hrc-54-76-p0113","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"113","seq":115,"section":"A. Conclusions","text":"Toutes les initiatives de justice transitionnelle devraient intégrer une approche\nglobale incluant des mesures psychothérapeutiques pour faciliter la réinsertion\nsocioéconomique des victimes."},{"id":"a-hrc-54-76-p0114","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"114","seq":116,"section":"A. Conclusions","text":"Il est observé que l’entité de liaison des droits de l’homme créée par le décret\nno 09/35 du 12 août 2009 n’est toujours pas opérationnelle au niveau national."},{"id":"a-hrc-54-76-p0115","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"115","seq":117,"section":"A. Conclusions","text":"Les efforts consentis dans le cadre des initiatives sous-régionales sont très\nimportants et à saluer. Ces initiatives semblent principalement axées sur une réponse\ndiplomatique et sécuritaire. Il est indispensable qu’elles incorporent davantage la\ndimension des droits de l’homme et accordent une attention particulière aux mesures\njudiciaires et non judiciaires pour aboutir à une paix durable."},{"id":"a-hrc-54-76-p0116","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"116","seq":118,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux rappelle la nécessité de poursuivre la mise en\nœuvre des recommandations énoncées dans ses précédents rapports 16 . Elle réitère\nci-après certaines de ces recommandations et en formule de nouvelles.\n1.        Conceptualisation, articulation et stratégie de communication de la politique\nde justice transitionnelle et lutte contre l’impunité"},{"id":"a-hrc-54-76-p0117","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"117","seq":119,"section":"B. Recommandations","text":"Afin de rendre visibles les efforts du Gouvernement et de faciliter\nl’appropriation du processus par la population, l’Équipe d’experts internationaux\nsouligne l’urgence d’une stratégie de communication appropriée sur la mise en œuvre\nde la justice transitionnelle et recommande au Gouvernement d’accorder une priorité\nà son élaboration."},{"id":"a-hrc-54-76-p0118","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"118","seq":120,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux exhorte les autorités chargées de la mise en\nœuvre du Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation à davantage collaborer avec les institutions\nnationales impliquées dans le processus de justice transitionnelle."},{"id":"a-hrc-54-76-p0119","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"119","seq":121,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux invite le Gouvernement à poursuivre les\nconsultations populaires en veillant à leur conformité avec les normes internationales."},{"id":"a-hrc-54-76-p0120","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"120","seq":122,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux invite le Ministère des droits humains à\nprocéder dans les meilleurs délais à la validation de son plan d’action en matière de\njustice transitionnelle."},{"id":"a-hrc-54-76-p0121","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"121","seq":123,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux exhorte les autorités chargées de la mise en\nœuvre du Programme de désarmement, de démobilisation, de relèvement\ncommunautaire et de stabilisation et les partenaires à établir un équilibre entre, d’une\npart, les poursuites judiciaires, qui garantissent le droit des victimes à la justice et,\nd’autre part, les stratégies de resocialisation, qui favorisent un climat d’apaisement au\nsein des communautés.\n2.        Prévention de l’impunité"},{"id":"a-hrc-54-76-p0122","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"122","seq":124,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux recommande au Gouvernement de renforcer\nla formation initiale des magistrats par des formations continues, y compris dans le\ncadre d’une coopération Sud-Sud étendue si nécessaire aux autres acteurs judiciaires,\nnotamment les officiers de police judiciaire."},{"id":"a-hrc-54-76-p0123","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"123","seq":125,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux recommande au Conseil des droits de\nl’homme de maintenir la présence de l’équipe d’assistance technique et de renforcer ses\ncapacités par l’augmentation du nombre de ses membres et de leurs ressources,\ny compris des outils performants pouvant permettre la collecte des éléments de preuve\npour la justice et le travail de mémoire."},{"id":"a-hrc-54-76-p0124","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"124","seq":126,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux exhorte le Gouvernement et le Parlement à\nmettre en œuvre la feuille de route issue des travaux du colloque international sur les\nenjeux et défis de la médecine légale en République démocratique du Congo. Elle invite\nla communauté internationale à apporter tout son soutien à la République\ndémocratique du Congo en vue de la réalisation des objectifs de ce colloque."},{"id":"a-hrc-54-76-p0125","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"125","seq":127,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux recommande au Haut-Commissariat des\nNations Unies aux droits de l’homme de formaliser sa coopération institutionnelle avec\nle Réseau de coopération judiciaire de la région des Grands Lacs, afin de permettre à\nce dernier de bénéficier de l’appui du Haut-Commissariat.\n3.    Prise en compte des victimes dans toutes les phases du processus"},{"id":"a-hrc-54-76-p0126","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"126","seq":128,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux salue la création du FONAREV et invite le\nGouvernement à le rendre opérationnel dans les meilleurs délais."},{"id":"a-hrc-54-76-p0127","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"127","seq":129,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux invite le Gouvernement à combiner, dans le\ncadre de la réparation non judiciaire, les mesures cliniques, l’appui\npsychothérapeutique et les actions de réinsertion sociale pour permettre aux victimes\nde se prendre en charge et de retrouver leur dignité.\n4.    Prévention des conflits et garanties de non-répétition"},{"id":"a-hrc-54-76-p0128","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"128","seq":130,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux recommande à nouveau au Gouvernement\nd’ajouter un plan de réforme de l’administration pour compléter les programmes\nactuels de réforme des secteurs sécuritaire et judiciaire, les trois réformes devant être\nmenées de front pour se renforcer mutuellement."},{"id":"a-hrc-54-76-p0129","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"129","seq":131,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux encourage le Gouvernement à mettre en\nplace un programme adéquat de formation de qualité pour ses cadres, en tenant compte\nnotamment du retrait progressif de la Mission de l’Organisation des Nations Unies pour\nla stabilisation en République démocratique du Congo et du besoin d’assurer la\ndurabilité des réformes en vue."},{"id":"a-hrc-54-76-p0130","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"130","seq":132,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux salue la prise en compte du caractère\ntransfrontalier des conflits et de l’insécurité par le processus de Nairobi. Elle\nrecommande aux différentes initiatives d’impliquer davantage la sous-région dans\nl’identification des causes des conflits et la prévention de leur répétition et, sans se\nlimiter aux seuls aspects politiques, diplomatiques et militaires, de renforcer la\ndimension de justice transitionnelle. Elle recommande également aux différents acteurs\nd’accroître leur coopération dans ce sens."},{"id":"a-hrc-54-76-p0131","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"131","seq":133,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux recommande aux différentes parties\nprenantes la mise en œuvre rapide des décisions, des recommandations et des\nconclusions issues des processus de Nairobi et de Luanda, et exhorte tous les groupes\narmés à un désarmement effectif. Elle réitère la nécessité de procéder au profilage des\nex-combattants."},{"id":"a-hrc-54-76-p0132","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"132","seq":134,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux recommande au Haut-Commissariat des\nNations Unies aux droits de l’homme de poursuivre ses efforts de renforcement des\ncapacités des Forces armées de la République démocratique du Congo dans les\ndomaines des droits de l’homme et du droit international humanitaire."},{"id":"a-hrc-54-76-p0133","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"133","seq":135,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux invite les partenaires au développement et la\ncommunauté internationale à accompagner le Gouvernement en prenant des actions\nurgentes et concertées allant dans le sens de la restauration de la paix et de l’équilibre\nsocial, afin de renforcer la protection des civils."},{"id":"a-hrc-54-76-p0134","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"134","seq":136,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux invite fortement le Gouvernement à rendre\nopérationnelle au niveau national l’entité de liaison des droits de l’homme en y intégrant\nla dimension de justice transitionnelle.\n5.    Financement public, privé et international du processus\nde justice transitionnelle"},{"id":"a-hrc-54-76-p0135","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"135","seq":137,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux continue de déplorer la faiblesse des\nressources mises à disposition pour le processus de justice transitionnelle dans la région\ndu Kasaï, et réitère la nécessité d’un financement suffisant et durable de tous les volets\nde la justice transitionnelle."},{"id":"a-hrc-54-76-p0136","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"136","seq":138,"section":"B. Recommandations","text":"Tout en saluant les partenariats noués entre la Commission provinciale vérité,\njustice et réconciliation au Kasaï-Central et le BCNUDH, l’Équipe d’experts\ninternationaux encourage les autres bailleurs de fonds à faire de même afin d’assurer\nde façon cohérente le succès du processus de justice transitionnelle dans la province du\nKasaï-Central."},{"id":"a-hrc-54-76-p0137","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"137","seq":139,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux exhorte à nouveau le Gouvernement à\nredoubler d’efforts pour assurer, aux niveaux provincial et national, le financement par\nle budget national de ses initiatives pour la justice transitionnelle et la réforme de l’État.\nCes efforts financiers renforceront la volonté politique réitérée par le Gouvernement,\nassureront la mise en œuvre immédiate et durable des projets de justice transitionnelle,\net encourageront une participation accrue à leur financement par la coopération\nbilatérale et multilatérale."},{"id":"a-hrc-54-76-p0138","rec_id":"recFcelLCcNFThdpq","symbol":"A/HRC/54/76","n":"138","seq":140,"section":"B. Recommandations","text":"L’Équipe d’experts internationaux recommande au Gouvernement d’élaborer\nune politique qui organiserait la contribution des entreprises nationales comme\nmultinationales actives en République démocratique du Congo au financement des\ninitiatives de paix, de réconciliation, de stabilité et de développement durable."},{"id":"a-hrc-57-81-p0001","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"1","seq":0,"section":"I. Introduction","text":"In resolution 54/34 of 12 October 2022, the Human Rights Council renewed the\nmandate of the team of international experts on the Democratic Republic of the Congo and\nrequested the team to provide the necessary technical support to the Government in its\nimplementation of the national policy on transitional justice. The Council also requested the\nteam of international experts to submit its final report to the Council, in the framework of an\nenhanced interactive dialogue, at its fifty-seventh session, and to present an oral update at its\nfifty-fifth session. The present report is part of the implementation of the above-mentioned\nresolution."},{"id":"a-hrc-57-81-p0002","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"2","seq":1,"section":"I. Introduction","text":"In the resolution, the Human Rights Council requested the United Nations High\nCommissioner for Human Rights to continue providing technical assistance, including the\nnecessary forensic expertise, to the Government in order to support the judicial authorities in\ntheir investigations into allegations of human rights violations and abuses, including conflict-\nrelated sexual violence and serious violations of children's rights, with a view to bringing\nthose responsible to justice."},{"id":"a-hrc-57-81-p0003","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"3","seq":2,"section":"I. Introduction","text":"On 12 October 2023, the High Commissioner for Human Rights renewed the\nmandates of Marie-Th�r�se Keita-Bocoum (C�te d'Ivoire) and Bessol� Ren� Bagoro\n(Burkina Faso) as, respectively, chair and member of the team of international experts."},{"id":"a-hrc-57-81-p0004","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"4","seq":3,"section":"I. Introduction","text":"The team of international experts is supported by a secretariat comprising a\ncoordinator and a human rights officer specializing in transitional justice. In 2024, it made\ntwo field visits to the Democratic Republic of the Congo, from 24 to 30 March and 20 to\n30 July."},{"id":"a-hrc-57-81-p0005","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"5","seq":4,"section":"I. Introduction","text":"During these visits, the team of international experts met with a number of officials,\nincluding the Minister of State and the Minister of Justice and Keeper of the Seals; the\nMinister of Human Rights; the President of the National Human Rights Commission; the\nPermanent Secretary of the human rights liaison body; the members of the Commission on\nTruth, Justice and Reconciliation of Kasai Central Province; the focal point for transitional\njustice of the Disarmament, Demobilization, Community Recovery and Stabilization\nProgramme and the Special Representative of the Secretary-General for the Democratic\nRepublic of the Congo and the Head of MONUSCO; members of United Nations system\nentities; and members of the diplomatic corps accredited in the Democratic Republic of the\nCongo, including the Deputy Head of Mission of the Belgian Embassy and the Ambassador\nof Burundi. In its discussions with interlocutors, the team of international experts enquired\nabout progress made in the fight against impunity and the implementation of transitional\njustice."},{"id":"a-hrc-57-81-p0006","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"6","seq":5,"section":"I. Introduction","text":"On its second visit, the team of international experts took part in the inauguration of\nthe first forensic thanatology centre in the Democratic Republic of the Congo, in Bukavu,\nSouth Kivu Province, on 23 July 2024. On 24 and 25 July 2024, it took part in a workshop,\nin which all relevant actors also took part, to assess the implementation of the\nrecommendations contained in Human Rights Council resolution 54/34."},{"id":"a-hrc-57-81-p0007","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"7","seq":6,"section":"I. Introduction","text":"In accordance with Human Rights Council resolution 54/34, on 2 April 2024, the team\nof international experts gave an oral update on the situation in the Democratic Republic of\nthe Congo at the interactive dialogue held during the Council's fifty-fifth session."},{"id":"a-hrc-57-81-p0008","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"8","seq":7,"section":"I. Introduction","text":"The present report is submitted in accordance with Human Rights Council resolution\n54/34. It highlights the various activities undertaken by the team of international experts in\nfulfilment of its expanded mandate."},{"id":"a-hrc-57-81-p0009","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"9","seq":8,"section":"II. Mandate","text":"The mandate of the team of international experts was implemented against a backdrop\nof ongoing instability in the east of the country, owing to the expansion of the Mouvement\ndu 23 mars (M23), the persistent presence of several armed groups in the region and the\nhumanitarian crisis, and in the run-up to the general elections in December 2023."},{"id":"a-hrc-57-81-p0010","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"10","seq":9,"section":"II. Mandate","text":"The mandate was also implemented in parallel with the withdrawal of MONUSCO.\nIn addition, the financial situation of the United Nations had a negative impact on the\nfulfilment of the mandate of the team of international experts, forcing it to forgo several field\nvisits, including to Nairobi to continue the technical work begun with the Special Envoy of\nthe Secretary-General for the Great Lakes Region."},{"id":"a-hrc-57-81-p0011","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"11","seq":10,"section":"II. Mandate","text":"Notwithstanding this situation, the team of international experts was able to conduct\ntwo field visits to the Democratic Republic of the Congo and provide significant support to\nthe Government. The team of international experts would particularly like to thank the Office\nof the United Nations High Commissioner for Human Rights and the United Nations Joint\nHuman Rights Office in the Democratic Republic of the Congo (UNJHRO) for all their\nefforts to enable it to fulfil its mandate, especially for their mission support."},{"id":"a-hrc-57-81-p0012","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"12","seq":11,"section":"III. Cooperation between the team of international experts and","text":"Throughout its mandate, the team of international experts enjoyed direct and close\ncollaboration with the authorities of the Democratic Republic of the Congo, thus enabling it\nto carry out its work successfully."},{"id":"a-hrc-57-81-p0013","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"13","seq":12,"section":"III. Cooperation between the team of international experts and","text":"The team of international experts notes the establishment of a new government and\nthe appointment of new institutional representatives in May 2024, following the confirmation\nof the results of the presidential election on 9 January 2024, and their readiness to continue\nstrengthening the fight against impunity and respect for human rights."},{"id":"a-hrc-57-81-p0014","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"14","seq":13,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts remains concerned by the continued deterioration of\nthe security situation in the east of the country. The intensification of the conflict linked to\nthe M23 offensive, with the increased involvement of multiple actors, including countries in\nthe region,1 and the armed groups Wazalendo and Volontaires pour la d�fense de la patrie,\nhas led to serious human rights violations and abuses against civilians and a real risk of a\nregional conflict.2 The team of international experts notes that a two-week humanitarian truce\nwas announced in early July 2024, followed by a ceasefire agreement between the\nDemocratic Republic of the Congo and Rwanda, facilitated by the President of Angola and\nmade public on 31 July 2024.3"},{"id":"a-hrc-57-81-p0015","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"15","seq":14,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts is concerned that the withdrawal of MONUSCO\nfrom South Kivu Province, which was completed on 30 June 2024 at the request of the\nGovernment, has not been followed by a meaningful strengthening of the capacities of the\nCongolese armed and security forces, thus creating a security vacuum in certain areas and\nincreasing the vulnerability of the civilian population."},{"id":"a-hrc-57-81-p0016","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"16","seq":15,"section":"IV. Current security and humanitarian situation in the","text":"In North Kivu and Ituri Provinces, murderous attacks by the Allied Democratic\nForces, the Coop�rative pour le d�veloppement du Congo and various Mai-Mai armed groups\nhave adversely affected the human rights situation.4"},{"id":"a-hrc-57-81-p0017","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"17","seq":16,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts deplores the persistence of inter-community\nconflicts, particularly in the country's western provinces. In Mai-Ndombe Province, it notes\nthat despite the signing on 6 April 2024 of a deed of commitment by certain community\nleaders, in the presence of the President, to cease hostilities and move towards a peaceful\ndispute settlement, groups of armed Mobondo civilians remain active, as do military\noperations, heightening the vulnerability of civilian populations.5 It is concerned about the\nhumanitarian crisis faced by civilians, particularly displaced persons, in areas that are\ndifficult to access and poorly covered by humanitarian actors."},{"id":"a-hrc-57-81-p0018","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"18","seq":17,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts also deplores the outbreak of land-related\ninter-community conflict in Tshopo Province, between the Mbole and Lengola communities,\nwhich as has caused several deaths, massive population displacement and the destruction of\ndozens of homes.6"},{"id":"a-hrc-57-81-p0019","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"19","seq":18,"section":"IV. Current security and humanitarian situation in the","text":"On the humanitarian front, the team of international experts notes that the Democratic\nRepublic of the Congo is facing one of the world's largest displacement crises. The number\nof displaced people has risen sharply to 7.4 million, mainly in Ituri, North Kivu and South\nKivu Provinces.7"},{"id":"a-hrc-57-81-p0020","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"20","seq":19,"section":"IV. Current security and humanitarian situation in the","text":"The problem of how to access populations in need has become much more acute due\nto insecurity resulting from, among other things, attacks on humanitarian actors, some of\nwhich have been deadly,8 the absence or poor state of the road network, and administrative\nobstacles."},{"id":"a-hrc-57-81-p0021","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"21","seq":20,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts is concerned about the growing risk of armed-\nconflict-related sexual violence, especially with the intensification of armed violence in\nNorth Kivu Province. It noted cases of pregnancy resulting from rape.9"},{"id":"a-hrc-57-81-p0022","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"22","seq":21,"section":"V. Implementation of the mandate of the team of international","text":"The main purpose of the mandate of the team of international experts is to provide the\nGovernment with the technical support necessary to implement a national transitional justice\nprocess focused on the needs of victims and on strengthening the fight against impunity."},{"id":"a-hrc-57-81-p0023","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"23","seq":22,"section":"A. Fight against impunity","text":"With regard to the fight against impunity, the team of international experts continued\nto observe the administration of justice in the Democratic Republic of the Congo, including\nin emblematic legal cases, particularly those opened in connection with the crisis linked to\nthe Kamuina Nsapu militia, not to mention monitor the situation of victims.\n1. Administration of justice in the Democratic Republic of the Congo"},{"id":"a-hrc-57-81-p0024","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"24","seq":23,"section":"A. Fight against impunity","text":"The team of international experts notes with satisfaction the Government's efforts in\ncombating impunity, in particular its efforts to improve the administration of justice, both at\nthe judicial and prison levels."},{"id":"a-hrc-57-81-p0025","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"25","seq":24,"section":"A. Fight against impunity","text":"On the judicial front, the team of international experts notes that the first half of the\n5,000 judges recruited in November 2022 was effectively trained in April 2024 and has been\ndeployed across the country. It welcomes the support of international partners, including\nUNJHRO, in the preparation and conduct of this training organized by the Supreme Council\nof Justice.\n5 UNJHRO, weekly note on the situation of human rights, 11�17 May 2024.\n6 UNJHRO, annual report on the situation of human rights, 1 January�31 December 2023; UNJHRO,\nmonthly analysis on the situation of human rights, January 2024; and UNJHRO, monthly analysis of\nthe situation of human rights, March 2024.\n7 MONUSCO, MONUSCO fact sheet (briefing to the Security Council), June 2024.\n8 Ibid. See also Office of the Humanitarian Coordinator in the Democratic Republic of the Congo, \"Le\nCoordonnateur humanitaire condamne l'attaque contre un convoi humanitaire et d�plore la mort de\ndeux travailleurs humanitaires � Butembo au Nord-Kivu\" (\"Humanitarian Coordinator condemns\nattack on humanitarian convoy and deplores death of two aid workers in Butembo, North Kivu\"),\npress release, 2 July 2024.\n9 UNJHRO, monthly analysis on the situation of human rights, February 2024."},{"id":"a-hrc-57-81-p0026","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"26","seq":25,"section":"A. Fight against impunity","text":"The team of international experts congratulates the Government and the judicial\nauthorities on this important step forward, which is in line with a recommendation in its\nprevious report.10 It calls on the Government to continue the initial training of the other 2,500\njudges recruited in 2022, in order to meet the recruitment target set by the Government of\n10,000 magistrates by 2025."},{"id":"a-hrc-57-81-p0027","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"27","seq":26,"section":"A. Fight against impunity","text":"The team of international experts invites the Government to continue its efforts to\nmake initial and in-service training, particularly in the investigation and prosecution of\ninternational crimes, systematic for members of the judiciary, including by building the\ncapacities of the National Judicial Training Institute and taking advantage of South-South\ncooperation where necessary. In addition, it stresses the need to deploy judges trained in the\njudicial response to serious offences, including conflict-related sexual violence, to the areas\nconcerned."},{"id":"a-hrc-57-81-p0028","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"28","seq":27,"section":"A. Fight against impunity","text":"The team of international experts notes the predominant role of the military courts in\nthe judicial response to international crimes. It calls on the Government to undertake the\nreforms necessary to increase the involvement of civil courts, in line with international\nstandards and instruments."},{"id":"a-hrc-57-81-p0029","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"29","seq":28,"section":"A. Fight against impunity","text":"On the prison front, the team of international experts welcomes the adoption\non 15 June 2023 of Act No. 23/028 on the fundamental principles of the prison system, and\ncalls for its full and effective implementation."},{"id":"a-hrc-57-81-p0030","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"30","seq":29,"section":"A. Fight against impunity","text":"The team of international experts calls in particular for measures to be taken regarding\nthe rehabilitation and construction of detention centres and for the establishment of a\nfunctioning general directorate of prison administration to improve conditions of detention,\nreduce the mortality rate in prisons and ensure respect for prisoners' rights."},{"id":"a-hrc-57-81-p0031","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"31","seq":30,"section":"A. Fight against impunity","text":"From 24 to 30 March 2024 in Kinshasa, the team of international experts met with the\nMinister of Human Rights, the Minister of State, the Minister of Justice and Keeper of the\nSeals, members of the previous Administration and with the President of the National Human\nRights Commission. At these various meetings, the team expressed its deep concern at the\nGovernment's decision to lift the moratorium on enforcement of the death penalty amid\ngrowing consensus about universal abolition of the death penalty."},{"id":"a-hrc-57-81-p0032","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"32","seq":31,"section":"A. Fight against impunity","text":"In response to the concerns expressed by the team of international experts, the\nauthorities indicated that the reinstatement of the death penalty was a strategic measure aimed\nat restoring discipline within the army by, inter alia, preventing acts of treason."},{"id":"a-hrc-57-81-p0033","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"33","seq":32,"section":"A. Fight against impunity","text":"Following these exchanges, the team of international experts was left with the strong\nimpression that the measure was due to circumstances and had been taken for dissuasive\npurposes but that it could nonetheless be implemented if a situation warranted it."},{"id":"a-hrc-57-81-p0034","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"34","seq":33,"section":"A. Fight against impunity","text":"The team of international experts urged the authorities to reverse the decision to lift\nthe moratorium on enforcement of the death penalty, to ratify the Second Optional Protocol\nto the International Covenant on Civil and Political Rights, aiming at the abolition of the\ndeath penalty, and to complete the legislative process to abolish the death penalty in the\nDemocratic Republic of the Congo."},{"id":"a-hrc-57-81-p0035","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"35","seq":34,"section":"A. Fight against impunity","text":"The establishment of a special criminal court was also raised during the discussions\nof the team of international experts with the Minister of Justice and the President of the\nNational Human Rights Commission. This matter has already been raised several times in\nexchanges between the team of international experts and some of its interlocutors during its\nrecent visits to the country. The team of international experts has taken due note.\n2. Monitoring judicial cases"},{"id":"a-hrc-57-81-p0036","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"36","seq":35,"section":"A. Fight against impunity","text":"The team of international experts is concerned about the lack of progress in the judicial\ncases concerning the crisis linked to the Kamuina Nsapu militia."},{"id":"a-hrc-57-81-p0037","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"37","seq":36,"section":"A. Fight against impunity","text":"The team of international experts notes that, of the 16 emblematic cases opened in this\nconnection, 5 have not yet been investigated, 9 remain under investigation and 2 remain in\nthe trial phase, namely, the Mulombodi case and that of the assassination of the two\nUnited Nations experts, Zaida Catal�n and Michael Sharp."},{"id":"a-hrc-57-81-p0038","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"38","seq":37,"section":"A. Fight against impunity","text":"The team of international experts notes that an appeal hearing continues before the\nMilitary High Court in the case of the assassination of the two United Nations experts. It\nfurther notes that investigations are ongoing in the Moyo Musuila case concerning the four\npeople who were accompanying the United Nations experts."},{"id":"a-hrc-57-81-p0039","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"39","seq":38,"section":"A. Fight against impunity","text":"The team of international experts is concerned by the slow progress of these cases,\nespecially as four defendants have already died.11"},{"id":"a-hrc-57-81-p0040","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"40","seq":39,"section":"A. Fight against impunity","text":"The team of international experts encourages the judicial authorities to continue these\nlegal proceedings in order to establish the truth, assign responsibility for the offences\ncommitted in Kasai-Central Province during the crisis linked to the Kamuina Nsapu militia\nand realize the victims' right to justice. The team invites the Government, with the support\nof its partners, to continue building the capacity of professionals in the criminal justice system\nto investigate and prosecute international crimes in order to speed up and strengthen the\njudicial response."},{"id":"a-hrc-57-81-p0041","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"41","seq":40,"section":"A. Fight against impunity","text":"The team of international experts is concerned about the impact that the withdrawal\nof MONUSCO might have on the fight against impunity, for instance by slowing down or\neven hindering the judicial response. There is no doubt that the logistical support provided\nby MONUSCO is essential for successfully organizing investigative missions and mobile\ncourt hearings and for facilitating access to the judicial system for victims and witnesses."},{"id":"a-hrc-57-81-p0042","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"42","seq":41,"section":"A. Fight against impunity","text":"In Kasai-Central Province, for example, the judicial authorities with which the team\nmet mentioned that the loss of the MONUSCO-led consultation framework to support\ninternational criminal justice had resulted in loss of support for the judicial authorities and\nhad had a negative impact on the judicial response, in the absence of an increase in the human,\ntechnical and logistical resources provided by the Government."},{"id":"a-hrc-57-81-p0043","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"43","seq":42,"section":"A. Fight against impunity","text":"The team of international experts calls on the Government to strengthen its support to\nthe judicial authorities, particularly in provinces from which MONUSCO has already\nwithdrawn, and asks international partners to support these efforts as well as those of\nUnited Nations entities, including UNJHRO, aimed at strengthening the judicial response to\nserious violations and abuses of international human rights law and international\nhumanitarian law."},{"id":"a-hrc-57-81-p0044","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"44","seq":43,"section":"A. Fight against impunity","text":"Notwithstanding the above-mentioned challenges, the team of international experts\ntakes note of the efforts made by the Government and the military justice system to combat\nimpunity through the adoption of certain judicial decisions."},{"id":"a-hrc-57-81-p0045","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"45","seq":44,"section":"A. Fight against impunity","text":"In this regard, the team of international experts notes that, since October 2023,\n343 people � 38 officers of the Armed Forces of the Democratic Republic of the Congo,\n18 officers of the Congolese National Police, 223 members of armed groups and 64 civilians\n� have been convicted of offences related to violations of human rights and international\nhumanitarian law. Most of these convictions were handed down by military courts. For\nexample, in June 2024, the military court of South Kivu confirmed the conviction of three\nleaders of armed groups, who committed human rights violations, for environmental offences\nand crimes against humanity through forced pregnancy."},{"id":"a-hrc-57-81-p0046","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"46","seq":45,"section":"A. Fight against impunity","text":"The team of international experts welcomes the significant contribution of the Office\nof the United Nations High Commissioner for Human Rights to supporting the judicial\nauthorities in the fight against impunity, thanks to the expertise in forensic medicine and\nforensic psychology shared by the technical assistance team deployed to UNJHRO."},{"id":"a-hrc-57-81-p0047","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"47","seq":46,"section":"A. Fight against impunity","text":"The team of international experts also welcomes the progress made in implementing\nthe road map and recommendations under the Kinshasa Declaration adopted at the\ninternational symposium on the issues at stake and challenges in the field of forensic\nmedicine in the Democratic Republic of the Congo, held in Kinshasa in July 2023. It notes\nthat the University of Kinshasa, with technical and financial support from UNJHRO,\n11 A general prosecuted in the Mulombodi case and three defendants in the case of the assassination of\nthe two United Nations experts have died in custody.\norganized a workshop from 14 to 19 May 2024 on the preparation of skills and job profiles\nfor the establishment of a forensic medicine training programme in the country's universities.\nOn 31 May 2024, thanks to the advocacy and support of the technical assistance team, the\nCongolese College of Physicians sent to four doctors, including one woman, a letter of\nnotification officially awarding them the title of forensic doctor recognized by their peers\nand, by extension, by the State."},{"id":"a-hrc-57-81-p0048","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"48","seq":47,"section":"A. Fight against impunity","text":"In Bukavu, South Kivu Province, the technical assistance team supported the\nconstruction and inauguration of a forensic medicine centre for the living in November 2023,\nand the equipping and operationalization of the first forensic thanatology centre in the\nDemocratic Republic of the Congo, inaugurated on 23 July 2024. The team of international\nexperts welcomes the establishment of a forensic medicine and thanatology centre in\nKananga, with support from the World Bank."},{"id":"a-hrc-57-81-p0049","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"49","seq":48,"section":"A. Fight against impunity","text":"The team of international experts encourages the Government to continue its efforts\nto realize the road map and the recommendations contained in the Kinshasa Declaration, with\nexpert advice from the technical assistance team. This progress, anchored in a sustainable\napproach and focused on the development of national forensic expertise, goes some way\ntowards fulfilling one of the recommendations made in the previous report of the team of\ninternational experts."},{"id":"a-hrc-57-81-p0050","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"50","seq":49,"section":"A. Fight against impunity","text":"The team of international experts invites all international partners to support the\nCongolese Government's efforts in this area with a view to improving criminal\ninvestigations, strengthening the fight against impunity and ensuring better access to justice\nfor victims.\n3. Situation of victims"},{"id":"a-hrc-57-81-p0051","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"51","seq":50,"section":"A. Fight against impunity","text":"The team of international experts notes with satisfaction that the concerns of victims\nhave been taken into account through the promulgation of Act No. 22/065 of 26 December\n2022 on the fundamental principles of protection and redress for victims of conflict-related\nsexual violence and victims of crimes against the peace and security of humankind, pursuant\nto which registration and legal fees have been abolished for victims of such offences."},{"id":"a-hrc-57-81-p0052","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"52","seq":51,"section":"A. Fight against impunity","text":"The team of international experts notes that, on the basis of Act No. 22/065, victims\nwho had sued for damages in criminal proceedings had been exempted from legal fees in two\njudgments handed down in Kasai-Central and Ituri Provinces in August and December 2023,\nthus setting positive precedent."},{"id":"a-hrc-57-81-p0053","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"53","seq":52,"section":"A. Fight against impunity","text":"The team of international experts encourages the State to widely disseminate the\nprovisions of Act No. 22/065 among judicial authorities and potential beneficiaries, to ensure\nthat all its provisions strengthening victims' access to justice and judicial reparations are\nsystematically invoked in all future proceedings."},{"id":"a-hrc-57-81-p0054","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"54","seq":53,"section":"A. Fight against impunity","text":"The team of international experts welcomes the decision by the military judicial\nauthorities to request, under Act No. 22/065, that 120 victims undergo a medical and\npsychological assessment by the forensic psychology experts of the technical assistance team\nas part of the ongoing investigations in the Mulombodi and Nganza cases."},{"id":"a-hrc-57-81-p0055","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"55","seq":54,"section":"A. Fight against impunity","text":"The team of international experts calls for a full medical and psychological assessment\nof victims taking part in legal proceedings to be systematically requested, at any point in the\nproceedings, such that psychological harm may be taken into account more effectively,\nincluding in the determination of reparation measures. It invites the Government to broaden\nthe legal basis for the judicial authorities to request such assessments, so that they can be\nused to support victims of serious human rights violations not covered under Act No. 22/065."},{"id":"a-hrc-57-81-p0056","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"56","seq":55,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes with satisfaction the ongoing support provided\nto the Truth, Justice and Reconciliation Commission of Kasai-Central Province during its\nlaunch and preparatory phase. In particular, it welcomes the support provided by UNJHRO,\nwhich facilitated the renovation of the Commission's headquarters and made it possible for\nthe Office of the United Nations High Commissioner for Human Rights to continue providing\na transitional justice expert."},{"id":"a-hrc-57-81-p0057","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"57","seq":56,"section":"B. Implementation of the transitional justice process","text":"The team of international experts appreciates the continued implementation of the\npartnership agreement between the Truth, Justice and Reconciliation Commission of Kasai-\nCentral Province and the non-governmental organization TRIAL International, as well as the\ndetermination expressed by the United Nations Entity for Gender Equality and the\nEmpowerment of Women (UN-Women) to boost its support to the Commission."},{"id":"a-hrc-57-81-p0058","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"58","seq":57,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the enhanced synergies between itself and\nTRIAL International, UN-Women and UNJHRO enabled them to assist the Truth, Justice\nand Reconciliation Commission of Kasai-Central Province in developing, as early as\nNovember 2023, a technical partnership with 15 civil society organizations and the judicial\nauthorities based in Kananga and in finalizing the legal and strategic instruments regarding\nits operations in May 2024."},{"id":"a-hrc-57-81-p0059","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"59","seq":58,"section":"B. Implementation of the transitional justice process","text":"The team of international experts invites the Commission's partners to establish a\ncooperation framework to strengthen their coordination and the complementarity of their\nsupport efforts. It also calls on the provincial government of Kasai-Central to support the\neffective operationalization of the consultation framework it established with the\nCommission on 25 July 2023."},{"id":"a-hrc-57-81-p0060","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"60","seq":59,"section":"B. Implementation of the transitional justice process","text":"The team of international experts commends the Provincial Assembly of Kasai-\nCentral for renewing the mandate of the Commission on 18 July 2024. It calls on the\nprovincial government of Kasai-Central to promulgate the draft edict renewing the\nCommission's mandate for a further three years."},{"id":"a-hrc-57-81-p0061","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"61","seq":60,"section":"B. Implementation of the transitional justice process","text":"The team of international experts encourages the Truth, Justice and Reconciliation\nCommission of Kasai-Central Province to complete the pilot phase of its investigations in the\ncity of Kananga as soon as possible, then expand its operations to the Province's five\nterritories."},{"id":"a-hrc-57-81-p0062","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"62","seq":61,"section":"B. Implementation of the transitional justice process","text":"During its discussions with the commissioners, the team of international experts noted\nthe significant impact that the lack of State funding was having on the fulfilment of the\nmandate of the Truth, Justice and Reconciliation Commission of Kasai-Central Province."},{"id":"a-hrc-57-81-p0063","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"63","seq":62,"section":"B. Implementation of the transitional justice process","text":"The team of international experts continues to encourage the Governor of Kasai-\nCentral Province to allocate the resources necessary for the Commission to plan and\neffectively launch its investigations, among other activities. It also invites the national\nGovernment to provide supplemental financial support to the Commission."},{"id":"a-hrc-57-81-p0064","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"64","seq":63,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the financial support provided by\ninternational partners, particularly UNJHRO, to the Truth, Justice and Reconciliation\nCommission of Kasai-Central Province. It notes especially the commitment of the\nPeacebuilding Fund to support the operations of the Commission over the next three years.\nThe team of international experts invites other donors to step up their support for the\ntransitional justice process in Kasai-Central Province.\n2. Implementation of the transitional justice process at the national level"},{"id":"a-hrc-57-81-p0065","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"65","seq":64,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the President's determination to place the\nkey objectives of transitional justice at the heart of the presidential programme for his second\nterm. It encourages the Government to take greater account of transitional justice in its\nprogramme of action for the period 2024�2028."},{"id":"a-hrc-57-81-p0066","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"66","seq":65,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the organization and holding of the 2023\ngeneral elections slowed the progress of the transitional justice process. It remains convinced\nthat the installation of the Government will further strengthen commitment to this process."},{"id":"a-hrc-57-81-p0067","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"67","seq":66,"section":"B. Implementation of the transitional justice process","text":"The team of international experts commends the Government's efforts to revitalize\nand operationalize the human rights liaison body, a government monitoring, warning and\nadvocacy mechanism in the area of human rights, including transitional justice."},{"id":"a-hrc-57-81-p0068","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"68","seq":67,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the technical and financial support that it\nand UNJHRO provided for the first ordinary meeting of the human rights liaison body, held\non 16 November 2023, which marked the official launch of the body's activities and resulted\nin an amendment to Decree No. 09/35 of 12 August 2009 on the establishment, organization\nand functioning of the body to, inter alia, add monitoring of the transitional justice process\nto the its remit. The team encourages the Government to promulgate the amended decree and\ncontinue the operationalization of the body."},{"id":"a-hrc-57-81-p0069","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"69","seq":68,"section":"B. Implementation of the transitional justice process","text":"The team of international experts also welcomes the deployment by the Office of the\nUnited Nations High Commissioner for Human Rights of a human rights officer specializing\nin transitional justice within the Ministry of Human Rights to support the Ministry's\nimplementation of the transitional justice process."},{"id":"a-hrc-57-81-p0070","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"70","seq":69,"section":"B. Implementation of the transitional justice process","text":"This support enabled the Ministry of Human Rights, in collaboration with UNJHRO,\nthe team of international experts and UN-Women, to validate its strategic action plan for\nhuman rights and transitional justice in August 2023. The team of international experts invites\nthe Government and its partners to support the implementation of the strategic action plan."},{"id":"a-hrc-57-81-p0071","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"71","seq":70,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes with satisfaction that the National Reparations\nFund for Victims of Conflict-Related Sexual Violence and Other Crimes against the Peace\nand Security of Humankind in the Democratic Republic of the Congo (FONAREV) and the\nInter-Institutional Commission for Assistance to Victims and Support for Reforms (CIA-\nVAR), responsible for overseeing the development of reparations programmes by\nFONAREV, are now operational."},{"id":"a-hrc-57-81-p0072","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"72","seq":71,"section":"B. Implementation of the transitional justice process","text":"The team of international experts appreciates the collaboration among FONAREV,\nCIA-VAR and UNJHRO, which in May 2023 facilitated an exchange of expertise, in the\nframework of South-South cooperation, with experts from the Victims Trust Fund of the\nInternational Criminal Court and other international experts. It notes with satisfaction the\ndeepening of such cooperation during a study visit to C�te d'Ivoire by a FONAREV\ndelegation in June 2024, organized with support from UNJHRO."},{"id":"a-hrc-57-81-p0073","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"73","seq":72,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the operational launch of the Special\nReparations and Compensation Fund for Victims of Illicit Activities by Uganda (FRIVAO),\nwhich is mandated to administer the reparations awarded by the International Court of Justice\nto Congolese victims of harm caused by Uganda during the armed conflict from August 1998\nto June 2003.12"},{"id":"a-hrc-57-81-p0074","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"74","seq":73,"section":"B. Implementation of the transitional justice process","text":"The team of international experts stresses that it is essential for ongoing reparations\nprojects to be implemented in a transparent manner to ensure that these transitional justice\ninitiatives effectively contribute to boosting the population's confidence in the State and\npromoting national reconciliation."},{"id":"a-hrc-57-81-p0075","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"75","seq":74,"section":"B. Implementation of the transitional justice process","text":"The team of international experts calls on FONAREV and FRIVAO, with the support\nof their respective lead ministries, to continue developing reparations programmes that are\nfocused on the needs of victims, facilitate access to different forms of individual and\ncollective reparations13 and promote the social reintegration of victims."},{"id":"a-hrc-57-81-p0076","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"76","seq":75,"section":"B. Implementation of the transitional justice process","text":"The team of international experts also calls on FONAREV and FRIVAO to work with\nUNJHRO and other international partners to strengthen experience-sharing initiatives in the\ncontext of South-South cooperation."},{"id":"a-hrc-57-81-p0077","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"77","seq":76,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the determination of the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme to foster synergies\nbetween it and ongoing transitional justice initiatives. It also welcomes the appointment by\nthe Programme of a transitional justice focal point and the organization in June 2024, with\nsupport from UNJHRO, of a workshop on the links between the Programme and transitional\njustice."},{"id":"a-hrc-57-81-p0078","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"78","seq":77,"section":"B. Implementation of the transitional justice process","text":"The team of international experts takes note of the development by the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme of an initial proposal\nfor a screening procedure. Such a procedure would be essential to ensure that the Programme\ndoes not become a mechanism for promoting impunity and to strike a balance between\ncommunity reintegration strategies for former combatants and respect for victims' rights."},{"id":"a-hrc-57-81-p0079","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"79","seq":78,"section":"B. Implementation of the transitional justice process","text":"The team of international experts calls on the Government and its partners to step up\ntheir technical and financial support to accelerate the implementation of the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme and the development of\nsynergies between the Programme and transitional justice initiatives at the national and\nsubregional levels."},{"id":"a-hrc-57-81-p0080","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"80","seq":79,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes with interest the intensification of official\ncommunications around transitional justice initiatives, including the celebration of the\nnational day of homage to victims of conflict-related sexual violence and to victims of crimes\nagainst the peace and security of humankind,14 commonly known as \"Genocost\"."},{"id":"a-hrc-57-81-p0081","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"81","seq":80,"section":"B. Implementation of the transitional justice process","text":"The team of international experts encourages the Government to increase\ncommunication and awareness-raising initiatives on transitional justice, in various local\nlanguages, that are focused on the needs and perspectives of victims and respect their dignity\nand the \"do no harm\" principle. This is essential to strengthen the impact of these initiatives\non all communities and to help victims take ownership of and participate in them.\n3. Challenges in the implementation of the transitional justice process in the Democratic\nRepublic of the Congo"},{"id":"a-hrc-57-81-p0082","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"82","seq":81,"section":"B. Implementation of the transitional justice process","text":"The team of international experts identified four major challenges concerning the\ntransitional justice process: (a) the lack of consistent and coordinated design and\nimplementation of transitional justice initiatives based on an overall vision focused on the\nneeds of victims; (b) the lack of sufficient effective funding to implement the transitional\njustice process; (c) the fact that transitional justice is being applied in a context of insecurity\nand inter-community conflicts; and (d) the growing impact of the cross-border dimension of\nconflicts.\n(a) Lack of consistent and coordinated design and implementation of transitional justice\ninitiatives based on an overall vision focused on the needs of victims"},{"id":"a-hrc-57-81-p0083","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"83","seq":82,"section":"B. Implementation of the transitional justice process","text":"The team of international experts reiterates that weakness in the coordination of\ntransitional justice initiatives, at both national and provincial levels, is an obstacle to the\nrealization of a comprehensive transitional justice process that is focused on the needs of\nvictims and effectively contributes to peace, the strengthening of the rule of law, the\npromotion of reconciliation and the development of the country."},{"id":"a-hrc-57-81-p0084","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"84","seq":83,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the draft national policy on transitional\njustice, aimed at defining the Government's vision and conceptual and institutional\nframework for transitional justice in the Democratic Republic of the Congo, which was\nsubmitted to the Ministry of Human Rights in January 2023, does not yet include the\nrecommendations arising from the national consultations on transitional justice organized by\nthe Ministry of Human Rights with support from UNJHRO."},{"id":"a-hrc-57-81-p0085","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"85","seq":84,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the draft national policy does not at this\nstage include any reference to several ongoing transitional justice initiatives, in particular\nFONAREV, FRIVAO and the Disarmament, Demobilization, Community Recovery and\nStabilization Programme. It nonetheless notes with satisfaction the initiative of FONAREV\nand the Truth, Justice and Reconciliation Commission of Kasai-Central Province to work\n14 Democratic Republic of the Congo, Act No. 22/065 of 26 December 2022 on the fundamental\nprinciples of protection and redress for victims of conflict-related sexual violence and victims of\ncrimes against the peace and security of humankind, art. 28.\ntogether to establish a common consultation framework for harmonizing their approaches\nand ensuring the complementarity of their actions in Kasai-Central Province."},{"id":"a-hrc-57-81-p0086","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"86","seq":85,"section":"B. Implementation of the transitional justice process","text":"The team of international experts is concerned, however, about the development of a\nnational policy on reparations, under the aegis of FONAREV and CIA-VAR, separately from\nthe process to finalize the national policy on transitional justice."},{"id":"a-hrc-57-81-p0087","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"87","seq":86,"section":"B. Implementation of the transitional justice process","text":"The consistency, coordination and complementarity sought by the Government\namong the various ongoing transitional justice initiatives should be made explicit in the final\nversion of the national policy on transitional justice. Otherwise, there might be duplication\nof efforts, loss of resources and even obstacles to the fulfilment of the mandates of the various\ninstitutions already in operation."},{"id":"a-hrc-57-81-p0088","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"88","seq":87,"section":"B. Implementation of the transitional justice process","text":"The national policy on transitional justice would enable the Government to establish\na single national framework, focused on the needs of victims, to continue the coordinated\nimplementation, based on a common vision, of all the pillars of transitional justice at the\nprovincial, national and subregional levels."},{"id":"a-hrc-57-81-p0089","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"89","seq":88,"section":"B. Implementation of the transitional justice process","text":"The team of international experts reiterates its call to the Ministry of Human Rights\nto continue and conclude the national consultations on transitional justice, in compliance with\ninternational standards and instruments, and to publish and disseminate widely the results of\nthe consultations so that they may inform the final version of the national policy on\ntransitional justice. The team invites the Government to adopt the national policy on\ntransitional justice and collectively commit to its effective implementation, with the support\nof its technical and financial partners."},{"id":"a-hrc-57-81-p0090","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"90","seq":89,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes the absence of a mechanism for cooperation\namong technical and financial partners providing support for the transitional justice process,\nat both the national and provincial levels. It calls for the establishment of such a mechanism\nto effectively coordinate support for the transitional justice process.\n(b) Lack of sufficient effective funding to implement the transitional justice process"},{"id":"a-hrc-57-81-p0091","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"91","seq":90,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the innovative approach developed under\nAct No. 22/065, thanks to which 11 per cent of mining royalties are now allocated to\nFONAREV reparation programmes. It invites the Government to adopt similar approaches\nto strengthen the private sector's contribution to the financing of all transitional justice\ninitiatives."},{"id":"a-hrc-57-81-p0092","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"92","seq":91,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes the efforts of the Congolese Government to\nfinancially support FONAREV. However, it would like this support to be expanded to all\ntransitional justice initiatives currently under way. Such financial efforts would ensure\nnational ownership of the transitional justice process and encourage greater participation by\nbilateral and multilateral partners."},{"id":"a-hrc-57-81-p0093","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"93","seq":92,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes the low level of mobilization of international\npartners for the financing of the transitional justice process and regrets that the current\nfinancial difficulties of the United Nations Secretariat have had an impact on the support\nprovided by the Office of the United Nations High Commissioner for Human Rights to the\ntransitional justice process, particularly with regard to the deployment of additional technical\nexperts."},{"id":"a-hrc-57-81-p0094","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"94","seq":93,"section":"B. Implementation of the transitional justice process","text":"The team of international experts calls on the Office of the United Nations High\nCommissioner for Human Rights and international partners to step up their financial support\nfor the transitional justice process in the Democratic Republic of the Congo, in line with its\nprevious recommendations and requests by the Human Rights Council.\n(c) Applying transitional justice in a context of insecurity and inter-community conflicts"},{"id":"a-hrc-57-81-p0095","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"95","seq":94,"section":"B. Implementation of the transitional justice process","text":"The team of international experts is concerned by the withdrawal of MONUSCO from\nSouth Kivu Province at a time when several provinces in the east of the country are facing\nsituations of armed conflict and inter-community strife."},{"id":"a-hrc-57-81-p0096","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"96","seq":95,"section":"B. Implementation of the transitional justice process","text":"The team of international experts calls on the Government and the Security Council\nto consider the major challenges in terms of access, security and human rights protection that\nthe next stages of the withdrawal of MONUSCO might cause in the absence of deployment\nof sufficient trained national armed and security forces who respect international\nhumanitarian and human rights law.\n(d) Growing impact of the cross-border dimension of conflicts"},{"id":"a-hrc-57-81-p0097","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"97","seq":96,"section":"B. Implementation of the transitional justice process","text":"The team of international experts observes with concern the worsening regional\ntensions due to the conflicts, particularly in the east of the country. It notes that prioritizing\nthe military approach taken thus far in response to security and humanitarian challenges\ncannot in itself bring about peace or meet the needs expressed by the population concerned."},{"id":"a-hrc-57-81-p0098","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"98","seq":97,"section":"B. Implementation of the transitional justice process","text":"The team of international experts points out the need for the Government and all\nstakeholders to step up their involvement in the implementation of the Nairobi Process, under\nthe aegis of the East African Community, and the Luanda road map, under the auspices of\nthe African Union, and to incorporate in these processes a human rights-based approach\nthrough transitional justice to achieve lasting peace. It also invites the Government to\nstrengthen dialogue with countries in the region through other existing subregional\ncooperation initiatives."},{"id":"a-hrc-57-81-p0099","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"99","seq":98,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes the importance for the Government of\nintensifying implementation of the Disarmament, Demobilization, Community Recovery and\nStabilization Programme. It stresses that a coherent, long-term strategy for the demobilization\nof armed groups, taking into account the impact of the establishment of the Armed Defense\nReserve, is needed to support the implementation of regional political processes."},{"id":"a-hrc-57-81-p0100","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"100","seq":99,"section":"B. Implementation of the transitional justice process","text":"The team of international experts underscores the vital importance of strengthening\nregional judicial cooperation to intensify the fight against impunity for cross-border offences,\nincluding in relation to the illegal exploitation of natural resources. It commends the efforts\nof MONUSCO and the Special Envoy of the Secretary-General for the Great Lakes Region\nto build the capacities of the Great Lakes Judicial Cooperation Network and invites the Office\nof the United Nations High Commissioner for Human Rights to become more involved in\nthose efforts."},{"id":"a-hrc-57-81-p0101","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"101","seq":100,"section":"A. Conclusions","text":"The team of international experts welcomes the excellent cooperation by the\nauthorities of the Democratic Republic of the Congo and would like to express its deep\ngratitude to them. It also welcomes the essential support of UNJHRO, MONUSCO and\nthe entire United Nations system."},{"id":"a-hrc-57-81-p0102","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"102","seq":101,"section":"A. Conclusions","text":"The team of international experts notes that, since its last report, the security and\nhumanitarian situation in the country has deteriorated significantly. It welcomes the\nannouncement of a humanitarian truce and ceasefire in July 2024, and strongly hopes\nthat these will be swiftly implemented to address the extreme vulnerability of the\ncivilian population."},{"id":"a-hrc-57-81-p0103","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"103","seq":102,"section":"A. Conclusions","text":"The team of international experts regrets the limited progress, and even\nslowdown, in the fight against impunity and the development of a comprehensive\nnational transitional justice process focused on the needs of victims, due to differing\npolitical agendas, particularly regarding the electoral context and the installation of the\nnew Government."},{"id":"a-hrc-57-81-p0104","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"104","seq":103,"section":"A. Conclusions","text":"The team of international experts invites the Government to strengthen its\nsupport for the judicial response to serious violations and abuses of international\nhuman rights law and international humanitarian law, particularly conflict-related\nsexual violence. This must include reinforced deployment of the judicial authorities in\nthe country, as well as the strengthening of their technical and operational capacities,\nincluding the development of national expertise in forensic medicine and forensic\npsychology."},{"id":"a-hrc-57-81-p0105","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"105","seq":104,"section":"A. Conclusions","text":"The team of international experts reiterates the need for the Government to\nstrengthen coordination of and support to the national transitional justice process,\nincluding financial support, taking into account the history, context and needs of the\npopulation of each affected province, to ensure the coherence and participatory nature\nof the process and its effectiveness in promoting peace, reconciliation and development."},{"id":"a-hrc-57-81-p0106","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"106","seq":105,"section":"A. Conclusions","text":"The implementation of the national transitional justice process becomes essential\nin the context of the withdrawal of MONUSCO. In this regard, the entities of the\nUnited Nations system, particularly UNJHRO, whose resources must be increased,\nhave a key role to play in supporting the Government's efforts."},{"id":"a-hrc-57-81-p0107","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"107","seq":106,"section":"B. Recommendations","text":"The team of international experts recalls the need to pursue the implementation\nof the recommendations made in its previous reports. It reiterates some of these\nrecommendations and makes new ones.\n1. Vision and coordination of transitional justice initiatives"},{"id":"a-hrc-57-81-p0108","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"108","seq":107,"section":"B. Recommendations","text":"The team of international experts recommends that the Government maintain\ntransitional justice as a priority objective as part of a high-level, consistent and\ncomplementary basis for the realization of its programme of action for the period\n2024�2028."},{"id":"a-hrc-57-81-p0109","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"109","seq":108,"section":"B. Recommendations","text":"The team of international experts urges the Government to finalize and\nimplement the national policy on transitional justice, taking into account the results of\nnational consultations, so that the policy reflects the perspectives of victims and\ncommunities in the various provinces."},{"id":"a-hrc-57-81-p0110","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"110","seq":109,"section":"B. Recommendations","text":"The team of international experts invites the Government to promulgate as soon\nas possible the revised version of the decree establishing the human rights liaison body\nand urges it to ensure the body's effective functioning."},{"id":"a-hrc-57-81-p0111","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"111","seq":110,"section":"B. Recommendations","text":"The team of international experts urges the Disarmament, Demobilization,\nCommunity Recovery and Stabilization Programme to develop synergies between it\nand ongoing transitional justice initiatives, specifically by prioritizing the development\nof screening mechanisms and adopting a consistent demobilization strategy."},{"id":"a-hrc-57-81-p0112","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"112","seq":111,"section":"B. Recommendations","text":"The team of international experts invites international partners supporting the\ntransitional justice process to strengthen their coordination and complementarity at the\nnational and provincial levels by establishing a framework for cooperation and\nsupporting the implementation of the Government's strategic action plan.\n2. Prevention of impunity"},{"id":"a-hrc-57-81-p0113","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"113","seq":112,"section":"B. Recommendations","text":"The team of international experts once again calls on the Government to continue\nits efforts to provide appropriate initial and in-service training for judges, to build the\ncapacity of professionals in the criminal justice system to investigate and prosecute\ninternational crimes, and to assign judges trained in this field to the areas concerned."},{"id":"a-hrc-57-81-p0114","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"114","seq":113,"section":"B. Recommendations","text":"The team of international experts urges the Government to undertake reforms\nto strengthen the capacity of the civil courts, so that they become more involved in the\nfight against impunity for international crimes."},{"id":"a-hrc-57-81-p0115","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"115","seq":114,"section":"B. Recommendations","text":"The team of international experts recommends that the Government implement\nall the provisions of Act No. 23/028 on the fundamental principles of the prison system,\nadopted on 15 June 2023."},{"id":"a-hrc-57-81-p0116","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"116","seq":115,"section":"B. Recommendations","text":"The team of international experts calls on the Government to reverse its decision\nto lift the moratorium on enforcement of the death penalty, and to pursue dialogue with\nits partners in order to find a solution that respects the fundamental rights and human\ndignity of all."},{"id":"a-hrc-57-81-p0117","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"117","seq":116,"section":"B. Recommendations","text":"The team of international experts invites the Government to continue its efforts\nto implement the road map and the recommendations contained in the Kinshasa\nDeclaration resulting from the work of the international symposium on the issues at\nstake and challenges in the field of forensic medicine in the Democratic Republic of the\nCongo."},{"id":"a-hrc-57-81-p0118","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"118","seq":117,"section":"B. Recommendations","text":"The team of international experts recommends that the Human Rights Council\nbuild the capacities of the technical assistance team by increasing its human and\ntechnical resources so that it may continue to strengthen national efforts to combat\nimpunity."},{"id":"a-hrc-57-81-p0119","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"119","seq":118,"section":"B. Recommendations","text":"The team of international experts encourages the authorities of the Democratic\nRepublic of the Congo and the International Criminal Court to pursue and strengthen\ntheir cooperation.\n3. Consideration of victims at all stages of the transitional justice process"},{"id":"a-hrc-57-81-p0120","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"120","seq":119,"section":"B. Recommendations","text":"The team of international experts urges the Government to ensure the active,\neffective and secure participation of victims in the transitional justice process, including\nongoing national consultations on the matter."},{"id":"a-hrc-57-81-p0121","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"121","seq":120,"section":"B. Recommendations","text":"The team of international experts invites the Government to ensure that\ninformation on the measures set out in Act No. 22/065 of 26 December 2022 is widely\ndisseminated among the judicial authorities, victims and their representatives, so that\nvictims can avail themselves of the measures, thus strengthening their access to justice."},{"id":"a-hrc-57-81-p0122","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"122","seq":121,"section":"B. Recommendations","text":"The team of international experts calls on the judicial authorities to\nsystematically request medical and psychological assessments for victims of\ninternational crimes involved in legal proceedings, including by broadening the legal\nbasis for requesting such assessments."},{"id":"a-hrc-57-81-p0123","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"123","seq":122,"section":"B. Recommendations","text":"The team of international experts urges FONAREV and FRIVAO to coordinate\ntheir approaches, including with other transitional justice initiatives, under the\nsupervision of their respective lead ministries, to support the development of\ncomprehensive individual and collective reparations programmes focused on the needs\nof victims.\n4. Conflict prevention and guarantees of non-repetition"},{"id":"a-hrc-57-81-p0124","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"124","seq":123,"section":"B. Recommendations","text":"The team of international experts urges the Government to tackle the\nhumanitarian and protection crises and the resulting gross violations and abuses of\ninternational humanitarian and human rights law by taking all measures to end armed\nconflict. It recommends that the Government make it a priority to provide lasting\nsolutions based on human rights through transitional justice, including accountability\nfor the perpetrators of these violations and abuses."},{"id":"a-hrc-57-81-p0125","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"125","seq":124,"section":"B. Recommendations","text":"The team of international experts reiterates its recommendation that the Office\nof the United Nations High Commissioner for Human Rights continue its efforts to\nstrengthen the capacities of the Armed Forces of the Democratic Republic of the Congo\nin the field of human rights and international humanitarian law, especially in the\ncontext of the withdrawal of MONUSCO."},{"id":"a-hrc-57-81-p0126","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"126","seq":125,"section":"B. Recommendations","text":"The team of international experts calls on development partners and the\ninternational community to support the Government in facilitating civilians' access to\na humanitarian response adapted to their most pressing needs.\n5. Public, private and international funding of the transitional justice process"},{"id":"a-hrc-57-81-p0127","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"127","seq":126,"section":"B. Recommendations","text":"The team of international experts calls on the provincial government of Kasai-\nCentral to provide adequate financial, material and human resources to ensure the full\nimplementation of the mandate of the Truth, Justice and Reconciliation Commission of\nKasai-Central Province."},{"id":"a-hrc-57-81-p0128","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"128","seq":127,"section":"B. Recommendations","text":"The team of international experts reiterates its call on the Government to ensure\nthat its transitional justice and State reform initiatives are funded from the national\nbudget at both the central and provincial levels."},{"id":"a-hrc-57-81-p0129","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"129","seq":128,"section":"B. Recommendations","text":"The team of international experts invites the Government to continue developing\npolicy mechanisms to organize the contributions of national and multinational\ncompanies operating in the Democratic Republic of the Congo to the funding of peace,\nreconciliation, stability and sustainable development initiatives, modelled on the\npioneering initiative for the financing of FONAREV."},{"id":"a-hrc-57-81-p0130","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"130","seq":129,"section":"B. Recommendations","text":"The team of international experts once again encourages donors to step up their\nsupport for the transitional justice process at the national and provincial levels in the\nDemocratic Republic of the Congo.\n6. Subregional dimension of the transitional justice process"},{"id":"a-hrc-57-81-p0131","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"131","seq":130,"section":"B. Recommendations","text":"The team of international experts urges the Government to support the\nresumption of the implementation of the Nairobi Process and the Luanda road map,\nincluding for the purpose of integrating a human rights-based approach through\ntransitional justice, with the aim of taking into account subregional dynamics in the\nsearch for the root causes of conflicts and the prevention of their recurrence."},{"id":"a-hrc-57-81-p0132","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"132","seq":131,"section":"B. Recommendations","text":"The team of international experts recommends that the Government strengthen\ndialogue with countries in the region through other existing subregional cooperation\ninitiatives, including to promote subregional transitional justice initiatives."},{"id":"a-hrc-57-81-p0133","rec_id":"recRKoUWhEAMnMLuM","symbol":"A/HRC/57/81","n":"133","seq":132,"section":"B. Recommendations","text":"The team of international experts reiterates its call for closer cooperation\nbetween the Special Envoy of the Secretary-General for the Great Lakes Region and\nthe Office of the United Nations High Commissioner for Human Rights to further\nsupport the Great Lakes Judicial Cooperation Network."},{"id":"a-hrc-60-83-u0000","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":null,"seq":0,"section":null,"text":"United Nations                                                                                   A/HRC/60/83\nGeneral Assembly                                                           Distr.: General\n20 August 2025\nEnglish\nOriginal: French","unnumbered":true},{"id":"a-hrc-60-83-u0001","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":null,"seq":1,"section":null,"text":"Human Rights Council\nSixtieth session\n8 September–3 October 2025\nAgenda items 2 and 10\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General\nTechnical assistance and capacity-building","unnumbered":true},{"id":"a-hrc-60-83-u0002","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":null,"seq":2,"section":null,"text":"Summary\nBy resolution 57/34 of 11 October 2024, the Human Rights Council renewed the\nmandate of the team of international experts on the Democratic Republic of the Congo and\nrequested the team to provide the necessary technical support to the Government in\nimplementing effectively its National Transitional Justice Policy. The Council requested the\nteam of international experts to submit its final report at its sixtieth session.\nThe mandate was carried out against a backdrop of continuing tensions between the\nDemocratic Republic of the Congo and Rwanda, a worsening security and humanitarian\nsituation in the east of the country, and the withdrawal of the United Nations Organization\nStabilization Mission in the Democratic Republic of the Congo.\nThe team of international experts carried out three field visits, enabling it to assess\nremaining challenges and the options to be explored to promote the fight against impunity\nand transitional justice at the provincial, national and subregional levels.\nLastly, the team of international experts offered its conclusions and made\nrecommendations with a view to strengthening current and future activities.","unnumbered":true},{"id":"a-hrc-60-83-u0003","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":null,"seq":3,"section":null,"text":" Reissued for technical reasons on 16 September 2025.\n** Agreement was reached to publish the present report after the standard publication date owing to\ncircumstances beyond the submitter’s control.","unnumbered":true},{"id":"a-hrc-60-83-p0001","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"1","seq":4,"section":"I. Introduction","text":"By resolution 57/34 of 11 October 2024, the Human Rights Council renewed the\nmandate of the team of international experts on the Democratic Republic of the Congo and\nrequested the team to provide the necessary technical support to the Government in\nimplementing effectively its National Transitional Justice Policy, in particular by taking\naccount of the cross-border nature of conflict and insecurity in the Great Lakes, identifying\nthe causes of conflict and preventing their recurrence, and designing and implementing\nmechanisms for transitional justice and the fight against impunity, and encouraged it to\nsupport the Government in this regard, in particular by proposing concrete measures. This\nmandate was reiterated in Council resolution S-37/1 of 7 February 2025."},{"id":"a-hrc-60-83-p0002","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"2","seq":5,"section":"I. Introduction","text":"The Council requested the team of international experts to submit its final report to\nthe Council, in the framework of an enhanced interactive dialogue, at its sixtieth session and\nto present it with an oral update at its fifty-eighth session."},{"id":"a-hrc-60-83-p0003","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"3","seq":6,"section":"I. Introduction","text":"In the same resolution, the Council requested the High Commissioner to continue to\nprovide the Government of the Democratic Republic of the Congo with technical assistance,\nincluding the necessary forensic expertise, to support the country’s judicial authorities in their\ninvestigations into allegations of serious human rights violations and abuses, including\nconflict-related sexual violence and grave violations of children’s rights, with a view to\nbringing the perpetrators to justice."},{"id":"a-hrc-60-83-p0004","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"4","seq":7,"section":"I. Introduction","text":"On 11 October 2024, the High Commissioner for Human Rights renewed the\nmandates of Marie-Thérèse Keita-Bocoum (Côte d’Ivoire) and Bessolé René Bagoro\n(Burkina Faso) as, respectively, chair and member of the team of international experts."},{"id":"a-hrc-60-83-p0005","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"5","seq":8,"section":"I. Introduction","text":"In carrying out its mandate, the team of international experts was supported by a\nsecretariat comprising a coordinator and a human rights officer specializing in transitional\njustice. It conducted three field visits to the Democratic Republic of the Congo.1"},{"id":"a-hrc-60-83-p0006","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"6","seq":9,"section":"I. Introduction","text":"During its visits, the team of international experts met with a number of Congolese\nofficials, 2 members of the diplomatic corps, 3 representatives of United Nations agencies,\nfunds and programmes,4 members of the panel of facilitators of the African mediation process\nfor peace in the Democratic Republic of the Congo, 5 established by the African Union,\ninternational non-governmental organizations, 6 the Kasai-Central Truth, Justice and\nReconciliation Commission and civil society. The team of international experts was briefed\non the progress made in the fight against impunity and the implementation of transitional\njustice, and it provided technical support to the authorities in these areas."},{"id":"a-hrc-60-83-p0007","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"7","seq":10,"section":"I. Introduction","text":"On 1 April 2025, the team of international experts presented its oral report during the\ninteractive dialogue held as part of the Council’s fifty-eighth session."},{"id":"a-hrc-60-83-p0008","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"8","seq":11,"section":"I. Introduction","text":"The present report is submitted by the team of international experts, in accordance\nwith Council resolution 57/34, adopted on 11 October 2024. It highlights the various\nactivities undertaken by the team of international experts in fulfilment of its expanded\nmandate."},{"id":"a-hrc-60-83-p0009","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"9","seq":12,"section":"II. Mandate","text":"The team of international experts carried out its mandate against a backdrop of\nworsening armed conflict in the east of the country,7 with the expansion of the Mouvement\ndu 23 mars (M23) and the Rwanda Defence Force into the North and South Kivu Provinces,\nwhich has had humanitarian and security-related consequences that are ongoing at the time\nof writing. However, a number of important peace initiatives give cause for hope. On 19 July\n2025, the Government of the Democratic Republic of the Congo and a delegation\nrepresenting the coalition of Alliance Fleuve Congo (AFC) and M23 signed a declaration of\nprinciples in Doha. On 27 June 2025, the Governments of the Democratic Republic of the\nCongo and of Rwanda signed a peace agreement in Washington, D.C., under the auspices of\nthe United States of America."},{"id":"a-hrc-60-83-p0010","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"10","seq":13,"section":"II. Mandate","text":"The team of international experts completed its mandate in October 2024 when the\nDemocratic Republic of the Congo was elected to the Human Rights Council for the period\n2025–2027. The Democratic Republic of the Congo supported 235 of the 284\nrecommendations made during the fourth cycle of the universal periodic review. 8 These are\nopportunities for the country to strengthen its commitment to human rights."},{"id":"a-hrc-60-83-p0011","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"11","seq":14,"section":"II. Mandate","text":"The mandate was carried out in parallel with the withdrawal of the United Nations\nOrganization Stabilization Mission in the Democratic Republic of the Congo (MONUSCO).\nThe financial situation of the United Nations has had a negative impact on the mandate of\nthe team of international experts, forcing it to forego several field visits to the country and\nthe subregion and several other activities relating to its mandate."},{"id":"a-hrc-60-83-p0012","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"12","seq":15,"section":"II. Mandate","text":"Nevertheless, the team of international experts conducted three visits to the\nDemocratic Republic of the Congo and provided significant support to the Government. The\nteam of international experts would like to thank in particular the United Nations Joint\nHuman Rights Office in the Democratic Republic of the Congo and MONUSCO for their\nsupport."},{"id":"a-hrc-60-83-p0013","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"13","seq":16,"section":"III. Cooperation between the team of international experts and","text":"The team of international experts thanks the authorities of the Democratic Republic\nof the Congo for their fruitful cooperation, which facilitated its work."},{"id":"a-hrc-60-83-p0014","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"14","seq":17,"section":"III. Cooperation between the team of international experts and","text":"The team of international experts particularly appreciated its exchanges with the\nhighest authorities of the State, which enabled it to provide support in relation to the crisis in\nthe east of the country, to comment on various aspects concerning its mandate and to obtain\n6 Avocats sans frontières, Impunity Watch, TRIAL International, Solidarité féminine pour la paix et le\ndéveloppement intégral (SOFEPADI) and Coalition nationale des groupes de victimes en République\ndémocratique du Congo.\n7 https://news.un.org/fr/story/2025/01/1152571.\n8 See A/HRC/58/6/Add.1.\nstrategic information for the implementation of its new mandate in order to formulate relevant\nrecommendations to stakeholders."},{"id":"a-hrc-60-83-p0015","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"15","seq":18,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts remains deeply concerned about the deteriorating\nsecurity situation in the east of the country following the offensive led by M23 and RDF in\nthe North Kivu and South Kivu Provinces. It deplores the victims of this offensive among\nthe civilian population, the Congolese army, MONUSCO peacekeepers and soldiers of the\nSouthern African Development Community Mission in the Democratic Republic of the\nCongo."},{"id":"a-hrc-60-83-p0016","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"16","seq":19,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts laments the consequences of this escalation of\nviolence, notably the escape of major war criminals, the destruction of courts, a rise in crime\nand an increase in cases of kidnapping and vigilante justice. In addition, threats have been\nmade against members of the judiciary, human rights defenders, journalists, traditional\nleaders, and victims and witnesses involved in trials for serious crimes. 9"},{"id":"a-hrc-60-83-p0017","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"17","seq":20,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts is concerned about the worsening humanitarian\ncrisis, which is causing major displacements of the population inside and outside the country.\nIt notes the serious violations of international humanitarian law and the forced displacement\nof thousands of people, the difficulties in providing basic social services and the obstacles to\nthe delivery of humanitarian aid in areas affected by the security crisis. It deplores the threats\nagainst health workers and the kidnappings to which they are subjected, as well as the attacks\non medical facilities, looting of medicine supplies and destruction of medical equipment in\nthe affected provinces. All of this severely restricts the population’s access to primary\nhealthcare and results in reduced support from humanitarian organizations."},{"id":"a-hrc-60-83-p0018","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"18","seq":21,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts deplores the persistence of inter-community\nconflicts in the provinces not affected by armed conflict. For instance, Mai-Ndombe Province\nis marked by inter-community conflict, with numerous victims among the Teke and Yaka\ncommunities, and by clashes between soldiers of the Armed Forces of the Democratic\nRepublic of the Congo and “Mobondo” groups. In Tshopo province, an ongoing\nintercommunity conflict between the Mbole and Lengola communities has led to massive\npopulation displacement."},{"id":"a-hrc-60-83-p0019","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"19","seq":22,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts is concerned about the increase in cases of sexual\nviolence, including in the context of community conflicts. It notes that women and girls,\nparticularly those who have been displaced, have been raped, and in many cases gang-raped,\nby members of M23, the Allied Democratic Forces and the Cooperative for the Development\nof the Congo (CODECO), in North Kivu and Ituri Provinces. The dire humanitarian situation,\nparticularly in the east of the country, has considerably increased the risk that displaced\nwomen and girls will experience insecurity, sexual exploitation and child marriage."},{"id":"a-hrc-60-83-p0020","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"20","seq":23,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts remains concerned about the security situation in\nIturi Province, where the Allied Democratic Forces continue to commit atrocities. Ituri\nremains the epicentre of the conflict between CODECO and the armed group Front populaire\nd’autodéfense en Ituri (FPAC), affecting the Lendu and Hema communities."},{"id":"a-hrc-60-83-p0021","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"21","seq":24,"section":"IV. Current security and humanitarian situation in the","text":"The team of international experts is also concerned about the creation of the armed\ngroup, Convention pour la révolution populaire, by Thomas Lubanga, who has already been\nconvicted by the International Criminal Court.10"},{"id":"a-hrc-60-83-p0022","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"22","seq":25,"section":"V. Implementation of the mandate of the team of international","text":"The mandate of the team of international experts is to provide the Government with\nthe technical support necessary to combat impunity and implement a transitional justice\nprocess focused on the needs of victims, while taking into account the subregional impact of\nthe crises in the Democratic Republic of the Congo."},{"id":"a-hrc-60-83-p0023","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"23","seq":26,"section":"A. Fight against impunity","text":"With regard to the fight against impunity, the team of international experts continued\nto observe the administration of justice, including in emblematic legal cases, particularly\nthose opened in connection with the crisis linked to the Kamuina Nsapu militia.\n1.         Administration of justice"},{"id":"a-hrc-60-83-p0024","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"24","seq":27,"section":"A. Fight against impunity","text":"The team of international experts notes with satisfaction the Government’s efforts to\nimprove the administration of justice but is concerned about the impact of the crisis in the\neast of the country on the fight against impunity and the protection of victims, witnesses and\njudicial actors."},{"id":"a-hrc-60-83-p0025","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"25","seq":28,"section":"A. Fight against impunity","text":"The team of international experts notes that the occupation of Goma and Bukavu has\nled to the destruction of the main judicial and penitentiary facilities 11 and to the disappearance\nof almost all case files, including those concerning serious crimes, including conflict-related\nsexual violence."},{"id":"a-hrc-60-83-p0026","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"26","seq":29,"section":"A. Fight against impunity","text":"The team of international experts notes that, against this challenging backdrop,\nMONUSCO and the United Nations Joint Human Rights Office, with the support of\ninternational partners in Bukavu, have assisted the Government in digitizing the case files of\n10 persons convicted of international crimes and 10 alleged perpetrators of such crimes."},{"id":"a-hrc-60-83-p0027","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"27","seq":30,"section":"A. Fight against impunity","text":"The team of international experts is concerned about the wave of insecurity which,\nfollowing the mass escape of prisoners from the central prisons of Goma, Bukavu, Uvira,\nKabare and Kalemie between January and March 2025, has hit the justice sector in the east\nof the country, resulting in numerous deaths, sexual violence and the flight of almost 200 war\ncriminals."},{"id":"a-hrc-60-83-p0028","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"28","seq":31,"section":"A. Fight against impunity","text":"The team of international experts remains concerned about the security situation in\nprisons and the living and working conditions of prison staff. It reiterates its recommendation\nthat prison facilities should be made more secure and that prison staff should be better trained\nand remunerated."},{"id":"a-hrc-60-83-p0029","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"29","seq":32,"section":"A. Fight against impunity","text":"Recent events in the east of the country have worsened the insecurity faced by judicial\nactors and led to an increase in impunity, seriously undermining the rule of law. The\nUnited Nations Joint Human Rights Office has received many requests for protection from\njudicial actors, victims, witnesses and human rights defenders who have been threatened with\nreprisals by former prisoners implicated in serious crimes or by members of armed groups.\nThe establishment, by AFC/M23, of a conflict arbitration court 12 replacing the State\nauthorities constitutes a serious infringement of the State’s sovereignty.\n11 In North Kivu Province, the courthouse in Goma was pillaged and ransacked and remains out of\noperation. Munzenze Central Prison was set on fire, causing the death of 141 women prisoners and 28\nyoung children. All the remaining prisoners escaped, including those charged with or convicted of\nwar crimes or crimes against humanity. However, it should be noted that a few days before the\ncoalition entered Goma, the prison authorities had transferred to Kinshasa certain prisoners who were\ndangerous or had been involved in serious crimes. In South Kivu Province, Bukavu Court of Appeal\nwas pillaged, its archives were destroyed and the offices of members of the judiciary were ransacked.\nSeveral district courts, in Uvira, Kalehe and Fizi, have ceased to operate on account of the continued\ninsecurity.\n12 https://kivumorningpost.com/2025/05/30/goma-lafc-m23-ouvre-un-tribunal-darbitrage-pour-les-\ndossiers-judiciaires-en-suspens/."},{"id":"a-hrc-60-83-p0030","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"30","seq":33,"section":"A. Fight against impunity","text":"The team of international experts invites the Government to improve protection\nmeasures for members of the judiciary and other persons affected by the crisis and invites the\nSecurity Council to strengthen the mandate of MONUSCO in order to increase its capacity\nto support the Government in its efforts to secure national territory and restore the rule of\nlaw."},{"id":"a-hrc-60-83-p0031","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"31","seq":34,"section":"A. Fight against impunity","text":"The team of international experts is concerned about the increase in the number of\nwomen and children being trafficked, including for the purposes of forced labour and sexual\nexploitation, due to the security situation in the east of the country. It calls on the Government\nto step up the fight against trafficking in women and children and to provide comprehensive\nsupport for victims."},{"id":"a-hrc-60-83-p0032","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"32","seq":35,"section":"A. Fight against impunity","text":"The team of international experts notes that a national conference on justice on the\ntheme “Why is the Congolese justice system in such a poor state?” was held from 6 to\n16 November 2024. The event was attended by over 3,500 representatives of the justice\nsector, political, administrative and traditional authorities, the student population and\ninternational partners."},{"id":"a-hrc-60-83-p0033","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"33","seq":36,"section":"A. Fight against impunity","text":"The team of international experts encourages the Government to take into account the\nwork and discussions arising from the national conference on justice when drawing up the\nnew national justice reform policy for the period 2026–2035 and to adopt a holistic approach\nto transitional justice based on the needs of victims in order to ensure complementarity\nbetween the national justice reform policy and the national transitional justice policy."},{"id":"a-hrc-60-83-p0034","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"34","seq":37,"section":"A. Fight against impunity","text":"The team of international experts commends the Government on the two bills, the\ndraft decree and the draft order presented at the forty-fourth meeting of the Council of\nMinisters on 23 May 202513 in the context of the implementation of transitional justice, in\nparticular the bill amending and supplementing the Organic Act on the organization,\nfunctioning and powers of the ordinary courts and the bill on the fundamental principles of\ntransitional justice."},{"id":"a-hrc-60-83-p0035","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"35","seq":38,"section":"A. Fight against impunity","text":"The team of international experts is pleased to note that its recommendation\nconcerning greater involvement of the civil courts in dealing with international crimes has\nbeen taken into consideration, with the possibility of adding military judges to the\ncomposition of the Court of Cassation and the courts of appeal and the proposed creation of\nspecial units to investigate crimes against the peace and security of humanity. The team of\ninternational experts strongly encourages the Government to adopt these two bills in order to\nbe able to implement these measures."},{"id":"a-hrc-60-83-p0036","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"36","seq":39,"section":"A. Fight against impunity","text":"The team of international experts notes the appointment on 1 April 2025, by\npresidential order, of 2,500 members of the national legal service, the second cohort to be\nappointed from among the 5,000 persons recruited in November 2022. It encourages the\nSupreme Council of Justice to begin their initial training, with the support of international\npartners."},{"id":"a-hrc-60-83-p0037","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"37","seq":40,"section":"A. Fight against impunity","text":"The team of international experts deplores the consequences of the mass escape in\nSeptember 2024 of nearly 1,300 inmates, including dangerous criminals, from Kinshasa\nPenitentiary and Re-education Centre (Makala Prison), which resulted in the deaths of\n131 inmates, including 3 women, and during which hundreds of people were injured and at\nleast 269 women were raped."},{"id":"a-hrc-60-83-p0038","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"38","seq":41,"section":"A. Fight against impunity","text":"The team of international experts calls on the Government to take protective measures\nwith a view to establishing the facts, identifying those responsible, providing reparation to\nvictims and strengthening the technical and operational capacities of prison staff."},{"id":"a-hrc-60-83-p0039","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"39","seq":42,"section":"A. Fight against impunity","text":"The team of international experts appreciates the rehabilitation efforts that have been\nmade, including the renovation of Kinshasa Penitentiary and Re-education Centre, and the\nlaunch of projects to improve prison food and to facilitate the reintegration of prisoners. Work\nis also under way to improve the conditions of detention in Luzumu Prison in Kongo Central\nProvince."},{"id":"a-hrc-60-83-p0040","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"40","seq":43,"section":"A. Fight against impunity","text":"The team of international experts is concerned about the impact of the mpox epidemic,\nparticularly in prison environments on account of the crowded living conditions. It\nencourages the Government to continue its rehabilitation efforts and to take measures to\nrelieve prison overcrowding in order to improve conditions of detention.\n2.    Handling of emblematic legal cases"},{"id":"a-hrc-60-83-p0041","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"41","seq":44,"section":"A. Fight against impunity","text":"The team of international experts remains concerned about the lack of progress in the\ncases concerning the crisis linked to the Kamuina Nsapu militia. It notes, however, that the\ncase of the murder of the two United Nations experts, Zaida Catalán and Michael Sharp,\nremains under appeal before the High Military Court in Kinshasa, while the case of the\nmurder of the four Congolese persons who were accompanying them has been at a standstill\nsince 2017."},{"id":"a-hrc-60-83-p0042","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"42","seq":45,"section":"A. Fight against impunity","text":"Only 2 out of 22 emblematic cases have reached the trial stage, namely, the case of\nthe murder of the two United Nations experts and the Mulombodi case."},{"id":"a-hrc-60-83-p0043","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"43","seq":46,"section":"A. Fight against impunity","text":"The team of international experts is concerned about the suspension, as of late May\n2024, following the death of one of the two defendants, of the first trial based on command\nresponsibility in the Democratic Republic of the Congo, involving a general of the Congolese\nNational Police and a general of the Armed Forces of the Democratic Republic of the Congo."},{"id":"a-hrc-60-83-p0044","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"44","seq":47,"section":"A. Fight against impunity","text":"The team of international experts deplores the lack of progress in the Bana Mura case,\nwhich has been referred to the High Military Court with jurisdiction over two of the\ndefendants, namely, a deputy chief superintendent of the Congolese National Police and a\nsenator and former vice-governor of Kasai."},{"id":"a-hrc-60-83-p0045","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"45","seq":48,"section":"A. Fight against impunity","text":"The team of international experts invites the judicial authorities to take the necessary\nsteps to complete these legal proceedings in order to establish the truth, assign responsibility\nfor the offences committed in Kasai and realize the victims’ right to justice and reparation."},{"id":"a-hrc-60-83-p0046","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"46","seq":49,"section":"A. Fight against impunity","text":"The team of international experts encourages the Government to continue, with the\nsupport of its partners, building the capacity of professionals in the criminal justice system\nto investigate and prosecute international crimes, in order to speed up and strengthen the\njudicial response."},{"id":"a-hrc-60-83-p0047","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"47","seq":50,"section":"A. Fight against impunity","text":"The team of international experts has taken note of the conviction, in Ituri Province,\nof Jean Deus Django Dyogo, a political and administrative authority of the State at the time\nof the events and a member of the Coopérative pour le développement du Congo armed\ngroup, and in South Kivu Province, of Donat Kwenga Omari, a former warlord, including, in\nthe latter case, the award of substantial compensation to the 399 victims who had sued for\ndamages in the proceedings."},{"id":"a-hrc-60-83-p0048","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"48","seq":51,"section":"A. Fight against impunity","text":"The team of international experts also takes note of the conviction of 425 people, since\nOctober 2024, for crimes involving violations of human rights and international humanitarian\nlaw: 149 officers of the Armed Forces of the Democratic Republic of the Congo, 21 officers\nof the Congolese National Police, 25 members of armed groups and 230 civilians."},{"id":"a-hrc-60-83-p0049","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"49","seq":52,"section":"A. Fight against impunity","text":"The team of international experts commends the Government and its partners on the\nefforts made to update provincial strategies for prioritizing the prosecution of serious crimes,\nwithin the framework of the United Nations joint programme to support justice reform in the\nDemocratic Republic of the Congo. This work, which was carried out recently in the\nProvinces of Ituri, North Kivu, South Kivu, Kasai and Kasai Central, has brought the number\nof priority case files to 88."},{"id":"a-hrc-60-83-p0050","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"50","seq":53,"section":"A. Fight against impunity","text":"The team of international experts encourages the Government to adopt a national\nstrategy on the prioritization of prosecutions that would ensure consistency and\nharmonization at the highest level and strengthen judicial independence."},{"id":"a-hrc-60-83-p0051","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"51","seq":54,"section":"A. Fight against impunity","text":"The team of international experts appreciates the significant contribution of the\ntechnical assistance team deployed to the United Nations Joint Human Rights Office to\nsupport the judicial authorities in the fight against impunity through the sharing of expertise\nin forensic medicine and forensic psychology."},{"id":"a-hrc-60-83-p0052","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"52","seq":55,"section":"A. Fight against impunity","text":"The team of international experts welcomes the forensic examinations carried out in\nthe village of Diboko, in Kasai Province, where the United Nations Joint Human Rights\nOffice forensic team, at the request of the military courts, documented the remains of 115\nvictims who had been discovered in secret mass graves."},{"id":"a-hrc-60-83-p0053","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"53","seq":56,"section":"A. Fight against impunity","text":"The team of international experts also welcomes the forensic anthropological\nexamination of the remains of 29 police officers who had disappeared in Malenga, which has\nprovided crucial insight into the crisis linked to the Kamuina Nsapu militia and has allowed\ntheir families and communities to move through the mourning process and the judicial\nauthorities to initiate proceedings."},{"id":"a-hrc-60-83-p0054","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"54","seq":57,"section":"A. Fight against impunity","text":"The team of international experts welcomes the official handover of a full\npostgraduate and residency programme in forensic medicine to the Minister of Higher and\nUniversity Education on 14 May 2025. This handover of programmes supported by the\nUnited Nations Joint Human Rights Office forensic team is in line with one of the\nrecommendations made in its previous report."},{"id":"a-hrc-60-83-p0055","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"55","seq":58,"section":"A. Fight against impunity","text":"The team of international experts notes that, in June 2025, the forensic team helped\nthe Lubumbashi judicial authorities to assess the injuries of seven victims who had been\nexposed to toxic substances released by an ore processing plant and to carry out an\naccountability analysis."},{"id":"a-hrc-60-83-p0056","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"56","seq":59,"section":"A. Fight against impunity","text":"The team of international experts invites international partners to support the\nGovernment’s efforts in this area with a view to strengthening the fight against impunity and\nensuring better access to justice for victims.\n3.     Situation of victims"},{"id":"a-hrc-60-83-p0057","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"57","seq":60,"section":"A. Fight against impunity","text":"The team of international experts notes that the crisis in the east of the country has led\nto the collapse of protection mechanisms and has disrupted the provision of psychological\nsupport and care."},{"id":"a-hrc-60-83-p0058","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"58","seq":61,"section":"A. Fight against impunity","text":"The team of international experts has been informed that, given the scale of the crisis\nin the east of the country, a partnership agreement has been signed between the\nUnited Nations system and the National Reparations Fund for Victims of Conflict-Related\nSexual Violence and Other Crimes against the Peace and Security of Humanity in the\nDemocratic Republic of the Congo, with a view to ensuring that victims of violence linked\nto the armed conflict in the Provinces of North Kivu and South Kivu have access to justice\nand urgent provisional reparation."},{"id":"a-hrc-60-83-p0059","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"59","seq":62,"section":"A. Fight against impunity","text":"The team of international experts notes with satisfaction that Act No. 22/065 of\n26 December 2022, on the fundamental principles of protection and redress for victims of\nconflict-related sexual violence and victims of crimes against the peace and security of\nhumanity, has enabled some 1,500 victims to benefit from the abolition of registration and\nlegal fees."},{"id":"a-hrc-60-83-p0060","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"60","seq":63,"section":"A. Fight against impunity","text":"The team of international experts is pleased that the United Nations Joint Human\nRights Office has supported 836 victims of international crimes. It urges the Government to\nsystematize the provision of legal, judicial and psycholegal support to victims of serious\ncrimes."},{"id":"a-hrc-60-83-p0061","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"61","seq":64,"section":"A. Fight against impunity","text":"The team of international experts welcomes the steps taken to build the capacities of\nseven national actors to conduct psychological assessments tailored to mass crimes and to\ndraft expert reports with a focus on the trans- and intergenerational dimensions of the\nphysical, emotional, psychological and social repercussions of the acts committed."},{"id":"a-hrc-60-83-p0062","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"62","seq":65,"section":"A. Fight against impunity","text":"The team of international experts encourages the actors concerned to promote the\ntransfer of skills and the development of national psychological expertise in order to provide\nthe country with the human resources needed to carry out psychological assessments of\nvictims and witnesses during legal proceedings. The team of international experts invites the\nGovernment to broaden the legal basis on which assessments of this kind may be ordered by\nthe judicial authorities."},{"id":"a-hrc-60-83-p0063","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"63","seq":66,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes some interesting advances in transitional\njustice at the provincial and national levels, as well as encouraging initiatives at the regional\nlevel.\n1.         Monitoring of the implementation of the transitional justice process in Kasai Central\nProvince"},{"id":"a-hrc-60-83-p0064","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"64","seq":67,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the continuous support that has been\nprovided to the provincial Truth, Justice and Reconciliation Commission since the launch of\nthe operational phase of its activities. It welcomes the development and approval of\ndocuments and tools relating to the truth-seeking process in preparation for the phase that\nwill involve taking statements from victims and witnesses."},{"id":"a-hrc-60-83-p0065","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"65","seq":68,"section":"B. Implementation of the transitional justice process","text":"The team of international experts recalls that this phase is crucial to establishing the\ntruth and requires the implementation of a protection strategy to ensure the security of\nvictims, witnesses, Commission buildings and personnel, and data."},{"id":"a-hrc-60-83-p0066","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"66","seq":69,"section":"B. Implementation of the transitional justice process","text":"The team of international experts appreciates the support provided to the provincial\nTruth, Justice and Reconciliation Commission through collaboration with the European\nUnion, the United Nations Entity for Gender Equality and the Empowerment of Women\n(UN-Women) and TRIAL International. It also welcomes the support provided by the\nPeacebuilding Fund for the project to promote transitional justice for peacebuilding in the\nKasai and Kasai Central Provinces. It strongly encourages other partners to support the\nCommission."},{"id":"a-hrc-60-83-p0067","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"67","seq":70,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the strategic consultations between the\nNational Reparations Fund for Victims of Conflict-Related Sexual Violence and Other\nCrimes against the Peace and Security of Humanity in the Democratic Republic of the Congo\nand the provincial Truth, Justice and Reconciliation Commission, facilitated by the\nUnited Nations Joint Human Rights Office, which have enabled the two organizations to\ndiscuss their respective mandates and to identify opportunities for collaboration in the\nimplementation of two important pillars of transitional justice, namely truth-seeking and\nreparation for the victims of the crisis linked to the Kamuina Nsapu militia in Kasai Central\nProvince. The team of international experts welcomes this initiative, which is in line with one\nof its recommendations, and calls for this collaboration to be formalized."},{"id":"a-hrc-60-83-p0068","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"68","seq":71,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that there has been a lack of communication\nconcerning the activities of the provincial Truth, Justice and Reconciliation Commission. It\ndeplores the insufficient funding of the Commission by the provincial and national\nauthorities."},{"id":"a-hrc-60-83-p0069","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"69","seq":72,"section":"B. Implementation of the transitional justice process","text":"The team of international experts reiterates its recommendation to the government of\nKasai Central Province to give concrete expression to its support for the provincial Truth,\nJustice and Reconciliation Commission and invites the Ministry of Human Rights to include\nthe Commission in its budget.\n2.         Monitoring of the implementation of the transitional justice process at the national\nlevel"},{"id":"a-hrc-60-83-p0070","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"70","seq":73,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the Head of State’s ongoing commitment\nto transitional justice and the progress made by the Government at the national level."},{"id":"a-hrc-60-83-p0071","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"71","seq":74,"section":"B. Implementation of the transitional justice process","text":"The team of international experts particularly commends the Government on the\nadoption by the Council of Ministers of a set of legal texts, including the draft national\ntransitional justice policy.14 This policy sets out a new, context-specific approach that takes\n14   The texts in question, which were introduced at the forty-fourth meeting of the Council of Ministers\non 23 May 2025, are as follows: the bill amending and supplementing Organic Act No. 13/011-B of\n11 April 2013 on the organization, functioning and powers of the ordinary courts; the bill on the\nfundamental principles of transitional justice; the draft decree on the implementation of Act\ninto account the conflict and post-conflict situations that coexist in the country and advocates\na decentralized approach to transitional justice."},{"id":"a-hrc-60-83-p0072","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"72","seq":75,"section":"B. Implementation of the transitional justice process","text":"The team of international experts encourages the Parliament to adopt these legal texts\nand the Government to facilitate their implementation, taking into account the concerns of\nvictims in line with international standards."},{"id":"a-hrc-60-83-p0073","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"73","seq":76,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the approval of the strategy for\nimplementing the right to reparation, at the round table held by the National Reparations\nFund for Victims of Conflict-Related Sexual Violence and Other Crimes against the Peace\nand Security of Humanity in the Democratic Republic of the Congo from 1 to 3 July 2025,\nconstitutes a significant development."},{"id":"a-hrc-60-83-p0074","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"74","seq":77,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the persons in charge of the Disarmament,\nDemobilization, Community Recovery and Stabilization Programme do not wish to include\nformer combatants in the disarmament, demobilization and reintegration process without\nprior vetting and wish to ensure that human rights are taken into account in the process."},{"id":"a-hrc-60-83-p0075","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"75","seq":78,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the action taken, with the participation of\nthe United Nations Joint Human Rights Office, in response to the recommendation in which\nit called for closer collaboration between the Disarmament, Demobilization, Community\nRecovery and Stabilization Programme and other national mechanisms."},{"id":"a-hrc-60-83-p0076","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"76","seq":79,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the rapprochement between the\nUnited Nations Joint Human Rights Office and the Special Fund to Compensate Victims of\nIllicit Acts Carried Out by Uganda and recommends that priority should be given to collective\nreparation in Tshopo Province and that this collaboration should be strengthened in the fields\nof communication, data security, forensic medicine, site security and victim protection."},{"id":"a-hrc-60-83-p0077","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"77","seq":80,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the adoption of the national transitional\njustice policy and particularly appreciates the appointment, by the Ministry of Human Rights,\nof a coordinator and two deputies to lead its implementation."},{"id":"a-hrc-60-83-p0078","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"78","seq":81,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes the organization of two workshops on\ntransitional justice, involving national and international actors, by the Inter-Institutional\nCommission for Assistance to Victims and Support for Reforms. These workshops were an\nopportunity to review the activities carried out, gather recommendations from the actors\nconcerned and establish a permanent consultation framework."},{"id":"a-hrc-60-83-p0079","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"79","seq":82,"section":"B. Implementation of the transitional justice process","text":"The team of international experts encourages all initiatives to promote the\ncoordination of the State bodies involved in the transitional justice process and welcomes the\nholding, on 9 June 2025, of the first round table organized jointly by the United Nations Joint\nHuman Rights Office and the Ministry of Human Rights, with the participation of technical\nand financial partners and civil society, with a view to setting up a framework for\nconsultations between relevant actors in the field of transitional justice."},{"id":"a-hrc-60-83-p0080","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"80","seq":83,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the enthusiasm and willingness of civil\nsociety to become more involved in the transitional justice process. The team notes the\nconcern of civil society that it is not sufficiently involved and invites the Government to\nincrease its involvement."},{"id":"a-hrc-60-83-p0081","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"81","seq":84,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the Government wishes to set up a steering\ncommittee for the establishment of a special criminal court in the Democratic Republic of\nthe Congo."},{"id":"a-hrc-60-83-p0082","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"82","seq":85,"section":"B. Implementation of the transitional justice process","text":"The team of international experts deplores the slow progress made in setting up the\nhuman rights liaison body. It recalls the importance of this body for promoting and ensuring\nNo. 22/065 of 26 December 2022 on the fundamental principles of protection and redress for victims\nof conflict-related sexual violence and victims of crimes against the peace and security of humanity;\nand the draft ministerial order setting out the procedures for maintaining the single consolidated list of\nvictims of conflict-related sexual violence and victims of crimes against the peace and security of\nhumanity.\nrespect for human rights in the Democratic Republic of the Congo and invites the\nGovernment to work towards ensuring that it is fully operational."},{"id":"a-hrc-60-83-p0083","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"83","seq":86,"section":"B. Implementation of the transitional justice process","text":"The team of international experts is concerned about the disappearance of certain sites\nwhere mass crimes have been committed, throughout the Democratic Republic of the Congo,\nand points out that truth-seeking mechanisms will be severely impacted by the disappearance\nof evidence and that the protection of these sites is essential for memorialization."},{"id":"a-hrc-60-83-p0084","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"84","seq":87,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the efforts of the United Nations Joint\nHuman Rights Office to promote a human rights economy, realize the right to development\nand protect human rights in relation to the extractive industries. It notes with satisfaction the\norganization by the United Nations Joint Human Rights Office of training sessions on these\ntopics for relevant actors and welcomes the holding of the twentieth Mining Week by the\nGovernment.15 It calls on the Government and international partners to continue their efforts\nto support this sector.\n3.         Design and implementation of transitional justice at the regional level"},{"id":"a-hrc-60-83-p0085","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"85","seq":88,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the progress made through regional\npolitical processes."},{"id":"a-hrc-60-83-p0086","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"86","seq":89,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the appointment of Faure Gnassingbé,\nPresident of the Council of Togo, as Mediator of the African Union. He will be supported by\na panel of facilitators 16 in his efforts to resolve the ongoing conflict in the east of the\nDemocratic Republic of the Congo."},{"id":"a-hrc-60-83-p0087","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"87","seq":90,"section":"B. Implementation of the transitional justice process","text":"The team of international experts welcomes the peace agreement between the\nDemocratic Republic of the Congo and Rwanda that was signed on 27 June 2025 in\nWashington, D.C., under the auspices of the United States of America."},{"id":"a-hrc-60-83-p0088","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"88","seq":91,"section":"B. Implementation of the transitional justice process","text":"The team of international experts is pleased that this agreement builds on the progress\nmade through the Nairobi and Luanda processes and the mediation in Doha and hopes that it\nwill constitute a step towards peace, stability and sustainable development in the Great Lakes\nRegion."},{"id":"a-hrc-60-83-p0089","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"89","seq":92,"section":"B. Implementation of the transitional justice process","text":"The team of international experts regrets, however, that this agreement makes no\nreference to accountability or transitional justice, including the rights to truth, justice,\nreparation and guarantees of non-repetition, and that the other processes do not take these\nmatters into account either."},{"id":"a-hrc-60-83-p0090","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"90","seq":93,"section":"B. Implementation of the transitional justice process","text":"The team of international experts calls for transitional justice to be incorporated into\npeace negotiations, with emphasis on the participation of civil society and women’s\norganizations. It remains convinced that a regional approach to transitional justice is all the\nmore essential as the causes and consequences of regional crises are cross-cutting rather than\nexclusive to each State."},{"id":"a-hrc-60-83-p0091","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"91","seq":94,"section":"B. Implementation of the transitional justice process","text":"The team of international experts encourages the Governments of the subregion to\npromote the creation of mechanisms for intergenerational and community dialogue, with the\nsupport of the United Nations. The team also calls on them to build the capacities of civil\nsociety in the subregion to enable it to make a meaningful contribution to the various peace\nprocesses."},{"id":"a-hrc-60-83-p0092","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"92","seq":95,"section":"B. Implementation of the transitional justice process","text":"The team of international experts remains convinced that dialogue is the path to\nachieving peaceful coexistence, peace and stability in the subregion. It advocates for adopting\n15 Sessions for the provincial authorities, the security and defence forces, the National Human Rights\nCommission and civil society in Haut-Katanga and Lualaba Provinces, as well as a special session for\nstaff and managers of Tenke Fungurume Mining in Fungurume, Lualaba Province, on the right to\ndevelopment, the United Nations Guiding Principles on Business and Human Rights, corporate social\nresponsibility, social auditing and the Sustainable Development Goals.\n16 The panel of facilitators of the African mediation process for peace in the Democratic Republic of the\nCongo is composed of the following persons: Olusegun Obasanjo, former President of Nigeria; Uhuru\nKenyatta, former President of Kenya; Mokgweetsi Masisi, former President of Botswana; Catherine\nSamba-Panza, former President of the Central African Republic; and Sahle-Work Zewde, former\nPresident of Ethiopia.\nprinciples of cohabitation based on international law, respect for human rights and the\nstrengthening of the rule of law in the Great Lakes Region.\n4.        Challenges in the implementation of the transitional justice process in the Democratic\nRepublic of the Congo"},{"id":"a-hrc-60-83-p0093","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"93","seq":96,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes five major challenges in the implementation\nof the transitional justice process despite the progress made: (a) inclusive implementation of\nthe transitional justice policy, taking into account national consultations; (b) inadequate\ncoordination and harmonization of national transitional justice mechanisms; (c) the lack of\neffective communication and the need to foster ownership of the process at the provincial\nand national levels; (d) the financing of the process; and (e) the difficulty of implementing\ntransitional justice in the midst of a deepening crisis.\n(a)        Inclusive implementation of the transitional justice policy, taking into account national\nconsultations"},{"id":"a-hrc-60-83-p0094","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"94","seq":97,"section":"B. Implementation of the transitional justice process","text":"The team of international experts regrets that the Government was unable to complete\nnational consultations in all provinces prior to the adoption of the national transitional justice\npolicy and encourages it to continue these consultations in accordance with the established\nroad map and with the support of its technical and financial partners."},{"id":"a-hrc-60-83-p0095","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"95","seq":98,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the process of implementing a national\ntransitional justice policy must be inclusive and participatory if it is to be successful. The\nteam invites the Government to facilitate the participation of civil society and the main\nbeneficiaries, including victims.\n(b)        Inadequate coordination and harmonization of national transitional justice mechanisms"},{"id":"a-hrc-60-83-p0096","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"96","seq":99,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the various national bodies working in the\nfield of transitional justice were created to meet specific needs but operate in accordance with\na comprehensive approach based on the four pillars of transitional justice."},{"id":"a-hrc-60-83-p0097","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"97","seq":100,"section":"B. Implementation of the transitional justice process","text":"The team of international experts believes that the various strategies in the areas of\nreparation, truth-seeking, justice and guarantees of non-repetition pursued by the relevant\nmechanisms should be aligned with national policy to ensure that there is a shared vision and\nresources are used efficiently."},{"id":"a-hrc-60-83-p0098","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"98","seq":101,"section":"B. Implementation of the transitional justice process","text":"The team of international experts reaffirms that coordinating and harmonizing the\nwork of the national transitional justice mechanisms around a shared vision supported by the\ndraft national transitional justice policy will facilitate the implementation of the process and\nensure its effectiveness."},{"id":"a-hrc-60-83-p0099","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"99","seq":102,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes with satisfaction that a mechanism for the\ntechnical coordination and evaluation of the implementation of the various pillars of\ntransitional justice is provided for in the bill on the fundamental principles of transitional\njustice in the Democratic Republic of the Congo. This mechanism, which would be under the\nauthority of the President, should allow for greater synergy between the various transitional\njustice initiatives."},{"id":"a-hrc-60-83-p0100","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"100","seq":103,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the bill on the fundamental principles of\ntransitional justice in the Democratic Republic of the Congo17 provides for the establishment\nof a new national truth and reconciliation commission, which would be responsible for\ntruth-seeking and the promotion of reconciliation, peaceful cohabitation and a culture of\npeace, and whose operating procedures would be set out in a decree. The commission’s\nmandate would have both a national and a provincial component. The team of international\nexperts invites the Government to find ways of ensuring cooperation between the national\nmechanism and the provincial mechanisms.\n17   See article 10 of the bill on the fundamental principles of transitional justice in the Democratic\nRepublic of the Congo: “A national truth, justice, peace and reconciliation commission shall be\nestablished.”\n(c)   The lack of effective communication and the need to foster ownership of the process at the\nprovincial and national levels"},{"id":"a-hrc-60-83-p0101","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"101","seq":104,"section":"B. Implementation of the transitional justice process","text":"The team of international experts continues to deplore the inadequate communication\nabout the transitional justice process at the provincial and national levels."},{"id":"a-hrc-60-83-p0102","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"102","seq":105,"section":"B. Implementation of the transitional justice process","text":"The team of international experts points out that the lack of communication about the\nprovincial and national transitional justice process has a direct impact on the ownership of\nthe process by the populations who are supposed to benefit directly from it, and invites the\nGovernment to disseminate the national transitional justice policy to enable those populations\nto take ownership of it."},{"id":"a-hrc-60-83-p0103","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"103","seq":106,"section":"B. Implementation of the transitional justice process","text":"The team of international experts reaffirms the need for greater involvement of civil\nsociety, including organizations that defend the rights of vulnerable groups, especially\nwomen, children and Indigenous Peoples, to make the process more inclusive and to meet\npeople’s aspirations.\n(d)    The financing of the process"},{"id":"a-hrc-60-83-p0104","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"104","seq":107,"section":"B. Implementation of the transitional justice process","text":"The team of international experts appreciates the Government’s considerable efforts\nto financially support the National Reparations Fund for Victims of Conflict-Related Sexual\nViolence and Other Crimes against the Peace and Security of Humanity in the Democratic\nRepublic of the Congo. However, it would like this support to be extended to all transitional\njustice initiatives currently under way, including the Truth, Justice and Reconciliation\nCommission of Kasai Central Province. Financial support of this kind would promote\nnational ownership of the transitional justice process and encourage bilateral and multilateral\npartners to step up their participation."},{"id":"a-hrc-60-83-p0105","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"105","seq":108,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes the low level of mobilization of international\npartners for the financing of the transitional justice process. It deplores the fact that the\nworsening financial situation of the United Nations has considerably affected the support\nprovided by the Office of the United Nations High Commissioner for Human Rights\n(OHCHR), including the deployment of additional technical experts, and urges the Office to\nkeep in place those already deployed."},{"id":"a-hrc-60-83-p0106","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"106","seq":109,"section":"B. Implementation of the transitional justice process","text":"The team of international experts calls on the Government, OHCHR and international\npartners to better coordinate and strengthen their financial support for the transitional justice\nprocess and to explore other types of financial partnership.\n(e)   The difficulty of implementing transitional justice in the midst of a deepening crisis"},{"id":"a-hrc-60-83-p0107","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"107","seq":110,"section":"B. Implementation of the transitional justice process","text":"The team of international experts recognizes the difficulty of implementing a\ntransitional justice policy while some of the country’s provinces are occupied or affected by\nconflict."},{"id":"a-hrc-60-83-p0108","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"108","seq":111,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes with concern the persistence of regional\ntensions, particularly in the east of the country. It recalls that responding to security and\nhumanitarian challenges through a military approach alone cannot bring about lasting peace\nor meet the needs expressed by the populations affected."},{"id":"a-hrc-60-83-p0109","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"109","seq":112,"section":"B. Implementation of the transitional justice process","text":"The team of international experts notes that the Government needs to strengthen\ndialogue with all parties involved in the crisis in the east of the country, including\nneighbouring countries, and calls for commitments to be honoured and for all existing\nsubregional cooperation initiatives to be taken into consideration."},{"id":"a-hrc-60-83-p0110","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"110","seq":113,"section":"B. Implementation of the transitional justice process","text":"The team of international experts reaffirms the need to incorporate a human\nrights-based approach into these processes within the context of transitional justice in order\nto achieve lasting peace."},{"id":"a-hrc-60-83-p0111","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"111","seq":114,"section":"B. Implementation of the transitional justice process","text":"The team of international experts reiterates that it is important for the Government to\nspeed up the implementation of the Disarmament, Demobilization, Community Recovery\nand Stabilization Programme, in accordance with international standards, and to take into\naccount the regional dimension."},{"id":"a-hrc-60-83-p0112","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"112","seq":115,"section":"B. Implementation of the transitional justice process","text":"The team of international experts underscores the importance of strengthening\nregional judicial cooperation to intensify the fight against impunity for cross-border offences,\nincluding offences involving the illegal exploitation of natural resources. It welcomes the\nefforts of MONUSCO, OHCHR and the Office of the Special Envoy of the Secretary-General\nfor the Great Lakes Region to build the capacities of the Great Lakes Judicial Cooperation\nNetwork."},{"id":"a-hrc-60-83-p0113","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"113","seq":116,"section":"B. Implementation of the transitional justice process","text":"The team of international experts remains concerned about the ongoing withdrawal of\nMONUSCO at a time when several provinces in the east of the country are facing situations\nof armed conflict and intercommunity strife. The team of international experts calls on the\nGovernment and the Security Council to consider the major challenges in terms of access,\nsecurity and human rights protection that this withdrawal might cause if it is not offset by the\ndeployment of sufficient troops belonging to the armed forces and the national security forces\nwho have receiving training on the rules of international human rights law and international\nhumanitarian law and who abide by those rules."},{"id":"a-hrc-60-83-p0114","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"114","seq":117,"section":"A. Conclusions","text":"The team of international experts is grateful to the Congolese authorities for\nengaging in positive and fruitful cooperation throughout its mandate. It commends\nthem on their collaborative approach and their efforts to implement transitional justice\nand combat impunity."},{"id":"a-hrc-60-83-p0115","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"115","seq":118,"section":"A. Conclusions","text":"The team of international experts is also grateful to the entire United Nations\nsystem, including MONUSCO and the Office of the Special Envoy of the\nSecretary-General for the Great Lakes Region, and the diplomatic community for their\ncontinued support and appreciates the receptiveness of civil society and national and\ninternational non-governmental organizations working to combat impunity and\npromote transitional justice. It is also grateful to the panel of facilitators of the African\nmediation process for peace in the Democratic Republic of the Congo for giving it the\nopportunity to discuss its mandate and the possibility of incorporating transitional\njustice into subregional peace initiatives."},{"id":"a-hrc-60-83-p0116","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"116","seq":119,"section":"A. Conclusions","text":"The team of international experts welcomes the progress made on the legislative\nand regulatory fronts and the adoption of the national transitional justice policy and\nhopes that this policy will meet the expectations of the Congolese people in terms of\njustice, reconciliation and lasting peace. It also appreciates the efforts made to\ncoordinate, harmonize and finance national transitional justice mechanisms."},{"id":"a-hrc-60-83-p0117","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"117","seq":120,"section":"A. Conclusions","text":"The team of international experts remains deeply concerned about the impact of\nthe crisis in the east of the country on the fight against impunity and is worried about\nthe lack of progress in legal cases, particularly the emblematic cases opened in\nconnection with the crisis linked to the Kamuina Nsapu militia in Kasai Central\nProvince. It fears that these delays within the judicial system, combined with the\nchallenges faced by the provincial Truth, Justice and Reconciliation Commission, will\nhave an impact on progress towards reconciliation and lasting peace in the province."},{"id":"a-hrc-60-83-p0118","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"118","seq":121,"section":"A. Conclusions","text":"The team of international experts welcomes all the initiatives undertaken since\nthe signing of the Peace, Security and Cooperation Framework for the Democratic\nRepublic of the Congo and the Region in Addis Ababa on 24 February 2013 with a view\nto resolving conflicts and achieving lasting peace, particularly in the east of the country.\nIt notes, moreover, that the escalation of the crisis in the east of the country proves that\npeace in this part of the country remains very fragile and that solutions can be found\nonly through the genuine shared commitment of actors in the subregion. In this context,\nit stresses the need to develop a regional approach to transitional justice, starting by\nexplicitly incorporating this theme into the regional peace processes of Addis Ababa,\nLuanda, Nairobi, Doha and Washington, D.C."},{"id":"a-hrc-60-83-p0119","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"119","seq":122,"section":"A. Conclusions","text":"The team of international experts draws the attention of the Congolese\nauthorities to the need to strengthen the judicial response to serious violations of human\nrights and international humanitarian law, with a focus on building the technical and\noperational capacities of judicial actors and developing national expertise in forensic\nmedicine and the provision of psychological support."},{"id":"a-hrc-60-83-p0120","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"120","seq":123,"section":"A. Conclusions","text":"The team of international experts calls on the Government once again to step up\nits coordination and its support, including financial support, for the national\ntransitional justice process, taking into account the history, circumstances and needs of\nthe affected populations, in order to ensure the coherence, participatory nature and\neffectiveness of the process and thus promote peace, reconciliation and development."},{"id":"a-hrc-60-83-p0121","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"121","seq":124,"section":"A. Conclusions","text":"The team of international experts calls for synergy between technical and\nfinancial partners. In view of the immense challenges facing the country, it also calls for\nan increase in the resources allocated to the United Nations Joint Human Rights Office\nto enable it to effectively support the fight against impunity and the transitional justice\nprocess that is under way and it stands ready to support the authorities in their search\nfor ways to achieve lasting peace."},{"id":"a-hrc-60-83-p0122","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"122","seq":125,"section":"B. Recommendations","text":"The team of international experts recalls that it is necessary to continue\nimplementing the recommendations made in its previous reports. It reiterates some of\nits recommendations and makes some new ones.\n1.    Prevention of impunity"},{"id":"a-hrc-60-83-p0123","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"123","seq":126,"section":"B. Recommendations","text":"In view of the current impact of the crisis in the east of the country on the fight\nagainst impunity, the team of international experts urges the Government to take\nmeasures to preserve case files and to secure judicial and penitentiary facilities,\nincluding by digitizing files and ensuring the protection of victims, witnesses, human\nrights defenders and all those working in the criminal justice system. It invites\ninternational partners to support the Government in taking these measures."},{"id":"a-hrc-60-83-p0124","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"124","seq":127,"section":"B. Recommendations","text":"The team of international experts recommends that the Human Rights Council\nbuild the capacities of the technical assistance team by maintaining and increasing its\nhuman and financial resources in order to avoid undermining efforts to combat\nimpunity. It recommends that the Government establish forensic medicine programmes\nat Congolese universities."},{"id":"a-hrc-60-83-p0125","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"125","seq":128,"section":"B. Recommendations","text":"The team of international experts reiterates its call for the Government and the\nSupreme Council of Justice to continue their efforts to provide adequate initial and\nin-service training for members of the national legal service."},{"id":"a-hrc-60-83-p0126","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"126","seq":129,"section":"B. Recommendations","text":"The team of international experts encourages the Government to continue\nbuilding the capacity of all those working in the criminal justice system to investigate\nand prosecute international crimes, and to increase the involvement of the civil courts.\nIt invites all international partners to support these efforts with a view to improving\ncriminal investigations, strengthening the fight against impunity and ensuring better\naccess to justice for victims."},{"id":"a-hrc-60-83-p0127","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"127","seq":130,"section":"B. Recommendations","text":"The team of international experts invites the judicial authorities to take all the\nnecessary steps to complete the relevant legal proceedings in order to establish the truth,\nassign responsibility for the offences committed in Kasai and realize the victims’ right\nto justice and reparation."},{"id":"a-hrc-60-83-p0128","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"128","seq":131,"section":"B. Recommendations","text":"The team of international experts encourages the Government to give further\nthought to setting up a special court or mixed chambers, taking into account the\nsubregional dimension of the crisis, and to continue engaging in regional judicial\ncooperation."},{"id":"a-hrc-60-83-p0129","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"129","seq":132,"section":"B. Recommendations","text":"The team of international experts remains concerned about the lifting of the\nmoratorium on the death penalty and calls on the Government to reconsider its\ndecision.\n2.     Vision and coordination of transitional justice initiatives"},{"id":"a-hrc-60-83-p0130","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"130","seq":133,"section":"B. Recommendations","text":"The team of international experts invites the United Nations Joint Human Rights\nOffice to help the authorities, international partners and stakeholders to organize\nthemselves in order to better coordinate and finance the implementation of the\ntransitional justice strategy and to enable the population to take ownership of the\nstrategy."},{"id":"a-hrc-60-83-p0131","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"131","seq":134,"section":"B. Recommendations","text":"The team of international experts encourages the Government to coordinate the\nvarious strategies relating to reparation, truth-seeking, justice and guarantees of\nnon-repetition around a shared vision in order to promote the implementation of the\nnational transitional justice policy and the efficient use of resources."},{"id":"a-hrc-60-83-p0132","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"132","seq":135,"section":"B. Recommendations","text":"The team of international experts calls on the national and international actors\ninvolved in the transitional justice process to act in synergy and coordinate their\nresources and recommends that the National Reparations Fund for Victims of\nConflict-Related Sexual Violence and Other Crimes against the Peace and Security of\nHumanity in the Democratic Republic of the Congo and the provincial Truth, Justice\nand Reconciliation Commission formalize their collaboration with a view to better\naligning their approaches and ensuring the complementarity of their actions in Kasai\nCentral Province."},{"id":"a-hrc-60-83-p0133","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"133","seq":136,"section":"B. Recommendations","text":"The team of international experts encourages international partners supporting\nthe transitional justice process to strengthen the coordination and complementarity of\ntheir actions at the national and provincial levels and to implement the consultation\nframework established at the round table of 9 June 2025."},{"id":"a-hrc-60-83-p0134","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"134","seq":137,"section":"B. Recommendations","text":"The team of international experts invites the Government to redouble its efforts\nto ensure that the human rights liaison body is fully operational.\n3.     Consideration of victims at all stages of the process"},{"id":"a-hrc-60-83-p0135","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"135","seq":138,"section":"B. Recommendations","text":"The team of international experts encourages the Parliament to adopt the legal\ninstruments on transitional justice presented at the forty-fourth meeting of the Council\nof Ministers on 23 May 2025."},{"id":"a-hrc-60-83-p0136","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"136","seq":139,"section":"B. Recommendations","text":"It encourages the Government to facilitate the implementation of these\ninstruments and to ensure the effective and secure participation of victims, civil society\nand religious and traditional authorities in the transitional justice process, including\nduring national consultations. It also encourages the Government to ensure data\nsecurity."},{"id":"a-hrc-60-83-p0137","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"137","seq":140,"section":"B. Recommendations","text":"The team of international experts reiterates its call for the judicial authorities to\nsystematically request medical and psychological assessments of victims of international\ncrimes involved in legal proceedings, including by broadening the legal basis for\nrequesting such assessments."},{"id":"a-hrc-60-83-p0138","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"138","seq":141,"section":"B. Recommendations","text":"The team of international experts encourages the relevant actors to promote the\ntransfer of skills and the development of national psychological expertise in order to\nprovide the country with the human resources needed to carry out psychological\nassessments of and provide psychotherapy to victims and witnesses.\n4.     Conflict prevention and guarantees of non-repetition"},{"id":"a-hrc-60-83-p0139","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"139","seq":142,"section":"B. Recommendations","text":"The team of international experts encourages the Disarmament, Demobilization,\nCommunity Recovery and Stabilization Programme to continue developing synergies\nbetween the Programme and ongoing transitional justice initiatives, specifically by\nprioritizing the development of screening mechanisms and adopting a consistent\ndemobilization strategy, including in the implementation of the agreement signed in\nWashington, D.C."},{"id":"a-hrc-60-83-p0140","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"140","seq":143,"section":"B. Recommendations","text":"The team of international experts calls on the Government and international\npartners to continue their efforts to support the promotion of a human rights economy,\nthe realization of the right to development and the protection of human rights in\nrelation to the extractive industries.\n5.    Public, private and international funding of the transitional justice process"},{"id":"a-hrc-60-83-p0141","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"141","seq":144,"section":"B. Recommendations","text":"The team of international experts once again urges the Government and the\nprovincial government of Kasai Central to provide the provincial Truth, Justice and\nReconciliation Commission with adequate financial, material and human resources to\nenable it to fully discharge its mandate."},{"id":"a-hrc-60-83-p0142","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"142","seq":145,"section":"B. Recommendations","text":"The team of international experts calls on the Government, OHCHR and\ninternational partners to better coordinate and strengthen their financial support for\nthe national transitional justice process and to explore other types of financial\npartnership.\n6.    Subregional dimension of the transitional justice process"},{"id":"a-hrc-60-83-p0143","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"143","seq":146,"section":"B. Recommendations","text":"The team of international experts calls for transitional justice to be incorporated\ninto peace negotiations and underscores the importance of the participation of civil\nsociety and women’s organizations."},{"id":"a-hrc-60-83-p0144","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"144","seq":147,"section":"B. Recommendations","text":"The team of international experts notes that the Government needs to strengthen\ndialogue with all parties involved in the crisis in the east of the country, including\nneighbouring countries, and calls for commitments to be honoured and for all existing\nsubregional cooperation initiatives to be taken into consideration."},{"id":"a-hrc-60-83-p0145","rec_id":"reczKpHBpllGVhs0C","symbol":"A/HRC/60/83","n":"145","seq":148,"section":"B. Recommendations","text":"The team of international experts encourages the Special Envoy of the\nSecretary-General for the Great Lakes Region and OHCHR to step up their\ncooperation in order to further support the Great Lakes Judicial Cooperation Network."}]});